def _check_plan_repo(tmp_path, purpose="harness"):
    import hashlib
    repo = tmp_path / "plan-repo"
    repo.mkdir()
    def git(*args):
        return subprocess.check_output(["git", "-C", str(repo), *args], text=True).strip()
    git("init", "-q")
    git("config", "user.name", "Test")
    git("config", "user.email", "test@example.invalid")
    (repo / "selector.py").write_text("# selector\n")
    (repo / "control.sh").write_text("exit 0\n")
    git("add", ".")
    git("commit", "-qm", "inputs")
    candidate = git("rev-parse", "HEAD")
    scope = {"paths": {p: hashlib.sha256((repo / p).read_bytes()).hexdigest()
                       for p in ("selector.py", "control.sh")}, "commands": ["sh control.sh"]}
    plan = {"purpose": purpose, **({"coverage": scope} if purpose == "harness" else
                                  {"candidates": {candidate: scope}})}
    (repo / "plan.json").write_text(json.dumps(plan))
    git("add", ".")
    git("commit", "-qm", "independent definition")
    definition = git("rev-parse", "HEAD")
    return repo, git, plan, definition, candidate


@pytest.mark.parametrize("case,expected", [("harness", 0), ("unknown", 65),
    ("missing", 66), ("mismatch", 65), ("selected", 42), ("dirty", 65), ("purpose", 65)])
def test_check_plan_separates_coverage_from_candidate_identity(tmp_path, case, expected):
    from ttp import checkplan
    purpose = "candidate" if case == "unknown" else "harness"
    repo, git, plan, definition, candidate = _check_plan_repo(tmp_path, purpose)
    if case == "harness":
        (repo / "notes.md").write_text("selector preparation\n")
        git("add", ".")
        git("commit", "-qm", "unlisted harness head")
        # A working copy of the definition cannot change the pinned commands.
        (repo / "plan.json").write_text('{}')
    if case in ("missing", "mismatch", "selected"):
        if case == "missing":
            (repo / "selector.py").unlink()
        elif case == "mismatch":
            (repo / "selector.py").write_text("# changed\n")
        else:
            (repo / "control.sh").write_text("exit 42\n")
            import hashlib
            plan["coverage"]["paths"]["control.sh"] = hashlib.sha256(b"exit 42\n").hexdigest()
            (repo / "plan.json").write_text(json.dumps(plan))
        git("add", "-A")
        git("commit", "-qm", "next harness change")
        if case == "selected":
            definition = git("rev-parse", "HEAD")
    if case == "dirty":
        (repo / "control.sh").write_text("exit 0 # uncommitted\n")
    assert checkplan.run(repo, definition, "plan.json", "candidate" if case == "purpose" else purpose) == expected
    if case == "unknown":
        git("checkout", "-q", candidate)
        assert checkplan.run(repo, definition, "plan.json", "candidate") == 0


def test_check_plan_nested_path_from_subdirectory(tmp_path):
    import hashlib
    from ttp import checkplan
    repo, git, plan, definition, candidate = _check_plan_repo(tmp_path)
    (repo / "dir").mkdir()
    (repo / "dir" / "file.py").write_text("# nested\n")
    plan["coverage"]["paths"]["dir/file.py"] = hashlib.sha256(b"# nested\n").hexdigest()
    plan["coverage"]["commands"] = ["test -f dir/file.py"]
    (repo / "plan.json").write_text(json.dumps(plan))
    git("add", "-A")
    git("commit", "-qm", "nested input")
    definition = git("rev-parse", "HEAD")
    assert checkplan.run(repo / "dir", definition, "plan.json", "harness") == 0
    (repo / "dir" / "file.py").write_text("# changed\n")
    assert checkplan.run(repo / "dir", definition, "plan.json", "harness") == 65


def test_check_plan_git_failure_with_matching_output_still_fails(tmp_path, monkeypatch):
    from ttp import checkplan
    repo, git, plan, definition, candidate = _check_plan_repo(tmp_path)
    monkeypatch.setattr(checkplan, "_git", lambda *a: subprocess.CompletedProcess(a, 20, definition, "git failed"))
    assert checkplan.run(repo, definition, "plan.json", "harness") == 20


@pytest.mark.parametrize("case", ["empty_paths", "empty_commands", "outside_path", "glob_path",
    "bad_digest", "unknown_key", "symlink", "missing_definition", "bad_json", "mutable_ref"])
def test_check_plan_invalid_or_missing_coverage_never_passes(tmp_path, case):
    from ttp import checkplan
    repo, git, plan, definition, candidate = _check_plan_repo(tmp_path)
    scope = plan["coverage"]
    if case == "empty_paths":
        scope["paths"] = {}
    elif case == "empty_commands":
        scope["commands"] = []
    elif case == "outside_path":
        scope["paths"] = {"../selector.py": "0" * 64}
    elif case == "glob_path":
        scope["paths"] = {"*.py": "0" * 64}
    elif case == "bad_digest":
        scope["paths"]["selector.py"] = "bad"
    elif case == "unknown_key":
        scope["if_exists"] = "selector.py"
    elif case == "symlink":
        (repo / "selector.py").unlink()
        (repo / "selector.py").symlink_to("control.sh")
    elif case == "missing_definition":
        (repo / "plan.json").unlink()
    if case != "missing_definition":
        (repo / "plan.json").write_text("{" if case == "bad_json" else json.dumps(plan))
    (repo / "notes.md").write_text("control\n")
    git("add", "-A")
    git("commit", "-qm", "invalid definition or input")
    definition = "HEAD" if case == "mutable_ref" else git("rev-parse", "HEAD")
    assert checkplan.run(repo, definition, "plan.json", "harness") == 66


def test_check_plan_absent_definition_commit_names_commit_and_repo(tmp_path):
    repo, git, plan, definition, candidate = _check_plan_repo(tmp_path)
    absent = "b" * 40
    env = {**{k: v for k, v in os.environ.items() if k != "TTP_PROJECT"}, "PYTHONPATH": str(RUNTIME)}
    result = subprocess.run([sys.executable, "-m", "ttp", "check-plan", "--purpose", "harness",
                             "--definition-commit", absent, "--definition-path", "checks/harness-plan.json"],
                            cwd=repo, env=env, capture_output=True, text=True)
    assert result.returncode == 66
    assert f"definition commit {absent} is not in repository {repo.resolve()}" in result.stderr
    assert "Needed a single revision" not in result.stderr


def test_check_plan_outside_the_harness_repo_says_where_it_runs(tmp_path, monkeypatch, capsys):
    """Started in another repo's worktree or in a folder that is no git repo, check-plan fails with
    an input error that names the problem (never git's raw error) and points to the project's own
    repo when that one has the definition commit."""
    from ttp import checkplan
    repo, git, plan, definition, candidate = _check_plan_repo(tmp_path)
    other = tmp_path / "other"
    other.mkdir()
    subprocess.run(["git", "init", "-q", str(other)], check=True)
    subprocess.run(["git", "-C", str(other), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q",
                    "--allow-empty", "-m", "init"], check=True)
    plain = tmp_path / "plain"
    plain.mkdir()
    monkeypatch.setenv("GIT_CEILING_DIRECTORIES", str(tmp_path))
    monkeypatch.delenv("TTP_PROJECT", raising=False)
    for where, said in ((other, f"definition commit {definition} is not in repository"),
                        (plain, f"{plain} is not in a git repository")):
        assert checkplan.run(where, definition, "plan.json", "harness") == checkplan.INPUT_ERROR
        err = capsys.readouterr().err
        assert said in err and "git failed" not in err and "it is in" not in err, err
        monkeypatch.setenv("TTP_PROJECT", str(repo / "tt-project"))
        assert checkplan.run(where, definition, "plan.json", "harness") == checkplan.INPUT_ERROR
        assert f"it is in {repo.resolve()}" in capsys.readouterr().err
        monkeypatch.delenv("TTP_PROJECT")


def test_check_plan_keeps_all_required_commands_and_first_failure(tmp_path):
    from ttp import checkplan
    repo, git, plan, definition, candidate = _check_plan_repo(tmp_path)
    plan["coverage"]["commands"] = ["sh control.sh", "exit 42", "touch skipped"]
    (repo / "plan.json").write_text(json.dumps(plan))
    git("add", ".")
    git("commit", "-qm", "mandatory commands")
    assert checkplan.run(repo, git("rev-parse", "HEAD"), "plan.json", "harness") == 42
    assert not (repo / "skipped").exists()


def test_check_plan_cli_preserves_identity_exit(tmp_path, monkeypatch):
    from ttp import cli
    repo, git, plan, definition, candidate = _check_plan_repo(tmp_path, "candidate")
    monkeypatch.chdir(repo)
    with pytest.raises(SystemExit) as e:
        cli.main(["check-plan", "--definition-commit", definition,
                  "--definition-path", "plan.json", "--purpose", "candidate"])
    assert e.value.code == 65


def test_check_plan_at_head_takes_a_covered_change_and_its_digests_in_one_commit(tmp_path, monkeypatch, capsys):
    import hashlib
    from ttp import checkplan, cli
    repo, git, plan, definition, candidate = _check_plan_repo(tmp_path)
    # One commit changes a covered input and refreshes its digest. The pinned definition needs a
    # second commit to move the pin ("uncovered committed input"); a definition read at HEAD does not.
    (repo / "control.sh").write_text("exit 0 # v2\n")
    plan["coverage"]["paths"]["control.sh"] = hashlib.sha256(b"exit 0 # v2\n").hexdigest()
    (repo / "plan.json").write_text(json.dumps(plan))
    git("add", "-A")
    git("commit", "-qm", "harness change with its digests")
    capsys.readouterr()
    assert checkplan.run(repo, definition, "plan.json", "harness") == 65
    assert "uncovered committed input: control.sh" in capsys.readouterr().err
    assert checkplan.run(repo, None, "plan.json", "harness") == 0
    # A working copy of the definition still cannot change the commands: HEAD's commit is read.
    (repo / "plan.json").write_text(json.dumps({**plan, "coverage": {**plan["coverage"], "commands": ["exit 9"]}}))
    assert checkplan.run(repo, None, "plan.json", "harness") == 0
    git("checkout", "-q", "plan.json")
    # A covered change whose digest was not refreshed is still uncovered; the error names the new digest.
    (repo / "control.sh").write_text("exit 0 # v3\n")
    git("commit", "-qam", "digest not refreshed")
    capsys.readouterr()
    assert checkplan.run(repo, None, "plan.json", "harness") == 65
    assert hashlib.sha256(b"exit 0 # v3\n").hexdigest() in capsys.readouterr().err
    # Candidate identities are never read from the head they would admit.
    assert checkplan.run(repo, None, "plan.json", "candidate") == 66
    monkeypatch.chdir(repo)
    with pytest.raises(SystemExit) as e:
        cli.main(["check-plan", "--definition-at-head", "--definition-path", "plan.json", "--purpose", "harness"])
    assert e.value.code == 65
    with pytest.raises(SystemExit) as e:   # one definition source, never both
        cli.main(["check-plan", "--definition-at-head", "--definition-commit", definition,
                  "--definition-path", "plan.json", "--purpose", "harness"])
    assert e.value.code == 2


def test_check_plan_covers_a_committed_watcher_input_in_one_step(tmp_path, capsys):
    """A watcher's JSON (box-watch.json) committed with the definition that binds it to "committed"
    passes at once, and a later change to it passes under the same pinned definition commit."""
    import hashlib
    from ttp import checkplan
    repo, git, plan, definition, candidate = _check_plan_repo(tmp_path)
    (repo / "box-watch.json").write_text('{"boxes": []}\n')
    plan["coverage"]["paths"]["box-watch.json"] = "committed"
    plan["coverage"]["commands"].append("python3 -m json.tool box-watch.json")
    (repo / "plan.json").write_text(json.dumps(plan))
    git("add", "-A")
    git("commit", "-qm", "watcher input and its definition, one commit")
    pinned = git("rev-parse", "HEAD")
    assert checkplan.run(repo, pinned, "plan.json", "harness") == 0
    assert checkplan.run(repo, None, "plan.json", "harness") == 0
    # The watcher input changes again: no digest to refresh and no pin to move.
    (repo / "box-watch.json").write_text('{"boxes": ["a"]}\n')
    git("commit", "-qam", "watcher input only")
    assert checkplan.run(repo, pinned, "plan.json", "harness") == 0
    assert checkplan.run(repo, None, "plan.json", "harness") == 0
    # Still bound: the committed file must parse, match the working copy and exist.
    (repo / "box-watch.json").write_text("{\n")
    git("commit", "-qam", "broken watcher input")
    assert checkplan.run(repo, pinned, "plan.json", "harness") != 0
    git("revert", "--no-edit", "HEAD")
    (repo / "box-watch.json").write_text('{"boxes": ["b"]}\n')
    assert checkplan.run(repo, pinned, "plan.json", "harness") == 65   # uncommitted edit
    git("checkout", "-q", "box-watch.json")
    git("rm", "-q", "box-watch.json")
    git("commit", "-qm", "watcher input removed")
    assert checkplan.run(repo, pinned, "plan.json", "harness") == 66
    git("revert", "--no-edit", "HEAD")
    # A digest-bound input still fails when stale, and the error says how to cover it.
    (repo / "selector.py").write_text("# selector v2\n")
    git("commit", "-qam", "selector change")
    capsys.readouterr()
    assert checkplan.run(repo, pinned, "plan.json", "harness") == 65
    err = capsys.readouterr().err
    assert "uncovered committed input: selector.py" in err and 'plan.json, or bind it to "committed"' in err
    assert hashlib.sha256(b"# selector v2\n").hexdigest() in err
    # Candidate identities keep exact digests: "committed" is not a candidate binding.
    (tmp_path / "c").mkdir()
    crepo, cgit, cplan, _, cand = _check_plan_repo(tmp_path / "c", "candidate")
    cplan["candidates"][cand]["paths"]["selector.py"] = "committed"
    (crepo / "plan.json").write_text(json.dumps(cplan))
    cgit("commit", "-qam", "candidate bound to committed")
    assert checkplan.run(crepo, cgit("rev-parse", "HEAD"), "plan.json", "candidate") == 66

RUNTIME = pathlib.Path(__file__).resolve().parents[1] / "plugins" / "tt-project" / "runtime"
TTP = pathlib.Path(__file__).resolve().parents[1] / "plugins" / "tt-project" / "bin" / "ttp"
# `ttp setup` syncs every filesystem on the host (os.sync); on a busy machine that waits tens of seconds
# for other processes' writes. The env fixture skips it in-process; subprocess runs of setup skip it the
# same way through this launcher. The sync itself is tested in-process.
NO_SYNC = [sys.executable, "-c", "import os, runpy, sys; os.sync = lambda: None; del sys.argv[0]; "
           "runpy.run_path(sys.argv[0], run_name='__main__')"]   # + the launcher to run
TTP_NO_SYNC = [*NO_SYNC, str(TTP)]
# Tests without the env fixture import ttp too; each must also pass when run alone.
sys.path.insert(0, str(RUNTIME))


def _sockets_refused() -> bool:
    """Some sandboxes (`codex sandbox` with the network off) refuse to create a network socket at all,
    even one for loopback, and to bind a Unix socket. The probe binds a name relative to its temporary
    folder, so a deep TMPDIR (past the ~104-byte Unix socket path limit) is not taken for a refusal."""
    import tempfile
    try:
        socket.socket().close()
        with tempfile.TemporaryDirectory() as d, socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM) as s:
            cwd = os.getcwd()
            os.chdir(d)
            try:
                s.bind("s")
            finally:
                os.chdir(cwd)
        return False
    except PermissionError:
        return True


needs_sockets = pytest.mark.skipif(_sockets_refused(), reason="this sandbox refuses network sockets and socket binds")


_CODE: dict = {}       # (path, mtime, size) -> code object of a runtime module
_LOCALES: dict = {}    # gettext.find's arguments and locale settings -> its answer


def _cached_get_code(real):
    """Every test imports the runtime afresh; the modules' code objects are reused instead of being
    read and unmarshalled each time. Each import still runs the module anew."""
    def get_code(self, fullname):
        path = self.get_filename(fullname)
        if not path.startswith(str(RUNTIME) + os.sep):
            return real(self, fullname)
        st = os.stat(path)
        key = (path, st.st_mtime_ns, st.st_size)
        if key not in _CODE:
            _CODE[key] = real(self, fullname)
        return _CODE[key]
    return get_code


def _cached_find(real):
    """argparse looks up a translation for each help string; every `ttp` command in-process builds its
    whole parser, which is thousands of locale file lookups whose answer never changes."""
    def find(domain, localedir=None, languages=None, all=False):
        key = (domain, localedir, tuple(languages) if languages else None, all,
               *(os.environ.get(v) for v in ("LANGUAGE", "LC_ALL", "LC_MESSAGES", "LANG")))
        if key not in _LOCALES:
            _LOCALES[key] = real(domain, localedir, languages, all)
        return _LOCALES[key]
    return find


# Every agent CLI a provider resolves (providers/*.py `binaries`). The env fixture puts stand-ins for
# them first on PATH, and fails a test that resolves or starts one outside its own folder: a test that
# reaches start_run with a real provider would otherwise start a real, billed agent.
PROVIDER_BINARIES = ("claude", "codex", "agent", "cursor-agent")
FAKE_PROVIDER = """#!/bin/sh
# Stands in for an agent CLI in tests: no test ever starts a real one.
[ "$1" = --version ] && echo "0.0.0 (test stand-in)"
exit 0
"""


def _real_provider(argv, env, allowed: pathlib.Path) -> str | None:
    """The agent CLI outside `allowed` that argv would start or names, else None."""
    first = argv if isinstance(argv, (str, bytes, os.PathLike)) else (argv[0] if argv else "")
    first = os.fsdecode(first)
    if os.path.basename(first) not in PROVIDER_BINARIES:
        return None
    path = first if os.sep in first else shutil.which(first, path=(env or os.environ).get("PATH"))
    if not path or not os.path.isfile(path):
        return None
    real = os.path.realpath(path)
    return None if real.startswith(os.path.realpath(allowed) + os.sep) else real


def _no_real_providers(tmp_path, monkeypatch) -> list:
    """Stand-ins for every agent CLI first on PATH, and guards that record (and for Popen, refuse) a
    real one being resolved or started. Returns the list of what was caught."""
    fake_bin = tmp_path / "provider-bin"
    fake_bin.mkdir()
    for name in PROVIDER_BINARIES:
        (fake_bin / name).write_text(FAKE_PROVIDER)
        (fake_bin / name).chmod(0o755)
    monkeypatch.setenv("PATH", f"{fake_bin}{os.pathsep}{os.environ.get('PATH', '')}")
    caught: list = []
    real_popen = subprocess.Popen

    class NoRealProvider(real_popen):
        def __init__(self, args, *a, **kw):
            bad = _real_provider(args, kw.get("env"), tmp_path)
            if bad:
                caught.append(f"started {bad}")
                raise AssertionError(f"a test started a real agent CLI: {bad}")
            super().__init__(args, *a, **kw)
    monkeypatch.setattr(subprocess, "Popen", NoRealProvider)
    from ttp.providers import base
    real_find = base.find_binary

    def find_binary(*names):
        got = real_find(*names)
        if got and _real_provider([got], None, tmp_path):
            caught.append(f"resolved {got}")
        return got
    monkeypatch.setattr(base, "find_binary", find_binary)
    return caught


@pytest.fixture(scope="session")
def _short_tmp(pytestconfig):
    """A short folder for the short temp dirs (ttp.shorttmp) tests make, removed at the end: on the
    session's tmpfs when conftest.py picked one, else /tmp. TTP_TEST_SHORT_TMP_ROOT puts it elsewhere
    (a nested suite that must write nothing else to /tmp)."""
    root = os.environ.get("TTP_TEST_SHORT_TMP_ROOT") or getattr(pytestconfig, "_ttp_tmpfs", None) or "/tmp"
    try:
        base = tempfile.mkdtemp(prefix="ts", dir=root)
    except OSError:   # a sandbox that refuses /tmp: the default temp root
        base = tempfile.mkdtemp(prefix="ts")
    # Named without links, as shorttmp.root() names it: macOS /tmp is a link to /private/tmp, and tests
    # compare paths under the root with this one.
    yield os.path.realpath(base)
    shutil.rmtree(base, ignore_errors=True)


@pytest.fixture(scope="session")
def _git_session(tmp_path_factory):
    """Made once per session: the starting repository each test copies, and an object store holding
    every runtime and template file, which test repositories borrow (git alternates). A project's
    first commit then finds its 2 MB of runtime already stored instead of compressing and writing it."""
    base = tmp_path_factory.mktemp("git-session")
    objects = base / "objects.git"
    subprocess.run(["git", "init", "-q", "--bare", str(objects)], check=True)
    files = [str(f) for d in (RUNTIME, RUNTIME.parent / "template") for f in sorted(d.rglob("*"))
             if f.is_file() and "__pycache__" not in f.parts]
    subprocess.run(["git", f"--git-dir={objects}", "hash-object", "-w", "--stdin-paths"],
                   input="\n".join(files), text=True, capture_output=True, check=True)
    repo = base / "repo"
    repo.mkdir()
    subprocess.run(["git", "init", "-q", str(repo)], check=True)
    (repo / "README.md").write_text("hello\n")
    subprocess.run(["git", "-C", str(repo), "add", "."], check=True)
    subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "i"],
                   check=True)
    # The account's git settings, minus the automatic gc check each commit starts in a child git.
    config = base / "gitconfig"
    home = pathlib.Path(os.environ.get("HOME", "/"))
    xdg = pathlib.Path(os.environ.get("XDG_CONFIG_HOME") or home / ".config")
    own = [os.environ["GIT_CONFIG_GLOBAL"]] if os.environ.get("GIT_CONFIG_GLOBAL") else \
        [str(f) for f in (xdg / "git" / "config", home / ".gitconfig") if f.is_file()]
    config.write_text("".join(f"[include]\n\tpath = {f}\n" for f in own)
                      + "[maintenance]\n\tauto = false\n[gc]\n\tauto = 0\n")
    # An empty bare repository, as `git init --bare` makes it under the tests' git settings: tests copy it.
    bare = base / "bare.git"
    subprocess.run(["git", "init", "-q", "--bare", str(bare)], check=True,
                   env={**os.environ, "GIT_CONFIG_GLOBAL": str(config)})
    return {"objects": objects / "objects", "repo": repo, "config": config, "base": base, "bare": bare}


@pytest.fixture()
def env(tmp_path, monkeypatch, _git_session, _short_tmp):
    home = tmp_path / "home"
    monkeypatch.setenv("TTP_HOME", str(home))
    monkeypatch.setenv("TTP_TEST_SHORT_TMP", _short_tmp)   # never the real /tmp/ttp-<uid>
    monkeypatch.setenv("XDG_CACHE_HOME", str(tmp_path / "cache"))
    monkeypatch.setenv("TTP_HOST", "testhost")
    monkeypatch.setenv("TTP_TEST_LOCAL_TZ", "UTC")   # home zones: never the zone of the machine running the tests
    monkeypatch.setenv("TTP_TEST_POLL_S", "0.05")   # wait loops (runner, ttp lock, listen) check often
    monkeypatch.setenv("TTP_TEST_DISK_MOUNT", str(tmp_path))   # the disk guard's du stays in the test folder
    monkeypatch.setenv("TTP_TEST_SSH_CONFIG", str(tmp_path / "ssh_config"))   # never the user's own ssh config
    monkeypatch.setenv("CLAUDE_CONFIG_DIR", str(tmp_path / "claude"))   # `ttp setup` never writes the user's own skills
    monkeypatch.setenv("TTP_TEST_NO_SYNC", "1")   # setup and upgrades skip the host-wide flush (minutes on a busy host)
    monkeypatch.setenv("TTP_TEST_NO_MCP_PROBE", "1")   # daemons never run the real `claude mcp list` (mcpgap.py)
    monkeypatch.setenv("TTP_TEST_NO_NOTIFIER", "1")   # setup, upgrade and status never restart or test the account's own notifier
    monkeypatch.setenv("TTP_TEST_NO_JOURNAL", "1")   # a reboot record never reads this host's own journal (initiator.py)
    monkeypatch.setenv("TTP_TEST_CYCLE_NOTICES", str(tmp_path / "no-cycle-notice.json"))   # never the real /run notice (cyclenotice.py)
    # Tests may run inside a live run, detached checks, `ttp detach` (no in-run lock-wait cap) or `ttp lock`.
    # The outer checks' output directory and lifetime descriptor belong to that invocation.
    for var in ("TTP_RUN_DIR", "TTP_TASK", "TTP_RUN_ID", "TTP_PROJECT", "TTP_DETACHED", "TTP_LOCKS_HELD", "TTP_PIDNS",
                "TTP_CGROUP", "TTP_CHECK_OUTPUT_DIR", "TTP_CHECKS_TMP_FD", "TTP_PUSH_OWN_BRANCH", "TTP_DETACH_RC",
                "TTP_CHECKS_SLOT", "TTP_CHECKS_HOST_MAX", "TTP_TEST_SLOTS_HELD", "TTP_TEST_POOL", "TTP_TEST_RUN_MAX",
                "TTP_BUILD_SLOTS_HELD", "TTP_BUILD_POOL", "TTP_BUILD_RUN_MAX", "TTP_BUILD_PROJECT_MAX", "MAKEFLAGS",
                "CMAKE_BUILD_PARALLEL_LEVEL"):
        monkeypatch.delenv(var, raising=False)
    monkeypatch.setenv("TTP_CHECKS_LOAD_EXTRA", "0")   # the checks cap never grows with this host's load
    # Tests may run from an ssh login: timefmt.in_ssh_login() is false unless a test sets it.
    for var in ("SSH_CONNECTION", "SSH_CLIENT", "SSH_TTY"):
        monkeypatch.delenv(var, raising=False)
    # A run's environment makes every git fsync its objects (project.git_fsync_env); test repositories
    # need no power-loss durability, and on some filesystems each `git add` then takes 20x longer.
    # Tests of those settings set and inspect them explicitly.
    for var in [v for v in os.environ if v == "GIT_CONFIG_COUNT" or v.startswith(("GIT_CONFIG_KEY_", "GIT_CONFIG_VALUE_"))]:
        monkeypatch.delenv(var)
    sys.path.insert(0, str(RUNTIME))
    for mod in [m for m in list(sys.modules) if m == "ttp" or m.startswith("ttp.")]:
        del sys.modules[mod]
    monkeypatch.setattr(importlib.machinery.SourceFileLoader, "get_code",
                        _cached_get_code(importlib.machinery.SourceFileLoader.get_code))
    monkeypatch.setattr(gettext, "find", _cached_find(gettext.find))
    real_connect = sqlite3.connect

    def no_fsync(*args, **kwargs):
        # Test databases need no power-loss durability; skipping the fsync per commit (the schema
        # alone is a dozen commits) saves most of the time of the many short tests. Subprocesses
        # (runner, ttp lock) keep the real setting.
        conn = real_connect(*args, **kwargs)
        conn.execute("PRAGMA synchronous=OFF")
        return conn
    monkeypatch.setattr(sqlite3, "connect", no_fsync)
    # Likewise for state files: durable_write still writes, renames and calls os.fsync (tests that
    # check the syncs wrap it), but the sync itself, slow on copy-on-write filesystems, is skipped.
    monkeypatch.setattr(os, "fsync", lambda fd: None)
    monkeypatch.setattr(os, "sync", lambda: None)   # setup and upgrade sync the whole disk
    # And for the harness's own commits, which pass the fsync settings per command; it doubles their
    # cost. Tests of those settings set TTP_TEST_GIT_FSYNC to get them back.
    # Tests may run in a `ttp sandbox` (`ttp checks`), where `ttp say` is refused: tests that check
    # the sandbox set it.
    from ttp import sandbox
    monkeypatch.setattr(sandbox, "inside", lambda: False)
    from ttp import project
    # TMPDIR may be a run folder inside a real repository and project. Test directories must
    # not discover either ancestor; keep the temporary files in the sandbox's writable TMPDIR.
    ceiling = str(tmp_path.parent.resolve())
    inherited = os.environ.get("GIT_CEILING_DIRECTORIES", "")
    monkeypatch.setenv("GIT_CEILING_DIRECTORIES", os.pathsep.join(filter(None, (ceiling, inherited))))
    ancestors = set(tmp_path.resolve().parents)
    real_exists = project.Project.exists
    monkeypatch.setattr(project.Project, "exists",
                        lambda self: self.root not in ancestors and real_exists(self))
    real_fsync_args = project.git_fsync_args
    monkeypatch.setattr(project, "git_fsync_args",
                        lambda: real_fsync_args() if os.environ.get("TTP_TEST_GIT_FSYNC") else [])
    # Every new project records the plugin checkout's commit, three git commands in the checkout;
    # it does not change during a session, so it is looked up once. Other folders are looked up live.
    from ttp import cli
    real_checkout_commit = cli._checkout_commit

    def checkout_commit(root):
        if pathlib.Path(root).resolve() != RUNTIME.parent:
            return real_checkout_commit(root)
        if "plugin_commit" not in _git_session:
            _git_session["plugin_commit"] = real_checkout_commit(root)
        return _git_session["plugin_commit"]
    monkeypatch.setattr(cli, "_checkout_commit", checkout_commit)
    # A daemon tick never sends upstream notes on over ssh in a test that registers a remote project;
    # the tests of forwarding turn it back on, with a fake ssh.
    from ttp import upstream
    monkeypatch.setattr(upstream, "FORWARD_EVERY_S", float("inf"))
    monkeypatch.setenv("GIT_ALTERNATE_OBJECT_DIRECTORIES", str(_git_session["objects"]))
    monkeypatch.setenv("GIT_CONFIG_GLOBAL", str(_git_session["config"]))
    repo = tmp_path / "repo"   # a git repository with one commit of README.md
    shutil.copytree(_git_session["repo"], repo, symlinks=True)
    real_agents = _no_real_providers(tmp_path, monkeypatch)
    # make() clones a bootstrapped project unless the test first patches what bootstrap uses: through
    # any MonkeyPatch (this one, monkeypatch.context(), pytest.MonkeyPatch()), or by replacing a
    # function of a standard module bootstrap calls (unittest.mock.patch("time.time")).
    patched = []
    real_setattr, real_delattr = pytest.MonkeyPatch.setattr, pytest.MonkeyPatch.delattr

    def recording(real):
        def patch(self, *args, **kwargs):
            real(self, *args, **kwargs)
            patched.extend(self._setattr[-1:])
        return patch
    monkeypatch.setattr(pytest.MonkeyPatch, "setattr", recording(real_setattr))
    monkeypatch.setattr(pytest.MonkeyPatch, "delattr", recording(real_delattr))
    stdlib = {m: dict(vars(m)) for m in _MAKE_STDLIB}
    yield {"home": home, "repo": repo, "tmp": tmp_path, "real_agents": real_agents,
           "_make": (_git_session, patched, stdlib)}
    _stop_left_checks(repo)
    sys.path.remove(str(RUNTIME))
    assert not real_agents, f"a test reached a real agent CLI: {real_agents}"


def _stop_left_checks(root: pathlib.Path, grace: float = 10.0) -> list[pathlib.Path]:
    """Stops the detached `ttp checks` a test left running in the project at `root` (the daemon starts
    them as a review is queued), by their checks.pid, and returns their folders. pytest removes a
    passed test's folder and gives the next test of the same name the same path, so checks still
    running would write into that test's project. Cheap: it reads only the state's run folders."""
    from ttp import cli
    stopped = []
    for f in (root / "tt-project" / "state").glob(f"*/*/{cli.CHECKS_PID}"):
        info = cli._read_checks_pid(f.parent)
        if not cli._checks_alive(info) or not _own_group_leader(info["pid"]):
            continue   # a pid a test wrote (its own, a helper's) is no detached checks: never wait on it
        for sig in (signal.SIGTERM, signal.SIGKILL):
            try:
                os.killpg(info["pid"], sig)
            except OSError:
                break
            end = time.time() + grace
            while cli._checks_alive(info) and time.time() < end:
                time.sleep(0.05)
            if not cli._checks_alive(info):
                break
        stopped.append(f.parent)
    return stopped


def _own_group_leader(pid: int) -> bool:
    """`pid` leads a process group of its own, as detached checks do (their own session), and that
    group is not this process's: signalling it can stop nothing of the test session."""
    try:
        return os.getpgid(pid) == pid and pid != os.getpgrp()
    except OSError:
        return False


@pytest.fixture
def host_tz(monkeypatch):
    """Sets this machine's zone (TZ + time.tzset) for one test, so a test can prove the runtime reads
    the project's home zone, never the host's. Restores the zone afterwards."""
    old = os.environ.get("TZ")

    def setz(name):
        monkeypatch.setenv("TZ", name)
        time.tzset()
    yield setz
    if old is None:
        os.environ.pop("TZ", None)
    else:
        os.environ["TZ"] = old
    time.tzset()


MAKE_BRIEF = "Keep the README friendly."


def make(env, name="demo"):
    from ttp.project import register
    p = _clone_project(env, name)
    register(name, {"host": "testhost", "dir": str(p.root)})
    return p


# make() bootstraps each project once per test process and clones it after that: a bootstrap is about
# 15 git processes and 3 MB of copies, and most tests start with one. The clone gets the project's own
# root, creation time and id, the git history a bootstrap at that root writes (commits rewritten in
# process), and a database filled anew at the current time. test_make_clone_matches_a_real_bootstrap
# compares the two.

_MAKE_STDLIB = (time, subprocess, os, shutil, secrets, json, sqlite3)


def _bootstrap_patched(patched: list, stdlib: dict) -> bool:
    """Whether the test patched anything bootstrap's outcome depends on (the clock, processes, files,
    the runtime) before calling make(): it then bootstraps for real."""
    for obj, _name, _old in patched:
        mod = obj.__name__ if isinstance(obj, types.ModuleType) else getattr(obj, "__module__", None) or ""
        if mod in ("time", "subprocess", "os", "shutil", "secrets", "json", "sqlite3", "datetime") \
                or mod == "ttp" or mod.startswith("ttp."):
            return True
    return any(vars(m).get(k) is not v for m, attrs in stdlib.items() for k, v in attrs.items())


def _make_key(name: str) -> tuple:
    """Everything outside the test folder that a bootstrap's result depends on."""
    from ttp import cli, timefmt
    from ttp.project import load_secrets
    return (name, cli.__version__, cli.PLUGIN_ROOT, cli.RUNTIME, cli.source_commit(), time.strftime("%Y-%m-%d"),
            os.environ.get("TZ"), cli.hostname(), timefmt.in_ssh_login(), timefmt.detect_local(),
            bool((load_secrets().get("slack") or {}).get("bot_token")),
            tuple(sorted((k, v) for k, v in os.environ.items() if k.startswith("GIT_"))))


def _git_object(git: pathlib.Path, sha: str) -> bytes | None:
    import zlib
    try:
        raw = zlib.decompress((git / "objects" / sha[:2] / sha[2:]).read_bytes())
    except OSError:
        return None
    return raw[raw.index(b"\0") + 1:]


def _put_git_object(git: pathlib.Path, kind: bytes, body: bytes) -> str:
    import hashlib
    import zlib
    raw = kind + b" %d\0" % len(body) + body
    sha = hashlib.sha1(raw).hexdigest()
    path = git / "objects" / sha[:2] / sha[2:]
    if not path.exists():
        path.parent.mkdir(exist_ok=True)
        path.write_bytes(zlib.compress(raw))
        path.chmod(0o444)
    return sha


def _index_layout(data: bytes) -> tuple[list, int] | None:
    """(path, offset) of each entry of a version 2 index, and the offset of its cache-tree root id;
    None for any other layout (the clone then bootstraps for real)."""
    import struct
    if data[:4] != b"DIRC" or struct.unpack(">I", data[4:8])[0] != 2 or not any(data[-20:]):
        return None
    count, off, entries = struct.unpack(">I", data[8:12])[0], 12, []
    for _ in range(count):
        end = data.index(b"\0", off + 62)
        entries.append((data[off + 62:end].decode(), off))
        off += (62 + end - (off + 62) + 8) // 8 * 8
    root = None
    while off < len(data) - 20:
        sig, size = data[off:off + 4], struct.unpack(">I", data[off + 4:off + 8])[0]
        if sig != b"TREE":
            return None
        nl = data.index(b"\n", off + 8)
        if not data[off + 9:nl].startswith(b"-"):   # "" NUL "<entries> <subtrees>\n" <root id>
            root = nl + 1
        off += 8 + size
    return entries, root


def _project_snapshot(gs: dict, name: str) -> dict | None:
    """The bootstrapped project make() clones for `name`, made on first use; None when its git layout
    is one the clone cannot rewrite."""
    key = _make_key(name)
    cache = gs.setdefault("make", {})
    if key in cache:
        return cache[key]
    from ttp import cli
    root = gs["base"] / f"make{len(cache)}"
    shutil.copytree(gs["repo"], root, symlinks=True)
    p = cli.bootstrap(root, name, MAKE_BRIEF, "fake")
    welcome = p.db.one("SELECT text FROM messages")["text"]
    p.db.close()
    for f in p.state.glob("project.db*"):
        f.unlink()
    git = p.harness / ".git"
    snap = None
    head = (git / "refs" / "heads" / "main").read_text().strip() if (git / "refs" / "heads" / "main").is_file() else ""
    chain, sha = [], head
    for _ in range(2):   # the charter-and-config commit, then the schedules commit
        body = _git_object(git, sha) if sha else None
        if not body:
            break
        tree, parent = re.match(rb"tree ([0-9a-f]{40})\nparent ([0-9a-f]{40})\n", body).groups()
        chain.insert(0, (sha, body, tree.decode(), _git_object(git, tree.decode())))
        sha = parent.decode()
    blob = subprocess.run(["git", "-C", str(p.harness), "rev-parse", "HEAD:project.json"],
                          capture_output=True, text=True).stdout.strip()
    index = (git / "index").read_bytes()
    layout = _index_layout(index)
    if (len(chain) == 2 and all(t for *_, t in chain) and blob and layout and layout[1]
            and (git / "HEAD").read_text() == "ref: refs/heads/main\n"
            and index[layout[1]:layout[1] + 20].hex() == chain[1][2]
            and all(bytes.fromhex(blob) in t for *_, t in chain)):
        snap = {"base": p.base, "first": sha, "chain": chain, "blob": blob, "index": index,
                "entries": layout[0], "root": layout[1], "welcome": welcome}
    cache[key] = snap
    return snap


def _clone_file(src, dst):
    """shutil.copy2 that shares the data blocks where the filesystem can (copy_file_range)."""
    try:
        with open(src, "rb") as fi, open(dst, "wb") as fo:
            left = os.fstat(fi.fileno()).st_size
            while left > 0:
                n = os.copy_file_range(fi.fileno(), fo.fileno(), left)
                if not n:
                    break
                left -= n
    except (AttributeError, OSError):
        shutil.copyfile(src, dst)
    shutil.copystat(src, dst)
    return dst


def _rewrite_history(harness: pathlib.Path, snap: dict) -> None:
    """Gives the clone's harness the commits a bootstrap at its root writes: the charter-and-config
    and schedules commits again, with this project.json and the current time, and an index to match."""
    import hashlib
    import struct
    git = harness / ".git"
    now = b"> %d " % int(time.time())
    blob = _put_git_object(git, b"blob", (harness / "project.json").read_bytes())
    old_raw, new_raw = bytes.fromhex(snap["blob"]), bytes.fromhex(blob)
    parent, renamed, stale = snap["first"], {}, [snap["blob"]]
    for sha, body, tree, tree_body in snap["chain"]:
        new_tree = _put_git_object(git, b"tree", tree_body.replace(old_raw, new_raw))
        body = body.replace(b"tree " + tree.encode(), b"tree " + new_tree.encode(), 1)
        body = re.sub(rb"^parent [0-9a-f]{40}", b"parent " + parent.encode(), body, count=1, flags=re.M)
        body = re.sub(rb"> \d+ (?=[+-]\d{4}\n)", now, body)
        renamed[sha] = parent = _put_git_object(git, b"commit", body)
        stale += [sha, tree]
    for sha in stale:
        (git / "objects" / sha[:2] / sha[2:]).unlink(missing_ok=True)
    (git / "refs" / "heads" / "main").write_text(parent + "\n")
    for log in (git / "logs" / "HEAD", git / "logs" / "refs" / "heads" / "main"):
        if log.is_file():
            log.write_text(re.sub("[0-9a-f]{40}", lambda m: renamed.get(m[0], m[0]), log.read_text()))
    index = bytearray(snap["index"][:-20])
    for path, off in snap["entries"]:
        st = os.lstat(harness / path)
        struct.pack_into(">6I", index, off, int(st.st_ctime) & 0xffffffff, st.st_ctime_ns % 10**9,
                         int(st.st_mtime) & 0xffffffff, st.st_mtime_ns % 10**9, st.st_dev & 0xffffffff,
                         st.st_ino & 0xffffffff)
        struct.pack_into(">3I", index, off + 28, st.st_uid, st.st_gid, st.st_size & 0xffffffff)
        if path == "project.json":
            index[off + 40:off + 60] = new_raw
    index[snap["root"]:snap["root"] + 20] = bytes.fromhex(new_tree)
    tmp = git / "index.clone"
    tmp.write_bytes(bytes(index) + hashlib.sha1(index).digest())
    os.replace(tmp, git / "index")


def _clone_project(env, name):
    from ttp import cli
    from ttp import schedule as sched
    from ttp import timefmt
    from ttp.project import Project, write_json
    gs, patched, stdlib = env.get("_make") or (None, [], {})
    if gs is None or Project(env["repo"]).exists() or _bootstrap_patched(patched, stdlib):
        return cli.bootstrap(env["repo"], name, MAKE_BRIEF, "fake")
    snap = _project_snapshot(gs, name)
    if not snap:
        return cli.bootstrap(env["repo"], name, MAKE_BRIEF, "fake")
    p = Project(env["repo"])
    shutil.copytree(snap["base"], p.base, symlinks=True, copy_function=_clone_file)
    cfg = json.loads(p.config_path.read_text())
    cfg.update(root=str(p.root), created=time.time(), id=secrets.token_hex(4))
    write_json(p.config_path, cfg)
    _rewrite_history(p.harness, snap)
    # The database as bootstrap fills it, at this time.
    db = p.db
    for s in json.loads((cli.PLUGIN_ROOT / "template" / "recurring.json").read_text()):
        sched.upsert(db, s["name"], s["kind"], s["every"], s.get("at"), s.get("enabled", True),
                     s.get("budget_usd_day"), s.get("description", ""), s.get("payload", {}), cfg[timefmt.KEY])
    db.set_kv(sched._APPLIED, sched._sha(sched.file_path(p).read_text()))
    db.set_meta("name", name)
    db.post("in", snap["welcome"], chat=None, channel="system", kind="user", provenance="system")
    return p


def _project_picture(p) -> dict:
    """What a project holds, minus what differs per bootstrap (its root, creation time, id and times)."""
    def git(*args):
        out = subprocess.run(["git", "-C", str(p.harness), *args], capture_output=True, text=True)
        return out.returncode, out.stdout.replace(blob, "<config>"), out.stderr
    blob = subprocess.run(["git", "-C", str(p.harness), "hash-object", "project.json"],
                          capture_output=True, text=True, check=True).stdout.strip()
    files = {}
    for f in sorted(p.base.rglob("*")):
        rel = str(f.relative_to(p.base))
        if rel.startswith(("harness/.git/objects/", "harness/.git/logs/", "harness/.git/refs/heads/",
                           "state/project.db")) or rel in ("harness/project.json", "harness/.git/index"):
            continue   # object and commit ids differ by the commits' times; compared through git below
        else:
            files[rel] = "dir" if f.is_dir() else (f.read_bytes(), stat.S_IMODE(f.lstat().st_mode))
    cfg = json.loads(p.config_path.read_text())
    assert cfg.pop("root") == str(p.root)
    cfg.pop("created"), cfg.pop("id")
    def when(v):
        return "<time>" if isinstance(v, (float, str)) and re.fullmatch(r"1[0-9]{9}(\.[0-9]*)?", str(v)) else v
    tables = {r["name"]: [{k: when(v) for k, v in row.items()} for row in p.db.q(f"SELECT * FROM [{r['name']}]")]
              for r in p.db.q("SELECT name FROM sqlite_master WHERE type='table'")}
    return {"files": files, "config": cfg, "db": tables,
            "log": git("log", "--graph", "--format=%s|%an|%ae|%cn|%ce", "--all", "--topo-order"),
            "reflogs": [len(git("reflog", "show", ref)[1].splitlines()) for ref in ("HEAD", "main", "upstream")],
            "tree": git("ls-tree", "-r", "HEAD"), "head_config": git("rev-parse", "HEAD:project.json"),
            "refs": git("for-each-ref", "--format=%(refname)"), "status": git("status", "--porcelain"),
            "staged": git("diff", "--cached", "--stat"), "fsck": git("fsck", "--strict", "--unreachable"),
            "local": git("config", "--local", "-l")}


def test_make_clone_matches_a_real_bootstrap(env):
    from ttp.cli import bootstrap
    p = make(env)
    gs = env["_make"][0]
    assert any(gs["make"].values()), "make() bootstrapped for real instead of cloning"
    real = env["tmp"] / "real"
    shutil.copytree(env["repo"], real, symlinks=True, ignore=shutil.ignore_patterns("tt-project"))
    q = bootstrap(real, "demo", MAKE_BRIEF, "fake")
    got, want = _project_picture(p), _project_picture(q)
    assert got["head_config"] == (0, "<config>\n", "")
    for k in want:
        assert got[k] == want[k], k


def test_make_bootstraps_for_real_after_any_patch_of_what_bootstrap_uses(env):
    import unittest.mock
    from ttp import cli
    def patched():
        return _bootstrap_patched(*env["_make"][1:])
    assert not patched()
    with unittest.mock.patch("time.time", return_value=1.0):
        assert patched()
    assert not patched()
    with pytest.MonkeyPatch.context() as m:
        m.setattr(cli, "HARNESS_ROOT_FILES", ())
        assert patched()
        assert not (make(env).harness / "pytest.ini").exists()


def test_project_folder_is_invisible_to_the_enclosing_repo(env):
    p = make(env)
    out = subprocess.run(["git", "-C", str(env["repo"]), "status", "--porcelain"], capture_output=True, text=True)
    assert out.stdout == "", "the project folder leaked into the user's repository"
    branches = subprocess.run(["git", "-C", str(p.harness), "branch", "--format=%(refname:short)"],
                              capture_output=True, text=True).stdout.split()
    assert set(branches) == {"main", "upstream"}


def test_fake_round_trip_reply_task_and_answer(env):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    p.db.post("in", "add a greeting", chat="c1")
    p.set_config("coordinator.debounce_s", 0)
    deadline = time.time() + 60
    while time.time() < deadline:
        d.cfg = p.config()
        d.tick()
        done = p.db.q("SELECT id FROM tasks WHERE status='done'")
        if len(done) >= 2 and not p.db.q("SELECT id FROM runs WHERE status='running'"):
            break
        time.sleep(0.05)
    replies = p.db.unread_for_chat("c1", 0)
    assert any("ack: add a greeting" in r["text"] for r in replies)
    assert any("fake worker finished" in r["text"] for r in replies)
    assert all(r["status"] == "ok" for r in p.db.q("SELECT status FROM runs"))


def test_replies_stay_in_their_chat_and_broadcasts_respect_the_floor(env):
    p = make(env)
    db = p.db
    db.post("out", "for A", chat="A", kind="reply")
    db.post("out", "for B", chat="B", kind="reply")
    db.post("out", "routine", chat=None, kind="alert", severity="low")
    db.post("out", "needs you", chat=None, kind="ask", severity="high")
    texts = [m["text"] for m in db.unread_for_chat("A", 0, "normal")]
    assert texts == ["for A", "needs you"]


def _reading(p, ts, account, window, util, resets):
    p.db.x("INSERT INTO snapshots(ts,provider,account,window,utilization,resets_at) VALUES(?,?,?,?,?,?)",
           (ts, "claude", account, window, util, resets))


def _run(p, account, started, ended=None, cost=0.0):
    p.db.x("INSERT INTO runs(role,provider,account,started,ended,status,cost_usd) VALUES('worker','claude',?,?,?,?,?)",
           (account, started, ended, "ok" if ended else "running", cost))


def _old_plan(p, now):
    """A plan account's readings, its spend and one completed weekly period (for the 7d average)."""
    _run(p, "acct-a | plan", now - 7200, now - 3000, 60.0)
    p.db.spend("claude", 60.0, "task:1", account="acct-a | plan", ts=now - 3000)
    _reading(p, now - 9 * 86400, "acct-a | plan", "seven_day", 70.0, now - 8 * 86400)
    for ago in (1800, 600):
        _reading(p, now - ago, "acct-a | plan", "seven_day", 86.0, now + 2 * 86400)
        _reading(p, now - ago, "acct-a | plan", "five_hour", 10.0, now + 3600)


def _plan_then_billed(p, now):
    """Plan account A spends inside the 24 h window while it reports plan windows, then the provider
    switches to usage-billed account B mid-window and B spends. B also spent once before the switch
    (an earlier login), when B was already billed by use."""
    from ttp import budget as bud
    _run(p, "acct-b | billed", now - 20 * 3600, now - 19 * 3600, 3.0)
    p.db.spend("claude", 3.0, "task:9", account="acct-b | billed", ts=now - 19 * 3600)
    for h in range(18, 6, -1):   # A on its plan: readings with its runs, every hour
        _reading(p, now - h * 3600, "acct-a | plan", "five_hour", 20.0, now + 3600)
        _run(p, "acct-a | plan", now - h * 3600 - 600, now - h * 3600 + 60, 20.0)
        p.db.spend("claude", 20.0, "task:1", account="acct-a | plan", ts=now - h * 3600 + 60)
    bud.note_account(p.db, "claude", "acct-b | billed")
    for h in (5, 3, 1):
        _run(p, "acct-b | billed", now - h * 3600 - 600, now - h * 3600, 4.0)
        p.db.spend("claude", 4.0, "task:2", account="acct-b | billed", ts=now - h * 3600)


def test_a_switch_back_to_a_plan_keeps_the_billed_spend_billed(env):
    """usage-billed B -> plan A: B's spend stays billed and A's new spend is plan spend, decided by
    each row's account and time, not by the account the provider is on now."""
    p = make(env)
    from ttp import billing
    now = time.time()
    _plan_then_billed(p, now)
    _run(p, "acct-a | plan", now - 1800, now - 600, 30.0)
    p.db.spend("claude", 30.0, "task:3", account="acct-a | plan", ts=now - 600)
    _reading(p, now - 600, "acct-a | plan", "five_hour", 25.0, now + 3600)
    bud_spent = p.db.spent_since(now - 86400, billed=True)
    assert round(bud_spent, 2) == 15.0, "B's spend stayed billed; A's spend before and after was plan"
    assert billing.billed_by_account(p.db.conn, now - 86400) == {("claude", "acct-b | billed"): 15.0}
    spans = billing.plan_spans(p.db.conn, now - 86400, "claude")
    assert not billing.is_plan(spans, "claude", "acct-a | plan", now - 3 * 3600), "A was not in use then"
    assert billing.is_plan(spans, "claude", "acct-a | plan", now - 10 * 3600)


def test_ledger_rows_without_an_account_take_their_runs_or_follow_the_providers_plan(env):
    """Old rows written without an account: the migration gives each the account of the run that
    ended when it was booked; one no run explains is plan spend while the provider reported plan
    windows then, and billed otherwise. Never billed just for having no account."""
    p = make(env)
    from ttp import db as dbm
    now = time.time()
    _reading(p, now - 6 * 3600, "acct-a | plan", "five_hour", 20.0, now + 3600)
    _run(p, "acct-b | billed", now - 3 * 3600, now - 2 * 3600, 6.0)
    for ts, usd in ((now - 2 * 3600, 6.0),          # B's run: inferred, billed
                    (now - 6 * 3600 + 60, 40.0),    # no run, A on its plan then: plan
                    (now - 4 * 3600, 5.0)):         # no run, no plan reading then: billed
        p.db.x("INSERT INTO ledger(ts,provider,account,source,usd) VALUES(?,?,NULL,'task:1',?)", (ts, "claude", usd))
    p.db.x("DELETE FROM meta WHERE key=?", (dbm.LEDGER_ACCOUNT_MIGRATION,))
    p.db._migrate()
    got = {round(r["usd"]): r["account"] or "" for r in p.db.q("SELECT usd, account FROM ledger")}
    assert got == {6: "acct-b | billed", 40: "", 5: ""}, got
    assert round(p.db.spent_since(now - 86400, billed=True), 2) == 11.0


def test_a_lapsed_plan_counts_its_spend_after_its_last_reading(env):
    """Paid runs of the same account that report no windows end its plan at the last reading."""
    p = make(env)
    now = time.time()
    _reading(p, now - 5 * 3600, "acct-a | plan", "five_hour", 20.0, now + 3600)
    for h in (4.9, 4.5, 3):
        _run(p, "acct-a | plan", now - h * 3600 - 60, now - h * 3600, 8.0)
        p.db.spend("claude", 8.0, "task:1", account="acct-a | plan", ts=now - h * 3600)
    assert round(p.db.spent_since(now - 86400, billed=True), 2) == 24.0


def test_fingerprint_keeps_digits_inside_identifiers(env):
    make(env)
    from ttp.screen import fingerprint
    a = fingerprint("watch", "broker host03 chip 22 drop after 30s at 2026-10-01T05:30:00Z")
    b = fingerprint("watch", "broker host01 chip 22 drop after 30s at 2026-10-01T05:30:00Z")
    c = fingerprint("watch", "broker host03 chip 9 drop after 45s at 2026-10-02T11:02:03Z")
    assert a != b and a == c
    assert fingerprint("w", "gpu1 failed v1.0.0 in /tmp/x1/y") == fingerprint("w", "gpu1 failed v1.2.3 in /tmp/z")
    assert fingerprint("w", "gpu1 failed") != fingerprint("w", "gpu2 failed")


def test_screening_dedupes_and_reopens_fixed_issues(env):
    p = make(env)
    from ttp.screen import screen
    cfg = p.config()
    first = screen(p.db, cfg, "log:app", "ERROR: device timed out after 30s on core 12")
    again = screen(p.db, cfg, "log:app", "ERROR: device timed out after 45s on core 7")
    assert first.wake and not again.wake and first.fingerprint == again.fingerprint
    p.db.x("UPDATE issues SET status='fixed' WHERE id=?", (first.issue_id,))
    assert screen(p.db, cfg, "log:app", "ERROR: device timed out after 9s on core 1").wake


def test_screening_wakes_again_on_repeats_and_after_a_quiet_spell(env):
    p = make(env)
    from ttp.screen import screen
    cfg = p.config()
    text = "box-a: chip 3 dropped, power-cycle failed"
    first = screen(p.db, cfg, "watcher:hw", text, rewake_after_s=6 * 3600)
    assert first.wake
    # Seen again soon: still the same event, stays quiet.
    assert not screen(p.db, cfg, "watcher:hw", text, rewake_after_s=6 * 3600).wake
    # The watcher marks it as a new occurrence: wakes every time.
    assert screen(p.db, cfg, "watcher:hw", text, repeat=True).reason == "repeated"
    # Back after more than the window: wakes again, without the window it never does.
    quiet = "UPDATE issues SET last_seen=?, last_woken=? WHERE id=?"
    p.db.x(quiet, (time.time() - 7 * 3600, time.time() - 7 * 3600, first.issue_id))
    assert not screen(p.db, cfg, "watcher:hw", text).wake
    p.db.x(quiet, (time.time() - 7 * 3600, time.time() - 7 * 3600, first.issue_id))
    again = screen(p.db, cfg, "watcher:hw", text, rewake_after_s=6 * 3600)
    assert again.wake and again.issue_id == first.issue_id and "quiet" in again.reason
    # Below the wake floor, or ignored by the user: repeats stay quiet.
    info = screen(p.db, cfg, "watcher:hw", "box-a: all chips up")
    assert not info.wake and not screen(p.db, cfg, "watcher:hw", "box-a: all chips up", repeat=True).wake
    p.db.x("UPDATE issues SET status='ignored' WHERE id=?", (first.issue_id,))
    assert not screen(p.db, cfg, "watcher:hw", text, repeat=True).wake


def _rewake_rig(env, monkeypatch):
    """A watcher reporting one held condition on a fake clock: (see(at_h, **kw) -> Verdict, p, scr)."""
    p = make(env)
    from ttp import screen as scr
    cfg = p.config()
    clock = {"t": 1_800_000_000.0}
    t0 = clock["t"]
    monkeypatch.setattr(scr.time, "time", lambda: clock["t"])

    def see(at_h, text="box-a: queue held (3 jobs waiting)", **kw):
        clock["t"] = t0 + at_h * 3600
        kw.setdefault("rewake_after_s", 6 * 3600)
        return scr.screen(p.db, cfg, "watcher:hw", text, "high", key="box-a-queue", **kw)
    return see, p, scr


def test_a_held_condition_reported_every_run_reminds_every_rewake_window(env, monkeypatch):
    see, p, _scr = _rewake_rig(env, monkeypatch)
    # Reported every 2 h for a day: woken at the first sighting, then about every 6 h, never in between.
    woke = [h for h in range(0, 26, 2) if see(h, f"box-a: queue held ({h} jobs waiting)").wake]
    assert woke == [0, 6, 12, 18, 24]
    assert len(p.db.q("SELECT id FROM issues")) == 1
    row = p.db.one("SELECT last_seen, last_woken, count FROM issues")
    assert row["count"] == 13 and row["last_seen"] == row["last_woken"]
    assert not see(26).wake and not see(28).wake
    assert "after its last wake" in see(30).reason


def test_a_held_condition_without_a_rewake_window_wakes_once(env, monkeypatch):
    see, _p, _scr = _rewake_rig(env, monkeypatch)
    assert [h for h in range(0, 50, 2) if see(h, rewake_after_s=None).wake] == [0]


def test_a_muted_held_condition_reminds_only_after_the_mute(env, monkeypatch):
    see, p, scr = _rewake_rig(env, monkeypatch)
    assert see(0).wake
    scr.mute(p.db, "watcher:hw", "queue held", 20, now=1_800_000_000.0 + 3600)
    assert [h for h in range(2, 21, 2) if see(h).wake] == [], "no reminder while muted"
    # The mute is over: the overdue reminder comes at the next sighting, then the clock restarts.
    assert see(22).wake and not see(24).wake and see(28).wake


def test_a_migrated_issue_does_not_rewake_at_once_after_the_upgrade(env, monkeypatch):
    see, p, _scr = _rewake_rig(env, monkeypatch)
    from ttp.db import DB
    # A day-old issue, seen every run, from a database without the last_woken column.
    assert see(0).wake
    for h in range(2, 25, 2):
        see(h)
    p.db.x("ALTER TABLE issues DROP COLUMN last_woken")
    db = DB(p.db.path)
    row = db.one("SELECT last_seen, last_woken FROM issues")
    assert row["last_woken"] == row["last_seen"], "the reminder clock starts at the last sighting"
    assert not see(26).wake and see(30).wake


def test_a_cleared_held_condition_that_returns_wakes_as_new(env, monkeypatch):
    see, p, scr = _rewake_rig(env, monkeypatch)
    assert see(0).wake and not see(2).wake
    assert not see(3, "box-a: cleared: queue held").wake
    assert p.db.one("SELECT status FROM issues")["status"] == "fixed"
    back = see(4)
    assert back.wake and back.reason == "regressed after fix"
    # The return restarts the reminder clock.
    assert not see(8).wake and see(10).wake


class _FakeJev:
    """Stands in for providers.jev.Jev: answers every screening question the same way."""

    def __init__(self, actionable, severity, cost=0.0001):
        self.actionable, self.severity, self.last_cost, self.calls = actionable, severity, cost, 0

    def enabled(self):
        return True

    def decide(self, state, questions, purpose="decide"):
        self.calls += 1
        return {"actionable": {"noul": self.actionable}, "severity": {"score": self.severity}}


def test_jev_screening_that_saves_nothing_is_switched_off_once_and_can_be_forced_back(env):
    p = make(env)
    from ttp import jevuse
    from ttp.screen import screen
    p.set_config("jev.min_calls", 3)
    cfg = p.config()
    jev = _FakeJev(0.95, 2.0)   # agrees with the rules: every wake still happens
    for i in range(3):
        assert screen(p.db, cfg, "log:app", f"ERROR: job {chr(97 + i)} failed", jev=jev).wake
    rows = p.db.q("SELECT use, ref, cost_usd, avoided_usd, decision FROM jev_calls ORDER BY id")
    assert [r["use"] for r in rows] == ["screen"] * 3 and all(r["avoided_usd"] == 0 for r in rows)
    assert rows[0]["ref"].startswith("issue:") and json.loads(rows[0]["decision"])["wake"] is True
    [line] = jevuse.lines(p.db, cfg)
    assert "3 calls" in line and "est. saved $0.000" in line and "net -$0.000" in line and line.endswith("; on")
    [(use, s)] = jevuse.review(p.db, cfg)
    assert use == "screen" and s["net"] < 0
    assert jevuse.review(p.db, cfg) == []   # reported once
    assert "switched off" in jevuse.off_text(use, s, cfg) and "jev.uses.screen" in jevuse.off_text(use, s, cfg)
    assert not jevuse.allowed(p.db, cfg, "screen") and "switched off (net" in jevuse.lines(p.db, cfg)[0]
    screen(p.db, cfg, "log:app", "ERROR: job z failed", jev=jev)
    assert jev.calls == 3   # the rules decide alone now
    p.set_config("jev.uses", {"screen": "on"})
    cfg = p.config()
    assert jevuse.allowed(p.db, cfg, "screen") and jevuse.review(p.db, cfg) == []
    assert p.db.kv(jevuse.OFF_KEY) == {} and "forced on" in jevuse.lines(p.db, cfg)[0]
    p.set_config("jev.uses", {"screen": "off"})
    assert not jevuse.allowed(p.db, p.config(), "screen")


def test_jev_skipped_wake_is_priced_at_a_coordinator_turn_and_a_later_wake_marks_it_wrong(env):
    p = make(env)
    from ttp import jevuse
    from ttp.screen import screen
    now = time.time()
    for cost in (0.3, 0.5, 0.0):   # unmetered turns do not count
        p.db.x("INSERT INTO runs(role,status,started,ended,cost_usd,effort) VALUES('coordinator','ok',?,?,?,'low')",
               (now - 3600, now - 3500, cost))
    p.set_config("coordinator.effort", "low")
    cfg = p.config()
    assert jevuse.mean_turn_cost(p.db, cfg) == pytest.approx(0.4)
    quiet = _FakeJev(0.1, 0.0)
    v = screen(p.db, cfg, "watcher:hw", "box-a: link retry failed", jev=quiet)
    assert not v.wake and v.screen == "jev"
    [s] = jevuse.stats(p.db, cfg).values()
    assert s["saved"] == pytest.approx(0.4) and s["net"] > 0 and s["right"] == s["wrong"] == 0
    assert "error rate unknown" in jevuse.lines(p.db, cfg)[0]
    # The watcher later rates it high: the coordinator wakes for it after all, so the skip was wrong.
    again = screen(p.db, cfg, "watcher:hw", "box-a: link retry failed", "high", jev=quiet)
    assert again.wake and again.issue_id == v.issue_id
    row = p.db.one("SELECT outcome, note FROM jev_calls")
    assert row["outcome"] == "wrong" and row["note"] == "now high"
    s = jevuse.stats(p.db, cfg)["screen"]
    assert s["saved"] == 0 and s["wrong"] == 1
    # A skip whose issue stayed quiet past the settle time counts as right.
    screen(p.db, cfg, "watcher:hw", "box-b: fan slow failed", jev=quiet)
    assert jevuse.stats(p.db, cfg)["screen"]["right"] == 0
    assert jevuse.stats(p.db, cfg, now=time.time() + 4 * 86400)["screen"]["right"] == 1
    p.db.x("UPDATE jev_calls SET settle_at=? WHERE outcome IS NULL", (time.time() - 1,))
    assert "errors 1/2 (50%)" in jevuse.lines(p.db, cfg)[0]
    # The ledger is generic: any later use logs its picks and their outcomes the same way.
    cid = jevuse.record(p.db, "effort", {"effort": "high"}, 0.0002, avoided_usd=1.5, ref="task:7")
    assert jevuse.resolve(p.db, cid, True) and not jevuse.resolve(p.db, cid, False)
    assert jevuse.stats(p.db, cfg)["effort"]["net"] == pytest.approx(1.5 - 0.0002)


def test_jev_screening_skip_is_priced_at_a_low_turn_settles_against_later_wakes_and_tasks(env):
    p = make(env)
    from ttp import daemon as dm
    from ttp import jevuse
    from ttp import screen as scr
    now = time.time()
    p.set_config("coordinator.effort", "low")
    cfg = p.config()
    quiet = _FakeJev(0.1, 0.0)
    # No low-effort turn measured yet: the documented constant prices the skipped wake.
    a = scr.screen(p.db, cfg, "watcher:hw", "box-a: link retry failed", jev=quiet)
    assert not a.wake and p.db.one("SELECT avoided_usd FROM jev_calls")["avoided_usd"] == jevuse.WAKE_COST_FALLBACK_USD
    # A turn at another effort does not count: only the coordinator's current effort prices a skip.
    for cost, effort in ((0.2, "low"), (0.4, "low"), (2.0, "high")):
        p.db.x("INSERT INTO runs(role,status,started,ended,cost_usd,effort) VALUES('coordinator','ok',?,?,?,?)",
               (now - 3600, now - 3500, cost, effort))
    assert jevuse.coordinator_effort(cfg) == "low"
    assert jevuse.turn_cost(p.db, cfg) == pytest.approx(0.3)
    b = scr.screen(p.db, cfg, "watcher:hw", "box-b: fan speed check failed", jev=quiet)
    c = scr.screen(p.db, cfg, "watcher:hw", "box-c: disk scrub failed", jev=quiet)
    d = scr.screen(p.db, cfg, "watcher:hw", "box-d: clock sync failed", jev=quiet)
    calls = {r["ref"]: r for r in p.db.q("SELECT * FROM jev_calls")}
    assert calls[f"issue:{b.issue_id}"]["avoided_usd"] == pytest.approx(0.3)
    assert calls[f"issue:{b.issue_id}"]["changed"] == 1, "a skipped wake changed the rules' decision"
    # Within the window: a's condition woke the coordinator anyway, a task quotes b's title.
    p.db.x("INSERT INTO events(ts,source,kind,fingerprint,severity,text,status) VALUES(?,?,?,?,?,?,?)",
           (time.time() + 1, "watcher:hw", "observation", a.fingerprint, "high", "box-a: link retry failed", "done"))
    p.db.x("INSERT INTO tasks(created,title,spec) VALUES(?,?,?)",
           (time.time() + 1, "Check fans", "The watcher said: box-b: fan speed check failed. Look into it."))
    assert scr.settle_jev(p.db, time.time() + 5) == 2
    out = {r["ref"]: r for r in p.db.q("SELECT ref, outcome, note FROM jev_calls")}
    assert out[f"issue:{a.issue_id}"]["outcome"] == "wrong" and "woke the coordinator" in out[f"issue:{a.issue_id}"]["note"]
    assert out[f"issue:{b.issue_id}"]["outcome"] == "wrong" and "was about the issue" in out[f"issue:{b.issue_id}"]["note"]
    assert out[f"issue:{c.issue_id}"]["outcome"] is None and out[f"issue:{d.issue_id}"]["outcome"] is None
    # After the window: a task about c, or a wake of d, comes too late to count against the skip.
    late = now + scr.JEV_SETTLE_S + 3600
    p.db.x("INSERT INTO tasks(created,title,spec) VALUES(?,?,?)", (late - 60, "box-c: disk scrub failed", ""))
    p.db.x("UPDATE issues SET status='fixed' WHERE id=?", (d.issue_id,))
    p.db.x("UPDATE jev_calls SET settle_at=? WHERE outcome IS NULL", (time.time() - 1,))
    assert scr.screen(p.db, cfg, "watcher:hw", "box-d: clock sync failed", "high", jev=quiet).wake
    assert p.db.one("SELECT outcome FROM jev_calls WHERE ref=?", (f"issue:{d.issue_id}",))["outcome"] is None
    d_ = dm.Daemon(p.base)
    d_.cfg = cfg
    d_.review_jev(every_s=0)   # the daemon settles before it reviews
    s = jevuse.stats(p.db, cfg)["screen"]
    assert (s["right"], s["wrong"]) == (2, 2)
    assert s["saved"] == pytest.approx(0.6) and "errors 2/4 (50%)" in jevuse.lines(p.db, cfg)[0]
    assert p.db.one("SELECT note FROM jev_calls WHERE ref=?", (f"issue:{c.issue_id}",))["note"] == "stayed quiet"


def test_jev_use_called_rarely_is_judged_once_its_first_call_is_a_window_old(env):
    p = make(env)
    from ttp import jevuse
    cfg = p.config()
    now = time.time()
    week = jevuse.window_s(cfg)
    # Fewer calls than min_calls and nothing saved: not judged until a full window has passed.
    for _ in range(3):
        jevuse.record(p.db, "screen", {"wake": True}, 0.001, now=now - 3600)
    assert jevuse.review(p.db, cfg, now) == []
    jevuse.record(p.db, "screen", {"wake": True}, 0.001, now=now - week - 60)   # a first call, a window ago
    [(use, s)] = jevuse.review(p.db, cfg, now)
    assert use == "screen" and s["calls"] == 3 and s["saved"] == 0 and not jevuse.allowed(p.db, cfg, "screen")
    # A rare use that does save stays on.
    jevuse.record(p.db, "effort", {"effort": "low"}, 0.001, avoided_usd=0.5, now=now - week - 60)
    jevuse.record(p.db, "effort", {"effort": "low"}, 0.001, avoided_usd=0.5, now=now - 60)
    assert jevuse.review(p.db, cfg, now) == [] and jevuse.allowed(p.db, cfg, "effort")


def test_jev_use_that_never_changes_the_rules_decision_is_switched_off_after_idle_calls(env):
    """A use whose idle_calls known calls all made the rules' own decision goes off, with that reason in
    the daily line; one call that changed a decision keeps it on. Screening records whether it skipped
    or raised a wake."""
    p = make(env)
    from ttp import jevuse
    from ttp import screen as scr
    cfg = p.config()
    assert jevuse.idle_calls(cfg) == 20
    for _ in range(19):
        jevuse.record(p.db, "screen", {"wake": True}, 0.001, changed=False)
        jevuse.record(p.db, "effort", {"effort": "standard"}, 0.001, changed=False)
    jevuse.record(p.db, "screen", {"wake": True}, 0.001)   # unknown: neither counts nor keeps it on
    assert jevuse.review(p.db, cfg) == []
    jevuse.record(p.db, "screen", {"wake": True}, 0.001, changed=False)
    jevuse.record(p.db, "effort", {"effort": "light"}, 0.001, avoided_usd=0.0, changed=True)
    jevuse.record(p.db, "effort", {"effort": "standard"}, 0.001, changed=False)
    [(use, s)] = jevuse.review(p.db, cfg)
    assert use == "screen" and s["unchanged"] == 20 and s["changed"] == 0 and not jevuse.allowed(p.db, cfg, "screen")
    assert jevuse.allowed(p.db, cfg, "effort"), "one changed decision keeps it on"
    assert "none of its 20 calls changed the rules' decision" in jevuse.off_text(use, s, cfg)
    line = next(x for x in jevuse.lines(p.db, cfg) if x.startswith("watcher screening"))
    assert "switched off (no call changed the rules' decision in 20 calls)" in line
    assert "changed the rules' decision 0/20" in line
    p.set_config("jev.uses.screen", "on")   # forced on: no idle switch-off
    assert jevuse.allowed(p.db, p.config(), "screen")
    # Screening: agreeing with the rules is no change; raising a wake the rules would not is one.
    p.set_config("jev.uses.screen", "auto")
    p.db.set_kv(jevuse.OFF_KEY, {})
    cfg = p.config()
    scr.screen(p.db, cfg, "watcher:hw", "box-e: link retry failed", "high", jev=_FakeJev(0.9, 2.0))
    scr.screen(p.db, cfg, "watcher:hw", "box-f: all fine", jev=_FakeJev(0.9, 3.0))
    a, b = p.db.q("SELECT changed FROM jev_calls WHERE use='screen' ORDER BY id DESC LIMIT 2")
    assert (b["changed"], a["changed"]) == (0, 1)


def test_jev_never_raises_a_watcher_lines_explicit_severity_hint_but_may_lower_it(env):
    p = make(env)
    from ttp.screen import screen
    p.set_config("jev.uses.screen", "on")
    cfg = p.config()
    loud = _FakeJev(0.95, 3.0)
    # A hinted 'low' line (a recovery) stays low when Jev rates it critical: no coordinator wake.
    v = screen(p.db, cfg, "watcher:hw", "box-a: recovered after link retry failed", "low", jev=loud)
    assert loud.calls == 1 and v.severity == "low" and not v.wake
    assert "capped at the watcher's hint low" in v.reason
    row = p.db.one("SELECT changed FROM jev_calls WHERE use='screen' ORDER BY id DESC LIMIT 1")
    assert row["changed"] == 0
    # Jev may still lower a hinted line.
    v = screen(p.db, cfg, "watcher:hw", "box-b: link retry failed", "high", jev=_FakeJev(0.1, 0.0))
    assert v.severity == "info" and not v.wake and v.screen == "jev"
    # Below the hint it is left as Jev scored it.
    v = screen(p.db, cfg, "watcher:hw", "box-c: fan slow", "critical", jev=_FakeJev(0.9, 2.0))
    assert v.severity == "high" and "capped" not in v.reason
    # A line without a hint keeps today's behaviour: Jev may raise it.
    v = screen(p.db, cfg, "watcher:hw", "box-d: all fine", jev=loud)
    assert v.severity == "critical" and v.wake and "capped" not in v.reason


def test_daemon_reports_a_jev_use_switched_off_once_and_feeds_the_daily_review(env):
    p = make(env)
    from ttp import daemon as dm
    from ttp import jevuse
    p.set_config("jev.min_calls", 2)
    for _ in range(2):
        jevuse.record(p.db, "screen", {"wake": True}, 0.001)
    d = dm.Daemon(p.base)
    d.cfg = p.config()
    d.review_jev(every_s=0)
    d.review_jev(every_s=0)
    sent = [m for m in p.db.q("SELECT text, severity FROM messages WHERE direction='out' AND ref='jev-off:screen'")]
    assert len(sent) == 1 and sent[0]["severity"] == "low" and "watcher screening is switched off" in sent[0]["text"]
    s = {"name": "daily-review", "budget_usd_day": None, "last_run": None, "description": "review"}
    assert d._schedule_llm(s, {}) == "queued"
    spec = p.db.one("SELECT spec FROM tasks WHERE origin='schedule'")["spec"]
    assert "Jev uses over the last 7 d" in spec and "- watcher screening [screen]: 2 calls, cost $0.002" in spec


def test_jev_out_of_funds_alerts_and_screening_falls_back_to_rules(env):
    p = make(env)
    from ttp import daemon as dm
    from ttp.providers.jev import JevOutOfFunds

    class Broke:
        calls = 0

        def enabled(self):
            return True

        def decide(self, *a, **k):
            self.calls += 1
            raise JevOutOfFunds("no credits")

    d = dm.Daemon(p.base)
    d.cfg = p.config()
    d.jev = Broke()
    d.observe("log:app", "ERROR: job a failed")
    assert d.jev.calls == 1
    assert p.db.one("SELECT COUNT(*) n FROM messages WHERE direction='out' AND ref='jev-funds'")["n"] == 1
    assert p.db.one("SELECT COUNT(*) n FROM events WHERE kind='observation' AND source='log:app'")["n"] == 1


def test_jev_pause_after_out_of_funds_holds_across_config_reloads_and_schedule_runs(env, monkeypatch):
    p = make(env)
    import io
    import urllib.error
    from ttp import daemon as dm
    from ttp.providers import jev as jevmod
    calls = []

    def broke(req, timeout=None):
        calls.append(req.full_url)
        raise urllib.error.HTTPError(req.full_url, 402, "Payment Required", {}, io.BytesIO(b""))

    monkeypatch.setattr(jevmod, "load_secrets", lambda: {"jev": {"key": "k", "url": "http://jev.invalid"}})
    monkeypatch.setattr(jevmod.urllib.request, "urlopen", broke)
    d = dm.Daemon(p.base)
    with pytest.raises(jevmod.JevOutOfFunds):
        d.jev.decide("s", {"q": {"type": "noul", "question": "?"}})
    assert len(calls) == 1 and not d.jev.enabled()
    d._last_cfg = 0.0
    d.tick()   # reloads the config and builds a new Jev: still paused
    assert not d.jev.enabled()
    seen = []

    def watcher(self, s, payload):
        seen.append((self.jev is not d.jev, self.jev.enabled(), self.jev.decide("s", {})))
        return "ok"

    monkeypatch.setattr(dm.Daemon, "_run_command_watcher", watcher)
    run = d._start_schedule({"name": "w", "kind": "command"}, {"command": "true"})
    assert run.done.wait(20), "the schedule run did not end"
    assert seen == [(True, False, None)] and run.result[0] == "ok"
    assert len(calls) == 1, "a schedule run started during the pause called Jev"


def test_effort_rules_start_short_lookups_light_and_everything_else_standard(env):
    from ttp.effort import rules_tier
    assert rules_tier({"kind": "question", "title": "Which boxes run the old broker?", "spec": "List them."}) == "light"
    assert rules_tier({"kind": "work", "title": "Check the queue status", "spec": "Report its length."}) == "light"
    assert rules_tier({"kind": "work", "title": "Check the queue and fix it", "spec": ""}) == "standard"
    assert rules_tier({"kind": "work", "title": "Tidy notes", "spec": "Merge the two notes."}) == "standard"
    assert rules_tier({"kind": "code", "title": "What breaks?", "spec": "x"}) == "standard"
    assert rules_tier({"kind": "question", "title": "Why?", "spec": "x" * 900}) == "standard"


class _EffortJev:
    def __init__(self, score, cost=0.0002):
        self.score, self.last_cost, self.calls = score, cost, 0

    def enabled(self):
        return True

    def decide(self, state, questions, purpose="decide", timeout=20.0):
        self.calls += 1
        assert purpose == "effort" and "effort" in questions
        return {"effort": {"score": self.score}}


def test_jev_picks_effort_once_logs_it_with_the_run_and_deep_comes_only_on_a_retry(env, monkeypatch):
    p = make(env)
    from ttp import jevuse
    from ttp.daemon import Daemon
    from ttp.providers.base import RunUsage as Usage
    now = time.time()
    for model, effort, cost in (("opus", "high", 3.0), ("opus", "high", 5.0), ("sonnet", "low", 1.0)):   # per tier
        p.db.x("INSERT INTO runs(role,provider,model,effort,status,started,ended,cost_usd) "
               "VALUES('worker','claude',?,?,'ok',?,?,?)", (model, effort, now - 3600, now - 3500, cost))
    d = Daemon(p.base)
    d.jev = _EffortJev(0.2)
    monkeypatch.setattr(d, "_workdir_for", lambda t: (str(p.base), None))
    started = []
    monkeypatch.setattr(d, "start_run", lambda *a, **k: started.append((a, k)) or 0)
    q = p.db.add_task("Which boxes run the old broker?", "List them.", kind="question", tier="standard",
                      origin="coordinator", provider="claude", budget_usd=8.0)
    d.dispatch()
    (args, kw), = started
    assert args[3] == "light" and p.db.task(q)["tier"] == "light"
    assert kw["note"]["pick"] == {"tier": "light", "by": "jev", "score": 0.2, "jev_call": kw["note"]["pick"]["jev_call"],
                                  "from": "standard", "review": False}
    row = p.db.one("SELECT * FROM jev_calls")
    assert row["use"] == "effort" and row["ref"] == f"task:{q}" and row["avoided_usd"] == pytest.approx(3.0)
    assert row["changed"] == 0, "the rules pick light for a short question too"
    assert json.loads(row["decision"]) == {"effort": "light", "review": False, "spec_len": 10, "score": 0.2}
    # Done on its first try: the pick was right.
    run_dir = env["tmp"] / "run-q"
    run_dir.mkdir()
    (run_dir / "result.json").write_text(json.dumps({"status": "done", "summary": "two boxes"}))
    d._finish_worker({"task": q}, Usage(cost_usd=0.5), "ok", run_dir)
    assert p.db.one("SELECT outcome FROM jev_calls")["outcome"] == "right"
    assert "task effort picking [effort]: 1 calls" in jevuse.lines(p.db, p.config())[0]

    # A hard task: Jev never starts it at deep; it runs at standard and keeps its review.
    d.jev = _EffortJev(2.9)
    c = p.db.add_task("Redesign the scheduler", "Make it fair.", kind="code", tier="standard", origin="coordinator",
                      provider="claude", budget_usd=8.0)
    started.clear()
    d.dispatch()
    (args, kw), = started
    assert args[3] == "standard" and kw["note"]["pick"]["review"] is True and kw["note"]["pick"]["by"] == "jev"
    assert p.db.one("SELECT avoided_usd FROM jev_calls WHERE ref=?", (f"task:{c}",))["avoided_usd"] == 0
    assert p.db.one("SELECT changed FROM jev_calls WHERE ref=?", (f"task:{c}",))["changed"] == 0
    # Its run ends without a hand-off: the retry runs at deep, within what is left of its budget.
    p.db.x("INSERT INTO runs(task,role,provider,status,started) VALUES(?,'worker','claude','ok',?)", (c, now))
    run_dir = env["tmp"] / "run-c"
    run_dir.mkdir()
    d._finish_worker({"task": c}, Usage(cost_usd=2.0), "ok", run_dir)
    t = p.db.task(c)
    assert t["status"] == "queued" and t["attempts"] == 1
    p.db.update_task(c, not_before=None, spent_usd=2.0)
    started.clear()
    d.jev.calls = 0
    d.dispatch()
    (args, kw), = started
    assert args[3] == "deep" and kw["note"]["pick"] == {"tier": "deep", "from": "standard", "by": "retry", "review": True}
    assert kw["budget_usd"] == pytest.approx(6.0) and d.jev.calls == 0 and p.db.task(c)["tier"] == "deep"
    p.db.update_task(c, status="running")
    run_dir = env["tmp"] / "run-c2"
    run_dir.mkdir()
    (run_dir / "result.json").write_text(json.dumps({"status": "done", "summary": "fair now"}))
    d._finish_worker({"task": c}, Usage(cost_usd=4.0), "ok", run_dir)
    row = p.db.one("SELECT outcome, note FROM jev_calls WHERE ref=?", (f"task:{c}",))
    assert row["outcome"] == "wrong" and "after 2 attempt" in row["note"]


def test_effort_retry_raises_once_per_failed_try_when_a_start_is_requeued(env, monkeypatch):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.jev = None
    monkeypatch.setattr(d, "_workdir_for", lambda t: (str(p.base), None))
    tiers = []

    def start(*a, **k):
        tiers.append(a[3])
        if len(tiers) == 1:
            raise OSError("no space left")
        return 0
    monkeypatch.setattr(d, "start_run", start)
    t = p.db.add_task("Look it up", "x", kind="work", tier="light", origin="coordinator", provider="claude")
    p.db.update_task(t, attempts=1, result=json.dumps({"status": "failed", "summary": "not found"}))
    d.dispatch()   # raised to standard, but the run never starts: no attempt is spent
    assert tiers == ["standard"] and p.db.task(t)["status"] == "queued" and p.db.task(t)["attempts"] == 1
    p.db.update_task(t, not_before=None)
    d.dispatch()
    assert tiers == ["standard", "standard"] and p.db.task(t)["tier"] == "standard"


def test_effort_falls_back_to_rules_and_leaves_other_tasks_alone(env, monkeypatch):
    p = make(env)
    from ttp import effort
    p.set_config("jev.uses", {"effort": "off"})
    cfg = p.config()
    jev = _EffortJev(2.0)
    q = p.db.add_task("Is the queue empty?", "Say yes or no.", kind="question", tier="standard", origin="coordinator")
    assert effort.pick(p.db, cfg, p.db.task(q), "claude", jev) == {"tier": "light", "by": "rules", "from": "standard",
                                                                 "review": False}
    assert jev.calls == 0 and not p.db.q("SELECT 1 FROM jev_calls")

    class Down(_EffortJev):
        def decide(self, *a, **k):
            raise OSError("down")
    p.set_config("jev.uses", {"effort": "on"})
    got = effort.pick(p.db, p.config(), p.db.task(q), "claude", Down(0))
    assert got["by"] == "rules" and got["jev_error"] == "OSError"
    # The user's tier, a deep or light pick by the coordinator, and reviews are kept as given.
    for kw in ({"origin": "user", "tier": "standard"}, {"origin": "coordinator", "tier": "deep"},
               {"origin": "coordinator", "tier": "light"}):
        t = p.db.add_task(f"Is it up? {kw}", "x", kind="question", **kw)
        assert effort.pick(p.db, cfg, p.db.task(t), "claude", jev) is None
    r = p.db.add_task("Review #1", "x", kind="review", tier="standard", origin="daemon")
    p.db.update_task(r, attempts=1, result=json.dumps({"status": "failed"}))
    assert effort.pick(p.db, cfg, p.db.task(r), "claude", jev) is None
    # A failed light try retries at standard; a task that continues a failed standard one starts at its
    # queued tier, and at deep only when that try handed off needs_deep.
    lt = p.db.add_task("Look it up", "x", kind="work", tier="light", origin="coordinator")
    p.db.update_task(lt, attempts=1, result=json.dumps({"status": "failed"}))
    assert effort.pick(p.db, cfg, p.db.task(lt), "claude", jev)["tier"] == "standard"
    old = p.db.add_task("Port it", "x", kind="code", tier="standard", origin="coordinator")
    p.db.update_task(old, status="failed")
    new = p.db.add_task("Port it again", "x", kind="code", tier="standard", origin="coordinator",
                        labels=[f"continues:{old}"])
    assert effort.pick(p.db, cfg, p.db.task(new), "claude", jev)["by"] != "retry"
    p.db.update_task(old, result=json.dumps({"status": "failed", "needs_deep": "needs a redesign"}))
    assert effort.pick(p.db, cfg, p.db.task(new), "claude", jev)["by"] == "retry"
    # A task that waited or was lost to the host is not retried deeper.
    w = p.db.add_task("Port more", "x", kind="code", tier="standard", origin="coordinator")
    p.db.update_task(w, attempts=1, result=json.dumps({"status": "lost"}))
    p.db.x("INSERT INTO runs(task,role,status) VALUES(?,'worker','lost')", (w,))
    assert effort.pick(p.db, cfg, p.db.task(w), "claude", jev) is None


def test_device_tasks_retry_at_standard_unless_a_run_hands_off_needs_deep(env, monkeypatch):
    p = make(env)
    from ttp import effort, machines
    monkeypatch.setattr(machines, "load", lambda: {"box1": {"tags": ["device", "x86"]}, "build1": {"tags": ["x86"]}})
    cfg = p.config()
    failed = {"status": "failed", "summary": "chip dropped mid-job"}
    deep_ask = {**failed, "needs_deep": "the hang reproduces without drops; needs a deeper look"}
    device_labels = (["resource:box1-device"], ["exclusive:lab-device"], ["needs_device"], ["resource:box1"])
    for labels in device_labels:
        t = p.db.add_task(f"Run the job {labels}", "x", kind="work", tier="standard", origin="coordinator",
                          labels=labels)
        assert effort.device_task(p.db.task(t))
        # A failed or hand-off-less standard try of a device task retries at standard.
        for result in (failed, {"status": "no_handoff"}, {**failed, "needs_deep": "  "}):
            p.db.update_task(t, attempts=1, result=json.dumps(result))
            assert effort.retry_tier(p.db, p.db.task(t)) is None
            assert effort.pick(p.db, cfg, p.db.task(t), "claude", None) is None
        # Its hand-off asks for deep: the retry runs deep.
        p.db.update_task(t, result=json.dumps(deep_ask))
        assert effort.pick(p.db, cfg, p.db.task(t), "claude", None) == {
            "tier": "deep", "from": "standard", "by": "retry", "review": False}
    # A failed light device try still goes up to standard: only deep is gated.
    lt = p.db.add_task("Check the box", "x", kind="work", tier="light", origin="coordinator",
                       labels=["resource:box1-device"])
    p.db.update_task(lt, attempts=1, result=json.dumps(failed))
    assert effort.retry_tier(p.db, p.db.task(lt)) == "standard"
    # Non-device tasks (no resource, a plain resource, a machine without the device tag) are unchanged.
    for labels in ([], ["resource:build1"], ["resource:lab-printer"], ["exclusive:unknown"]):
        t = p.db.add_task(f"Port it {labels}", "x", kind="code", tier="standard", origin="coordinator", labels=labels)
        assert not effort.device_task(p.db.task(t))
        p.db.update_task(t, attempts=1, result=json.dumps(failed))
        assert effort.retry_tier(p.db, p.db.task(t)) == "deep"
    # A device task that continues a failed standard one starts deep only when that one asked for it.
    old = p.db.add_task("Run it", "x", kind="work", tier="standard", origin="coordinator",
                        labels=["resource:box1-device"])
    p.db.update_task(old, status="failed", result=json.dumps(failed))
    new = p.db.add_task("Run it again", "x", kind="work", tier="standard", origin="coordinator",
                        labels=["resource:box1-device", f"continues:{old}"])
    assert effort.retry_tier(p.db, p.db.task(new)) is None
    p.db.update_task(old, result=json.dumps(deep_ask))
    assert effort.retry_tier(p.db, p.db.task(new)) == "deep"
    # An unreadable machines list never holds a task back: it is just not a device task.
    monkeypatch.setattr(machines, "load", lambda: (_ for _ in ()).throw(OSError("unreadable")))
    t = p.db.add_task("Run on box1", "x", kind="work", tier="standard", origin="coordinator", labels=["resource:box1"])
    assert not effort.device_task(p.db.task(t))


def test_coordinator_deep_device_tasks_start_at_standard_unless_asked_for_deep(env, monkeypatch):
    p = make(env)
    from ttp import effort
    from ttp.daemon import Daemon
    cfg = p.config()
    t = p.db.add_task("Profile the job", "x", kind="work", tier="deep", origin="coordinator",
                      labels=["resource:box1-device"])
    assert effort.pick(p.db, cfg, p.db.task(t), "claude", None) == {
        "tier": "standard", "from": "deep", "by": "device", "review": False}
    # The daemon starts it at standard and stores that on the task.
    d = Daemon(p.base)
    d.jev = None
    monkeypatch.setattr(d, "_workdir_for", lambda tk: (str(p.base), None))
    started = []
    monkeypatch.setattr(d, "start_run", lambda *a, **k: started.append(a[3]) or 0)
    d.dispatch()
    assert started == ["standard"] and p.db.task(t)["tier"] == "standard"
    # Kept at deep: the user asked for it, the user queued it, a non-device task, or a later start.
    old = p.db.add_task("Profile", "x", kind="work", tier="standard", origin="coordinator",
                        labels=["resource:box1-device"])
    p.db.update_task(old, status="failed", result=json.dumps({"status": "failed", "needs_deep": "a real hang"}))
    kept = [{"origin": "coordinator", "labels": ["resource:box1-device", effort.USER_DEEP]},
            {"origin": "user", "labels": ["resource:box1-device"]},
            {"origin": "coordinator", "labels": ["resource:build1"]},
            {"origin": "coordinator", "labels": ["resource:box1-device", f"continues:{old}"]}]
    for kw in kept:
        k = p.db.add_task(f"Profile {kw}", "x", kind="work", tier="deep", **kw)
        assert effort.pick(p.db, cfg, p.db.task(k), "claude", None) is None, kw
    later = p.db.add_task("Profile later", "x", kind="work", tier="deep", origin="coordinator",
                          labels=["resource:box1-device"])
    p.db.update_task(later, attempts=1, result=json.dumps({"status": "waiting"}))
    assert effort.pick(p.db, cfg, p.db.task(later), "claude", None) is None
    # task_add records the user's ask as a label, only on a deep task.
    from ttp import coordinator as co
    notes = co.apply(p, [
        {"type": "task_add", "title": "Hunt the hang", "spec": "x", "tier": "deep", "resources": ["box1-device"],
         "user_deep": True},
        {"type": "task_add", "title": "Run the sweep", "spec": "x", "tier": "standard", "resources": ["box1-device"],
         "user_deep": True}])
    assert not [n for n in notes if "rejected" in n], notes
    hunt = p.db.one("SELECT * FROM tasks WHERE title='Hunt the hang'")
    sweep = p.db.one("SELECT * FROM tasks WHERE title='Run the sweep'")
    assert effort.USER_DEEP in json.loads(hunt["labels"]) and effort.USER_DEEP not in json.loads(sweep["labels"])
    assert effort.pick(p.db, cfg, dict(hunt), "claude", None) is None


@pytest.mark.parametrize("text", [
    "Decide it yourself.", "your call", "That's up to you", "you decide", "Just do it", "use your judgement",
    "whatever you think is best", "No need to ask for this", "don’t ask me about restarts",
    "Stop asking for tickets", "don't get blocked on things you can fix", "always unblock efficiently",
    "you don't need my approval for that"])
def test_unblock_handback_phrases_match(env, text):
    from ttp import unblock
    assert unblock.handback(text)


@pytest.mark.parametrize("text", [
    "yes, approve the merge", "no, keep it as it is", "wait until the job ends", "I'll top up the account",
    "the decision is no", "ask the other team first"])
def test_unblock_ordinary_answers_are_not_handbacks(env, text):
    from ttp import unblock
    assert unblock.handback(text) is None


def test_unblock_answer_part_splits_a_message_by_the_asks_it_names(env):
    from ttp import unblock
    text = "#7: yes, merge it. #9, your call. See task #8 too."
    assert unblock.answer_part(text, 7, {7, 8, 9}).startswith("#7: yes") and "your call" not in \
        unblock.answer_part(text, 7, {7, 8, 9})
    assert "your call" in unblock.answer_part(text, 9, {7, 8, 9})
    assert unblock.answer_part(text, 8, {7, 8, 9}) is None   # "task #8" names a task
    assert unblock.answer_part("nothing here", 7, {7}) is None
    # The user-facing form "ask N" (and "ask #N") names an ask too.
    text = "Ask 7: yes. ask #9: your call."
    assert unblock.answer_part(text, 7, {7, 9}) == "Ask 7: yes. "
    assert unblock.answer_part(text, 9, {7, 9}).startswith("ask #9: your call")
    assert unblock.answer_part("I will ask 3 people", 7, {7}) is None


def _ask_db(env):
    p = make(env)
    p.db.x("DELETE FROM messages")   # the project's brief, posted as the user's first message
    now = time.time()

    def msg(direction, text, ago, kind="user", chat=None, ref=None, ext=None, context=None):
        return p.db.x("INSERT INTO messages(ts,direction,chat,kind,text,ref,ext_id,context) VALUES(?,?,?,?,?,?,?,?)",
                      (now - ago, direction, chat, kind, text, ref, ext, context))
    return p, now, msg


