def test_watcher_conditions_keep_one_issue_each_and_close_when_cleared(env):
    p = make(env)
    from ttp import screen as scr
    cfg = p.config()

    def see(text, sev="high"):
        return scr.screen(p.db, cfg, "watcher:hw", text, sev, rewake_after_s=6 * 3600)

    def issue(title_part):
        return p.db.one("SELECT * FROM issues WHERE title LIKE ?", (f"%{title_part}%",))

    first = see("broker box03 [abc1234 1.0.0]: hold x2 (device recovery x2); chip drop (chip 8,9,10); "
                "failed health checks x3")
    assert first.wake
    # The same conditions with new counts, chip numbers and version: the same three issues, no wake.
    again = see("broker box03 [def5678 1.0.1]: hold (device recovery); chip drop (chip 9); failed health checks x5")
    assert not again.wake and again.fingerprint == first.fingerprint
    rows = p.db.q("SELECT count, status FROM issues WHERE source='watcher:hw'")
    assert len(rows) == 3 and {(r["count"], r["status"]) for r in rows} == {(2, "open")}
    assert "x5" in issue("failed health checks")["title"]   # the title shows the latest sighting
    # Digits inside identifiers still tell subjects apart.
    assert see("broker box01 [abc1234 1.0.0]: chip drop (chip 1)").wake
    # "now X" opens, "cleared: X" closes the same issue without waking, and "still: X" is the same issue.
    assert see("broker box03 [def5678 1.0.1]: now unreachable over ssh").wake
    assert not see("broker box03 [def5678 1.0.1]: still: unreachable over ssh").wake
    gone = see("broker box03 [def5678 1.0.1]: cleared: unreachable over ssh")
    row = issue("unreachable over ssh")
    assert not gone.wake and row["status"] == "fixed" and row["cleared_why"] == scr.CLEARED_WHY and row["closed"]
    # A recurrence reopens it; it wakes only at or above the wake floor.
    assert not see("broker box03 [def5678 1.0.1]: now unreachable over ssh", "info").wake
    assert issue("unreachable over ssh")["status"] == "ignored"
    see("broker box03 [def5678 1.0.1]: cleared: unreachable over ssh")   # an ignored issue is left as it is
    assert issue("unreachable over ssh")["status"] == "ignored"
    # Kept quiet at info, then rated high by the watcher: wakes once, then is a known issue again.
    up = see("broker box03 [def5678 1.0.1]: still: unreachable over ssh")
    assert up.wake and up.reason == "now high" and issue("unreachable over ssh")["status"] == "open"
    assert not see("broker box03 [def5678 1.0.1]: still: unreachable over ssh").wake
    see("broker box03 [def5678 1.0.1]: cleared: unreachable over ssh")
    back = see("broker box03 [def5678 1.0.1]: now unreachable over ssh")
    assert back.wake and back.reason == "regressed after fix"
    assert len(p.db.q("SELECT id FROM issues WHERE source='watcher:hw'")) == 5
    assert not p.db.q("SELECT id FROM alerts") and not p.db.q("SELECT id FROM messages WHERE direction='out'")


def test_jev_out_of_funds_mid_line_falls_back_to_rules_in_one_pass_and_alerts(env):
    p = make(env)
    from ttp import daemon as dm
    from ttp.providers.jev import JevOutOfFunds

    class Broke(_FakeJev):
        def decide(self, state, questions, purpose="decide"):
            self.calls += 1
            raise JevOutOfFunds("no credits")

    d = dm.Daemon(p.base)
    d.cfg = p.config()
    d.jev = None
    d.observe("watcher:hw", "box-a: now link failed")
    d.observe("watcher:hw", "box-a: cleared: link failed")
    p.db.x("DELETE FROM events")
    d.jev = Broke(0.9, 2.0)
    # The fixed condition is reopened first; the new one then needs Jev, which is out of credits.
    d.observe("watcher:hw", "box-a: now link failed; fan noise")
    assert d.jev.calls == 1
    assert p.db.one("SELECT COUNT(*) AS n FROM events WHERE kind='observation'")["n"] == 1
    link = p.db.one("SELECT count, status FROM issues WHERE title LIKE '%link failed%'")
    assert link["count"] == 2 and link["status"] == "open"
    fan = p.db.one("SELECT count, screen FROM issues WHERE title LIKE '%fan noise%'")
    assert fan["count"] == 1 and json.loads(fan["screen"])["by"] == "rules"
    assert len(p.db.q("SELECT id FROM messages WHERE direction='out' AND ref='jev-funds'")) == 1


def test_watcher_issues_close_when_quiet_for_a_day_or_after_a_clean_run(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm
    from ttp import screen as scr
    out = {"stdout": ""}
    monkeypatch.setattr(dm.schedrun, "run_group", lambda cmd, **kw: subprocess.CompletedProcess(cmd, 0, out["stdout"], ""))
    d = dm.Daemon(p.base)
    cfg = p.config()

    def wakes():
        return p.db.one("SELECT COUNT(*) AS n FROM events WHERE kind='observation'")["n"]

    def status(source):
        return p.db.one("SELECT status, cleared_why FROM issues WHERE source=?", (source,))

    for src in ("watcher:old", "watcher:new", "log:app"):
        scr.screen(p.db, cfg, src, "box-a: power-cycle failed", "high")
    p.db.x("UPDATE issues SET last_seen=? WHERE source IN ('watcher:old', 'log:app')", (time.time() - 25 * 3600,))
    d.tick()
    assert status("watcher:old") == {"status": "fixed", "cleared_why": scr.QUIET_WHY}
    assert status("watcher:new")["status"] == "open" and status("log:app")["status"] == "open"
    # A run that reports nothing closes that watcher's open issues; a recurrence shows as a regression.
    out["stdout"] = json.dumps({"text": "box-a: power-cycle failed", "severity": "high"})
    d._run_command_watcher({"name": "hw"}, {"command": "x"})
    d._run_command_watcher({"name": "hw"}, {"command": "x"})
    assert wakes() == 1
    out["stdout"] = ""
    assert d._run_command_watcher({"name": "hw"}, {"command": "x"}) == "ok (0 observations)"
    assert status("watcher:hw") == {"status": "fixed", "cleared_why": scr.CLEAN_RUN_WHY}
    assert status("watcher:new")["status"] == "open"
    out["stdout"] = json.dumps({"text": "box-a: power-cycle failed", "severity": "high"})
    d._run_command_watcher({"name": "hw"}, {"command": "x"})
    assert wakes() == 2 and status("watcher:hw") == {"status": "open", "cleared_why": None}
    assert p.db.one("SELECT text FROM events WHERE kind='observation' ORDER BY id DESC")["text"].startswith("box-a")
    assert not p.db.q("SELECT id FROM alerts")


def test_keyed_issue_a_quiet_run_closed_only_counts_when_resent_within_the_window(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm
    from ttp import screen as scr
    out = {"stdout": ""}
    monkeypatch.setattr(dm.schedrun, "run_group", lambda cmd, **kw: subprocess.CompletedProcess(cmd, 0, out["stdout"], ""))
    d = dm.Daemon(p.base)

    def line(text, severity, key="gate"):
        return json.dumps({"text": text, "severity": severity, "key": key})

    def wakes():
        return p.db.one("SELECT COUNT(*) AS n FROM events WHERE kind='observation'")["n"]

    def issue(key="gate"):
        return p.db.one("SELECT id, status, count, severity, cleared_why FROM issues WHERE fingerprint=?",
                        (scr.key_fingerprint("watcher:hw", key),))

    def run(stdout):
        out["stdout"] = stdout
        d._run_command_watcher({"name": "hw"}, {"command": "x"})

    run(line("fleet gate: closed for 0.5h", "critical"))
    assert wakes() == 1
    first = issue()["id"]
    # A wake that re-sends the known line after a quiet run closed it: counted, still closed, no wake.
    for n in range(5):
        run("")
        run(line(f"fleet gate: closed for {n + 1}.5h", "critical"))
    assert wakes() == 1
    i = issue()
    assert i["id"] == first and i["count"] == 6 and i["status"] == "fixed"
    assert i["cleared_why"] == scr.CLEAN_RUN_WHY and len(p.db.q("SELECT id FROM issues")) == 1
    # A lower severity is the same story; a higher one reopens and wakes.
    run(line("fleet gate: closed", "high", key="lower"))
    run("")
    run(line("fleet gate: closed", "normal", key="lower"))
    assert wakes() == 2 and issue("lower")["status"] == "fixed"
    run(line("fleet gate: closed", "critical", key="lower"))
    assert wakes() == 3 and issue("lower")["status"] == "open" and issue("lower")["severity"] == "critical"
    # Past the window it reopens and wakes as before.
    p.db.x("UPDATE issues SET closed=? WHERE id=?", (time.time() - 7 * 3600, first))
    run(line("fleet gate: closed for 9h", "critical"))
    assert wakes() == 4 and issue()["status"] == "open"
    # Only a quiet run's close counts: a cleared or a 24 h-quiet close reopens and wakes at once.
    for why in (scr.CLEARED_WHY, scr.QUIET_WHY):
        p.db.x("UPDATE issues SET status='fixed', closed=?, cleared_why=? WHERE id=?", (time.time(), why, first))
        before = wakes()
        run(line("fleet gate: closed", "critical"))
        assert wakes() == before + 1 and issue()["status"] == "open"
    # A "repeat": true line wakes on every occurrence, also within the window.
    rep = json.dumps({"text": "fleet gate: tripped", "severity": "high", "key": "rep", "repeat": True})
    run(rep)
    run("")
    before = wakes()
    run(rep)
    assert wakes() == before + 1 and issue("rep")["status"] == "open"
    # Lines without a key keep the old rule: a recurrence after a quiet run wakes.
    run(json.dumps({"text": "box-b: fan failed", "severity": "high"}))
    run("")
    before = wakes()
    run(json.dumps({"text": "box-b: fan failed", "severity": "high"}))
    assert wakes() == before + 1
    # Off (0 or null) restores the old rule for keyed lines too.
    for off in (0, None):
        d.cfg["screen"]["reraise_window_h"] = off
        run("")
        before = wakes()
        run(line("fleet gate: closed", "critical"))
        assert wakes() == before + 1


def test_keyed_watcher_error_a_run_repaired_only_counts_when_resent_within_the_window(env, monkeypatch):
    """A keyed "error": true line a successful run repaired, sent again within screen.reraise_window_h at
    the same or a lower severity, stays closed: no 'regressed after fix', no wake, no reopen churn. A
    higher severity, a re-raise past the window and a repaired non-error keyed issue reopen as before."""
    p = make(env)
    from ttp import daemon as dm
    from ttp import screen as scr
    from ttp import watchdup
    out = {"stdout": ""}
    monkeypatch.setattr(dm.schedrun, "run_group", lambda cmd, **kw: subprocess.CompletedProcess(cmd, 0, out["stdout"], ""))
    d = dm.Daemon(p.base)

    def line(text, severity, key="tunnel", error=True):
        return json.dumps({"text": text, "severity": severity, "key": key, **({"error": True} if error else {})})

    def wakes():
        return p.db.one("SELECT COUNT(*) AS n FROM events WHERE kind='observation'")["n"]

    def issue(key="tunnel", source="watcher-error:hw"):
        return p.db.one("SELECT * FROM issues WHERE fingerprint=?", (scr.key_fingerprint(source, key),))

    def opens(source="watcher-error:hw"):   # what same_subject_warn counts for the source
        return sum(len(keys) for _s, _k, keys in watchdup.groups(p.db, source, time.time()))

    def regressed(row):
        return [h for h in json.loads(row["history"] or "[]") if h.get("why") == "regressed after fix"]

    def run(stdout):
        out["stdout"] = stdout
        d._run_command_watcher({"name": "hw"}, {"command": "x"})

    run(line("tunnel to host-a: down", "high"))
    assert wakes() == 1 and issue()["status"] == "open" and opens() == 1
    first = issue()["id"]
    # (a) Repaired, then back at the same severity within the window, several times: counted only.
    for _ in range(3):
        run("")
        assert issue()["cleared_why"] == scr.REPAIRED_WHY
        run(line("tunnel to host-a: down", "high"))
    row = issue()
    assert wakes() == 1 and row["id"] == first and row["status"] == "fixed" and row["count"] == 4
    assert regressed(row) == [] and opens() == 1
    # (b) Back at a lower severity: the same.
    run(line("tunnel to host-a: down", "normal"))
    assert wakes() == 1 and issue()["status"] == "fixed" and issue()["severity"] == "high" and opens() == 1
    # (c) Back at a higher severity: reopens as a regression and wakes.
    run(line("tunnel to host-a: down", "critical"))
    row = issue()
    assert wakes() == 2 and row["status"] == "open" and row["severity"] == "critical"
    assert len(regressed(row)) == 1 and opens() == 2
    # (d) Repaired, then back past the window: reopens as before.
    run("")
    assert issue()["cleared_why"] == scr.REPAIRED_WHY
    p.db.x("UPDATE issues SET closed=? WHERE id=?", (time.time() - 7 * 3600, first))
    run(line("tunnel to host-a: down", "critical"))
    assert wakes() == 3 and issue()["status"] == "open" and len(regressed(issue())) == 2 and opens() == 3
    # Off (0) restores the old rule for repaired errors too.
    d.cfg["screen"]["reraise_window_h"] = 0
    run("")
    run(line("tunnel to host-a: down", "critical"))
    assert wakes() == 4 and issue()["status"] == "open"
    d.cfg["screen"]["reraise_window_h"] = 6
    # (e) A keyed report (not an error) closed as repaired keeps today's rule: it reopens as regressed.
    run(line("box-a: link down", "high", key="link", error=False))
    assert wakes() == 5
    p.db.x("UPDATE issues SET status='fixed', closed=?, cleared_why=? WHERE source='watcher:hw'",
           (time.time(), scr.REPAIRED_WHY))
    run(line("box-a: link down", "high", key="link", error=False))
    row = issue("link", "watcher:hw")
    assert wakes() == 6 and row["status"] == "open" and len(regressed(row)) == 1
    # A keyed error closed for another reason (cleared, 24 h quiet) also reopens at once, as before.
    for why in (scr.CLEARED_WHY, scr.QUIET_WHY):
        p.db.x("UPDATE issues SET status='fixed', closed=?, cleared_why=? WHERE id=?", (time.time(), why, first))
        before = wakes()
        run(line("tunnel to host-a: down", "critical"))
        assert wakes() == before + 1 and issue()["status"] == "open"


def test_keyed_issue_new_episode_supersedes_the_old_issue_and_wakes_once(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm
    from ttp import screen as scr
    out = {"stdout": ""}
    monkeypatch.setattr(dm.schedrun, "run_group", lambda cmd, **kw: subprocess.CompletedProcess(cmd, 0, out["stdout"], ""))
    d = dm.Daemon(p.base)

    def line(text, episode=None, key="gate", severity="high"):
        obs = {"text": text, "severity": severity, "key": key}
        return json.dumps(obs if episode is None else {**obs, "episode": episode})

    def wakes():
        return p.db.one("SELECT COUNT(*) AS n FROM events WHERE kind='observation'")["n"]

    def issues(key="gate"):
        fp = scr.key_fingerprint("watcher:hw", key)
        return p.db.q("SELECT id, fingerprint, status, count, cleared_why, episode FROM issues "
                      "WHERE fingerprint=? OR fingerprint LIKE ? ORDER BY id", (fp, fp + "~%"))

    def run(stdout):
        out["stdout"] = stdout
        d._run_command_watcher({"name": "hw"}, {"command": "x"})

    # (1) The same key and episode: one issue, one wake, whatever the text says.
    run(line("box-a: link down", "e1"))
    run(line("box-a: link down for 2h", "e1"))
    assert wakes() == 1 and [(i["count"], i["episode"], i["status"]) for i in issues()] == [(2, "e1", "open")]
    # (2) A new episode closes the old issue, opens a new one and wakes once.
    run(line("box-a: link down", "e2"))
    run(line("box-a: link down again", "e2"))
    assert wakes() == 2
    old, new = issues()
    assert old["status"] == "fixed" and old["cleared_why"] == scr.SUPERSEDED_WHY and old["episode"] == "e1"
    assert new["fingerprint"] == scr.key_fingerprint("watcher:hw", "gate")
    assert (new["status"], new["episode"], new["count"]) == ("open", "e2", 2)
    # A recently closed issue (a quiet run within the reraise window) and a new episode: no dedupe.
    run("")
    assert issues()[-1]["cleared_why"] == scr.CLEAN_RUN_WHY
    run(line("box-a: link down", "e2"))
    assert wakes() == 2 and issues()[-1]["status"] == "fixed"   # same episode: today's dedupe
    run(line("box-a: link down", "e3"))
    assert wakes() == 3 and [i["status"] for i in issues()] == ["fixed", "fixed", "open"]
    assert issues()[1]["cleared_why"] == scr.SUPERSEDED_WHY
    # (3) No episode keeps today's behaviour: the open issue absorbs the line, no wake, no new issue.
    run(line("box-a: link down, other reason"))
    assert wakes() == 3 and len(issues()) == 3 and issues()[-1]["episode"] == "e3"
    # An issue opened without an episode adopts the first one it sees instead of being superseded.
    run(line("box-b: fan slow", key="fan"))
    run(line("box-b: fan slow", "f1", key="fan"))
    assert wakes() == 4 and [(i["episode"], i["status"]) for i in issues("fan")] == [("f1", "open")]
    # (4) An active mute still suppresses the new episode's wake; its issue opens all the same.
    scr.mute(p.db, "watcher:hw", "box-a", 2, why="planned work")
    run(line("box-a: link down", "e4"))
    assert wakes() == 4 and [i["status"] for i in issues()][-2:] == ["fixed", "open"]
    assert issues()[-1]["episode"] == "e4"


def test_migration_closes_old_watcher_issues_once(env, tmp_path):
    import sqlite3
    from ttp.db import DB, WATCHER_ISSUES_MIGRATION
    path = tmp_path / "old.db"
    c = sqlite3.connect(str(path))
    c.execute("CREATE TABLE issues (id INTEGER PRIMARY KEY AUTOINCREMENT, fingerprint TEXT UNIQUE, source TEXT, "
              "first_seen REAL, last_seen REAL, count INTEGER DEFAULT 1, title TEXT, severity TEXT DEFAULT "
              "'normal', status TEXT DEFAULT 'open', task INTEGER, screen TEXT)")
    for i, (src, st) in enumerate([("watcher:hw", "open"), ("watcher:hw", "open"), ("watcher:hw", "ignored"),
                                   ("log:app", "open")]):
        c.execute("INSERT INTO issues(fingerprint, source, title, status, first_seen) VALUES(?,?,?,?,?)",
                  (f"f{i}", src, "t", st, 100.0 + i))
    c.commit()
    c.close()
    db = DB(path)
    rows = db.q("SELECT source, status, cleared_why, opened FROM issues ORDER BY id")
    assert [r["opened"] for r in rows] == [100.0, 101.0, 102.0, 103.0]   # open stretches start at first_seen
    assert [r["status"] for r in rows] == ["fixed", "fixed", "ignored", "open"]
    assert rows[0]["cleared_why"] and rows[3]["cleared_why"] is None and db.meta(WATCHER_ISSUES_MIGRATION)
    db.x("UPDATE issues SET status='open' WHERE id=1")
    db.close()
    assert DB(path).one("SELECT status FROM issues WHERE id=1")["status"] == "open"   # runs once


def test_the_push_queue_tables_are_added_to_an_existing_project_db_once(env, tmp_path):
    from ttp.db import DB, PUSH_QUEUE_MIGRATION
    path = tmp_path / "old.db"
    db = DB(path)
    tid = db.add_task("older work", "s", kind="review", status="review")
    db.x("DROP TABLE push_queue")   # a project.db from before the push queue
    db.x("DROP TABLE push_batches")
    db.x("DELETE FROM meta WHERE key=?", (PUSH_QUEUE_MIGRATION,))
    db.close()
    db = DB(path)
    assert db.meta(PUSH_QUEUE_MIGRATION) and db.task(tid)["status"] == "review"
    db.x("INSERT INTO push_queue(task,branch,head,target,created,updated) VALUES(?,?,?,?,?,?)",
         (tid, "b", "ab" * 20, "origin/proj", 1.0, 1.0))
    db.x("INSERT INTO push_batches(id,marker,target,started) VALUES('b1','m','origin/proj',1.0)")
    db.close()
    db = DB(path)
    assert db.one("SELECT status, tries FROM push_queue") == {"status": "approved", "tries": 0}
    assert db.one("SELECT after_tries FROM push_batches")["after_tries"] == 0


def test_no_mute_outlasts_its_cap_however_often_it_is_extended(env):
    p = make(env)
    from ttp import screen as scr
    t0 = time.time()
    scr.mute(p.db, "watcher:hw", "dropped", 72, now=t0)
    at = t0
    for _ in range(3):   # 72 h extensions on days 0-6
        at += 2 * 86400
        m = scr.mute(p.db, "watcher:hw", "dropped", 72, now=at)
    assert m["since"] == t0 and m["until"] == t0 + scr.MUTE_CAP_S and m["capped"]
    with pytest.raises(ValueError, match="7 days"):
        scr.mute(p.db, "watcher:hw", "dropped", 72, now=t0 + scr.MUTE_CAP_S - 30)
    [done] = scr.expire_mutes(p.db, now=t0 + scr.MUTE_CAP_S + 1)
    [ended] = [e["text"] for e in p.db.q("SELECT text FROM events WHERE kind='observation'")]
    assert ended.startswith("mute ended") and "for 168 h" in ended and "7-day cap" in ended, ended
    # Over, a new mute starts a new clock; one ended by its time alone says nothing of a cap.
    m = scr.mute(p.db, "watcher:hw", "dropped", 2, now=t0 + scr.MUTE_CAP_S + 2)
    assert m["since"] == t0 + scr.MUTE_CAP_S + 2 and not m["capped"]
    scr.expire_mutes(p.db, now=m["until"] + 1)
    assert "cap" not in p.db.q("SELECT text FROM events WHERE kind='observation' ORDER BY id")[-1]["text"]


def test_ttp_mute_end_ends_a_mute_without_a_turn_and_records_who(env, capsys, monkeypatch):
    from ttp import cli
    from ttp import screen as scr
    p = make(env)
    scr.mute(p.db, "watcher:hw", "tray dropped", 24)
    scr.count_muted(p.db, "watcher:hw", "box-a: tray dropped", "high")
    cli.main(["mute", "list", "demo"])
    assert "watcher:hw 'tray dropped'" in capsys.readouterr().out
    for var in ("TTP_RUN_DIR", "TTP_TASK", "TTP_PROJECT"):
        monkeypatch.delenv(var, raising=False)
    cli.main(["mute", "end", "demo", "WATCHER:hw", "Tray Dropped"])   # any case, as a mute matches
    assert "ended the mute" in capsys.readouterr().out and scr.mutes(p.db) == []
    ev = p.db.q("SELECT text, status FROM events WHERE kind='observation' AND text LIKE 'mute ended:%'")
    assert len(ev) == 1 and ev[0]["status"] == "queued" and "ended by the user" in ev[0]["text"], ev
    assert "1 observation" in ev[0]["text"]
    with pytest.raises(SystemExit) as e:   # nothing left to end
        cli.main(["mute", "end", "demo", "watcher:hw", "tray dropped"])
    assert e.value.code == 2 and "no active mute" in capsys.readouterr().err
    # A run ends only its own project's mutes, and is named as who ended it.
    scr.mute(p.db, "watcher:hw", "tray dropped", 24)
    monkeypatch.setenv("TTP_RUN_DIR", str(p.base / "state" / "runs" / "9"))
    monkeypatch.setenv("TTP_TASK", "7")
    monkeypatch.setenv("TTP_PROJECT", str(env["repo"] / "elsewhere"))   # another project's run
    with pytest.raises(SystemExit):
        cli.main(["mute", "end", "demo", "watcher:hw", "tray dropped"])
    assert "only its own project" in capsys.readouterr().err and len(scr.mutes(p.db)) == 1
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    cli.main(["mute", "end", "demo", "watcher:hw", "tray dropped"])
    assert p.db.q("SELECT id FROM events WHERE text LIKE '%ended by task #7%'")


def _muted_watcher(env, monkeypatch, first):
    """A command watcher `hw` reporting `first`, muted on 'held' for 24 h: (run(at_h, stdout), asks(), p)."""
    p = make(env)
    from ttp import coordinator as coord
    from ttp import daemon as dm
    from ttp import screen as scr
    clock = {"t": 1_800_000_000.0}
    t0 = clock["t"]
    monkeypatch.setattr(scr.time, "time", lambda: clock["t"])
    out = {"stdout": ""}
    monkeypatch.setattr(dm.schedrun, "run_group", lambda cmd, **kw: subprocess.CompletedProcess(cmd, 0, out["stdout"], ""))
    d = dm.Daemon(p.base)

    def run(at_h, stdout):
        clock["t"], out["stdout"] = t0 + at_h * 3600, stdout
        d._run_command_watcher({"name": "hw"}, {"command": "x"})

    run(0, first)
    assert coord.apply(p, [{"type": "observation_mute", "source": "watcher:hw", "match": "held",
                            "hours": 24, "why": "known"}]) == []

    def asks():
        return [(e["ts"] - t0) / 3600 for e in p.db.q("SELECT ts FROM events WHERE text LIKE ? ORDER BY id",
                                                       (f"%{scr.MUTE_PERSISTS}%",))]
    return run, asks, p


def test_mute_clock_clears_on_a_clean_watcher_run_and_re_arms(env, monkeypatch):
    held = json.dumps({"text": "box-a: held by the broker", "severity": "high", "repeat": True})
    run, asks, _ = _muted_watcher(env, monkeypatch, held)
    for h in (0.5, 1, 1.5, 2, 2.5):
        run(h, held)
    assert asks() == [1.0], "a hold mute asks after its cap (1 h), not the 2 h default"
    run(3, "")   # a clean run: the daemon counts it as cleared
    for h in (3.5, 4, 4.5, 5, 5.5, 6, 6.5):
        run(h, held)   # back from 3.5 h and held for 3 h
    assert asks() == [1.0, 4.5], asks()


def test_mute_clock_restarts_after_clean_runs(env, monkeypatch):
    held = json.dumps({"text": "box-a: held by the broker", "severity": "high", "repeat": True})
    run, asks, _ = _muted_watcher(env, monkeypatch, held)
    run(0.5, held)
    run(1, "")
    run(1.5, "")
    run(2, held)   # back: 0 h old, not 2 h
    assert asks() == []
    run(2.5, held)
    assert asks() == []
    run(3, held)
    assert asks() == [3.0], asks()


def test_mute_clock_clears_only_the_condition_a_run_dropped(env, monkeypatch):
    from ttp import screen as scr
    both = json.dumps({"text": "boxes: box-a held; box-b held", "severity": "high", "repeat": True})
    only_b = json.dumps({"text": "boxes: box-b held", "severity": "high", "repeat": True})
    run, asks, p = _muted_watcher(env, monkeypatch, both)
    run(0.5, both)
    run(1, only_b)   # box-a cleared, box-b still held

    def conds():
        [m] = scr.mutes(p.db, now=0)
        return {c["text"]: c for c in m["conds"].values()}
    c = conds()
    assert c["boxes: box-a held"]["first_at"] is None
    assert c["boxes: box-b held"]["first_at"] is not None
    assert asks() == [1.0] and "box-b" in p.db.one("SELECT text FROM events WHERE text LIKE ?",
                                                     (f"%{scr.MUTE_PERSISTS}%",))["text"]
    run(1.5, both)   # box-a back: a new clock
    run(2, both)
    assert asks() == [1.0]
    run(2.5, both)
    assert asks() == [1.0, 2.5], asks()


