def _open_issue(db, title, *, first, last, severity="high", status="open"):
    return db.x("INSERT INTO issues(fingerprint,source,first_seen,last_seen,count,title,severity,status) "
                "VALUES(?,?,?,?,2,?,?,?)", (f"fp-{title}", "watch", first, last, title, severity, status))


def test_high_conditions_reach_the_chat_model_free_only_while_the_coordinator_cannot_run(env, monkeypatch):
    p = make(env)
    from ttp.daemon import Daemon
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    start = time.time()
    clock = {"t": start}
    monkeypatch.setattr(time, "time", lambda: clock["t"])
    d = Daemon(p.base)
    told = lambda: [m["text"] for m in p.db.unread_for_chat("c1", 0)]
    p.db.x("INSERT INTO runs(role,status,started,ended) VALUES('coordinator','ok',?,?)", (start - 5 * 3600,) * 2)
    _open_issue(p.db, "box-a is down", first=start - 3 * 3600, last=start)
    _open_issue(p.db, "seen once an hour ago", first=start - 3600, last=start - 3600)
    _open_issue(p.db, "known before the last turn", first=start - 6 * 3600, last=start)
    _open_issue(p.db, "only normal", first=start - 3 * 3600, last=start, severity="normal")
    _open_issue(p.db, "already fixed", first=start - 3 * 3600, last=start, status="fixed")
    d.relay_when_blocked()
    clock["t"] = start + 3600
    d.relay_when_blocked()
    assert told() == [], "relayed while the coordinator could run"
    # Its turns keep failing: after 30 min the persistent new high condition goes to the chat.
    p.db.set_kv("coordinator_failures", 3)
    d.relay_when_blocked()
    clock["t"] = start + 3600 + 1700
    d.relay_when_blocked()
    assert told() == []
    clock["t"] = start + 3600 + 1900
    d.relay_when_blocked()
    assert len(told()) == 1
    assert "The coordinator cannot run (its last 3 turns failed" in told()[0]
    assert "\n- high: box-a is down (seen for 3.0 h, watch)" in told()[0]
    assert all(x not in told()[0] for x in ("seen once", "known before", "only normal", "already fixed"))
    # Rate limit: a new condition waits for the hour; the one already told is not repeated.
    _open_issue(p.db, "box-b is down", first=start, last=start + 3 * 3600, severity="critical")
    clock["t"] = start + 3600 + 1900 + 1800
    d.relay_when_blocked()
    assert len(told()) == 1, "two relays within the hour"
    clock["t"] = start + 3600 + 1900 + 3601
    d.relay_when_blocked()
    assert len(told()) == 2 and "critical: box-b is down" in told()[1] and "box-a" not in told()[1]
    assert p.db.q("SELECT severity FROM messages WHERE id=(SELECT MAX(id) FROM messages)")[0]["severity"] == "critical"
    # Once the condition clears, its relayed alert leaves the top section.
    from ttp.web import attention
    assert any("box-b" in m["text"] for m in attention(p.db, time.time()))
    p.db.x("UPDATE issues SET status='fixed' WHERE title='box-b is down'")
    assert not any("box-b" in m["text"] for m in attention(p.db, time.time()))
    # The coordinator runs again: nothing more is relayed.
    p.db.set_kv("coordinator_failures", 0)
    d.relay_when_blocked()
    assert p.db.kv("coordinator_blocked") is None
    _open_issue(p.db, "box-c is down", first=start + 3600, last=start + 9 * 3600)
    clock["t"] = start + 10 * 3600
    d.relay_when_blocked()
    assert len(told()) == 2


def test_a_condition_back_during_the_block_is_relayed_after_two_hours_of_its_new_stretch(env, monkeypatch):
    p = make(env)
    from ttp.daemon import Daemon
    from ttp.screen import _issue
    from ttp import alerts
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    start = time.time()
    clock = {"t": start}
    monkeypatch.setattr(time, "time", lambda: clock["t"])
    d = Daemon(p.base)
    told = lambda: [m["text"] for m in p.db.unread_for_chat("c1", 0)]
    seen = lambda fp, at: _issue(p.db, fp, "watch", fp, None, "high", lambda: ("high", "rule", "new", {}), 2,
                                 at, None, False)
    p.db.x("INSERT INTO runs(role,status,started,ended) VALUES('coordinator','ok',?,?)", (start - 3600,) * 2)
    # Seen 48 h ago (and after the last good turn), fixed since.
    old = _open_issue(p.db, "box-a is down", first=start - 48 * 3600, last=start - 47 * 3600, status="fixed")
    late = _open_issue(p.db, "box-b is down", first=start - 1800, last=start - 1700, status="fixed")
    p.db.x("UPDATE issues SET opened=first_seen")
    p.db.set_kv("coordinator_failures", 3)
    d.relay_when_blocked()
    # 3 h into the block box-a is down again; box-b too, 10 min before the next check.
    clock["t"] = start + 3 * 3600
    seen("fp-box-a is down", clock["t"])
    assert p.db.one("SELECT opened FROM issues WHERE id=?", (old,))["opened"] == clock["t"]
    clock["t"] = start + 5 * 3600 - 600
    seen("fp-box-b is down", clock["t"])
    clock["t"] = start + 5 * 3600
    seen("fp-box-a is down", clock["t"])
    seen("fp-box-b is down", clock["t"])
    d.relay_when_blocked()
    assert len(told()) == 1
    assert "\n- high: box-a is down (seen for 2.0 h, watch)" in told()[0]
    assert "box-b" not in told()[0], "a regressed condition was relayed without 2 h of its new stretch"
    clock["t"] = start + 6 * 3600 + 1
    seen("fp-box-a is down", clock["t"])
    d.relay_when_blocked()
    assert len(told()) == 1, "box-a was told twice in one stretch, or box-b before 2 h"
    # box-a recovers, then is down again: its old alert does not stand for the new stretch, and the
    # new stretch is relayed on its own once it has lasted 2 h.
    first = p.db.one("SELECT ref, ts FROM messages WHERE ref LIKE 'relayed:%'")
    p.db.x("UPDATE issues SET status='fixed' WHERE id=?", (old,))
    clock["t"] = start + 7 * 3600
    seen("fp-box-a is down", clock["t"])
    assert not alerts.holds(p.db, first["ref"], first["ts"], clock["t"])
    clock["t"] = start + 9 * 3600 + 1
    seen("fp-box-a is down", clock["t"])
    seen("fp-box-b is down", clock["t"])
    d.relay_when_blocked()
    assert len(told()) == 2 and "box-a is down (seen for 2.0 h" in told()[1] and "box-b is down" in told()[1]
    assert late


def test_one_listener_per_chat(env):
    """The newest listener wins, and a listener whose starter is gone exits by itself. The replaced
    one says so and exits LISTEN_REPLACED; any other SIGTERM still ends a listener as before."""
    from ttp import cli
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost")
    lock = p.state / "listen-c1.pid"
    cmd = [sys.executable, str(TTP), "listen", "demo", "--chat", "c1", "--timeout", "60"]
    first = subprocess.Popen(cmd, env=run_env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    try:
        deadline = time.time() + 15
        while time.time() < deadline and not lock.exists():
            time.sleep(0.05)
        assert lock.exists(), "the first listener never took the chat"
        second = subprocess.Popen(cmd, env=run_env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        try:
            first.wait(timeout=15)
            deadline = time.time() + 10     # the new listener writes its id just after the old one dies
            while time.time() < deadline and lock.exists() and lock.read_text().strip() != str(second.pid):
                time.sleep(0.05)
            assert lock.read_text().strip() == str(second.pid), "the newest listener does not own the chat"
            p.db.post("out", "hello", chat="c1", kind="reply")
            out = ""
            deadline = time.time() + 15
            while time.time() < deadline and "hello" not in out:
                time.sleep(0.05)
                out = p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] and "hello" or ""
            assert out == "hello", "the newest listener did not receive the message"
            err = first.stderr.read()
            assert first.returncode == cli.LISTEN_REPLACED and cli.REPLACED_MARK in err, (first.returncode, err)
            second.terminate()      # nobody claimed the chat: a plain SIGTERM, not a replacement
            second.wait(timeout=10)
            assert second.returncode == -signal.SIGTERM and cli.REPLACED_MARK not in second.stderr.read()
        finally:
            if second.poll() is None:
                second.terminate()
                second.wait(timeout=10)
    finally:
        if first.poll() is None:
            first.terminate()
            first.wait(timeout=10)
    # A listener whose parent dies (a lost background task, a dropped ssh session) exits on its own.
    starter = subprocess.run(["/bin/sh", "-c", " ".join(shlex.quote(x) for x in cmd) + " >/dev/null 2>&1 & echo $!; sleep 1"],
                             env=run_env, capture_output=True, text=True, timeout=30)
    orphan = int(starter.stdout.split()[0])
    deadline = time.time() + 15
    while time.time() < deadline:
        try:
            os.kill(orphan, 0)
        except OSError:
            break
        time.sleep(0.05)
    else:
        os.kill(orphan, 15)
        raise AssertionError("an orphaned listener kept running")


def test_newest_listener_claims_chat_before_old_one_exits(env):
    """The lock names the newest listener at once, even while an older one is slow to exit."""
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost")
    lock = p.state / "listen-c1.pid"
    release = env["home"] / "release-old-listener"
    seen = env["home"] / "lock-at-sigterm"
    # Stands in for an older listener that is slow to shut down: when SIGTERM arrives it records
    # what the lock names, then exits only once the test creates the release file, so it is still
    # shutting down however slow the machine is.
    slow = ("import os,signal,sys,time\n"
            "def stop(*a):\n"
            f"    open({str(seen)!r}, 'w').write(open({str(lock)!r}).read())\n"
            "    end = time.time() + 60\n"
            f"    while not os.path.exists({str(release)!r}) and time.time() < end:\n"
            "        time.sleep(0.05)\n"
            "    sys.exit(0)\n"
            "signal.signal(signal.SIGTERM, stop)\n"
            "print('ready', flush=True)\n"
            "time.sleep(120)\n")
    old = subprocess.Popen([sys.executable, "-c", slow, "listen", "c1"], stdout=subprocess.PIPE, text=True)
    new = None
    try:
        assert old.stdout.readline().strip() == "ready"
        lock.write_text(str(old.pid))
        new = subprocess.Popen([sys.executable, str(TTP), "listen", "demo", "--chat", "c1", "--timeout", "60"],
                               env=run_env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        # Generous: under load the new listener's interpreter start alone can take seconds.
        deadline = time.time() + 30
        while time.time() < deadline and lock.read_text().strip() != str(new.pid) and new.poll() is None:
            time.sleep(0.05)
        assert lock.read_text().strip() == str(new.pid), "the lock still names the older listener"
        assert old.poll() is None, "test premise: the older listener is still shutting down"
        release.touch()
        # It exits only through its SIGTERM handler, so this also shows the new listener stopped it.
        old.wait(timeout=30)
        assert lock.read_text().strip() == str(new.pid)
        # Ordering, not timing: the lock already named the new listener when the old one was told to stop.
        assert seen.read_text().strip() == str(new.pid), "the older listener was stopped before the claim"
    finally:
        for proc in (new, old):
            if proc and proc.poll() is None:
                proc.kill()
                proc.wait(timeout=10)


def test_process_checks_read_the_whole_command_line_under_a_narrow_terminal(env, monkeypatch):
    """`ps -o command=` cuts at $COLUMNS (80 under pytest-xdist, or a narrow terminal), so a long
    path hid 'listen' or 'daemon': an older listener was never replaced, a live daemon looked dead."""
    from ttp import cli, daemon
    monkeypatch.setenv("COLUMNS", "40")
    pad = "x" * 200
    child = subprocess.Popen([sys.executable, "-c", "import time; time.sleep(60)", pad,
                              "ttp", "listen", "demo", "--chat", "c1", "daemon"])
    try:
        assert cli._listener_alive(child.pid, "c1"), "the listener check read a cut command line"
        assert daemon._is_daemon(child.pid), "the daemon check read a cut command line"
    finally:
        child.kill()
        child.wait()


def test_listener_does_not_skip_a_reply_posted_between_its_reads(env, capsys):
    """A reply that lands after the unread query but before the high-water read is still shown."""
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    from types import SimpleNamespace
    from ttp.cli import _listen_loop
    db, real, posted = p.db, p.db.unread_for_chat, []

    def racy(*args, **kw):
        rows = real(*args, **kw)
        if not posted:
            posted.append(db.post("out", "late reply", chat="c1", kind="reply"))
        return rows
    db.unread_for_chat = racy
    _listen_loop(p, db, SimpleNamespace(chat="c1", timeout=3, once=True, ack=None), 0, "normal")
    assert "late reply" in capsys.readouterr().out, "the listener skipped a reply posted between its reads"


def test_listener_redelivers_until_acknowledged(env):
    """A listener killed after printing leaves the message unread; `--ack` is what marks it read."""
    import select
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost")
    cmd = [sys.executable, str(TTP), "listen", "demo", "--chat", "c1"]
    mid = p.db.post("out", "important", chat="c1", kind="reply")
    first = subprocess.Popen(cmd + ["--ack", "0", "--timeout", "60"], env=run_env, stdout=subprocess.PIPE,
                             stderr=subprocess.PIPE, text=True)
    try:
        ready, _, _ = select.select([first.stdout], [], [], 15)
        assert ready, "the listener printed nothing"
        line = first.stdout.readline()
        assert "important" in line and f"#{mid}" in line, line
    finally:
        first.kill()
        first.wait(timeout=10)
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == 0
    again = subprocess.run(cmd + ["--once", "--ack", "0", "--timeout", "5"], env=run_env,
                           capture_output=True, text=True, timeout=30)
    assert "important" in again.stdout, "an unacknowledged message was not delivered again"
    done = subprocess.run(cmd + ["--once", "--ack", str(mid), "--timeout", "0.3"], env=run_env,
                          capture_output=True, text=True, timeout=30)
    assert "important" not in done.stdout, "an acknowledged message was delivered again"
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == mid


def test_listen_ack_is_clamped_to_known_messages(env):
    """An `--ack` past the newest message stops at it, and an older `--ack` never moves back."""
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost")
    cmd = [sys.executable, str(TTP), "listen", "demo", "--chat", "c1", "--once", "--timeout", "0.3"]
    mid = p.db.post("out", "first", chat="c1", kind="reply")
    top = p.db.one("SELECT MAX(id) m FROM messages")["m"]
    subprocess.run(cmd + ["--ack", str(top + 1000)], env=run_env, capture_output=True, text=True, timeout=30)
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == top
    later = p.db.post("out", "second", chat="c1", kind="reply")
    assert later > top, "a future message would have been pre-acknowledged"
    subprocess.run(cmd + ["--ack", str(mid - 1)], env=run_env, capture_output=True, text=True, timeout=30)
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == top


def _hold_write_lock(path, release_after: float | None = None):
    """A second connection holding the database's write lock (BEGIN IMMEDIATE), as a slow daemon
    transaction does; released after `release_after` seconds, or by the caller."""
    import sqlite3
    import threading
    other = sqlite3.connect(str(path), isolation_level=None, check_same_thread=False)
    other.execute("BEGIN IMMEDIATE")
    release = lambda: (other.execute("ROLLBACK"), other.close())
    if release_after is not None:
        threading.Timer(release_after, release).start()
    return release


def _short_busy_waits(monkeypatch, timeout_s=0.1, pauses=(0.2, 0.4)):
    from ttp import db as dbm
    monkeypatch.setattr(dbm, "BUSY_TIMEOUT_S", timeout_s)
    monkeypatch.setattr(dbm, "BUSY_RETRY_PAUSES_S", pauses)


def _listen_once(p, chat, ack):
    import signal
    from types import SimpleNamespace
    from ttp.cli import cmd_listen
    was = signal.getsignal(signal.SIGTERM)   # cmd_listen installs its own; keep the test process's
    try:
        cmd_listen(SimpleNamespace(name=p.name, chat=chat, ack=ack, once=True, timeout=0.3))
    finally:
        signal.signal(signal.SIGTERM, was)


def test_listen_ack_waits_out_a_write_lock_held_past_the_busy_timeout(env, monkeypatch, capsys):
    """The relay's crash: `ttp listen --once --ack` while another process held the write lock longer
    than the busy timeout raised "database is locked". A write is retried, so the ack lands."""
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    first = p.db.post("out", "first", chat="c1", kind="reply")
    p.db.post("out", "second", chat="c1", kind="reply")
    _short_busy_waits(monkeypatch)
    _hold_write_lock(p.state / "project.db", release_after=0.3)   # longer than the 0.1 s busy timeout
    _listen_once(p, "c1", first)
    out = capsys.readouterr()
    assert "second" in out.out and "first" not in out.out, out
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == first


def test_listen_keeps_listening_when_its_ack_stays_locked(env, monkeypatch, capsys):
    """Still locked after every retry: the acknowledgement is skipped with a line on stderr, never
    raised, and the listener delivers as usual. The next acknowledgement catches up."""
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    first = p.db.post("out", "first", chat="c1", kind="reply")
    p.db.post("out", "second", chat="c1", kind="reply")
    _short_busy_waits(monkeypatch, pauses=(0.05,))
    release = _hold_write_lock(p.state / "project.db")
    try:
        _listen_once(p, "c1", first)
    finally:
        release()
    out = capsys.readouterr()
    assert "first" in out.out and "second" in out.out, out   # nothing acknowledged yet: both again
    assert "skipped, the database stayed busy" in out.err, out.err
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == 0
    _listen_once(p, "c1", first)
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == first


def test_say_on_a_database_locked_past_its_retries_exits_75_without_a_traceback(env, monkeypatch, capsys):
    import sqlite3
    from types import SimpleNamespace
    from ttp.cli import cmd_say
    p = make(env)
    _short_busy_waits(monkeypatch, pauses=(0.05,))
    release = _hold_write_lock(p.state / "project.db")
    try:
        with pytest.raises(SystemExit) as ex:
            cmd_say(SimpleNamespace(name=p.name, text="hello", context=None, chat=None, client_id="k1"))
    finally:
        release()
    assert ex.value.code == 75
    assert "message was not saved" in capsys.readouterr().err
    _short_busy_waits(monkeypatch)
    _hold_write_lock(p.state / "project.db", release_after=0.3)
    cmd_say(SimpleNamespace(name=p.name, text="hello", context=None, chat=None, client_id="k1"))
    assert "sent (#" in capsys.readouterr().out
    assert len(p.db.q("SELECT id FROM messages WHERE ref='client:k1'")) == 1


def test_every_db_connection_waits_for_a_busy_database(env, tmp_path):
    """No code path opens the project database without a busy timeout, and it runs in WAL mode."""
    import ast
    from ttp import db as dbm
    d = dbm.DB(tmp_path / "x.db")
    assert d.conn.execute("PRAGMA busy_timeout").fetchone()[0] >= 1000
    assert d.conn.execute("PRAGMA journal_mode").fetchone()[0] == "wal"
    src = pathlib.Path(dbm.__file__).read_text()
    connects = [n for n in ast.walk(ast.parse(src)) if isinstance(n, ast.Call)
                and isinstance(n.func, ast.Attribute) and n.func.attr == "connect"]
    assert len(connects) == 1, "db.py opens a connection outside DB.__init__"
    assert any(k.arg == "timeout" for k in connects[0].keywords)


def test_db_write_retries_a_lock_held_past_the_busy_timeout(env, tmp_path, monkeypatch):
    import sqlite3
    from ttp import db as dbm
    _short_busy_waits(monkeypatch, timeout_s=0.05, pauses=(0.2, 0.4))
    d = dbm.DB(tmp_path / "x.db")
    _hold_write_lock(tmp_path / "x.db", release_after=0.3)
    d.set_kv("a", 1)                        # a write on its own
    _hold_write_lock(tmp_path / "x.db", release_after=0.3)
    with d.tx():                            # a transaction's BEGIN IMMEDIATE
        d.set_kv("b", 2)
    assert (d.kv("a"), d.kv("b")) == (1, 2)
    release = _hold_write_lock(tmp_path / "x.db")
    try:
        with pytest.raises(sqlite3.OperationalError, match="locked"):   # bounded: it gives up
            d.set_kv("c", 3)
    finally:
        release()
    with pytest.raises(sqlite3.OperationalError, match="no such table"):   # not busy: never retried
        d.x("UPDATE nope SET a=1")


def test_a_slow_write_transaction_is_logged_with_its_caller(tmp_path, monkeypatch):
    from ttp import db as dbm
    monkeypatch.setattr(dbm, "SLOW_TX_S", 0.0)
    d = dbm.DB(tmp_path / "x.db")

    def slow_writer():
        with d.tx():
            d.set_kv("a", 1)
    slow_writer()
    line = (tmp_path / "logs" / "slow-tx.log").read_text()
    assert "write lock held" in line and "slow_writer" in line, line


def test_the_slow_tx_log_names_the_slowest_subprocess_of_the_transaction(tmp_path, monkeypatch):
    from ttp import db as dbm
    monkeypatch.setattr(dbm, "SLOW_TX_S", 0.0)
    d = dbm.DB(tmp_path / "x.db")
    with d.tx():
        subprocess.run(["true"])
        subprocess.run([sys.executable, "-c", "import time; time.sleep(0.5)"])
        d.set_kv("a", 1)
    with d.tx():
        d.set_kv("b", 1)
    first, second = (tmp_path / "logs" / "slow-tx.log").read_text().splitlines()[-2:]
    assert "2 subprocess(es), slowest step" in first and "time.sleep(0.5)" in first, first
    assert float(first.split("slowest step ")[1].split(" s")[0]) >= 0.5, first
    assert second.endswith("; no subprocess"), second


def test_a_transaction_sqlite_already_rolled_back_raises_the_original_error(tmp_path):
    """SQLITE_FULL or IOERR roll the transaction back themselves: a second ROLLBACK would raise
    'no transaction is active' and hide the error that mattered."""
    from ttp import db as dbm
    d = dbm.DB(tmp_path / "x.db")
    ran = []
    with pytest.raises(RuntimeError, match="disk full"):
        with d.tx():
            d.set_kv("a", 1)
            d.after_commit(lambda: ran.append(1))
            d.conn.execute("ROLLBACK")      # what SQLite does on its own after SQLITE_FULL
            raise RuntimeError("disk full")
    assert not d.conn.in_transaction and ran == [] and d.kv("a") is None
    with d.tx():
        d.set_kv("b", 2)
    assert d.kv("b") == 2 and ran == [], "a dropped after-commit hook ran with the next commit"


def test_a_failed_commit_rolls_back_and_drops_its_after_commit_hooks(tmp_path):
    import sqlite3
    from ttp import db as dbm
    d = dbm.DB(tmp_path / "x.db")
    d.conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY)")
    d.conn.execute("CREATE TABLE child (p INTEGER REFERENCES parent(id) DEFERRABLE INITIALLY DEFERRED)")
    ran = []
    with pytest.raises(sqlite3.IntegrityError):    # a deferred constraint fails only at COMMIT
        with d.tx():
            d.conn.execute("INSERT INTO child VALUES (7)")
            d.after_commit(lambda: ran.append(1))
    assert not d.conn.in_transaction, "a failed COMMIT left the transaction open"
    assert d.conn.execute("SELECT COUNT(*) FROM child").fetchone()[0] == 0
    with d.tx():
        d.set_kv("b", 2)
    assert d.kv("b") == 2 and ran == [], "the failed transaction's hook ran with the next commit"


def test_concurrent_registry_updates_lose_no_entry(tmp_path, monkeypatch):
    """register and unregister read, change and write registry.json under one lock: two commands
    at once both keep their change."""
    import threading
    from ttp import project
    monkeypatch.setattr(project, "HOME_DIR", tmp_path)
    real = project.load_registry

    def slow_load():                      # widen the read-to-write gap a race needs
        reg = real()
        time.sleep(0.2)
        return reg
    monkeypatch.setattr(project, "load_registry", slow_load)
    project.register("gone", {"dir": "/g"})
    threads = [threading.Thread(target=project.register, args=(n, {"dir": f"/{n}"})) for n in ("a", "b")]
    threads.append(threading.Thread(target=project.unregister, args=("gone",)))
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert sorted(real()["projects"]) == ["a", "b"]


def test_the_tx_guard_refuses_a_git_network_command_inside_a_write_transaction(tmp_path, monkeypatch):
    """Under TTP_TX_GUARD=1 (the tests) a git command that asks a remote (ls-remote, fetch, push, pull,
    clone) raises when it starts inside db.tx(): it would hold the write lock for as long as the network
    takes. Local git, other commands and the same command outside a transaction are untouched."""
    from ttp import db as dbm
    monkeypatch.setenv("TTP_TX_GUARD", "1")
    d = dbm.DB(tmp_path / "x.db")
    subprocess.run(["git", "init", "-q", str(tmp_path / "r")], check=True)
    remote = ["git", "-C", str(tmp_path / "r"), "-c", "core.askPass=true", "ls-remote", str(tmp_path / "none")]
    assert subprocess.run(remote, capture_output=True).returncode != 0   # outside: runs (and fails)
    for argv in (remote, ["git", "fetch", "origin"], ["/usr/bin/git", "--git-dir=x", "push", "o", "b"]):
        with pytest.raises(dbm.TxNetworkError, match="inside a write transaction"):
            with d.tx():
                d.set_kv("a", 1)
                subprocess.run(argv, capture_output=True)
        assert d.kv("a") is None, "the transaction rolled back"
    with d.tx():
        subprocess.run(["git", "-C", str(tmp_path / "r"), "status"], capture_output=True, check=True)
        subprocess.run(["echo", "push"], capture_output=True, check=True)
    assert dbm.git_network(["git", "-C", "push", "log"]) == "" and dbm.git_network(["git", "-c", "a=b", "pull"])
    monkeypatch.delenv("TTP_TX_GUARD")
    with d.tx():
        subprocess.run(remote, capture_output=True)   # guard off: only recorded for the slow-tx log


def test_the_tx_guard_adds_one_audit_hook_per_process_however_often_ttp_is_imported(tmp_path, monkeypatch):
    """An audit hook cannot be removed and runs on every audit event (id() raises one, so deepcopy pays
    per object): a hook per fresh import of ttp (as each test's env fixture does) made the suite
    quadratic. One hook serves every import; the newest import's guard raises and an older import's
    open transaction still records its subprocesses."""
    real, added = sys.addaudithook, []
    monkeypatch.setattr(sys, "addaudithook", lambda f: added.append(f) or real(f))
    monkeypatch.setenv("TTP_TX_GUARD", "1")
    dbs = []
    for i in range(3):
        for mod in [m for m in list(sys.modules) if m == "ttp" or m.startswith("ttp.")]:
            monkeypatch.delitem(sys.modules, mod)
        from ttp import db as dbm
        dbs.append(dbm)
        with dbm.DB(tmp_path / f"{i}.db").tx():
            subprocess.run(["true"], check=True)
    assert len({id(m) for m in dbs}) == 3 and len(added) <= 1, added
    assert dbs[0].TxNetworkError is dbs[-1].TxNetworkError
    with pytest.raises(dbs[-1].TxNetworkError):
        with dbs[0].DB(tmp_path / "old.db").tx():
            subprocess.run(["git", "fetch", "origin"], capture_output=True)


def test_run_end_reads_the_root_checkout_after_its_transaction_commits(env, monkeypatch):
    """git status of the project root (_note_dirty_main) can take long in a large repository; it runs
    after the run-end transaction commits, never while every other process waits for its lock."""
    from ttp import worktree
    from ttp.daemon import Daemon
    from ttp.providers.base import RunUsage as Usage
    p = make(env)
    d = Daemon(p.base)
    seen, real = [], worktree.dirty_tracked
    monkeypatch.setattr(worktree, "dirty_tracked", lambda repo: seen.append(d.p.db.conn.in_transaction) or real(repo))
    tid = p.db.add_task("hand-off", "spec", kind="work", tier="standard", origin="coordinator")
    p.db.update_task(tid, status="running")
    run_dir = env["tmp"] / f"run-{tid}"
    run_dir.mkdir()
    (run_dir / "result.json").write_text(json.dumps({"status": "done", "summary": "ok"}))
    (env["repo"] / "README.md").write_text("edited\n")
    with d.p.db.tx():   # as _finish_run calls it
        d._finish_worker({"task": tid}, Usage(cost_usd=1.0), "ok", run_dir)
        assert seen == [], "git status ran inside the write transaction"
    assert seen == [False]
    assert p.db.q("SELECT id FROM events WHERE kind='observation' AND text LIKE '%README.md%'")


def test_listen_honours_the_project_chat_floor(env):
    """notify.chat_min_severity filters broadcasts on every listener; a per-chat floor can only raise it."""
    p = make(env)
