def test_charter_restrictions_lead_every_worker_prompt_once(env):
    p = make(env)
    p.charter_path.write_text("# demo\n\n## Goals\nGo fast.\n\n## Restrictions\n(none stated yet)\n\n"
                              "## Policies\nDraft PRs.\n\n## Restrictions (added 2026-09-30)\n"
                              "Never merge to main.\n")
    from ttp.prompts import charter_restrictions, restrictions_pointer, worker_prompt
    from ttp.coordinator import system_prompt
    body = charter_restrictions(p.charter_path.read_text())
    assert body == "Never merge to main."
    tid = p.db.add_task("tidy docs", "tidy the docs", kind="work", tier="light", origin="user")
    prompt = worker_prompt(p, p.db.task(tid), str(p.root), None)
    assert prompt.startswith("# BINDING RESTRICTIONS")
    assert prompt.rstrip().endswith(restrictions_pointer(p))
    assert prompt.count("Never merge to main.") == 1, "the restrictions are stated more than once"
    assert "Go fast." in prompt and "Draft PRs." in prompt
    system = system_prompt(p)
    assert system.startswith("# BINDING RESTRICTIONS")
    assert system.count("Never merge to main.") == 1, "the coordinator reads the restrictions twice"
    assert "Draft PRs." in system
    two = ("# demo\n\n## Goals\nGo fast.\n\n## Restrictions (binding on every task)\nNo host scanning.\n\n"
           "## Policies\nDraft PRs.\n\n## Restrictions (added later)\nOnly charter-named resources.\n")
    assert charter_restrictions(two) == "No host scanning.\nOnly charter-named resources."
    assert charter_restrictions("") == ""
    p.charter_path.write_text("")
    assert "BINDING RESTRICTIONS" not in worker_prompt(p, p.db.task(tid), str(p.root), None)


def test_an_ask_recommending_yes_to_a_safe_step_is_rejected(env):
    p = make(env)
    stale = ("Retire the stale restriction \"Restrictions (added 2026-09-02)\"? A newer section says the "
             "diagnosis is done.")
    least = "keep obeying it; it breaks no restriction to leave it in place for now"
    rc, ir = {"classify": "restriction_change"}, {"classify": "irreversible", "least_disruptive": least}
    problems, ask = _ask(p, stale, blocking="restriction", recommendation="yes, retire it", least_disruptive=least,
                         **rc)
    assert problems and "retired, not asked about" in problems[0] and ask is None
    problems, ask = _ask(p, "Delete the scratch branch on the fork?", blocking="irreversible",
                         recommendation="Yes: it is reversible, the commits stay in the reflog", **ir)
    assert problems and "you call reversible" in problems[0] and ask is None
    # A plain "reversible" is still rejected, including after a clause hedged otherwise.
    for k, say in enumerate(("yes, this is reversible", "Yes. It can be undone with one command",
                             "yes: not a big change, and it is reversible")):
        problems, ask = _ask(p, f"Pause nightly job {k}?", blocking="irreversible", recommendation=say, **ir)
        assert problems and "you call reversible" in problems[0] and ask is None, say
    # Truly unclear (no yes), a step that cannot be undone, and review asks still go out.
    assert _ask(p, stale, blocking="restriction", recommendation="keep it until you confirm",
                least_disruptive=least, **rc)[0] == []
    assert _ask(p, "Publish the package?", blocking="irreversible", recommendation="yes, it is not reversible",
                **ir)[0] == []
    # Any negation or hedge before "reversible" / "be undone", or "irreversible" anywhere, lets it go out.
    for k, say in enumerate(("yes. It isn't reversible", "yes, though it is not easily reversible",
                             "yes; it's not fully reversible", "yes, it is only partly reversible",
                             "yes, but it cannot easily be undone", "yes; it is non-reversible",
                             "yes, it is only partially reversible", "yes \u2014 it is never reversible",
                             "yes, it is hardly reversible",
                             "yes. Once pushed the tag is permanent, so reversible only by a new release")):
        for blocking in ("irreversible", "restriction"):
            cls = "irreversible" if blocking == "irreversible" else "restriction_change"
            assert _ask(p, f"Publish package {k} ({blocking})?", blocking=blocking, recommendation=say,
                        least_disruptive=least, classify=cls)[0] == [], (blocking, say)
    assert _ask(p, "Publish the package? It isn\u2019t reversible.", blocking="irreversible",
                recommendation="yes, publish", **ir)[0] == []
    assert _ask(p, "Grant the bot read access?", blocking="access", recommendation="yes, it can be undone")[0] == []


def test_worker_prompt_drops_placeholders_and_keeps_restrictions_verbatim(env):
    p = make(env)
    from ttp.prompts import worker_system
    p.charter_path.write_text(
        "# demo\n\n## Brief (verbatim from the user)\n\nKeep it tidy.\n\n"
        "## Goals and success criteria\n\n(to be restated by the coordinator from the brief)\n\n"
        "## Restrictions (binding on every task)\n\n(none stated yet)\n\n"
        "## Resources\n\n(machines, devices — to be filled in)\n\nMachines this project may use (aliases\n"
        "from `ttp machines list`): (none stated yet)\n\n"
        "## Policies\n\n(drafts first)\n\n- Auto-merge repositories: none (the user merges).\n\n"
        "## Restrictions (added 2026-09-30)\nNever push to main (the user merges).\n  - (and never force-push)\n")
    system = worker_system(p)
    for gone in ("(to be restated", "(none stated yet)", "## Goals and success criteria", "## Resources",
                 "(machines"):
        assert gone not in system, f"{gone!r} is still in the worker prompt"
    # No goals stated yet: the brief stands in for them. A note for nobody's work stays in the full charter.
    assert "Keep it tidy." in system and "## Policies\n- Auto-merge repositories: none (the user merges)." in system
    assert "(drafts first)" not in system
    assert system.startswith("# BINDING RESTRICTIONS")
    assert "\nNever push to main (the user merges).\n  - (and never force-push)\n" in system


def _dispatch_claude_worker(p, monkeypatch, flags, kind="work", spec="TASK-SPEC-MARKER"):
    from ttp import daemon as dmod
    from ttp.providers import claude

    class Proc:
        pid = 4242
    real = subprocess.Popen
    monkeypatch.setattr(claude, "_FLAGS", {claude.EXCLUDE_DYNAMIC: True, claude.APPEND_SYSTEM_FILE: True,
                                           claude.APPEND_SYSTEM: True, claude.TOOLS: True, **flags})
    # Only the runner is not launched; git still runs.
    monkeypatch.setattr(dmod.subprocess, "Popen",
                        lambda argv, *a, **k: Proc() if "ttp.runner" in argv else real(argv, *a, **k))
    p.set_config("core_provider", "claude")
    tid = p.db.add_task("tidy docs", spec, kind=kind, tier="light", origin="user")
    dmod.Daemon(p.base).dispatch()
    run = p.db.one("SELECT dir FROM runs WHERE task=?", (tid,))
    assert run, p.db.task(tid)["blocked_reason"]
    run_dir = pathlib.Path(run["dir"])
    return (json.loads((run_dir / "run.json").read_text())["argv"], run_dir,
            (run_dir / "prompt.md").read_text())


def test_claude_workers_get_the_stable_prompt_as_a_cacheable_system_prompt(env, monkeypatch):
    from ttp.prompts import restrictions_pointer
    p = make(env)
    p.charter_path.write_text("# demo\n\n## Goals\nGo fast.\n\n## Restrictions\nNever merge to main.\n")
    p.add_memory("MEMORY-MARKER", kind="fact")
    from ttp.providers import claude
    argv, run_dir, prompt = _dispatch_claude_worker(p, monkeypatch, {})
    assert argv[argv.index("--append-system-prompt-file") + 1] == str(run_dir / "system.md")
    system = (run_dir / "system.md").read_text()
    assert system.startswith("# BINDING RESTRICTIONS")
    assert "Go fast." in system and "MEMORY-MARKER" in system and "TASK-SPEC-MARKER" not in system
    assert "TASK-SPEC-MARKER" in prompt and "Go fast." not in prompt and "MEMORY-MARKER" not in prompt
    assert prompt.rstrip().endswith(restrictions_pointer(p)), "a pointer at the restrictions closes the prompt"
    assert "Never merge to main." not in prompt, "the restrictions are in the system prompt only"


