def _daemon_log_text(p):
    f = p.logs / "daemon.log"
    return f.read_text() if f.exists() else ""


def _harness_dirty(p):
    return subprocess.run(["git", "-C", str(p.harness), "status", "--porcelain"], capture_output=True,
                          text=True).stdout


def test_harness_commit_moves_stale_git_locks_aside_and_commits(env, monkeypatch):
    p = make(env)
    from ttp import project
    gitdir = p.harness / ".git"
    head = subprocess.run(["git", "-C", str(p.harness), "rev-parse", "--abbrev-ref", "HEAD"], capture_output=True,
                          text=True).stdout.strip()
    # What a commit killed mid-way leaves behind.
    left = [gitdir / "index.lock", gitdir / "HEAD.lock", gitdir / "next-index-123.lock",
            gitdir / "refs" / "heads" / f"{head}.lock"]
    old = time.time() - 3600
    for f in left:
        f.write_text("x\n")
        os.utime(f, (old, old))
    fresh = gitdir / "packed-refs.lock"
    fresh.write_text("y\n")
    # A process that may hold them (a git running in the repo) keeps even old locks in place.
    from ttp import gitlocks
    holders = gitlocks.holders
    monkeypatch.setattr(gitlocks, "holders", lambda *a, **k: [4242])
    assert p.clear_stale_git_locks() == []
    assert all(f.exists() for f in left) and "left alone: pid(s) 4242" in _daemon_log_text(p)
    monkeypatch.setattr(gitlocks, "holders", holders)
    fresh.unlink()
    p.add_memory("Locks a killed commit left are moved aside.")
    assert not any(f.exists() for f in left)
    kept = sorted(str(x.relative_to(gitdir / "ttp-stale-locks").parts[1:]) for x in
                  (gitdir / "ttp-stale-locks").glob("*/**/*.lock"))
    assert len(kept) == 4, kept   # backed up, never deleted
    assert "moved stale lock file(s) aside" in _daemon_log_text(p)
    assert "MEMORY.md" not in _harness_dirty(p), "the commit went through once the locks were gone"
    # A fresh lock (a commit in progress elsewhere) is never touched.
    fresh.write_text("y\n")
    assert p.clear_stale_git_locks() == [] and fresh.exists()


def _real_git() -> str:
    """The first git on PATH that is no tt-project git wrapper, as the wrapper itself picks it."""
    for d in os.environ.get("PATH", "").split(os.pathsep):
        f = pathlib.Path(d) / "git"
        try:
            if d and f.is_file() and os.access(f, os.X_OK) and b"# tt-project git wrapper" not in f.read_bytes():
                return str(f)
        except OSError:
            continue
    raise AssertionError("no real git on PATH")


def test_git_lock_holders_see_a_real_git_in_the_repo(env, tmp_path, monkeypatch):
    from ttp import gitlocks
    # As inside a run, the plugin's git wrapper comes first on PATH. Until it execs the real git, its
    # process is a shell, so the test starts the real git itself.
    wrap = tmp_path / "wrapper-bin"
    wrap.mkdir()
    (wrap / "git").symlink_to(RUNTIME.parent / "template" / "bin" / "git")
    monkeypatch.setenv("PATH", f"{wrap}{os.pathsep}{os.environ.get('PATH', '')}")
    assert _real_git() != str(wrap / "git")
    p = make(env)
    gdir = gitlocks.git_dir(p.harness)
    proc = subprocess.Popen([_real_git(), "-C", str(p.harness), "hash-object", "--stdin"], stdin=subprocess.PIPE,
                            stdout=subprocess.DEVNULL)
    try:
        assert proc.pid in gitlocks.holders(p.harness, gdir, [])
        other = tmp_path / "elsewhere"
        other.mkdir()
        assert proc.pid not in gitlocks.holders(other, other / ".git", [])
    finally:
        proc.communicate(b"x")


def test_harness_commit_failure_is_logged_and_a_later_commit_sweeps_it(env, monkeypatch):
    p = make(env)
    from ttp import project
    real = project.subprocess.run

    def broken(argv, **kw):
        if "commit" in argv:
            return subprocess.CompletedProcess(argv, 128, "", "fatal: Unable to create 'index.lock': File exists.")
        return real(argv, **kw)
    monkeypatch.setattr(project.subprocess, "run", broken)
    p.add_memory("This commit fails.")
    log = _daemon_log_text(p)
    assert "commit failed with exit 128" in log and "index.lock" in log, log
    assert "MEMORY.md" in _harness_dirty(p)
    monkeypatch.setattr(project.subprocess, "run", real)
    # The writer's own commit is left alone for a minute; after that the sweep picks the files up.
    assert p.sweep_harness() is False
    assert p.sweep_harness(min_age_s=0) is True
    assert _harness_dirty(p).strip() == "", _harness_dirty(p)
    assert "sweep: committing" in _daemon_log_text(p)
    # Unrelated harness files are never swept.
    (p.harness / "prompts" / "scratch.md").write_text("a harness task's unfinished edit\n")
    p.charter_path.write_text(p.charter_path.read_text() + "\nhand edit\n")
    os.utime(p.charter_path, (time.time() - 120, time.time() - 120))
    p.add_memory("A later commit heals the earlier failure.")
    dirty = _harness_dirty(p)
    assert "CHARTER.md" not in dirty and "prompts/scratch.md" in dirty, dirty
    msgs = subprocess.run(["git", "-C", str(p.harness), "log", "--format=%s", "-3"], capture_output=True,
                          text=True).stdout
    assert "earlier failed commit" in msgs


def test_harness_commit_timeout_is_configurable_and_logged(env, monkeypatch):
    p = make(env)
    from ttp import project
    from ttp.daemon import Daemon
    seen = []
    real = project.subprocess.run

    def slow(argv, **kw):
        seen.append(kw.get("timeout"))
        if "commit" in argv:
            raise subprocess.TimeoutExpired(argv, kw.get("timeout"))
        return real(argv, **kw)
    monkeypatch.setattr(project.subprocess, "run", slow)
    p.add_memory("Default timeout.")
    assert 120 in seen and "commit timed out after 120 s" in _daemon_log_text(p)
    p.set_config("harness_git.timeout_s", 300)   # project.json is not swept: not charter or memory
    seen.clear()
    p.add_memory("Raised timeout.")
    assert seen and set(seen) == {300}, seen
    monkeypatch.setattr(project.subprocess, "run", real)
    # The daemon's tick sweeps what the timed-out commits left, once per sweep_every_s.
    d = Daemon(p.base)
    old = time.time() - 120
    for f in [p.memory_index, *p.memory_dir.glob("*.md")]:
        os.utime(f, (old, old))
    d.heal_harness_git()
    assert "memory" not in _harness_dirty(p).lower()
    p.add_memory("Swept on the next tick window only.")
    for f in [p.memory_index, *p.memory_dir.glob("*.md")]:
        os.utime(f, (old, old))
    subprocess.run(["git", "-C", str(p.harness), "reset", "-q", "--soft", "HEAD~1"], check=True)
    d.heal_harness_git()
    assert "MEMORY.md" in _harness_dirty(p), "swept again before sweep_every_s"
    d._harness_swept = 0.0
    d.heal_harness_git()
    assert "memory" not in _harness_dirty(p).lower()


def test_harness_sweep_never_commits_a_cut_write_over_the_good_copy(env):
    """A power cut leaves damaged charter and memory files uncommitted; the sweep that heals failed
    commits must leave them for the boot integrity check to put back from the last commit."""
    p = make(env)
    from ttp import integrity, runner
    from ttp.daemon import Daemon, KV_INTEGRITY
    a = p.add_memory("A good entry the cut damages.", kind="fact")
    good, charter = a.read_bytes(), p.charter_path.read_bytes()
    a.write_bytes(good[:len(good) // 2].rstrip(b"\n") + b"\0" * 16)   # cut short, NUL-padded
    p.charter_path.write_bytes(charter[:len(charter) - 7].rstrip(b"\n"))
    old = time.time() - 3600
    for f in (a, p.charter_path):
        os.utime(f, (old, old))
    p.add_memory("A later fact whose commit sweeps.")
    Daemon(p.base).heal_harness_git()
    dirty = _harness_dirty(p)
    assert a.name in dirty and "CHARTER.md" in dirty, dirty
    assert "look like a cut write" in _daemon_log_text(p)
    res = integrity.check_harness(p)
    assert a.read_bytes() == good and p.charter_path.read_bytes() == charter, res
    assert not res["bad"] and len(res["restored"]) == 2, res
    # A good leftover waits for this boot's integrity check, once a daemon has run one before.
    b = p.add_memory("Left by a failed commit.", kind="fact")
    subprocess.run(["git", "-C", str(p.harness), "reset", "-q", "--soft", "HEAD~1"], check=True)
    p.db.set_kv(KV_INTEGRITY, {"boot": "an-earlier-boot", "at": old})
    assert p.sweep_harness(min_age_s=0) is False and b.name in _harness_dirty(p)
    p.db.set_kv(KV_INTEGRITY, {"boot": runner.boot_id(), "at": time.time()})
    assert p.sweep_harness(min_age_s=0) is True and b.name not in _harness_dirty(p)


def test_a_bulky_handoff_keeps_its_summary_and_retry_fields(env):
    from ttp.db import dump_result
    stored = json.loads(dump_result({
        "summary": "S" * 8000, "status": "waiting", "waits": 3,
        "followups": [{"title": "t", "spec": "x" * 3000} for _ in range(200)],
        "metrics": {f"k{i}": ["y" * 100] * 50 for i in range(500)}}))
    assert stored["summary"] == "S" * 8000 and stored["status"] == "waiting" and stored["waits"] == 3
    assert stored["clipped"] and stored["followups"]


def test_an_orphan_run_row_is_reaped_and_the_next_turn_runs(env):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    # A coordinator turn whose start was cut short: no run directory or pid was ever recorded.
    rid = p.db.x("INSERT INTO runs(role,provider,started,status,boot_id,note) VALUES(?,?,?,?,?,?)",
                 ("coordinator", "fake", time.time(), "running", d.boot, "{}"))
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    p.db.post("in", "status please", chat="c1")
