    (run_dir / "lease").touch()
    p.db.x("INSERT INTO runs(task,role,provider,started,status,dir,boot_id) VALUES(?,?,?,?,?,?,?)",
           (live, "worker", "fake", time.time(), "running", str(run_dir), d.boot))
    d.tick()
