def test_a_run_end_is_recorded_whole_or_not_at_all(env, tmp_path, monkeypatch):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = p.db.add_task("job", "s", kind="work", tier="light", origin="user")
    p.db.update_task(tid, status="running")
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    (run_dir / "output.jsonl").write_text(json.dumps({"_cost": 1.5}))
    (run_dir / "exit.json").write_text(json.dumps({"rc": 0, "ended": time.time()}))
    rid = p.db.x("INSERT INTO runs(task,role,provider,started,status,dir,boot_id) VALUES(?,?,?,?,?,?,?)",
                 (tid, "worker", "fake", time.time(), "running", str(run_dir), d.boot))

    def broken(*a, **k):
        raise RuntimeError("bug while recording the hand-off")
    monkeypatch.setattr(d, "_finish_worker", broken)
    d.reap_runs()
    assert p.db.one("SELECT status FROM runs WHERE id=?", (rid,))["status"] == "running"
    assert not p.db.q("SELECT id FROM ledger") and not p.db.task(tid)["spent_usd"], "a half-recorded run end"
    p.db.x("UPDATE runs SET cost_usd=0.75, cost_estimated=1 WHERE id=?", (rid,))   # priced while it ran
    d.reap_runs()
    d.reap_runs()          # a run end that keeps failing is closed, not retried forever
    assert p.db.one("SELECT status FROM runs WHERE id=?", (rid,))["status"] == "failed"
    assert p.db.task(tid)["status"] == "failed"
    assert p.db.spent_since(0) == 0.75 and p.db.task(tid)["spent_usd"] == 0.75, "an abandoned run's spend vanished"
    d._abandon_run(p.db.one("SELECT * FROM runs WHERE id=?", (rid,)))
    assert p.db.spent_since(0) == 0.75 and p.db.task(tid)["spent_usd"] == 0.75, "booked twice"


def test_remote_listener_reconnects_after_a_network_drop(env, monkeypatch):
    from ttp import cli
    results = iter([255, 255, 0])
    calls, naps = [], []
    monkeypatch.setattr(cli, "forward", lambda entry, argv, quiet=False, shown=None, failure=None:
                        calls.append(quiet) or next(results))
    monkeypatch.setattr(cli.time, "sleep", lambda s: naps.append(s))
    assert cli.forward_listen({"host": "box", "dir": "/x"}, ["listen", "demo", "--chat", "c1", "--once"]) == 0
    assert calls == [True, True, True], "the listener explains a drop itself, once, not forward() per retry"
    assert naps == [5.0, 10.0]


class _Session:
    """A fake `ssh HOST CMD` for a listener: prints `lines`, writes `err` to its stderr, exits `rc`."""
    def __init__(self, args, lines, rc, err, kw):
        self.args, self.stdout, self.returncode = args, iter(lines), rc
        kw["stderr"].write(err)

    def wait(self):
        return self.returncode


def _ssh_sessions(monkeypatch, cwd, sessions, calls):
    """Each ssh call takes the next of `sessions`: (lines, rc, stderr) is a fake session; "real"
    (or none left) runs CMD here in `cwd`, as the project's machine would."""
    real = subprocess.Popen

    def popen(args, **kw):
        if args[0] != "ssh":
            return real(args, **kw)
        calls.append(args[-1])
        s = sessions.pop(0) if sessions else "real"
        if s == "real":
            return real(["bash", "-c", args[-1]], cwd=cwd, **kw)
        return _Session(args, *s, kw)
    monkeypatch.setattr(subprocess, "Popen", popen)


_BROKEN_PIPE = "client_loop: send disconnect: Broken pipe\n"


def test_remote_listen_once_ack_reconnects_after_an_ssh_drop_and_acks_once(env, monkeypatch, capsys):
    """The reported bug: `ttp listen --once --ack N` forwarded over ssh said "will keep retrying"
    after a broken pipe and then exited. It reconnects, shows the new reply once and acks only N."""
    from ttp import cli
    from ttp.project import register
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    old = p.db.post("out", "already shown", chat="c1", kind="reply")
    new = p.db.post("out", "fresh reply", chat="c1", kind="reply")
    entry = {"host": "far", "dir": str(env["repo"])}
    register("demo", entry)
    monkeypatch.chdir(env["tmp"])
    calls, naps = [], []
    _ssh_sessions(monkeypatch, env["repo"], [([], 255, _BROKEN_PIPE)], calls)
    monkeypatch.setattr(cli.time, "sleep", lambda s: naps.append(s))
    argv = ["listen", "demo", "--chat", "c1", "--once", "--ack", str(old), "--timeout", "20"]
    assert cli.forward_listen(entry, argv, "demo") == 0
    out, err = capsys.readouterr()
    assert len(calls) == 2 and naps == [5.0], (calls, naps)
    assert "Broken pipe" not in err and "etrying" not in err, "a reconnect within the grace says nothing: " + err
    assert out.count(f"[#{new} ") == 1 and "fresh reply" in out and "already shown" not in out, out
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == old, \
        "only --ack marks messages read; the reconnect neither lost nor acknowledged the new reply"


