def test_setup_installs_the_plain_tt_project_shortcut_for_claude_code(env, tmp_path):
    claude = env["tmp"] / "claude"
    f = claude / "skills" / "tt-project" / "SKILL.md"

    def setup(*extra):
        # 300 s at least: one setup copies the plugin and took 28 s alone at host load 120.
        r = subprocess.run([*TTP_NO_SYNC, "setup", "--bin-dir", str(tmp_path / "bin"), *extra],
                           capture_output=True, text=True, timeout=max(300, _load_scaled(300)))
        assert r.returncode == 0, r.stderr
        # Mask temp paths: they may hold "/tt-project" when the suite runs under a harness folder.
        return r.stdout.replace(str(tmp_path), "<tmp>").replace(str(env["tmp"]), "<tmp>")

    ready = "Claude Code: /tt-project is ready"
    assert ready not in setup() and not claude.exists()              # no Claude Code: nothing written
    claude.mkdir()
    assert "/tt-project is ready" in setup()
    text = f.read_text()
    assert "name: tt-project\n" in text and "disable-model-invocation: true" in text
    assert "`tt-project:tt-project`" in text
    assert ready not in setup() and f.read_text() == text             # idempotent
    f.write_text(text.replace("Request:", "Old request:"))            # an older release's text
    assert "/tt-project is ready" in setup() and f.read_text() == text
    assert "removed the /tt-project shortcut" in setup("--no-shortcut")
    assert not f.parent.exists()
    assert "removed the /tt-project shortcut" not in setup("--no-shortcut")  # nothing left to remove
    f.parent.mkdir(parents=True)
    f.write_text("---\nname: tt-project\ndescription: mine\n---\nmy own skill\n")
    assert "left your own" in setup() and f.read_text().endswith("my own skill\n")
    assert "left " in setup("--no-shortcut") and f.read_text().endswith("my own skill\n")


def test_setup_never_downgrades_a_newer_install_without_force(env, tmp_path):
    from ttp import __version__
    _install_template(env)
    newer = env["home"] / "lib" / _newer(__version__)
    (env["home"] / "lib" / "current").rename(newer)
    init = newer / "runtime" / "ttp" / "__init__.py"
    init.write_text(init.read_text().replace(f'"{__version__}"', f'"{_newer(__version__)}"'))
    (env["home"] / "lib" / "current").symlink_to(newer)

    def setup(*extra):
        return subprocess.run([*TTP_NO_SYNC, "setup", "--bin-dir", str(tmp_path / "bin"), *extra],
                              capture_output=True, text=True, timeout=max(300, _load_scaled(300)))
    r = setup()
    assert r.returncode != 0 and f"ttp {_newer(__version__)} is installed" in r.stderr and "--force" in r.stderr
    assert (env["home"] / "lib" / "current").resolve() == newer.resolve() and not (tmp_path / "bin").exists()
    r = setup("--force")
    assert r.returncode == 0, r.stderr
    assert (env["home"] / "lib" / "current").resolve() == (env["home"] / "lib" / __version__).resolve()
    mark = env["home"] / "lib" / "forced-downgrade"
    assert mark.read_text().strip() == __version__     # daemons leave a deliberate downgrade alone
    assert setup().returncode == 0 and mark.read_text().strip() == __version__   # same version stays forced
    mark.write_text("0.0.1\n")                         # a marker for another version is stale
    assert setup().returncode == 0 and not mark.exists()


def test_setup_writes_the_forced_downgrade_marker_before_it_switches_lib_current(env, tmp_path, monkeypatch):
    from ttp import __version__, cli, release
    _install_template(env)
    lib = env["home"] / "lib"
    newer = lib / _newer(__version__)
    (lib / "current").rename(newer)
    init = newer / "runtime" / "ttp" / "__init__.py"
    init.write_text(init.read_text().replace(f'"{__version__}"', f'"{_newer(__version__)}"'))
    (lib / "current").symlink_to(newer)
    seen = []
    real = release.forced_mark

    def mark():                  # what a daemon checking at this moment would find in lib/current
        seen.append((lib / "current").resolve())
        return real()
    monkeypatch.setattr(release, "forced_mark", mark)
    with contextlib.redirect_stdout(io.StringIO()):
        cli.main(["setup", "--bin-dir", str(tmp_path / "bin"), "--force"])
    assert seen == [newer.resolve()] and real().read_text().strip() == __version__
    assert (lib / "current").resolve() == (lib / __version__).resolve()


def test_setup_syncs_the_copied_lib_to_disk_before_switching_lib_current(env, tmp_path, monkeypatch):
    from ttp import cli
    _install_template(env)
    lib = env["home"] / "lib"
    (lib / "current").rename(lib / "old")
    (lib / "current").symlink_to(lib / "old")
    seen = []
    monkeypatch.delenv("TTP_TEST_NO_SYNC")   # this test checks the flush itself
    monkeypatch.setattr(cli.os, "sync", lambda: seen.append((lib / "current").resolve()), raising=False)
    with contextlib.redirect_stdout(io.StringIO()):
        cli.main(["setup", "--bin-dir", str(tmp_path / "bin"), "--force"])
    assert seen == [(lib / "old").resolve()]    # synced before lib/current points at the new copy
    assert (lib / "current").resolve() == (lib / cli.__version__).resolve()


@pytest.mark.parametrize("there,ships", [("newer", False), ("same", False), ("older", True), ("none", True)])
def test_ship_runtime_never_replaces_a_newer_or_equal_remote_install(env, monkeypatch, there, ships):
    from ttp import __version__, cli
    ver = {"newer": _newer(__version__), "same": __version__, "older": "0.0.1", "none": ""}[there]
    calls = []

    def run(cmd, **kw):
        calls.append(("run", cmd[-1]))
        out = f'__version__ = "{ver}"\n' if ver else ""
        return subprocess.CompletedProcess(cmd, 0 if ver else 1, out, "" if ver else "No such file")

    class Tar:
        stdout = None

        def wait(self):
            return 0
    monkeypatch.setattr(cli.subprocess, "run", run)
    monkeypatch.setattr(cli.subprocess, "check_call", lambda cmd, **kw: calls.append(("call", cmd[-1])))
    monkeypatch.setattr(cli.subprocess, "Popen", lambda *a, **kw: Tar())
    launcher = cli.ship_runtime("box")
    assert calls[0] == ("run", "cat ~/.tt-project/lib/current/runtime/ttp/__init__.py")
    shipped = [c for kind, c in calls if kind == "call"]
    if ships:
        assert launcher == f"~/.tt-project/lib/{__version__}/bin/ttp"
        assert shipped[0].startswith("rm -rf") and shipped[-1].endswith("bin/ttp setup >/dev/null")
    else:
        assert launcher == "~/.tt-project/lib/current/bin/ttp" and not shipped


def test_a_runtime_from_no_git_checkout_gets_a_stable_content_hash_its_consumers_accept(env, tmp_path):
    """A plugin installed from a cache or archive records 'sha-<12 hex>' over runtime/'s files, not
    'unknown': a receipt with it is verified, `ttp deployed` matches it, and a finish task that targeted
    it counts as landed."""
    import shutil
    from ttp import cli, identity, overview, release
    rt = tmp_path / "runtime"
    shutil.copytree(RUNTIME, rt, ignore=shutil.ignore_patterns("__pycache__", "*.pyc", "SOURCE_COMMIT"))
    h = cli.content_hash(rt)
    assert re.fullmatch(r"sha-[0-9a-f]{12}", h)
    (rt / "ttp" / "__pycache__").mkdir(exist_ok=True)
    (rt / "ttp" / "__pycache__" / "x.cpython.pyc").write_bytes(b"compiled")
    (rt / "ttp" / "SOURCE_COMMIT").write_text(h + "\n")
    assert cli.content_hash(rt) == h                     # bytecode and the recorded identity do not count
    (rt / "ttp" / "new.py").write_text("")
    assert cli.content_hash(rt) != h                     # a new file does
    (rt / "ttp" / "new.py").unlink()
    (rt / "ttp" / "__init__.py").write_text((rt / "ttp" / "__init__.py").read_text() + "# edited\n")
    edited = cli.content_hash(rt)
    assert edited != h                                   # and so does an edit
    # identity: a receipt with a content hash is verified
    rec = identity.capture(mod=_fake_runtime(tmp_path / "rcpt", "9.9.1", commit=h))
    assert rec["provenance"] == "verified" and rec["commit"] == h, rec
    # `ttp deployed`: the hash is the deploy's commit; a runtime with other files is not this deploy
    _deploy_lib("0.5.0", commit=h)
    _, a = _deploy_project(tmp_path, "alpha", "0.5.0", commit=h)
    r = overview.deployed()
    assert r["rc"] == 0 and r["commit"] == h, r["text"]
    assert overview.deployed(target="0.5.0", commit=edited)["rc"] == 1
    a.close()
    # release.landed: a finish task targeting a hashed release landed once the harness runs it
    p = make(env)
    tid = p.db.add_task("Finish", f"merge it\n\nTarget release: tt-project 0.5.0 ({h})\n", kind="harness")
    p.db.x("UPDATE tasks SET status='done' WHERE id=?", (tid,))
    assert release.landed(p.db, tid, "0.5.0", h) and not release.landed(p.db, tid, "0.5.0", edited)


