_IDENT = ["-c", "user.name=t", "-c", "user.email=t@t"]


def _code_task(p, name, status="done"):
    from ttp import worktree
    tid = p.db.add_task(name, "s", kind="code", tier="light", origin="user")
    path, branch = worktree.ensure(p, p.db.task(tid))
    p.db.update_task(tid, status=status, branch=branch)
    return tid, path, branch


def _no_grace(monkeypatch):
    """Finished worktrees become removable at once (not after worktree.FINISH_GRACE_S)."""
    from ttp import worktree
    monkeypatch.setattr(worktree, "FINISH_GRACE_S", 0)


def _commit_file(path, name):
    (path / f"{name}.txt").write_text(name)
    _git_out(path, "add", ".")
    _git_out(path, *_IDENT, "commit", "-qm", name)


def test_finished_worktrees_are_removed_at_task_end_only_when_nothing_is_lost(env, monkeypatch):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp.daemon import Daemon
    t_clean, clean, clean_branch = _code_task(p, "clean")
    (clean / ".gitignore").write_text("build/\n*.log\n")
    _commit_file(clean, "clean")
    (clean / "run.log").write_text("ignored, not a cache: goes with the worktree")
    (clean / "build").mkdir()
    (clean / "build" / "big.o").write_bytes(b"0" * 1000)
    head = _git_out(clean, "rev-parse", "HEAD")
    t_dirty, dirty, _ = _code_task(p, "dirty", status="failed")
    (dirty / "pkg").mkdir()
    (dirty / ".gitignore").write_text("build/\n__pycache__/\n.venv/\n")
    _git_out(dirty, "add", ".gitignore")
    _commit_file(dirty / "pkg", "mod")
    (dirty / "README.md").write_text("edited\n")
    for cache in ("build", "pkg/__pycache__", ".venv/lib"):
        (dirty / cache).mkdir(parents=True)
        (dirty / cache / "blob").write_text("x")
    t_open, open_, _ = _code_task(p, "still open", status="queued")
    t_run, running, _ = _code_task(p, "cancelled, run not ended yet", status="cancelled")
    p.db.x("INSERT INTO runs(role,provider,started,status,task) VALUES('worker','fake',?,'running',?)",
           (time.time(), t_run))
    t_det, detached, _ = _code_task(p, "detached")
    _git_out(detached, "checkout", "-q", "--detach")
    _commit_file(detached, "orphan")
    d = Daemon(p.base)
    d.prune_worktrees()
    assert not clean.exists(), "a clean finished worktree was kept"
    assert _git_out(p.root, "rev-parse", clean_branch) == head, "the task branch was lost"
    worktrees = {pathlib.Path(line.removeprefix("worktree "))
                 for line in _git_out(p.root, "worktree", "list", "--porcelain").splitlines()
                 if line.startswith("worktree ")}
    assert clean not in worktrees, "the worktree was not pruned from git"
    assert dirty.exists() and (dirty / "README.md").read_text() == "edited\n", "uncommitted work was lost"
    assert not any((dirty / c).exists() for c in ("build", "pkg/__pycache__", ".venv")), "caches were kept"
    assert open_.exists() and running.exists() and detached.exists()
    kept = p.db.kv("worktrees_kept")
    assert set(kept) == {str(t_dirty), str(t_det)} and "uncommitted" in kept[str(t_dirty)], kept
    assert "detached" in kept[str(t_det)]
    log = (p.logs / "daemon.log").read_text()
    assert f"task {t_clean} (done) removed" in log and f"task {t_dirty} kept: uncommitted" in log
    # Kept worktrees are not re-examined every sweep, but are once their task changes.
    (dirty / "build").mkdir()
    d.prune_worktrees(every_s=0)
    assert (dirty / "build").exists(), "an unchanged kept worktree was swept again"
    _git_out(dirty, "checkout", "--", "README.md")
    p.db.update_task(t_dirty, status="cancelled")
    d.prune_worktrees()
    assert not dirty.exists() and str(t_dirty) not in (p.db.kv("worktrees_kept") or {})


def test_a_worktree_another_tasks_probe_reads_survives_a_forced_prune_while_that_task_waits(env, monkeypatch, capsys):
    """A waiting task whose retry_when cds into another, finished task's worktree: pruning that worktree
    would leave the probe failing ("not yet") forever. It stays, with a keep reason naming the waiting
    task, and one log line when the hand-off is accepted or the probe set by hand; it goes once the wait ends."""
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import cli, worktree
    from ttp.daemon import Daemon
    t_done, path, _ = _code_task(p, "finished, its job runs in its worktree")
    probe = f"cd {path} && ttp detach --check job"
    t_wait = _due_waiting_task(p, "true")
    p.db.update_task(t_wait, not_before=time.time() + 3600)
    cli.main(["task", "demo", "set-when", str(t_wait), probe])
    assert f"reads the worktree of task(s) #{t_done}" in capsys.readouterr().out
    assert f"task {t_wait} retry_when reads the worktree of task(s) #{t_done}" in (p.logs / "daemon.log").read_text()
    d = Daemon(p.base)
    d.prune_worktrees(force=True)
    assert path.exists(), "the worktree a waiting task's probe reads was pruned"
    why = p.db.kv("worktrees_kept")[str(t_done)]
    assert f"task #{t_wait}" in why and "probe" in why, why
    # A relative path from the project root, and the task's own worktree, count the same way / not at all.
    rel = path.relative_to(p.root).as_posix()
    assert worktree.worktree_refs(f"cd {rel} && true; cd tt-project/worktrees/t{t_wait}", t_wait) == [t_done]
    assert worktree.worktree_refs(f"cd /x/myworktrees/t{t_done} && test -e worktrees/t{t_done}x") == []
    p.db.update_task(t_wait, status="done")
    d.prune_worktrees(force=True)
    assert not path.exists(), "the worktree outlived the wait"


def test_a_kept_worktree_is_logged_once_and_tracked_changes_raise_one_event(env, monkeypatch):
    """The keep reason is logged when it changes, not every sweep, nor again after a restart. Modified
    tracked files keep the worktree and reach the coordinator once per content; status and the web
    feed show them, the top section does not."""
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    from ttp.cli import status_text
    from ttp.daemon import Daemon
    from ttp.web import state_payload
    tid, path, _ = _code_task(p, "half done", status="failed")
    _commit_file(path, "a")
    (path / "a.txt").write_text("edited\n")
    (path / "notes.md").write_text("scratch")

    def events():
        return p.db.q("SELECT * FROM events WHERE kind=?", (worktree.DIRTY_EVENT,))
    Daemon(p.base).prune_worktrees()
    Daemon(p.base).prune_worktrees(every_s=0)   # a restart forgets the in-memory memo
    d = Daemon(p.base)
    d.prune_worktrees()
    assert path.exists() and (path / "a.txt").read_text() == "edited\n" and (path / "notes.md").exists()
    log = (p.logs / "daemon.log").read_text()
    assert log.count(f"task {tid} kept:") == 1, log
    (ev,) = events()
    assert ev["task"] == tid and ev["status"] == "queued" and "(failed)" in ev["text"] and "a.txt" in ev["text"]
    assert "1 finished task worktree kept with uncommitted changes" in status_text(p)
    st = state_payload(p, p.db)
    assert any(m["kind"] == "worktree" and f"#{tid} (failed)" in m["text"] for m in st["feed"])
    assert not any(f"#{tid}" in m["text"] for m in st["attention"])
    # The event does not hold the worktree as "not yet seen" by the coordinator; new content is a new event.
    assert "not yet seen" not in p.db.kv("worktrees_kept")[str(tid)]
    (path / "a.txt").write_text("edited again\n")
    p.db.update_task(tid, status="done")
    d.prune_worktrees()
    assert len(events()) == 2 and (p.logs / "daemon.log").read_text().count(f"task {tid} kept:") == 1
    _git_out(path, "checkout", "--", "a.txt")   # now only the untracked note is left: it moves out
    p.db.x("INSERT INTO runs(role,provider,started,status,task,dir) VALUES('worker','fake',?,'done',?,?)",
           (time.time(), tid, str(p.runs / "77")))
    p.db.update_task(tid, status="cancelled")
    d.prune_worktrees()
    assert not path.exists() and not p.db.kv("worktrees_dirty") and "uncommitted" not in status_text(p)


def test_a_kept_reason_is_logged_once_per_holder_and_only_real_clean_ups_are_logged(env, monkeypatch):
    """The keep line comes again only when the holder task changes, not when it goes queued, running or
    pushing, nor after a restart; status still shows its current state. A cache clean-up is logged only
    when it removed something from a worktree that stays."""
    p = make(env)
    _no_grace(monkeypatch)
    from ttp.daemon import Daemon
    tid, path, _ = _code_task(p, "change")
    (path / ".gitignore").write_text("build/\n")
    _commit_file(path, "change")
    review = p.db.add_task("review change", "Review it, then ttp push.", kind="review", tier="light",
                           origin="user", depends_on=[tid])

    def kept_lines():
        return [ln for ln in (p.logs / "daemon.log").read_text().splitlines() if f"task {tid} kept:" in ln]
    d = Daemon(p.base)
    d.prune_worktrees()
    for status in ("running", "pushing", "queued", "pushing"):
        p.db.update_task(review, status=status)
        d.prune_worktrees(every_s=0)
        Daemon(p.base).prune_worktrees(every_s=0)   # a restart does not log it again
    d.prune_worktrees(every_s=0)
    assert path.exists() and len(kept_lines()) == 1 and f"task #{review} (queued)" in kept_lines()[0]
    assert f"task #{review} (pushing)" in p.db.kv("worktrees_kept")[str(tid)]
    p.db.update_task(review, status="done")
    other = p.db.add_task("follow-up", f"Continue from #{tid}.", kind="code", tier="light", origin="user")
    d.prune_worktrees(every_s=0)
    assert path.exists() and len(kept_lines()) == 2 and f"task #{other} (queued)" in kept_lines()[1]
    # A worktree kept for its own uncommitted edit: an empty clean-up logs nothing, a real one logs once.
    p.db.update_task(other, status="done")
    (path / "change.txt").write_text("edited\n")
    d.prune_worktrees(every_s=0)
    log = (p.logs / "daemon.log").read_text()
    assert path.exists() and f"task {tid}: removed" not in log and "kept: uncommitted" in kept_lines()[-1]
    (path / "build").mkdir()
    (path / "build" / "a.o").write_text("x")
    p.db.update_task(tid, status="failed")
    d.prune_worktrees(every_s=0)
    log = (p.logs / "daemon.log").read_text()
    assert not (path / "build").exists() and log.count(f"task {tid}: removed build") == 1, log
    # The worktree goes: its caches go with it, under the one removal line.
    _git_out(path, "checkout", "--", "change.txt")
    (path / "build").mkdir()
    (path / "build" / "a.o").write_text("x")
    p.db.update_task(tid, status="done")
    d.prune_worktrees(every_s=0)
    log = (p.logs / "daemon.log").read_text()
    assert not path.exists() and f"task {tid} (done) removed" in log
    assert log.count(f"task {tid}: removed") == 1, log


def test_untracked_leftovers_move_to_the_last_run_and_the_worktree_goes(env, monkeypatch):
    """A finished worktree whose only dirty entries are untracked files under the size limit: they move
    to <last run dir>/worktree-leftovers/ with their relative paths, the worktree goes, the branch
    stays. Over the limit they go to the task's archive instead and the worktree goes too. Running and
    queued tasks' worktrees are untouched."""
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    from ttp.daemon import Daemon
    tid, path, branch = _code_task(p, "done with scratch")
    _commit_file(path, "work")
    head = _git_out(path, "rev-parse", "HEAD")
    (path / "tmp" / "sub").mkdir(parents=True)
    (path / "tmp" / "sub" / "out.txt").write_text("scratch")
    (path / "notes.md").write_text("notes")
    for r in (1, 2):
        p.db.x("INSERT INTO runs(role,provider,started,status,task,dir) VALUES('worker','fake',?,'done',?,?)",
               (time.time(), tid, str(p.runs / f"r{r}")))
    big_id, big, _ = _code_task(p, "done with a big file", status="cancelled")
    p.db.x("INSERT INTO runs(role,provider,started,status,task) VALUES('worker','fake',?,'done',?)", (time.time(), big_id))
    with open(big / "huge.bin", "wb") as fh:
        fh.truncate(51 * 10**6)   # sparse: over the 50 MB default without using the disk
    open_id, open_, _ = _code_task(p, "still queued", status="queued")
    (open_ / "notes.md").write_text("mine")
    run_id, running, _ = _code_task(p, "cancelled, run not ended", status="cancelled")
    p.db.x("INSERT INTO runs(role,provider,started,status,task) VALUES('worker','fake',?,'running',?)",
           (time.time(), run_id))
    (running / "notes.md").write_text("mine")
    dry = {r["task"]: r for r in worktree.sweep(p, dry_run=True)}
    assert dry[tid]["why"] is None and dry[tid]["moved"]["files"] == 2 and path.exists()
    assert dry[big_id]["why"] is None and dry[big_id]["archived"]["files"] == 1 and big.exists()
    assert open_id not in dry and run_id not in dry
    d = Daemon(p.base)
    d.prune_worktrees()
    Daemon(p.base).prune_worktrees(every_s=0)
    dest = p.runs / "r2" / worktree.LEFTOVERS_DIR
    assert (dest / "tmp" / "sub" / "out.txt").read_text() == "scratch" and (dest / "notes.md").read_text() == "notes"
    assert not path.exists() and _git_out(p.root, "rev-parse", branch) == head, "the branch was lost"
    assert not big.exists()
    from ttp import archive
    assert [(e["path"], e["size"], e["stored"]) for e in archive.manifest(p, big_id)["files"]] == [
        ("huge.bin", 51 * 10**6, "tar")]
    assert (open_ / "notes.md").read_text() == "mine" and (running / "notes.md").read_text() == "mine"
    log = (p.logs / "daemon.log").read_text()
    assert log.count(f"task {tid}: moved 2 untracked file(s)") == 1 and f"task {tid} (done) removed" in log
    assert log.count(f"task {big_id}: archived 1 file(s) (51.0 MB)") == 1, log
    assert not p.db.q("SELECT id FROM events WHERE kind=?", (worktree.DIRTY_EVENT,))
    # The limit is a setting; at 0 nothing moves.
    t0, p0, _ = _code_task(p, "limit off")
    (p0 / "x.txt").write_text("x")
    p.set_config("disk.worktree_leftovers_max_mb", 0)
    Daemon(p.base).prune_worktrees()
    assert (p0 / "x.txt").exists() and "moving them out is off" in p.db.kv("worktrees_kept")[str(t0)]


def test_the_worktree_sweep_leaves_the_push_queue_checkouts_alone(env, monkeypatch):
    """The batch's checkout (worktrees/push) and its after_push checkouts (worktrees/after_push-<id>)
    belong to no task: the sweep removes a finished task's worktree next to them, never them."""
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    from ttp.daemon import Daemon
    tid, path, _ = _code_task(p, "finished")
    keep = [p.worktrees / "push", p.worktrees / "after_push-batch-20261005-120000-1"]
    for wt in keep:
        _git_out(p.root, "worktree", "add", "-q", "--detach", str(wt))
    worktree.sweep(p)
    Daemon(p.base).prune_worktrees(every_s=0)
    assert not path.exists(), "the sweep did not run"
    assert all((wt / "README.md").exists() for wt in keep)
    assert all(str(wt) in _git_out(p.root, "worktree", "list") for wt in keep)


def test_a_tracked_file_in_a_cache_named_directory_is_never_cleared(env):
    p = make(env)
    from ttp import worktree
    _, path, _ = _code_task(p, "tracked build dir")
    (path / "build").mkdir()
    (path / "build" / "script.sh").write_text("echo hi\n")
    (path / ".gitignore").write_text("*.o\n__pycache__/\n")
