    _git_out(path, *_IDENT, "commit", "-qm", "tracked build dir")
    (path / "build" / "out.o").write_text("x")
    (path / "build" / "__pycache__").mkdir()
    (path / "build" / "__pycache__" / "m.pyc").write_text("x")
