def test_an_untracked_file_in_a_tracked_build_directory_is_archived_not_lost(env, monkeypatch):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    tid, path, _ = _code_task(p, "new build step")
    (path / "tools" / "build").mkdir(parents=True)
    (path / "tools" / "build" / "CMakeLists.txt").write_text("project(x)\n")
    _git_out(path, "add", ".")
    _git_out(path, *_IDENT, "commit", "-qm", "tools")
    (path / "tools" / "build" / "new.cmake").write_text("uncommitted work\n")
    (res,) = worktree.sweep(p)
    # The cache sweep leaves a tracked build directory alone; the new file is archived, not deleted.
    assert res["cleared"] == [] and res["why"] is None and not path.exists()
    assert _archived(p, tid) == {"tools/build/new.cmake": (False, "tar")}
    from ttp import archive
    assert archive.restore(p, tid, env["tmp"] / "back") == ["tools/build/new.cmake"]
    assert (env["tmp"] / "back" / "tools" / "build" / "new.cmake").read_text() == "uncommitted work\n"


def _handoff(p, tid, artifacts):
    run = p.db.x("INSERT INTO runs(role,provider,started,status,task) VALUES('worker','fake',?,'done',?)",
                 (time.time(), tid))
    d = p.runs / str(run)
    d.mkdir(parents=True)
    p.db.x("UPDATE runs SET dir=? WHERE id=?", (str(d), run))
    (d / "result.json").write_text(json.dumps({"status": "done", "summary": "s", "artifacts": artifacts}))


def test_ignored_hand_off_artifacts_are_archived_and_other_ignored_files_are_not(env, monkeypatch):
    # `git worktree remove` deletes ignored files, and workers often leave their hand-off there.
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    exclude = pathlib.Path(_git_out(p.root, "rev-parse", "--git-common-dir"))
    exclude = (exclude if exclude.is_absolute() else p.root / exclude) / "info" / "exclude"
    exclude.parent.mkdir(parents=True, exist_ok=True)
    exclude.write_text("tmp/\nbuild/\n")
    tid, path, _ = _code_task(p, "render")
    _commit_file(path, "tracked")
    (path / "tmp" / "out").mkdir(parents=True)
    (path / "tmp" / "out" / "new.mp4").write_bytes(b"video")
    (path / "tmp" / "NEXT.md").write_text("notes\n")
    (path / "build").mkdir()
    (path / "build" / "model.pt").write_bytes(b"weights")
    rel_root = path.relative_to(p.root).as_posix()
    _handoff(p, tid, [f"{rel_root}/tmp/out/new.mp4 (the render)", f"{path}/tmp/NEXT.md:3", "build/model.pt",
                      "tracked.txt", "https://example.com/x", "tmp/gone.log"])
    t2, other, _ = _code_task(p, "scratch only")
    _commit_file(other, "tracked")
    (other / "tmp").mkdir()
    (other / "tmp" / "scratch.log").write_text("not handed off")
    _handoff(p, t2, ["tracked.txt", str(path / "tmp" / "out" / "new.mp4")])
    # status.showUntrackedFiles=no must not hide a new, not ignored file.
    _git_out(p.root, "config", "status.showUntrackedFiles", "no")
    t3, hidden, _ = _code_task(p, "untracked")
    (hidden / "new.py").write_text("uncommitted work\n")
    res = {r["task"]: r for r in worktree.sweep(p)}
    assert not path.exists() and res[tid]["why"] is None
    assert _archived(p, tid) == {"tmp/out/new.mp4": (True, "tar"), "tmp/NEXT.md": (True, "tar"),
                                 "build/model.pt": (True, "tar")}, "a hand-off artifact was lost"
    from ttp import archive
    archive.restore(p, tid, env["tmp"] / "back")
    assert (env["tmp"] / "back" / "tmp" / "out" / "new.mp4").read_bytes() == b"video"
    assert (env["tmp"] / "back" / "build" / "model.pt").read_bytes() == b"weights"
    assert not other.exists() and res[t2]["why"] is None, "an ignored file nobody handed off kept the worktree"
    assert _archived(p, t2) == {"tmp/scratch.log": (False, "tar")}, "a small ignored log was not kept"
    assert not hidden.exists() and _archived(p, t3) == {"new.py": (False, "tar")}


def test_a_named_directory_with_tracked_files_archives_only_its_ignored_entries(env, monkeypatch):
    # A hand-off naming a directory that holds tracked files and an ignored cache once archived the
    # whole directory: its tracked files were deleted, and the worktree never looked clean again.
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    tid, path, _ = _code_task(p, "skill")
    (path / "skills" / "box").mkdir(parents=True)
    (path / "skills" / "box" / "SKILL.md").write_text("skill\n")
    (path / "skills" / "box" / "run.py").write_text("print(1)\n")
    (path / ".gitignore").write_text("__pycache__/\n")
    _git_out(path, "add", ".")
    _git_out(path, *_IDENT, "commit", "-qm", "skill")
    (path / "skills" / "box" / "__pycache__").mkdir()
    (path / "skills" / "box" / "__pycache__" / "run.pyc").write_bytes(b"pyc")
    _handoff(p, tid, ["skills/box"])
    assert worktree.handoff_artifacts(p, tid, path) == ["skills/box/__pycache__"]
    (res,) = worktree.sweep(p)
    assert res["why"] is None and not path.exists(), "the worktree was kept"
    assert _archived(p, tid) == {"skills/box/__pycache__/run.pyc": (True, "tar")}


def test_archive_store_never_takes_a_tracked_file_out_of_the_worktree(env):
    p = make(env)
    from ttp import archive
    tid, path, _ = _code_task(p, "tracked")
    _commit_file(path, "kept")
    (path / "new.txt").write_text("untracked\n")
    out = archive.store(p, p.db.task(tid), path, ["kept.txt", "new.txt"], ["kept.txt"], 200)
    assert out["files"] == 1 and (path / "kept.txt").read_text() == "kept"
    assert not (path / "new.txt").exists()
    assert _git_out(path, "status", "--porcelain").strip() == ""
    assert _archived(p, tid) == {"new.txt": (True, "tar")}


def _archived(p, tid):
    from ttp import archive
    return {e["path"]: (e["named"], e["stored"]) for e in (archive.manifest(p, tid) or {}).get("files", [])}


def _ignore_tmp(p):
    exclude = pathlib.Path(_git_out(p.root, "rev-parse", "--git-common-dir"))
    exclude = (exclude if exclude.is_absolute() else p.root / exclude) / "info" / "exclude"
    exclude.parent.mkdir(parents=True, exist_ok=True)
    exclude.write_text("tmp/\n")


def test_another_tasks_hand_off_in_a_worktree_is_archived_with_it(env, monkeypatch):
    # Later tasks often write their logs into an earlier task's worktree; removing it deletes them.
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    _ignore_tmp(p)
    ta, a, _ = _code_task(p, "first")
    _commit_file(a, "tracked")
    (a / "tmp").mkdir()
    (a / "tmp" / "b.log").write_text("task b's log")
    (a / "tmp" / "stray.log").write_text("nobody's")
    tc, c, _ = _code_task(p, "untouched")
    _commit_file(c, "tracked")
    (c / "tmp").mkdir()
    (c / "tmp" / "stray.log").write_text("nobody's")
    tb = p.db.add_task("second", "s", kind="experiment", tier="light", origin="user")
    p.db.update_task(tb, status="done")
    # Relative to the tt-project folder; a bare tmp/stray.log is B's own, not A's or C's.
    _handoff(p, tb, [f"worktrees/t{ta}/tmp/b.log (the drive log)", "tmp/stray.log"])
    res = {r["task"]: r for r in worktree.sweep(p)}
    assert not a.exists() and res[ta]["why"] is None
    assert _archived(p, ta) == {"tmp/b.log": (True, "tar"), "tmp/stray.log": (False, "tar")}, \
        "another task's hand-off artifact was lost"
    from ttp import archive
    found = archive.resolve(p, str(a / "tmp" / "b.log"))
    assert found["task"] == ta and found["location"].endswith("files.tar.gz:tmp/b.log")
    assert archive.resolve(p, "tmp/b.log", task_id=ta)["sha256"] == found["sha256"]
    assert archive.resolve(p, str(a / "tmp" / "nothing.log")) is None
    assert not c.exists() and res[tc]["why"] is None


def test_large_untracked_files_are_archived_under_the_cap_and_listed_above_it(env, monkeypatch):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import archive, worktree
    tid, path, _ = _code_task(p, "big outputs")
    _commit_file(path, "tracked")
    (path / "out").mkdir()
    (path / "out" / "small.bin").write_bytes(b"s" * 400_000)
    (path / "out" / "large.bin").write_bytes(b"l" * 3_000_000)
    (path / "out" / "named.bin").write_bytes(b"n" * 2_000_000)
    _handoff(p, tid, ["out/named.bin (the result)"])
    (dry,) = worktree.sweep(p, archive_max_mb=1, leftovers_max_mb=0.1, dry_run=True)
    assert dry["archived"] == {"files": 2, "bytes": 2_400_000, "dropped": 1, "dropped_bytes": 3_000_000}
    assert path.exists() and archive.manifest(p, tid) is None, "a dry run changed something"
    (res,) = worktree.sweep(p, archive_max_mb=1, leftovers_max_mb=0.1)
    assert res["why"] is None and not path.exists() and res["archived"]["dropped"] == 1
    # A named artifact is archived whatever its size; unnamed files only up to the cap, the rest listed.
    assert _archived(p, tid) == {"out/named.bin": (True, "tar"), "out/small.bin": (False, "tar"),
                                 "out/large.bin": (False, "dropped")}
    m = {e["path"]: e for e in archive.manifest(p, tid)["files"]}
    import hashlib
    assert m["out/large.bin"]["sha256"] == hashlib.sha256(b"l" * 3_000_000).hexdigest()
    assert m["out/large.bin"]["size"] == 3_000_000 and archive.manifest(p, tid)["branch"]
    assert sorted(archive.restore(p, tid, env["tmp"] / "back")) == ["out/named.bin", "out/small.bin"]
    assert (env["tmp"] / "back" / "out" / "named.bin").read_bytes() == b"n" * 2_000_000
    assert worktree.sweep(p, archive_max_mb=1) == [], "a second sweep found something"


def test_tracked_changes_are_saved_as_a_verified_patch_only_when_asked(env, monkeypatch, capsys):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import archive, cli, worktree
    tid, path, _ = _code_task(p, "half done")
    _commit_file(path, "tracked")
    (path / "tracked.txt").write_text("changed\n")
    (path / "new.txt").write_text("new\n")
    (res,) = worktree.sweep(p)
    assert path.exists() and res["tracked"] == ["tracked.txt"], "a plain sweep must keep tracked changes"
    cli.main(["prune", "demo", "--patch-tracked"])
    out = capsys.readouterr().out
    assert not path.exists() and "saved its 1 changed tracked file(s) as a verified patch" in out, out
    m = archive.manifest(p, tid)
    assert m["status"] == "done" and m["patches"][0]["paths"] == ["tracked.txt"]
    assert _archived(p, tid) == {"new.txt": (False, "tar")}
    patch = archive.task_dir(p, tid) / m["patches"][0]["file"]
    _git_out(p.root, "worktree", "add", "-q", "--detach", str(env["tmp"] / "again"), m["head"])
    _git_out(env["tmp"] / "again", "apply", str(patch))
    assert (env["tmp"] / "again" / "tracked.txt").read_text() == "changed\n"
    assert f"task {tid} (done)" in (archive.task_dir(p, tid).parent / "MANIFEST.md").read_text()

def _no_pending_or_temp(p, tid):
    from ttp import archive
    d = archive.task_dir(p, tid)
    m = archive.manifest(p, tid) or {}
    assert not [x.name for x in d.rglob("*") if x.name.endswith((".tmp", ".part"))] if d.is_dir() else True
    assert not [e for e in (m.get("files") or []) + (m.get("patches") or []) if e.get("pending")], m


def test_a_failed_archive_write_leaves_no_temp_file_or_patch_and_the_worktree_as_it_was(env, monkeypatch):
    # The disk guard sweeps when space is short: a tarball cut off by ENOSPC must not stay behind.
    import errno
    import tarfile
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import archive, worktree
    tid, path, _ = _code_task(p, "out of space")
    _commit_file(path, "tracked")
    (path / "tracked.txt").write_text("changed\n")
    (path / "a.bin").write_bytes(b"a" * 1000)
    (path / "b.bin").write_bytes(b"b" * 1000)
    _handoff(p, tid, ["a.bin", "b.bin"])
    calls = []

    def full(self, name, *a, **kw):
        calls.append(name)
        if len(calls) == 2:
            raise OSError(errno.ENOSPC, "No space left on device")
        return add(self, name, *a, **kw)
    add = tarfile.TarFile.add
    monkeypatch.setattr(tarfile.TarFile, "add", full)
    (res,) = worktree.sweep(p, patch_tracked=True)
    assert res["why"].startswith("error:") and "No space left" in res["why"], res
    assert path.exists() and (path / "a.bin").read_bytes() == b"a" * 1000 and (path / "b.bin").exists()
    assert (path / "tracked.txt").read_text() == "changed\n"
    d = archive.task_dir(p, tid)
    assert not list(d.glob("*.tar.gz*")) and not list(d.glob("tracked*.patch")), sorted(x.name for x in d.iterdir())
    _no_pending_or_temp(p, tid)
    assert archive.resolve(p, str(path / "a.bin")) is None
    monkeypatch.setattr(tarfile.TarFile, "add", add)
    (res,) = worktree.sweep(p, patch_tracked=True)
    assert res["why"] is None and not path.exists() and set(_archived(p, tid)) == {"a.bin", "b.bin"}
    assert [e["file"] for e in archive.manifest(p, tid)["patches"]] == ["tracked.patch"]


def test_an_archive_that_does_not_fit_in_free_space_is_skipped_with_the_sizes(env, monkeypatch):
    import collections
    import shutil
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import archive, worktree
    tid, path, _ = _code_task(p, "no room")
    (path / "out.bin").write_bytes(b"o" * 3_000_000)
    _handoff(p, tid, ["out.bin"])
    usage = collections.namedtuple("usage", "total used free")
    real = shutil.disk_usage
    monkeypatch.setattr(shutil, "disk_usage", lambda path: usage(10**12, 10**12 - 2_000_000, 2_000_000))
    (res,) = worktree.sweep(p, reserve_bytes=1_000_000)
    assert res["why"].startswith("archiving skipped") and "3.1 MB" in res["why"] and "2.0 MB are free" in res["why"], res
    assert (path / "out.bin").exists() and archive.manifest(p, tid) is None and "archived" not in res
    # The disk guard's threshold stays free; while free space is already below it, RESERVE_FLOOR_MB does.
    floor = archive.RESERVE_FLOOR_MB * 1e6
    monkeypatch.setattr(shutil, "disk_usage", lambda path: usage(10**12, 0, 200e9))
    assert archive.room(path, 1_000_000, 150e9) is None and archive.room(path, 60e9, 150e9)
    monkeypatch.setattr(shutil, "disk_usage", lambda path: usage(10**12, 0, floor + 2e6))
    assert archive.room(path, 1_000_000, 150e9) is None and "must stay free" in archive.room(path, 3e6, 150e9)
    monkeypatch.setattr(shutil, "disk_usage", real)
    (res,) = worktree.sweep(p)
    assert res["why"] is None and _archived(p, tid) == {"out.bin": (True, "tar")}


def test_a_kill_after_moving_a_big_file_is_recovered_by_the_next_sweep(env, monkeypatch):
    # Known gap, recovered later: the process dies between the big file's move and the final manifest.
    import os
    from pathlib import Path
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import archive, worktree
    monkeypatch.setattr(archive, "TAR_MAX_MB", 0.001)   # files over 1 KB are "big": stored as objects, not tarred
    tid, path, _ = _code_task(p, "killed mid-archive")
    (path / "big.bin").write_bytes(b"B" * 5000)
    (path / "small.txt").write_text("s")
    _handoff(p, tid, ["big.bin", "small.txt"])
    pid = os.fork()
    if pid == 0:   # the child is killed (no finally, no cleanup) as it would write the final manifest
        try:
            real = archive.write_json

            def killed(target, data):
                if not any(e.get("pending") for e in data.get("files") or []):
                    os._exit(9)
                real(target, data)
            archive.write_json = killed
            archive.store(p, p.db.task(tid), path, ["big.bin", "small.txt"], [], 200)
        finally:
            os._exit(1)
    assert os.waitpid(pid, 0)[1] >> 8 == 9
    m = archive.manifest(p, tid)
    assert all(e.get("pending") for e in m["files"]) and not (path / "big.bin").exists()
    big = next(e for e in m["files"] if e["path"] == "big.bin")
    assert (archive.task_dir(p, tid) / big["blob"]).exists() and (path / "small.txt").exists()
    (res,) = worktree.sweep(p)
    assert res["why"] is None and not path.exists(), res
    _no_pending_or_temp(p, tid)
    found = archive.resolve(p, str(path / "big.bin"))
    assert found["stored"] == "file" and Path(found["location"]).read_bytes() == b"B" * 5000
    assert archive.resolve(p, "small.txt", task_id=tid)["stored"] == "tar"
    # small.txt's tarball was in place before the kill, so it is kept, and archived again from the worktree.
    assert set(archive.restore(p, tid, env["tmp"] / "back")) == {"big.bin", "small.txt"}


def test_the_daemon_archives_one_worktree_per_step_within_its_budget_and_finishes_later(env, monkeypatch):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import daemon as dmod
    from ttp.daemon import Daemon
    clean, clean_path, _ = _code_task(p, "nothing to keep")
    heavy = []
    for i in range(3):
        tid, path, _ = _code_task(p, f"output {i}")
        for f in ("one.bin", "two.bin"):
            (path / f).write_bytes(f"{i}{f}".encode() * 100)
        _handoff(p, tid, ["one.bin", "two.bin"])
        heavy.append((tid, path))
    d = Daemon(p.base)
    ticks = []
    d._progress = lambda: ticks.append(1)
    first = {r["task"]: r for r in d.prune_worktrees(every_s=0)}
    assert first[clean]["why"] is None and not clean_path.exists(), "cheap removals are not held back"
    assert sum(1 for r in first.values() if r.get("archived")) == 1
    assert sorted(t for t, r in first.items() if r.get("deferred")) == [heavy[1][0], heavy[2][0]]
    assert len(ticks) >= 4 + 2 * 2, ticks   # per worktree looked at, and per file hashed and tarred
    assert "kept: archiving deferred" not in (p.logs / "daemon.log").read_text()
    # Over the time budget no archiving starts; the deferred ones stay for the next tick.
    monkeypatch.setattr(dmod, "HEARTBEAT_STALE_S", 0)
    again = d.prune_worktrees()
    assert again and all(r.get("deferred") for r in again) and all(path.exists() for _, path in heavy[1:])
    monkeypatch.undo()
    _no_grace(monkeypatch)
    d.prune_worktrees()   # the default every_s would wait: deferred work runs at the next tick anyway
    d.prune_worktrees()
    assert not any(path.exists() for _, path in heavy)
    assert all(set(_archived(p, tid)) == {"one.bin", "two.bin"} for tid, _ in heavy)
    assert d.prune_worktrees() == [] and d._prune_more is None


def test_a_failing_archive_neither_starves_a_forced_sweep_nor_is_retried_every_tick(env, monkeypatch):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import archive
    from ttp.daemon import Daemon
    heavy = []
    for i in range(3):
        tid, path, _ = _code_task(p, f"output {i}")
        (path / "one.bin").write_bytes(b"x" * 1000)
        _handoff(p, tid, ["one.bin"])
        heavy.append((tid, path))
    real, calls = archive.sha256, []

    def unreadable(path, progress=lambda: None):
        if str(heavy[0][1]) in str(path):
            calls.append(path)
            raise PermissionError(13, "Permission denied", str(path))
        return real(path, progress)
    monkeypatch.setattr(archive, "sha256", unreadable)
    d = Daemon(p.base)
    d._progress = lambda: None
    first = {r["task"]: r for r in d.prune_worktrees(every_s=0, force=True)}
    assert first[heavy[0][0]]["why"].startswith("error:") and heavy[0][1].exists()
    assert first[heavy[1][0]].get("archived"), "the failed archive used up the step's slot"
    for _ in range(5):
        d.prune_worktrees()
    assert not any(path.exists() for _, path in heavy[1:]), "later worktrees never archived"
    assert len(calls) == 1, f"the failing worktree was hashed {len(calls)} times"
    assert d._prune_more is None


def test_a_cross_filesystem_big_file_copy_reports_progress_per_chunk(tmp_path, monkeypatch):
    from ttp import archive
    src, dst = tmp_path / "big.bin", tmp_path / "big.copy"
    src.write_bytes(b"y" * 10_000)
    os.chmod(src, 0o640)
    monkeypatch.setattr(archive, "COPY_CHUNK", 1000)
    ticks = []
    archive.copy(src, dst, lambda: ticks.append(1))
    assert dst.read_bytes() == src.read_bytes() and len(ticks) == 10
    assert (dst.stat().st_mode & 0o777) == 0o640


def test_a_stale_initializing_lock_is_cleared_but_a_live_or_foreign_lock_is_not(env, monkeypatch):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    t_stale, stale, branch = _code_task(p, "stale lock")
    t_live, live, _ = _code_task(p, "live lock")
    t_user, user, _ = _code_task(p, "someone's lock")
    for path, reason in ((stale, "initializing"), (live, "initializing"), (user, "kept for a bisect")):
        _git_out(p.root, "worktree", "lock", "--reason", reason, str(path))
    real = worktree._users
    monkeypatch.setattr(worktree, "_users", lambda path: [4242] if path == live else real(path))
    res = {r["task"]: r for r in worktree.sweep(p)}
    assert res[t_stale]["unlocked"] == "initializing" and res[t_stale]["why"] is None and not stale.exists()
    assert _git_out(p.root, "branch", "--list", branch).strip(), "the branch went with the worktree"
    assert res[t_live]["held"] and res[t_live]["why"] == "process 4242 runs in it" and live.exists()
    assert res[t_user]["why"].startswith("locked (kept for a bisect)") and user.exists()
    assert "locked" in _git_out(p.root, "worktree", "list", "--porcelain").split(str(live))[1].split("\n\n")[0]


def test_a_finished_review_frees_the_reviewed_worktree_without_the_grace(env, monkeypatch):
    p = make(env)
    from ttp import worktree
    tid, path, _ = _code_task(p, "reviewed change")
    (path / "notes.md").write_text("review notes\n")
    _handoff(p, tid, ["notes.md"])
    review = p.db.add_task("review it", "s", kind="review", tier="light", origin="user")
    p.db.update_task(review, status="running", depends_on=str(tid))
    (res,) = worktree.sweep(p)
    assert res["held"] and path.exists(), "the grace did not hold a fresh finished worktree"
    p.db.update_task(review, status="failed")   # a failed review ends the review just as a pass does
    (res,) = worktree.sweep(p)
    assert res["why"] is None and not path.exists()
    assert _archived(p, tid) == {"notes.md": (True, "tar")}


def test_open_and_running_tasks_worktrees_are_never_touched(env, monkeypatch):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    kept = {}
    for status in ("queued", "running", "waiting", "blocked", "needs_review"):
        tid, path, _ = _code_task(p, status, status=status)
        (path / "work.txt").write_text("in progress\n")
        _git_out(p.root, "worktree", "lock", "--reason", "initializing", str(path))
        kept[tid] = path
    done, fin, _ = _code_task(p, "finished")
    p.db.update_task(done, status="done")
    assert [r["task"] for r in worktree.sweep(p)] == [done]
    for tid, path in kept.items():
        assert (path / "work.txt").read_text() == "in progress\n" and _archived(p, tid) == {}
    assert str(kept[next(iter(kept))]) in _git_out(p.root, "worktree", "list")
    assert all("locked" in _git_out(p.root, "worktree", "list", "--porcelain").split(str(path))[1].split("\n\n")[0]
               for path in kept.values())


def test_the_disk_guard_sweeps_finished_worktrees_and_releases_held_work(env, monkeypatch):
    import collections
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import daemon as dm
    from ttp import worktree
    usage = collections.namedtuple("usage", "total used free")
    free = {"gb": 40}   # a 1000 GB disk: the guard is at 50 GB
    monkeypatch.setattr(dm.shutil, "disk_usage", lambda path: usage(1000e9, 0, free["gb"] * 1e9))
    real = worktree.remove

    def remove(p, task_id, force=False):
        real(p, task_id, force)
        free["gb"] += 15   # the finished worktree held 15 GB
    monkeypatch.setattr(worktree, "remove", remove)
    t_old, old, _ = _code_task(p, "old output")
    (old / "result.bin").write_bytes(b"r")
    _handoff(p, t_old, ["result.bin"])
    alerts = lambda: p.db.q("SELECT id FROM messages WHERE kind='alert' AND ref='disk'")  # noqa: E731
    code = p.db.add_task("build it", "s", kind="code", tier="light", origin="user")
    d = dm.Daemon(p.base)
    d.dispatch()
    assert not old.exists() and _archived(p, t_old) == {"result.bin": (True, "tar")}
    assert p.db.kv("disk_low") is None and not alerts(), "the sweep freed enough, yet the guard held"
    assert p.db.q("SELECT id FROM runs WHERE task=?", (code,)), "held work was not released"
    assert "disk guard sweep: 1 finished task worktree(s) removed, 0 kept, 15.0 GB freed" in (
        p.logs / "daemon.log").read_text()
    # Still low after a sweep that freed nothing: one alert, and no second sweep inside the rate limit.
    free["gb"] = 20
    d._disk_swept = 0.0   # the last sweep is past the rate limit
    d.check_disk()
    assert p.db.kv("disk_low") and len(alerts()) == 1
    assert "0 removed, 0 kept, 0.0 GB freed" in p.db.one("SELECT text FROM messages WHERE ref='disk'")["text"]
    calls = []
    monkeypatch.setattr(d, "_disk_sweep", lambda: calls.append(1) or {"removed": 0, "kept": 0, "freed": 0})
    d.check_disk()
    assert calls == [] and len(alerts()) == 1


def test_a_glob_hand_off_entry_is_archived_before_the_worktree_goes(env, monkeypatch):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    _ignore_tmp(p)
    ta, a, _ = _code_task(p, "weights")
    _commit_file(a, "tracked")
    (a / "tmp").mkdir()
    (a / "tmp" / "ckpt_1.pt").write_bytes(b"w1")
    (a / "tmp" / "ckpt_2.pt").write_bytes(b"w2")
    tb, b, _ = _code_task(p, "no match")
    _commit_file(b, "tracked")
    (b / "tmp").mkdir()
    (b / "tmp" / "other.pt").write_bytes(b"w")
    _handoff(p, ta, ["tmp/ckpt_*.pt (weights)"])
    _handoff(p, tb, ["tmp/ckpt_*.pt"])
    res = {r["task"]: r for r in worktree.sweep(p)}
    assert not a.exists() and res[ta]["why"] is None and res[ta]["archived"]["files"] == 2
    assert _archived(p, ta) == {"tmp/ckpt_1.pt": (True, "tar"), "tmp/ckpt_2.pt": (True, "tar")}
    assert not b.exists() and res[tb]["why"] is None and not res[tb].get("archived")

def test_a_finished_worktree_stays_while_an_unfinished_task_still_needs_it(env, monkeypatch):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    from ttp.daemon import Daemon
    tid, path, branch = _code_task(p, "change")
    _commit_file(path, "change")
    review = p.db.add_task("review change", "Review it, then ttp push.", kind="review", tier="light",
                           origin="user", depends_on=[tid])
    named = p.db.add_task("review by name", f"Push {branch} after checks.", kind="review", tier="light",
                          origin="user")
    p.db.update_task(review, status="cancelled")
    d = Daemon(p.base)
    d.prune_worktrees()
    assert path.exists(), "the worktree went while a queued task names its branch"
    assert f"task #{named} (queued)" in p.db.kv("worktrees_kept")[str(tid)]
    p.db.update_task(named, status="done")
    p.db.update_task(review, status="queued")
    d.prune_worktrees()
    assert path.exists(), "the worktree went while a queued review depends on its task"
    p.db.update_task(review, status="done")
    d.prune_worktrees()
    assert not path.exists() and str(tid) not in (p.db.kv("worktrees_kept") or {})
    assert worktree.needed_by({"id": 7, "branch": None}, [{"id": 8, "status": "queued", "spec": "see #7 and t7.",
                                                           "depends_on": None, "labels": None}])
    assert not worktree.needed_by({"id": 7, "branch": None}, [{"id": 8, "status": "queued", "spec": "#70, t77",
                                                               "depends_on": None, "labels": None}])
    assert worktree.needed_by({"id": 7, "branch": None}, [{"id": 8, "status": "queued", "depends_on": None,
                                                           "spec": "cd tt-project/worktrees/t7 && ttp push",
                                                           "labels": None}])


def _sub_git(*args):
    return ["git", "-c", "protocol.file.allow=always", *_IDENT, *args]


def test_a_worktree_with_submodule_commits_is_never_removed(env, monkeypatch):
    # `git worktree remove --force` deletes the worktree's git directory, and with it modules/,
    # the only copy of commits made inside a submodule there.
    p = make(env)
    _no_grace(monkeypatch)
    from ttp.daemon import Daemon
    sub = env["tmp"] / "sub"
    subprocess.run(["git", "init", "-q", str(sub)], check=True)
    _commit_file(sub, "lib")
    subprocess.run(_sub_git("-C", str(p.root), "submodule", "add", "-q", str(sub), "sub"), check=True,
                   capture_output=True)
    _git_out(p.root, *_IDENT, "commit", "-qm", "add submodule")
    tid, path, branch = _code_task(p, "bump submodule")
    assert _git_out(path, "rev-parse", "--abbrev-ref", "HEAD") == branch
    subprocess.run(_sub_git("-C", str(path), "submodule", "update", "--init", "-q"), check=True, capture_output=True)
    _commit_file(path / "sub", "fix")
    sub_head = _git_out(path / "sub", "rev-parse", "HEAD")
    _git_out(path, "add", "sub")
    _git_out(path, *_IDENT, "commit", "-qm", "bump sub")
    assert not _git_out(path, "status", "--porcelain", "--ignore-submodules=none")
    d = Daemon(p.base)
    d.prune_worktrees()
    assert path.exists() and _git_out(path / "sub", "rev-parse", "HEAD") == sub_head, "submodule commits were lost"
    assert "submodules" in p.db.kv("worktrees_kept")[str(tid)]
    # A submodule that was never set up in the worktree holds nothing.
    t2, plain, _ = _code_task(p, "no submodule work")
    d.prune_worktrees(every_s=0)
    assert not plain.exists()


def test_a_finished_worktree_waits_for_the_review_queued_after_it(env):
    p = make(env)
    from ttp.daemon import Daemon
    tid, path, _ = _code_task(p, "change")
    _commit_file(path, "change")
    p.db.x("INSERT INTO events(ts,source,kind,severity,text,status,task) VALUES(?,?,?,?,?,?,?)",
           (time.time(), f"task:{tid}", "task_done", "normal", "done", "queued", tid))
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (time.time() - 7200, tid))
    d = Daemon(p.base)
    d.prune_worktrees()
    assert path.exists(), "the worktree went before the coordinator saw the task end"
    assert "not yet seen" in p.db.kv("worktrees_kept")[str(tid)]
    p.db.x("UPDATE events SET status='handled' WHERE task=?", (tid,))
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (time.time(), tid))
    d.prune_worktrees(every_s=0)
    assert path.exists(), "the worktree went within the grace period"
    review = p.db.add_task("review change", "Review it, then ttp push.", kind="review", tier="light",
                           origin="user", depends_on=[tid])
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (time.time() - 7200, tid))
    d.prune_worktrees(every_s=0)
    assert path.exists(), "the worktree went while its review was queued"
    p.db.update_task(review, status="done")
    d.prune_worktrees()
    assert not path.exists()


