def _local_only_events(p):
    return p.db.q("SELECT text, task FROM events WHERE kind='local_only'")


def _local_only_daemon(p):
    """A daemon whose local-only check counts as installed before the test's tasks finished."""
    from ttp import daemon as dm
    p.db.set_kv(dm.KV_LOCAL_ONLY_FROM, 0)
    return dm.Daemon(p.base)


def _finish_local_only(d):
    """Wait for the local-only check running in its thread, then let a tick apply what it found."""
    job = d._local_only_job
    if job is not None:
        assert job["done"].wait(60), "the local-only check did not finish"
        d.check_local_only()
        assert d._local_only_job is None


def _check_local_only(d):
    """One check_local_only as the daemon runs it: started on one tick, applied on a later one."""
    d.check_local_only()
    _finish_local_only(d)


def _bare_init(env, path):
    """`git init -q --bare <path>` without a git process: a copy of the session's empty bare repository."""
    shutil.copytree(env["_make"][0]["bare"], path, symlinks=True)
    return path


def _remote_add(repo, url, name="origin"):
    """`git remote add <name> <url>` in `repo` without a git process: the section git writes for it,
    appended to the repository's config. A url git would quote, or a linked worktree, uses git itself."""
    config, url = pathlib.Path(repo) / ".git" / "config", str(url)
    if not config.is_file() or any(c in url + name for c in '"\\;#\n\t ') or url.startswith("-"):
        subprocess.run(["git", "-C", str(repo), "remote", "add", name, url], check=True)
        return
    text = config.read_text()
    assert f'[remote "{name}"]' not in text, f"remote {name} already exists in {repo}"
    config.write_text(text + ("" if text.endswith("\n") else "\n")
                      + f'[remote "{name}"]\n\turl = {url}\n\tfetch = +refs/heads/*:refs/remotes/{name}/*\n')


def _with_origin(env, clone=True):
    remote = env["tmp"] / "remote.git"
    if clone:
        subprocess.run(["git", "clone", "-q", "--bare", str(env["repo"]), str(remote)], check=True)
    else:
        _bare_init(env, remote)
    _remote_add(env["repo"], remote)
    return remote


def test_local_only_flags_a_done_branch_on_no_remote_once_until_pushed(env):
    p = make(env)
    from ttp import daemon as dm
    from ttp.cli import status_text
    from ttp.web import health
    remote = env["tmp"] / "remote.git"
    subprocess.run(["git", "clone", "-q", "--bare", str(env["repo"]), str(remote)], check=True)
    subprocess.run(["git", "-C", str(env["repo"]), "remote", "add", "origin", str(remote)], check=True)
    tid, path, branch = _code_task(p, "local work")
    _commit_file(path, "a")
    _commit_file(path, "b")
    t_pushed, pushed, pushed_branch = _code_task(p, "pushed work")
    _commit_file(pushed, "c")
    _git_out(pushed, "push", "-q", "origin", f"HEAD:refs/heads/{pushed_branch}")
    d = _local_only_daemon(p)
    _check_local_only(d)
    ev = _local_only_events(p)
    assert [e["task"] for e in ev] == [tid], ev
    assert f"task #{tid}'s branch {branch} exists only on this machine, 2 commits ahead" in ev[0]["text"]
    assert f"1 done task with work only on this machine (branch not on any remote): #{tid} {branch} (2 commits)" \
        in status_text(p)
    assert health(p, p.db)["local_only"]
    d._local_only_due = 0
    _check_local_only(d)
    assert len(_local_only_events(p)) == 1   # one event, not one per check
    _git_out(path, "push", "-q", "origin", f"HEAD:refs/heads/{branch}")
    d._local_only_due = 0
    _check_local_only(d)
    assert p.db.kv(dm.KV_LOCAL_ONLY) is None and "only on this machine" not in status_text(p)
    assert len(_local_only_events(p)) == 1


def test_local_only_skips_a_repo_without_a_remote_and_drops_a_cancelled_task(env):
    p = make(env)
