def _hand_off(env, p, result: dict, kind="work"):
    from ttp.daemon import Daemon
    from ttp.providers.base import RunUsage as Usage
    tid = p.db.add_task("hand-off", "spec", kind=kind, tier="standard", origin="coordinator")
    p.db.update_task(tid, status="running")
    run_dir = env["tmp"] / f"run-{tid}"
    run_dir.mkdir()
    (run_dir / "result.json").write_text(json.dumps(result))
    Daemon(p.base)._finish_worker({"task": tid}, Usage(cost_usd=1.0), "ok", run_dir)
    ids = [e["id"] for e in p.db.q("SELECT id FROM events WHERE task=? AND status='queued' ORDER BY id", (tid,))]
    return tid, run_dir, ids


def test_a_waiting_task_runs_only_once_its_probe_passes(env, monkeypatch, tmp_path):
    p = make(env)
    from ttp import daemon as dmod
    flag = tmp_path / "board-free"
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    monkeypatch.setenv("TTP_FAKE_RESULT", json.dumps(
        {"status": "waiting", "summary": "all boards reserved", "waiting_for": "a free board",
         "retry_after_s": 3600, "retry_when": f"test -f {shlex.quote(str(flag))}"}))
    tid = p.db.add_task("measure on a board", "needs a board", kind="work", tier="light", origin="user")
    d = dmod.Daemon(p.base)
    assert _run_until(d, p, lambda: p.db.task(tid)["status"] == "queued" and p.db.task(tid)["attempts"] == 0
                      and p.db.task(tid)["not_before"] and not p.db.q("SELECT id FROM runs WHERE status='running'"))
    runs = lambda: len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,)))
    assert runs() == 1
    for _ in range(6):
        d.tick()
        time.sleep(0.2)
    assert runs() == 1 and d._probed.get(tid), "the task ran while its probe was failing, or never probed"
    assert json.loads(p.db.task(tid)["result"])["waiting_since"] > time.time() - 120
    monkeypatch.setenv("TTP_FAKE_RESULT", json.dumps({"status": "done", "summary": "measured"}))
    flag.write_text("")
    assert _run_until(d, p, lambda: p.db.task(tid)["status"] == "done", timeout=30)
    assert runs() == 2


def _stop_all(p):
    for r in p.db.q("SELECT dir FROM runs WHERE status='running'"):
        if r["dir"]:
            (pathlib.Path(r["dir"]) / "STOP").write_text("cancel")


def test_one_dispatch_tick_does_not_commit_past_the_caps(env):
    p = make(env)
    from ttp.daemon import Daemon
    p.db.x("UPDATE messages SET handled=1")
    p.db.x("INSERT INTO ledger(ts,provider,account,source,usd) VALUES(?,?,?,?,?)",
           (time.time() - 600, "fake", "", "task:0", 59.0))
    for i in range(6):
        p.db.add_task(f"deep {i}", "s", kind="work", tier="deep", origin="user", budget_usd=25.0)
    light = p.db.add_task("light", "s", kind="work", tier="light", origin="user", budget_usd=5.0)
    d = Daemon(p.base)
    d.update_gates()
    try:
        d.dispatch()
        started = p.db.q("SELECT t.id, t.budget_usd FROM runs r JOIN tasks t ON t.id=r.task "
                         "WHERE r.role!='coordinator'")
    finally:
        _stop_all(p)
    assert 59.0 + sum(r["budget_usd"] for r in started) <= 100.0, started
    assert sum(r["budget_usd"] == 25.0 for r in started) == 1 and light in {r["id"] for r in started}, started
    assert p.db.one("SELECT COUNT(*) n FROM tasks WHERE status='queued'")["n"] == 5, "tasks that did not fit wait"
    huge = p.db.add_task("huge", "s", kind="work", tier="deep", origin="user", budget_usd=150.0)
    d.dispatch()
    _stop_all(p)
    assert p.db.task(huge)["status"] == "blocked", "a task that can never fit must say so, not wait forever"


def _until(flag):
    """A command that runs until the file `flag` exists: the test decides when it ends."""
    return ["sh", "-c", f"while [ ! -e {shlex.quote(str(flag))} ]; do sleep 0.05; done"]


def _exclusive_run_detaching(p, task_id, run_id, run_dir, job_cmd, wait=True, opts=()):
    """A run supervisor of exclusive task `task_id` holding the board, whose agent detaches `job_cmd`
    (with `ttp detach` options `opts`) and ends at once, as a worker that hands off `waiting` on its job does."""
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    run_dir.mkdir(parents=True)
    (run_dir / "prompt.md").write_text("x")
    (run_dir / "run.json").write_text(json.dumps({
        "argv": [sys.executable, str(TTP), "detach", "job", *opts, "--", *job_cmd],
        "env": {"TTP_TASK": str(task_id), "TTP_RUN_ID": str(run_id), "TTP_RUN_DIR": str(run_dir),
                "TTP_PROJECT": str(p.base)},
        "cwd": str(p.root), "timeout_s": 60, "provider": "fake", "holds": str(p.state / "holds"),
        "exclusive": [{"resource": "board", "paths": [str(x) for x in d._slot_paths("board")],
                       "reserve": str(d._reserve_path("board")), "holder": f"task #{task_id}"}]}))
    proc = subprocess.Popen([sys.executable, "-m", "ttp.runner", str(run_dir)], cwd=str(RUNTIME),
                            env={**os.environ, "PYTHONPATH": str(RUNTIME)})
    if wait:
        assert proc.wait(timeout=60) == 0
    return proc


def _board_task(p, title):
    from ttp import coordinator as coord
    assert coord.apply(p, [{"type": "task_add", "title": title, "spec": "s", "tier": "light",
                            "resources": ["board"], "exclusive": True}]) == []
    return p.db.one("SELECT * FROM tasks WHERE title=?", (title,))


def _until_true(cond, timeout=20):
    deadline = time.time() + timeout
    while time.time() < deadline and not cond():
        time.sleep(0.05)
    return cond()


def test_an_exclusive_hold_outlives_the_run_while_its_detached_job_runs_and_ends_with_its_rc(env, tmp_path):
    p = make(env)
    from ttp import hold, locks
    from ttp.daemon import Daemon
    mine, other = _board_task(p, "flash"), _board_task(p, "other")
    run_dir, release = p.runs / "41", tmp_path / "release"
    _exclusive_run_detaching(p, mine["id"], 41, run_dir, _until(release))
    d = Daemon(p.base)
    paths = d._slot_paths("board")
    try:
        # The agent has ended, its job has not: the board stays the task's, for others and ttp lock alike.
        assert (run_dir / "exit.json").exists() and not (run_dir / "job.rc").exists()
        assert not locks.any_free(paths), "the run's hold lapsed while its detached job still ran"
        assert locks.held_labels(paths) == [f"task #{mine['id']} (run 41), detached jobs"]
        assert not d._resources_free(other), "another exclusive task could take the board from a live job"
        rc = subprocess.run([sys.executable, str(TTP), "lock", "--timeout", "0.5", "board", "--", "true"],
                            env=dict(os.environ, TTP_PROJECT=str(p.base))).returncode
        assert rc == 75, "ttp lock got the board while a detached job of its exclusive run still ran"
        rec = hold.read(run_dir)
        assert rec["state"] == "holding" and rec["jobs"] == [str((run_dir / "job.rc").resolve())]
        d.tend_holds()
        assert not locks.any_free(paths), "tending a live keeper let its hold go"
    finally:
        release.touch()
    assert _until_true(lambda: (run_dir / "job.rc").exists())
    assert _until_true(lambda: locks.any_free(paths)), "the hold outlived the job's .rc"
    assert hold.read(run_dir)["state"] == "released"
    d.tend_holds()
    ev = p.db.one("SELECT * FROM events WHERE kind='hold_released'")
    assert ev and ev["task"] == mine["id"] and "every detached job of the run ended" in ev["text"]
    assert not list((p.state / "holds").glob("*.json")), "an ended hold stayed registered"
    assert d._resources_free(other)


def test_a_run_without_live_detached_jobs_lets_its_exclusive_hold_go_at_once(env, tmp_path):
    p = make(env)
    from ttp import hold, locks
    from ttp.daemon import Daemon
    mine = _board_task(p, "flash")
    run_dir = p.runs / "42"
    _exclusive_run_detaching(p, mine["id"], 42, run_dir, ["true"])
    assert _until_true(lambda: (run_dir / "job.rc").exists())
    paths = Daemon(p.base)._slot_paths("board")
    # The job may still be running when the agent ends; then its keeper lets go within a poll.
    assert _until_true(lambda: locks.any_free(paths))
    assert (hold.read(run_dir) or {}).get("state") in (None, "released")


def test_an_exclusive_hold_kept_for_a_detached_job_ends_when_the_job_dies(env, tmp_path):
    p = make(env)
    from ttp import hold, locks
    from ttp.daemon import Daemon
    mine = _board_task(p, "flash")
    run_dir = p.runs / "43"
    _exclusive_run_detaching(p, mine["id"], 43, run_dir, ["sleep", "600"])
    paths = Daemon(p.base)._slot_paths("board")
    assert not locks.any_free(paths)
    pid = json.loads((run_dir / "detached.json").read_text())[0]["pid"]
    os.killpg(pid, signal.SIGKILL)   # killed: it never writes its .rc
    assert _until_true(lambda: locks.any_free(paths)), "a dead job's hold was never released"
    assert not (run_dir / "job.rc").exists() and hold.read(run_dir)["state"] == "released"


def test_an_exclusive_hold_for_a_detached_job_survives_a_daemon_restart_and_a_dead_keeper(env, tmp_path):
    p = make(env)
    from ttp import hold, locks
    from ttp.daemon import Daemon
    mine, other = _board_task(p, "flash"), _board_task(p, "other")
    run_dir, release = p.runs / "44", tmp_path / "release"
    _exclusive_run_detaching(p, mine["id"], 44, run_dir, _until(release))
    paths = Daemon(p.base)._slot_paths("board")
    try:
        keeper = hold.read(run_dir)["keeper"]
        # A daemon restart: the keeper is no child of the daemon, and a new daemon leaves it be.
        d = Daemon(p.base)
        d.tend_holds()
        assert hold.read(run_dir)["keeper"] == keeper and not locks.any_free(paths)
        assert not d._resources_free(other)
        # The keeper dies (`ttp stop --kill`, a crash) while the job runs: the next tend takes the board again.
        os.killpg(keeper, signal.SIGKILL)
        assert _until_true(lambda: locks.any_free(paths))
        d = Daemon(p.base)
        d.tend_holds()
        rec = hold.read(run_dir)
        assert rec["state"] == "holding" and rec["keeper"] != keeper and rec["rebuilt"] == 1
        assert not locks.any_free(paths), "a dead keeper's hold was not rebuilt from the detach state"
        assert p.db.one("SELECT 1 FROM events WHERE kind='hold_rebuilt'")
        assert not d._resources_free(other)
    finally:
        release.touch()
    assert _until_true(lambda: locks.any_free(paths)), "the rebuilt hold outlived the job"
    # A keeper gone with its jobs (a reboot) is released on the next tend, not rebuilt.
    run_dir2 = p.runs / "45"
    _exclusive_run_detaching(p, mine["id"], 45, run_dir2, ["sleep", "600"])
    rec = hold.read(run_dir2)
    os.killpg(rec["keeper"], signal.SIGKILL)
    os.killpg(json.loads((run_dir2 / "detached.json").read_text())[0]["pid"], signal.SIGKILL)
    assert _until_true(lambda: locks.any_free(paths))
    assert _until_true(lambda: locks.job_ended(pathlib.Path(rec["jobs"][0])))
    Daemon(p.base).tend_holds()
    assert hold.read(run_dir2)["state"] == "released" and locks.any_free(paths)
    assert "while no keeper ran" in p.db.one("SELECT text FROM events WHERE kind='hold_released' "
                                             "ORDER BY id DESC LIMIT 1")["text"]


def test_a_slot_handed_to_a_keeper_names_the_keeper_as_its_live_holder_until_it_exits(env, tmp_path, monkeypatch):
    """The run supervisor that took an exclusive slot exits once its agent ends; the keeper of the run's
    detached jobs then holds it. `ttp lock --json`, the holder lines and `ttp machines activity` name the
    keeper's pid (alive), with via "keeper" and the exited taker's pid apart, and nothing reaps the slot or
    calls it stale while the keeper lives. Once the keeper exits the slot is free again."""
    p = make(env)
    from ttp import activity, hold, locks, responsibilities
    from ttp.daemon import Daemon
    mine = _board_task(p, "flash")
    run_dir, release = p.runs / "46", tmp_path / "release"
    taker = _exclusive_run_detaching(p, mine["id"], 46, run_dir, _until(release)).pid
    d = Daemon(p.base)
    paths = d._slot_paths("board")

    def probe_json():
        r = subprocess.run([sys.executable, str(TTP), "lock", "--json", "board"], capture_output=True, text=True,
                           env=dict(os.environ, TTP_PROJECT=str(p.base)))
        return r.returncode, json.loads(r.stdout)

    try:
        keeper = hold.read(run_dir)["keeper"]
        assert not locks._alive(taker) and locks._alive(keeper)
        p.db.x("UPDATE tasks SET status='done' WHERE id=?", (mine["id"],))   # a done task: only a live pid keeps it
        rc, got = probe_json()
        assert rc == 75 and not got["free"] and len(got["holders"]) == 1, got
        h = got["holders"][0]
        assert h["holder"] == f"task #{mine['id']} (run 46), detached jobs" and h["pid"] == keeper, h
        assert h["alive"] is True and h["via"] == "keeper" and h["taker_pid"] == taker and not h["stale"], h
        assert f"pid {keeper} alive" in got["line"] and "stale" not in got["line"], got["line"]
        assert f"pid {keeper} alive" in locks.holders_now(paths, p)[0], locks.holders_now(paths, p)
        monkeypatch.setattr(responsibilities, "_names", lambda _alias, res: res == "board")
        view = {"holders": []}
        activity._current("here", p.name, p.state / "locks", view)
        assert [(x["pid"], x["alive"], x["via"], x["taker_pid"]) for x in view["holders"]] == \
            [(keeper, True, "keeper", taker)], view
        d.tend_holds()
        assert not locks.any_free(paths) and hold.read(run_dir)["keeper"] == keeper, "a live keeper's hold was reaped"
    finally:
        release.touch()
    assert _until_true(lambda: locks.any_free(paths)), "the keeper's hold outlived its job"
    rc, got = probe_json()
    assert rc == 0 and got["free"] and got["holders"] == [], got
    assert locks.holders_now(paths, p) == [] and hold.read(run_dir)["state"] == "released"


def test_a_hold_kept_for_a_closed_task_alerts_once_low_never_releases_and_clears_once_released(env, tmp_path):
    p = make(env)
    from ttp import hold, locks
    from ttp.daemon import Daemon, STALE_HOLDS_KEY
    mine = _board_task(p, "flash")
    run_dir, release = p.runs / "46", tmp_path / "release"
    _exclusive_run_detaching(p, mine["id"], 46, run_dir, _until(release))
    paths = Daemon(p.base)._slot_paths("board")

    def alerts():
        return p.db.q("SELECT * FROM messages WHERE kind='alert' AND ref='hold-stale:46'")

    def age(hours):   # the hold has been kept this long
        rec = hold.read(run_dir)
        rec["since"] = time.time() - hours * 3600
        (run_dir / hold.RECORD).write_text(json.dumps(rec))

    try:
        age(7)
        Daemon(p.base).tend_holds()
        assert not alerts(), "a hold kept for an open task's jobs was alerted"
        p.db.update_task(mine["id"], status="done")
        age(5)
        Daemon(p.base).tend_holds()
        assert not alerts(), "a hold alerted before the default 6 h"
        p.set_config("budget.stale_hold_alert_s", 4 * 3600)   # configurable
        d = Daemon(p.base)
        d.tend_holds()
        d.tend_holds()
        got = alerts()
        assert len(got) == 1 and got[0]["severity"] == "low", got
        rc = str((run_dir / "job.rc").resolve())
        assert f"#{mine['id']}" in got[0]["text"] and "board" in got[0]["text"] and rc in got[0]["text"]
        # Never released: the job may still use the board.
        assert hold.read(run_dir)["state"] == "holding" and not locks.any_free(paths)
        assert not (run_dir / "job.rc").exists()
        Daemon(p.base).tend_holds()   # a daemon restart does not repeat it
        assert len(alerts()) == 1
    finally:
        release.touch()
    assert _until_true(lambda: locks.any_free(paths))
    Daemon(p.base).tend_holds()
    cleared = p.db.q("SELECT * FROM messages WHERE kind='resolved' AND ref='hold-stale:46'")
    assert len(cleared) == 1 and "released" in cleared[0]["text"], cleared
    assert not p.db.kv(STALE_HOLDS_KEY)
    Daemon(p.base).tend_holds()
    assert len(p.db.q("SELECT 1 FROM messages WHERE ref='hold-stale:46'")) == 2


def test_a_later_run_of_the_same_task_takes_over_the_hold_its_detached_job_keeps(env, tmp_path):
    p = make(env)
    from ttp import hold, locks
    from ttp.daemon import Daemon
    mine = _board_task(p, "flash")
    run_dir, release = p.runs / "46", tmp_path / "release"
    _exclusive_run_detaching(p, mine["id"], 46, run_dir, _until(release))
    d = Daemon(p.base)
    paths = d._slot_paths("board")
    try:
        assert not locks.any_free(paths)
        assert d._resources_free(mine), "a task was kept out by the hold kept for its own job"
        # Its next run takes the board over; the job still runs when that run ends, so the hold goes on.
        _exclusive_run_detaching(p, mine["id"], 47, p.runs / "47", ["true"])
        assert hold.read(run_dir)["state"] == "handed_over"
        rec = hold.read(p.runs / "47")
        assert rec["state"] == "holding" and str((run_dir / "job.rc").resolve()) in rec["jobs"]
        assert not locks.any_free(paths), "the board lapsed between the two runs of the task"
    finally:
        release.touch()
    assert _until_true(lambda: locks.any_free(paths)), "the handed-over hold outlived the earlier run's job"


def test_a_stale_reservation_never_wedges_the_resource(env):
    p = make(env)
    from ttp import locks
    mark = locks.reserve_path(p.state / "locks", "board")
    mark.parent.mkdir(parents=True, exist_ok=True)
    mark.write_text(json.dumps({"holder": "task #9", "since": 0, "ts": time.time() - locks.RESERVE_STALE_S - 5}))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost", TTP_PROJECT=str(p.base))
    rc = subprocess.run([sys.executable, str(TTP), "lock", "--timeout", "2", "board", "--", "true"],
                        env=run_env).returncode
    assert rc == 0, "a reservation nobody refreshes still held the resource"
    locks.reserve(mark, "task #3")
    assert locks.reserved_by(mark) == "task #3", "a stale reservation blocked a new one"


def test_a_lock_wait_is_progress_and_gives_up_with_75(env, tmp_path):
    p = make(env)
    run_dir = tmp_path / "wrun"
    run_dir.mkdir()
    (run_dir / "run.json").write_text(json.dumps({"stall_s": 2}))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost", TTP_PROJECT=str(p.base))
    held, release = tmp_path / "held", tmp_path / "release"
    holder = subprocess.Popen([sys.executable, str(TTP), "lock", "board", "--", "sh", "-c",
                               f"touch {shlex.quote(str(held))}; {shlex.join(_until(release))}"], env=run_env)
    try:
        _wait_for_file(held, holder)
        t0 = time.time()
        # The holder keeps the board until this command has returned: only a give-up ends it.
        r = subprocess.run([sys.executable, str(TTP), "lock", "board", "--", "true"], capture_output=True,
                           text=True, env={**run_env, "TTP_RUN_DIR": str(run_dir)}, timeout=60)
        waited = time.time() - t0
    finally:
        release.touch()
        holder.wait(timeout=30)
    # half the stall limit, not forever
    assert r.returncode == 75 and "stayed busy for 1 s" in r.stderr and waited >= 1, (r.returncode, r.stderr, waited)
    assert "waiting for board" in (run_dir / "progress.md").read_text(), "a wait looked like a stall"


def test_a_lock_wait_that_gives_up_on_its_first_poll_still_shows_as_progress(env, tmp_path):
    # A busy host: the first poll already passes the cap. The give-up must not skip the progress line.
    p = make(env)
    run_dir = tmp_path / "wrun"
    run_dir.mkdir()
    (run_dir / "run.json").write_text(json.dumps({"stall_s": 0.002}))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost", TTP_PROJECT=str(p.base))
    held, release = tmp_path / "held", tmp_path / "release"
    holder = subprocess.Popen([sys.executable, str(TTP), "lock", "board", "--", "sh", "-c",
                               f"touch {shlex.quote(str(held))}; {shlex.join(_until(release))}"], env=run_env)
    try:
        _wait_for_file(held, holder)
        r = subprocess.run([sys.executable, str(TTP), "lock", "board", "--", "true"], capture_output=True,
                           text=True, env={**run_env, "TTP_RUN_DIR": str(run_dir)}, timeout=60)
    finally:
        release.touch()
        holder.wait(timeout=30)
    assert r.returncode == 75 and "stayed busy" in r.stderr, (r.returncode, r.stderr)
    assert "waiting for board" in (run_dir / "progress.md").read_text(), "a wait looked like a stall"


def _wait_for_file(path, proc, timeout=60):
    deadline = time.time() + timeout
    while not path.exists():
        assert time.time() < deadline and proc.poll() is None, f"{path.name} never appeared"
        time.sleep(0.02)


def _no_events(p):
    p.db.x("UPDATE messages SET handled=1")
    p.db.x("UPDATE events SET status='handled'")


def _turns(p):
    return p.db.one("SELECT COUNT(*) n FROM runs WHERE role='coordinator'")["n"]


def test_the_idle_slot_wake_skips_usage_billed_and_waiting_projects(env):
    p = make(env)
    from ttp.daemon import Daemon
    _no_events(p)
    d = Daemon(p.base)
    d.update_gates()
    assert d.gates[d.cfg.get("core_provider", "claude")].regime == "caps"
    p.db.set_kv("last_coordinator_turn", time.time() - 301)
    d.maybe_coordinate()
    assert _turns(p) == 0, "an idle usage-billed project woke the coordinator"
    tid = p.db.add_task("needs the board", "s", kind="work", tier="light", origin="user")
    p.db.update_task(tid, not_before=time.time() + 1800)
    d.maybe_coordinate()
    _stop_all(p)
    assert _turns(p) == 0, "woken while the only task waits on its retry timer"


def _stall_events(p):
    return p.db.q("SELECT * FROM events WHERE kind='observation' AND source='daemon' AND fingerprint LIKE 'stall:%' "
                  "ORDER BY id")


def _stall_setup(env, monkeypatch=None):
    """A daemon past its start settle with a last worker run 5 h ago, and a check that runs now
    (each call is a fresh check, as if a minute had passed)."""
    from ttp.daemon import Daemon
    p = make(env)
    _no_events(p)
    now = time.time()
    d = Daemon(p.base)
    d._started = now - 86400
    p.db.x("INSERT INTO runs(task,role,started,ended,status) VALUES(NULL,'worker',?,?,'ok')",
           (now - 5 * 3600, now - 5 * 3600 + 60))

    def check(at):
        d._stall_checked = at - 60
        if monkeypatch:
            monkeypatch.setattr(time, "time", lambda: at)
        d.check_stall()
        return _stall_events(p)
    return p, d, now, check


def test_stall_check_stays_quiet_when_nothing_is_stalled(env, monkeypatch):
    p, d, now, check = _stall_setup(env, monkeypatch)
    assert check(now) == [] and check(now + 4 * 3600) == [], "nothing queued is no stall"
    p.db.add_task("ready", "s", kind="work", tier="light", origin="coordinator")
    d._started = now + 5 * 3600
    assert check(now + 5 * 3600) == [] and check(now + 9 * 3600) == [], \
        "a daemon that just started gives dispatch a chance first; readiness counts again after it"
    d._started = now - 86400
    d.cfg["coordinator"]["stall_wake_h"] = 0
    assert check(now + 10 * 3600) == [] and check(now + 14 * 3600) == [], "stall_wake_h 0 turns the check off"
    d.cfg["coordinator"]["stall_wake_h"] = 3
    assert check(now + 15 * 3600) == []
    d._stall_checked = now + 15 * 3600
    monkeypatch.setattr(time, "time", lambda: now + 19 * 3600)
    d.check_stall()
    assert _stall_events(p) == [], "checks far apart (a paused project) count readiness again"
    assert check(now + 19.5 * 3600) == [] and check(now + 22 * 3600) == []
    assert len(check(now + 22.5 * 3600)) == 1


def _idle_setup(env, monkeypatch):
    """A daemon past its start settle with one device resource ("rig-device") and a green gate of two
    slots; check(at) runs the idle-capacity check at `at` and returns its events."""
    from ttp import budget as bud
    from ttp.daemon import Daemon
    p = make(env)
    _no_events(p)
    now = time.time()
    d = Daemon(p.base)
    d._started = now - 86400
    d.cfg["resources"] = {"rig-device": 1}
    prov = d.cfg.get("core_provider", "claude")
    d.gates = {prov: bud.Gate(provider=prov, regime="windows", max_parallel=2)}
    used = p.db.add_task("ran on the rig", "s", kind="work", tier="light", origin="coordinator",
                         labels=["resource:rig-device"])
    p.db.update_task(used, status="done")
    p.db.x("INSERT INTO runs(task,role,provider,started,ended,status) VALUES(?,'worker',?,?,?,'ok')",
           (used, prov, now - 7200, now - 3600))

    def check(at):
        d._idle_cap_checked = at - 60
        monkeypatch.setattr(time, "time", lambda: at)
        d.check_idle_capacity()
        return p.db.q("SELECT * FROM events WHERE kind='idle_capacity' ORDER BY id")
    return p, d, now, prov, check


def test_idle_capacity_wakes_the_coordinator_once_per_idle_stretch_with_a_long_doubling_rearm(env, monkeypatch):
    p, d, now, prov, check = _idle_setup(env, monkeypatch)
    p.db.x("INSERT INTO runs(task,role,provider,started,status) VALUES(NULL,'worker',?,?,'running')",
           (prov, now - 3600))
    later = p.db.add_task("check the slow CPU job", "s", kind="work", tier="light", origin="coordinator",
                          not_before=now + 3.7 * 3600)
    assert check(now) == [] and check(now + 20 * 60) == [], "idle for less than the grace raises nothing"
    evs = check(now + 26 * 60)
    assert len(evs) == 1, "a device idle past the grace with a free slot and nothing queued raises one event"
    e = evs[0]
    assert e["status"] == "queued" and e["severity"] == "normal" and e["source"] == "daemon"
    assert "rig-device for 26 min" in e["text"] and "1 worker slot(s) free" in e["text"], e["text"]
    assert f"#{later} at " in e["text"] and "(in 3.3 h)" in e["text"], "it names the next scheduled check"
    assert "Running: #None " in e["text"], "it names the running work"
    assert len(check(now + 3.8 * 3600)) == 1, "a ready task dispatch would start comes first"
    p.db.update_task(later, status="done")
    for h in (1, 3, 6):
        assert len(check(now + h * 3600)) == 1, "one event per idle stretch"
    assert len(check(now + 26 * 60 + 6 * 3600)) == 2, "still idle after the rearm: raised once more"
    assert len(check(now + 26 * 60 + 11 * 3600)) == 2, "the next rearm is twice as long"
    assert len(check(now + 26 * 60 + 18 * 3600)) == 3
    # The stretch ends once the device is used; a new one counts its grace afresh.
    t = now + 20 * 3600
    use = p.db.add_task("uses it", "s", kind="work", tier="light", origin="coordinator",
                        labels=["exclusive:rig-device"], not_before=t + 86400)
    assert len(check(t)) == 3
    p.db.update_task(use, status="done")
    assert len(check(t + 60)) == 3 and len(check(t + 20 * 60)) == 3
    assert len(check(t + 26 * 60)) == 4, "a new idle stretch raises once its grace has passed"
    # A restart keeps the stretches: nothing is raised twice.
    from ttp.daemon import Daemon
    d2 = Daemon(p.base)
    d2._started, d2.gates, d2.cfg["resources"] = now - 86400, d.gates, {"rig-device": 1}
    d2._idle_cap_checked = 0.0
    monkeypatch.setattr(time, "time", lambda: t + 30 * 60)
    d2.check_idle_capacity()
    assert p.db.one("SELECT COUNT(*) n FROM events WHERE kind='idle_capacity'")["n"] == 4
    d.cfg["coordinator"]["idle_capacity_s"] = 0
    assert len(check(t + 30 * 3600)) == 4 and not p.db.kv("idle_capacity"), "0 turns it off"


def test_idle_capacity_skips_devices_held_by_a_machine_change_or_not_used_by_the_project(env, monkeypatch):
    from ttp import idlecap
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    p, d, now, prov, check = _idle_setup(env, monkeypatch)
    mm.add("rig", tags="device")
    held = ml.add_change("rig", "holds the broker for a firmware update", "release-hold", "other", expires="2d")
    assert check(now) == [] and check(now + 3600) == [], "a change entry holding its device work: not idle"
    ml.close_change(held["id"], "done")
    power = ml.add_change("rig", "disabled auto power cycle", "enable it", "other", expires="2d")
    assert check(now + 2 * 3600) == [] and len(check(now + 3 * 3600)) == 1, \
        "a change that does not hold device work leaves the device idle capacity"
    ml.close_change(power["id"], "done")
    assert idlecap.holds_work({"what": "paused the job queue"}) and idlecap.holds_work({"what": "drained the box"})
    assert idlecap.holds_work({"what": "disabled the broker service"})
    assert not idlecap.holds_work({"what": "added a log rotation drop-in"})
    assert idlecap.holds_work({"what": "queue is paused"}) and idlecap.holds_work({"what": "device work disabled"})
    # Only a clear phrase holds work: not a bare word elsewhere, a file name or a recovery switch.
    poller = ml.add_change("rig", "broker drop-in sets POLLER_SERVICES=cap-keeper.service so the broker "
                           "stops/starts the cap keeper around reset", "rm it", "other", expires="2d")
    offbus = ml.add_change("rig", "broker auto resets/re-power/reboot/power-cycle off via zz-broker-offbus-hold.conf",
                           "rm it", "other", expires="2d")
    assert not any(idlecap.holds_work(c) for c in (poller, offbus))
    assert not idlecap.holds_work({"what": "the broker stops the cap keeper around reset"})
    assert not idlecap.holds_work({"what": "disabled the broker auto reset"})
    assert len(check(now + 4 * 3600)) == 1 and "rig-device" in (p.db.kv("idle_capacity") or {}), \
        "unrelated open changes leave the device idle capacity"
    ml.close_change(poller["id"], "done")
    ml.close_change(offbus["id"], "done")
    # A device no task of the project named lately is not the project's to fill.
    p.db.x("UPDATE runs SET started=? WHERE status='ok'", (now - 8 * 86400,))
    t = now + 10 * 3600
    assert len(check(t)) == 1 and len(check(t + 3600)) == 1 and not p.db.kv("idle_capacity"), \
        "a device no recent run or open task names raises nothing"
    d.cfg["coordinator"]["idle_capacity_use_days"] = 0
    assert len(check(t + 2 * 3600)) == 1 and len(check(t + 3 * 3600)) == 2, "use_days 0 turns that filter off"
    d.cfg["coordinator"]["idle_capacity_use_days"] = 30
    assert len(check(t + 4 * 3600)) == 2, "a longer window counts the older run"


def test_idle_capacity_device_candidates():
    from ttp import idlecap
    machines = {"rig": {"tags": ["device"]}, "box": {"tags": ["device", "x86"]}, "cpu": {"tags": ["x86"]}}
    cfg = {"device": {"locks": ["board", "board-device"]}, "resources": {"build-dir": 2}}
    got = idlecap.candidates(cfg, {"rig-device", "scratch"}, ["rig", "box", "cpu"], machines)
    assert got == {"board", "rig-device", "box"}, got
    assert idlecap.candidates({}, set(), [], {}) == set(), "a project with no device has no idle capacity"
    assert idlecap.uses("rig", "rig-device") and idlecap.uses("rig-device", "rig") and not idlecap.uses("rig", "box")
    assert idlecap.task_names({"labels": '["needs_device", "exclusive:board-device"]'}, cfg) == {"board"}


def test_codex_workers_may_write_run_state_and_git_metadata(env, monkeypatch):
    from ttp.providers import codex as codex_provider
    monkeypatch.setattr(codex_provider.Codex, "binary", lambda self: "/usr/bin/true")  # never a real agent
    p = make(env)
    p.set_config("pricing", {"codex": {"some-model": [1.0, 0.1, 2.0]}})
    from ttp.daemon import Daemon
    wt = env["tmp"] / "wt"
    subprocess.run(["git", "-C", str(env["repo"]), "worktree", "add", "-q", str(wt)], check=True)
    d = Daemon(p.base)
    tid = p.db.add_task("t", "s", kind="work", tier="light", origin="user")
    rid = d.start_run("worker", "go", "codex", "light", str(wt), task=p.db.task(tid))
    spec = json.loads((p.runs / str(rid) / "run.json").read_text())
    argv = spec["argv"]
    assert argv[-1] == "-", "the prompt on stdin must stay the last argument"
    roots = next(a for a in argv if a.startswith("sandbox_workspace_write.writable_roots="))
    roots = json.loads(roots.split("=", 1)[1])
    assert str(p.state) in roots and str((env["repo"] / ".git").resolve()) in roots
    assert str((env["repo"] / ".git" / "worktrees" / "wt").resolve()) in roots, "the worktree's own gitdir"
    assert spec["prices"] == {"some-model": [1.0, 0.1, 2.0]}, "the runner's budget check must use project prices"
    (p.runs / str(rid) / "STOP").touch()
    crid = d.start_run("coordinator", "decide", "codex", "light", str(p.base), read_only=True)
    assert not any("writable_roots" in a for a in json.loads((p.runs / str(crid) / "run.json").read_text())["argv"])
    (p.runs / str(crid) / "STOP").touch()


def _codex_worker_roots(env, p, cwd):
    """The writable roots the daemon gives a Codex worker in cwd."""
    return _codex_worker_launch(env, p, cwd)[0]


def _codex_worker_launch(env, p, cwd):
    """The writable roots and the environment (as the runner hands it to the agent) the daemon gives
    a Codex worker in cwd."""
    from ttp.providers import codex as codex_provider
    from ttp.daemon import Daemon
    real = codex_provider.Codex.binary
    codex_provider.Codex.binary = lambda self: "/usr/bin/true"   # never a real agent
    try:
        d = Daemon(p.base)
        tid = p.db.add_task("t", "s", kind="work", tier="light", origin="user")
        rid = d.start_run("worker", "go", "codex", "light", str(cwd), task=p.db.task(tid))
    finally:
        codex_provider.Codex.binary = real
    (p.runs / str(rid) / "STOP").touch()
    deadline = time.time() + 30
    while not (p.runs / str(rid) / "exit.json").exists() and time.time() < deadline:
        time.sleep(0.05)
    spec = json.loads((p.runs / str(rid) / "run.json").read_text())
    if spec.get("tmp_dir"):
        # The runner removed it when the stand-in agent ended; a live worker has it.
        pathlib.Path(spec["tmp_dir"]).mkdir(exist_ok=True)
    roots = next(a for a in spec["argv"] if a.startswith("sandbox_workspace_write.writable_roots="))
    return json.loads(roots.split("=", 1)[1]), {**os.environ, **spec["env"]}


def test_sandboxed_workers_get_a_private_writable_temp_dir(env):
    # On macOS git is an xcrun shim; in Codex's sandbox xcrun could not write its cache under /tmp
    # (`couldn't create cache file /tmp/xcrun_db-...`), so git failed. A fenced worker gets its own
    # temp dir, a short one (shorttmp: AF_UNIX path limit), inside its writable roots and outside
    # the worktree; run.json records it, and the run's end removes it.
    from ttp import runner, shorttmp
    p = make(env)
    repo = env["repo"]
    roots, run_env = _codex_worker_launch(env, p, repo)
    tmp = pathlib.Path(run_env["TMPDIR"])
    assert run_env["TMP"] == run_env["TEMP"] == str(tmp) and tmp.is_dir()
    assert shorttmp.owned(tmp), "a short dir of its own"
    assert any(tmp.is_relative_to(r) for r in roots), roots
    assert str(shorttmp.root()) in roots, "the worker may make the short dirs of its checks and jobs"
    (tmp / "scratch").write_text("x")
    assert subprocess.run(["git", "-C", str(repo), "status", "--porcelain"],
                          capture_output=True, text=True).stdout == "", "never committed with the work"
    run_dir = next(d for d in p.runs.iterdir()
                   if json.loads((d / "run.json").read_text()).get("tmp_dir") == str(tmp))
    runner.remove_private(run_dir)   # also what the daemon does for a runner that died
    assert not tmp.exists()
    # An unfenced provider (no writable roots) keeps the caller's temp dir.
    from ttp.providers import claude as claude_provider
    from ttp.daemon import Daemon
    real = claude_provider.Claude.binary
    claude_provider.Claude.binary = lambda self: "/usr/bin/true"   # never a real agent
    try:
        tid = p.db.add_task("t", "s", kind="work", tier="light", origin="user")
        rid = Daemon(p.base).start_run("worker", "go", "claude", "light", str(repo), task=p.db.task(tid))
    finally:
        claude_provider.Claude.binary = real
    (p.runs / str(rid) / "STOP").touch()
    assert "TMPDIR" not in json.loads((p.runs / str(rid) / "run.json").read_text())["env"]
    assert not (p.runs / str(rid) / "tmp").exists()


def test_codex_workers_may_write_the_shared_lock_root_only(env):
    # `ttp lock <machine>` on a machine shared across projects takes ~/.tt-project/locks/<machine>/
    # <machine>.0.lock; a workspace-write sandbox made that read-only, so the lock failed.
    p = make(env)
    p.set_config("shared_resources", ["box1"])
    from ttp import locks as lk
    from ttp import shared
    roots = _codex_worker_roots(env, p, p.base)
    slot = lk.slot_paths(shared.locks_dir(p, "box1"), "box1", 1)[0]
    assert slot == env["home"] / "locks" / "box1" / "box1.0.lock", "the shared lock root must not move"
    assert any(slot.is_relative_to(r) for r in roots), roots
    assert str(env["home"] / "locks") in roots and (env["home"] / "locks").is_dir()
    assert str(env["home"]) not in roots, "only the lock root, not the rest of the user's tt-project home"


def _codex_sandbox(cwd, roots):
    """argv prefix that runs a command in Codex's workspace-write sandbox writing only cwd and
    roots (not the temp dir the test lives in); None when no Codex sandbox works here. /tmp stays
    writable, as for a real worker, when the test is elsewhere (macOS: under $TMPDIR): xcrun, which
    git calls there, falls back to /tmp for its cache."""
    import shutil
    exe = shutil.which("codex")
    if not exe:
        return None
    in_tmp = pathlib.Path(cwd).resolve().is_relative_to(pathlib.Path("/tmp").resolve())
    argv = [exe, "sandbox", "-c", 'sandbox_mode="workspace-write"',
            "-c", f"sandbox_workspace_write.exclude_slash_tmp={'true' if in_tmp else 'false'}",
            "-c", "sandbox_workspace_write.exclude_tmpdir_env_var=true",
            "-c", "sandbox_workspace_write.writable_roots=" + json.dumps([str(r) for r in roots]), "--"]
    probe = pathlib.Path(cwd) / "probe"
    try:
        r = subprocess.run(argv + ["sh", "-c", f"touch {probe} && ! touch {pathlib.Path(cwd).parent}/outside"],
                           cwd=cwd, capture_output=True, timeout=60)
    except (OSError, subprocess.TimeoutExpired):
        return None
    return argv if r.returncode == 0 and probe.exists() else None


def test_sandboxed_codex_worker_can_git_add_in_a_linked_worktree(env):
    # Codex makes the gitdir a worktree's `.git` file points to (<common>/worktrees/<name>) read-only
    # even inside a writable common .git, so `git add` failed creating index.lock there (EROFS).
    p = make(env)
    wt = env["tmp"] / "wt-add"
    subprocess.run(["git", "-C", str(env["repo"]), "worktree", "add", "-q", str(wt)], check=True)
    gitdir = (env["repo"] / ".git" / "worktrees" / "wt-add").resolve()
    roots, run_env = _codex_worker_launch(env, p, wt)
    assert str(gitdir) in roots and str(p.state) in roots, roots
    assert not any(pathlib.Path(r) != p.state and p.state.is_relative_to(r) for r in roots), \
        "nothing above state/ becomes writable"
    sandbox = _codex_sandbox(wt, roots)
    if sandbox is None:
        pytest.skip("no working Codex sandbox on this machine")
    (wt / "new.txt").write_text("x")
    add = subprocess.run(sandbox + ["git", "add", "new.txt"], cwd=wt, env=run_env, capture_output=True, text=True)
    assert add.returncode == 0, add.stderr
    assert "new.txt" in subprocess.run(["git", "-C", str(wt), "diff", "--cached", "--name-only"],
                                       capture_output=True, text=True).stdout
    # Without the gitdir root, as before the fix, the same add fails on index.lock.
    old = _codex_sandbox(wt, [r for r in roots if r != str(gitdir)])
    (wt / "other.txt").write_text("y")
    add = subprocess.run(old + ["git", "add", "other.txt"], cwd=wt, env=run_env, capture_output=True, text=True)
    assert add.returncode != 0 and "index.lock" in add.stderr, add.stderr


def test_sandboxed_codex_worker_writes_all_git_metadata_of_a_task_worktree(env, monkeypatch):
    # A task worktree under the project (<root>/tt-project/worktrees/tN) failed `git merge --ff-only`
    # with EROFS on <root>/.git/worktrees/tN/ORIG_HEAD.lock. Every metadata write a worker makes
    # there (ORIG_HEAD, index, HEAD's reflog, branches, tags, packed-refs) must go through.
    for var, val in (("GIT_AUTHOR_NAME", "t"), ("GIT_AUTHOR_EMAIL", "t@t"),
                     ("GIT_COMMITTER_NAME", "t"), ("GIT_COMMITTER_EMAIL", "t@t")):
        monkeypatch.setenv(var, val)
    p = make(env)
    repo = env["repo"]
    _commit(repo, "ahead.txt", "x\n")
    wt = p.worktrees / "t30"
    subprocess.run(["git", "-C", str(repo), "worktree", "add", "-q", "-b", "ttp/t30-x", str(wt), "HEAD~1"],
                   check=True, capture_output=True)
    roots, run_env = _codex_worker_launch(env, p, wt)
    sandbox = _codex_sandbox(wt, roots)
    if sandbox is None:
        pytest.skip("no working Codex sandbox on this machine")
    target = _git_out(repo, "rev-parse", "HEAD")
    script = ("set -e; git merge -q --ff-only " + target + "; echo y > y.txt; git add y.txt; "
              "git commit -qm y; git branch side; git tag t1; git reset -q --soft HEAD~1; "
              "git commit -qm again; git pack-refs --all; git reflog -1")
    r = subprocess.run(sandbox + ["sh", "-c", script], cwd=wt, env=run_env, capture_output=True, text=True)
    assert r.returncode == 0, r.stderr
    assert _git_out(wt, "rev-parse", "HEAD~1") == target and _git_out(wt, "log", "-1", "--format=%s") == "again"
    assert _git_out(repo, "rev-parse", "side", "t1").count("\n") == 1
    # Without the worktree's own gitdir, as before 0.2.101, the merge fails exactly as reported.
    gitdir = _git_out(wt, "rev-parse", "--absolute-git-dir")
    _git_out(wt, "reset", "-q", "--hard", "HEAD~2")
    old = _codex_sandbox(wt, [r for r in roots if r != gitdir])
    r = subprocess.run(old + ["git", "merge", "--ff-only", target], cwd=wt, env=run_env, capture_output=True, text=True)
    assert r.returncode != 0 and "ORIG_HEAD.lock" in r.stderr, r.stderr

def test_ttp_lock_says_plainly_when_the_shared_lock_is_not_writable(env):
    if os.geteuid() == 0:
        pytest.skip("root writes read-only directories")
    p = make(env)
    p.set_config("shared_resources", ["box1"])
    root = env["home"] / "locks" / "box1"
    root.mkdir(parents=True)
    root.chmod(0o500)
    try:
        run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost", TTP_PROJECT=str(p.base))
        out = subprocess.run([sys.executable, str(TTP), "lock", "--timeout", "5", "box1", "--", "true"],
                             env=run_env, capture_output=True, text=True)
    finally:
        root.chmod(0o700)
    assert out.returncode == 2 and "not writable" in out.stderr and str(root) in out.stderr, out.stderr
    assert "Traceback" not in out.stderr
    assert not list((p.state / "locks").glob("box1*")) if (p.state / "locks").exists() else True


def test_codex_and_cursor_price_tokens_with_project_rows(env, tmp_path):
    from ttp.providers import get_provider
    out = tmp_path / "o.jsonl"
    out.write_text(json.dumps({"type": "turn.completed", "usage": {
        "input_tokens": 1_000_000, "cached_input_tokens": 0, "output_tokens": 1_000_000,
        "reasoning_output_tokens": 400_000}}) + "\n")
    u = get_provider("codex").use("m1", {"m1": [1.0, 0.1, 2.0]}).parse(out)
    assert u.output_tokens == 1_000_000, "reasoning tokens are part of output_tokens, not extra"
    assert u.cost_usd == pytest.approx(3.0)
    assert get_provider("codex").use("m1", {"m1": [1.0, 0.1, 2.0]}).cost_so_far(out) == pytest.approx(3.0)
    assert get_provider("codex").use("other", {"m1": [1.0, 0.1, 2.0]}).parse(out).cost_usd == pytest.approx(24.0)
    cur = tmp_path / "c.json"
    cur.write_text(json.dumps({"result": "ok", "usage": {"inputTokens": 1_000_000, "outputTokens": 1_000_000}}))
    assert get_provider("cursor").use("fast", {"fast": [0.5, 0.05, 1.0]}).parse(cur).cost_usd == pytest.approx(1.5)
    assert get_provider("cursor").parse(cur).cost_usd == pytest.approx(18.0)


# A stand-in for the `codex` and `agent` CLIs: answers `--help` and `features list` with
# FAKE_CLI_HELP; otherwise records its argv and stdin, writes result.json when told to, then prints
# FAKE_CLI_STDOUT and FAKE_CLI_STDERR and exits with FAKE_CLI_RC. With FAKE_CLI_PACE it takes that
# many seconds per output line: streamed one by one under stream-json, all at the end otherwise.
FAKE_CLI = """#!{python}
import json, os, sys, time
from pathlib import Path
if "--help" in sys.argv[1:] or sys.argv[1:3] == ["features", "list"]:
    print(os.environ.get("FAKE_CLI_HELP", ""))
    sys.exit(0)
log = Path(os.environ["FAKE_CLI_LOG"])
log.mkdir(parents=True, exist_ok=True)
if sys.argv[1:2] == ["app-server"]:
    # thread/start answers with the session its -c overrides resolve, or FAKE_CLI_SESSION's fields;
    # FAKE_CLI_SESSION "exit" is a CLI that cannot answer.
    with open(log / "app_server.jsonl", "a") as f:
        f.write(json.dumps({{"argv": sys.argv, "cwd": os.getcwd()}}) + "\\n")
    if os.environ.get("FAKE_CLI_SESSION") == "exit":
        sys.exit(1)
    conf = dict(a.split("=", 1) for a in sys.argv[2:] if "=" in a)
    for line in sys.stdin:
        msg = json.loads(line)
        if msg.get("id") == 1:
            print(json.dumps({{"id": 1, "result": {{}}}}), flush=True)
        elif msg.get("id") == 2:
            with open(log / "app_server.jsonl", "a") as f:
                f.write(json.dumps({{"request": msg}}) + "\\n")
            if msg["method"] == "account/rateLimits/read":
                print(json.dumps({{"id": 2, "result": json.loads(os.environ["FAKE_CLI_SESSION"])}}), flush=True)
                continue
            res = {{"model": json.loads(conf.get("model", '"tier-default"')),
                   "reasoningEffort": conf.get("model_reasoning_effort")}}
            res.update(json.loads(os.environ.get("FAKE_CLI_SESSION") or "{{}}"))
            print(json.dumps({{"id": 2, "result": res}}), flush=True)
    sys.exit(0)
(log / "argv.json").write_text(json.dumps(sys.argv))
(log / "cwd.txt").write_text(os.getcwd())
(log / "stdin.txt").write_text(sys.stdin.read())
tmp = os.environ.get("TMPDIR", "")
if tmp and any(tmp.startswith(os.environ[v]) for v in ("TTP_RUN_DIR", "TTP_TEST_SHORT_TMP") if os.environ.get(v)):
    (Path(tmp) / "scratch").mkdir()   # a run's own temp dir only, never the test's
    (Path(tmp) / "scratch" / "basetemp.txt").write_text("x")
    (log / "tmpdir.txt").write_text(tmp)
if os.environ.get("FAKE_CLI_RESULT"):
    (Path(os.environ["TTP_RUN_DIR"]) / "result.json").write_text(os.environ["FAKE_CLI_RESULT"])
pace, streaming = float(os.environ.get("FAKE_CLI_PACE") or 0), "stream-json" in sys.argv
lines = os.environ.get("FAKE_CLI_STDOUT", "").splitlines(keepends=True)
if pace and not streaming:
    time.sleep(pace * len(lines))
for i, line in enumerate(lines):
    if pace and streaming and i:
        time.sleep(pace)
    sys.stdout.write(line)
    sys.stdout.flush()
sys.stderr.write(os.environ.get("FAKE_CLI_STDERR", ""))
sys.exit(int(os.environ.get("FAKE_CLI_RC", "0")))
"""


def _cli_run(env, monkeypatch, provider, stdout, *, stderr="", rc=0, result=None, role="worker",
             read_only=False, schema=None, note=None, before=None, budget_usd=2.0, help_text="", pace=0,
             resume=None, pin=None, session=None):
    """Launch one run of `provider` through the daemon and its detached runner against a fake CLI,
    reap it, and return the project, run row, task row, argv and the stdin the CLI received."""
    bin_dir = env["tmp"] / "fakebin"
    bin_dir.mkdir(exist_ok=True)
    for name in ("codex", "agent"):
        exe = bin_dir / name
        exe.write_text(FAKE_CLI.format(python=sys.executable))
        exe.chmod(0o755)
    log_dir = env["tmp"] / "fakecli"
    monkeypatch.setenv("PATH", f"{bin_dir}{os.pathsep}{os.environ.get('PATH', '')}")
    monkeypatch.setenv("FAKE_CLI_LOG", str(log_dir))
    monkeypatch.setenv("FAKE_CLI_STDOUT", stdout)
    monkeypatch.setenv("FAKE_CLI_STDERR", stderr)
    monkeypatch.setenv("FAKE_CLI_RC", str(rc))
    monkeypatch.setenv("FAKE_CLI_RESULT", json.dumps(result) if result else "")
    monkeypatch.setenv("FAKE_CLI_HELP", help_text)
    monkeypatch.setenv("FAKE_CLI_PACE", str(pace))
    monkeypatch.setenv("FAKE_CLI_SESSION", session if isinstance(session, str) else json.dumps(session or {}))
    p = make(env)
    if before:
        before(p)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = None
    if role != "coordinator":
        tid = p.db.add_task("t", "s", kind="work", tier="light", origin="user", **(pin or {}))
        p.db.update_task(tid, status="running")
    rid = d.start_run(role, "PROMPT-MARKER", provider, "light", str(env["repo"]),
                      task=p.db.task(tid) if tid else None, budget_usd=budget_usd, timeout_s=100,
                      read_only=read_only, schema=schema, note=note, resume=resume)
    exit_file = p.runs / str(rid) / "exit.json"
    deadline = time.time() + 60
    while not exit_file.exists() and time.time() < deadline:
        time.sleep(0.05)
    assert exit_file.exists(), (p.runs / str(rid) / "runner.log").read_text()
    d.reap_runs()
    if not (log_dir / "argv.json").exists() and json.loads(exit_file.read_text()).get("launched") is False:
        return p, p.db.one("SELECT * FROM runs WHERE id=?", (rid,)), p.db.task(tid) if tid else None, None, None
    argv = json.loads((log_dir / "argv.json").read_text())
    assert argv[0] == str(bin_dir / ("codex" if provider == "codex" else "agent")), "not the fake CLI"
    return (p, p.db.one("SELECT * FROM runs WHERE id=?", (rid,)), p.db.task(tid) if tid else None, argv,
            (log_dir / "stdin.txt").read_text())


def _codex_events(*events):
    return "".join(json.dumps(e) + "\n" for e in events)


def _codex_turn(text, inp=1000, cached=0, out=500):
    return [{"type": "thread.started", "thread_id": "th-1"}, {"type": "turn.started"},
            {"type": "item.completed", "item": {"id": "i1", "type": "agent_message", "text": text}},
            {"type": "turn.completed", "usage": {"input_tokens": inp, "cached_input_tokens": cached,
                                                 "output_tokens": out}}]


def test_codex_worker_launches_on_stdin_and_hands_off(env, monkeypatch):
    done = {"status": "done", "summary": "changed the README"}
    p, run, task, argv, stdin = _cli_run(env, monkeypatch, "codex", _codex_events(*_codex_turn("all done")),
                                         result=done)
    cwd = str(env["repo"])
    assert argv[1:3] == ["exec", "--json"] and argv[argv.index("-C") + 1] == cwd
    assert argv[argv.index("-s") + 1] == "workspace-write" and "approval_policy=never" in argv
    assert "model_reasoning_effort=low" in argv and "sandbox_workspace_write.network_access=true" in argv
    assert any(a.startswith("sandbox_workspace_write.writable_roots=") for a in argv)
    assert "--output-schema" not in argv and argv[-1] == "-", "the prompt must arrive on stdin"
    assert "PROMPT-MARKER" in stdin
    assert run["status"] == "ok" and run["exit_code"] == 0 and run["cost_estimated"] == 1
    assert run["input_tokens"] == 1000 and run["output_tokens"] == 500
    assert run["cost_usd"] == pytest.approx((1000 * 4.0 + 500 * 20.0) / 1e6), "priced from the default row"
    assert task["status"] == "done" and task["spent_usd"] == pytest.approx(run["cost_usd"])


def test_sandboxed_worker_temp_dir_is_removed_when_the_run_ends(env, monkeypatch):
    # Run dirs are kept, so a fenced worker's temp files (pytest basetemps, build scratch) that the
    # OS used to clean from /tmp must not pile up in state/: the runner removes the dir at the end.
    done = {"status": "done", "summary": "ok"}
    p, run, task, _, _ = _cli_run(env, monkeypatch, "codex", _codex_events(*_codex_turn("all done")), result=done)
    run_dir = p.runs / str(run["id"])
    from ttp import shorttmp
    tmp = pathlib.Path((env["tmp"] / "fakecli" / "tmpdir.txt").read_text())
    assert shorttmp.owned(tmp), "the agent wrote its scratch into its own (short) temp dir"
    assert json.loads((run_dir / "run.json").read_text())["tmp_dir"] == str(tmp)
    assert not tmp.exists(), "the run's temp dir outlived the run"
    assert (run_dir / "run.json").exists() and (run_dir / "result.json").exists() and (run_dir / "exit.json").exists()
    assert run["status"] == "ok" and task["status"] == "done"


def test_remove_private_removes_only_the_run_temp_dir(env):
    # The daemon's fallback for a runner that died; it never deletes outside the run dir.
    from ttp import runner
    run_dir = env["tmp"] / "runs" / "7"
    (run_dir / "tmp" / "deep").mkdir(parents=True)
    (run_dir / "tmp" / "deep" / "f").write_text("x")
    outside = env["tmp"] / "keep"
    outside.mkdir()
    (run_dir / "run.json").write_text(json.dumps({"private_files": [], "tmp_dir": str(run_dir / "tmp")}))
    runner.remove_private(run_dir)
    assert not (run_dir / "tmp").exists() and (run_dir / "run.json").exists()
    (run_dir / "run.json").write_text(json.dumps({"tmp_dir": str(outside)}))
    runner.remove_private(run_dir)
    assert outside.is_dir(), "a temp dir outside the run dir must never be removed"


def test_codex_error_it_retried_does_not_fail_a_completed_turn(env, monkeypatch):
    turn = _codex_turn("all done")
    out = _codex_events(turn[0], turn[1], {"type": "error", "message": "stream disconnected; retrying 1/5"},
                        *turn[2:])
    _, run, task, _, _ = _cli_run(env, monkeypatch, "codex", out, result={"status": "done", "summary": "ok"})
    assert run["status"] == "ok", "a transient error the turn recovered from failed the run"
    assert task["status"] == "done" and task["attempts"] == 1


def test_codex_failed_turn_is_an_attempt_and_says_why(env, monkeypatch):
    out = _codex_events({"type": "thread.started", "thread_id": "th-1"}, {"type": "turn.started"},
                        {"type": "error", "message": "model is overloaded"},
                        {"type": "turn.failed", "error": {"message": "model is overloaded"}})
    _, run, task, _, _ = _cli_run(env, monkeypatch, "codex", out, rc=1)
    assert run["status"] == "failed" and run["exit_code"] == 1
    assert task["status"] == "queued" and task["attempts"] == 1
    assert "overloaded" in json.loads(task["result"])["summary"], "the failure's reason was lost"
    assert run["cost_usd"] > 0 and run["cost_estimated"] == 1, "a run that reported no usage booked $0"


def test_codex_usage_limit_pauses_the_provider_without_an_attempt(env, monkeypatch):
    out = _codex_events({"type": "turn.failed", "error": {"message": "You've hit your usage limit."}})
    p, run, task, _, _ = _cli_run(env, monkeypatch, "codex", out, rc=1)
    assert run["status"] == "limit" and task["status"] == "queued" and task["attempts"] == 0
    assert p.db.kv("limited:codex")["until"] > time.time()


def test_codex_that_cannot_start_reports_its_stderr(env, monkeypatch):
    err = "error: unexpected argument '--bogus' found\n"
    _, run, task, _, _ = _cli_run(env, monkeypatch, "codex", "", stderr=err, rc=2)
    assert run["status"] == "failed" and task["status"] == "queued"
    assert "unexpected argument" in json.loads(task["result"])["summary"]


def _cursor_result(text, **extra):
    return json.dumps({"type": "result", "subtype": "success", "is_error": False, "duration_ms": 1200,
                       "duration_api_ms": 1100, "result": text, "session_id": "s-1", **extra}) + "\n"


def test_cursor_worker_launches_on_stdin_and_books_spend_without_usage(env, monkeypatch):
    done = {"status": "done", "summary": "changed the README"}
    p, run, task, argv, stdin = _cli_run(env, monkeypatch, "cursor", _cursor_result("all done"), result=done)
    assert argv[1:4] == ["-p", "--output-format", "json"] and argv[argv.index("--workspace") + 1] == str(env["repo"])
    assert argv[argv.index("--model") + 1] == "auto" and "--force" in argv and "--trust" in argv
    assert "PROMPT-MARKER" in stdin, "the prompt must arrive on stdin"
    assert run["status"] == "ok" and task["status"] == "done"
    # Cursor's result carries no usage: the run still spent money, and the caps must count it.
    assert run["cost_usd"] > 0 and run["cost_estimated"] == 1, "a Cursor run booked $0"
    assert p.db.one("SELECT SUM(usd) AS s FROM ledger WHERE provider='cursor'")["s"] == pytest.approx(run["cost_usd"])


