def _timed_out_add(monkeypatch, worktree, after):
    """Replay `git worktree add` timing out on a loaded host: the first add runs, `after(path)` leaves
    what the killed git left behind, then it raises TimeoutExpired; later adds run normally."""
    from pathlib import Path
    real, calls = worktree._git, []

    def git(cwd, *args, **kw):
        out = real(cwd, *args, **kw)
        if args[:2] == ("worktree", "add"):
            calls.append(args)
            if len(calls) == 1:
                after(Path(args[-2]))
                raise subprocess.TimeoutExpired(["git", *args], 120)
        return out
    monkeypatch.setattr(worktree, "_git", git)
    return calls


def _half_made(path):
    """What a `git worktree add` killed during its checkout leaves: locked "initializing", no index."""
    from pathlib import Path
    _git_out(path, "worktree", "lock", "--reason", "initializing", str(path))
    Path(_git_out(path, "rev-parse", "--absolute-git-dir"), "index").unlink()


def test_a_timed_out_workspace_add_that_made_a_whole_worktree_is_reused(env, monkeypatch):
    p = make(env)
    from ttp import worktree
    task = p.db.task(p.db.add_task("slow add", "s", kind="code", tier="light", origin="user"))
    lock = lambda path: _git_out(path, "worktree", "lock", "--reason", "initializing", str(path))  # noqa: E731
    calls = _timed_out_add(monkeypatch, worktree, lock)
    path, branch = worktree.ensure(p, task)
    assert len(calls) == 1, "a whole worktree a timed-out add left was made again"
    assert _git_out(path, "rev-parse", "--abbrev-ref", "HEAD") == branch
    assert _git_out(path, "rev-parse", "HEAD") == _git_out(p.root, "rev-parse", worktree.resolve_base(p))
    assert "locked" not in _git_out(p.root, "worktree", "list", "--porcelain"), "the reused worktree stayed locked"
    assert worktree.ensure(p, task) == (path, branch)


def test_a_half_made_workspace_is_removed_and_made_again(env, monkeypatch):
    p = make(env)
    from ttp import worktree
    task = p.db.task(p.db.add_task("slow checkout", "s", kind="code", tier="light", origin="user"))
    calls = _timed_out_add(monkeypatch, worktree, _half_made)
    path, branch = worktree.ensure(p, task)
    assert len(calls) == 2 and calls[1][2] == "-B", "the branch left with nothing of its own was not remade"
    assert _git_out(path, "status", "--porcelain") == "" and _git_out(path, "rev-parse", "--abbrev-ref", "HEAD") == branch
    assert "locked" not in _git_out(p.root, "worktree", "list", "--porcelain")


def test_a_half_made_workspace_never_deletes_a_branch_with_its_own_commits(env, monkeypatch):
    p = make(env)
    from ttp import worktree
    task = p.db.task(p.db.add_task("retried", "s", kind="code", tier="light", origin="user"))
    path, branch = worktree.ensure(p, task)
    (path / "work.txt").write_text("step 1")
    _git_out(path, "add", ".")
    _git_out(path, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "step 1")
    head = _git_out(path, "rev-parse", "HEAD")
    _git_out(p.root, "worktree", "remove", str(path))
    calls = _timed_out_add(monkeypatch, worktree, _half_made)
    assert worktree.ensure(p, task) == (path, branch)
    assert [c[2] for c in calls] == [str(path), str(path)], "a branch with its own commits was reset"
    assert _git_out(path, "rev-parse", "HEAD") == head and (path / "work.txt").read_text() == "step 1"


@pytest.mark.parametrize("smudge", [False, True])
def test_a_workspace_checkout_skips_git_lfs_downloads_unless_configured(env, monkeypatch, smudge):
    # A checkout that downloads LFS objects outlasts git_timeout and leaves a half-made worktree.
    p = make(env)
    from ttp import worktree
    if smudge:
        p.set_config("worktree.lfs_smudge", True)
    task = p.db.task(p.db.add_task("lfs repo", "s", kind="code", tier="light", origin="user"))
    real, seen = worktree._git, []

    def git(cwd, *args, **kw):
        if args[:2] == ("worktree", "add"):
            seen.append((kw.get("env") or {}).get("GIT_LFS_SKIP_SMUDGE"))
        return real(cwd, *args, **kw)
    monkeypatch.setattr(worktree, "_git", git)
    path, branch = worktree.ensure(p, task)
    assert seen == [None if smudge else "1"]
    assert _git_out(path, "rev-parse", "--abbrev-ref", "HEAD") == branch


def test_a_transient_git_failure_never_removes_a_workspace_with_uncommitted_work(env, monkeypatch):
    p = make(env)
    from ttp import worktree
    task = p.db.task(p.db.add_task("retried", "s", kind="code", tier="light", origin="user"))
    path, branch = worktree.ensure(p, task)
    (path / "work.txt").write_text("uncommitted")
    real_is_git, real_git = worktree.is_git, worktree._git
    # is_git times out once (it answers False then): no reason to call the worktree half-made.
    flaky = [False]
    monkeypatch.setattr(worktree, "is_git", lambda pth: flaky.pop() if flaky else real_is_git(pth))
    assert worktree.ensure(p, task) == (path, branch)
    assert (path / "work.txt").read_text() == "uncommitted"
    # A rev-parse in the worktree, then the worktree list, time out once each: ensure raises and
    # leaves everything as it is; the next try reuses it.
    for failing in ("rev-parse", "list"):
        hit = []

        def git(cwd, *args, **kw):
            if failing in args[:2] and not hit:
                hit.append(args)
                raise subprocess.TimeoutExpired(["git", *args], 1)
            return real_git(cwd, *args, **kw)
        monkeypatch.setattr(worktree, "_git", git)
        with pytest.raises((RuntimeError, subprocess.SubprocessError)):
            worktree.ensure(p, task)
        assert hit and (path / "work.txt").read_text() == "uncommitted", f"a failing {failing} removed the work"
        assert worktree.ensure(p, task) == (path, branch)
        assert (path / "work.txt").read_text() == "uncommitted"


def test_a_plain_folder_at_a_workspace_path_is_moved_aside_never_deleted(env):
    # A copy restored from another host left a folder git does not know at the task's worktree path:
    # ensure moves it to worktrees/.stale-<UTC time>/<name>, says so, and makes the worktree.
    p = make(env)
    from ttp import worktree
    task = p.db.task(p.db.add_task("restored", "s", kind="code", tier="light", origin="user"))
    path = p.worktrees / f"t{task['id']}"
    (path / "sub").mkdir(parents=True)
    (path / "sub" / "old.txt").write_text("keep me")
    assert worktree.ensure(p, task)[0] == path
    assert worktree.is_git(path) and not (path / "sub").exists()
    stale = [d for d in p.worktrees.iterdir() if d.name.startswith(worktree.STALE_PREFIX)]
    assert len(stale) == 1 and re.fullmatch(r"\.stale-\d{8}T\d{6}Z", stale[0].name)
    assert (stale[0] / path.name / "sub" / "old.txt").read_text() == "keep me"
    assert f"moved aside to {stale[0] / path.name}" in worktree.recovery_note(p, task)
    # A second stray folder at the same path: moved aside too, the first copy untouched.
    _git_out(p.root, "worktree", "remove", "--force", str(path))
    path.mkdir()
    (path / "x").write_text("x")
    worktree.ensure(p, task)
    kept = sorted(str(f.relative_to(p.worktrees)).split("/", 1)[1] for f in p.worktrees.glob(".stale-*/*/**/*")
                  if f.is_file())
    assert kept == [f"{path.name}/sub/old.txt", f"{path.name}/x"]


def test_a_workspace_locked_initializing_with_an_index_and_edits_is_kept_and_reused(env):
    p = make(env)
    from ttp import worktree
    task = p.db.task(p.db.add_task("retried", "s", kind="code", tier="light", origin="user"))
    path, branch = worktree.ensure(p, task)
    tracked = next(f for f in _git_out(path, "ls-files").splitlines() if (path / f).is_file())
    (path / tracked).write_text("edited")
    (path / "new.txt").write_text("untracked")
    _git_out(path, "worktree", "lock", "--reason", "initializing", str(path))
    assert worktree.ensure(p, task) == (path, branch)
    assert (path / tracked).read_text() == "edited" and (path / "new.txt").read_text() == "untracked"
    assert not [ln for ln in _git_out(p.root, "worktree", "list", "--porcelain").splitlines() if ln.startswith("locked")], \
        "the kept worktree stayed locked"


def test_a_review_publishes_an_unlabelled_code_tasks_head_onto_the_branch_its_spec_names(env, monkeypatch):
    """A code task with no pr_branch label, reviewed by a task whose spec has a `pr_branch:` line:
    `ttp push --own` in the code task's worktree publishes its head onto that branch, fast-forward
    only. A review with no such line, lines naming two branches or a protected branch is refused."""
    from ttp import push
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    _git_out(other, "push", "-q", "origin", "HEAD:refs/heads/feature/x")
    cid = p.db.add_task("work", "s", kind="code")
    _git_out(repo, "checkout", "-q", "-b", f"ttp/t{cid}-work")
    _commit(repo, "work.txt", "work\n")
    head = _git_out(repo, "rev-parse", "HEAD")

    def review(spec):
        return str(p.db.add_task(f"Review #{cid}", spec, kind="review", depends_on=[cid]))
    for spec, why in (("check it", "only this task's own branch"),
                      ("pr_branch: feature/x\npr_branch: feature/y", "only this task's own branch"),
                      ("pr_branch: main", "not one valid branch name")):
        monkeypatch.setenv("TTP_TASK", review(spec))
        with pytest.raises(ValueError, match=why):
            push.own_target(p, repo)
    monkeypatch.setenv("TTP_TASK", review("Deliver it.\npr_branch: feature/x\n"))
    assert push.own_target(p, repo) == ("origin", "feature/x")
    assert _ttp("push", "--own") == 0
    assert _git_out(origin, "rev-parse", "feature/x") == head
    # Never a force: once the branch moved elsewhere, a head that does not contain it is not pushed.
    _git_out(other, "fetch", "-q", "origin")
    _git_out(other, "checkout", "-q", "-b", "fx", "origin/feature/x")
    _commit(other, "theirs.txt", "theirs\n")
    _git_out(other, "push", "-q", "origin", "HEAD:feature/x")
    theirs = _git_out(origin, "rev-parse", "feature/x")
    _commit(repo, "more.txt", "more\n")
    assert _ttp("push", "--own") != 0
    assert _git_out(origin, "rev-parse", "feature/x") == theirs


def test_a_workspace_on_another_branch_without_commits_keeps_its_files_and_is_made_again(env):
    p = make(env)
    from ttp import worktree
    task = p.db.task(p.db.add_task("moved", "s", kind="code", tier="light", origin="user"))
    path, branch = worktree.ensure(p, task)
    _git_out(path, "checkout", "-q", "-b", "elsewhere")
    (path / "work.txt").write_text("mine")
    assert worktree.ensure(p, task) == (path, branch)
    assert _git_out(path, "rev-parse", "--abbrev-ref", "HEAD") == branch and not (path / "work.txt").exists()
    moved = list((p.state / worktree.LEFTOVERS_DIR).glob(f"t{task['id']}-*/work.txt"))
    assert [f.read_text() for f in moved] == ["mine"], "the worktree's file was not kept"
    assert _git_out(p.root, "rev-parse", "--verify", "elsewhere"), "the other branch was deleted"


def test_a_dangling_worktrees_symlink_gives_a_clear_error_and_is_flagged_by_the_integrity_check(env, tmp_path):
    p = make(env)
    from ttp import integrity, worktree
    import shutil
    if p.worktrees.exists():
        shutil.rmtree(p.worktrees)
    gone = tmp_path / "moved-away" / "worktrees"
    p.worktrees.symlink_to(gone)
    task = p.db.task(p.db.add_task("dangling", "s", kind="code", tier="light", origin="user"))
    # Not a bare "[Errno 17] File exists": the link and its missing target, and no retries.
    with pytest.raises(worktree.WorkspaceStuck, match=f"symlink to {gone}, which does not exist"):
        worktree.ensure(p, task)
    res = integrity.check(p)
    assert any(str(p.worktrees) in b and str(gone) in b for b in res["bad"]), res["bad"]
    assert str(gone) in integrity.problem_text(res)
    gone.mkdir(parents=True)
    path, _ = worktree.ensure(p, task)
    assert path.is_dir() and worktree.dangling_root(p) is None
    assert not any(str(gone) in b for b in integrity.check(p)["bad"])


def test_a_carried_branch_workspace_is_reused_when_its_branch_was_never_stored(env, monkeypatch):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    from ttp import worktree
    _git_out(repo, "branch", "fix-loader")
    task = p.db.task(p.db.add_task("Fix PR findings", "s", kind="code", labels=["pr_branch:fix-loader"]))
    path, branch = worktree.ensure(p, task)
    assert branch == "fix-loader"
    (path / "work.txt").write_text("mine")
    # The first attempt failed after making the worktree, so the task row never got its branch.
    assert worktree.ensure(p, task) == (path, "fix-loader")
    assert (path / "work.txt").read_text() == "mine"
    # Another task's worktree on the branch still keeps it from this one.
    other_task = p.db.task(p.db.add_task("Also fix", "s", kind="code", labels=["pr_branch:fix-loader"]))
    assert worktree.on_carried(p, other_task) == ""
    # A worktree an earlier attempt made on the task's own branch (the carried one was held then)
    # stays on it once the carried branch is free.
    opath, obranch = worktree.ensure(p, other_task)
    assert obranch.startswith(f"ttp/t{other_task['id']}-")
    _git_out(repo, "worktree", "remove", "--force", str(path))
    assert worktree.ensure(p, other_task) == (opath, obranch)
    _git_out(opath, "checkout", "-q", "-b", "elsewhere")
    _git_out(opath, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "--allow-empty", "-m", "theirs")
    with pytest.raises(worktree.WorkspaceStuck, match="elsewhere"):
        worktree.ensure(p, other_task)


def test_the_workspace_git_timeout_grows_with_the_hosts_load(env, monkeypatch):
    p = make(env)
    from ttp import worktree
    monkeypatch.setattr(worktree.os, "cpu_count", lambda: 4)
    monkeypatch.setattr(worktree.os, "getloadavg", lambda: (2.0, 0, 0))
    assert worktree.git_timeout(p) == 120
    monkeypatch.setattr(worktree.os, "getloadavg", lambda: (12.0, 0, 0))
    assert worktree.git_timeout(p) == 360
    monkeypatch.setattr(worktree.os, "getloadavg", lambda: (400.0, 0, 0))
    assert worktree.git_timeout(p) == 900
    p.set_config("worktree.git_timeout_max_s", 600)
    assert worktree.git_timeout(p) == 600
    assert worktree.git_timeout(p, 1.5) == 600, "a later attempt's timeout went past the cap"
    monkeypatch.setattr(worktree.os, "getloadavg", lambda: (2.0, 0, 0))
    assert worktree.git_timeout(p, 1.5) == 180


def test_a_task_blocked_on_its_workspace_retries_by_itself_until_the_retries_run_out(env, monkeypatch):
    p = make(env)
    from ttp import waits
    from ttp.daemon import Daemon
    p.set_config("worktree.create_retries", 2)
    # Blocked by an older daemon on the first failure: queued again on start, with no coordinator turn.
    tid = p.db.add_task("stuck", "s", kind="code", tier="light", origin="user")
    p.db.update_task(tid, status="blocked", blocked_reason="workspace: Command 'git worktree add' timed out after 120 seconds")
    d = Daemon(p.base)
    d.retry_workspaces()
    t = p.db.task(tid)
    assert t["status"] == "queued" and t["blocked_reason"].startswith("workspace retry")
    assert waits.wait_kind(t, [])["kind"] != "coordinator"
    # Still failing: queued after a growing backoff, then blocked for the coordinator once they run out.
    for n in (1, 2):
        d._workspace_failed(p.db.task(tid), TimeoutError("timed out"))
        t = p.db.task(tid)
        assert t["status"] == "queued" and t["not_before"] > time.time() + 100 * 2 ** (n - 1)
    d._workspace_failed(p.db.task(tid), TimeoutError("timed out"))
    t = p.db.task(tid)
    assert t["status"] == "blocked" and t["blocked_reason"].startswith("workspace: timed out")
    d.retry_workspaces()
    assert p.db.task(tid)["status"] == "blocked", "a failure that outlasted its retries was queued again"
    p.db.update_task(tid, status="cancelled")
    d.retry_workspaces()
    assert d._workspace_tries(tid) == 0, "a cancelled task's workspace tries were kept"


def test_a_workspace_block_reason_cut_for_length_keeps_its_tail(env):
    # A long error (deep paths) is cut to fit the 400-char reason; what happens next is kept whole.
    p = make(env)
    from ttp import worktree
    from ttp.daemon import Daemon
    p.set_config("worktree.create_retries", 0)
    d = Daemon(p.base)
    for e, tail in ((worktree.WorkspaceStuck("gone from /" + "deep/" * 120), "(not retried: it cannot recover by itself)"),
                    (TimeoutError("timed out in /" + "deep/" * 120), "(after 1 tries)")):
        tid = p.db.add_task("stuck", "s", kind="code", tier="light", origin="user")
        d._workspace_failed(p.db.task(tid), e)
        t = p.db.task(tid)
        assert t["status"] == "blocked" and t["blocked_reason"].startswith("workspace: ")
        assert t["blocked_reason"].endswith(tail) and len(t["blocked_reason"]) == 400


def _dangling_setup(env, monkeypatch):
    """A code task whose worktree was made, holding an uncommitted file, and a daemon whose starts
    are recorded. Returns (p, task, path, daemon, starts)."""
    p = make(env)
    from ttp import worktree
    from ttp.daemon import Daemon
    task = p.db.task(p.db.add_task("lost clone", "s", kind="code", tier="light", origin="user"))
    path, branch = worktree.ensure(p, task)
    p.db.update_task(task["id"], branch=branch)   # recorded, as a run's start does
    task = p.db.task(task["id"])
    (path / "draft.txt").write_text("not committed")
    d, starts = Daemon(p.base), []
    monkeypatch.setattr(d, "start_run", lambda role, prompt, provider, tier, cwd, **k: starts.append(
        (prompt, cwd, k["note"])) or 0)
    return p, task, path, d, starts


def test_a_dangling_worktree_whose_repository_is_gone_is_moved_aside_and_blocks_its_task(env, monkeypatch):
    # After a reboot the clone a worktree pointed into was left empty: its git dir is gone and its
    # unpushed commits with it. The run never starts on a fresh worktree as if nothing happened.
    p, task, path, d, starts = _dangling_setup(env, monkeypatch)
    from ttp import startcheck, worktree
    gone = p.root.parent / "vanished-clone"
    gone.mkdir()   # left as an empty folder
    (path / ".git").write_text(f"gitdir: {gone}/.git/worktrees/{path.name}\n")
    assert startcheck.dangling(path) == {"gitdir": f"{gone}/.git/worktrees/{path.name}", "repo": str(gone),
                                         "repo_gone": True}
    d.dispatch()
    t = p.db.task(task["id"])
    assert not starts and t["status"] == "blocked", "a task started on a dangling worktree"
    assert t["blocked_reason"].startswith("workspace: ") and "dangling" in t["blocked_reason"]
    assert "not retried" in t["blocked_reason"]
    obs = p.db.q("SELECT * FROM events WHERE kind='observation' AND fingerprint LIKE 'dangling:%'")
    assert len(obs) == 1 and obs[0]["severity"] == "high" and obs[0]["status"] == "queued"
    assert str(gone) in obs[0]["text"] and "lost" in obs[0]["text"]
    stale, = [s / path.name for s in p.worktrees.iterdir() if s.name.startswith(worktree.STALE_PREFIX)]
    assert (stale / "draft.txt").read_text() == "not committed" and not path.exists()
    # Requeued (the coordinator's decision): it starts afresh on a whole worktree.
    p.db.update_task(task["id"], status="queued", blocked_reason=None)
    d._workspace_tries(task["id"], clear=True)
    d.dispatch()
    assert len(starts) == 1 and worktree.is_git(path) and starts[0][1] == str(path)


def test_a_dangling_worktree_whose_repository_is_there_is_made_again_on_its_branch_and_reported(env, monkeypatch):
    # Only git's record of the worktree is gone: the branch's commits are in the repository, so the
    # worktree is made again on them, the old files kept aside, and the run and its hand-off say so.
    p, task, path, d, starts = _dangling_setup(env, monkeypatch)
    from ttp import startcheck
    head = _commit_file_in(path, "work.txt")
    shutil.rmtree(pathlib.Path(_git_out(path, "rev-parse", "--absolute-git-dir")))
    assert startcheck.dangling(path)["repo_gone"] is False
    d.dispatch()
    (prompt, cwd, note), = starts
    assert cwd == str(path) and _git_out(path, "rev-parse", "HEAD") == head, "the branch's commits were lost"
    assert "Run-start checks found" in prompt and "was dangling" in prompt
    assert len(note["start_checks"]) == 1 and "was dangling" in note["start_checks"][0]
    assert startcheck.of_run(json.dumps(note)) == note["start_checks"]
    # A session that worked in the old worktree is not resumed in the new one.
    assert startcheck.remade(note["start_checks"]) and not startcheck.remade(["~/.ssh/known_hosts is missing"])
    assert p.db.one("SELECT severity FROM events WHERE kind='observation' AND fingerprint LIKE 'dangling:%'")[
        "severity"] == "normal"


def test_a_dangling_worktree_whose_repository_lost_the_tasks_branch_blocks_its_task(env, monkeypatch):
    # The clone was emptied and cloned again: the repository is there, but the task's branch with
    # its unpushed commits is not. The task is never restarted on a fresh branch as if they were kept.
    p, task, path, d, starts = _dangling_setup(env, monkeypatch)
    from ttp import startcheck, worktree
    _commit_file_in(path, "work.txt")
    shutil.rmtree(pathlib.Path(_git_out(path, "rev-parse", "--absolute-git-dir")))
    _git_out(p.root, "worktree", "prune")
    _git_out(p.root, "branch", "-D", task["branch"])
    assert startcheck.dangling(path)["repo_gone"] is False
    d.dispatch()
    t = p.db.task(task["id"])
    assert not starts and t["status"] == "blocked", "a task restarted after its branch was lost"
    assert t["blocked_reason"].startswith("workspace: ") and "not retried" in t["blocked_reason"]
    assert task["branch"] in t["blocked_reason"]
    obs = p.db.q("SELECT * FROM events WHERE kind='observation' AND fingerprint LIKE 'dangling:%'")
    assert len(obs) == 1 and obs[0]["severity"] == "high" and task["branch"] in obs[0]["text"]
    assert "lost" in obs[0]["text"] and "kept" not in obs[0]["text"]
    stale, = [s / path.name for s in p.worktrees.iterdir() if s.name.startswith(worktree.STALE_PREFIX)]
    assert (stale / "work.txt").exists() and (stale / "draft.txt").read_text() == "not committed"
    assert not path.exists()


def test_a_base_clone_that_lost_its_git_dir_blocks_code_tasks_and_one_on_tmpfs_is_reported(env, monkeypatch):
    p = make(env)
    from ttp import startcheck, worktree
    task = p.db.task(p.db.add_task("build", "s", kind="code", tier="light", origin="user"))
    assert startcheck.check(p, task) == []
    assert p.db.kv(startcheck.KV_BASE) == {"root": str(p.root)}
    (p.root / ".git").rename(p.root.parent / "moved-git")
    try:
        with pytest.raises(worktree.WorkspaceStuck, match="no .git directory"):
            startcheck.check(p, task)
        obs = p.db.one("SELECT * FROM events WHERE kind='observation' AND fingerprint=?", (f"base-gone:{p.root}",))
        assert obs["severity"] == "high"
        # A task that works in no worktree of the root is not held by it.
        other = p.db.task(p.db.add_task("look", "s", kind="question", tier="light", origin="user"))
        assert startcheck.check(p, other) == []
        # A root that was never a git repository (tasks work in it, as before): nothing to report.
        p.db.set_kv(startcheck.KV_BASE, None)
        assert startcheck.check(p, task) == []
    finally:
        (p.root.parent / "moved-git").rename(p.root / ".git")
    # On a file system a reboot empties: reported, not blocked.
    monkeypatch.delenv(startcheck.ALLOW_VOLATILE_ENV, raising=False)
    monkeypatch.setattr(startcheck, "volatile", lambda where: "tmpfs" if where == p.root else None)
    found = startcheck.check(p, task)
    assert len(found) == 1 and "tmpfs" in found[0] and str(p.root) in found[0]
    monkeypatch.setenv(startcheck.ALLOW_VOLATILE_ENV, "1")
    assert startcheck.check(p, task) == []


def test_volatile_reads_the_file_system_type_of_the_deepest_mount(tmp_path, monkeypatch):
    from ttp import startcheck
    monkeypatch.setattr(startcheck.sys, "platform", "linux")
    mounts = tmp_path / "mounts"
    mounts.write_text("/dev/sda1 / ext4 rw 0 0\ntmpfs /scratch tmpfs rw 0 0\n/dev/sdb1 /scratch/disk xfs rw 0 0\n")
    assert startcheck.volatile(pathlib.Path("/scratch/clone"), str(mounts)) == "tmpfs"
    assert startcheck.volatile(pathlib.Path("/scratch"), str(mounts)) == "tmpfs"
    assert startcheck.volatile(pathlib.Path("/scratch/disk/clone"), str(mounts)) is None
    assert startcheck.volatile(pathlib.Path("/scratchy"), str(mounts)) is None
    assert startcheck.volatile(pathlib.Path("/x"), str(tmp_path / "none")) is None


def test_a_missing_or_empty_known_hosts_is_reported_at_run_start_once_a_day(env, monkeypatch, tmp_path):
    p = make(env)
    from ttp import machines, startcheck
    home = tmp_path / "kh-home"
    home.mkdir()
    monkeypatch.setenv("HOME", str(home))
    monkeypatch.setattr(machines, "load", lambda: {})
    task = p.db.task(p.db.add_task("ssh work", "s", kind="work", tier="light", origin="user"))
    assert startcheck.check(p, task) == [], "a project that never used ssh was told about known_hosts"
    kh = home / ".ssh" / "known_hosts"
    kh.parent.mkdir()
    kh.write_text("host ssh-ed25519 AAAA\n")
    assert startcheck.check(p, task) == [] and p.db.kv(startcheck.KV_KNOWN_HOSTS)["path"] == str(kh)
    kh.write_text("")
    found, = startcheck.check(p, task)
    assert str(kh) in found and "is empty" in found
    kh.unlink()
    for _ in range(2):
        found, = startcheck.check(p, task)
        assert "is missing" in found
    fps = [r["fingerprint"] for r in p.db.q("SELECT fingerprint FROM events WHERE kind='observation' "
                                            "AND fingerprint LIKE 'known_hosts:%' ORDER BY id")]
    assert fps == [f"known_hosts:{kh}:empty", f"known_hosts:{kh}:missing"], "an observation was repeated"
    # Never seen here, but machines are listed: reported too.
    p.db.set_kv(startcheck.KV_KNOWN_HOSTS, None)
    monkeypatch.setattr(machines, "load", lambda: {"box": {}})
    assert "is missing" in startcheck.check(p, task)[0]


def _moved_branch(p, worktree):
    """A task continuing another whose worktree was made on its own branch, after which its recorded
    branch changed to the continued task's (the reported case). Returns (task, path, own branch)."""
    old = p.db.add_task("first try", "s", kind="code", tier="light", origin="user")
    p.db.update_task(old, branch=f"ttp/t{old}-first-try", status="failed")
    _git_out(p.root, "branch", f"ttp/t{old}-first-try", worktree.resolve_base(p))
    tid = p.db.add_task("second try", "s", kind="code", tier="light", origin="user", labels=[f"continues:{old}"])
    path, own = worktree.ensure(p, dict(p.db.task(tid), branch=None))
    assert own == f"ttp/t{tid}-second-try"
    p.db.update_task(tid, branch=f"ttp/t{old}-first-try")
    return p.db.task(tid), path, own


def _commit_file_in(path, name, text="x"):
    (path / name).write_text(text)
    _git_out(path, "add", name)
    _git_out(path, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", name)
    return _git_out(path, "rev-parse", "HEAD")


def test_a_worktree_on_another_branch_with_the_tasks_own_commits_is_adopted(env):
    p = make(env)
    from ttp import worktree
    from ttp.prompts import worker_task
    task, path, own = _moved_branch(p, worktree)
    head = _commit_file_in(path, "work.txt")
    (path / "notes.txt").write_text("loose")
    assert worktree.ensure(p, task) == (path, own), "the worktree's branch with this task's commits was not adopted"
    assert _git_out(path, "rev-parse", "HEAD") == head and (path / "notes.txt").read_text() == "loose"
    ev = p.db.one("SELECT * FROM events WHERE task=? AND kind=?", (task["id"], worktree.RECOVERED_EVENT))
    assert ev and json.loads(ev["data"])["adopted"] == own and ev["status"] == "handled"
    assert "now works on it" in worker_task(p, task, str(path), own)


def test_a_worktree_on_another_branch_with_only_loose_output_moves_it_and_is_made_again(env):
    p = make(env)
    from ttp import worktree
    from ttp.prompts import worker_task
    task, path, own = _moved_branch(p, worktree)
    exclude = p.root / _git_out(p.root, "rev-parse", "--git-common-dir") / "info" / "exclude"
    exclude.parent.mkdir(parents=True, exist_ok=True)
    exclude.write_text(exclude.read_text() + "\nbuild/\nout/\n" if exclude.exists() else "build/\nout/\n")
    (path / "out").mkdir()
    (path / "out" / "frame.png").write_text("png")
    (path / "build").mkdir()
    (path / "build" / "lib.so").write_bytes(b"\0" * 4096)
    (path / "shot.png").write_text("png2")
    tracked = _git_out(path, "ls-files").splitlines()[0]
    (path / tracked).write_bytes(b"edited \xff\xfe not utf-8")
    path2, branch = worktree.ensure(p, task)
    assert (path2, branch) == (path, task["branch"])
    assert _git_out(path, "rev-parse", "--abbrev-ref", "HEAD") == task["branch"]
    assert _git_out(path, "status", "--porcelain") == "", "the remade worktree is not clean"
    assert _git_out(p.root, "rev-parse", "--verify", own), "the worktree's old branch was deleted"
    data = json.loads(p.db.one("SELECT data FROM events WHERE task=? AND kind=?",
                               (task["id"], worktree.RECOVERED_EVENT))["data"])
    from pathlib import Path
    dest = Path(data["leftovers"])
    assert dest.parent == p.state / worktree.LEFTOVERS_DIR and dest.name.startswith(f"t{task['id']}-")
    assert (dest / "out" / "frame.png").read_text() == "png" and (dest / "shot.png").read_text() == "png2"
    assert (dest / tracked).read_bytes() == b"edited \xff\xfe not utf-8"
    assert b"edited" in (dest / "uncommitted.patch").read_bytes()
    # An ignored build cache is regenerable: it goes with the old worktree, not to the leftovers.
    assert not (dest / "build").exists() and not (path / "build").exists() and data["caches"] == ["build"]
    assert data["bytes"] == len("png") + len("png2") + len(b"edited \xff\xfe not utf-8")
    assert str(dest) in worker_task(p, task, str(path), branch), "the start note does not name the leftovers"
    # Once a run started, the note is not repeated.
    p.db.x("INSERT INTO runs(task,role,started,status) VALUES(?,?,?,?)", (task["id"], "worker", time.time() + 1, "done"))
    assert str(dest) not in worker_task(p, task, str(path), branch)


def test_old_worktree_leftovers_folders_are_pruned_after_the_configured_days(env):
    p = make(env)
    from ttp import worktree
    from ttp.daemon import Daemon
    root = p.state / worktree.LEFTOVERS_DIR
    now = time.time()
    old, recent, stamped = root / "t1-20200101-000000", root / "t2-20200101-000000", root / "t3-29990101-000000"
    for d in (old, recent, stamped):
        (d / "out").mkdir(parents=True)
        (d / "out" / "f.txt").write_text("x")
        os.utime(d, (now - 40 * 86400,) * 2)
    os.utime(recent, (now - 86400,) * 2)   # its name is old, but the folder is recent: kept
    assert worktree.prune_leftovers(p, 0, now) == [] and old.exists(), "0 keeps all"
    assert worktree.prune_leftovers(p, None, now) == [old.name]
    assert not old.exists() and recent.exists() and stamped.exists()
    p.set_config("disk.worktree_leftovers_keep_days", 0.5)
    d = Daemon(p.base)
    assert d.prune_leftovers() == [recent.name] and stamped.exists()
    assert d.prune_leftovers() == [], "ran again within the hour"


def test_a_worktree_on_another_branch_moves_hand_off_artifacts_inside_ignored_caches(env):
    # Caches go with the old worktree, but a hand-off artifact inside one is output, not cache.
    p = make(env)
    from ttp import worktree
    task, path, own = _moved_branch(p, worktree)
    exclude = p.root / _git_out(p.root, "rev-parse", "--git-common-dir") / "info" / "exclude"
    exclude.parent.mkdir(parents=True, exist_ok=True)
    exclude.write_text(exclude.read_text() + "\nbuild/\n.cache/\n" if exclude.exists() else "build/\n.cache/\n")
    (path / "build").mkdir()
    (path / "build" / "report.html").write_text("<html>")
    (path / "build" / "lib.so").write_bytes(b"\0" * 4096)
    (path / ".cache").mkdir()
    (path / ".cache" / "blob").write_text("cached")
    _handoff(p, task["id"], [str(path / "build" / "report.html")])
    worktree.ensure(p, task)
    data = json.loads(p.db.one("SELECT data FROM events WHERE task=? AND kind=?",
                               (task["id"], worktree.RECOVERED_EVENT))["data"])
    from pathlib import Path
    dest = Path(data["leftovers"])
    assert (dest / "build" / "report.html").read_text() == "<html>", "a hand-off artifact in a cache was lost"
    assert not (dest / "build" / "lib.so").exists() and not (dest / ".cache").exists()
    assert data["bytes"] == len("<html>") and "build/report.html" in data["moved"]


