# crash windows: each test kills (or fails) a step half way, then checks nothing was lost or doubled --------
def _die_in(p, code):
    """Run `code` against the project in a fresh process that is killed outright (os._exit, no cleanup,
    no rollback handler) wherever it calls die(). `d` is a Daemon on the project."""
    script = (f"import os, sys\nsys.path.insert(0, {str(RUNTIME)!r})\nfrom ttp.daemon import Daemon\n"
              f"d = Daemon({str(p.base)!r})\n\ndef die(*a, **k):\n    os._exit(9)\n\n{code}\n")
    r = subprocess.run([sys.executable, "-c", script], capture_output=True, text=True, timeout=120)
    assert r.returncode == 9, f"the process was not killed where expected: {r.stdout}{r.stderr}"


def _wait(cond, timeout=30.0):
    deadline = time.time() + timeout
    while time.time() < deadline:
        if cond():
            return True
        time.sleep(0.05)
    return cond()


def _gone(pid):
    """pid runs no more (a zombie waiting for its reaper counts as gone)."""
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return True
    try:
        return pathlib.Path(f"/proc/{pid}/stat").read_text().rsplit(")", 1)[1].split()[0] == "Z"
    except (OSError, IndexError):
        return False


def _json_or_none(path):
    try:
        return json.loads(path.read_text())
    except (OSError, ValueError):
        return None


def test_a_killed_supervisor_ends_its_agent_and_the_handoff_still_counts(env):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = p.db.add_task("finish the thing", "s", kind="work", tier="light", origin="user", reply_chat="c1")
    p.db.update_task(tid, status="running")
    handoff = json.dumps({"status": "done", "summary": "pushed the fix, tests green"})
    rid, run_dir, proc = _start_sleeping_run(p, tid, boot=d.boot, argv=(
        "sh", "-c", f'printf %s {shlex.quote(handoff)} > "$TTP_RUN_DIR/result.json"; exec sleep 120'))
    agent = None
    try:
        assert _wait(lambda: _json_or_none(run_dir / "result.json") and (run_dir / "child.pid").exists())
        agent = int((run_dir / "child.pid").read_text().split()[0])
        proc.kill()           # the supervisor dies after the hand-off (kill -9, OOM) and stops renewing its lease
        proc.wait()
        os.utime(run_dir / "lease", (time.time() - 999, time.time() - 999))
        d.reap_runs()
        assert _wait(lambda: _gone(agent), 15), "the agent kept running without its supervisor"
    finally:
        if agent and not _gone(agent):
            os.killpg(agent, signal.SIGKILL)
    assert p.db.one("SELECT status FROM runs WHERE id=?", (rid,))["status"] == "lost"
    t = p.db.task(tid)
    assert t["status"] == "done" and "pushed the fix" in t["result"], "a finished task was queued to be redone"
    assert len(p.db.q("SELECT id FROM events WHERE kind='task_done' AND task=?", (tid,))) == 1
    assert p.db.q("SELECT id FROM messages WHERE direction='out' AND chat='c1' AND text LIKE '%pushed the fix%'")


@pytest.mark.parametrize("ended", ["timeout", "stalled", "reboot"])
def test_a_handoff_written_before_a_run_ends_badly_is_kept(env, tmp_path, ended):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = p.db.add_task("measure", "s", kind="work", tier="light", origin="user")
    p.db.update_task(tid, status="running")
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    (run_dir / "output.jsonl").write_text("")
    (run_dir / "result.json").write_text(json.dumps({"status": "done", "summary": "measured 12 ms"}))
    boot = d.boot
    if ended == "reboot":     # no exit.json: the machine went down under the run
        boot = "an-earlier-boot"
        (run_dir / "lease").touch()
        os.utime(run_dir / "lease", (time.time() - 999, time.time() - 999))
    else:
        (run_dir / "exit.json").write_text(json.dumps({"rc": -15, "stopped": ended, "ended": time.time()}))
    rid = p.db.x("INSERT INTO runs(task,role,provider,started,status,dir,boot_id) VALUES(?,?,?,?,?,?,?)",
                 (tid, "worker", "fake", time.time(), "running", str(run_dir), boot))
    d.reap_runs()
    # A timed-out run that handed off is not waste; the task still says how its run ended.
    run_status = {"reboot": "lost", "timeout": "ok"}.get(ended, ended)
    assert p.db.one("SELECT status FROM runs WHERE id=?", (rid,))["status"] == run_status
    t = p.db.task(tid)
    assert t["status"] == "done" and json.loads(t["result"])["summary"] == "measured 12 ms"
    assert json.loads(t["result"]).get("run_status") == ("lost" if ended == "reboot" else ended)


def test_the_reaper_never_kills_a_process_that_reused_the_agents_pid(env, tmp_path):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = p.db.add_task("job", "s", kind="work", tier="light", origin="user")
    p.db.update_task(tid, status="running")
    other = subprocess.Popen(["sleep", "60"], start_new_session=True)
    try:
        run_dir = tmp_path / "run"
        run_dir.mkdir()
        (run_dir / "output.jsonl").write_text("")
        (run_dir / "child.pid").write_text(f"{other.pid}\n1\n")   # the run's agent had another start
        (run_dir / "lease").touch()
        old = time.time() - 600
        os.utime(run_dir / "lease", (old, old))
        p.db.x("INSERT INTO runs(task,role,provider,started,status,dir,boot_id) VALUES(?,?,?,?,?,?,?)",
               (tid, "worker", "fake", old, "running", str(run_dir), d.boot))
        d.reap_runs()
        time.sleep(0.5)
        assert other.poll() is None, "the reaper killed a process that only reused the agent's pid"
    finally:
        other.kill()
        other.wait()


@pytest.mark.filterwarnings("ignore::pytest.PytestUnhandledThreadExceptionWarning")
@pytest.mark.parametrize("fault", ["thread-dies", "one-look-fails"])
def test_an_error_in_the_watch_thread_never_leaves_the_agent_unwatched(env, tmp_path, monkeypatch, capsys, fault):
    # The watch thread is the only thing that enforces the wall clock, stall, budget and cancel. An
    # error in one look is logged and the next look still ends the agent at its limit; a thread that
    # dies anyway is noticed by the main thread, which ends the agent and writes exit.json.
    from ttp import runner
    if fault == "thread-dies":
        def broken(*a, **kw):
            raise RuntimeError("watch setup broke")
        monkeypatch.setattr(runner, "ProgressWatch", broken)
    else:
        monkeypatch.setattr(runner.ProgressWatch, "poll", lambda self: 1 / 0)
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    (run_dir / "prompt.md").write_text("x")
    (run_dir / "run.json").write_text(json.dumps({
        "argv": [sys.executable, "-c", "import time; time.sleep(60)"], "env": {}, "cwd": str(tmp_path),
        "timeout_s": 1, "stall_s": 30, "provider": "fake"}))
    t0 = time.time()
    runner.supervise(run_dir)
    info = json.loads((run_dir / "exit.json").read_text())
    assert time.time() - t0 < 20, "the agent ran on unwatched"
    if fault == "thread-dies":
        assert info["stopped"] == "supervisor_error"
        assert "watch thread died" in capsys.readouterr().out
    else:
        assert info["stopped"] == "timeout"
        assert "watch error 1: " in capsys.readouterr().out


class _Orphan:
    """A `sleep` in a session of its own that is not this process's child, like a real run's processes
    are not the daemon's: a child of ours would linger as a zombie once signalled, and the reaper's
    TERM-then-KILL would wait out its whole grace for it. Popen's pid/poll/kill/wait."""

    def __init__(self):
        code = ("import subprocess; print(subprocess.Popen(['sleep', '120'], start_new_session=True, "
                "stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).pid)")
        self.pid = int(subprocess.run([sys.executable, "-c", code], capture_output=True, text=True,
                                      check=True).stdout)

    def poll(self):
        try:
            os.kill(self.pid, 0)
        except OSError:
            return -1
        return None

    def kill(self):
        with contextlib.suppress(OSError):
            os.kill(self.pid, signal.SIGKILL)

    def wait(self):
        _wait(lambda: self.poll() is not None, 15)


def _hung_run(p, d, tmp_path, token=None, lease_age=999, spec=None, started=None):
    """A worker run on this boot whose supervisor and agent are live processes (sleeps in sessions of
    their own) and whose lease is lease_age old. token: the supervisor start recorded beside its pid
    (its real one by default)."""
    from ttp import runner
    tid = p.db.add_task("job", "s", kind="work", tier="light", origin="user")
    p.db.update_task(tid, status="running")
    sup, agent = _Orphan(), _Orphan()
    run_dir = tmp_path / f"run-{sup.pid}"
    run_dir.mkdir()
    (run_dir / "output.jsonl").write_text("")
    (run_dir / "runner.pid").write_text(f"{sup.pid}\n{token or runner.proc_start(sup.pid)}\n")
    (run_dir / "child.pid").write_text(f"{agent.pid}\n{runner.proc_start(agent.pid)}\n")
    if spec:
        (run_dir / "run.json").write_text(json.dumps(spec))
    (run_dir / "lease").touch()
    old = time.time() - lease_age
    os.utime(run_dir / "lease", (old, old))
    rid = p.db.x("INSERT INTO runs(task,role,provider,started,status,dir,boot_id,pid) VALUES(?,?,?,?,?,?,?,?)",
                 (tid, "worker", "fake", started or old, "running", str(run_dir), d.boot, sup.pid))
    return tid, rid, sup, agent


class _Awake:
    def __init__(self):
        self.up = 1000.0

    def tick(self):
        return self.up


def test_a_live_supervisor_with_a_stale_lease_is_ended_as_hung_after_the_threshold(env, tmp_path):
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    d._awake = clock = _Awake()
    tid, rid, sup, agent = _hung_run(p, d, tmp_path)
    try:
        d.reap_runs()
        clock.up += dmod.LEASE_HUNG_S - dmod.LEASE_STALE_S - 1
        d.reap_runs()
        assert p.db.one("SELECT status FROM runs WHERE id=?", (rid,))["status"] == "running"
        assert sup.poll() is None and agent.poll() is None, "ended before the threshold"
        clock.up += 2
        d.reap_runs()
        row = p.db.one("SELECT status, note FROM runs WHERE id=?", (rid,))
        assert row["status"] == "stalled" and json.loads(row["note"])["stopped"] == "hung"
        assert _wait(lambda: sup.poll() is not None and agent.poll() is not None, 15)
        t = p.db.task(tid)
        assert t["status"] == "queued" and t["attempts"] == 1, "a hung run counts an attempt like a stall"
        feed = p.db.q("SELECT kind, severity, text FROM messages WHERE ref=?", (f"hung:{rid}",))
        assert len(feed) == 1 and feed[0]["kind"] == "info" and feed[0]["severity"] == "low", feed
        assert not p.db.q("SELECT 1 FROM events WHERE task=? AND status='queued'", (tid,)), "a hung run needs no turn"
    finally:
        for proc in (sup, agent):
            proc.kill()
            proc.wait()


def test_a_reused_supervisor_pid_is_reaped_as_lost_and_never_signalled(env, tmp_path):
    p = make(env)
