def test_the_review_prompt_pushes_only_through_the_guarded_push():
    text = (RUNTIME.parent / "template" / "prompts" / "kind-review.md").read_text()
    text = text[text.index("## Pushing a reviewed change"):]
    assert "`ttp push`" in text and "NEVER use `git push` directly" in text
    # The checks outlast a tool call: the review pushes detached and waits on the printed probe.
    assert "run `ttp push --detach`" in text and "`waiting` with that `retry_when`" in text
    assert "NEVER put plain\n  `ttp push` in the background yourself" in text
    assert "75: another push to the branch held its turn too long; hand off `waiting` with the `retry_when`" in text
    # Every exit code is handled in the exit-code bullet, before the version-bump bullet.
    codes, bump = text.index("  Exit 0: pushed."), text.index("- Version bump:")
    for code in ("5: the branch kept moving", "2 or 6: refused", "75: another push"):
        assert codes < text.index(code) < bump, code


def test_the_worker_time_rule_sends_pushes_detached():
    """worker.md's 5-minute rule must agree with the review and code prompts' detached `ttp push`."""
    text = (RUNTIME.parent / "template" / "prompts" / "worker.md").read_text()
    assert "Never block one tool call longer than about 5 minutes" in text
    assert "Push with `ttp push --detach`" in text and "such as `ttp push`" not in text


def _ttp(*args):
    from ttp import cli
    with pytest.raises(SystemExit) as e:
        cli.main(list(args))
    return e.value.code


def _push_proc(p, cwd, **kw):
    """`ttp push` as its own process in cwd, for the project p."""
    env = {**os.environ, "PYTHONPATH": str(RUNTIME), "TTP_PROJECT": str(p.base)}
    return subprocess.Popen([sys.executable, "-m", "ttp", "push"], cwd=str(cwd), env=env, text=True, **kw)


def test_concurrent_pushes_to_one_branch_take_turns_and_both_land(env, monkeypatch):
    log = env["tmp"] / "checks.log"
    p, repo, origin, other = _push_setup(env, monkeypatch, [f"echo start >> {log}; sleep 1; echo end >> {log}"])
    second = env["tmp"] / "second"
    subprocess.run(["git", "clone", "-q", "-b", "proj", str(origin), str(second)], check=True)
    _commit(repo, "mine.txt", "mine\n")
    _commit(second, "second.txt", "second\n")
    procs = [_push_proc(p, d, stdout=subprocess.PIPE, stderr=subprocess.STDOUT) for d in (repo, second)]
    outs = [pr.communicate(timeout=60)[0] for pr in procs]
    assert [pr.returncode for pr in procs] == [0, 0], outs
    assert {"mine.txt", "second.txt"} <= set(_git_out(origin, "ls-tree", "--name-only", "proj").split())
    assert log.read_text().split() == ["start", "end", "start", "end"], \
        "the checks must run once per push, one push after the other"
    assert not any("round 2" in o for o in outs), outs
    assert any("waiting up to" in o for o in outs), outs


def test_a_killed_push_frees_the_branch(env, monkeypatch):
    started = env["tmp"] / "started"
    p, repo, origin, other = _push_setup(env, monkeypatch, [f"touch {started}; sleep 60"])
    _commit(repo, "mine.txt", "mine\n")
    proc = _push_proc(p, repo, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
    try:
        deadline = time.time() + 30
        while not started.exists() and time.time() < deadline:
            time.sleep(0.05)
        assert started.exists()
        assert _ttp("push", "--free") == 1
        proc.kill()     # only the push itself; its check lives on without the lock
        proc.wait(timeout=10)
        assert _ttp("push", "--free") == 0
    finally:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except OSError:
            pass


def _detach(capsys):
    """`ttp push --detach`: (exit code, marker path, probe command) from what it printed."""
    rc = _ttp("push", "--detach")
    out = capsys.readouterr().out
    lines = dict(ln.split(": ", 1) for ln in out.splitlines() if ln.startswith(("marker: ", "retry_when: ")))
    return rc, pathlib.Path(lines["marker"]) if "marker" in lines else None, lines.get("retry_when")


def _probe(p, probe):
    """Run the probe where the harness runs a retry_when: in the project root, without the run's env."""
    penv = {k: v for k, v in os.environ.items() if not k.startswith("TTP_") or k == "TTP_HOME"}
    return subprocess.run(probe, shell=True, cwd=str(p.root), env=penv, capture_output=True, text=True)


def _probe_until_done(p, probe, timeout=60):
    deadline = time.time() + timeout
    while True:
        r = _probe(p, probe)
        if r.returncode != 1 or time.time() > deadline:
            return r
        time.sleep(0.05)


def _gated_check(started, gate):
    """A check that touches started, then waits for gate (or for the test's folder to go away)."""
    return f"touch {started}; while [ ! -e {gate} ] && [ -d {gate.parent} ]; do sleep 0.05; done"


def _wait_gone(pid, deadline):
    """Wait until the detached push `pid` exited (it lets go of its run lock just after its outcome)."""
    while time.time() < deadline:
        try:   # the push process is this test's child: reap it, or its zombie answers kill(pid, 0)
            if os.waitpid(pid, os.WNOHANG)[0]:
                return
        except ChildProcessError:
            pass
        try:
            os.kill(pid, 0)
        except OSError:
            return
        time.sleep(0.05)


def _release_detached(gate, pids):
    """Finalizer of a gated detached push: open the gate so a failed assertion leaves nothing
    spinning, then end any detached push (its own session) that is still running."""
    gate.touch()
    deadline = time.time() + 10
    for pid in pids:
        _wait_gone(pid, deadline)
        try:
            os.killpg(pid, signal.SIGKILL)
        except OSError:
            pass


def test_a_detached_push_whose_check_fails_reports_the_exit_and_log_tail(env, monkeypatch, capsys):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["echo the-check-said-no; false"])
    before = _git_out(origin, "rev-parse", "proj")
    _commit(repo, "mine.txt", "mine\n")
    rc, marker, probe = _detach(capsys)
    assert rc == 0
    r = _probe_until_done(p, probe)
    assert r.returncode == 0 and "not pushed (exit 4)" in r.stdout and "the-check-said-no" in r.stdout, r
    m = json.loads(marker.read_text())
    assert (m["status"], m["exit"], m["sha"]) == ("failed", 4, None)
    assert _git_out(origin, "rev-parse", "proj") == before
    assert _probe(p, probe).returncode == 0, "a finished push keeps answering 0"


def test_a_detached_push_refuses_a_dirty_tree_at_once_without_a_marker(env, monkeypatch, capsys):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    (repo / "README.md").write_text("dirty\n")
    rc, marker, probe = _detach(capsys)
    assert rc == 2 and marker is None and not (p.state / "pushes").exists()


def test_push_own_publishes_the_tasks_own_branch_as_it_is_and_never_a_shared_one(env, monkeypatch, capsys):
    log = env["tmp"] / "checked"
    p, repo, origin, other = _push_setup(env, monkeypatch, [f"git rev-parse HEAD >> {log}"])
    p.set_config("delivery.base_ref", "origin/proj")
    _commit(other, "theirs.txt", "theirs\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    shared = _git_out(origin, "rev-parse", "proj")
    _git_out(repo, "checkout", "-q", "-b", "ttp/t30-exp")
    _commit(repo, "mine.txt", "mine\n")
    head = _git_out(repo, "rev-parse", "HEAD")
    monkeypatch.setenv("TTP_TASK", "30")
    assert _ttp("push", "--own") == 0
    # The reviewed commit itself: no rebase onto the moved shared branch, which stays untouched.
    assert _git_out(origin, "rev-parse", "ttp/t30-exp") == head == _git_out(repo, "rev-parse", "HEAD")
    assert log.read_text().split() == [head] and _git_out(origin, "rev-parse", "proj") == shared
    # Another task's branch, a shared branch or main: refused before anything runs.
    monkeypatch.setenv("TTP_TASK", "31")
    assert _ttp("push", "--own") == 2 and "ttp/t31-" in capsys.readouterr().err
    monkeypatch.delenv("TTP_TASK")
    for name in ("proj", "main", "master"):
        _git_out(repo, "checkout", "-q", "-B", name)
        assert _ttp("push", "--own") == 2, name
    _git_out(repo, "checkout", "-q", "--detach")
    assert _ttp("push", "--own") == 2 and "detached HEAD" in capsys.readouterr().err
    assert _git_out(origin, "rev-parse", "proj") == shared
    assert _git_out(origin, "for-each-ref", "--format=%(refname:short)", "refs/heads") == "proj\nttp/t30-exp"
    # Never forced: a rewritten own branch is rejected and the remote keeps what it had.
    _git_out(repo, "checkout", "-q", "ttp/t30-exp")
    _git_out(repo, "commit", "-q", "--amend", "-m", "rewritten")
    assert _ttp("push", "--own") == 6 and _git_out(origin, "rev-parse", "ttp/t30-exp") == head
    # Pushing must still be allowed at all.
    p.set_config("delivery.push_allowed", False)
    assert _ttp("push", "--own") == 2


def test_push_own_with_plain_checks_still_fetches_the_push_target_base(env, monkeypatch):
    """--own fetches the push target before its checks even when no check is if_changed-scoped, so a
    check or publish step comparing with the base never sees a stale or missing one."""
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    _commit(other, "theirs.txt", "theirs\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    shared = _git_out(origin, "rev-parse", "proj")
    assert _git_out(repo, "rev-parse", "origin/proj") != shared
    _git_out(repo, "checkout", "-q", "-b", "ttp/t32-exp")
    _commit(repo, "mine.txt", "mine\n")
    monkeypatch.setenv("TTP_TASK", "32")
    assert _ttp("push", "--own") == 0
    assert _git_out(repo, "rev-parse", "origin/proj") == shared


def test_push_in_a_remote_less_harness_says_the_commit_is_already_delivered(env, monkeypatch, capsys):
    """A harness task's commit in the project's harness repo (no remote) is its delivery: `ttp push`,
    `--own` and `--detach` say so and exit 0 at once, with no push, check or marker."""
    log = env["tmp"] / "checked"
    p, repo, origin, other = _push_setup(env, monkeypatch, [f"echo ran >> {log}"])
    h = p.harness
    if not (h / ".git").exists():
        _git_out(h, "init", "-q")
    _commit(h, "note.md", "a harness change\n")
    monkeypatch.setenv("TTP_TASK", "50")
    monkeypatch.chdir(h / "prompts" if (h / "prompts").is_dir() else h)
    capsys.readouterr()
    for args in (("push", "--own"), ("push", "--own", "--detach"), ("push",)):
        assert _ttp(*args) == 0, args
        out = capsys.readouterr()
        assert "already delivered" in out.err and "no remote" in out.err and "marker: " not in out.out, args
        assert "nothing to push: this is the project's harness" in out.err, args
    assert not log.exists() and not (p.state / "pushes").exists()
    assert _git_out(origin, "for-each-ref", "--format=%(refname:short)", "refs/heads") == "proj"
    # A harness the user gave a remote is not short-circuited: the usual --own rules apply.
    _git_out(h, "remote", "add", "origin", str(origin))
    _git_out(h, "checkout", "-q", "-B", "main")
    assert _ttp("push", "--own") == 2 and "shared branch" in capsys.readouterr().err
    # The project's code repo, which has no harness in it, keeps its usual refusals too.
    monkeypatch.chdir(repo)
    _git_out(repo, "checkout", "-q", "-B", "main")
    assert _ttp("push", "--own") == 2 and "already delivered" not in capsys.readouterr().err


def test_push_own_publishes_a_named_branch_only_as_a_fast_forward(env, monkeypatch, capsys):
    log = env["tmp"] / "checked"
    p, repo, origin, other = _push_setup(env, monkeypatch, [f"git rev-parse HEAD >> {log}"])
    monkeypatch.setenv("TTP_TASK", "40")   # the worktree's own branch, named by the spec, not ttp/t40-...
    _git_out(repo, "checkout", "-q", "-b", "someone/feature-x")
    _commit(repo, "a.txt", "a\n")
    first = _git_out(repo, "rev-parse", "HEAD")
    assert _ttp("push", "--own") == 0, "new on the remote"
    assert _git_out(origin, "rev-parse", "someone/feature-x") == first
    _commit(repo, "b.txt", "b\n")
    second = _git_out(repo, "rev-parse", "HEAD")
    assert _ttp("push", "--own") == 0, "a fast-forward of the remote's tip"
    assert _git_out(origin, "rev-parse", "someone/feature-x") == second
    # Someone else moved it: diverged, refused before the checks run, the remote keeps theirs.
    _git_out(other, "fetch", "-q", "origin", "someone/feature-x")
    _git_out(other, "checkout", "-q", "-b", "fx", "FETCH_HEAD")
    _commit(other, "theirs.txt", "theirs\n")
    _git_out(other, "push", "-q", "origin", "HEAD:someone/feature-x")
    theirs = _git_out(origin, "rev-parse", "someone/feature-x")
    _commit(repo, "c.txt", "c\n")
    capsys.readouterr()
    assert _ttp("push", "--own") == 2 and "not an ancestor of HEAD" in capsys.readouterr().err
    assert _git_out(origin, "rev-parse", "someone/feature-x") == theirs
    assert log.read_text().split() == [first, second]
    # The push target, main/master and the remote's default branch: refused, whatever their history.
    for name in ("proj", "main", "master"):
        _git_out(repo, "checkout", "-q", "-B", name, _git_out(origin, "rev-parse", "proj"))
        assert _ttp("push", "--own") == 2 and "shared branch" in capsys.readouterr().err, name
    _git_out(other, "push", "-q", "origin", "HEAD:refs/heads/trunk")
    _git_out(origin, "symbolic-ref", "HEAD", "refs/heads/trunk")
    _git_out(repo, "fetch", "-q", "origin", "trunk")
    _git_out(repo, "checkout", "-q", "-B", "trunk", "FETCH_HEAD")
    _commit(repo, "d.txt", "d\n")
    assert _ttp("push", "--own") == 2 and "default branch" in capsys.readouterr().err
    _git_out(repo, "checkout", "-q", "--detach")
    assert _ttp("push", "--own") == 2 and "detached HEAD" in capsys.readouterr().err
    refs = _git_out(origin, "for-each-ref", "--format=%(refname:short)", "refs/heads").split()
    assert sorted(refs) == ["proj", "someone/feature-x", "trunk"]
    assert _git_out(origin, "rev-parse", "trunk") == theirs
    assert log.read_text().split() == [first, second], "no refused push ran its checks"


def test_push_never_rewrites_a_published_task_branch_and_rebases_an_unpublished_one_in_place(
        env, monkeypatch, capsys):
    from ttp import worktree
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    monkeypatch.setenv("TTP_TASK", "50")
    _git_out(repo, "checkout", "-q", "-b", "ttp/t50-exp")
    _commit(repo, "mine.txt", "mine\n")
    assert _ttp("push", "--own") == 0
    mine = _git_out(repo, "rev-parse", "HEAD")
    _commit(other, "theirs.txt", "theirs\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    theirs = _git_out(origin, "rev-parse", "proj")
    capsys.readouterr()
    assert _ttp("push") == 0
    assert "stays as it is" in capsys.readouterr().err
    # The target took a rebased copy; the named branch, here and on the remote, is as it was.
    landed = _git_out(origin, "rev-parse", "proj")
    assert _git_out(origin, "rev-parse", f"{landed}~1") == theirs and landed != mine
    assert _git_out(origin, "show", f"{landed}:mine.txt") == "mine"
    assert _git_out(repo, "symbolic-ref", "--short", "HEAD") == "ttp/t50-exp"
    assert _git_out(repo, "rev-parse", "HEAD") == mine == _git_out(origin, "rev-parse", "ttp/t50-exp")
    # The worktree's delivered check still counts the work as in the target (patch-id match).
    _git_out(repo, "fetch", "-q", "origin", "+refs/heads/proj:refs/remotes/origin/proj")
    assert worktree.delivered(repo, mine, "origin/proj")
    # New commits on the branch still publish as a fast-forward of the remote's copy.
    _commit(repo, "more.txt", "more\n")
    assert _ttp("push", "--own") == 0
    assert _git_out(origin, "rev-parse", "ttp/t50-exp") == _git_out(repo, "rev-parse", "HEAD")
    # A detached push reports the commit it pushed, not the branch's head.
    _git_out(other, "pull", "-q", "--rebase", "origin", "proj")
    _commit(other, "theirs2.txt", "theirs2\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    rc, marker, probe = _detach(capsys)
    assert rc == 0
    r = _probe_until_done(p, probe)
    pushed = _git_out(origin, "rev-parse", "proj")
    assert r.returncode == 0 and json.loads(marker.read_text())["sha"] == pushed, r
    assert _git_out(repo, "symbolic-ref", "--short", "HEAD") == "ttp/t50-exp"
    assert _git_out(origin, "rev-parse", "ttp/t50-exp") == _git_out(repo, "rev-parse", "HEAD") != pushed
    # A branch the remote does not have is rebased in place, as before.
    monkeypatch.setenv("TTP_TASK", "51")
    _git_out(repo, "checkout", "-q", "-b", "ttp/t51-local", "origin/proj")
    _commit(repo, "local.txt", "local\n")
    _git_out(other, "pull", "-q", "--rebase", "origin", "proj")
    _commit(other, "theirs3.txt", "theirs3\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    capsys.readouterr()
    assert _ttp("push") == 0
    assert "stays as it is" not in capsys.readouterr().err
    assert _git_out(repo, "rev-parse", "ttp/t51-local") == _git_out(origin, "rev-parse", "proj")
    assert _git_out(origin, "for-each-ref", "--format=%(refname:short)", "refs/heads").split() == [
        "proj", "ttp/t50-exp"]


def test_push_conflict_on_a_published_branch_says_merge_not_rebase(env, monkeypatch, capsys):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    monkeypatch.setenv("TTP_TASK", "52")
    _git_out(repo, "checkout", "-q", "-b", "ttp/t52-clash")
    _commit(repo, "clash.txt", "mine\n")
    assert _ttp("push", "--own") == 0
    mine = _git_out(repo, "rev-parse", "HEAD")
    _commit(other, "clash.txt", "theirs\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    capsys.readouterr()
    assert _ttp("push") == 3
    err = capsys.readouterr().err
    assert "do not rebase it" in err and "git merge origin/proj" in err, err
    assert _git_out(repo, "symbolic-ref", "--short", "HEAD") == "ttp/t52-clash"
    assert _git_out(repo, "rev-parse", "HEAD") == mine


def _foreign_setup(env, monkeypatch):
    """_push_setup with an integration branch ttp/t48-int (rt plus one commit) as the push target and
    rt as base_ref; origin also has main, ahead of the common root by two commits, a colleague's
    main-based branch and other tasks' ttp/* branches, all fetched."""
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    root = _git_out(repo, "rev-parse", "HEAD")
    for name, files in (("rt", ["rt.txt"]), ("ttp/t48-int", ["rt.txt", "int.txt"]),
                        ("main", ["m1.txt", "m2.txt"]), ("someone/feature", ["m1.txt", "m2.txt", "feat.txt"]),
                        ("ttp/t47-near", ["m1.txt", "m2.txt", "near.txt"]), ("ttp/t49-other", ["int.txt"])):
        _git_out(repo, "checkout", "-q", "--detach", root)
        for f in files:
            _commit(repo, f, f"{f}\n")
        _git_out(repo, "push", "-q", "origin", f"HEAD:refs/heads/{name}")
    _git_out(repo, "fetch", "-q", "origin")
    p.set_config("delivery.push_branch", "origin/ttp/t48-int")
    p.set_config("delivery.base_ref", "rt")
    return p, repo, origin


def test_push_never_rebases_a_foreign_based_branch_onto_the_push_target(env, monkeypatch, capsys):
    p, repo, origin = _foreign_setup(env, monkeypatch)
    target = _git_out(origin, "rev-parse", "ttp/t48-int")
    monkeypatch.setenv("TTP_TASK", "60")
    _git_out(repo, "checkout", "-q", "-b", "ttp/t60-h3", "origin/main")
    _commit(repo, "mine.txt", "mine\n")
    mine = _git_out(repo, "rev-parse", "HEAD")
    # Not on origin yet: refused at once, the branch and the push target untouched.
    capsys.readouterr()
    assert _ttp("push") == 2
    err = capsys.readouterr().err
    assert "based on origin/main" in err and "ttp push --own" in err, err
    assert "git rebase --onto origin/ttp/t48-int origin/main" in err, err
    rc, marker, _ = _detach(capsys)
    assert rc == 2 and marker is None
    assert _git_out(repo, "rev-parse", "HEAD") == mine
    assert _git_out(origin, "rev-parse", "ttp/t48-int") == target
    # Already on origin and a fast-forward: pushed there as it is, with no rebase.
    assert _ttp("push", "--own") == 0
    _commit(repo, "more.txt", "more\n")
    head = _git_out(repo, "rev-parse", "HEAD")
    capsys.readouterr()
    assert _ttp("push") == 0
    assert "fast-forward, with no rebase" in capsys.readouterr().err
    assert _git_out(origin, "rev-parse", "ttp/t60-h3") == head == _git_out(repo, "rev-parse", "HEAD")
    assert _git_out(origin, "rev-parse", "ttp/t48-int") == target
    # The detached push resolves the same target.
    _commit(repo, "more2.txt", "more2\n")
    rc, marker, probe = _detach(capsys)
    assert rc == 0
    assert json.loads(marker.read_text())["target"] == "origin/ttp/t60-h3"
    r = _probe_until_done(p, probe)
    assert r.returncode == 0, r
    assert _git_out(origin, "rev-parse", "ttp/t60-h3") == _git_out(repo, "rev-parse", "HEAD")
    assert _git_out(origin, "rev-parse", "ttp/t48-int") == target
    # Diverged from its copy on origin: refused, never rewritten.
    _git_out(repo, "reset", "-q", "--hard", "HEAD~1")
    _commit(repo, "fork.txt", "fork\n")
    assert _ttp("push") == 2
    assert _git_out(origin, "rev-parse", "ttp/t48-int") == target


def test_push_still_rebases_a_published_branch_based_on_base_ref_onto_the_push_target(env, monkeypatch, capsys):
    p, repo, origin = _foreign_setup(env, monkeypatch)
    monkeypatch.setenv("TTP_TASK", "63")
    _git_out(repo, "checkout", "-q", "-b", "ttp/t63-z", "origin/rt")
    _commit(repo, "z.txt", "z\n")
    assert _ttp("push", "--own") == 0
    mine = _git_out(repo, "rev-parse", "HEAD")
    capsys.readouterr()
    assert _ttp("push") == 0
    assert "stays as it is" in capsys.readouterr().err
    landed = _git_out(origin, "rev-parse", "ttp/t48-int")
    assert _git_out(origin, "show", f"{landed}:z.txt") == "z" and landed != mine
    assert _git_out(origin, "rev-parse", "ttp/t63-z") == mine


def test_push_own_without_checks_publishes_docs_only_and_refuses_code(env, monkeypatch, capsys):
    p, repo, origin, other = _push_setup(env, monkeypatch, [])
    p.set_config("delivery.push_checks", [])
    _git_out(repo, "checkout", "-q", "-b", "ttp/t8-exp")
    monkeypatch.setenv("TTP_TASK", "8")
    _commit(repo, "notes.md", "docs\n")
    assert _ttp("push", "--own") == 0
    assert _git_out(origin, "rev-parse", "ttp/t8-exp") == _git_out(repo, "rev-parse", "HEAD")
    docs = _git_out(origin, "rev-parse", "ttp/t8-exp")
    _commit(repo, "tool.py", "x = 1\n")
    capsys.readouterr()
    assert _ttp("push", "--own") == 2
    err = capsys.readouterr().err
    assert "no checks configured" in err and "tool.py" in err
    assert _git_out(origin, "rev-parse", "ttp/t8-exp") == docs


def test_push_own_detached_without_checks_refuses_code_at_once_and_detaches_docs_only(env, monkeypatch, capsys):
    p, repo, origin, other = _push_setup(env, monkeypatch, [])
    p.set_config("delivery.push_checks", [])
    _git_out(repo, "checkout", "-q", "-b", "ttp/t9-exp")
    monkeypatch.setenv("TTP_TASK", "9")
    _commit(repo, "tool.py", "x = 1\n")
    capsys.readouterr()
    assert _ttp("push", "--own", "--detach") == 2
    io = capsys.readouterr()
    assert "no checks configured" in io.err and "tool.py" in io.err and "retry_when" not in io.out
    assert not (p.state / "pushes").exists() or not list((p.state / "pushes").glob("*.json"))
    _git_out(repo, "reset", "-q", "--hard", "HEAD~1")
    _commit(repo, "notes.md", "docs\n")
    assert _ttp("push", "--own", "--detach") == 0
    probe = next(ln.split(": ", 1)[1] for ln in capsys.readouterr().out.splitlines()
                 if ln.startswith("retry_when: "))
    r = _probe_until_done(p, probe)
    assert r.returncode == 0 and _git_out(origin, "rev-parse", "ttp/t9-exp") == _git_out(repo, "rev-parse", "HEAD")


def test_push_own_detached_publishes_the_own_branch_and_reports_it(env, monkeypatch, capsys):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    _git_out(repo, "checkout", "-q", "-b", "ttp/t7-exp")
    _commit(repo, "mine.txt", "mine\n")
    monkeypatch.setenv("TTP_TASK", "7")
    rc = _ttp("push", "--own", "--detach")
    out = capsys.readouterr().out
    probe = next(ln.split(": ", 1)[1] for ln in out.splitlines() if ln.startswith("retry_when: "))
    assert rc == 0 and "origin/ttp/t7-exp" in out
    r = _probe_until_done(p, probe)
    head = _git_out(repo, "rev-parse", "HEAD")
    assert r.returncode == 0 and f"pushed {head} to origin/ttp/t7-exp" in r.stdout, r
    assert _git_out(origin, "rev-parse", "ttp/t7-exp") == head
    assert _git_out(origin, "rev-parse", "proj") != head


def test_a_stopped_detached_push_writes_its_outcome_with_the_signal(env, monkeypatch, capsys):
    started, gate = env["tmp"] / "started", env["tmp"] / "gate"
    p, repo, origin, other = _push_setup(env, monkeypatch, [_gated_check(started, gate)])
    _commit(repo, "mine.txt", "mine\n")
    rc, marker, probe = _detach(capsys)
    pid = json.loads(marker.read_text())["pid"]
    try:
        deadline = time.time() + 30
        while not started.exists() and time.time() < deadline:
            time.sleep(0.05)
        assert started.exists() and json.loads(marker.read_text())["alive"]
        os.kill(pid, signal.SIGTERM)
        r = _probe_until_done(p, probe)
        assert r.returncode == 0 and "not pushed (stopped by SIGTERM)" in r.stdout, r
        assert json.loads(marker.read_text())["exit"] == 1
    finally:
        _release_detached(gate, [pid])


def test_the_push_probe_of_a_missing_marker_wakes_the_task_as_broken(env, monkeypatch):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    assert _ttp("push", "--result", str(p.state / "pushes" / "nope.json")) == 2

def _bump_setup(env, monkeypatch, checks):
    """_push_setup with a plugin `p` at 0.1.0 on the target, versioned in a manifest and a module,
    and `delivery.version_bump` set to bump both and add a changeset."""
    p, repo, origin, other = _push_setup(env, monkeypatch, checks)
    (repo / "plugins/p/.claude-plugin").mkdir(parents=True)
    (repo / "plugins/p/rt").mkdir(parents=True)
    (repo / "plugins/p/.claude-plugin/plugin.json").write_text(
        json.dumps({"name": "p", "version": "0.1.0", "description": "d"}, indent=2) + "\n")
    (repo / "plugins/p/rt/__init__.py").write_text('"""p"""\n__version__ = "0.1.0"\n')
    _git_out(repo, "add", "plugins")
    _git_out(repo, "commit", "-qm", "p 0.1.0")
    _git_out(repo, "push", "-q", "origin", "HEAD:proj")
    _git_out(other, "pull", "-q", "origin", "proj")
    p.set_config("delivery.version_bump", {"files": ["plugins/p/.claude-plugin/plugin.json",
                                                     "plugins/p/rt/__init__.py"], "changeset_dir": ".changeset"})
    return p, repo, origin, other


def _versions(origin):
    return (json.loads(_git_out(origin, "show", "proj:plugins/p/.claude-plugin/plugin.json"))["version"],
            _git_out(origin, "show", "proj:plugins/p/rt/__init__.py").split('"')[-2])


def _bump_commits(origin):
    return _git_out(origin, "log", "--format=%s", "--grep=^Ttp-Version-Bump: ", "proj").splitlines()


def test_racing_pushes_with_version_bump_take_one_version_each_and_check_once(env, monkeypatch):
    """Two reviews push plugin changes at once: the lock orders them, and each bumps once above the
    tip it rebased onto, so neither finds its version taken and reruns its checks."""
    log = env["tmp"] / "checks.log"
    p, repo, origin, other = _bump_setup(env, monkeypatch, [f"echo start >> {log}; sleep 1; echo end >> {log}"])
    _commit(repo, "plugins/p/mine.txt", "mine\n")
    _commit(other, "plugins/p/theirs.txt", "theirs\n")
    procs = [_push_proc(p, d, stdout=subprocess.PIPE, stderr=subprocess.STDOUT) for d in (repo, other)]
    outs = [pr.communicate(timeout=60)[0] for pr in procs]
    assert [pr.returncode for pr in procs] == [0, 0], outs
    assert _versions(origin) == ("0.1.2", "0.1.2")
    bumps = sorted(_bump_commits(origin))
    assert [b[:9] for b in bumps] == ["p: 0.1.1 ", "p: 0.1.2 "], bumps
    assert {b[9:] for b in bumps} == {"(edit plugins/p/mine.txt)", "(edit plugins/p/theirs.txt)"}, bumps
    assert log.read_text().split() == ["start", "end"] * 2, "each push must run its checks once"
    assert not any("round 2" in o for o in outs), outs
    sets = _git_out(origin, "ls-tree", "--name-only", "proj", ".changeset/").split()
    assert len(sets) == 2, sets
    assert all(_git_out(origin, "show", f"proj:{c}").startswith('---\n"p": patch\n---') for c in sets)
    # The manifest keeps its formatting; only the version changed.
    assert _git_out(origin, "show", "proj:plugins/p/.claude-plugin/plugin.json") == \
        json.dumps({"name": "p", "version": "0.1.2", "description": "d"}, indent=2)


def test_version_bump_is_redone_once_above_a_tip_that_moved(env, monkeypatch, capsys):
    """Someone pushes 0.1.1 during our checks: the next round drops our own 0.1.1 bump, rebases
    and bumps to 0.1.2, so one bump commit of ours lands. A failed run's bump is replaced too."""
    once = env["tmp"] / "moved"
    move = (f"test -e {once} || (touch {once} && cd {env['tmp'] / 'other'} && echo x > plugins/p/late.txt"
            f" && sed -i.bak 's/0.1.0/0.1.1/' plugins/p/.claude-plugin/plugin.json plugins/p/rt/__init__.py"
            f" && rm plugins/p/.claude-plugin/plugin.json.bak plugins/p/rt/__init__.py.bak"
            f" && git add -A plugins && git commit -qm 'p: 0.1.1 (late)' && git push -q origin HEAD:proj)")
    gate = env["tmp"] / "pass"
    p, repo, origin, other = _bump_setup(env, monkeypatch, [f"test -e {gate}", move])
    _commit(repo, "plugins/p/mine.txt", "mine\n")
    assert _ttp_push() == 4
    assert _git_out(repo, "log", "-1", "--format=%s") == "p: 0.1.1 (edit plugins/p/mine.txt)"
    gate.touch()
    assert _ttp_push() == 0
    assert "round 2" in capsys.readouterr().err
    assert _versions(origin) == ("0.1.2", "0.1.2")
    assert _bump_commits(origin) == ["p: 0.1.2 (edit plugins/p/mine.txt)"], "earlier bumps must be replaced"
    (cs,) = _git_out(origin, "ls-tree", "--name-only", "proj", ".changeset/").split()
    assert _git_out(origin, "show", f"proj:{cs}").endswith("`p`: edit plugins/p/mine.txt.")


def test_version_bump_keeps_a_changeset_the_change_brings_and_skips_changes_outside_the_plugin(env, monkeypatch):
    p, repo, origin, other = _bump_setup(env, monkeypatch, ["true"])
    (repo / ".changeset").mkdir()
    (repo / ".changeset/mine.md").write_text('---\n"p": patch\n---\n\nWritten by hand.\n')
    _git_out(repo, "add", ".changeset")
    _commit(repo, "plugins/p/mine.txt", "mine\n")
    assert _ttp_push() == 0
    assert _versions(origin) == ("0.1.1", "0.1.1")
    assert _git_out(origin, "ls-tree", "--name-only", "proj", ".changeset/").split() == [".changeset/mine.md"]
    _commit(repo, "outside.txt", "not the plugin\n")
    assert _ttp_push() == 0
    assert _versions(origin) == ("0.1.1", "0.1.1") and len(_bump_commits(origin)) == 1
    # A listed file without a version refuses before writing anything, leaving the tree clean.
    _commit(repo, "plugins/p/rt/__init__.py", '"""p"""\n')
    _commit(repo, "plugins/p/mine.txt", "more\n")
    assert _ttp_push() == 2
    assert _git_out(repo, "status", "--porcelain") == ""


def test_push_checks_see_the_push_mode_and_the_tip_they_push_onto(env, monkeypatch, tmp_path):
    log = env["tmp"] / "modes"
    p, repo, origin, other = _push_setup(env, monkeypatch, [f'echo "$TTP_PUSH_MODE ${{TTP_PUSH_TIP:-none}}" >> {log}'])
    seen = lambda: log.read_text().splitlines()[-1]
    _commit(other, "theirs.txt", "theirs\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    tip = _git_out(origin, "rev-parse", "proj")
    _commit(repo, "mine.dat", "mine\n")
    assert _ttp_push() == 0 and seen() == f"target {tip}"
    # --own: a branch the remote does not have yet has no tip; once published, its tip there.
    _git_out(repo, "checkout", "-q", "-b", "ttp/t30-exp")
    monkeypatch.setenv("TTP_TASK", "30")
    _commit(repo, "own.dat", "1\n")
    assert _ttp("push", "--own") == 0 and seen() == "own none"
    first = _git_out(repo, "rev-parse", "HEAD")
    _commit(repo, "own.dat", "2\n")
    assert _ttp("push", "--own") == 0 and seen() == f"own {first}"
    # ttp checks pushes nothing: no tip.
    monkeypatch.setenv("TTP_RUN_DIR", str(tmp_path))
    from ttp import cli
    cli.main(["checks", "--fresh"])
    assert seen() == "checks none"


def test_push_exclude_paths_is_off_by_default(env, monkeypatch):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    (repo / "tmp").mkdir()
    _commit(repo, "tmp/scratch.txt", "x\n")
    assert _ttp_push() == 0 and _git_out(origin, "show", "proj:tmp/scratch.txt") == "x"


def test_push_exclude_paths_refuses_adds_and_edits_on_the_push_branch_only(env, monkeypatch, capsys):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    (other / "notes").mkdir()
    _commit(other, "notes/old.md", "old\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    _git_out(repo, "pull", "-q", "origin", "proj")
    p.set_config("delivery.push_exclude_paths", ["tmp", "notes/*.md"])
    before = _git_out(origin, "rev-parse", "proj")
    # Deleting a matching file passes.
    _git_out(repo, "rm", "-q", "notes/old.md")
    _git_out(repo, "commit", "-qm", "drop the note")
    assert _ttp_push() == 0
    assert _git_out(origin, "ls-tree", "--name-only", "proj", "notes/") == ""
    before = _git_out(origin, "rev-parse", "proj")
    # An add, even one a later commit deletes again, is refused before anything moves.
    _git_out(repo, "checkout", "-q", "-b", "ttp/t30-exp")
    (repo / "tmp").mkdir()
    _commit(repo, "tmp/scratch.txt", "x\n")
    _commit(repo, "tool.py", "print(1)\n")
    _git_out(repo, "rm", "-q", "tmp/scratch.txt")
    _git_out(repo, "commit", "-qm", "drop scratch")
    head = _git_out(repo, "rev-parse", "HEAD")
    assert _ttp_push() == 2
    err = capsys.readouterr().err
    assert "tmp/scratch.txt" in err and "tool.py" not in err and "ttp push --own" in err
    assert _git_out(origin, "rev-parse", "proj") == before and _git_out(repo, "rev-parse", "HEAD") == head
    # --own is not affected.
    monkeypatch.setenv("TTP_TASK", "30")
    assert _ttp("push", "--own") == 0 and _git_out(origin, "rev-parse", "ttp/t30-exp") == head
    # A modified file is refused too (put there while the guard was off); the key may be a string.
    p.set_config("delivery.push_exclude_paths", [])
    _git_out(repo, "checkout", "-q", "-B", "edit", before)
    (repo / "notes").mkdir(exist_ok=True)
    _commit(repo, "notes/kept.md", "a\n")
    assert _ttp_push() == 0
    p.set_config("delivery.push_exclude_paths", "notes/*.md")
    _commit(repo, "notes/kept.md", "b\n")
    assert _ttp_push() == 2 and "notes/kept.md" in capsys.readouterr().err


# push queue batches (batch.py) --------------------------------------------------------------------
def _entry(repo, name, files):
    """A reviewed branch `name` off the target's tip whose one commit writes `files` ({path: text});
    its head."""
    _git_out(repo, "fetch", "-q", "origin")
    _git_out(repo, "checkout", "-q", "-B", name, "origin/proj")
    for path, text in files.items():
        (repo / path).parent.mkdir(parents=True, exist_ok=True)
        (repo / path).write_text(text)
        _git_out(repo, "add", path)
    _git_out(repo, "commit", "-qm", f"{name}: edit {', '.join(files)}")
    return _git_out(repo, "rev-parse", "HEAD")


def _batch_marker(p, heads, bid="b1", target="origin/proj"):
    """A batch marker as the push queue writes it: entry n (task 100 + n, branch e<n>) pushes heads[n-1]."""
    from ttp.project import write_json
    from ttp import checkdirs
    marker = p.state / "pushes" / f"{bid}.json"
    marker.parent.mkdir(parents=True, exist_ok=True)
    output = checkdirs.new(p.state, marker)
    checkdirs.environment(output, {})
    write_json(marker, {
        "v": 1, "kind": "batch", "id": bid, "status": "running", "phase": "push", "pid": os.getpid(),
        "check_run_dir": str(output), "check_report_dir": str(checkdirs.reports(output)),
        "started": time.time(), "repo": str(p.root), "target": target, "log": str(marker.with_suffix(".log")),
        "lock": str(p.state / "locks" / f"push:run-{bid}.0.lock"),
        "entries": [{"id": n, "task": 100 + n, "branch": f"e{n}", "head": h, "ref": f"refs/ttp/push/{n}"}
                    for n, h in enumerate(heads, 1)]})
    return marker


def _run_batch(p, marker, monkeypatch):
    """`ttp push --batch <marker>` in this process, its go given: (exit code, the marker after it)."""
    from ttp import batch, push
    monkeypatch.setattr(sys, "stdin", io.StringIO(""))
    monkeypatch.setenv("TTP_RUN_DIR", push._read(marker)["check_report_dir"])
    return batch.run_batch(p, marker), push._read(marker)


def test_a_push_batch_runs_its_checks_on_the_priority_slot_while_task_checks_queue(env, monkeypatch, capsys):
    """Every host-wide checks slot busy and a task waiting for one: the batch does not queue behind it."""
    import threading
    from ttp import checkcap
    log = env["tmp"] / "checks.log"
    p, repo, origin, other = _bump_setup(env, monkeypatch, [f'echo "${{{checkcap.HELD_ENV}:-none}}" >> {log}'])
    monkeypatch.setenv("TTP_CHECKS_HOST_MAX", "1")
    heads = [_entry(repo, "e1", {"plugins/p/f1.txt": "1\n"})]
    holder = _cap_holder("other project task #3 (run 9)")
    got = []
    waiter = threading.Thread(target=lambda: got.append(checkcap.acquire("task #4").close()))
    waiter.start()
    try:
        assert _wait_for(lambda: len(checkcap.state()["queued"]) == 1)
        rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
        assert rc == 0 and m["outcome"] == "pushed", m
        assert log.read_text().split() == ["1"], "the checks ran, holding a slot"
        assert got == [], "the queued task still waits for its own slot"
        assert "push checks took the push priority slot (beyond the host-wide cap of 1: 1 task checks running, " \
               "1 queued behind)" in capsys.readouterr().out
    finally:
        holder.kill()
        holder.wait()
        waiter.join(10)
    assert got == [None] and checkcap.line() == ""


def _statuses(m):
    return [r["status"] for r in m["results"]]


def test_a_push_batch_lands_its_entries_with_one_bump_one_changeset_and_one_check_run(env, monkeypatch):
    """Three reviewed changes go out as one push: replayed in order onto the tip, one version bump,
    one changeset for those that bring none, the checks run once, and the target only fast-forwards."""
    log = env["tmp"] / "checks.log"
    p, repo, origin, other = _bump_setup(env, monkeypatch, [f"git rev-parse HEAD >> {log}"])
    before = _git_out(origin, "rev-parse", "proj")
    heads = [_entry(repo, f"e{n}", {f"plugins/p/f{n}.txt": f"{n}\n"}) for n in (1, 2, 3)]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert rc == 0 and m["outcome"] == "pushed" and _statuses(m) == ["pushed"] * 3, m
    assert [r["task"] for r in m["results"]] == [101, 102, 103]
    tip = _git_out(origin, "rev-parse", "proj")
    assert log.read_text().split() == [tip], "the checks run once, on the commit that is pushed"
    assert (m["pushed_sha"], m["tip"], m["version"], m["rounds"]) == (tip, before, "0.1.1", 1)
    assert m["checks"]["runs"] == 1 and m["checks"]["flaky"] is False
    assert _versions(origin) == ("0.1.1", "0.1.1")
    assert _bump_commits(origin) == ["p: 0.1.1 (e1: edit plugins/p/f1.txt; +2 more)"]
    assert _git_out(origin, "rev-list", "--count", f"{before}..proj") == "4"
    assert _git_out(origin, "rev-list", "--merges", f"{before}..proj") == ""
    assert _git_out(origin, "show", "proj:.changeset/p-b1.md") == (
        '---\n"p": patch\n---\n\n`p`:\n\n- e1: edit plugins/p/f1.txt\n- e2: edit plugins/p/f2.txt\n'
        "- e3: edit plugins/p/f3.txt")
    assert m["phase"] == "finished" and m["after_push"] == {"status": "skipped", "reason": "delivery.after_push is not set"}
    assert not list((p.state / "locks").glob("*run-b1*")), "no lock file of the batch is left behind"


def test_a_push_batch_checkout_gets_the_projects_venv_link(env, monkeypatch):
    """The push queue's own checkout gets the project's .venv link, as a code task's worktree does,
    so a check like `.venv/bin/python ...` runs there."""
    p, repo, origin, other = _bump_setup(env, monkeypatch, ["test -x .venv/bin/python"])
    (repo / ".git" / "info" / "exclude").write_text("/.venv\n")
    venv = _fake_venv(repo / ".venv")
    (venv / "bin" / "python").chmod(0o755)
    heads = [_entry(repo, "e1", {"plugins/p/f1.txt": "1\n"})]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert rc == 0 and m["outcome"] == "pushed", m


def test_a_push_batch_reuses_a_pass_on_the_same_tree_and_never_a_failure(env, monkeypatch, capsys):
    """A batch retried on the same merged tree (as after a reboot cut the first) does not run again a
    check that passed there; the check that failed runs again, and a check skipped by if_exists is
    never recorded as a pass. The record is on disk, so a new batch process reads it."""
    from ttp import pushpass
    ran, flag = env["tmp"] / "ran", env["tmp"] / "flag"
    flag.write_text("")
    a = f"git rev-parse HEAD^{{tree}} >> {ran}"
    b = f"test ! -f {flag} -o ! -f f1.txt"
    gone = {"run": "true", "if_exists": "absent.txt"}
    p, repo, origin, other = _push_setup(env, monkeypatch, [a, b, gone])
    heads = [_entry(repo, "e1", {"f1.txt": "1\n"})]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert m["results"][0]["status"] != "pushed", m
    first = ran.read_text().split()
    assert len(first) == 2, "the head, then the tip alone"
    store = json.loads((p.state / pushpass.STORE).read_text())["passes"]
    assert sorted(e["cmd"] for e in store) == sorted([a, a, b]), "passes only: never b's failure, never the skipped check"
    flag.unlink()
    capsys.readouterr()
    rc, m = _run_batch(p, _batch_marker(p, heads, bid="b2"), monkeypatch)
    assert rc == 0 and m["outcome"] == "pushed", m
    assert ran.read_text().split() == first, "a's pass on the same tree was reused, not run again"
    assert f"reused pass from b1 (tree {first[0][:10]}): {a}" in capsys.readouterr().out
    assert m["checks"]["reused"] == 1


def _pass_key_parts(env, monkeypatch):
    from ttp import push, pushpass
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    tree = pushpass.tree_of(repo, "HEAD")
    return p, repo, tree, dict(os.environ)


def test_push_check_passes_are_keyed_on_tree_command_and_interpreter(env, monkeypatch):
    from ttp import pushpass
    monkeypatch.delenv("VIRTUAL_ENV", raising=False)
    p, repo, tree, cenv = _pass_key_parts(env, monkeypatch)
    eid = pushpass.env_id(repo, "python3 -m pytest -q", cenv, "tip")
    assert pushpass.record(p, tree, "python3 -m pytest -q", eid, "b1") == ""
    assert pushpass.passed(p, tree, "python3 -m pytest -q", eid)["batch"] == "b1"
    assert pushpass.passed(p, "0" * 40, "python3 -m pytest -q", eid) is None, "another tree"
    assert pushpass.passed(p, tree, "python3 -m pytest -q -x", eid) is None, "another command"
    assert pushpass.env_id(repo, "python3 -m pytest -q", cenv, "other") != eid, "another tip"
    bin_ = env["tmp"] / "otherbin"
    bin_.mkdir()
    (bin_ / "python3").write_text("#!/bin/sh\n")
    (bin_ / "python3").chmod(0o755)
    other = {**cenv, "PATH": f"{bin_}{os.pathsep}{cenv.get('PATH', '')}"}
    assert pushpass.env_id(repo, "python3 -m pytest -q", other, "tip") != eid, "another python3"
    venv = _fake_venv(repo / ".venv")
    (venv / "bin" / "python").chmod(0o755)
    (venv / "bin" / "pytest").write_text("")
    with_venv = pushpass.env_id(repo, "python3 -m pytest -q", cenv, "tip")
    assert with_venv != eid, "a venv the check now runs with"
    site = venv / "lib" / "python3" / "site-packages"
    site.mkdir(parents=True)
    os.utime(site, ns=(1, 1))
    before = pushpass.env_id(repo, "python3 -m pytest -q", cenv, "tip")
    (site / "newpkg").mkdir()
    assert pushpass.env_id(repo, "python3 -m pytest -q", cenv, "tip") != before, "a package installed in the venv"


def test_push_check_passes_and_resume_files_are_pruned(env, monkeypatch):
    from ttp import pushpass
    p, repo, tree, cenv = _pass_key_parts(env, monkeypatch)
    real = time.time
    monkeypatch.setattr(pushpass, "MAX", 3)
    for n in range(5):
        pushpass.record(p, tree, f"c{n}", "e", f"b{n}")
    store = json.loads((p.state / pushpass.STORE).read_text())["passes"]
    assert [e["cmd"] for e in store] == ["c2", "c3", "c4"]
    clock = time.time() + pushpass.MAX_AGE_S + 1
    monkeypatch.setattr(pushpass.time, "time", lambda: clock)
    assert pushpass.passed(p, tree, "c4", "e") is None, "an entry past MAX_AGE_S is not served"
    pushpass.record(p, tree, "c5", "e", "b5")
    assert [e["cmd"] for e in json.loads((p.state / pushpass.STORE).read_text())["passes"]] == ["c5"]
    monkeypatch.setattr(pushpass.time, "time", real)
    folder = p.state / pushpass.RESUME_DIR
    folder.mkdir(parents=True)
    monkeypatch.setattr(pushpass, "RESUME_MAX", 2)
    now = time.time()
    for n in range(4):
        (folder / f"k{n}.txt").write_text("a.py\n")
        os.utime(folder / f"k{n}.txt", (now - 10 + n, now - 10 + n))
    (folder / "old.txt").write_text("")
    os.utime(folder / "old.txt", (now - pushpass.RESUME_MAX_AGE_S - 5,) * 2)
    keep = folder / "k0.txt"
    pushpass.prune(folder, keep=keep)
    assert sorted(f.name for f in folder.iterdir()) == ["k0.txt", "k2.txt", "k3.txt"]


_RESUME_TESTS = {
    "test_a.py": "def test_a1(log): log('a1')\ndef test_a2(log): log('a2')\n",
    "test_b.py": "import os\ndef test_b(log):\n    log('b')\n    assert not os.path.exists(os.environ['FLAG'])\n",
    "test_c.py": "def test_c(log): log('c')\n",
    "conftest.py": ("import os, pytest\n@pytest.fixture\ndef log():\n"
                    "    return lambda s: open(os.environ['LOG'], 'a').write(s + '\\n')\n"),
}


def test_the_resume_plugin_skips_only_test_files_that_passed(env, tmp_path):
    """The pytest plugin records each file whose tests all passed; the next run skips those and runs
    the rest, and a run with every file recorded passes without running any."""
    from ttp import pushpass
    suite, log, flag = tmp_path / "suite", tmp_path / "log", tmp_path / "flag"
    suite.mkdir()
    for name, text in _RESUME_TESTS.items():
        (suite / name).write_text(text)
    flag.write_text("")
    record = tmp_path / "state" / "k.txt"
    base = {k: v for k, v in os.environ.items() if k not in ("PYTEST_ADDOPTS", "PYTHONPATH")}
    base.update(LOG=str(log), FLAG=str(flag))

    def run():
        e = {**base, **pushpass.resume_env(record, base)}
        return subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", "."], cwd=suite,
                              env=e, capture_output=True, text=True)

    r = run()
    assert r.returncode == 1, r.stdout
    assert sorted(pushpass.resumed(record)) == ["test_a.py", "test_c.py"], "never the file that failed"
    assert log.read_text().split() == ["a1", "a2", "b", "c"]
    flag.unlink()
    log.write_text("")
    r = run()
    assert r.returncode == 0, r.stdout
    assert log.read_text().split() == ["b"], "only the file that did not pass runs"
    assert "ttp: resuming: 2 test file(s) passed" in r.stdout
    log.write_text("")
    r = run()
    assert r.returncode == 0 and log.read_text() == "", r.stdout


def test_the_resume_plugin_forgets_files_when_the_session_fails_though_every_test_passed(env, tmp_path):
    from ttp import pushpass
    suite = tmp_path / "suite"
    suite.mkdir()
    (suite / "test_a.py").write_text("def test_a(): pass\n")
    (suite / "conftest.py").write_text(
        "import os\ndef pytest_sessionfinish(session, exitstatus):\n"
        "    if os.path.exists(os.environ['FLAG']): session.exitstatus = 1\n")
    flag, record = tmp_path / "flag", tmp_path / "k.txt"
    flag.write_text("")
    base = {k: v for k, v in os.environ.items() if k not in ("PYTEST_ADDOPTS", "PYTHONPATH")}
    base["FLAG"] = str(flag)

    def run():
        e = {**base, **pushpass.resume_env(record, base)}
        return subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", "."], cwd=suite,
                              env=e, capture_output=True, text=True)

    assert run().returncode == 1
    assert pushpass.resumed(record) == [], "a failed session leaves nothing to resume"
    r = run()
    assert r.returncode == 1 and "resuming" not in r.stdout, "the next run reruns and does not pass"


def test_the_resume_plugin_keeps_itself_out_of_a_pytest_a_test_starts(env, tmp_path):
    from ttp import pushpass
    suite = tmp_path / "suite"
    suite.mkdir()
    (suite / "test_env.py").write_text(
        "import os\ndef test_env():\n    assert 'TTP_PYTEST_RESUME' not in os.environ\n"
        "    assert 'ttp_pytest_resume' not in os.environ.get('PYTEST_ADDOPTS', '')\n")
    base = {k: v for k, v in os.environ.items() if k not in ("PYTEST_ADDOPTS", "PYTHONPATH")}
    e = {**base, **pushpass.resume_env(tmp_path / "k.txt", base)}
    r = subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", "."], cwd=suite, env=e,
                       capture_output=True, text=True)
    assert r.returncode == 0, r.stdout
    assert pushpass.resumed(tmp_path / "k.txt") == ["test_env.py"]


def test_only_a_single_plain_pytest_run_resumes():
    sys.path.insert(0, str(RUNTIME))
    from ttp import pushpass
    assert pushpass.resumable("python3 -m pytest -q tests/a.py")
    assert pushpass.resumable("cd sub && timeout 600 pytest -q")
    assert not pushpass.resumable("pytest -q a.py && pytest -q b.py"), "two runs could share a file"
    assert not pushpass.resumable("PYTHONPATH=src pytest -q"), "it would drop the plugin's path"
    assert not pushpass.resumable("PYTEST_ADDOPTS=-x pytest -q")
    assert not pushpass.resumable("./run_tests.sh")


def test_a_push_batch_resumes_a_pytest_check_that_was_cut(env, monkeypatch, capsys):
    """A pytest check that did not finish on a tree runs, on the next batch of that tree, only the
    test files that did not pass; its whole pass then removes the resume record."""
    from ttp import pushpass
    monkeypatch.delenv("VIRTUAL_ENV", raising=False)
    monkeypatch.delenv("PYTEST_ADDOPTS", raising=False)
    monkeypatch.setenv("PATH", f"{pathlib.Path(sys.executable).parent}{os.pathsep}{os.environ['PATH']}")
    log, flag = env["tmp"] / "log", env["tmp"] / "flag"
    monkeypatch.setenv("LOG", str(log))
    monkeypatch.setenv("FLAG", str(flag))
    cmd = "python3 -m pytest -q -p no:cacheprovider suite"
    p, repo, origin, other = _push_setup(env, monkeypatch, [cmd])
    for name, text in _RESUME_TESTS.items():
        (repo / "suite").mkdir(exist_ok=True)
        (repo / "suite" / name).write_text(text.replace("assert not", "assert not os.path.exists('f1.txt') or not"))
    _git_out(repo, "add", "suite")
    _git_out(repo, "commit", "-qm", "suite")
    _git_out(repo, "push", "-q", "origin", "HEAD:proj")
    heads = [_entry(repo, "e1", {"f1.txt": "1\n"})]
    flag.write_text("")
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert m["results"][0]["status"] != "pushed", m
    from ttp import batch
    assert log.read_text().split() == ["a1", "a2", "b", "c", "b"] + ["b"] * batch.TIP_RERUNS, \
        "the head, its failing test once more there, then only that test on the tip alone, TIP_RERUNS times"
    flag.unlink()
    log.write_text("")
    capsys.readouterr()
    rc, m = _run_batch(p, _batch_marker(p, heads, bid="b2"), monkeypatch)
    assert rc == 0 and m["outcome"] == "pushed", m
    assert log.read_text().split() == ["b"]
    out = capsys.readouterr().out
    assert f"resuming {cmd}: 2 test file(s) passed" in out
    from ttp import slowtests   # the check's slowest tests, next to the batch's check report, in its log
    slow = slowtests.load(pathlib.Path(m["check_report_dir"]) / slowtests.FILE)
    assert [t for t, _ in slow] == ["suite/test_b.py::test_b"], slow
    assert "slowest 1 tests" in out and "suite/test_b.py::test_b" in out
    assert not list((p.state / pushpass.RESUME_DIR).glob("*.txt")), "a whole pass removes its resume record"

def _merge_entry(repo, name):
    """Entry `name`: a --no-ff merge, on origin/proj, of a task branch whose first commit is tagged."""
    _entry(repo, f"{name}-task", {f"plugins/p/{name}a.txt": "a\n"})
    _git_out(repo, "tag", f"{name}-done")
    _commit(repo, f"plugins/p/{name}b.txt", "b\n")
    _git_out(repo, "checkout", "-q", "-B", name, "origin/proj")
    _git_out(repo, "merge", "-q", "--no-ff", "-m", f"land {name}", f"{name}-task")
    return _git_out(repo, "rev-parse", "HEAD"), _git_out(repo, "rev-parse", f"{name}-done")


def test_a_push_batch_keeps_a_merge_landing_and_its_tagged_commits(env, monkeypatch):
    """An entry that already descends from the tip goes out as it is, with its merge (no flattening
    rebase, so a tag on its commits stays an ancestor); one needing a rebase keeps its merge too."""
    p, repo, origin, other = _bump_setup(env, monkeypatch, ["true"])
    before = _git_out(origin, "rev-parse", "proj")
    h1, tagged = _merge_entry(repo, "e1")
    rc, m = _run_batch(p, _batch_marker(p, [h1]), monkeypatch)
    assert rc == 0 and _statuses(m) == ["pushed"], m
    assert _git_out(origin, "rev-parse", "proj^") == h1, "the entry goes out as it is, under the bump"
    assert _git_out(origin, "merge-base", "--is-ancestor", tagged, "proj") == ""
    assert _git_out(origin, "log", "--merges", "--format=%s", f"{before}..proj") == "land e1"

    h2, _ = _merge_entry(repo, "e2")
    _git_out(other, "pull", "-q", "origin", "proj")
    _commit(other, "late.txt", "late\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    moved = _git_out(origin, "rev-parse", "proj")
    rc, m = _run_batch(p, _batch_marker(p, [h2], bid="b2"), monkeypatch)
    assert rc == 0 and _statuses(m) == ["pushed"], m
    assert _git_out(origin, "log", "--merges", "--format=%s", f"{moved}..proj") == "land e2", "flattened"
    assert sorted(_git_out(origin, "log", "--no-merges", "--format=%s", f"{moved}..proj").splitlines())[:2] \
        == ["e2-task: edit plugins/p/e2a.txt", "edit plugins/p/e2b.txt"]
    assert _git_out(origin, "show", "proj:plugins/p/e2b.txt") == "b"


def test_a_push_batch_refuses_an_entry_adding_an_excluded_path_and_runs_checks_as_target(env, monkeypatch):
    log = env["tmp"] / "modes"
    p, repo, origin, other = _bump_setup(env, monkeypatch, [f'echo "$TTP_PUSH_MODE $TTP_PUSH_TIP" >> {log}'])
    p.set_config("delivery.push_exclude_paths", ["tmp"])
    before = _git_out(origin, "rev-parse", "proj")
    heads = [_entry(repo, "e1", {"plugins/p/f1.txt": "1\n", "tmp/notes.md": "n\n"}),
             _entry(repo, "e2", {"plugins/p/f2.txt": "2\n"})]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert _statuses(m) == ["refused", "pushed"], m
    msg = m["results"][0]["detail"]["message"]
    assert "tmp/notes.md" in msg and "ttp push --own" in msg
    assert _git_out(origin, "ls-tree", "-r", "--name-only", "proj", "tmp") == ""
    assert log.read_text().split() == ["target", before]


def test_a_push_batch_entry_already_on_the_target_is_landed_without_a_bump(env, monkeypatch):
    p, repo, origin, other = _bump_setup(env, monkeypatch, ["true"])
    h1 = _entry(repo, "e1", {"plugins/p/f1.txt": "1\n"})
    _git_out(repo, "push", "-q", "origin", f"{h1}:refs/heads/proj")
    rc, m = _run_batch(p, _batch_marker(p, [h1]), monkeypatch)
    assert rc == 0 and m["outcome"] == "landed" and _statuses(m) == ["landed"], m
    assert _git_out(origin, "rev-parse", "proj") == h1 and _bump_commits(origin) == []
    # Delivered as another commit (rebased onto a tip that moved): landed too.
    h2 = _entry(repo, "e2", {"plugins/p/f2.txt": "2\n"})
    _entry(repo, "late", {"late.txt": "late\n"})
    _git_out(repo, "cherry-pick", h2)
    _git_out(repo, "push", "-q", "origin", "HEAD:proj")
    before = _git_out(origin, "rev-parse", "proj")
    rc, m = _run_batch(p, _batch_marker(p, [h2], bid="b2"), monkeypatch)
    assert m["outcome"] == "landed" and _git_out(origin, "rev-parse", "proj") == before, m
    # A head ending in a bump of its own (a push that failed after bumping) goes out with one bump: ours.
    _entry(repo, "e3", {"plugins/p/f3.txt": "3\n"})
    for f in ("plugins/p/.claude-plugin/plugin.json", "plugins/p/rt/__init__.py"):
        (repo / f).write_text((repo / f).read_text().replace("0.1.0", "0.1.7"))
    _git_out(repo, "commit", "-qam", "p: 0.1.7 (stale)\n\nTtp-Version-Bump: 0.1.7")
    rc, m = _run_batch(p, _batch_marker(p, [_git_out(repo, "rev-parse", "HEAD")], bid="b3"), monkeypatch)
    assert m["outcome"] == "pushed" and _versions(origin) == ("0.1.1", "0.1.1"), m
    assert _bump_commits(origin) == ["p: 0.1.1 (e3: edit plugins/p/f3.txt)"]


def test_a_push_batch_carries_a_merge_entry_whose_rebase_conflicts_as_one_commit_of_its_clean_merge(
        env, monkeypatch):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    _f_base(repo, origin)
    head = _merge_then_edit(repo, other)
    moved = _git_out(origin, "rev-parse", "proj")
    rc, m = _run_batch(p, _batch_marker(p, [head]), monkeypatch)
    assert rc == 0 and _statuses(m) == ["pushed"], m
    pushed = _git_out(origin, "rev-parse", "proj")
    assert _git_out(origin, "rev-parse", f"{pushed}^") == moved and m["results"][0].get("sha") == pushed
    for name, text in (("f.txt", "1\n2z\n3"), ("g.txt", "g"), ("late.txt", "late")):
        assert _git_out(origin, "show", f"proj:{name}") == text, name


def test_a_push_batch_entry_with_a_real_conflict_stays_out_and_the_others_land(env, monkeypatch, capsys):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    _commit(other, "notes.txt", "a\nb\nc\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    heads = [_entry(repo, "e1", {"notes.txt": "a\nB1\nc\n"}), _entry(repo, "e2", {"notes.txt": "a\nB2\nc\n"}),
             _entry(repo, "e3", {"more.txt": "3\n"})]
    marker = _batch_marker(p, heads)
    rc, m = _run_batch(p, marker, monkeypatch)
    assert rc == 0 and m["outcome"] == "pushed" and _statuses(m) == ["pushed", "conflict", "pushed"], m
    assert m["results"][1]["detail"] == {"files": ["notes.txt"], "onto": heads[0]}
    assert _git_out(origin, "show", "proj:notes.txt") == "a\nB1\nc"
    assert _git_out(origin, "show", "proj:more.txt") == "3"
    capsys.readouterr()
    assert _ttp("push", "--result", str(marker)) == 0
    out = capsys.readouterr().out
    assert f"ttp push: batch b1: pushed, {m['pushed_sha'][:10]} to origin/proj" in out, out
    assert "#2 task 102 e2: conflict in notes.txt" in out and "#3 task 103 e3: pushed" in out, out
    # A batch whose process still holds its lock is running; one that died before its outcome is over.
    from ttp import locks
    live = _batch_marker(p, heads, bid="b2")
    held = locks.try_take([p.state / "locks" / "push:run-b2.0.lock"], "push queue")
    assert _ttp("push", "--result", str(live)) == 1 and "still running" in capsys.readouterr().out
    held.close()
    assert _ttp("push", "--result", str(live)) == 0 and "without an outcome" in capsys.readouterr().out


def test_a_push_batch_settles_version_lines_and_lines_both_sides_added(env, monkeypatch):
    """Two changes each bumped the version by hand and each added a test at the end of one file; both
    conflict, and neither conflict needs judgment. The batch takes its own version and keeps both
    tests, and the checks (which run every test) judge the result."""
    log = env["tmp"] / "tests.log"
    run_tests = (f"python3 -c \"import runpy; ns = runpy.run_path('tests/test_x.py'); "
                 f"names = sorted(n for n in ns if n.startswith('test_')); [ns[n]() for n in names]; "
                 f"open('{log}', 'a').write(' '.join(names) + chr(10))\"")
    p, repo, origin, other = _bump_setup(env, monkeypatch, [run_tests])
    (other / "tests").mkdir()
    _commit(other, "tests/test_x.py", "def test_a():\n    assert True\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    versioned = ("plugins/p/.claude-plugin/plugin.json", "plugins/p/rt/__init__.py")
    base = {f: _git_out(origin, "show", f"proj:{f}") + "\n" for f in versioned}

    def change(name, version, test):
        files = {f: base[f].replace("0.1.0", version) for f in versioned}
        files["tests/test_x.py"] = f"def test_a():\n    assert True\n\n\ndef {test}():\n    assert True\n"
        files[f"plugins/p/{name}.txt"] = f"{name}\n"
        return _entry(repo, name, files)
    heads = [change("e1", "0.1.1", "test_b"), change("e2", "0.1.5", "test_c")]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert rc == 0 and m["outcome"] == "pushed" and _statuses(m) == ["pushed", "pushed"], m
    assert log.read_text().splitlines() == ["test_a test_b test_c"]
    assert _git_out(origin, "show", "proj:tests/test_x.py") == (
        "def test_a():\n    assert True\n\n\ndef test_b():\n    assert True\n\n\ndef test_c():\n    assert True")
    assert _versions(origin) == ("0.1.1", "0.1.1") and len(_bump_commits(origin)) == 1


def test_a_push_batch_takes_both_changes_of_adjacent_lines_and_sends_back_only_a_real_overlap(env, monkeypatch, capsys):
    """Three changes of one file: the first two edit adjacent lines (a conflict to git, none in fact),
    the third edits the line the first changed. The batch takes both of the first two, runs the checks
    on the result and pushes it; only the third goes back. The marker and the log count it all."""
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    _commit(other, "notes.txt", "a\nb\nc\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    heads = [_entry(repo, "e1", {"notes.txt": "A1\nb\nc\n"}), _entry(repo, "e2", {"notes.txt": "a\nB2\nc\n"}),
             _entry(repo, "e3", {"notes.txt": "A3\nb\nc\n"})]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert m["outcome"] == "pushed" and _statuses(m) == ["pushed", "pushed", "conflict"], m
    assert _git_out(origin, "show", "proj:notes.txt") == "A1\nB2\nc"
    assert m["results"][1]["detail"] == {"settled": ["notes.txt"], "settled_by": ["hunks"]}
    assert "settled" not in m["results"][0]["detail"] and m["results"][2]["detail"]["files"] == ["notes.txt"]
    assert m["conflicts"] == {"entries": 3, "conflicted": 2, "auto_resolved": 1, "by_hunks": 1, "sent_back": 1}
    out = capsys.readouterr().out
    assert "settled notes.txt (changes of different lines)" in out
    assert "conflicts: 2 of 3 entries, 1 settled without judgment (1 by changes of different lines), 1 sent back" in out


def test_a_push_batch_sends_back_an_entry_whose_merged_changes_fail_the_checks(env, monkeypatch):
    """The checks fail only on the result of taking both sides' changes of different lines: the entry
    whose replay merged them goes back as a conflict (the merge may be the cause), not check_failed,
    and counts as sent back, not as resolved."""
    p, repo, origin, other = _push_setup(env, monkeypatch, ["! grep -q A1 notes.txt || ! grep -q B2 notes.txt"])
    _commit(other, "notes.txt", "a\nb\nc\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    heads = [_entry(repo, "e1", {"notes.txt": "A1\nb\nc\n"}), _entry(repo, "e2", {"notes.txt": "a\nB2\nc\n"})]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert m["outcome"] == "pushed" and _statuses(m) == ["pushed", "conflict"], m
    d = m["results"][1]["detail"]
    assert d["files"] == ["notes.txt"] and d["settled_by"] == ["hunks"] and d["cmd"].startswith("! grep"), d
    assert _git_out(origin, "show", "proj:notes.txt") == "A1\nb\nc"
    assert m["conflicts"] == {"entries": 2, "conflicted": 1, "auto_resolved": 0, "by_hunks": 0, "sent_back": 1}


@pytest.mark.parametrize("passes", [True, False])
def test_a_push_batch_keeps_parallel_test_additions_only_when_the_checks_pass(env, monkeypatch, passes):
    """Two changes each append a new test function at the end of one test file: a conflict to git
    that the batch settles without a model by keeping both. With checks that pass on the result both
    land; when the checks fail only on the merged file, the second entry goes back as a conflict (for
    a rebase), not check_failed, and the first lands alone."""
    check = "true" if passes else "! (grep -q test_one test_x.py && grep -q test_two test_x.py)"
    p, repo, origin, other = _push_setup(env, monkeypatch, [check])
    _commit(other, "test_x.py", "def test_base():\n    assert True\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    heads = [_entry(repo, "e1", {"test_x.py": "def test_base():\n    assert True\n\n\ndef test_one():\n    pass\n"}),
             _entry(repo, "e2", {"test_x.py": "def test_base():\n    assert True\n\n\ndef test_two():\n    pass\n"})]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert m["outcome"] == "pushed", m
    landed = _git_out(origin, "show", "proj:test_x.py")
    if passes:
        assert _statuses(m) == ["pushed", "pushed"]
        assert m["results"][1]["detail"] == {"settled": ["test_x.py"], "settled_by": ["added"]}
        assert "def test_one" in landed and "def test_two" in landed
    else:
        assert _statuses(m) == ["pushed", "conflict"], m
        d = m["results"][1]["detail"]
        assert d["files"] == ["test_x.py"] and d["settled_by"] == ["added"] and d["cmd"] == check, d
        assert "def test_one" in landed and "def test_two" not in landed
        assert m["conflicts"]["sent_back"] == 1 and m["conflicts"]["auto_resolved"] == 0


def test_a_push_batch_does_not_settle_an_addition_that_repeats_a_top_level_name(env, monkeypatch):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    _commit(other, "test_x.py", "def test_a():\n    assert True\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    heads = [_entry(repo, f"e{n}", {"test_x.py": f"def test_a():\n    assert True\n\n\ndef test_b():\n    assert {n}\n"})
             for n in (1, 2)]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert _statuses(m) == ["pushed", "conflict"] and m["results"][1]["detail"]["files"] == ["test_x.py"], m
    assert _git_out(origin, "show", "proj:test_x.py").endswith("assert 1")


def test_a_push_batch_never_pushes_again_an_entry_it_settled_and_pushed(env, monkeypatch):
    """A fresh batch gets the entries of one that pushed and died before recording it (design §7).
    The entry settled against the one before it went out as another patch (its context changed), so
    git cherry does not match it; the trailer naming the commit it replays does: it is landed, never
    a conflict for its review to look into, nor a second push of its line and a second bump."""
    p, repo, origin, other = _bump_setup(env, monkeypatch, ["true"])
    _commit(other, "plugins/p/notes.txt", "a\nc\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    heads = [_entry(repo, f"e{n}", {"plugins/p/notes.txt": f"a\nX{n}\nc\n"}) for n in (1, 2)]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert rc == 0 and _statuses(m) == ["pushed", "pushed"], m
    assert _git_out(origin, "show", "proj:plugins/p/notes.txt") == "a\nX1\nX2\nc"
    tip = _git_out(origin, "rev-parse", "proj")
    for bid, again in (("b2", heads), ("b3", heads[1:])):
        rc, m = _run_batch(p, _batch_marker(p, again, bid=bid), monkeypatch)
        assert rc == 0 and m["outcome"] == "landed" and _statuses(m) == ["landed"] * len(again), m
        assert m["pushed_sha"] is None and _git_out(origin, "rev-parse", "proj") == tip, "nothing goes out again"
    assert _versions(origin) == ("0.1.1", "0.1.1") and len(_bump_commits(origin)) == 1
    settled = _git_out(origin, "log", "-1", "--format=%B%x00%an%x00%ad", "proj^", "--", "plugins/p/notes.txt")
    msg, author, date = settled.split("\0")
    assert msg.splitlines()[0] == "e2: edit plugins/p/notes.txt" and f"Ttp-Replayed-From: {heads[1]}" in msg
    assert (author, date) == tuple(_git_out(repo, "log", "-1", "--format=%an%x00%ad", heads[1]).split("\0"))
    # Only a commit the trailer names counts: the same change made anew still conflicts.
    _git_out(repo, "checkout", "-q", "-B", "e3", heads[1])
    _git_out(repo, "commit", "-q", "--amend", "-m", "e3: the same line, another commit")
    again = _git_out(repo, "rev-parse", "HEAD")
    rc, m = _run_batch(p, _batch_marker(p, [again], bid="b4"), monkeypatch)
    assert _statuses(m) == ["conflict"] and m["results"][0]["detail"]["files"] == ["plugins/p/notes.txt"], m


def _reused(capsys, cmd):
    """How many times the batch reused a recorded pass of `cmd` instead of running it."""
    return sum(1 for line in capsys.readouterr().out.splitlines() if "reused pass from" in line and line.endswith(cmd))


@pytest.mark.parametrize("bad", [1, 3, 4])
def test_a_push_batch_blames_the_first_failing_entry_and_pushes_the_ones_before_it(env, monkeypatch, capsys, bad):
    """Four entries, one of which breaks the checks: a binary search over prefixes finds it in at most
    three more check runs (ceil(log2 4) + 1). The entries before it go, and the later ones too after
    one more check of them replayed without it."""
    log = env["tmp"] / "checks.log"
    p, repo, origin, other = _bump_setup(env, monkeypatch, [f"echo run >> {log}", "test ! -e plugins/p/bad.txt"])
    heads = [_entry(repo, f"e{n}", {f"plugins/p/{'bad' if n == bad else f'f{n}'}.txt": f"{n}\n"}) for n in (1, 2, 3, 4)]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    good = [n for n in (1, 2, 3, 4) if n != bad]
    assert _statuses(m) == ["check_failed" if n == bad else "pushed" for n in (1, 2, 3, 4)], m
    assert m["results"][bad - 1]["detail"]["cmd"] == "test ! -e plugins/p/bad.txt"
    runs = len(log.read_text().split()) + _reused(capsys, f"echo run >> {log}")   # a recheck of a tree reuses its passes
    assert runs == m["checks"]["runs"] and runs - 1 <= 3 + (bad < 4), runs
    if bad == 1:
        assert m["tip_passed"] is True, "the tip passed alone: the queue may forget it as failing"
    assert rc == 0 and m["outcome"] == "pushed" and _versions(origin) == ("0.1.1", "0.1.1")
    more = f"; +{len(good) - 1} more" if len(good) > 1 else ""
    assert _bump_commits(origin) == [f"p: 0.1.1 (e{good[0]}: edit plugins/p/f{good[0]}.txt{more})"]
    names = _git_out(origin, "ls-tree", "--name-only", "proj", "plugins/p/").split()
    assert [n for n in names if n.endswith(".txt")] == [f"plugins/p/f{n}.txt" for n in good]
    assert f"e{good[-1]}: edit" in _git_out(origin, "show", "proj:.changeset/p-b1.md")
    assert f"e{bad}:" not in _git_out(origin, "show", "proj:.changeset/p-b1.md")


def test_a_push_batch_whose_target_fails_its_checks_alone_pushes_nothing(env, monkeypatch):
    p, repo, origin, other = _bump_setup(env, monkeypatch, ["test ! -e broken.txt"])
    _commit(other, "broken.txt", "x\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    before = _git_out(origin, "rev-parse", "proj")
    heads = [_entry(repo, f"e{n}", {f"plugins/p/f{n}.txt": f"{n}\n"}) for n in (1, 2)]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert rc == 4 and m["outcome"] == "tip_failed" and _statuses(m) == ["requeued", "requeued"], m
    assert m["tip_check"]["cmd"] == "test ! -e broken.txt" and m["checks"]["runs"] == 3 and m["tip_tried"] == [1]
    assert _git_out(origin, "rev-parse", "proj") == before and m["pushed_sha"] is None


def test_a_push_batch_starts_over_when_the_target_moves_and_gives_up_when_it_keeps_moving(env, monkeypatch):
    once = env["tmp"] / "moved"
    move = (f"cd {env['tmp'] / 'other'} && git pull -q --rebase origin proj && echo x >> late.txt"
            " && git add late.txt && git commit -qm late && git push -q origin HEAD:proj")
    p, repo, origin, other = _push_setup(env, monkeypatch, [f"test -e {once} || (touch {once} && {move})"])
    heads = [_entry(repo, f"e{n}", {f"f{n}.txt": f"{n}\n"}) for n in (1, 2)]
    rc, m = _run_batch(p, _batch_marker(p, heads), monkeypatch)
    assert rc == 0 and m["outcome"] == "pushed" and m["rounds"] == 2 and m["checks"]["runs"] == 2, m
    assert _git_out(origin, "show", "proj:late.txt") == "x" and _git_out(origin, "show", "proj:f2.txt") == "2"
    assert m["tip"] == _git_out(origin, "rev-parse", "proj~2"), "round 2 replays onto the moved tip"
    # A target that moves during every check run: after delivery.push_rounds the batch gives up.
    p.set_config("delivery.push_checks", [move])
    p.set_config("delivery.push_rounds", 2)
    rc, m = _run_batch(p, _batch_marker(p, [_entry(repo, "e3", {"f3.txt": "3\n"})], bid="b2"), monkeypatch)
    assert rc == 5 and m["outcome"] == "moved" and m["rounds"] == 2 and _statuses(m) == ["requeued"], m
    assert "f3.txt" not in _git_out(origin, "ls-tree", "--name-only", "proj")


def test_a_push_batch_refuses_main_the_remotes_default_branch_and_a_changed_target(env, monkeypatch):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    heads = [_entry(repo, "e1", {"f1.txt": "1\n"})]
    before = _git_out(origin, "rev-parse", "proj")
    p.set_config("delivery.push_branch", "origin/main")
    rc, m = _run_batch(p, _batch_marker(p, heads, target="origin/main"), monkeypatch)
    assert rc == 2 and m["outcome"] == "refused" and _statuses(m) == ["refused"], m
    assert m["results"][0]["detail"]["message"].startswith("refusing to push to origin/main")
    p.set_config("delivery.push_branch", "origin/proj")
    subprocess.run(["git", "-C", str(origin), "symbolic-ref", "HEAD", "refs/heads/proj"], check=True)
    rc, m = _run_batch(p, _batch_marker(p, heads, bid="b2"), monkeypatch)
    assert rc == 2 and _statuses(m) == ["refused"] and "default branch" in m["message"], m
    # The configured target changed after the batch was made: its entries wait for a batch to the new one.
    rc, m = _run_batch(p, _batch_marker(p, heads, bid="b3", target="origin/old"), monkeypatch)
    assert rc == 2 and m["outcome"] == "refused" and _statuses(m) == ["requeued"], m
    assert _git_out(origin, "rev-parse", "proj") == before
    assert subprocess.run(["git", "-C", str(origin), "rev-parse", "-q", "--verify", "main"]).returncode != 0


def test_after_push_runs_at_the_pushed_commit_in_a_clean_checkout_with_the_push_locks_let_go(env, monkeypatch):
    """The batch process inherits its run lock from the push queue. After the push it lets go of that
    lock and of the push lock, so automatic upgrades do not wait for the deploy, and it runs
    after_push at the pushed commit, in a fresh checkout, with the batch's facts in its environment."""
    seen = env["tmp"] / "after_push.txt"
    p, repo, origin, other = _bump_setup(env, monkeypatch, ["true"])
    probe = (f"{sys.executable} -c \"import sys; sys.path.insert(0, '{RUNTIME}'); from pathlib import Path; "
             f"from ttp import batch, locks, release; from ttp.project import Project; p = Project('{p.base}'); "
             f"print('in_flight', release.push_in_flight(p)); print('held', locks.held(p.state / 'locks')); "
             f"print('alive', batch.alive(Path('{p.state / 'pushes' / 'b1.json'}')))\"")
    p.set_config("delivery.after_push", [
        f"(env | grep '^TTP_' | sort; echo head $(git rev-parse HEAD); echo dirty $(git status --porcelain | wc -l);"
        f" echo cwd $(pwd); ls {p.state / 'locks'}; {probe}) > {seen}"])
    marker = _batch_marker(p, [_entry(repo, f"e{n}", {f"plugins/p/f{n}.txt": f"{n}\n"}) for n in (1, 2)])
    from ttp import locks
    run_lock = locks.try_take([p.state / "locks" / "push:run-b1.0.lock"], "push queue")
    proc = subprocess.Popen([sys.executable, "-m", "ttp", "push", "--batch", str(marker)], cwd=str(repo),
                            env={**os.environ, "PYTHONPATH": str(RUNTIME), "TTP_BATCH_LOCK_FD": str(run_lock.fileno()),
                                 "TTP_RUN_DIR": json.loads(marker.read_text())["check_report_dir"]}, stdin=subprocess.PIPE,
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, pass_fds=(run_lock.fileno(),))
    run_lock.close()        # the child holds it now
    out = proc.communicate("", timeout=120)[0]
    assert proc.returncode == 0, out
    m = json.loads(marker.read_text())
    sha = _git_out(origin, "rev-parse", "proj")
    assert m["pushed_sha"] == sha and m["after_push"]["status"] == "ok" and m["phase"] == "finished", m
    lines = seen.read_text().splitlines()
    for want in (f"TTP_PUSHED_SHA={sha}", "TTP_PUSHED_VERSION=0.1.1", "TTP_PUSH_TARGET=origin/proj",
                 "TTP_PUSH_TASKS=101,102", f"TTP_PUSH_BATCH={marker}", f"TTP_PROJECT={p.base}", f"head {sha}",
                 "dirty 0", f"cwd {p.worktrees / 'after_push-b1'}", "in_flight False", "alive True"):
        assert want in lines, (want, lines)
    assert "push:run-b1.0.lock" not in lines and any(x.startswith("held ['after_push:run-b1: ") for x in lines), lines
    assert not (p.worktrees / "after_push-b1").exists() and "after_push-b1" not in _git_out(repo, "worktree", "list")
    assert not list((p.state / "locks").glob("*run-b1*"))
    assert not (p.state / "after_push").exists(), "a batch runs its own after_push, never a second one"


def test_after_push_failure_and_timeout_are_recorded_without_changing_the_push(env, monkeypatch):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    p.set_config("delivery.after_push", ["echo deploying; exit 3"])
    rc, m = _run_batch(p, _batch_marker(p, [_entry(repo, "e1", {"f1.txt": "1\n"})]), monkeypatch)
    assert rc == 0 and m["outcome"] == "pushed" and m["phase"] == "finished", m
    assert (m["after_push"]["status"], m["after_push"]["exit"], m["after_push"]["tail"]) == ("failed", 3, "deploying")
    p.set_config("delivery.after_push", ["sleep 60 & wait"])
    p.set_config("delivery.after_push_timeout_s", 1)
    started = time.time()
    rc, m = _run_batch(p, _batch_marker(p, [_entry(repo, "e2", {"f2.txt": "2\n"})], bid="b2"), monkeypatch)
    assert rc == 0 and m["outcome"] == "pushed" and m["after_push"]["status"] == "timeout", m
    # The whole process group is killed: a `sleep` left behind would hold the output open for 10 s more.
    assert time.time() - started < 9
    assert _git_out(origin, "show", "proj:f2.txt") == "2" and not (p.worktrees / "after_push-b2").exists()


def test_a_batch_marker_with_an_outcome_resumes_only_its_after_push(env, monkeypatch):
    from ttp.project import write_json
    checks, deploys = env["tmp"] / "checks.log", env["tmp"] / "deploys.log"
    p, repo, origin, other = _push_setup(env, monkeypatch, [f"echo check >> {checks}"])
    p.set_config("delivery.after_push", [f"git rev-parse HEAD >> {deploys}"])
    marker = _batch_marker(p, [_entry(repo, "e1", {"f1.txt": "1\n"})])
    rc, m = _run_batch(p, marker, monkeypatch)
    assert rc == 0 and m["outcome"] == "pushed" and m["after_push"]["status"] == "ok", m
    tip = _git_out(origin, "rev-parse", "proj")
    # The process died in the hand-over: the marker has its outcome but still names the run lock.
    run_lock = p.state / "locks" / "push:run-b1.0.lock"
    run_lock.write_text("")
    write_json(marker, {**{k: v for k, v in m.items() if k not in ("after_push", "ended")},
                        "status": "running", "phase": "push", "lock": str(run_lock)})
    rc, m = _run_batch(p, marker, monkeypatch)
    assert rc == 0 and m["phase"] == "finished" and m["after_push"]["status"] == "ok", m
    assert checks.read_text().split() == ["check"], "a resumed batch neither checks nor pushes again"
    assert deploys.read_text().split() == [tip, tip] and _git_out(origin, "rev-parse", "proj") == tip
    assert not run_lock.exists()
    # Its after_push ended but the process died before marking the batch finished: no second deploy.
    write_json(marker, {**m, "status": "running", "phase": "after_push"})
    rc, m = _run_batch(p, marker, monkeypatch)
    assert rc == 0 and m["phase"] == "finished" and deploys.read_text().split() == [tip, tip], m


# push queue: a passing review hands its approved commits to the daemon (pushq.py) ------------------
_PQ_STUB = r'''
import fcntl, json, os, sys, time
marker, plan = sys.argv[1], json.load(open(sys.argv[2]))
sys.stdin.read()   # the go: stdin closes once the marker is complete
m = json.load(open(marker))


def write(**kw):
    m.update(kw)
    with open(marker + ".tmp", "w") as f:
        json.dump(m, f)
    os.replace(marker + ".tmp", marker)


def wait(name):
    end = time.time() + 30
    while name and not os.path.exists(name) and time.time() < end:
        time.sleep(0.02)


def drop(path):   # let go of the inherited run lock: a flock belongs to the open file
    st = os.stat(path)
    for fd in range(3, 256):
        try:
            s = os.fstat(fd)
        except OSError:
            continue
        if (s.st_dev, s.st_ino) == (st.st_dev, st.st_ino):
            os.close(fd)


with open(marker[:-5] + ".starts", "a") as f:
    f.write(m.get("phase", "?") + "\n")
if m.get("outcome") is None:
    wait(plan.get("release"))
    if plan.get("die") == "push":
        if plan.get("pushing"):    # died between its `git push` and its outcome
            write(pushing=plan["pushing"])
        sys.exit(3)
    rows = plan.get("rows") or {}
    write(outcome=plan.get("outcome", "pushed"), tip=plan.get("tip"), pushed_sha=plan.get("sha"),
          version=plan.get("version"), checks={"runs": 1, "seconds": 2.0}, rounds=1, message=plan.get("message"),
          **({"tip_check": plan["tip_check"]} if "tip_check" in plan else {}),
          **({"tip_passed": True} if plan.get("tip_passed") else {}),
          **({"fast_forward": plan["ff"]} if "ff" in plan else {}),
          **({"reach": plan["reach"]} if "reach" in plan else {}),
          results=[{"id": e["id"], "status": rows.get(e["branch"], plan.get("row", "pushed")),
                    "task": e["task"], "detail": plan.get("detail") or {}} for e in m["entries"]])
    if not plan.get("after"):
        write(phase="finished", status="finished", ended=time.time(),
              after_push={"status": "skipped", "reason": "delivery.after_push is not set"})
        sys.exit(0)
    lock = os.path.join(os.path.dirname(m["lock"]), "after_push:run-%s.0.lock" % m["id"])
    fd = os.open(lock, os.O_CREAT | os.O_RDWR)
    fcntl.flock(fd, fcntl.LOCK_EX)
    old = m["lock"]
    write(lock=lock, phase="after_push")
    drop(old)
    wait(plan.get("after_release"))
    if plan.get("die") == "after":
        sys.exit(3)
    after = plan["after"]
else:   # started again on a marker with an outcome: only the after_push step
    if plan.get("die_resume"):
        sys.exit(3)
    after = plan.get("resume_after", "ok")
write(after_push={"status": after, "exit": 0 if after == "ok" else 2, "started": time.time(), "ended": time.time(),
                  "cmd": "./deploy.sh", "tail": "deploy said " + after}, phase="finished", status="finished")
'''


def _pq(env, monkeypatch, plan=None, **delivery):
    """A project whose push queue is on and pushes to origin/proj (see _push_setup), a done code task
    with one commit on its branch, a review of it, and the batch process replaced by a stub that
    writes the outcome `plan` describes into its marker."""
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    from ttp import pushq
    p.set_config("delivery.push_queue", True)
    for k, v in delivery.items():
        p.set_config(f"delivery.{k}", v)
    code, path, branch = _code_task(p, "feature")
    _commit(path, "feature.txt", "feature\n")
    stub, plan_file = env["tmp"] / "batch_stub.py", env["tmp"] / "plan.json"
    stub.write_text(_PQ_STUB)
    plan_file.write_text(json.dumps(plan or {}))
    monkeypatch.setattr(pushq, "batch_argv", lambda marker: [sys.executable, str(stub), str(marker), str(plan_file)])
    review = p.db.add_task("review feature", "review the feature", kind="review", tier="standard",
                           origin="coordinator", depends_on=[code])
    return types.SimpleNamespace(p=p, repo=repo, origin=origin, other=other, code=code, path=path, branch=branch,
                                 head=_git_out(path, "rev-parse", "HEAD"), review=review, plan=plan_file)


def _pq_plan(s, **plan):
    s.plan.write_text(json.dumps(plan))


def _pq_hand_off(env, s, push=None, task=None, note=None, **more):
    """The review's run hands off done with `push` (default: its branch at its head). `note`: the
    run's note, as dispatch recorded it."""
    from ttp.daemon import Daemon
    from ttp.providers.base import RunUsage as Usage
    task = task or s.review
    s.p.db.update_task(task, status="running")
    run_dir = env["tmp"] / f"run-{task}-{time.monotonic_ns()}"
    run_dir.mkdir()
    result = {"status": "done", "summary": "looks good", **more}
    if push is not False:
        result["push"] = [{"branch": s.branch, "head": s.head}] if push is None else push
    (run_dir / "result.json").write_text(json.dumps(result))
    Daemon(s.p.base)._finish_worker({"task": task, "id": 7, "note": json.dumps(note or {})}, Usage(cost_usd=1.0),
                                     "ok", run_dir)
    return s.p.db.task(task)


def _pq_batch(s, wait=True):
    """Start a batch of what is approved, as the tick does once one is due, and let it end."""
    from ttp import pushq
    rows, why = pushq.due(s.p, time.time() + 10 ** 6)   # past any window, pause or hold
    assert rows, why
    bid = pushq.start(s.p, rows, rows[0]["target"])
    assert bid
    if wait:
        pushq._children[bid].wait(timeout=30)
    return bid


def _pq_tend(s):
    from ttp.daemon import Daemon
    Daemon(s.p.base).tend_pushes()


def _pq_events(p, after=0, task=None):
    return p.db.q("SELECT kind, status, text FROM events WHERE id>? AND (? IS NULL OR task=?) ORDER BY id",
                  (after, task, task))


def _pq_mark(p):
    return p.db.one("SELECT COALESCE(MAX(id), 0) n FROM events")["n"]


def test_a_passing_review_hands_its_approval_to_the_push_queue_without_waking_the_coordinator(env, monkeypatch):
    s = _pq(env, monkeypatch)
    mark = _pq_mark(s.p)
    t = _pq_hand_off(env, s, followups=[{"title": "later", "spec": "do it later"}])
    assert t["status"] == "pushing" and json.loads(t["result"])["push"] == [{"branch": s.branch, "head": s.head}]
    [row] = s.p.db.q("SELECT * FROM push_queue")
    assert (row["task"], row["run"], row["branch"], row["head"], row["target"], row["status"]) == (
        s.review, 7, s.branch, s.head, "origin/proj", "approved")
    assert _git_out(s.repo, "rev-parse", f"refs/ttp/push/{row['id']}") == s.head, "the approved commit is not pinned"
    evs = _pq_events(s.p, mark)
    assert [e["kind"] for e in evs if e["status"] == "queued"] == ["followup_proposed"], "only the follow-up is news"
    [q] = [e for e in evs if e["kind"] == "push_queued"]
    assert q["status"] == "handled" and s.head[:7] in q["text"] and "origin/proj" in q["text"]
    assert not [e for e in evs if e["kind"].startswith("task_")]
    assert s.p.db.one("SELECT COUNT(*) n FROM runs")["n"] == 0


@pytest.mark.parametrize("case", ["short hash", "unknown commit", "unreviewed commit", "protected target", "no target",
                                  "queue off"])
def test_an_invalid_push_approval_runs_the_review_again_once_then_fails_it(env, monkeypatch, case):
    s = _pq(env, monkeypatch)
    head = {"short hash": s.head[:12], "unknown commit": "0123456789abcdef" * 2 + "01234567"}.get(case, s.head)
    if case == "unreviewed commit":
        _commit(s.repo, "elsewhere.txt", "not reviewed\n")
        head = _git_out(s.repo, "rev-parse", "HEAD")
    if case == "protected target":
        s.p.set_config("delivery.push_branch", "origin/main")
    if case == "no target":
        s.p.set_config("delivery.push_branch", "")
    if case == "queue off":   # turned off while the review ran: it runs again and pushes itself
        s.p.set_config("delivery.push_queue", False)
    mark = _pq_mark(s.p)
    t = _pq_hand_off(env, s, push=[{"branch": s.branch, "head": head}])
    assert t["status"] == "queued" and not s.p.db.q("SELECT id FROM push_queue")
    assert json.loads(t["result"])["woke"].startswith("push approval invalid: ")
    assert t["not_before"] <= time.time(), "the review should run again at once"
    assert not [e for e in _pq_events(s.p, mark) if e["status"] == "queued"], "the retry woke the coordinator"
    t = _pq_hand_off(env, s, push=[{"branch": s.branch, "head": head}])
    assert t["status"] == "failed" and "push approval invalid again" in json.loads(t["result"])["summary"]
    assert [e["kind"] for e in _pq_events(s.p, mark) if e["status"] == "queued"] == ["task_failed"]
    assert not s.p.db.q("SELECT id FROM push_queue")


def _re_plan(s, label):
    """A re-plan of the failed review `s.review`, carrying the reviewed branch by `label`: the reviewed
    task's worktree still holds that branch, so it commits on its own branch from that head (a
    `continues:` one starts from the base, and its worker builds on the reviewed head)."""
    from ttp import worktree
    s.p.db.update_task(s.review, status="failed")
    fix = s.p.db.add_task("Re-plan (narrowed)", "narrow it", kind="code", origin="coordinator", labels=[label])
    path, branch = worktree.ensure(s.p, s.p.db.task(fix))
    assert branch != s.branch
    _git_out(path, "reset", "-q", "--hard", s.head)
    _commit(path, "narrow.txt", "narrowed\n")
    s.p.db.update_task(fix, branch=branch)
    return fix, path, branch, _git_out(path, "rev-parse", "HEAD")


def _finish_fix(env, p, fix):
    """The re-plan `fix` hands off done. A review it queues gets the checks the daemon starts on its head
    (Daemon._precheck), detached processes in this test's folder: they are waited for here, as a later
    test can reuse the folder's name once pytest removes it, and a check still running there writes
    into that test's project."""
    from ttp import cli
    from ttp.daemon import Daemon, PRECHECKS_DIR
    from ttp.providers.base import RunUsage as Usage
    p.db.update_task(fix, status="running")
    run_dir = env["tmp"] / f"run-fix-{time.monotonic_ns()}"
    run_dir.mkdir()
    (run_dir / "result.json").write_text(json.dumps({"status": "done", "summary": "narrowed"}))
    Daemon(p.base)._finish_worker({"task": fix}, Usage(cost_usd=1.0), "ok", run_dir)
    for out in sorted((p.state / PRECHECKS_DIR).glob(f"t{fix}-*")):
        assert _wait_precheck(out) == "0", (out / cli.CHECKS_OUT).read_text()
        assert _wait_for(lambda: not cli._checks_alive(cli._read_checks_pid(out))), "the checks wrote their code, never exited"
    return p.db.one("SELECT * FROM events WHERE task=? AND kind='task_done' ORDER BY id DESC", (fix,))


@pytest.mark.parametrize("link", ["pr_branch", "continues"])
def test_a_re_plan_head_gets_one_review_not_its_re_review_plus_a_daemon_review(env, monkeypatch, link,
                                                                              leaked_tmp_processes):
    s = _pq(env, monkeypatch)
    fix, _, _, head = _re_plan(s, f"pr_branch:{s.branch}" if link == "pr_branch" else f"continues:{s.review}")
    again = s.p.db.add_task("Re-review (narrowed)", f"Re-review branch {s.branch} after its re-plan.", kind="review",
                            origin="coordinator")
    done = _finish_fix(env, s.p, fix)
    assert [r["id"] for r in s.p.db.q("SELECT id FROM tasks WHERE kind='review' AND status!='failed'")] == [again]
    assert f"Review #{again} was already queued" in done["text"]
    # A review that already passed the head (it ran while the re-plan waited on its checks) covers it too.
    s.p.db.update_task(again, status="done", spec="Re-review the re-plan.")
    s.p.db.x("INSERT INTO push_queue(task,run,branch,head,target,status,created,updated) "
             "VALUES(?,1,'b',?,'origin/proj','pushed',0,0)", (again, head))
    done = _finish_fix(env, s.p, fix)
    assert not s.p.db.q("SELECT id FROM tasks WHERE kind='review' AND status NOT IN ('failed','done')")
    assert f"Review #{again} already accepted this head" in done["text"]
    # Without either, the daemon reviews it as before.
    s.p.db.x("DELETE FROM push_queue")
    _finish_fix(env, s.p, fix)
    assert [r["title"][:len(f"Review #{fix}")] for r in s.p.db.q(
        "SELECT title FROM tasks WHERE kind='review' AND status='queued'")] == [f"Review #{fix}"]
    assert not leaked_tmp_processes(env["tmp"], 0), "the review's checks outlived the test"


@pytest.mark.parametrize("status", ["running", "waiting"])
def test_a_re_review_that_already_started_does_not_cover_a_later_fix_head(env, monkeypatch, status,
                                                                          leaked_tmp_processes):
    """A re-review of the reviewed branch can start while its re-plan still commits: it approves only
    the head it read, so the re-plan's later commits get their own review instead of none."""
    s = _pq(env, monkeypatch)
    fix, path, _, head = _re_plan(s, f"pr_branch:{s.branch}")
    again = s.p.db.add_task("Re-review (narrowed)", f"Re-review branch {s.branch} after its re-plan.", kind="review",
                            origin="coordinator")
    s.p.db.update_task(again, status=status)
    # It approved the head it read; the re-plan then commits once more.
    s.p.db.x("INSERT INTO push_queue(task,run,branch,head,target,status,created,updated) "
             "VALUES(?,1,'b',?,'origin/proj','approved',0,0)", (again, head))
    _commit(path, "later.txt", "a later fix\n")
    _finish_fix(env, s.p, fix)
    assert [r["title"][:len(f"Review #{fix}")] for r in s.p.db.q(
        "SELECT title FROM tasks WHERE kind='review' AND status='queued'")] == [f"Review #{fix}"]
    # Its checks ended with the test: none is left to write into a later test that gets this folder's name.
    assert not leaked_tmp_processes(env["tmp"], 0), "the review's checks outlived the test"


@pytest.mark.parametrize("setting, push", [("push_allowed", None), ("push_queue", "pushed it")])
def test_a_push_list_in_a_project_that_does_not_push_is_ignored_and_logged(env, monkeypatch, setting, push):
    """No pushing at all, or a stray `push` field (not a list of approvals) while the queue is off,
    as in every project that never turned it on: the review is done as before."""
    s = _pq(env, monkeypatch, **{setting: False})
    t = _pq_hand_off(env, s, push=push)
    assert t["status"] == "done" and not s.p.db.q("SELECT id FROM push_queue")
    [done] = [e for e in _pq_events(s.p, task=s.review) if e["kind"] == "task_done"]
    assert done["status"] == "queued" and "push list was ignored" in done["text"]
    assert "push list was ignored" in (s.p.logs / "daemon.log").read_text()


def test_a_pushed_batch_reports_fast_forward_also_in_its_notice_and_warns_on_not_ff(env, monkeypatch):
    from ttp.daemon import Daemon
    s = _pq(env, monkeypatch)
    sha = "ab" * 20
    _pq_plan(s, outcome="pushed", sha=sha, tip="cd" * 20, version="0.3.1",
             ff=[f"ff main {sha}", "not ff release: origin/release at 1234567890 is not an ancestor"])
    _pq_hand_off(env, s)
    mark = _pq_mark(s.p)
    s.p.db.set_kv("last_coordinator_turn", time.time())
    d = Daemon(s.p.base)
    assert _run_until(d, s.p, lambda: s.p.db.task(s.review)["status"] == "done", timeout=60)
    res = json.loads(s.p.db.task(s.review)["result"])
    assert res["fast_forward"] == [f"ff main {sha}", "not ff release: origin/release at 1234567890 is not an ancestor"]
    assert f"ff main {sha}; warning: not ff release:" in res["summary"]
    evs = _pq_events(s.p, mark)
    [done] = [e for e in evs if e["kind"] == "task_done"]
    assert "warning: not ff release" in done["text"]
    [warn] = [e for e in evs if e["kind"] == "push_not_ff"]
    assert warn["status"] == "queued" and "not ff release" in warn["text"] and f"ff main {sha}" not in warn["text"]


def test_a_pushed_batch_puts_a_diverged_mirror_in_the_feed(env, monkeypatch):
    from ttp.daemon import Daemon
    s = _pq(env, monkeypatch)
    sha, theirs = "ab" * 20, "ef" * 20
    line = f"not mirrored mirror/dev: it is at {theirs}, not an ancestor of the pushed {sha}; left as it is"
    _pq_plan(s, outcome="pushed", sha=sha, tip="cd" * 20, version="0.3.1", ff=[line])
