def _due_waiting_task(p, probe, since_ago=600.0, **extra):
    now = time.time()
    tid = p.db.add_task("measure", "s", kind="work", tier="light", origin="user", not_before=now - 1)
    p.db.update_task(tid, result=json.dumps({"status": "waiting", "summary": "board busy", "waiting_for": "a board",
                                             "retry_after_s": 900, "retry_when": probe,
                                             "waiting_since": now - since_ago, **extra}))
    return tid


def _settle_probe(d, tid):
    d.probe_waiting()
    if tid in d._probes:
        d._probes[tid][0].wait(_load_scaled(60))
        d.probe_waiting()


def _ready(p, tid):
    return tid in [t["id"] for t in p.db.ready_tasks()]


def _ssh_255(p, up=False):
    """A stand-in `ssh` first on the probes' PATH (the harness bin): a host that does not answer
    (exit 255, ssh's own error), or with `up` one that answers: `true` passes, any other remote
    command fails (exit 1). No real host is contacted. Returns a probe that reaches box-a over it."""
    b = p.harness / "bin"
    b.mkdir(parents=True, exist_ok=True)
    act = ('[ "$*" = true ] && exit 0; exit 1' if up
           else 'echo "ssh: connect to host $host port 22: Connection timed out" >&2; exit 255')
    (b / "ssh").write_text("#!/bin/sh\n"
                           "while [ $# -gt 0 ]; do case $1 in -o) shift 2;; -*) shift;; *) break;; esac; done\n"
                           f"host=$1; shift\n{act}\n")
    (b / "ssh").chmod(0o755)
    return "ssh -o BatchMode=yes box-a test -e /tmp/marker"


def test_a_due_waiting_task_sleeps_on_while_its_probe_says_not_yet(env):
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    tid = _due_waiting_task(p, "exit 1")
    d.probe_waiting()
    assert not _ready(p, tid) and tid in d._probes, "with no verdict yet it must ask the probe before waking"
    d._probes[tid][0].wait(10)
    d.probe_waiting()          # reaps the probe: exit 1
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()          # due with a fresh "not yet": extended, not run
    task = p.db.task(tid)
    assert not _ready(p, tid) and task["not_before"] > time.time() + 800, task["not_before"] - time.time()
    assert "probe says not yet" in task["blocked_reason"]
    assert "woke" not in json.loads(task["result"])
    assert f"task {tid} retry_when probe still failing" in (p.logs / "daemon.log").read_text()


def test_a_waiting_task_wakes_when_its_probe_passes_and_says_so(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dmod
    from ttp.prompts import worker_task
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tid = _due_waiting_task(p, "true")
    p.db.update_task(tid, not_before=time.time() + 3600)
    _settle_probe(d, tid)
    assert _ready(p, tid)
    assert "Woken because: probe passed." in worker_task(p, p.db.task(tid), str(p.root), None)


def _checks_wait_task(p, tmp_path, on_pass=None, rc="0", tier="standard", on_pass_cmd=None):
    """A code task that handed off `waiting` on its own detached `ttp checks`, which ended with `rc`."""
    from ttp import push, worktree
    now = time.time()
    tid = p.db.add_task("fix the parser", "s", kind="code", tier=tier, origin="user")
    path, branch = worktree.ensure(p, p.db.task(tid))
    p.db.update_task(tid, branch=branch)
    (path / "fix.txt").write_text("fixed\n")
    git = ["git", "-C", str(path)]
    subprocess.run([*git, "add", "fix.txt"], check=True, capture_output=True)
    subprocess.run([*git, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "fix"], check=True,
                   capture_output=True)
    head = subprocess.run([*git, "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    run_dir = tmp_path / f"run-{tid}"
    run_dir.mkdir()
    p.db.x("INSERT INTO runs(task,role,provider,started,ended,status,dir) VALUES(?,?,?,?,?,?,?)",
           (tid, "worker", "fake", now - 120, now - 60, "ok", str(run_dir)))
    hand = {"status": "waiting", "summary": "checks running", "waiting_for": "my checks", "retry_after_s": 900,
            "retry_when": f"{push._own_ttp(p)} checks --result {shlex.quote(str(run_dir))}"}
    if on_pass is not None:
        hand["on_pass"] = on_pass
    if on_pass_cmd is not None:
        hand["on_pass_cmd"] = on_pass_cmd
    (run_dir / "result.json").write_text(json.dumps(hand))
    if rc is not None:
        (run_dir / "checks.rc").write_text(f"{rc}\n")
    (run_dir / "checks.out").write_text("collected 9 items\nFAILED tests/test_x.py::test_parses_empty\n"
                                        "ttp checks: 'pytest -q' failed\n")
    (run_dir / "checks.json").write_text(json.dumps({"head": head, "worktree": str(path), "passed": rc == "0",
                                                     "commands": ["pytest -q"], "skipped": [], "ts": now}))
    p.db.update_task(tid, status="queued", not_before=now + 3600,
                     result=json.dumps({**hand, "waiting_since": now - 60}))
    return tid, path


DONE_ON_PASS = {"status": "done", "summary": "parser fixed; checks pass", "artifacts": ["fix.txt"],
                "metrics": {"tests": "9 passed"}}


def test_passed_checks_record_the_on_pass_hand_off_without_a_model_run(env, monkeypatch, tmp_path):
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tid, _ = _checks_wait_task(p, tmp_path, DONE_ON_PASS)
    _settle_probe(d, tid)
    task = p.db.task(tid)
    res = json.loads(task["result"])
    assert task["status"] == "done", (task["status"], task["blocked_reason"], res)
    assert res["summary"] == "parser fixed; checks pass" and res["run_status"] == "model-free"
    assert res["metrics"] == {"tests": "9 passed"} and res["artifacts"] == ["fix.txt"]
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1, "a model run was started"
    # The normal finish: its review is queued, and the event says no model ran.
    assert p.db.q("SELECT id FROM tasks WHERE kind='review'"), "the review did not start as usual"
    ev = p.db.one("SELECT text FROM events WHERE kind='task_done' AND task=?", (tid,))
    assert "run model-free" in ev["text"] and "$0.00" in ev["text"]
    assert "recorded its on_pass (done) model-free" in (p.logs / "daemon.log").read_text()
    for _ in range(3):
        d.tick()
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1


def _on_pass_reviews(p):
    return [r["title"] for r in p.db.q("SELECT title FROM tasks WHERE kind='review' ORDER BY id")]


def _later_sweeps(p, d, tid):
    """The review sweeps a done task meets afterwards: its run and record aged past their waits."""
    old = time.time() - 7200
    p.db.x("UPDATE runs SET ended=? WHERE task=?", (old, tid))
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (old, tid))
    d._review_swept = d._unreviewed_swept = 0.0
    d.sweep_reviews()
    d.sweep_unreviewed(force=True)
    d.tick()


def test_a_code_task_done_through_on_pass_gets_exactly_one_review(env, monkeypatch, tmp_path):
    """A code task its passed checks record done model-free (on_pass) gets its review from the same
    step a worker's done hand-off does (_finish_worker -> _auto_review): one 'Review #<id>: <title>',
    and the later sweeps (in review, unreviewed) and ticks add none."""
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tid, _ = _checks_wait_task(p, tmp_path, DONE_ON_PASS)
    _settle_probe(d, tid)
    assert p.db.task(tid)["status"] == "done"
    assert _on_pass_reviews(p) == [f"Review #{tid}: fix the parser"]
    ev = p.db.one("SELECT text FROM events WHERE kind='task_done' AND task=?", (tid,))
    assert "queued by the daemon" in ev["text"]
    _later_sweeps(p, d, tid)
    assert _on_pass_reviews(p) == [f"Review #{tid}: fix the parser"]


def test_an_on_pass_done_code_task_with_a_review_already_open_gets_no_second_one(env, monkeypatch, tmp_path):
    """A review queued ahead for the task (by the coordinator) is its review: the on_pass finish and
    the later sweeps queue none beside it."""
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tid, _ = _checks_wait_task(p, tmp_path, DONE_ON_PASS)
    ahead = p.db.add_task(f"Review #{tid}: fix the parser", "spec", kind="review", origin="coordinator",
                          depends_on=[tid], labels=[f"auto_review:{tid}"])
    _settle_probe(d, tid)
    assert p.db.task(tid)["status"] == "done"
    assert [r["id"] for r in p.db.q("SELECT id FROM tasks WHERE kind='review'")] == [ahead]
    assert "was already queued" in p.db.one("SELECT text FROM events WHERE kind='task_done' AND task=?",
                                            (tid,))["text"]
    _later_sweeps(p, d, tid)
    assert [r["id"] for r in p.db.q("SELECT id FROM tasks WHERE kind='review'")] == [ahead]


def test_an_on_pass_done_code_task_the_direct_review_missed_gets_one_from_the_backstop(env, monkeypatch, tmp_path):
    """The task is done, never in 'review', so the in-review sweep does not see it; the unreviewed
    sweep (sweep_unreviewed) does: one review, and none more on its next passes."""
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    real = dmod.Daemon._auto_review
    monkeypatch.setattr(dmod.Daemon, "_auto_review", lambda self, *a, **k: None)   # e.g. the review cap
    tid, _ = _checks_wait_task(p, tmp_path, DONE_ON_PASS)
    _settle_probe(d, tid)
    assert p.db.task(tid)["status"] == "done" and _on_pass_reviews(p) == []
    monkeypatch.setattr(dmod.Daemon, "_auto_review", real)
    _later_sweeps(p, d, tid)
    assert _on_pass_reviews(p) == [f"Review #{tid}: fix the parser"]
    _later_sweeps(p, d, tid)
    assert _on_pass_reviews(p) == [f"Review #{tid}: fix the parser"]


@pytest.mark.parametrize("case", ["not_code", "no_review_step"])
def test_an_on_pass_done_task_gets_no_review_where_a_hand_off_gets_none(env, monkeypatch, tmp_path, case):
    """As after a worker's hand-off: a task that is not code, or a project whose delivery has no
    review step (no review_before_pr, no push branch), gets no review from on_pass or the sweeps."""
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    if case == "no_review_step":
        p.set_config("delivery.review_before_pr", False)
        p.set_config("delivery.push_branch", "")
    d = dmod.Daemon(p.base)
    tid, _ = _checks_wait_task(p, tmp_path, DONE_ON_PASS)
    if case == "not_code":
        p.db.x("UPDATE tasks SET kind='work' WHERE id=?", (tid,))
    _settle_probe(d, tid)
    task = p.db.task(tid)
    assert task["status"] == "done", (task["status"], task["result"])
    assert "recorded its on_pass (done) model-free" in (p.logs / "daemon.log").read_text()
    _later_sweeps(p, d, tid)
    assert _on_pass_reviews(p) == []


@pytest.mark.parametrize("exit_code, writes, status, summary", [
    (1, False, "queued", None),
    (0, False, "done", "parser fixed; checks pass"),
    (0, True, "done", "published"),
])
def test_passed_checks_with_an_on_pass_cmd_run_it_and_record_on_pass_only_after_it_succeeds(
        env, monkeypatch, tmp_path, exit_code, writes, status, summary):
    """Its on_pass_cmd (a publish step) takes precedence over on_pass: a passed checks wait never
    records on_pass without running it, and a failing command leaves the task not done."""
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    ran = tmp_path / "ran"
    cmd = f"echo publishing > {ran}; "
    if writes:
        cmd += """printf '{"status":"done","summary":"published"}' > "$TTP_RESULT"; """
    tid, _ = _checks_wait_task(p, tmp_path, DONE_ON_PASS, on_pass_cmd=cmd + f"exit {exit_code}")
    _settle_on_pass(d, tid)
    assert ran.read_text() == "publishing\n", "the on_pass_cmd did not run"
    task = p.db.task(tid)
    res = json.loads(task["result"])
    assert task["status"] == status, (task["status"], task["blocked_reason"], res)
    log_text = (p.logs / "daemon.log").read_text()
    assert "recorded its on_pass (done) model-free" not in log_text
    if status == "done":
        assert res["summary"] == summary and res["run_status"] == "model-free"
        assert "on_pass_cmd recorded done model-free" in log_text
    else:
        assert _ready(p, tid) and "exit 1" in res["woke"] and res.get("escalated_wake"), res
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1, "a model run was started"


WRITES_OWN = ("printf '{\"status\":\"done\",\"summary\":\"published\","
              "\"followups\":[{\"title\":\"own\",\"spec\":\"from the command\"}]}' > \"$TTP_RESULT\"")


@pytest.mark.parametrize("cmd", [None, "true", WRITES_OWN])
def test_a_waiting_hand_offs_top_level_followups_survive_its_on_pass(env, monkeypatch, tmp_path, cmd):
    """The waiting hand-off's own followups (an upstream note among them) are filed when its on_pass,
    or what its on_pass_cmd records, is applied: alongside the final hand-off's own, none twice."""
    from ttp import daemon as dmod, upstream
    p = make(env)
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    note = {"title": "upstream: waits lose their followups", "spec": "the daemon should keep them"}
    later = {"title": "tidy the parser", "spec": "later"}
    tid, _ = _checks_wait_task(p, tmp_path, {**DONE_ON_PASS, "followups": [later]}, on_pass_cmd=cmd)
    run_dir = tmp_path / f"run-{tid}"
    hand = {**json.loads((run_dir / "result.json").read_text()), "followups": [note, later]}
    (run_dir / "result.json").write_text(json.dumps(hand))
    p.db.update_task(tid, result=json.dumps({**hand, "waiting_since": time.time() - 60}))
    _settle_on_pass(d, tid)
    task = p.db.task(tid)
    res = json.loads(task["result"])
    assert task["status"] == "done", (task["status"], task["blocked_reason"], res)
    want = ["own", note["title"], later["title"]] if cmd == WRITES_OWN else [later["title"], note["title"]]
    assert [f["title"] for f in res["followups"]] == want, res["followups"]
    filed = [json.loads(x) for x in upstream.path().read_text().splitlines()] if upstream.path().exists() else []
    assert [n["title"] for n in filed if n["task"] == tid] == [note["title"]]


def test_a_hand_off_naming_on_pass_and_on_pass_cmd_is_warned_about():
    from ttp.daemon import on_pass_both_warning
    hand = {"status": "waiting", "on_pass": DONE_ON_PASS, "on_pass_cmd": "./publish.sh",
            "retry_when": "/x/ttp checks --result /runs/7"}
    assert "on_pass_cmd takes precedence" in on_pass_both_warning(hand)
    assert "on_pass is ignored" in on_pass_both_warning({**hand, "retry_when": "test -e /tmp/done"})
    assert on_pass_both_warning({k: v for k, v in hand.items() if k != "on_pass_cmd"}) == ""
    assert on_pass_both_warning({k: v for k, v in hand.items() if k != "on_pass"}) == ""


def _on_pass_cmd_task(p, tmp_path, cmd, probe="true"):
    """A task that handed off `waiting` on `probe` and named `cmd` to run once it passes."""
    now = time.time()
    tid = p.db.add_task("run the long job", "s", kind="work", tier="standard", origin="user")
    run_dir = tmp_path / f"run-{tid}"
    run_dir.mkdir()
    p.db.x("INSERT INTO runs(task,role,provider,started,ended,status,dir) VALUES(?,?,?,?,?,?,?)",
           (tid, "worker", "fake", now - 120, now - 60, "ok", str(run_dir)))
    hand = {"status": "waiting", "summary": "job running", "waiting_for": "the job", "retry_after_s": 900,
            "retry_when": probe, "on_pass_cmd": cmd}
    (run_dir / "result.json").write_text(json.dumps(hand))
    p.db.update_task(tid, status="queued", not_before=now + 3600,
                     result=json.dumps({**hand, "waiting_since": now - 60}))
    return tid, run_dir


def _settle_on_pass(d, tid):
    _settle_probe(d, tid)
    if tid in d._on_pass:
        d._on_pass[tid][0].wait(120)
        d.probe_waiting()


def test_an_on_pass_cmd_that_records_done_is_the_hand_off_without_a_model_run(env, monkeypatch, tmp_path):
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    seen = tmp_path / "seen"
    tid, run_dir = _on_pass_cmd_task(p, tmp_path, f"echo \"$PWD $TTP_TASK\" > {seen}; echo verifying; "
                                     "printf '{\"status\":\"done\",\"summary\":\"job verified\","
                                     "\"metrics\":{\"rows\":\"9\"}}' > \"$TTP_RESULT\"")
    _settle_on_pass(d, tid)
    task = p.db.task(tid)
    res = json.loads(task["result"])
    assert task["status"] == "done", (task["status"], task["blocked_reason"], res)
    assert res["summary"] == "job verified" and res["run_status"] == "model-free" and res["metrics"] == {"rows": "9"}
    assert seen.read_text().split() == [str(p.root), str(tid)]
    assert "verifying" in (run_dir / "on_pass" / "on_pass.log").read_text()
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1, "a model run was started"
    ev = p.db.one("SELECT text FROM events WHERE kind='task_done' AND task=?", (tid,))
    assert "run model-free" in ev["text"]
    assert "on_pass_cmd recorded done model-free" in (p.logs / "daemon.log").read_text()
    for _ in range(3):
        d.tick()
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1


def test_an_on_pass_cmd_keeps_the_task_asleep_while_it_runs_and_runs_once(env, monkeypatch, tmp_path):
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tid, _ = _on_pass_cmd_task(p, tmp_path, "sleep 30")
    _settle_probe(d, tid)
    try:
        proc = d._on_pass[tid][0]
        assert not _ready(p, tid) and "on_pass_cmd" in p.db.task(tid)["blocked_reason"]
        p.db.update_task(tid, not_before=time.time() - 1)   # its own timer runs out meanwhile
        _settle_probe(d, tid)
        assert d._on_pass[tid][0] is proc and p.db.task(tid)["status"] == "queued"
        assert "woke" not in json.loads(p.db.task(tid)["result"])
    finally:
        dmod._kill_group(d._on_pass[tid][0])


@pytest.mark.parametrize("stale_context", [False, True])
def test_an_on_pass_cmd_can_send_notes_with_only_note_context(env, monkeypatch, tmp_path, stale_context):
    from ttp import daemon as dmod
    from ttp.project import register
    p = make(env)
    (env["tmp"] / "second").mkdir()
    register("second", {"host": "testhost", "dir": str(env["tmp"] / "second")})
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    cmd = ("set -e; ttp note 'job checked'; "
           "ttp note --to second 'job finished'; ttp note --to second 'job finished'; "
           "test -z \"$TTP_RUN_DIR$TTP_RUN_ID\"; "
           "if ttp notify 'should refuse'; then exit 10; fi; "
           "if ttp checks; then exit 11; fi; "
           "printf '{\"status\":\"done\",\"summary\":\"checked and reported\"}' > \"$TTP_RESULT\"")
    tid, run_dir = _on_pass_cmd_task(p, tmp_path, cmd)
    # Even a daemon launched with stale worker variables must not grant a full run context.
    if stale_context:
        monkeypatch.setenv("TTP_RUN_DIR", str(tmp_path / "stale-run"))
        monkeypatch.setenv("TTP_RUN_ID", "999")
    _settle_on_pass(d, tid)
    task = p.db.task(tid)
    output = (run_dir / "on_pass" / "on_pass.log").read_text()
    assert task["status"] == "done", (task["result"], output)
    (note,) = _upstream_inbox(env)
    assert (note["project"], note["task"], note["to"], note["from"], note["spec"]) == (
        p.name, tid, "second", "worker", "job finished")
    assert "stored 12 characters" in output and "sha256" in output
    assert "job checked" in (run_dir / "progress.md").read_text()
    assert "ttp notify only works inside a tt-project run" in output
    assert "ttp checks only works inside a tt-project run" in output
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1


def test_an_on_pass_cmd_records_obligation_progress_and_receipts_with_note_context(env, monkeypatch, tmp_path):
    """`ttp obligation progress|receipt` in an on_pass_cmd go to the waiting run's file, filed for its task
    when it settles, however old that run; user-only obligation actions stay refused."""
    from ttp import daemon as dmod, obligations as ob
    p = make(env)
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    cmd = ("set -e; ttp obligation progress \"$OID\" 'job checked'; "
           "ttp obligation receipt \"$OID\" 'docs/report.md'; "
           "if ttp obligation add 'should refuse'; then exit 10; fi; "
           "printf '{\"status\":\"done\",\"summary\":\"delivered\"}' > \"$TTP_RESULT\"")
    tid, run_dir = _on_pass_cmd_task(p, tmp_path, cmd)
    p.db.x("UPDATE runs SET started=?, ended=? WHERE task=?",
           (time.time() - 30 * 86400, time.time() - 30 * 86400 + 60, tid))
    oid = ob.add(p, "the urgent report", [tid])
    monkeypatch.setenv("OID", oid)
    _settle_on_pass(d, tid)
    output = (run_dir / "on_pass" / "on_pass.log").read_text()
    assert p.db.task(tid)["status"] == "done", (p.db.task(tid)["result"], output)
    assert "not inside a run" in output and f"recorded for task #{tid}" in output
    o = ob.get(p.db, oid)
    assert o["receipt"] and o["receipt"]["evidence"] == "docs/report.md", o
    assert [e["text"] for e in o["owners"][str(tid)]["evidence"]][:1] == ["job checked"]


def _ack_wait(cli, *args):
    with pytest.raises(SystemExit) as e:
        cli.main(["ack-wait", *args])
    return e.value.code


def test_ack_wait_probe_passes_only_on_the_named_projects_reply_naming_the_hash(env, monkeypatch, capsys):
    from ttp import cli, upstream
    from ttp.project import register
    p = make(env)
    for name in ("second", "third"):
        (env["tmp"] / name).mkdir()
        register(name, {"host": "testhost", "dir": str(env["tmp"] / name)})
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    request = "please confirm the new probe works"
    assert upstream.send(p.name, 4, "second", request) == "sent"
    fp, sha = upstream.note_id("second", request), upstream.receipt(request).split()[-1]
    probe = ["probe", "--from", "second", "--hash", fp]
    assert _ack_wait(cli, *probe) == 1, "the request itself is no reply"
    upstream.send("third", 1, p.name, f"re {fp}: not ours")
    upstream.send("second", 1, "third", f"re {fp}: to another project")
    upstream.send("second", 1, p.name, "an unrelated note")
    assert _ack_wait(cli, *probe) == 1
    upstream.send("second", 9, p.name, f"Re {fp.upper()} and {sha}: works here")
    assert _ack_wait(cli, *probe) == 0 and _ack_wait(cli, "probe", "--from", "second", "--hash", sha) == 0
    assert _ack_wait(cli, "probe", "--from", "nowhere", "--hash", fp) == 2, "an unknown project never replies"
    assert _ack_wait(cli, "probe", "--from", p.name, "--hash", fp) == 2
    assert _ack_wait(cli, "probe", "--from", "second", "--hash", "xyz") == 2
    assert _ack_wait(cli, "probe", "--from", "second", "--hash", "abc1234") == 2, "too short to name one note"
    assert _ack_wait(cli, "settle", "--from", "second", "--hash", fp) == 2, "settle writes $TTP_RESULT only"
    assert "not set" in capsys.readouterr().err


def test_ack_wait_ends_a_waiting_task_model_free_once_the_reply_arrives(env, monkeypatch, tmp_path):
    from ttp import daemon as dmod, upstream
    from ttp.project import register
