    assert "the probe passes here" in res["summary"] and res["metrics"]["reply_note"]
    assert f"second replied to {fp}" in (run_dir / "progress.md").read_text()
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1


