_DENIED_INBOX = """import errno, json, os, sys
from ttp import cli, upstream
def denied(*args, **kwargs):
    raise PermissionError(errno.EACCES, "read-only inbox")
upstream.send_or_queue = denied
cli.main(["note", "--to", "second", os.environ.get("NOTE", "job finished")])
"""


def _callback_note_task(env, p, tmp_path, tail="", text="job finished"):
    """A task whose on_pass_cmd sends a note it can only queue (its inbox is read-only), then `tail`."""
    from ttp.project import register
    (env["tmp"] / "second").mkdir(exist_ok=True)
    register("second", {"host": "testhost", "dir": str(env["tmp"] / "second")})
    return _on_pass_cmd_task(p, tmp_path, f"NOTE={shlex.quote(text)} python3 -c " + shlex.quote(_DENIED_INBOX + tail))


_DONE = 'open(os.environ["TTP_RESULT"], "w").write(json.dumps({"status": "done", "summary": "reported"}))\n'


@pytest.mark.parametrize("outcome", ["done", "failed", "missing_result", "invalid_result", "timeout",
                                     "cancelled", "replanned"])
def test_an_on_pass_cmds_queued_notes_are_filed_whatever_it_ends_with(env, monkeypatch, tmp_path, outcome):
    from ttp import daemon as dmod, upstream
    p = make(env)
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tail = {"done": _DONE, "failed": "sys.exit(1)\n", "missing_result": "",
            "invalid_result": 'open(os.environ["TTP_RESULT"], "w").write("{not json")\n',
            "timeout": "import time; time.sleep(60)\n", "cancelled": _DONE, "replanned": _DONE}[outcome]
    tid, run_dir = _callback_note_task(env, p, tmp_path, tail)
    if outcome == "timeout":
        p.set_config("waiting.on_pass_timeout_s", 3)
        d.cfg = p.config()
    _settle_probe(d, tid)
    proc = d._on_pass[tid][0]
    if outcome == "timeout":
        for _ in range(200):   # the note is queued before the command hangs
            if (run_dir / upstream.QUEUED_FILE).exists():
                break
            time.sleep(0.05)
        d._on_pass[tid] = (proc, time.time() - 10, *d._on_pass[tid][2:])
    else:
        proc.wait(10)
    if outcome == "cancelled":
        p.db.update_task(tid, status="cancelled")
    if outcome == "replanned":
        p.db.update_task(tid, result=json.dumps({"status": "waiting", "summary": "re-planned"}))
    d.probe_waiting()
    assert proc.poll() is not None
    (note,) = _upstream_inbox(env)
    assert (note["project"], note["task"], note["to"], note["spec"]) == (p.name, tid, "second", "job finished")
    assert not (run_dir / upstream.QUEUED_FILE).exists()
    assert p.db.task(tid)["status"] == {"done": "done", "cancelled": "cancelled"}.get(outcome, "queued")
    d2 = dmod.Daemon(p.base)   # a restart files nothing twice
    d2.probe_waiting()
    assert len(_upstream_inbox(env)) == 1


def test_an_on_pass_cmds_notes_survive_a_daemon_restart(env, monkeypatch, tmp_path):
    """The daemon running the command stops before settling it; the task is then cancelled. A later
    daemon files the notes once the command cannot still be running, and a retry files leftovers first."""
    from ttp import daemon as dmod, upstream
    p = make(env)
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tid, run_dir = _callback_note_task(env, p, tmp_path, _DONE)
    _settle_probe(d, tid)
    d._on_pass[tid][0].wait(10)
    assert (run_dir / upstream.QUEUED_FILE).exists()
    del d   # it died: nothing settles that command
    d2 = dmod.Daemon(p.base)
    d2.probe_waiting()
    assert (run_dir / upstream.QUEUED_FILE).exists()   # it may still be running: not yet
    p.db.update_task(tid, status="cancelled")
    old = time.time() - dmod.ON_PASS_TIMEOUT_S - dmod.PROBE_TIMEOUT_S - 1
    os.utime(run_dir / dmod.ON_PASS_DIR / dmod.ON_PASS_LOG, (old, old))
    d2._on_pass_notes_due = 0
    d2.probe_waiting()
    (note,) = _upstream_inbox(env)
    assert (note["project"], note["task"], note["spec"]) == (p.name, tid, "job finished")

    # A retry of the same command (its probe passed again) files what its earlier try left first.
    (tmp_path / "retry").mkdir()
    tid2, run_dir2 = _callback_note_task(env, p, tmp_path / "retry", _DONE, "retry finished")
    upstream.queue(run_dir2, "second", "left by an earlier try")
    assert d2._start_on_pass(p.db.task(tid2), time.time()) is True
    assert [n["spec"] for n in _upstream_inbox(env) if n["task"] == tid2] == ["left by an earlier try"]
    d2._on_pass[tid2][0].wait(10)
    d2.probe_waiting()
    assert sorted(n["spec"] for n in _upstream_inbox(env) if n["task"] == tid2) == \
        ["left by an earlier try", "retry finished"]


_TO_RESULT = ' > "$TTP_RESULT"'


@pytest.mark.parametrize("cmd, why", [
    ("""printf '{"status":"done","summary":"s"}'""" + _TO_RESULT + "; echo boom; exit 3", "exit 3"),
    ("echo nothing written", "no result.json"),
    ("""printf '{"status":"waiting","summary":"s"}'""" + _TO_RESULT, "not done"),
    ("""printf '{"status":"done"}'""" + _TO_RESULT, "no summary"),
    ("""printf '{"status":"done","summary":"s","retry_when":"true"}'""" + _TO_RESULT, "cannot carry"),
    ("""printf 'not json'""" + _TO_RESULT, "no result.json"),
    ("sleep 30", "timed out")])
def test_an_on_pass_cmd_that_does_not_record_done_wakes_the_task(env, monkeypatch, tmp_path, cmd, why):
    p = make(env)
    from ttp import daemon as dmod
    from ttp.prompts import worker_task
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    d.cfg["waiting"]["on_pass_timeout_s"] = 0.5
    tid, _ = _on_pass_cmd_task(p, tmp_path, cmd)
    _settle_probe(d, tid)
    if why == "timed out":
        time.sleep(0.6)
    else:
        d._on_pass[tid][0].wait(10)
    d.probe_waiting()
    task = p.db.task(tid)
    res = json.loads(task["result"])
    assert _ready(p, tid) and task["status"] == "queued" and task["attempts"] == 0, (task["status"], res)
    assert "its on_pass_cmd did not record done" in res["woke"] and why in res["woke"], res["woke"]
    if "boom" in cmd:
        assert "boom" in worker_task(p, task, str(p.root), None)
    from ttp import budget as bud
    failed = why in ("exit 3", "timed out")
    assert bool(res.get("escalated_wake")) == failed and res.get("wake_tier") == ("standard" if failed else None), res
    assert bud.wake_tier(task["tier"], res) == ("standard" if failed else "light")
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1


@pytest.mark.parametrize("tier, wake", [("deep", "deep"), ("light", "light"), ("bogus", "standard")])
def test_a_failed_on_pass_cmd_wakes_the_task_at_its_own_tier(env, monkeypatch, tmp_path, tier, wake):
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tid, _ = _on_pass_cmd_task(p, tmp_path, "echo tests failed; exit 1")
    p.db.x("UPDATE tasks SET tier=? WHERE id=?", (tier, tid))
    _settle_on_pass(d, tid)
    task = p.db.task(tid)
    res = json.loads(task["result"])
    assert _ready(p, tid) and task["status"] == "queued", (task["status"], res)
    assert "exit 1" in res["woke"] and "tests failed" in res["woke"], res["woke"]
    assert res["wake_tier"] == wake and res["escalated_wake"] is True, res


def _ended_jobs(tmp_path, **codes):
    """Detached jobs that ended with these exit codes (name=code), and the `ttp detach --check` on them."""
    jobs = tmp_path / "jobs"
    jobs.mkdir(exist_ok=True)
    for name, code in codes.items():
        (jobs / f"{name}.rc").write_text(f"{code}\n")
    return "ttp detach --check " + " ".join(str(jobs / f"{n}.rc") for n in codes)


def test_detach_check_tells_a_job_that_finished_ok_from_one_that_failed_or_still_runs(env, tmp_path):
    """0 only once every job wrote exit 0; 4 (detach.FAILED_RC) once all ended but one failed; 1 while
    any runs, whatever the others ended with. Each ended job says `job finished rc=N`."""
    from ttp import detach
    p = _device_project(env, device=False)
    ok = _ttp_run(p, *_ended_jobs(tmp_path, a=0, b=0).split()[1:])
    assert ok.returncode == 0 and "a: job finished rc=0" in ok.stdout and "b: job finished rc=0" in ok.stdout
    bad = _ttp_run(p, *_ended_jobs(tmp_path, a=0, c=3).split()[1:])
    assert bad.returncode == detach.FAILED_RC == 4 and "c: job finished rc=3" in bad.stdout, bad.stdout
    run_dir = p.runs / "9"
    run_dir.mkdir(parents=True)
    started = run_dir / "started"
    r = _ttp_run(p, "detach", "long", "--", "sh", "-c", f"touch {started}; sleep 60",
                 env={"TTP_RUN_DIR": str(run_dir)})
    assert r.returncode == 0 and _wait_for_path(started), r.stderr
    try:
        mixed = _ttp_run(p, *_ended_jobs(tmp_path, c=3).split()[1:], str(run_dir / "long.rc"))
        assert mixed.returncode == 1 and "long: running" in mixed.stdout, mixed.stdout
    finally:
        os.killpg(json.loads((run_dir / "detached.json").read_text())[0]["pid"], signal.SIGKILL)
    assert detach.failed_check("ttp detach --check /r/a.rc", 4) and not detach.failed_check("exit 4", 4)
    assert not detach.failed_check("ttp detach --check /r/a.rc", 3)


def test_a_failed_detached_job_wakes_its_task_at_once_with_its_rc_never_as_a_passed_probe(env, monkeypatch, tmp_path):
    """The reported failure: `ttp detach --check` exited 0 for a job that failed, so the wait read as
    passed and the log said 'probe passed'. Now the task wakes at once, at its own tier, with each
    job's `job finished rc=N`."""
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    probe = _ended_jobs(tmp_path, build=0, bench=3)
    tid = _due_waiting_task(p, probe)
    p.db.update_task(tid, not_before=time.time() + 3600)
    _settle_probe(d, tid)
    task = p.db.task(tid)
    res = json.loads(task["result"])
    assert _ready(p, tid) and task["status"] == "queued", (task["status"], task["blocked_reason"])
    assert res["woke"].startswith("detached job failed") and "bench: job finished rc=3" in res["woke"], res["woke"]
    assert res["escalated_wake"] is True and res["wake_tier"] == task["tier"], res
    log = (p.logs / "daemon.log").read_text()
    assert f"task {tid} retry_when detached job failed" in log and "job finished rc=3" in log
    assert f"task {tid} retry_when probe passed" not in log and "probe broken" not in log
    assert not p.db.q("SELECT id FROM events WHERE task=? AND kind='probe_never_passes'", (tid,))


def test_a_failed_detached_job_pages_a_machine_change_s_undo_at_once(env):
    """A ledger entry `--until-probe "ttp detach --check <rc>"` is overdue once the job ended, even when
    it failed (exit 4), not only after PROBE_END_S; its overdue reason says the job failed."""
    from ttp import ends
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    p = make(env)
    mm.add("box-a", tags="device")
    jobs = p.root / "jobs"
    jobs.mkdir()
    (jobs / "bench.rc").write_text("3\n")
    now = time.time()
    c = ml.add_change("box-a", "paused the queue for the bench", "resume it", p.name,
                      until_probe=f"ttp detach --check {jobs / 'bench.rc'}", now=now)
    probes = ml.Probes(p, log=lambda s: None)
    at = now + ml.PROBE_GRACE_S
    for n in range(ml.PROBE_PASSES):
        probes._probed.clear()
        probes.tick(at + n * ends.PROBE_EVERY_S)
        assert probes._procs[c["id"]][0].wait(timeout=30) == 4
        probes.tick(at + n * ends.PROBE_EVERY_S + 1)
    [got] = ml.changes()
    assert got["probe_passed"] and got["probe_job_failed"] == "job rc=3", got
    assert ml.overdue(got, at + ends.PROBE_EVERY_S).startswith("the detached job its until-probe waits on ended but failed")


def test_a_failed_detached_job_lets_the_on_pass_cmd_decide_model_free(env, monkeypatch, tmp_path):
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    probe = _ended_jobs(tmp_path, bench=2)
    tid, _ = _on_pass_cmd_task(p, tmp_path, """printf '{"status":"done","summary":"rc 2 is expected"}'""" + _TO_RESULT,
                               probe=probe)
    _settle_on_pass(d, tid)
    task = p.db.task(tid)
    assert task["status"] == "done" and json.loads(task["result"])["run_status"] == "model-free", task["status"]
    log = (p.logs / "daemon.log").read_text()
    assert f"task {tid} retry_when detached job failed; running its on_pass_cmd model-free" in log
    assert "probe passed" not in log
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1, "a model run was started"
    # One that does not record done (even with exit 0) wakes the task at its own tier.
    tid2, _ = _on_pass_cmd_task(p, tmp_path, "echo checked", probe=probe)
    _settle_on_pass(d, tid2)
    res = json.loads(p.db.task(tid2)["result"])
    assert _ready(p, tid2) and res["woke"].startswith("detached job failed; its on_pass_cmd did not record done")
    assert res["escalated_wake"] is True and res["wake_tier"] == "standard", res


_OWNER_HOME_CHECK = ("python3 -c \"import os, pwd, sys; "
                     "sys.exit(os.path.expanduser('~') != pwd.getpwuid(os.getuid()).pw_dir)\" && "
                     """printf '{"status":"done","summary":"home checked"}'""" + _TO_RESULT)


@pytest.mark.parametrize("daemon_home", ["unset", "worker dir", "missing", "another user's"])
def test_an_on_pass_cmd_runs_with_the_owners_home_whatever_the_daemon_inherited(env, monkeypatch, tmp_path,
                                                                                 daemon_home):
    """A daemon started without HOME, from a worker's folder, a sandbox or another user's shell must not
    make `~` in a hook mean somewhere else: the hook sees the owner's home and runs from the project root."""
    import pwd
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    if os.getuid() == 0 and daemon_home == "another user's":
        pytest.skip("root owns every directory")
    worker = p.base / "worktrees" / "t1"
    worker.mkdir(parents=True)
    home = {"worker dir": str(worker), "missing": str(tmp_path / "gone"), "another user's": "/"}.get(daemon_home)
    if home is None:
        monkeypatch.delenv("HOME", raising=False)
    else:
        monkeypatch.setenv("HOME", home)
    seen = tmp_path / "seen"
    tid, _ = _on_pass_cmd_task(p, tmp_path, f'echo "$PWD $USER" > {seen}; ' + _OWNER_HOME_CHECK)
    _settle_on_pass(d, tid)
    task = p.db.task(tid)
    assert task["status"] == "done", (task["status"], json.loads(task["result"]).get("woke"))
    assert seen.read_text().split() == [str(p.root), pwd.getpwuid(os.getuid()).pw_name]


def test_an_on_pass_cmd_keeps_a_real_inherited_home_and_sees_the_runs_output(env, monkeypatch, tmp_path):
    """A real home (the user's own directory, outside the project's folder) is kept, so `~` in the hook
    finds a file the job wrote there; and the hook runs only once the run that named it has ended."""
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    home = tmp_path / "userhome"
    home.mkdir()
    monkeypatch.setenv("HOME", str(home))
    d = dmod.Daemon(p.base)
    out = home / ".local" / "state" / "canary" / "out.bin"
    check = ("python3 -c \"import os, sys; sys.exit(not os.path.exists(os.path.expanduser("
             "'~/.local/state/canary/out.bin')))\" && "
             """printf '{"status":"done","summary":"output found"}'""" + _TO_RESULT)
    tid, _ = _on_pass_cmd_task(p, tmp_path, check)
    run = p.db.one("SELECT id FROM runs WHERE task=?", (tid,))["id"]
    p.db.x("UPDATE runs SET status='running', ended=NULL WHERE id=?", (run,))
    _settle_probe(d, tid)
    assert tid not in d._on_pass and "woke" not in json.loads(p.db.task(tid)["result"])
    assert f"on_pass_cmd waits for run {run} to finish" in (p.logs / "daemon.log").read_text()
    out.parent.mkdir(parents=True)
    out.write_bytes(b"frames")
    p.db.x("UPDATE runs SET status='ok', ended=? WHERE id=?", (time.time(), run))
    _settle_on_pass(d, tid)
    task = p.db.task(tid)
    assert task["status"] == "done", (task["status"], json.loads(task["result"]).get("woke"))
    assert json.loads(task["result"])["summary"] == "output found"


def test_a_failed_on_pass_cmd_logs_its_exit_output_home_and_cwd(env, monkeypatch, tmp_path):
    p = make(env)
