def test_always_passes_names_only_probes_that_test_nothing():
    from ttp.waitheal import always_passes
    assert all(always_passes(x) for x in ("true", ":", "exit 0", "exit", "/bin/true", "true && true", "true; :"))
    assert not any(always_passes(x) for x in ("exit 1", "test -e x", "", "  ", None, "true || false",
                                               "true && test -e x", "false"))


def test_set_when_refuses_an_always_passing_probe_while_the_hand_offs_on_pass_cmd_stays(env, monkeypatch, tmp_path,
                                                                                         capsys):
    """An overwrite of a waiting hand-off's probe with `true` (a watcher reading a stale record) would run
    its on_pass_cmd at once, before the wait ended: refused loudly, the probe stays; one event per wait."""
    p = make(env)
    from ttp import cli, daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    flag = tmp_path / "ran"
    tid, _ = _on_pass_cmd_task(p, tmp_path, f"touch {flag}", probe="exit 1")
    for _ in range(2):
        with pytest.raises(SystemExit):
            cli.main(["task", "demo", "set-when", str(tid), "true"])
        assert "rejected" in capsys.readouterr().err
    res = json.loads(p.db.task(tid)["result"])
    assert res["retry_when"] == "exit 1" and "retry_when_orig" not in res, res
    assert len(p.db.q("SELECT id FROM events WHERE kind='set_when_refused' AND fingerprint LIKE ?",
                      (f"set_when_refused:{tid}:%",))) == 1
    _settle_on_pass(d, tid)
    assert p.db.task(tid)["status"] == "queued" and not flag.exists() and not _ready(p, tid)
    # Still allowed: an explicit on_pass_cmd (run it now), or clearing it (wake the task for a run).
    cli.main(["task", "demo", "set-when", str(tid), "true", "--on-pass-cmd", ""])
    res = json.loads(p.db.task(tid)["result"])
    assert res["retry_when"] == "true" and res.get("on_pass_cmd") is None, res


def test_an_on_pass_cmd_waits_for_its_probe_and_runs_exactly_once(env, monkeypatch, tmp_path):
    """The on_pass_cmd runs only after the hand-off's own probe passes, and once: later ticks never rerun it."""
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    marker, count = tmp_path / "job.rc", tmp_path / "count"
    cmd = f"echo x >> {count}; printf '{{\"status\":\"done\",\"summary\":\"verified\"}}' > \"$TTP_RESULT\""
    tid, _ = _on_pass_cmd_task(p, tmp_path, cmd, probe=f"test -e {marker}")
    for _ in range(2):
        _settle_on_pass(d, tid)
        assert p.db.task(tid)["status"] == "queued" and not count.exists() and not _ready(p, tid)
    marker.write_text("0\n")
    for _ in range(3):   # a probe started before the marker existed may still answer "not yet" once
        _settle_on_pass(d, tid)
        if p.db.task(tid)["status"] == "done":
            break
    assert p.db.task(tid)["status"] == "done", p.db.task(tid)["result"]
    for _ in range(3):
        d.tick()
        _settle_on_pass(d, tid)
    assert count.read_text() == "x\n" and p.db.task(tid)["status"] == "done"


def test_a_hand_off_retry_when_that_is_no_shell_command_is_refused_not_stored(env, monkeypatch, tmp_path):
    """A hand-off's JSON `"retry_when": true` is never stored (nor read as passed): the task keeps no probe,
    says so in an event, and its on_pass_cmd never runs; a string probe is stored exactly as written."""
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    flag = tmp_path / "ran"
    probe = f"ttp detach --check {tmp_path}/drv  &&  test -e '{tmp_path}/a b'"
    for retry_when in (True, probe):
        monkeypatch.setenv("TTP_FAKE_RESULT", json.dumps({
            "status": "waiting", "summary": "job running", "waiting_for": "the job", "retry_after_s": 900,
            "retry_when": retry_when, "on_pass_cmd": f"touch {flag}"}))
        tid = p.db.add_task(f"waits on {retry_when!r}", "s", kind="work", tier="light", origin="user")
        assert _run_until(d, p, lambda: p.db.one("SELECT id FROM events WHERE kind='task_waiting' AND task=?",
                                                 (tid,)))
        res = json.loads(p.db.task(tid)["result"])
        refused = p.db.q("SELECT text FROM events WHERE kind='handoff_probe_refused' AND task=?", (tid,))
        if retry_when is True:
            assert "retry_when" not in res and res["retry_when_refused"] == "true", res
            assert len(refused) == 1 and "on_pass_cmd" in refused[0]["text"], refused
            for _ in range(3):
                d.tick()
                _settle_on_pass(d, tid)
            assert p.db.task(tid)["status"] == "queued" and not flag.exists()
        else:
            assert res["retry_when"] == probe and "retry_when_refused" not in res and not refused, res


@pytest.mark.parametrize("change", ["probe", "cmd", "both", "unrelated"])
def test_an_on_pass_cmd_runs_model_free_after_set_when_rewrites_the_hand_off(env, monkeypatch, tmp_path, capsys,
                                                                            change):
    """`ttp task set-when` re-points the probe and/or sets the on_pass_cmd of a waiting task; the run's
    result.json keeps what it wrote, and the daemon still takes it as the hand-off the task waits on."""
    p = make(env)
    from ttp import cli, daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    flag = tmp_path / "ran"
    cmd = f"touch {flag}; printf '{{\"status\":\"done\",\"summary\":\"verified\"}}' > \"$TTP_RESULT\""
    tid, run_dir = _on_pass_cmd_task(p, tmp_path, cmd, probe="exit 1" if change != "cmd" else "true")
    if change in ("cmd", "both", "unrelated"):   # the run named no on_pass_cmd
        hand = json.loads((run_dir / "result.json").read_text())
        hand.pop("on_pass_cmd")
        (run_dir / "result.json").write_text(json.dumps(hand))
        res = json.loads(p.db.task(tid)["result"])
        res.pop("on_pass_cmd")
        p.db.update_task(tid, result=json.dumps(res))
    # a new probe alone that passes at once would run the kept on_pass_cmd now: it must test something
    new = "test -d ." if change == "probe" else "true"
    args = {"probe": [new], "cmd": ["--on-pass-cmd", cmd]}.get(change, [new, "--on-pass-cmd", cmd])
    cli.main(["task", "demo", "set-when", str(tid), *args])
    out = capsys.readouterr().out
    res = json.loads(p.db.task(tid)["result"])
    assert res["retry_when"] == new and res["on_pass_cmd"] == cmd, res
    assert (f"retry_when set: {new}" in out) == (change != "cmd") and ("on_pass_cmd set" in out) == (change != "probe")
    if change == "unrelated":   # a result.json naming some other probe is still not the hand-off the task waits on
        hand = json.loads((run_dir / "result.json").read_text())
        (run_dir / "result.json").write_text(json.dumps({**hand, "retry_when": "test -e /tmp/other"}))
    _settle_on_pass(d, tid)
    task = p.db.task(tid)
    res = json.loads(task["result"])
    if change == "unrelated":
        assert _ready(p, tid) and not flag.exists()
        assert "its on_pass_cmd was not run: the task's last run's result.json is not the hand-off" in res["woke"]
    else:
        assert task["status"] == "done" and flag.exists(), (task["status"], task["blocked_reason"], res)
        assert res["summary"] == "verified" and res["run_status"] == "model-free"
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1


def test_set_when_keeps_the_runs_own_probe_across_rewrites_and_clears_an_on_pass_cmd(env, capsys):
    p = make(env)
    from ttp import cli
    tid = _due_waiting_task(p, "exit 1", on_pass_cmd="true")
    cli.main(["task", "demo", "set-when", str(tid), "exit 2"])
    cli.main(["task", "demo", "set-when", str(tid), "exit 3", "--on-pass-cmd", ""])
    assert "on_pass_cmd cleared" in capsys.readouterr().out
    res = json.loads(p.db.task(tid)["result"])
    assert (res["retry_when"], res["retry_when_orig"], res["on_pass_cmd_orig"]) == ("exit 3", "exit 1", "true")
    assert "on_pass_cmd" not in res


def test_set_when_on_pass_cmd_needs_a_waiting_task(env, capsys):
    p = make(env)
    from ttp import cli
    tid = p.db.add_task("t", "s", kind="work", tier="light", origin="user")
    with pytest.raises(SystemExit):
        cli.main(["task", "demo", "set-when", str(tid), "--on-pass-cmd", "true"])
    assert "only a waiting task has an on_pass_cmd" in capsys.readouterr().err
    with pytest.raises(SystemExit):
        cli.main(["task", "demo", "requeue", str(tid), "--on-pass-cmd", "true"])
    assert "--on-pass-cmd goes with set-when" in capsys.readouterr().err
    assert p.db.task(tid)["result"] is None


def test_on_pass_must_be_a_final_hand_off():
    from ttp.daemon import on_pass_problem
    assert on_pass_problem(DONE_ON_PASS) == ""
    assert on_pass_problem({"status": "needs_review", "summary": "s", "followups": []}) == ""
    assert "must be done or needs_review" in on_pass_problem({"status": "waiting", "summary": "s"})
    assert "must be done or needs_review" in on_pass_problem({"status": "failed", "summary": "s"})
    assert "no summary" in on_pass_problem({"status": "done"})
    assert "not an object" in on_pass_problem("done")
    assert "cannot carry next_step" in on_pass_problem({**DONE_ON_PASS, "next_step": "push"})
    assert "cannot carry on_pass" in on_pass_problem({**DONE_ON_PASS, "on_pass": DONE_ON_PASS})
    assert "metrics must be a dict" in on_pass_problem({**DONE_ON_PASS, "metrics": "9"})


@pytest.mark.parametrize("probe, why", [("exit 127", "probe broken: exit 127"),
                                        ("exit 2", "probe broken: exit 2")])
def test_a_broken_probe_wakes_the_task_at_its_timer(env, probe, why):
    p = make(env)
    from ttp import daemon as dmod
    from ttp.prompts import worker_task
    d = dmod.Daemon(p.base)
    tid = _due_waiting_task(p, probe)
    _settle_probe(d, tid)
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()
    assert _ready(p, tid)
    assert f"Woken because: {why}." in worker_task(p, p.db.task(tid), str(p.root), None)


@pytest.mark.parametrize("tail", ["&& exit 1", "&& exit 1 || exit 1"])
def test_a_probe_that_cds_into_a_removed_worktree_wakes_the_task_as_broken(env, tail):
    """`cd <gone worktree> && ...` exits 1 under bash (or with `|| exit 1`), which reads as "not yet"
    forever: it wakes the task now, as a broken probe, not at its timer or never."""
    p = make(env)
    from ttp import daemon as dmod
    from ttp.prompts import worker_task
    gone = p.worktrees / "t999"
    tid = _due_waiting_task(p, f"cd {gone} {tail}")
    p.db.update_task(tid, not_before=time.time() + 3600)
    d = dmod.Daemon(p.base)
    _settle_probe(d, tid)
    assert _ready(p, tid), "a probe into a removed worktree left the task asleep"
    assert "its cd target" in worker_task(p, p.db.task(tid), str(p.root), None)
    # A directory a job may still make (not a task worktree) stays "not yet".
    tid2 = _due_waiting_task(p, f"cd {p.root / 'out' / 'later'} 2>/dev/null || exit 1")
    p.db.update_task(tid2, not_before=time.time() + 3600)
    _settle_probe(d, tid2)
    assert not _ready(p, tid2)


def test_an_unreachable_host_probe_keeps_the_task_asleep_past_the_hold_cap(env):
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    tid = _due_waiting_task(p, _ssh_255(p))
    _settle_probe(d, tid)
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()          # due with a fresh 255: extended like "not yet", no worker run
    task = p.db.task(tid)
    assert not _ready(p, tid) and task["not_before"] > time.time() + 800
    assert "probe says host unreachable" in task["blocked_reason"]
    assert "woke" not in json.loads(task["result"])
    assert f"task {tid} retry_when probe still failing (host unreachable)" in (p.logs / "daemon.log").read_text()
    p.db.update_task(tid, result=json.dumps({**json.loads(task["result"]),
                                             "waiting_since": time.time() - 6 * 3600 - 1}),
                     not_before=time.time() - 1)
    _settle_probe(d, tid)
    assert not _ready(p, tid) and "woke" not in json.loads(p.db.task(tid)["result"])
    assert len(p.db.q("SELECT id FROM events WHERE task=? AND kind='wait_stale'", (tid,))) == 1


def test_a_timed_out_probe_is_broken(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_TIMEOUT_S", 0.2)
    d = dmod.Daemon(p.base)
    tid = _due_waiting_task(p, "sleep 30")
    d.probe_waiting()
    time.sleep(0.4)
    d.probe_waiting()          # kills it: timeout
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()
    assert _ready(p, tid) and json.loads(p.db.task(tid)["result"])["woke"] == "probe broken: timeout"


def test_a_probe_that_cannot_start_is_broken(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    tid = _due_waiting_task(p, "exit 1")

    def refuse(*a, **k):
        raise OSError("no shell")
    monkeypatch.setattr(dmod.subprocess, "Popen", refuse)
    d.probe_waiting()          # asks the probe first; it cannot start
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()
    assert _ready(p, tid) and json.loads(p.db.task(tid)["result"])["woke"] == "probe broken: could not start"


def test_past_the_hold_cap_a_passing_probe_still_wakes_the_task(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dmod
    from ttp.prompts import worker_task
    flag = env["tmp"] / "done.flag"
    d = dmod.Daemon(p.base)
    tid = _due_waiting_task(p, f"test -f {flag}", since_ago=6 * 3600 + 1)
    _settle_probe(d, tid)
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()
    assert not _ready(p, tid)
    flag.write_text("")
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    _settle_probe(d, tid)
    assert _ready(p, tid)
    assert "Woken because: probe passed." in worker_task(p, p.db.task(tid), str(p.root), None)


def test_waiting_tasks_with_the_same_probe_share_its_runs(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dmod
    from ttp.prompts import worker_task
    flag = env["tmp"] / "board.flag"
    calls = []
    real = dmod.subprocess.Popen

    def popen(cmd, *a, **k):
        calls.append(cmd)
        return real(cmd, *a, **k)
    monkeypatch.setattr(dmod.subprocess, "Popen", popen)
    d = dmod.Daemon(p.base)
    same = [_due_waiting_task(p, f"test -f {flag}") for _ in range(3)]
    other = _due_waiting_task(p, "exit 1")
    for tid in (*same, other):
        p.db.update_task(tid, not_before=time.time() + 3600)
    d.probe_waiting()
    # Probes run as shell strings; argv lists are other children (macOS: sysctl for the boot time).
    probes = [c for c in calls if isinstance(c, str)]
    assert sorted(probes) == sorted([f"test -f {flag}", "exit 1"]), "one run per distinct command"
    for tid in (*same, other):
        d._probes[tid][0].wait(10)
    d.probe_waiting()
    assert not any(_ready(p, t) for t in (*same, other))
    assert all(d._probe_rc[t][0] == 1 for t in (*same, other))
    flag.write_text("")
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    calls.clear()
    d.probe_waiting()
    assert calls.count(f"test -f {flag}") == 1
    for tid in same:
        d._probes[tid][0].wait(10)
    d.probe_waiting()
    assert all(_ready(p, t) for t in same) and not _ready(p, other)
    assert "Woken because: probe passed." in worker_task(p, p.db.task(same[-1]), str(p.root), None)


def test_a_shared_probe_run_is_kept_when_one_task_re_points_its_probe(env):
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    a, b = _due_waiting_task(p, "sleep 5; exit 1"), _due_waiting_task(p, "sleep 5; exit 1")
    for tid in (a, b):
        p.db.update_task(tid, not_before=time.time() + 3600)
    d.probe_waiting()
    run = d._probes[b]
    assert d._probes[a] is run
    d._drop_stale_probe(a, "exit 1")
    assert a not in d._probes and run[0].poll() is None, "b still needs its verdict"
    d._drop_stale_probe(b, "exit 1")
    assert run[0].poll() is not None, "no one shares it now: killed"


def test_a_waiting_task_without_a_probe_keeps_its_timer(env):
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    tid = _due_waiting_task(p, None)
    legacy = _due_waiting_task(p, "exit 1")   # a hand-off from before the hold
    p.db.update_task(legacy, result=json.dumps({"status": "waiting", "retry_when": "exit 1"}))
    d.probe_waiting()
    assert _ready(p, tid) and _ready(p, legacy) and not d._probes


