def _lost_to_reboot(p, d, tmp_path, tid, name="lost", notes=()):
    """A run of task tid that the host went down under, as the reaper finds it after the reboot."""
    p.db.update_task(tid, status="running")
    run_dir = tmp_path / name
    run_dir.mkdir()
    (run_dir / "output.jsonl").write_text("")
    if notes:
        (run_dir / "progress.md").write_text("".join(f"10:0{i} {n}\n" for i, n in enumerate(notes)))
    (run_dir / "lease").touch()
    os.utime(run_dir / "lease", (time.time() - 999, time.time() - 999))
    p.db.x("INSERT INTO runs(task,role,provider,started,status,dir,boot_id) VALUES(?,?,?,?,?,?,?)",
           (tid, "worker", "fake", time.time() - 1800, "running", str(run_dir), "an-earlier-boot"))
    d.reap_runs()
    return run_dir


def test_a_run_lost_to_a_reboot_spends_no_attempt_and_retries_at_once(env, tmp_path):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = p.db.add_task("build", "s", kind="work", tier="light", origin="user")
    p.db.update_task(tid, attempts=2)
    _lost_to_reboot(p, d, tmp_path, tid)
    t = p.db.task(tid)
    assert t["status"] == "queued" and t["attempts"] == 2, dict(t)
    assert not t["not_before"] or t["not_before"] <= time.time(), "a reboot loss was delayed like a failure"
    assert tid in [x["id"] for x in p.db.ready_tasks()]


def test_the_third_reboot_loss_blocks_the_task(env, tmp_path):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = p.db.add_task("flash the board", "s", kind="work", tier="light", origin="user")
    for i in range(3):
        _lost_to_reboot(p, d, tmp_path, tid, name=f"lost{i}")
        assert p.db.task(tid)["status"] == ("blocked" if i == 2 else "queued")
    t = p.db.task(tid)
    assert t["attempts"] == 0
    assert t["blocked_reason"] == "lost to a host reboot 3 times; it may be causing them"
    ev = p.db.q("SELECT severity, status FROM events WHERE kind='task_blocked' AND task=?", (tid,))
    assert ev and ev[-1]["severity"] == "high" and ev[-1]["status"] == "queued", ev


def _waiting_from_before_the_boot(p, tid, job=True, boot="an-earlier-boot", retry_when="exit 1"):
    """Task tid waits from before this boot; with job, on a detached job of its own that the reboot
    cut short (no .rc)."""
    if job:
        run_dir = p.runs / f"pre-boot-{tid}-{len(p.db.q('SELECT id FROM runs WHERE task=?', (tid,)))}"
        run_dir.mkdir(parents=True)
        (run_dir / "detached.json").write_text(json.dumps([{"name": "soak", "rc": str(run_dir / "soak.rc"),
                                                            "log": str(run_dir / "soak.log")}]))
        p.db.x("INSERT INTO runs(task,role,provider,started,ended,status,dir,boot_id) VALUES(?,?,?,?,?,?,?,?)",
               (tid, "worker", "fake", time.time() - 1800, time.time() - 900, "ok", str(run_dir), boot))
    p.db.update_task(tid, status="queued", not_before=time.time() + 3600, result=json.dumps(
        {**json.loads(p.db.task(tid)["result"] or "{}"), "status": "waiting", "summary": "job running",
         "retry_after_s": 3600, "retry_when": retry_when, "waiting_since": time.time() - 900}))


def test_three_boot_time_wakes_of_a_waiting_task_block_it(env):
    p = make(env)
    from ttp.daemon import Daemon
    tid = p.db.add_task("soak test", "s", kind="work", tier="light", origin="user")
    for i in range(3):
        _waiting_from_before_the_boot(p, tid)
        d = Daemon(p.base)
        d.boot_at = time.time() - 300
        d.wake_after_reboot()
        t = p.db.task(tid)
        assert t["status"] == ("blocked" if i == 2 else "queued"), (i, dict(t))
    assert t["blocked_reason"] == "lost to a host reboot 3 times; it may be causing them"
    assert "reboot_wakes" not in json.loads(t["result"]), "a block kept the old count"
    ev = p.db.q("SELECT severity, status FROM events WHERE kind='task_blocked' AND task=?", (tid,))
    assert ev and ev[-1]["severity"] == "high" and ev[-1]["status"] == "queued", ev


@pytest.mark.parametrize("probe, job, wakes", [
    ('test "$(date +%s)" -ge 1900000000', False, False),   # a timer
    (None, False, False),   # no probe: only its retry_after_s
    ("timeout 30 ssh box 'test -e /tmp/soak.done && kill -0 4242'", False, False),   # another host's state
    ("ttp detach --check --host box ~/.ttp-detach/r/soak", False, False),
    ("ttp ack-wait probe --from other --hash 0123abcd", False, False),   # another project's reply
    ("kill -0 4242", False, True),   # a process of the earlier boot
    ("test -e /tmp/soak.done", False, True),
    ("test -s {runs}/r1/soak.out", False, True),   # a file in a run folder
    ("ttp detach --check {runs}/r1/soak.rc", False, True),
    ("exit 1", True, True),   # its detached job from the earlier boot wrote no .rc
])
def test_a_host_reboot_wakes_only_waits_it_may_have_broken(env, probe, job, wakes):
    p = make(env)
    from ttp.daemon import Daemon
    tid = p.db.add_task("soak test", "s", kind="work", tier="light", origin="user")
    _waiting_from_before_the_boot(p, tid, job=job, retry_when=probe and probe.format(runs=p.runs))
    d = Daemon(p.base)
    d.boot_at = time.time() - 300
    d.wake_after_reboot()
    t = p.db.task(tid)
    res = json.loads(t["result"])
    if wakes:
        assert not t["not_before"] and res["woke"].startswith("the host rebooted"), dict(t)
    else:
        assert t["not_before"] > time.time() + 3000 and "woke" not in res, dict(t)


def test_reboot_wait_classifies_probes_by_where_they_run():
    from ttp import rebootwait as rw
    assert rw.transient("pgrep -f soak") == "a process"
    assert rw.transient("ttp devq probe dev 7") == "a device runner job"
    assert rw.transient("ttp checks --result /x/r1") == "its own checks"
    assert rw.transient("ssh box test -e /dev/shm/x || test -e /dev/shm/y") == "a path a reboot clears"
    assert rw.transient('test -e "$TTP_RUN_DIR/done"') == "a file in a run folder"
    assert rw.transient("ttp ci --repo o/r --branch b") == ""
    assert rw.transient("/opt/bin/ttp lock --probe dev") == ""
    assert rw.transient('test -e "/tmp/x') == "a path a reboot clears", "an unparsable probe wakes when in doubt"
    assert rw.stays_asleep({"retry_when": "kill -0 1", "survives_reboot": True})
    # A /tmp path on another host is untouched by a local reboot; a local one is not.
    assert rw.transient("ttp detach --check --host box1 /tmp/d/j") == ""
    assert rw.transient("ttp detach --check --host=box1 /tmp/d/j") == ""
    assert rw.transient("ssh box1 test -e /tmp/d/j") == ""
    assert rw.transient("test -e /tmp/d/j") == "a path a reboot clears"
    assert rw.stays_asleep({"retry_when": "ttp detach --check --host box1 /tmp/d/j"})
    # The --mirror run folder is copied from the remote host, so a reboot does not clear it.
    mirror = "ttp detach --check --host box1 --mirror /x/state/runs/7 /tmp/d/j"
    assert rw.transient(mirror) == "" and rw.transient(mirror.replace("--mirror ", "--mirror=")) == ""
    assert rw.stays_asleep({"retry_when": mirror})
    assert rw.transient("ttp detach --check /x/state/runs/7/x.rc") != ""
    assert rw.stays_asleep({"retry_when": "test -e /tmp/x", "survives_reboot": True})


def _reply_wait_hand_off(p, d, tmp_path, tid, **result):
    from ttp.providers.base import RunUsage as Usage
    p.db.update_task(tid, status="running")
    run_dir = tmp_path / f"run-{tid}-{len(list(tmp_path.iterdir()))}"
    run_dir.mkdir()
    (run_dir / "result.json").write_text(json.dumps({"status": "waiting", "summary": "asked the other project",
                                                     "retry_after_s": 1800, **result}))
    d._finish_worker({"task": tid, "note": "{}"}, Usage(cost_usd=0.1), "ok", run_dir)
    return p.db.task(tid)


def test_unmanaged_wait_matches_a_project_only_by_form_and_skips_detached_jobs():
    from ttp import ackwait
    w = lambda text, **kw: ackwait.unmanaged_wait({"waiting_for": text, "retry_when": "exit 1"}, ["ci", "review"], **kw)
    assert w("CI to respond") == "" and w("the review answer from the bot") == ""
    assert w("a reply from ci to note 0123abcd").startswith("hand-off refused")
    assert w("an answer from the review project").startswith("hand-off refused")
    assert w("ci's reply").startswith("hand-off refused")
    assert w("a reply from ci to note 0123abcd", job_in_flight=True) == ""


def test_ack_wait_accepts_a_projects_own_model_free_wrapper(tmp_path):
    from ttp import ackwait
    harness = tmp_path / "tt-project" / "harness"
    wait = {"status": "waiting", "waiting_for": "a reply from fleet-sim to note 0123abcd"}
    own = "python3 tt-project/harness/bin/ack_wait.py probe --from fleet-sim --hash 0123abcd"
    # The project's own `ack_wait.py probe` under its harness dir is a managed probe, relative or absolute.
    for rw in (own, own.split(" ", 1)[1], f"{harness}/bin/ack_wait.py probe --from fleet-sim --hash 0123abcd"):
        assert ackwait.is_probe(rw, harness=harness), rw
        assert ackwait.unmanaged_wait(dict(wait, retry_when=rw), ["fleet-sim"], harness=harness) == "", rw
    # Not without the harness dir, outside it, or without `probe`.
    for rw, h in ((own, None), ("python3 other/harness/bin/ack_wait.py probe --hash 0123abcd", harness),
                  ("python3 tt-project/harness/../../ack_wait.py probe --hash 0123abcd", harness),
                  ("python3 tt-project/harness/bin/ack_wait.py settle --hash 0123abcd", harness)):
        assert not ackwait.is_probe(rw, harness=h), rw
    # ack_wait.probe_commands lists more model-free wrappers: matched on whole leading words.
    cfg = {"ack_wait": {"probe_commands": ["bin/reply-wait probe", 7, ""]}}
    assert ackwait.is_probe("bin/reply-wait probe --from fleet-sim --hash 0123abcd", cfg)
    assert ackwait.is_probe("bin/reply-wait  probe", cfg)
    assert ackwait.unmanaged_wait(dict(wait, retry_when="bin/reply-wait probe --hash 0123abcd"), ["fleet-sim"], cfg=cfg) == ""
    for rw in ("bin/reply-wait probes", "bin/reply-wait", "exit 1", "bin/reply-wait-x probe"):
        assert not ackwait.is_probe(rw, cfg), rw
    # Any other command is still refused, and the refusal names the setting.
    msg = ackwait.unmanaged_wait(dict(wait, retry_when="exit 1"), ["fleet-sim"], cfg=cfg, harness=harness)
    assert msg.startswith("hand-off refused") and "ack_wait.probe_commands" in msg, msg


def test_a_reply_wait_on_the_projects_own_wrapper_is_not_refused(env, tmp_path, monkeypatch):
    from ttp import project
    from ttp.daemon import Daemon
    p = make(env)
    monkeypatch.setattr(project, "load_registry", lambda: {"projects": {p.name: {}, "fleet-sim": {}}})
