def test_waiting_tasks_from_before_the_boot_wake_on_the_first_tick(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    d.boot_at = time.time() - 300
    started = []
    monkeypatch.setattr(d, "start_run", lambda role, prompt, provider, tier, cwd, **k: started.append(k["task"]["id"]))
    later = time.time() + 3600

    def waiting(title, **extra):
        tid = p.db.add_task(title, "s", kind="work", tier="light", origin="user", not_before=later)
        p.db.update_task(tid, result=json.dumps({"status": "waiting", "summary": "job running", "retry_after_s": 3600,
                                                 "retry_when": "exit 1", "waiting_since": time.time() - 900,
                                                 **extra}))
        return tid

    dead = waiting("local job", retry_when="kill -0 4242")
    remote = waiting("remote job", retry_when="kill -0 4242", survives_reboot=True)
    d.tick()
    assert dead in started and remote not in started, started
    assert "the host rebooted" in json.loads(p.db.task(dead)["result"]).get("woke", "")
    assert p.db.task(remote)["not_before"] == later


@pytest.mark.parametrize("probe", ["test -e /tmp/build.done", "exit 1", "survives"])
def test_a_waiting_hand_off_cut_short_by_a_reboot_runs_again_now(env, tmp_path, probe):
    """Only a wait on what the reboot may have ended (a /tmp marker) runs again now: a timer sleeps on."""
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = p.db.add_task("build", "s", kind="work", tier="light", origin="user")
    p.db.update_task(tid, status="running")
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    (run_dir / "output.jsonl").write_text("")
    (run_dir / "result.json").write_text(json.dumps({"status": "waiting", "summary": "build started",
                                                     "retry_after_s": 3600, "retry_when": probe,
                                                     **({"survives_reboot": True} if probe == "survives" else {})}))
    if probe == "survives":   # its own job wrote no .rc, but the hand-off says the wait outlives a reboot
        (run_dir / "detached.json").write_text(json.dumps([{"name": "b", "rc": str(run_dir / "b.rc"),
                                                            "log": str(run_dir / "b.log")}]))
        probe = "exit 1"
    (run_dir / "lease").touch()
    os.utime(run_dir / "lease", (time.time() - 999, time.time() - 999))
    p.db.x("INSERT INTO runs(task,role,provider,started,status,dir,boot_id) VALUES(?,?,?,?,?,?,?)",
           (tid, "worker", "fake", time.time() - 1800, "running", str(run_dir), "an-earlier-boot"))
    d.reap_runs()
    d.probe_waiting()
    if probe == "exit 1":
        t = p.db.task(tid)
        assert tid not in [x["id"] for x in p.db.ready_tasks()] and t["not_before"] > time.time() + 3000, dict(t)
        assert "woke" not in json.loads(t["result"])
        return
    assert tid in [x["id"] for x in p.db.ready_tasks()], "a wait the reboot ended slept on its timer or probe"
    assert json.loads(p.db.task(tid)["result"])["woke"] == "the host rebooted"


# The daemon runs every stored probe with /bin/sh. Where that is dash, a bash here-string fails to parse.
SH_BROKEN = ["if then"] + (['grep -q ready <<< "$(cat status)"']
                           if os.path.realpath("/bin/sh").endswith("dash") else [])


