def test_machines_set_skips_a_host_in_outage_in_one_line_and_saves_locally(env, monkeypatch, capsys):
    """`ttp machines set` names a host in a known outage in one line and never copies to it; the local
    change is saved whatever the other hosts' state."""
    from ttp import cli
    from ttp import machines as mm
    from ttp import machine_ledger as ml
    from ttp import timefmt
    from ttp.project import register
    register("p1", {"host": "box-out", "dir": "/p1"})
    register("p2", {"host": "box-ok", "dir": "/p2"})
    mm.add("box-out", tags="x")
    ml.set_outage("box-out", "disk repair", "proj", "1d")
    started = []
    monkeypatch.setattr(mm, "push_background", lambda hosts: started.append(hosts) or "log")
    cli.main(["machines", "set", "box-a", "--tags", "device", "--note", "edited"])
    out = capsys.readouterr().out.splitlines()
    assert mm.load()["box-a"]["note"] == "edited"
    until = timefmt.long(ml.outages()["box-out"]["until"], timefmt.ambient())
    assert [ln for ln in out if "box-out" in ln] == [f"skipped box-out: box-out is in a known outage until {until}"]
    assert started == [["box-ok"]]
    monkeypatch.setattr(mm, "push_background", lambda hosts: (_ for _ in ()).throw(OSError(5, "Input/output error")))
    cli.main(["machines", "set", "box-b", "--tags", "device"])     # the copy cannot start: still saved, no raise
    assert "box-b" in mm.load()
    assert capsys.readouterr().out.splitlines()[-1] == ("could not start copying the machines list to box-ok: "
                                                        "[Errno 5] Input/output error")


def test_machines_push_reports_a_failing_host_in_one_line_and_updates_the_others(env, tmp_path, monkeypatch, capsys):
    """A copy that fails on one host (a read-only or failing disk there, an OSError here) is one line with no
    traceback, and the copies to the other hosts still go through."""
    import errno
    from ttp import cli
    from ttp import machines as mm
    from ttp.project import register
    homes = {h: tmp_path / h for h in ("box-ok", "box-ro", "box-io", "box-z")}
    for home in homes.values():
        home.mkdir()
    eio = tmp_path / "eio"      # the remote python on box-ro: every write fails with EIO, as on a failing /home
    eio.mkdir()
    (eio / "sitecustomize.py").write_text(
        "import errno, os\n"
        "def _eio(path, *a, **k):\n    raise OSError(errno.EIO, os.strerror(errno.EIO), path)\n"
        "os.open = _eio\nos.replace = _eio\n")
    real = subprocess.run

    def run(args, **kw):
        host = args[-2]
        if host == "box-io":
            raise OSError(errno.EIO, os.strerror(errno.EIO))
        env_ = {**os.environ, "HOME": str(homes[host])}
        if host == "box-ro" and "python3" in args[-1]:
            env_["PYTHONPATH"] = str(eio)
        return real(["bash", "-c", args[-1]], env=env_, **kw)
    monkeypatch.setattr(mm.subprocess, "run", run)
    for n, h in enumerate(("box-io", "box-ok", "box-ro", "box-z")):
        register(f"p{n}", {"host": h, "dir": f"/p{n}"})
    mm.add("box-a", tags="device")
    capsys.readouterr()
    cli.main(["machines", "push"])
    out = capsys.readouterr()
    lines = out.out.splitlines()
    assert "Traceback" not in out.out + out.err and len(lines) == 4
    assert lines[0] == "could not copy the machines list to box-io: OSError: [Errno 5] Input/output error"
    assert lines[2].startswith("could not copy the machines list to box-ro: [Errno 5] Input/output error: ")
    assert lines[1] == "copied the machines list (1 machines) to box-ok"
    assert lines[3] == "copied the machines list (1 machines) to box-z"
    for h in ("box-ok", "box-z"):
        assert "box-a" in json.loads((homes[h] / ".tt-project" / "machines.json").read_text())["machines"]
    assert not (homes["box-ro"] / ".tt-project" / "machines.json").exists()
    assert mm._short("Traceback (most recent call last):\n  File x\nOSError: boom\n\n") == "OSError: boom"


def test_machines_add_copies_the_list_in_the_background_past_a_down_host(env, tmp_path, monkeypatch, capsys):
    """A down host never holds `ttp machines add`: the copy runs on in its own session with a short ssh
    timeout, skipped hosts are named at once, and a failed copy is reported by the next change."""
    from ttp import cli
    from ttp import machines as mm
    from ttp import machine_ledger as ml
    from ttp.project import register
    bin_, gate, calls = tmp_path / "bin", tmp_path / "gate", tmp_path / "ssh.log"
    bin_.mkdir()
    (bin_ / "ssh").write_text(f"#!/bin/bash\necho \"$*\" >> {calls}\n"
                              f"for i in $(seq 300); do [ -e {gate} ] && break; sleep 0.1; done\n"
                              "echo 'connect to host far-down port 22: Connection timed out' >&2; exit 255\n")
    (bin_ / "ssh").chmod(0o755)
    monkeypatch.setenv("PATH", f"{bin_}:{os.environ['PATH']}")
    register("down", {"host": "far-down", "dir": "/p1"})
    register("out", {"host": "far-out", "dir": "/p2"})
    mm.add("far-out", tags="x")
    ml.set_outage("far-out", "repair", "proj", "1d")
    t0 = time.monotonic()
    cli.main(["machines", "add", "box-a", "--tags", "device"])
    assert time.monotonic() - t0 < 20 and not gate.exists()   # returned while the ssh still hangs
    out = capsys.readouterr().out
    assert "skipped far-out: far-out is in a known outage until " in out
    assert "copying the machines list to far-down in the background" in out
    gate.touch()
    for _ in range(300):
        if mm.PUSH_DONE in mm.push_log().read_text().splitlines():
            break
        time.sleep(0.1)
    args = calls.read_text()
    assert "far-down" in args and "far-out" not in args
    assert "BatchMode=yes" in args and "ConnectTimeout=5" in args and "ConnectionAttempts=1" in args
    assert mm.push_failures() == [f"could not copy the machines list to far-down: "
                                  f"connect to host far-down port 22: Connection timed out"]
    gate.unlink()
    monkeypatch.setattr(mm, "push_background", lambda hosts: "log")
    cli.main(["machines", "add", "box-b", "--tags", "device"])
    assert "last background copy: could not copy the machines list to far-down" in capsys.readouterr().out


def test_two_quick_machine_changes_keep_both_background_copies_results(env, tmp_path, monkeypatch, capsys):
    """A second change while the first copy still runs starts its own log: the first copy's results
    are never lost, each failure is reported once, and only the newest few logs are kept."""
    from ttp import cli
    from ttp import machines as mm
    from ttp.project import register
    bin_, gate = tmp_path / "bin", tmp_path / "gate"
    bin_.mkdir()
    (bin_ / "ssh").write_text(f"#!/bin/bash\nfor i in $(seq 300); do [ -e {gate} ] && break; sleep 0.1; done\n"
                              "echo \"connection timed out (copy $COPY_ID)\" >&2; exit 255\n")
    (bin_ / "ssh").chmod(0o755)
    monkeypatch.setenv("PATH", f"{bin_}:{os.environ['PATH']}")
    register("down", {"host": "far-down", "dir": "/p1"})
    for n, alias in ((1, "box-a"), (2, "box-b")):   # both start before either copy ends
        monkeypatch.setenv("COPY_ID", str(n))
        cli.main(["machines", "add", alias, "--tags", "device"])
    gate.touch()
    logs = []
    for _ in range(300):
        logs = sorted((mm.project.HOME_DIR / mm.PUSH_LOGS).glob("*.log"))
        if len(logs) == 2 and all(mm.PUSH_DONE in p.read_text().splitlines() for p in logs):
            break
        time.sleep(0.1)
    want = [f"could not copy the machines list to far-down: connection timed out (copy {n})" for n in (1, 2)]
    assert sorted(mm.push_failures()) == want
    capsys.readouterr()
    monkeypatch.setattr(mm, "push_background", lambda hosts: "log")
    cli.main(["machines", "add", "box-c", "--tags", "device"])
    out = capsys.readouterr().out
    assert all(f"last background copy: {w}" in out for w in want)
    cli.main(["machines", "add", "box-d", "--tags", "device"])
    assert "last background copy" not in capsys.readouterr().out      # each failure is reported once
    for n in range(mm.PUSH_KEEP + 2):
        (logs[0].parent / f"{n:019d}-1.log").write_text(f"x\n{mm.PUSH_DONE}\n")
    mm.prune_push_logs()
    assert len(list(logs[0].parent.glob("*.log"))) == mm.PUSH_KEEP and logs[-1].exists()


def test_machine_changes_are_copied_to_remote_project_machines(env, tmp_path, monkeypatch, capsys):
    from ttp import cli
    from ttp import machines as mm
    from ttp.project import register
    pushed = []
    monkeypatch.setattr(mm, "push", lambda host: pushed.append(host) or f"pushed {host}")
    monkeypatch.setattr(mm, "push_background", lambda hosts: pushed.extend(hosts) or "log")
    cli.main(["machines", "add", "box-a", "--tags", "device"])
    assert pushed == []                                     # no projects elsewhere: no ssh
    register("far1", {"host": "far", "dir": "/p1"})
    register("far2", {"host": "far", "dir": "/p2"})
    register("via", {"host": "other", "ssh": "other-alias", "dir": "/p3"})
    register("here", {"host": "testhost", "dir": str(tmp_path)})
    cli.main(["machines", "add", "box-b", "--tags", "device"])
    assert pushed == ["far", "other-alias"]
    cli.main(["machines", "remove", "box-b"])
    cli.main(["machines", "push", "--host", "only"])
    assert pushed == ["far", "other-alias"] * 2 + ["only"]
    assert "pushed only" in capsys.readouterr().out
    monkeypatch.setattr(cli, "ship_runtime", lambda host: pushed.append(f"ship {host}"))
    monkeypatch.setattr(cli, "forward", lambda entry, argv: 0)
    pushed.clear()
    with pytest.raises(SystemExit):
        cli.main(["upgrade", "via"])
    assert pushed == ["ship other-alias", "other-alias"]    # upgrade copies it with the runtime


def _bad_runs(p, tid, n, status="failed", ago=60):
    for _ in range(n):
        p.db.x("INSERT INTO runs(task, role, status, started, ended) VALUES(?,?,?,?,?)",
               (tid, "worker", status, time.time() - ago - 10, time.time() - ago))


def test_reboots_count_only_for_listed_machines_held_through_most_reboots(env):
    p = make(env)
    from ttp import machines as mm
    mm.add("box-a", tags="device")
    boot = lambda held: p.db.x("INSERT INTO events(ts,source,kind,severity,text,data,status) VALUES(?,?,?,?,?,?,?)",
                               (time.time(), "host", "boot", "normal", "reboot", json.dumps({"held": held}), "handled"))
    for _ in range(2):
        boot(["push: task #1 (run 2) since 10:02", "box-a: task #1 (run 2) since 10:02"])
    for _ in range(9):
        boot([])
    seen = mm.stats(p.db)
    assert "push" not in seen, "a logical lock is not a machine"
    assert "box-a" not in seen, "2 of 11 reboots while held is the host's own rate"
    for _ in range(9):
        boot(["box-a: task #1 (run 2) since 10:02"])
    assert mm.stats(p.db)["box-a"]["reboots"] == 11 and "push" not in mm.stats(p.db)


def test_a_failing_resource_starts_one_coordinator_turn_per_episode(env):
    p = make(env)
    from ttp import machines as mm
    from ttp.daemon import Daemon
    mm.add("box-a", tags="device")
    mm.add("box-b", tags="device")
    tid = p.db.add_task("soak test", "s", kind="work", tier="light", origin="user", labels=["exclusive:box-a"])
    d = Daemon(p.base)
    events = lambda: p.db.q("SELECT * FROM events WHERE kind='resource_trouble'")
    d.check_resource_trouble(every_s=0)
    assert not events()
    _bad_runs(p, tid, 2, status="lost")
    d.check_resource_trouble(every_s=0)
    d.check_resource_trouble(every_s=0)
    evs = events()
    assert len(evs) == 1 and evs[0]["status"] == "queued" and "box-a" in evs[0]["text"]
    assert "machines sharing its tags: box-b" in evs[0]["text"] and "task_update `resources`" in evs[0]["text"]
    assert set(p.db.kv("resource_trouble")) == {"box-a"}
    p.db.x("UPDATE runs SET ended=?", (time.time() - 2 * 86400,))
    d.check_resource_trouble(every_s=0)
    assert p.db.kv("resource_trouble") == {}, "the episode did not end once the failures aged out"
    _bad_runs(p, tid, 2)
    d.check_resource_trouble(every_s=0)
    assert len(events()) == 2, "a new episode was not told"


