    for _ in range(3):
        d.tick()
    notes = p.db.q("SELECT kind FROM messages WHERE ref LIKE 'reboot:%'")
    assert notes == [{"kind": "info"}], notes
    assert not p.db.q("SELECT id FROM alerts WHERE key LIKE 'reboot:%'")
