_CAP_HOLDER = ("import sys, time; sys.path.insert(0, sys.argv[1]); from ttp import checkcap; "
               "s = checkcap.acquire(sys.argv[2]); print('held', flush=True); time.sleep(120)")


def _cap_holder(label):
    proc = subprocess.Popen([sys.executable, "-c", _CAP_HOLDER, str(RUNTIME), label], stdout=subprocess.PIPE, text=True)
    assert proc.stdout.readline().strip() == "held"
    return proc


def test_checks_host_cap_default_follows_cores_and_the_account_setting_overrides_it(env, monkeypatch):
    from ttp import checkcap, project
    monkeypatch.setattr(checkcap, "cores", lambda: 64)
    monkeypatch.setattr(checkcap.os, "getloadavg", lambda: (60.0, 0.0, 0.0))
    assert checkcap.limit() == 4, "a busy host gets the floor"
    monkeypatch.setattr(checkcap, "cores", lambda: 8)
    assert checkcap.limit() == 1, "a small host still runs one at a time"
    project.set_account_setting("checks.host_max", 3)
    assert checkcap.limit() == 3
    monkeypatch.setenv("TTP_CHECKS_HOST_MAX", "0")
    assert checkcap.limit() == 0
    monkeypatch.setenv("TTP_CHECKS_HOST_MAX", "junk")
    assert checkcap.limit() == 3, "an unreadable override falls back to the setting"


def test_checks_host_cap_enforces_the_limit_and_serves_waiters_in_order(env, monkeypatch):
    import threading
    from ttp import checkcap
    monkeypatch.setenv("TTP_CHECKS_HOST_MAX", "2")
    a, b = checkcap.acquire("a"), checkcap.acquire("b")
    assert a.f and b.f
    got, told, waits = [], [], []

    def take(label):
        s = checkcap.acquire(label, tell=told.append, waiting=waits.append)
        got.append(label)
        s.close()

    first = threading.Thread(target=take, args=("c",))
    first.start()
    assert _wait_for(lambda: len(checkcap.state()["queued"]) == 1)
    second = threading.Thread(target=take, args=("d",))
    second.start()
    assert _wait_for(lambda: len(checkcap.state()["queued"]) == 2)
    time.sleep(0.3)
    assert got == [], "nobody runs past the cap"
    assert checkcap.state()["running"] == ["a", "b"]
    assert "2 running (cap 2), 2 queued: c; d" in checkcap.line()
    assert any("queued for a host-wide checks slot: 2 of 2 running" in t for t in told) and waits[0] is True
    a.close()
    first.join(10)
    second.join(10)
    assert got == ["c", "d"], "waiters are served in arrival order"
    assert False in waits
    b.close()
    # Nested in a check command (its parent holds a slot): it never waits.
    full = [checkcap.acquire("x"), checkcap.acquire("y")]
    monkeypatch.setenv(checkcap.HELD_ENV, "1")
    assert checkcap.acquire("nested").f is None
    for s in full:
        s.close()


def test_fair_order_takes_turns_by_project_and_keeps_arrival_order_within_one(tmp_path, monkeypatch):
    from ttp import locks
    d = tmp_path / "slots"
    t = [locks.enqueue(d, "r", f"{g}{i}", since=1000.0 + n, group=g or None)
         for n, (g, i) in enumerate([("A", 1), ("A", 2), ("A", 3), ("B", 1), ("", 1), ("B", 2)])]
    names = lambda: [x.read_text() for x in locks.fair_order(d, "r")]
    assert names() == ["A1", "B1", "1", "A2", "B2", "A3"], "unlabeled waiters are a group of their own"
    resumed = locks.enqueue(d, "r", "B0", since=999.0, group="B")
    assert names()[:3] == ["B0", "A1", "1"], "a resumed waiter keeps its arrival time and place"
    locks.dequeue(resumed)
    locks.mark_served(d, "r", "A")
    assert names() == ["B1", "1", "A1", "B2", "A2", "A3"], "the project served last waits for the others"
    assert [x.read_text() for x in locks.queued(d, "r")] == ["A1", "A2", "A3", "B1", "1", "B2"]
    old = locks.served_dir(d, "r") / locks.group_id("B")
    old.touch()
    os.utime(old, (1, 1))
    locks.mark_served(d, "r", None)
    assert not old.exists(), "records older than a day are pruned"
    for x in t:
        locks.dequeue(x)


def test_fair_order_serves_a_project_s_waiters_by_task_priority_then_arrival(tmp_path):
    import math
    from ttp import locks
    d = tmp_path / "slots"
    spec = [("A", "a3", 3), ("A", "a3b", 3), ("B", "b", None), ("A", "a1", 1), ("A", "a-", None),
            ("B", "b2", 2), ("A", "a-b", None), ("A", "a1b", 1)]
    t = [locks.enqueue(d, "r", label, since=1000.0 + n, group=g, priority=pr) for n, (g, label, pr) in enumerate(spec)]
    names = lambda: [x.read_text() for x in locks.fair_order(d, "r")]
    assert names() == ["a1", "b2", "a1b", "b", "a3", "a3b", "a-", "a-b"], \
        "a later p1 goes before earlier p3s, projects still take turns, no priority last in arrival order"
    locks.mark_served(d, "r", "A")
    assert names()[:2] == ["b2", "a1"], "the project served last still waits for the others"
    assert [x.read_text() for x in locks.queued(d, "r")] == [label for _, label, _ in spec]
    for x in t:
        locks.dequeue(x)
    # Tickets of older runtimes (no group, no priority) and new ones read by the old group parse.
    tk = lambda n: tmp_path / n
    assert [(locks.ticket_group(tk(n)), locks.ticket_priority(tk(n))) for n in (
        "1000.000000-12", "1000.000000-12-shared", "1000.000000-12.gabc123", "1000.000000-12.p2.gabc123-shared",
        "1000.000000-12.p1", "1000.000000-12.px.gabc123")] == [
        ("", math.inf), ("", math.inf), ("abc123", math.inf), ("abc123", 2), ("", 1), ("abc123", math.inf)]
    new = locks.enqueue(d, "r", "x", group="A", priority=2, shared=True)
    assert locks.is_shared(new) and locks.ticket_group(new) == locks.group_id("A") and locks.ticket_priority(new) == 2
    assert new.name.removesuffix(locks.SHARED_TICKET).rpartition(locks.GROUP_TICKET)[2] == locks.group_id("A")
    locks.dequeue(new)


def test_checks_slot_waiters_carry_the_running_task_s_priority(env, monkeypatch):
    import threading
    from types import SimpleNamespace
    from ttp import checkcap
    tasks = {7: {"priority": 1}, 8: {"priority": None}}
    p = SimpleNamespace(db=SimpleNamespace(task=tasks.get))
    for task, want in (("7", 1), ("8", None), ("9", None), ("", None)):
        monkeypatch.setenv("TTP_TASK", task)
        assert checkcap.task_priority(p) == want
    assert checkcap.task_priority(None) is None
    monkeypatch.setenv("TTP_TASK", "7")
    assert checkcap.task_priority(SimpleNamespace(db=SimpleNamespace(task=lambda i: 1 / 0))) is None
    monkeypatch.setenv("TTP_CHECKS_HOST_MAX", "1")
    held = checkcap.acquire("h")
    got = []

    def take(label, proj, prio):
        s = checkcap.acquire(label, project_name=proj, priority=prio)
        got.append(label)
        s.close()

    waiters = []
    for i, args in enumerate([("a3", "A", 3), ("a-", "A", None), ("b", "B", 2), ("a1", "A", 1)]):
        waiters.append(threading.Thread(target=take, args=args))
        waiters[-1].start()
        assert _wait_for(lambda: len(checkcap.state()["queued"]) == i + 1)
    assert checkcap.state()["queued"] == ["a1", "b", "a3", "a-"]
    held.close()
    for w in waiters:
        w.join(20)
    assert got == ["a1", "b", "a3", "a-"]


def test_checks_host_cap_serves_projects_round_robin(env, monkeypatch):
    import threading
    from ttp import checkcap
    monkeypatch.setenv("TTP_CHECKS_HOST_MAX", "1")
    held = checkcap.acquire("h")
    got, told = [], []

    def take(label, proj):
        s = checkcap.acquire(label, tell=told.append if label == "c1" else None, project_name=proj)
        got.append(label)
        s.close()

    waiters = []
    for i, (label, proj) in enumerate([("a1", "A"), ("a2", "A"), ("a3", "A"), ("b1", "B"), ("b2", "B"), ("c1", "C")]):
        waiters.append(threading.Thread(target=take, args=(label, proj)))
        waiters[-1].start()
        assert _wait_for(lambda: len(checkcap.state()["queued"]) == i + 1)
    assert _wait_for(lambda: told)
    assert "queued for a host-wide checks slot: 1 of 1 running, 2 ahead, 3 projects" in told[0]
    assert checkcap.state()["queued"] == ["a1", "b1", "c1", "a2", "b2", "a3"], "status lists them in serving order"
    assert "1 running (cap 1), 6 queued: a1; b1; c1; a2; ... (running: h)" in checkcap.line()
    assert checkcap.line().endswith("; next per project: a1 0 ahead, b1 1 ahead, c1 2 ahead"), \
        "each project's next waiter shows how many are served before it"
    held.close()
    for w in waiters:
        w.join(20)
    assert got == ["a1", "b1", "c1", "a2", "b2", "a3"], "projects take turns, each in arrival order"
    assert checkcap.line() == ""


_WAITER = ("import sys, time; sys.path.insert(0, sys.argv[1]); from ttp import checkcap; "
           "s = checkcap.acquire(sys.argv[2], tell=lambda m: print(m, flush=True), project_name=sys.argv[3]); print('took', flush=True); "
           "time.sleep(120)")


def test_checks_host_cap_a_killed_waiter_frees_its_place(env, monkeypatch):
    import threading
    from ttp import checkcap
    monkeypatch.setenv("TTP_CHECKS_HOST_MAX", "1")
    held = checkcap.acquire("h")
    proc = subprocess.Popen([sys.executable, "-c", _WAITER, str(RUNTIME), "doomed", "A"], stdout=subprocess.PIPE, text=True)
    got = []
    try:
        assert "queued for a host-wide checks slot" in proc.stdout.readline()
        t = threading.Thread(target=lambda: got.append(checkcap.acquire("next", project_name="B")))
        t.start()
        assert _wait_for(lambda: checkcap.state()["queued"] == ["doomed", "next"])
    finally:
        proc.kill()
        proc.wait()
    assert _wait_for(lambda: checkcap.state()["queued"] == ["next"]), "a dead waiter leaves the queue"
    held.close()
    t.join(20)
    assert got and got[0].f is not None, "the next waiter takes the place it left"
    got[0].close()


_PRIORITY_HOLDER = ("import sys, time; sys.path.insert(0, sys.argv[1]); from ttp import checkcap; "
                    "s = checkcap.acquire_priority(sys.argv[2], sys.argv[3]); print('held', flush=True); time.sleep(120)")


def test_push_checks_take_a_priority_slot_ahead_of_every_queued_task_check(env, monkeypatch):
    import threading
    from ttp import checkcap, locks
    monkeypatch.setenv("TTP_CHECKS_HOST_MAX", "2")
    full = [checkcap.acquire("a"), checkcap.acquire("b")]
    got = []

    def take(label):
        s = checkcap.acquire(label)
        got.append(label)
        s.close()

    waiters = [threading.Thread(target=take, args=(x,)) for x in ("c", "d", "e")]
    for i, t in enumerate(waiters):
        t.start()
        assert _wait_for(lambda: len(checkcap.state()["queued"]) == i + 1)
    told = []
    served = sorted(os.listdir(locks.served_dir(checkcap.slot_dir(), checkcap.RESOURCE)))
    push = checkcap.acquire_priority("git@example:org/repo#main", "proj push batch 5", "push checks", told.append)
    assert sorted(os.listdir(locks.served_dir(checkcap.slot_dir(), checkcap.RESOURCE))) == served, \
        "the priority slot takes no project's turn"
    assert push.f is not None and push.env() == {checkcap.HELD_ENV: "1"}, "it starts at once with every slot busy"
    assert got == [], "task checks keep their cap: the priority slot is not theirs"
    assert "push priority slot" in told[0] and "2 task checks running, 3 queued behind" in told[0]
    st = checkcap.state()
    assert st["priority"] == ["proj push batch 5"] and st["running"] == ["a", "b"] and len(st["queued"]) == 3
    assert "push priority slot: proj push batch 5" in checkcap.line()
    # One per push branch: another push to the same branch waits for it alone; another branch does not.
    other = checkcap.acquire_priority("git@example:org/repo#dev", "proj push batch 6")
    assert other.f is not None
    second = []
    t2 = threading.Thread(target=lambda: second.append(checkcap.acquire_priority("git@example:org/repo#main", "p2")))
    t2.start()
    time.sleep(0.3)
    assert second == []
    push.close()
    t2.join(10)
    assert second and second[0].f is not None
    second[0].close()
    other.close()
    # Task checks are not starved: they still run in arrival order as their own slots free.
    full[0].close()
    for t in waiters:
        t.join(10)
    assert got == ["c", "d", "e"]
    full[1].close()
    assert checkcap.line() == ""
    monkeypatch.setenv(checkcap.HELD_ENV, "1")
    assert checkcap.acquire_priority("k", "nested").f is None, "nested in a held slot it never waits"


def test_push_priority_slot_of_a_killed_push_is_reclaimed(env, monkeypatch):
    from ttp import checkcap
    monkeypatch.setenv("TTP_CHECKS_HOST_MAX", "1")
    proc = subprocess.Popen([sys.executable, "-c", _PRIORITY_HOLDER, str(RUNTIME), "repo#main", "killed push"],
                            stdout=subprocess.PIPE, text=True)
    try:
        assert proc.stdout.readline().strip() == "held"
        assert checkcap.state()["priority"] == ["killed push"]
    finally:
        proc.kill()
        proc.wait()
    assert checkcap.priority_path("repo#main").exists(), "the label stays behind"
    assert checkcap.state()["priority"] == [] and checkcap.line() == "", "but a dead holder holds nothing"
    s = checkcap.acquire_priority("repo#main", "next push")
    assert s.f is not None and checkcap.state()["priority"] == ["next push"]
    s.close()


def test_checks_host_cap_queues_detached_checks_and_starts_them_once_the_holder_dies(env, tmp_path, monkeypatch, capsys):
    from ttp import checkcap, cli, detach
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    monkeypatch.setenv("TTP_CHECKS_HOST_MAX", "1")
    monkeypatch.setenv("TTP_TASK", "7")
    holder = _cap_holder("other project task #3 (run 9)")
    ran, seen = tmp_path / "ran", tmp_path / "seen"
    try:
        cli.main(["checks", "--detach", "--", "sh", "-c", f'echo "${checkcap.HELD_ENV}" > {seen}; touch {ran}'])
        assert _wait_for(lambda: (run / cli.CHECKS_SLOT_WAIT).exists())
        capsys.readouterr()
        assert detach.queued(run / cli.CHECKS_RC) != run / cli.CHECKS_SLOT_WAIT, \
            "the slot wait is not the daemon's launch marker, which the probe clears as an orphan"
        assert cli._checks_result(run) == 1, "a queued run is still waiting, not finished"
        out = capsys.readouterr().out
        assert "queued for a host-wide checks slot" in out and "other project task #3 (run 9)" in out
        assert "queued for a host-wide checks slot" in (run / "progress.md").read_text()
        assert "host checks: 1 running (cap 1), 1 queued:" in cli.status_text(p)
        assert "(running: other project task #3 (run 9))" in cli.status_text(p), "it still lists the holders"
        assert f"{p.name} task #7 (run 41)" in checkcap.line()
        assert not ran.exists(), "nothing runs over the cap"
    finally:
        holder.kill()
        holder.wait()
    # The holder died without releasing anything: its slot is free with it.
    assert _wait_for(lambda: (run / cli.CHECKS_RC).exists())
    assert (run / cli.CHECKS_RC).read_text().strip() == "0" and ran.exists()
    assert seen.read_text().strip() == "1", "check commands know their run holds a slot"
    assert not (run / cli.CHECKS_SLOT_WAIT).exists()
    assert "slot taken after" in (run / "progress.md").read_text()
    assert checkcap.line() == "", "the slot is released once the checks end"


def test_checks_host_cap_foreground_wait_does_not_count_toward_the_run(env, tmp_path, monkeypatch, capsys):
    import threading
    from ttp import cli, locks
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
