def _fetch_origin(repo, tries=20):
    """`git fetch origin` that waits out a concurrent fetch (the daemon's) holding the same ref lock."""
    for i in range(tries):
        r = subprocess.run(["git", "-C", str(repo), "fetch", "-q", "origin"], capture_output=True, text=True)
        if r.returncode == 0:
            return
        if "cannot lock ref" not in r.stderr or i == tries - 1:
            raise subprocess.CalledProcessError(r.returncode, r.args, r.stdout, r.stderr)
        time.sleep(0.1)


def test_fetch_origin_helper_retries_only_a_ref_lock_race(monkeypatch):
    calls = []
    def fake(cmd, **kw):
        calls.append(1)
        err = "cannot lock ref 'refs/remotes/origin/proj'" if len(calls) < 3 else ""
        return subprocess.CompletedProcess(cmd, 1 if err else 0, "", err)
    monkeypatch.setattr(subprocess, "run", fake)
    monkeypatch.setattr(time, "sleep", lambda s: None)
    _fetch_origin("x")
    assert len(calls) == 3
    monkeypatch.setattr(subprocess, "run", lambda cmd, **kw: subprocess.CompletedProcess(cmd, 1, "", "fatal: other"))
    with pytest.raises(subprocess.CalledProcessError):
        _fetch_origin("x")


def _land_on_proj(repo, other, branch):
    """Another clone lands `branch`'s commits on origin/proj as rebased copies (new shas, after a commit
    of its own), as the push queue does."""
    _commit(other, f"theirs-{branch.replace('/', '-')}.txt", "theirs\n")
    _git_out(other, "fetch", "-q", str(repo), branch)
    _git_out(other, "cherry-pick", "HEAD..FETCH_HEAD")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    _fetch_origin(repo)


def test_a_split_hop_starts_at_once_and_never_waits_on_its_own_chains_landing(env, monkeypatch):
    """A split's hop starts from its branch's head, not the push branch's tip: it never waits on the
    split's landing, which comes only with the hop's own work. A landed: wait on a task of its own
    continue chain is refused (task_add and task_update) while that task has not landed."""
    from ttp import coordinator as coord
    from ttp import daemon as dmod
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    root, branch, done, reviews = _finish_code(env, p, "feature", {"a.py": 10}, result=_cont("feature"))
    (hop,) = p.db.q("SELECT * FROM tasks WHERE parent=?", (root,))
    assert not reviews and hop["status"] == "queued"
    assert not any(x.startswith("start_when:") for x in _labels(p, hop["id"]))
    assert "land on the push branch" not in done["text"] and done["status"] == "handled"
    _settle_deferred(dmod.Daemon(p.base), hop["id"])
    assert _ready(p, hop["id"]) and not _events(p, hop["id"], "deferral_probe_broken")
    (problem,) = coord.apply(p, [{"type": "task_update", "id": hop["id"], "start_when": f"landed:#{root}"}])
    assert f"waits on #{root}, which this task continues" in problem
    assert not any(x.startswith("start_when:") for x in _labels(p, hop["id"]))
    p.db.update_task(hop["id"], status="cancelled")
    (problem,) = coord.apply(p, [{"type": "task_add", "title": "continue: feature", "spec": "s", "kind": "code",
                                  "continues": root, "start_when": f"landed:#{root}"}])
    assert f"waits on #{root}, which this task continues" in problem
    # A wait on a task outside the chain, or on one whose work already landed, is accepted.
    outside = p.db.add_task("other work", "s", kind="code", origin="coordinator")
    assert coord.apply(p, [{"type": "task_add", "title": "continue: feature", "spec": "s", "kind": "code",
                            "continues": root, "start_when": f"landed:#{outside}"}]) == []
    from ttp import chaincap
    lineage = [t["id"] for t in chaincap.chain(p.db, root)]
    assert chaincap.own_wait(p, lineage, f"landed:#{root}")
    p.db.x("INSERT INTO task_superseded(task, head, sha, ts) VALUES(?,?,?,?)", (root, "b" * 40, "a" * 40, time.time()))
    assert chaincap.own_wait(p, lineage, f"landed:#{root}") == ""


def test_a_daemon_queued_code_hop_whose_predecessor_already_landed_starts_at_once(env, monkeypatch):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    branches = {}

    def land(tid, head):
        branches[tid] = p.db.task(tid)["branch"]
        _land_on_proj(repo, other, branches[tid])

    root, _, done, reviews = _finish_code(env, p, "feature", {"a.py": 10}, result=_cont("feature"), before=land)
    (hop,) = p.db.q("SELECT * FROM tasks WHERE parent=?", (root,))
    assert not reviews and p.db.one("SELECT 1 FROM task_superseded WHERE task=?", (root,))
    assert not any(x.startswith("start_when:") for x in _labels(p, hop["id"])) and _ready(p, hop["id"])
    assert f"Continue hop #{hop['id']} queued by the daemon (1 new commit)." in done["text"]
    # A code hop that committed nothing has nothing to land: its next hop starts at once too.
    _hop(env, p, hop["id"], {}, dict(_cont("feature, part 2"), metrics={"passed": 3}))
    (nxt,) = p.db.q("SELECT * FROM tasks WHERE parent=?", (hop["id"],))
    assert not any(x.startswith("start_when:") for x in _labels(p, nxt["id"])) and _ready(p, nxt["id"])


def test_a_daemon_queued_code_hop_waits_for_no_landing_where_its_review_pushes_nothing(env, monkeypatch):
    """With no push branch (draft PRs, the default) or pushing off, the predecessor's commits never land
    on a push branch: a landed: wait could never pass, so the hop starts at once, as before."""
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    p = make(env)
    _git_out(env["repo"], "branch", "work")
    for title, setup in (("parser", ()), ("widget", (("delivery.push_branch", "work"), ("delivery.push_allowed", False)))):
        for key, val in setup:
            p.set_config(key, val)
        root, _, done, reviews = _finish_code(env, p, title, {f"{title}.py": 10}, result=_cont(title))
        (hop,) = p.db.q("SELECT * FROM tasks WHERE parent=?", (root,))
        assert not reviews and hop["status"] == "queued"
        assert not any(x.startswith("start_when:") for x in _labels(p, hop["id"])), setup
        assert f"Continue hop #{hop['id']} queued by the daemon" in done["text"] and "land on the push" not in done["text"]
        _settle_deferred(dmod.Daemon(p.base), hop["id"])
        assert _ready(p, hop["id"]) and not _events(p, hop["id"], "deferral_probe_broken")


def _chain(p, n, status="done"):
    """A root code task and `n` `continue:` hops after it, all `status`: their ids."""
    ids = [p.db.add_task("parser", "s", kind="code", origin="coordinator")]
    for i in range(n):
        ids.append(p.db.add_task(f"continue: parser {i}", "s", kind="code", parent=ids[-1]))
    for i in ids:
        p.db.update_task(i, status=status)
    return ids


def test_a_continue_chain_over_its_cap_is_refused_unless_its_reason_names_what_changed(env):
    p = make(env)
    from ttp import audit, chaincap
    from ttp import coordinator as coord
    from ttp.db import continues_id
    p.set_config("chains.max_hops", 2)
    root, _, tip = _chain(p, 2)
    act = {"type": "task_add", "title": "continue: parser, next", "spec": "carry on", "kind": "code", "continues": tip}
    problems = coord.apply(p, [act])
    assert any("refused" in x and "chains.max_hops is 2" in x for x in problems), problems
    assert not p.db.q("SELECT id FROM tasks WHERE parent=?", (tip,))
    (ev,) = p.db.q("SELECT * FROM events WHERE kind=?", (chaincap.CAP_EVENT,))
    assert ev["status"] == "queued" and json.loads(ev["data"])["root"] == root and "Re-plan" in ev["text"]
    labels, _ = coord.effort_triggers(p.db, p.config(), [ev["id"]], None)
    assert chaincap.TRIGGER in labels
    coord.apply(p, [act])
    assert len(p.db.q("SELECT id FROM events WHERE kind=?", (chaincap.CAP_EVENT,))) == 1, "one event per lineage and hop"
    why = "new approach: parse the header once instead of per line"
    problems = coord.apply(p, [dict(act, reason="keep going, it is almost there")])
    assert any("does not name what changed" in x for x in problems)
    assert coord.apply(p, [dict(act, reason=why)]) == []
    (new,) = p.db.q("SELECT * FROM tasks WHERE parent=?", (tip,))
    assert p.db.one("SELECT 1 FROM events WHERE kind=?", (chaincap.OVERRIDE_EVENT,))
    assert any("past its cap" in x for x in p.db.kv(coord.NOTES_KEY))
    line = next(x for x in audit.lines(p.db) if x.startswith("continue chains"))
    assert f"#{root} parser: 3 hops to #{new['id']}" in line and "1 refused" in line and "1 overridden" in line
    # Dollars and failed hops in a row cap a lineage too.
    p.set_config("chains.max_hops", 0)
    ids = _chain(p, 2)
    p.db.x("UPDATE tasks SET spent_usd=25 WHERE id IN (?,?)", ids[:2])
    assert "chains.max_usd is $40" in chaincap.refusal(p, p.config(), chaincap.chain(p.db, ids[-1]))
    ids = _chain(p, 2, status="failed")
    assert "2 failed or no-progress hops" in chaincap.refusal(p, p.config(), chaincap.chain(p.db, ids[-1]))
    assert chaincap.refusal(p, p.config(), chaincap.chain(p.db, ids[-2])) == ""
    # A hop added with `continues` on a done task stays in its lineage whatever its title.
    p.set_config("chains.max_hops", 2)
    root, tip = _chain(p, 1)
    assert coord.apply(p, [{"type": "task_add", "title": "parser part three", "spec": "s", "kind": "code",
                            "continues": tip}]) == []
    (new,) = p.db.q("SELECT * FROM tasks WHERE parent=?", (tip,))
    assert chaincap.FOLLOWS + str(tip) in json.loads(new["labels"]) and continues_id(new) is None
    assert [t["id"] for t in chaincap.chain(p.db, new["id"])] == [root, tip, new["id"]]
    assert "chains.max_hops is 2" in chaincap.refusal(p, p.config(), chaincap.chain(p.db, new["id"]))
    p.db.update_task(new["id"], status="done")
    problems = coord.apply(p, [{"type": "task_add", "title": "parser, the rest", "spec": "s", "kind": "code",
                                "continues": new["id"]}])
    assert any("refused" in x and "chains.max_hops is 2" in x for x in problems), problems


def test_a_continue_hop_in_an_area_under_review_area_cap_is_refused(env):
    p = make(env)
    from ttp import chaincap, reviewcap
    from ttp import coordinator as coord
    root, tip = _chain(p, 1)
    p.db.x("INSERT INTO events(ts,source,kind,severity,text,data,status) VALUES(?,?,?,?,?,?,?)",
           (time.time(), "task:9", reviewcap.REVIEW_AREA_EVENT, "normal", "area", json.dumps({"root": root, "tasks": [root]}),
            "handled"))
    problems = coord.apply(p, [{"type": "task_add", "title": "continue: parser again", "spec": "s", "kind": "code",
                                "continues": tip}])
    assert any(f"review area of #{root}" in x for x in problems), problems
    assert not p.db.q("SELECT id FROM tasks WHERE parent=?", (tip,))
    assert p.db.one("SELECT 1 FROM events WHERE kind=?", (chaincap.CAP_EVENT,))
    # Past the review window the area no longer holds it.
    p.db.x("UPDATE events SET ts=? WHERE kind=?", (time.time() - reviewcap.AREA_WINDOW_S - 60, reviewcap.REVIEW_AREA_EVENT))
    assert chaincap.refusal(p, p.config(), chaincap.chain(p.db, tip)) == ""


def test_a_single_failure_on_a_busy_main_file_joins_another_lineage_only_where_the_changes_overlap(env):
    """A lineage with one failed review was capped because 12 failures of a separate lineage had the
    same main file. Then the plain main-file fallback came back at 2 failures in the review's own
    lineage, and unrelated lineages on a file most changes touch reported 14-18 failures. Now only
    overlapping hunks or functions in the main file join, however many failed in its own lineage,
    and the event and daily review report own-lineage and pooled failures apart."""
    p = make(env)
    from ttp import reviewcap, unblock
    fups = [{"title": "fix it", "spec": "it breaks"}]
    (p.root / "core.py").write_text("".join(f"def f{i}():\n" + "    x = 1\n" * 8 + f"    return {i}\n\n\n"
                                            for i in range(10)))
    _git_out(p.root, "add", "core.py")
    _git_out(p.root, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "core")

    def stack(title, fn):
        def edit(path):
            src = (path / "core.py").read_text()
            (path / "core.py").write_text(src.replace(f"    return {fn}\n", f"    return {fn}  # {title}\n"))
        _, _, _, (rev,) = _finish_code(env, p, title, {}, edit=edit)
        _fail_review(env, p, rev["id"], fups)
        return rev

    def fixed(rev):
        return p.db.one("SELECT id FROM tasks WHERE title LIKE ?", (f"Fix review #{rev['id']}:%",)) is not None

    def capped():
        return [json.loads(r["data"]) for r in p.db.q("SELECT data FROM events WHERE kind=? ORDER BY id",
                                                      (reviewcap.REVIEW_AREA_EVENT,))]
    # The busy lineage fails three times on f0 and reaches the cap by itself.
    a1 = stack("feature", 0)
    a2 = stack(f"#{a1['depends_on'][1:-1]} follow-up: feature", 0)
    a3 = stack(f"Fix re-review #{a2['id']}: feature", 0)
    assert [d["reviews"] for d in capped()] == [[a1["id"], a2["id"], a3["id"]]]
    # A separate lineage fails once on f9 of the same main file: not pooled, its fix is queued.
    b = stack("unrelated tidy", 9)
    assert reviewcap.main_file(p, p.db.task(b["id"])) == "core.py"
    assert fixed(b) and len(capped()) == 1, "an unrelated lineage on the same main file was capped"
    assert reviewcap.area(p, p.config(), p.db.task(b["id"])) is None
    # One failure that changes the busy lineage's own function does join it.
    c = stack("another take on f0", 0)
    assert not fixed(c) and capped()[-1]["reviews"] == [a1["id"], a2["id"], a3["id"], c["id"]]
    # Two failures in its own lineage do not pool the unrelated ones on the same main file.
    d1 = stack("d work", 5)
    assert fixed(d1) and len(capped()) == 2
    d2 = stack(f"#{d1['depends_on'][1:-1]} follow-up: d work", 5)
    assert fixed(d2) and len(capped()) == 2, "unrelated failures on one busy main file were pooled"
    assert reviewcap.area(p, p.config(), p.db.task(d2["id"])) is None
    # A separate lineage that changes d's function joins it; own and pooled are reported apart.
    e = stack("another take on f5", 5)
    assert not fixed(e)
    ev = p.db.one("SELECT * FROM events WHERE kind=? ORDER BY id DESC", (reviewcap.REVIEW_AREA_EVENT,))
    data = json.loads(ev["data"])
    assert data["reviews"] == [d1["id"], d2["id"], e["id"]]
    assert data["own"] == [e["id"]] and data["pooled"] == [d1["id"], d2["id"]]
    assert (f"1 in its own lineage (#{e['id']}), 2 pooled from other lineages with overlapping changes "
            f"to the same main file (#{d1['id']}, #{d2['id']})") in ev["text"]
    assert f"#{data['root']} (3 failed reviews: 1 own, 2 pooled, core.py)" in "\n".join(unblock.lines(p.db))


def test_edits_to_different_methods_of_one_class_do_not_overlap(env):
    """git's hunk header names the enclosing top-level line, `class Core:` for every method edit,
    so two edits to unrelated methods of one class overlapped. The shared name is now the innermost
    enclosing function read from the base file; an enclosing class alone is no overlap."""
    p = make(env)
    from ttp import reviewcap
    fups = [{"title": "fix it", "spec": "it breaks"}]
    (p.root / "core.py").write_text("class Core:\n" + "".join(
        f"    def m{i}(self):\n" + "        x = 1\n" * 8 + f"        return {i}\n\n" for i in range(10)))
    _git_out(p.root, "add", "core.py")
    _git_out(p.root, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "core")

    def stack(title, fn, line="return"):
        def edit(path):
            src = (path / "core.py").read_text()
            old = f"        return {fn}\n" if line == "return" else f"    def m{fn}(self):\n        x = 1\n"
            (path / "core.py").write_text(src.replace(old, old.replace("\n", f"  # {title}\n", 1), 1))
        _, _, _, (rev,) = _finish_code(env, p, title, {}, edit=edit)
        _fail_review(env, p, rev["id"], fups)
        return rev

    def capped():
        return [json.loads(r["data"]) for r in p.db.q("SELECT data FROM events WHERE kind=? ORDER BY id",
                                                      (reviewcap.REVIEW_AREA_EVENT,))]
    a1 = stack("feature", 0)
    a2 = stack(f"#{a1['depends_on'][1:-1]} follow-up: feature", 0)
    a3 = stack(f"Fix re-review #{a2['id']}: feature", 0)
    assert [d["reviews"] for d in capped()] == [[a1["id"], a2["id"], a3["id"]]]
    a_side = reviewcap.touched(p, p.db.task(a1["id"]), "core.py")
    assert a_side[1] == {"Core.m0"}, a_side
    # One failure in method m9 of the same class: not pooled with the m0 lineage.
    b = stack("unrelated tidy", 9)
    b_side = reviewcap.touched(p, p.db.task(b["id"]), "core.py")
    assert b_side[1] == {"Core.m9"} and not reviewcap.overlaps(a_side, b_side), b_side
    assert len(capped()) == 1, "an edit to another method of the same class was pooled"
    assert reviewcap.area(p, p.config(), p.db.task(b["id"])) is None
    # One failure elsewhere in m0 itself (no shared lines) does join.
    c = stack("another take on m0", 0, line="def")
    assert capped()[-1]["reviews"] == [a1["id"], a2["id"], a3["id"], c["id"]]


def test_a_review_done_with_a_changes_needed_verdict_gates_like_a_failed_review(env):
    """A project whose result rule is `done` plus `metrics.verdict` gets the same fix flow as `failed`,
    and approves nothing; `done` with another verdict, or from a non-review task, stays done."""
    p = make(env)
    from ttp.daemon import review_rejects
    code, _, _, (rev,) = _finish_code(env, p, "feature", {"app.py": 40})
    waiter = p.db.add_task("deploy it", "s", origin="coordinator", depends_on=[rev["id"]])
    fups = [{"title": "add the missing test", "spec": "test_x must fail without the change"}]
    ev = _fail_review(env, p, rev["id"], fups, status="done", metrics={"verdict": "changes_needed"},
                      push=[{"branch": "ttp/x", "head": "a" * 40}])
    assert ev is not None and ev["kind"] == "task_changes_needed" and p.db.task(rev["id"])["status"] == "failed"
    assert json.loads(p.db.task(rev["id"])["result"])["status"] == "changes_needed"
    assert p.db.q("SELECT * FROM events WHERE task=? AND kind='push_queued'", (rev["id"],)) == []
    (fix,) = p.db.q("SELECT * FROM tasks WHERE kind='code' AND origin='daemon'")
    assert "test_x must fail" in fix["spec"] and p.db.task(waiter)["status"] == "queued"
    assert all(review_rejects({"metrics": {"verdict": v}}) for v in ("changes_needed", "Changes-Requested", "rejected"))
    assert not any(review_rejects(r) for r in ({"metrics": {"verdict": "ready"}}, {"metrics": {}}, {},
                                               {"metrics": "changes_needed"}, {"verdict": "changes_needed"}))
    _, _, _, (ok,) = _finish_code(env, p, "other", {"b.py": 5})
    _fail_review(env, p, ok["id"], status="done", summary="fine", metrics={"verdict": "ready"})
    assert p.db.task(ok["id"])["status"] == "done"
    plain = p.db.add_task("not a review", "s", kind="question", origin="coordinator")
    _fail_review(env, p, plain, status="done", summary="answered", metrics={"verdict": "changes_needed"})
    assert p.db.task(plain)["status"] == "done"


def test_the_review_result_rule_is_one_block_that_survives_upgrades(env, tmp_path):
    """A project that rewords kind-review.md's result rule merges template upgrades that edit the
    lines around it without a conflict, and the marker lines fencing it never reach the model."""
    from ttp.prompts import strip_markers, worker_task
    base = (RUNTIME.parent / "template" / "prompts" / "kind-review.md").read_text()
    rule = "- `result.json`: `status` `done` when it may proceed, `failed` when it must not.\n"
    start, end = base.index("<!-- ttp:result-rule"), base.index("<!-- /ttp:result-rule -->")
    assert base[start:end].count("\n") == 2 and base[start:end].endswith(rule), "the block is not just the rule"
    ours = base.replace(rule, "- `result.json`: `status` `done`, with `metrics.verdict` `ready` or `changes_needed`.\n")
    lines = base.splitlines(keepends=True)
    i = next(n for n, line in enumerate(lines) if line.startswith("<!-- ttp:result-rule"))
    lines[i - 1] = lines[i - 1].rstrip("\n") + " (upstream fix)\n"
    lines[i + 3] = lines[i + 3].rstrip("\n") + " (upstream fix)\n"
    for name, text in (("base", base), ("ours", ours), ("theirs", "".join(lines))):
        (tmp_path / name).write_text(text)
    r = subprocess.run(["git", "merge-file", "-p", str(tmp_path / "ours"), str(tmp_path / "base"),
                        str(tmp_path / "theirs")], capture_output=True, text=True)
    assert r.returncode == 0, r.stdout
    assert "`metrics.verdict` `ready`" in r.stdout and r.stdout.count("(upstream fix)") == 2
    assert strip_markers(base) == base.replace(base[start:base.index(rule, start)], "").replace(
        "<!-- /ttp:result-rule -->\n", "")
    assert "`<!-- ttp -->`" in strip_markers(base), "the PR comment marker is not a fence line"
    p = make(env)
    prompt = worker_task(p, p.db.task(p.db.add_task("review it", "s", kind="review", origin="user")), str(p.root), None)
    assert rule.strip() in prompt and "ttp:result-rule" not in prompt


def test_a_failed_review_without_fixes_still_blocks_its_dependents(env):
    p = make(env)
    _, _, _, (rev,) = _finish_code(env, p, "feature", {"app.py": 40})
    waiter = p.db.add_task("deploy it", "s", origin="coordinator", depends_on=[rev["id"]])
    failed = _fail_review(env, p, rev["id"])
    assert p.db.q("SELECT id FROM tasks WHERE origin='daemon' AND kind='code'") == []
    assert failed["status"] == "queued" and "Fix #" not in failed["text"]
    w = p.db.task(waiter)
    assert w["status"] == "blocked" and w["blocked_reason"] == f"dependency #{rev['id']} failed"
    # Fixes for a review of two unrelated branches: no single branch to fix on, so the coordinator decides.
    a, _, _, _ = _finish_code(env, p, "change a", {"a.py": 5})
    b, _, _, _ = _finish_code(env, p, "change b", {"b.py": 5})
    both = p.db.add_task("Review a and b", "Review both.", kind="review", origin="coordinator", depends_on=[a, b])
    waiter2 = p.db.add_task("after both", "s", origin="coordinator", depends_on=[both])
    failed = _fail_review(env, p, both, [{"title": "fix a", "spec": "s"}])
    assert failed["status"] == "queued" and p.db.task(waiter2)["status"] == "blocked"
    assert p.db.q("SELECT id FROM tasks WHERE origin='daemon' AND kind='code'") == []
    # Auto reviews off: the same.
    p.set_config("review.auto", False)
    _, _, _, _ = _finish_code(env, p, "change c", {"c.py": 5})
    c_rev = p.db.add_task("Review c", "Review it.", kind="review", origin="coordinator",
                          depends_on=[p.db.one("SELECT id FROM tasks WHERE title='change c'")["id"]])
    failed = _fail_review(env, p, c_rev, [{"title": "fix c", "spec": "s"}])
    assert failed["status"] == "queued" and p.db.q("SELECT id FROM tasks WHERE origin='daemon' AND kind='code'") == []


def test_a_failed_review_with_only_notes_or_deferred_follow_ups_still_blocks(env):
    """An `upstream:` note or a deferred follow-up is not a fix: no daemon fix, the dependents stay
    blocked and every event stays queued for the coordinator."""
    p = make(env)
    for fup in ({"title": "upstream: the prompt could say X", "spec": "a lesson for tt-project"},
                {"title": "later: retune it", "spec": "s", "start_after": 600},
                {"title": "when ready: rerun it", "spec": "s", "start_when": "test -e done"}):
        _, _, _, (rev,) = _finish_code(env, p, f"feature {fup['title'][:5]}", {"app.py": 40})
        waiter = p.db.add_task("deploy it", "s", origin="coordinator", depends_on=[rev["id"]])
        failed = _fail_review(env, p, rev["id"], [fup])
        assert p.db.q("SELECT id FROM tasks WHERE origin='daemon' AND kind='code'") == [], fup["title"]
        assert failed["status"] == "queued" and "Fix #" not in failed["text"]
        w = p.db.task(waiter)
        assert w["status"] == "blocked" and w["blocked_reason"] == f"dependency #{rev['id']} failed"
        assert [e["status"] for e in p.db.q("SELECT status FROM events WHERE task=? AND kind='followup_proposed'",
                                            (rev["id"],))] == ["queued"]


def test_a_failed_reviews_fix_takes_only_the_real_findings(env):
    p = make(env)
    _, _, _, (rev,) = _finish_code(env, p, "feature", {"app.py": 40})
    waiter = p.db.add_task("deploy it", "s", origin="coordinator", depends_on=[rev["id"]])
    failed = _fail_review(env, p, rev["id"], [
        {"title": "add the missing test", "spec": "test_x must fail without the change"},
        {"title": "upstream: the review prompt could say X", "spec": "a lesson for tt-project"},
        {"title": "retune later", "spec": "after the soak", "start_after": 3600}])
    (fix,) = p.db.q("SELECT * FROM tasks WHERE kind='code' AND origin='daemon'")
    re_rev = p.db.one("SELECT * FROM tasks WHERE kind='review' AND id!=?", (rev["id"],))
    assert "test_x must fail" in fix["spec"] and "a lesson for tt-project" not in fix["spec"]
    assert "after the soak" not in fix["spec"] and "a lesson for tt-project" not in re_rev["spec"]
    assert failed["status"] == "handled" and p.db.task(waiter)["status"] == "queued"
    ev = {e["text"].split(" — ")[0]: e["status"] for e in
          p.db.q("SELECT text, status FROM events WHERE task=? AND kind='followup_proposed'", (rev["id"],))}
    assert ev == {"proposed follow-up: add the missing test": "handled",
                  "proposed follow-up: upstream: the review prompt could say X": "queued",
                  "proposed follow-up: retune later [start_after: 3600]": "queued"}


