def test_global_total_excludes_plan_spend_before_switch(env, tmp_path):
    # The global total counts only billed spend, as the project caps do (billing.billed_by_account):
    # plan account A's $240 before the switch to usage-billed B stays out, B's $15 counts, here and in
    # another project on this machine, and so does B's run still going.
    p = make(env)
    from ttp import globalcap as gcap
    now = time.time()
    start, end = now - 86400, now + 3600
    _plan_then_billed(p, now)
    other = _other_project(tmp_path, "other")
    other.spend("claude", 240.0, "task:1", account="acct-a | plan", ts=now - 10 * 3600)
    other.x("INSERT INTO snapshots(ts,provider,account,window,utilization,resets_at) VALUES(?,?,?,?,?,?)",
            (now - 10 * 3600, "claude", "acct-a | plan", "five_hour", 20.0, now - 5 * 3600))
    other.spend("claude", 6.0, "task:2", account="acct-b | billed", ts=now - 1800)
    _run(p, "acct-b | billed", now - 300, None, 2.5)
    assert round(p.db.spent_since(start), 2) == 255.0, "the plan spend is in the ledger"
    t = gcap.total(p.db, "claude", start, end, now, account="acct-b | billed")
    assert t["usd"] == 23.5 and t["local_projects"] == 2, t
    gcap._LOCAL.clear()
    t = gcap.total(p.db, "claude", start, end, now, account="acct-a | plan")
    assert t["usd"] == 0, t


def _spend_record(host, wins, sent=None):
    """A record as `globalcap.push` sends it: wins is [(start, end, usd on acct-a)]."""
    from ttp import globalcap as gcap
    key = gcap.account_key("claude", "acct-a")
    return (json.dumps({"v": 1, "host": host, "sent": sent or time.time(), "windows": [
        {"start": s, "end": e, "projects": ["far"], "rows": [{"provider": "claude", "key": key, "usd": u}]}
        for s, e, u in wins]}) + "\n").encode()


def test_a_pushed_spend_record_is_checked_and_kept_per_machine_and_window(env, monkeypatch, capsys):
    # A machine this one cannot reach pushes its `spend-today` here. Only a whole, well-formed record
    # within the caps is kept; anything else keeps nothing and exits 2.
    make(env)
    from ttp import cli
    from ttp import globalcap as gcap
    now = time.time()
    day = (now - 3600, now + 3600)
    ack, rc = gcap.receive(_spend_record("laptop", [(*day, 12.5), (now - 2 * 86400, now - 86400, 9.0)]), "lap", now)
    assert rc == 0 and ack == {"accepted": 1, "pulls": False}, ack     # a day already over is dropped
    m = gcap.load_pushed(now)["laptop"]
    assert m["via"] == "lap" and m["ts"] == now and list(m["windows"]) == [gcap._key(*day)], m
    assert m["windows"][gcap._key(*day)]["rows"][0]["usd"] == 12.5
    before = gcap.pushed_path().read_bytes()
    rec = json.loads(_spend_record("laptop", [(*day, 1.0)]))

    w0 = rec["windows"][0]

    def bad(top=None, win=None):
        r = {**rec, **(top or {}), "windows": [{**w0, **(win or {})}]} if "windows" not in (top or {}) else {**rec, **top}
        return (json.dumps(r) + "\n").encode()
    row = w0["rows"][0]
    for stream, via in [(bad(), "not an alias!"), (bad({"host": "testhost"}), "lap"),       # this machine's own
                        (bad({"host": "a b"}), "lap"), (bad({"v": 2}), "lap"),
                        (bad(win={"rows": [{**row, "usd": -1.0}]}), "lap"),
                        (bad(win={"rows": [{**row, "usd": 1e300 * 10}]}), "lap"),            # inf
                        (bad(win={"start": "0"}), "lap"), (bad(win={"end": day[0]}), "lap"),
                        (bad({"windows": [w0] * (gcap.MAX_WINDOWS + 1)}), "lap"),
                        (bad(win={"projects": ["x"] * (gcap.MAX_PROJECTS + 1)}), "lap"),
                        (bad(win={"rows": [{**row, "key": "not-a-key"}]}), "lap"),
                        (b"{not json", "lap"), (b"[" * 60000, "lap"),                   # too deep
                        (b" " * (gcap.RECEIVE_BYTES + 1), "lap")]:
        ack, rc = gcap.receive(stream, via, now)
        assert rc == 2 and "error" in ack, (stream[:80], ack)
    assert gcap.pushed_path().read_bytes() == before
    # A newer push replaces that window's answer; through the command, one JSON ack line.
    monkeypatch.setattr(sys, "stdin", type("S", (), {"buffer": io.BytesIO(_spend_record("laptop", [(*day, 20.0)]))})())
    with pytest.raises(SystemExit) as e:
        cli.main(["spend-today", "--receive", "--via", "lap"])
    assert e.value.code == 0 and json.loads(capsys.readouterr().out)["accepted"] == 1
    assert gcap.load_pushed()["laptop"]["windows"][gcap._key(*day)]["rows"][0]["usd"] == 20.0
    # A machine silent for PUSHED_KEEP_S is forgotten.
    assert gcap.load_pushed(time.time() + gcap.PUSHED_KEEP_S + 1) == {}


def test_a_pushed_number_counts_in_the_global_total_and_goes_stale(env, monkeypatch):
    p = make(env)
    from ttp import globalcap as gcap
    now = time.time()
    start, end = now - 3600, now + 3600
    p.db.spend("claude", 1.0, "task:1", account="acct-a")
    assert gcap.total(p.db, "claude", start, end, now, account="acct-a")["usd"] == 1.0   # nothing pushed: nothing invented
    gcap.receive(_spend_record("laptop", [(start, end, 40.0)]), "lap", now)
    t = gcap.total(p.db, "claude", start, end, now + 60, account="acct-a")
    assert t["usd"] == 41.0 and t["machines"] == ["lap"] and t["stale"] == [] and t["remote_projects"] == 1, t
    # Past STALE_S: a budget day keeps counting the last pushed number, shown stale.
    later = now + gcap.STALE_S + 1
    t = gcap.total(p.db, "claude", start, end, later, account="acct-a")
    assert t["usd"] == 41.0 and t["stale"] == ["lap"] and "(1 stale)" in t["includes"], t
    # The rolling 24 h counts it only while it is fresh, like a pulled answer.
    rs, re_ = now - 86400, now + 86400
    gcap.receive(_spend_record("laptop", [(rs, re_, 7.0)]), "lap", now)
    assert gcap.total(p.db, "claude", rs, re_, now + 60, account="acct-a", rolling=True)["usd"] == 8.0
    t = gcap.total(p.db, "claude", rs, re_, later, account="acct-a", rolling=True)
    assert t["usd"] == 1.0 and t["stale"] == ["lap"], t
    # Another day has no answer from it yet: stale, not counted.
    t = gcap.total(p.db, "claude", end, end + 86400, now + 60, account="acct-a")
    assert t["usd"] == 0 and t["stale"] == ["lap"], t


def test_a_machine_both_asked_and_pushing_counts_once_with_its_freshest_answer(env, monkeypatch):
    p = make(env)
    from ttp import globalcap as gcap
    from ttp.project import register
    now = time.time()
    start, end = now - 3600, now + 3600
    register("far", {"host": "box2", "dir": "/srv/far"})
    key = gcap.account_key("claude", "acct-a")
    monkeypatch.setattr(gcap, "fetch", lambda t, s, e: {"host": "box2", "projects": ["far"],
                                                        "rows": [{"provider": "claude", "key": key, "usd": 50.0}]})
    gcap.refresh(start, end, now)
    gcap.receive(_spend_record("box2", [(start, end, 70.0)]), "b2", now + 60)    # pushed later: newer
    t = gcap.total(p.db, "claude", start, end, now + 120, account="acct-a")
    assert t["usd"] == 70.0 and t["machines"] == ["box2"] and t["stale"] == [], t
    gcap.refresh(start, end, now + gcap.REFRESH_S + 1)                          # asked later: newer
    t = gcap.total(p.db, "claude", start, end, now + gcap.REFRESH_S + 2, account="acct-a")
    assert t["usd"] == 50.0 and t["machines"] == ["box2"], t
    # Never answered over ssh (it cannot be reached), but pushing: matched by its alias, fresh.
    monkeypatch.setattr(gcap, "fetch", lambda *a: (_ for _ in ()).throw(RuntimeError("ssh: no route")))
    gcap.cache_path().unlink()
    gcap.refresh(start, end, now)
    t = gcap.total(p.db, "claude", start, end, now + 120, account="acct-a")
    assert t["usd"] == 70.0 and t["machines"] == ["box2"] and t["stale"] == [], t
    # The receiver tells a pusher it already reads that machine itself.
    gcap.cache_path().unlink()
    monkeypatch.setattr(gcap, "fetch", lambda t, s, e: {"host": "box2", "projects": [], "rows": []})
    gcap.refresh(start, end, now)
    assert gcap.receive(_spend_record("box2", [(start, end, 1.0)]), "b2", now + 1)[0]["pulls"] is True


def _with_sessions(record, usd, account="acct-a", unknown=False):
    """A pushed record (bytes) whose every window carries the sender's other Claude Code sessions."""
    from ttp import globalcap as gcap
    rec = json.loads(record)
    field = None if unknown else {"provider": "claude", "key": gcap.account_key("claude", account), "usd": usd,
                                  "sessions": 2, "estimated": True}
    for w in rec["windows"]:
        w[gcap.SESSIONS] = field
    return (json.dumps(rec) + "\n").encode()


def test_each_machines_other_sessions_count_once_pulled_pushed_or_both(env, monkeypatch):
    # Every machine's answer carries its own other Claude Code sessions beside its projects' spend, so
    # all machines on the account add up the same total. One answer per machine, never pulled + pushed.
    p = make(env)
    from ttp import globalcap as gcap
    from ttp.project import register
    now = time.time()
    start, end = now - 3600, now + 3600
    monkeypatch.setattr(gcap, "OTHER_SOURCES", [lambda *a: (1.0, "other Claude Code sessions on this machine ($1.00)")])
    register("far", {"host": "box2", "dir": "/srv/far"})
    key = gcap.account_key("claude", "acct-a")

    def answer(usd, sessions):
        return {"host": "box2", "projects": ["far"], "rows": [{"provider": "claude", "key": key, "usd": usd}],
                gcap.SESSIONS: {"provider": "claude", "key": key, "usd": sessions, "sessions": 3, "estimated": True}}
    # Pulled only.
    monkeypatch.setattr(gcap, "fetch", lambda t, s, e: answer(50.0, 5.0))
    gcap.refresh(start, end, now)
    t = gcap.total(p.db, "claude", start, end, now + 1, account="acct-a")
    assert t["usd"] == 56.0 and t["remote_sessions_usd"] == 5.0 and t["sessions_missing"] == [], t
    assert "other Claude Code sessions on this machine ($1.00)" in t["includes"]
    assert "other Claude Code sessions on 1 other machine ($5.00, estimated)" in t["includes"], t["includes"]
    # Pushed only, from a machine this one cannot ask.
    assert gcap.receive(_with_sessions(_spend_record("laptop", [(start, end, 10.0)]), 3.0), "lap", now)[1] == 0
    t = gcap.total(p.db, "claude", start, end, now + 2, account="acct-a")
    assert t["usd"] == 69.0 and t["machines"] == ["box2", "lap"], t
    assert "other Claude Code sessions on 2 other machines ($8.00, estimated)" in t["includes"], t["includes"]
    # Both pulled and pushed: one answer, the newer, sessions included; never the two added.
    gcap.receive(_with_sessions(_spend_record("box2", [(start, end, 70.0)]), 7.0), "b2", now + 60)
    t = gcap.total(p.db, "claude", start, end, now + 120, account="acct-a")
    assert t["usd"] == 1 + 77 + 13 and t["machines"] == ["box2", "lap"] and t["remote_sessions_usd"] == 10.0, t
    gcap.refresh(start, end, now + gcap.REFRESH_S + 1)                          # asked later: newer
    t = gcap.total(p.db, "claude", start, end, now + gcap.REFRESH_S + 2, account="acct-a")
    assert t["usd"] == 1 + 55 + 13 and t["remote_sessions_usd"] == 8.0, t
    # Sessions on another account are not this account's spend.
    gcap.receive(_with_sessions(_spend_record("laptop", [(start, end, 10.0)]), 3.0, account="other"), "lap", now + 3)
    t = gcap.total(p.db, "claude", start, end, now + gcap.REFRESH_S + 2, account="acct-a")
    assert t["usd"] == 1 + 55 + 10 and t["remote_sessions_usd"] == 5.0 and t["sessions_missing"] == [], t


def test_this_machines_own_answer_never_counts_again_when_it_comes_back(env, monkeypatch):
    p = make(env)
    from ttp import globalcap as gcap
    now = time.time()
    start, end = now - 3600, now + 3600
    monkeypatch.setattr(gcap, "OTHER_SOURCES", [lambda *a: (1.0, "other Claude Code sessions on this machine ($1.00)")])
    before = gcap.pushed_path().read_bytes() if gcap.pushed_path().exists() else None
    ack, rc = gcap.receive(_with_sessions(_spend_record("testhost", [(start, end, 40.0)]), 9.0), "self", now)
    assert rc == 2 and "error" in ack and (gcap.pushed_path().read_bytes() if gcap.pushed_path().exists() else None) == before
    # Asked under another alias, it answers with this machine's own name: not counted again.
    monkeypatch.setattr(gcap, "targets", lambda: ["loop"])
    key = gcap.account_key("claude", "acct-a")
    monkeypatch.setattr(gcap, "fetch", lambda t, s, e: {
        "host": "testhost", "projects": ["x"], "rows": [{"provider": "claude", "key": key, "usd": 40.0}],
        gcap.SESSIONS: {"provider": "claude", "key": key, "usd": 9.0, "sessions": 1, "estimated": True}})
    gcap.refresh(start, end, now)
    t = gcap.total(p.db, "claude", start, end, now + 1, account="acct-a")
    assert t["usd"] == 1.0 and t["remote_sessions_usd"] == 0 and t["machines"] == [], t


def test_an_answer_without_other_sessions_still_counts_and_says_they_are_missing(env, monkeypatch):
    # An older tt-project sends no other-sessions field: its projects count, its sessions count 0 and
    # the total says so. A sender whose logs are not read yet sends null: the same.
    p = make(env)
    from ttp import globalcap as gcap
    from ttp.project import register
    now = time.time()
    start, end = now - 3600, now + 3600
    monkeypatch.setattr(gcap, "OTHER_SOURCES", [lambda *a: (1.0, "other Claude Code sessions on this machine ($1.00)")])
    register("far", {"host": "box2", "dir": "/srv/far"})
    key = gcap.account_key("claude", "acct-a")
    monkeypatch.setattr(gcap, "fetch", lambda t, s, e: {"host": "box2", "projects": ["far"],
                                                        "rows": [{"provider": "claude", "key": key, "usd": 50.0}]})
    gcap.refresh(start, end, now)
    assert gcap.receive(_spend_record("oldlaptop", [(start, end, 10.0)]), "old", now)[1] == 0
    assert gcap.receive(_with_sessions(_spend_record("newlaptop", [(start, end, 4.0)]), 0, unknown=True), "new", now)[1] == 0
    t = gcap.total(p.db, "claude", start, end, now + 1, account="acct-a")
    assert t["usd"] == 65.0 and t["remote_sessions_usd"] == 0 and t["sessions_missing"] == ["box2", "new", "old"], t
    assert "not other Claude Code sessions on box2, new, old (an older tt-project there" in t["includes"], t["includes"]
    # A malformed field rejects the whole record, pulled or pushed.
    for bad in [{"provider": "claude", "key": key, "usd": -1.0}, {"provider": "claude", "key": "x", "usd": 1.0}, 5]:
        rec = json.loads(_spend_record("laptop", [(start, end, 1.0)]))
        rec["windows"][0][gcap.SESSIONS] = bad
        assert gcap.receive((json.dumps(rec) + "\n").encode(), "lap", now)[1] == 2, bad
        assert not gcap._whole({"host": "box2", "rows": [], gcap.SESSIONS: bad})
    assert gcap._whole({"host": "box2", "rows": []}) and gcap._whole({"host": "box2", "rows": [], gcap.SESSIONS: None})


class _InlineThread:
    """A threading.Thread that runs its target at once, so a background refresh happens in order."""
    def __init__(self, target, daemon):
        self.target = target

    def start(self):
        self.target()

    def is_alive(self):
        return False


def _box2(env, monkeypatch, day_start):
    """A project with the global cap on, one other machine (box2) and a clock the test sets. Returns
    the project, its budget settings, the clock, the times box2 was asked and whether it is up."""
    p = make(env)
    from ttp import globalcap as gcap
    from ttp.project import register
    register("far", {"host": "box2", "dir": "/srv/far"})
    p.set_config("budget.global_daily_usd", 100)
    p.set_config("budget.timezone", "America/New_York")
    p.set_config("budget.day_start", day_start)
    key = gcap.account_key("claude", "acct-a")
    clock, asked, up = [0.0], [], [False]

    def fetch(t, s, e):
        asked.append(clock[0])
        if not up[0]:
            raise RuntimeError("ssh: connect to host box2 port 22: Connection timed out")
        return {"host": "box2", "rows": [{"provider": "claude", "key": key, "usd": 50.0}], "projects": ["far"]}

    monkeypatch.setattr(time, "time", lambda: clock[0])
    monkeypatch.setattr(gcap, "fetch", fetch)
    monkeypatch.setattr(gcap, "account_of", lambda prov: "acct-a")
    monkeypatch.setattr(gcap.threading, "Thread", _InlineThread)
    return p, p.config()["budget"], clock, asked, up


def test_refresh_async_with_no_global_cap_never_uses_ssh(env, monkeypatch):
    # global_daily_usd 0 turns the global cap off: no asking, no pushing.
    make(env)
    from ttp import globalcap as gcap
    from ttp import upstream
    calls = []
    monkeypatch.setattr(upstream, "ssh_pipe", lambda *a, **k: calls.append(a) or (b"", b""))
    monkeypatch.setattr(gcap, "targets", lambda: ["box"])
    monkeypatch.setattr(gcap, "push_targets", lambda: ["box"])
    now = time.time()
    for i in range(5):
        gcap.refresh_async({"global_daily_usd": 0}, now + 3 * i)
    t = gcap._THREAD.get("t")
    if t:
        t.join(5)
    assert calls == []


def test_a_background_refresh_that_fails_waits_a_refresh_before_the_next(env, monkeypatch):
    # The tries of a refresh that cannot save the cache (here a full disk) are on record nowhere, so
    # the background refresh waits REFRESH_S before it asks the machines again.
    import errno
    from ttp import globalcap as gcap
    p, b, clock, asked, up = _box2(env, monkeypatch, "")
    up[0] = True

    def full(*a, **k):
        raise OSError(errno.ENOSPC, "No space left on device")
    monkeypatch.setattr(gcap.project, "write_json", full)
    t0 = 1_800_000_000
    for i in range(400):
        clock[0] = t0 + 3 * i
        gcap.refresh_async(b, clock[0])
    assert asked == [t0, t0 + gcap.REFRESH_S], asked


def test_a_try_stamped_ahead_of_the_clock_holds_nothing_off(env, monkeypatch):
    # After the clock goes back, a machine whose last try is stamped in the future is asked at once
    # and then held off as usual, not left unasked until the clock catches up.
    from ttp import globalcap as gcap
    p, b, clock, asked, up = _box2(env, monkeypatch, "")
    t0 = 1_800_000_000
    clock[0] = t0 + 3600
    gcap.refresh_async(b, clock[0])            # a failed try, then the clock goes back an hour
    asked.clear()
    for i in range(3):
        clock[0] = t0 + 3 * i
        gcap.refresh_async(b, clock[0])
    assert asked == [t0], asked


def test_projects_counting_different_days_keep_their_own_answers_and_ask_once_per_refresh(env, monkeypatch):
    # Projects on one machine may count different global windows (a per-project day_start or
    # timezone, or one rolling). Each keeps its own answer from another machine: they do not make
    # each other ask again on every daemon tick, and each total counts its own window's answer.
    from datetime import datetime, timezone
    p = make(env)
    from ttp import globalcap as gcap
    from ttp.project import register
    register("far", {"host": "box2", "dir": "/srv/far"})
    key = gcap.account_key("claude", "acct-a")
    budgets = [{"global_daily_usd": 100, "day_start": "08:00", "timezone": "America/New_York"},
               {"global_daily_usd": 100, "day_start": "00:00", "timezone": "UTC"},
               {"global_daily_usd": 100, "day_start": ""}]
    t0 = datetime(2026, 3, 4, 14, 0, 1, tzinfo=timezone.utc).timestamp()   # no day starts in the next 20 min
    wins = [gcap.window(b, t0) for b in budgets]
    usd = {gcap._key(s, e): 10.0 ** i for i, (s, e, _) in enumerate(wins)}
    assert len(usd) == 3
    asked = []
    monkeypatch.setattr(gcap, "fetch", lambda t, s, e: asked.append((gcap._key(s, e), s)) or {
        "host": "box2", "rows": [{"provider": "claude", "key": key, "usd": usd[gcap._key(s, e)]}], "projects": ["far"]})

    class Inline:                       # run the background refresh at once, in order
        def __init__(self, target, daemon):
            self.target = target

        def start(self):
            self.target()

        def is_alive(self):
            return False

    monkeypatch.setattr(gcap.threading, "Thread", Inline)
    gcap._LOCAL.clear()
    for i in range(int(2 * gcap.REFRESH_S / 3)):          # 3 s ticks, the projects in turn
        now = t0 + 3 * i
        b = budgets[i % 3]
        gcap.refresh_async(b, now)
        start, end, rolling = gcap.window(b, now)
        t = gcap.total(p.db, "claude", start, end, now, account="acct-a", rolling=rolling)
        assert t["usd"] == usd[gcap._key(start, end)] and t["stale"] == [], (i, b, t)
    per = {k: [s for kk, s in asked if kk == k] for k in usd}
    assert all(len(v) == 2 for v in per.values()), asked     # one per window per REFRESH_S
    m = gcap.load_cache()["machines"]["box2"]
    assert set(m["windows"]) == set(usd), m
    # A past day's answer is dropped at the next refresh: the UTC day is over, the New York one is not.
    gcap.refresh(*wins[0][:2], wins[1][1] + 60, force=True)
    assert set(gcap.load_cache()["machines"]["box2"]["windows"]) == {gcap._key(*wins[0][:2]), "rolling"}


