    rid = p.db.x("INSERT INTO runs(task,role,provider,model,started,status,boot_id,note) "
                 "VALUES(?,'worker','claude','opus',?,'running',?,'{}')", (task["id"], time.time() - 60, d.boot))
    p.db.update_task(task["id"], status="running")
