def test_lock_probe_outside_a_project_answers_for_a_machine_shared_lock(env, tmp_path):
    """No project here (the setup-box bare check run by hand): a lock `ttp machines` shares is
    machine-wide, so it answers; any other has no holder to read: n/a, exit 3, never a failure."""
    from ttp import locks as lk
    from ttp import machines as mm
    from ttp import shared
    e = {k: v for k, v in os.environ.items() if k not in ("TTP_PROJECT", "TTP_RUN_DIR")}
    out = tmp_path / "nowhere"
    out.mkdir()

    def probe(res):
        return subprocess.run([sys.executable, str(TTP), "lock", "--probe", res], cwd=str(out), env=e,
                              capture_output=True, text=True, timeout=30)
    r = probe("box-a-device")
    assert r.returncode == 3 and "n/a" in r.stdout, r.stdout + r.stderr
    mm.add("box-a", tags="device", shared="box-a-device")
    r = probe("box-a-device")
    assert r.returncode == 0 and "free" in r.stdout, r.stdout + r.stderr
    held = lk.try_take(lk.slot_paths(shared.root() / "box-a-device", "box-a-device", 1), "proj task #1")
    r = probe("box-a-device")
    assert r.returncode == 75 and "busy (held by proj task #1" in r.stdout, r.stdout + r.stderr
    held.close()
    shared.update_pause("box-a-device", lambda was: {"reason": "repair", "since": time.time()})
    r = probe("box-a-device")
    assert r.returncode == 75 and "paused (repair)" in r.stdout, r.stdout + r.stderr


def test_lock_wait_messages_name_only_live_holders_with_their_pid(env, tmp_path, monkeypatch):
    """A free slot keeps the JSON label of its last holder: a wait message never names it. A live
    holder shows its pid and whether that pid lives; a pid this process cannot judge (another PID
    namespace) shows bare."""
    from ttp import locks, push, runner
    monkeypatch.setenv("TTP_TEST_POLL_S", "0.05")
    slot = tmp_path / "locks" / "dev.0.lock"
    slot.parent.mkdir()
    slot.write_text(json.dumps({"holder": "task #1 (run 1), whole run", "since": time.time() - 60,
                                "command": "exclusive", "pid": 1, "node": os.uname().nodename}))
    assert locks.holders_now([slot]) == [], "a free slot's old label counted as a holder"
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    env_ = {"TTP_TASK": "5", "TTP_RUN_ID": "7"}

    def wait_line() -> str:
        (run_dir / "progress.md").unlink(missing_ok=True)
        got = runner._take_exclusive(run_dir, [{"resource": "dev", "paths": [str(slot)]}], env_, time.time() + 0.2)
        assert got is None
        return (run_dir / "progress.md").read_text()

    # A shared holder keeps the exclusive take out while the slot still carries the old label.
    sh = locks.try_take_shared([slot], "task #2 (run 3)", "read")
    try:
        line = wait_line()
    finally:
        sh.close()
    assert "task #1" not in line and "task #2 (run 3) (shared) since" in line, line
    assert f"pid {os.getpid()} alive" in line, line
    held = locks.try_take([slot], "task #4 (run 8)", "exclusive")
    try:
        line = wait_line()
        assert "task #1" not in line and "task #4 (run 8) since" in line, line
        assert f"pid {os.getpid()} alive)" in line, line
        said = []
        monkeypatch.setattr(push, "lock_paths", lambda *_a: [slot])
        monkeypatch.setattr(push, "free_probe", lambda _p: "probe")
        assert push.take(None, "origin", "b", 0, say=said.append, who="me") is None
        assert all(f"task #4 (run 8) since" in m and f"pid {os.getpid()} alive" in m for m in said), said
        # A keeper the slot was handed to is named as its holder; one that died shows gone.
        dead = subprocess.Popen(["true"])
        dead.wait()
        locks.label_pid(held, dead.pid)
        assert locks.holders_now([slot])[0].endswith(f"pid {dead.pid} gone"), locks.holders_now([slot])
        monkeypatch.setattr(locks, "_pid_ns", lambda: None)
        assert locks.holders_now([slot])[0].endswith(f"pid {dead.pid}"), locks.holders_now([slot])
    finally:
        held.close()
    assert locks.holders_now([slot]) == [] and locks.holders([slot]), "released: no live holder, label kept"


def _held_build_lock(p, res, holder):
    """`res` (a placeholder build-folder lock of project p) held now by `holder`, from this process."""
    from ttp import locks, shared
    cfg = p.config()
    paths = locks.slot_paths(shared.locks_dir(p, res, cfg), res, shared.slots(p, res, cfg))
    return locks.try_take(paths, holder, "build")


def test_lock_probe_names_the_live_holder_with_its_pid_and_liveness(env):
    p = make(env)
    held = _held_build_lock(p, "build-a", "task #250 (run 725)")
    try:
        r = _ttp_run(p, "lock", "--probe", "build-a")
    finally:
        held.close()
    assert r.returncode == 75, r.stdout + r.stderr
    assert "busy (held by task #250 (run 725) since" in r.stdout and f"pid {os.getpid()} alive" in r.stdout, r.stdout
    r = _ttp_run(p, "lock", "--probe", "build-a")
    assert r.returncode == 0 and "#250" not in r.stdout, r.stdout


def test_lock_probe_wait_note_names_live_holders_not_the_ones_its_hand_off_saw(env):
    """A task waiting on `ttp lock --probe` locks: its note names who holds each lock as its probe last
    ran, with pid and liveness, never the holders its hand-off named once those are done."""
    from ttp import daemon as dmod, locks
    p = make(env)
    old_a, old_b = (p.db.add_task(f"old holder {x}", "s", kind="work", origin="user") for x in "ab")
    probe = "ttp lock --probe build-a && ttp lock --probe build-b"
    tid = _due_waiting_task(p, probe, waiting_for=f"build-a held by #{old_a}, build-b held by #{old_b}")
    assert locks.probe_resources(probe) == ["build-a", "build-b"]
    assert locks.probe_resources("ttp lock --probe build-a && ttp ci --run 5") == []
    for t in (old_a, old_b):
        p.db.update_task(t, status="done")
    held = [_held_build_lock(p, "build-a", "task #900 (run 9)"), _held_build_lock(p, "build-b", "task #901 (run 10)")]
    try:
        d = dmod.Daemon(p.base)
        d.refresh_ref_waits()   # the old holders are done: the note says so, and never names them as holders
        note = p.db.task(tid)["blocked_reason"]
        assert f"held by #{old_a}" not in note and f"held by #{old_b}" not in note, note
        d.probe_waiting()
        d._probes[tid][0].wait(_load_scaled(60))
        d.probe_waiting()
        p.db.update_task(tid, not_before=time.time() - 1)
        d.probe_waiting()       # a fresh "not yet": the note is rebuilt from what the probe saw
        note = p.db.task(tid)["blocked_reason"]
    finally:
        for h in held:
            h.close()
    assert "probe says not yet" in note, note
    assert f"#{old_a}" not in note and f"#{old_b}" not in note, note
    assert "build-a: busy (held by task #900 (run 9) since" in note and f"pid {os.getpid()} alive" in note, note


def _relabel(f, holder):
    """The held slot file `f` relabelled as `holder` with no pid, as a label from before pids reads."""
    f.seek(0)
    f.truncate()
    f.write(json.dumps({"holder": holder, "since": time.time(), "command": "build"}))
    f.flush()


def _run_row(p, task, status="running", pid=None, run_dir=None, boot=None, note=None):
    """A worker run of `task` as the daemon records it: on this boot unless `boot` names another."""
    from ttp import runner
    return p.db.x("INSERT INTO runs(task,role,status,started,pid,dir,boot_id,note) VALUES(?,'worker',?,?,?,?,?,?)",
                  (task, status, time.time(), pid, str(run_dir) if run_dir else None, boot or runner.boot_id(),
                   json.dumps(note or {})))


def test_lock_probe_names_pid_and_liveness_for_every_holder_kind(env):
    """`ttp lock --probe` never names a bare `task #N (run M)`: a label with no pid names its run's worker
    pid, else "pid unknown" and whether the run is active; a keeper of detached jobs names each job's own
    pid and whether it runs; a done task's hold with no live pid is stale."""
    from ttp import hold, locks
    p = make(env)

    def probe():
        r = _ttp_run(p, "lock", "--probe", "build-a")
        assert r.returncode == 75, r.stdout + r.stderr
        return r.stdout.strip()

    t = p.db.add_task("holder", "s", kind="work", origin="user")
    held = _held_build_lock(p, "build-a", "x")
    try:
        run = _run_row(p, t, pid=os.getpid())
        _relabel(held, f"task #{t} (run {run})")
        assert f"held by task #{t} (run {run}) since" in (out := probe()), out
        assert f"pid {os.getpid()} alive (run {run}'s worker)" in out and "stale" not in out, out
        run = _run_row(p, t)
        _relabel(held, f"task #{t} (run {run})")
        assert f"pid unknown (run {run} active)" in (out := probe()) and "stale" not in out, out
        p.db.x("UPDATE runs SET status='ok' WHERE id=?", (run,))
        p.db.update_task(t, status="done")
        assert f"pid unknown (run {run} ended); stale: task #{t} is done" in (out := probe()), out

        # The keeper of a done task's detached jobs: it holds for its jobs, each named with its own pid.
        rd = p.state / "runs" / "keeper-run"
        rd.mkdir(parents=True)
        rc = rd / "job-a.rc"
        (rd / "detached.json").write_text(json.dumps([{"name": "job-a", "rc": str(rc), "pid": 4242}]))
        (rd / hold.RECORD).write_text(json.dumps({"state": "holding", "jobs": [str(rc)]}))
        run = _run_row(p, t, status="ok", run_dir=rd)
        dead = subprocess.Popen(["true"])
        dead.wait()
        job = locks.try_take([locks.job_lock(rc)], "detached job job-a", "sleep")
        try:
            _relabel(held, hold.label(f"task #{t}", run, hold.LABEL))
            locks.label_pid(held, dead.pid)
            out = probe()
            assert f"(run {run}), detached jobs since" in out and f"pid {dead.pid} gone; job job-a pid 4242 running" in out, out
            assert "stale" not in out, out
        finally:
            job.close()
        rc.write_text("0")
        assert f"job job-a pid 4242 ended; stale: task #{t} is done" in (out := probe()), out
    finally:
        held.close()


def test_lock_probe_judges_a_runs_worker_pid_only_on_its_own_boot_and_pid_namespace(env):
    """A run's worker pid recorded on an earlier boot, or seen from another host or PID namespace, may be any
    process here: the probe names it as unknown, never alive, so a done task's hold stays marked stale."""
    from ttp import locks
    p = make(env)
    t = p.db.add_task("holder", "s", kind="work", origin="user")
    p.db.update_task(t, status="done")
    held = _held_build_lock(p, "build-a", "x")
    try:
        for row, why in (({"boot": "an-earlier-boot"}, "recorded on an earlier boot"),
                         ({"note": {"pid_where": {"node": "another-host", "pidns": locks._pid_ns()}}},
                          "seen on another host or PID namespace"),
                         ({"note": {"pid_where": {"node": os.uname().nodename, "pidns": "pid:[0]"}}},
                          "seen on another host or PID namespace")):
            run = _run_row(p, t, status="ok", pid=os.getpid(), **row)
            _relabel(held, f"task #{t} (run {run})")
            out = _ttp_run(p, "lock", "--probe", "build-a").stdout
            assert f"pid {os.getpid()} unknown (run {run}'s worker, {why}); stale: task #{t} is done" in out, out
            assert "alive" not in out, out
        # The same pid on this boot, host and namespace (as the daemon records a run it starts) is judged.
        run = _run_row(p, t, status="ok", pid=os.getpid(),
                       note={"pid_where": {"node": os.uname().nodename, "pidns": locks._pid_ns()}})
        _relabel(held, f"task #{t} (run {run})")
        out = _ttp_run(p, "lock", "--probe", "build-a").stdout
        assert f"pid {os.getpid()} alive (run {run}'s worker)" in out and "stale" not in out, out
    finally:
        held.close()


def test_a_daemon_started_run_records_where_its_worker_pid_means_something(env, monkeypatch):
    from ttp import locks
    from ttp.daemon import Daemon
    p = make(env)
    monkeypatch.setenv("TTP_FAKE_RESULT", json.dumps({"status": "done", "summary": "ok"}))
    tid = p.db.add_task("quick", "s", kind="work", tier="light", origin="user")
    d = Daemon(p.base)
    assert _run_until(d, p, lambda: p.db.one("SELECT id FROM runs WHERE task=?", (tid,)))
    note = json.loads(p.db.one("SELECT note FROM runs WHERE task=?", (tid,))["note"])
    assert note["pid_where"] == {"node": os.uname().nodename, "pidns": locks._pid_ns()}, note


def test_a_lock_probe_error_never_breaks_a_waiting_hand_off(env, monkeypatch):
    """_wait_what runs the lock probe in the daemon: when it raises (an unwritable or corrupt shared lock
    dir), the hand-off still records the task as waiting, its note the hand-off's words and the locks'
    names, and the error is logged once per cause, not on every tick."""
    from ttp import lockprobe
    from ttp.daemon import Daemon
    p = make(env)

    def boom(*a, **k):
        raise OSError(30, "Read-only file system", "slots.json")
    monkeypatch.setattr(lockprobe, "answer", boom)
    monkeypatch.setenv("TTP_FAKE_RESULT", json.dumps(
        {"status": "waiting", "summary": "build dir busy", "waiting_for": "the build folder",
         "retry_after_s": 600, "retry_when": "ttp lock --probe build-a"}))
    tid = p.db.add_task("build it", "s", kind="work", tier="light", origin="user")
    d = Daemon(p.base)
    assert _run_until(d, p, lambda: p.db.task(tid)["status"] == "queued" and p.db.task(tid)["not_before"]
                      and not p.db.q("SELECT id FROM runs WHERE status='running'"))
    t = p.db.task(tid)
    assert t["attempts"] == 0 and json.loads(t["result"])["status"] == "waiting", t
    assert "the build folder; locks: build-a" in (t["blocked_reason"] or ""), t["blocked_reason"]
    for _ in range(3):
        assert d._wait_what(tid, json.loads(t["result"])) == "the build folder; locks: build-a"
    d.refresh_ref_waits()
    assert (p.logs / "daemon.log").read_text().count("lock probe for its wait note failed (OSError") == 1


def test_lock_wait_note_names_the_probes_live_holders_and_agrees_with_the_probe(env):
    """A waiting task's note on lock probes (output redirected or mixed with other commands too) is the
    probe's own answer: the same live holders, never the done task its hand-off named as holder."""
    from ttp import daemon as dmod, locks
    p = make(env)
    assert locks.lock_probe_parts("ttp lock --probe build-a >/dev/null 2>&1 && ttp lock --probe --shared build-b") \
        == ([("build-a", False), ("build-b", True)], [])
    assert locks.lock_probe_parts("ttp lock --probe build-a > /dev/null; test -e /tmp/x") == ([("build-a", False)],
                                                                                               ["test -e /tmp/x"])
    old = p.db.add_task("old holder", "s", kind="work", origin="user")
    p.db.update_task(old, status="done")
    now_t = p.db.add_task("holder now", "s", kind="work", origin="user")
    probe = "ttp lock --probe build-a >/dev/null 2>&1 && ttp lock --probe build-b >/dev/null"
    tid = _due_waiting_task(p, probe, waiting_for=f"build-a held by #{old}, build-b held by task #{old}")
    held = [_held_build_lock(p, "build-a", "x"), _held_build_lock(p, "build-b", "y")]
    try:
        _relabel(held[0], f"task #{now_t} (run {_run_row(p, now_t, pid=os.getpid())})")
        d = dmod.Daemon(p.base)
        d.refresh_ref_waits()
        note = p.db.task(tid)["blocked_reason"]
        said = [_ttp_run(p, "lock", "--probe", r).stdout.strip() for r in ("build-a", "build-b")]
        what = d._wait_what(tid, json.loads(p.db.task(tid)["result"]))
    finally:
        for h in held:
            h.close()
    assert f"#{old}" not in note and f"#{old}" not in what, (note, what)
    assert what == "; ".join(said) and what in note, (what, said, note)
    assert f"task #{now_t} (run" in said[0] and f"pid {os.getpid()} alive" in said[0], said
    assert f"pid {os.getpid()} alive" in said[1], said


def test_status_and_web_show_a_lock_waits_live_holders_not_its_stored_note(env):
    """`ttp status` and the web app's task row build a lock wait's note from the probe's answer when shown:
    the holder now (pid and liveness), or free, never the holder its stored note or hand-off named; a note
    from the hand-off's words becomes the locks now; a wait that names no lock keeps its stored note."""
    from ttp import cli, lockprobe
    from ttp.web import state_payload
    p = make(env)
    old = p.db.add_task("old holder", "s", kind="work", origin="user")
    new = p.db.add_task("holder now", "s", kind="work", origin="user")
    tid = _due_waiting_task(p, "ttp lock --probe build-a >/dev/null", waiting_for=f"build-a held by #{old}")
    hand = _due_waiting_task(p, "ttp lock --probe build-a && ttp lock --probe build-b",
                             waiting_for=f"build-a and build-b held by task #{old}")
    plain = _due_waiting_task(p, "test -e /tmp/never", waiting_for=f"the board task #{old} uses")
    later = time.time() + 3600
    held = _held_build_lock(p, "build-a", "x")
    try:
        _relabel(held, f"task #{old} (run {_run_row(p, old, pid=os.getpid())})")
        stored = f"waiting for {lockprobe.answer(p, p.config(), 'build-a')[1]}; its probe says not yet; next try 20:00"
        assert f"task #{old} (run" in stored, stored
        p.db.update_task(tid, not_before=later, blocked_reason=stored)
        p.db.update_task(hand, not_before=later, blocked_reason=f"waiting for build-a and build-b held by task #{old}; "
                                                                f"locks: build-a, build-b")
        p.db.update_task(plain, not_before=later, blocked_reason=f"waiting for the board task #{old} uses")
        _relabel(held, f"task #{new} (run {_run_row(p, new, pid=os.getpid())})")
        said = _ttp_run(p, "lock", "--probe", "build-a").stdout.strip()
        assert f"task #{new} (run" in said and f"pid {os.getpid()} alive" in said, said

        def shown():
            rows = {t["id"]: t["blocked_reason"] for t in state_payload(p, p.db)["tasks"]}
            out = {ln.split(":", 1)[0].split()[0]: ln for ln in cli.status_text(p).splitlines() if "waiting, next" in ln}
            return rows, out
        rows, out = shown()
        assert rows[tid] == f"waiting for {said}; its probe says not yet; next try 20:00", rows[tid]
        assert said in out[f"#{tid}"] and f"#{old}" not in out[f"#{tid}"], out
        assert rows[hand] == f"waiting for {said}; build-b: free" and said in out[f"#{hand}"], (rows[hand], out)
        assert f"#{old}" not in rows[hand] + out[f"#{hand}"], (rows[hand], out)
        assert rows[plain] == f"waiting for the board task #{old} uses" and f"#{old}" in out[f"#{plain}"], out
    finally:
        held.close()
    rows, out = shown()   # nobody holds it now: free, and the task retries at its next try
    assert rows[tid] == "waiting for build-a: free; its probe says not yet; next try 20:00", rows[tid]
    assert "build-a: free" in out[f"#{tid}"] and "busy" not in out[f"#{tid}"], out
    assert rows[hand] == "waiting for build-a: free; build-b: free", rows[hand]


def test_status_and_web_keep_a_lock_waits_later_non_lock_notes_as_stored(env):
    """Only a lock-wait note is rebuilt from the live holders: a note the daemon wrote later for another
    reason on a task still queued with its lock-probe hand-off (its on_pass_cmd running, a start failure, a
    paused resource, a workspace retry, ...) shows as stored in `ttp status` and the web row, never as a
    made-up "waiting for <lock>: free" that hides the real reason."""
    from ttp import cli
    from ttp.daemon import PAUSED_NOTE, WORKSPACE_RETRY_NOTE
    from ttp.web import state_payload
    p = make(env)
    notes = ["its probe passed; running its on_pass_cmd model-free (up to 10 min)",
             "could not start a run: OSError: disk full",
             f"{PAUSED_NOTE} build-a (maintenance); it starts once resumed",
             WORKSPACE_RETRY_NOTE,
             "interrupted by `ttp stop --kill`; resumes",
             "its resource stayed busy before the run could start; retries",
             "waiting for a standard run: board busy"]
    later = time.time() + 3600
    tids = {}
    for note in notes:
        tid = _due_waiting_task(p, "ttp lock --probe build-a >/dev/null", waiting_for="build-a held by #1")
        p.db.update_task(tid, not_before=later, blocked_reason=note)
        tids[tid] = note
    lock = _due_waiting_task(p, "ttp lock --probe build-a >/dev/null", waiting_for="build-a held by #1")
    p.db.update_task(lock, not_before=later, blocked_reason="waiting for build-a held by #1; next try 20:00")
    rows = {t["id"]: t["blocked_reason"] for t in state_payload(p, p.db)["tasks"]}
    out = {ln.split(":", 1)[0].split()[0]: ln for ln in cli.status_text(p).splitlines() if "waiting, next" in ln}
    for tid, note in tids.items():
        assert rows[tid] == note, (note, rows[tid])
        if f"#{tid}" in out:   # status lists the first few waits
            assert out[f"#{tid}"].endswith(f" — {note}"), (note, out[f"#{tid}"])
    assert {f"#{t}" for t in list(tids)[:3]} <= set(out), out   # on_pass_cmd, start failure, paused resource
    assert rows[lock] == "waiting for build-a: free", rows[lock]
    p.db.update_task(lock, not_before=time.time() + 60)   # first in the listing
    assert "waiting for build-a: free" in cli.status_text(p), cli.status_text(p)


