def test_detach_check_waits_while_running_and_wakes_when_the_job_dies(env):
    p = _device_project(env, device=False)
    run_dir = p.runs / "9"
    run_dir.mkdir(parents=True)
    started = run_dir / "started"
    r = _ttp_run(p, "detach", "long", "--", "sh", "-c", f"touch {started}; sleep 60",
                 env={"TTP_RUN_DIR": str(run_dir)})
    assert r.returncode == 0, r.stderr
    assert _wait_for_path(started)
    rc = run_dir / "long.rc"
    check = _ttp_run(p, "detach", "--check", str(rc))
    assert check.returncode == 1 and "running" in check.stdout
    # Killed (or the host restarted): no .rc is ever written, and the check still ends the wait.
    pid = json.loads((run_dir / "detached.json").read_text())[0]["pid"]
    os.killpg(pid, signal.SIGKILL)
    deadline = time.time() + 20
    while time.time() < deadline and _ttp_run(p, "detach", "--check", str(rc)).returncode == 1:
        time.sleep(0.1)
    check = _ttp_run(p, "detach", "--check", str(rc))
    assert check.returncode == 4 and "gone without an exit code" in check.stdout
    assert not rc.exists()


def _check_until_ended(p, rc, timeout=None):
    deadline = time.time() + (timeout or _load_scaled(60))
    while time.time() < deadline and _ttp_run(p, "detach", "--check", str(rc)).returncode == 1:
        time.sleep(0.1)
    return _ttp_run(p, "detach", "--check", str(rc))


def test_a_detached_job_gone_without_an_exit_code_says_why(env, monkeypatch):
    from ttp import detach, locks
    p = _device_project(env, device=False)
    run_dir = p.runs / "8"
    run_dir.mkdir(parents=True)
    from ttp.runner import boot_id
    jobs = [{"name": n, "rc": str(run_dir / f"{n}.rc"), "log": str(run_dir / f"{n}.log"), "boot": b}
            for n, b in (("never", boot_id()), ("killed", boot_id()), ("reboot", "an-earlier-boot"))]
    (run_dir / "detached.json").write_text(json.dumps(jobs))
    detach.started(run_dir / "killed.rc").write_text("123\n")
    assert detach.state(run_dir / "never.rc") == ("lost", detach.lost(run_dir / "never.rc").read_text().strip())
    assert "never started" in detach.state(run_dir / "never.rc")[1]
    assert "killed after it started" in detach.state(run_dir / "killed.rc")[1]
    assert "same boot: it crashed" in detach.state(run_dir / "killed.rc")[1]
    assert "host restarted" in detach.state(run_dir / "reboot.rc")[1]
    assert "driver died with the host reboot" in detach.state(run_dir / "reboot.rc")[1]
    assert all(locks.job_ended(run_dir / f"{n}.rc") for n in ("never", "killed", "reboot"))
    # A job the daemon did not start in time is recorded as lost, never started late.
    monkeypatch.setenv("TTP_PIDNS", "pid:[1]")
    if not __import__("ttp.push", fromlist=["x"]).pid_ns():
        return
    r = _ttp_run(p, "detach", "late", "--", "true", env={"TTP_RUN_DIR": str(run_dir), "TTP_PIDNS": "pid:[1]"})
    assert r.returncode == 0 and "queued" in r.stdout, r
    q = next((p.state / detach.QUEUE).glob("*.json"))
    m = json.loads(q.read_text())
    m["queued"] -= detach.QUEUED_S + 60
    q.write_text(json.dumps(m))
    detach.tend(p)
    check = _ttp_run(p, "detach", "--check", str(run_dir / "late.rc"))
    assert check.returncode == 4 and "did not start it" in check.stdout, check
    assert not (run_dir / "late.log").exists() and not q.exists()


def _ssh_stub(tmp_path):
    """A local `ssh` on PATH: drops the options and the host and runs the remote command here, or
    fails like an unreachable host (exit 255) while $SSH_STUB_FAIL is set. No real host is used."""
    bin_dir = tmp_path / "sshbin"
    bin_dir.mkdir()
    (bin_dir / "ssh").write_text(
        "#!/bin/sh\n"
        "while [ $# -gt 0 ]; do case $1 in -o) shift 2;; -*) shift;; *) break;; esac; done\n"
        "host=$1; shift\n"
        "echo \"$host\" >>\"$SSH_STUB_LOG\"\n"
        "[ -n \"$SSH_STUB_FAIL\" ] && { echo \"ssh: connect to host $host: Connection refused\" >&2; exit 255; }\n"
        "exec sh -c \"$*\"\n")
    (bin_dir / "ssh").chmod(0o755)
    if not shutil.which("setsid"):   # macOS: the stub's "remote" is this host; a pass-through stands in
        (bin_dir / "setsid").write_text("#!/bin/sh\nexec \"$@\"\n")
        (bin_dir / "setsid").chmod(0o755)
    return {"PATH": f"{bin_dir}{os.pathsep}{os.environ['PATH']}", "SSH_STUB_LOG": str(tmp_path / "ssh.log"),
            "HOME": str(tmp_path / "home")}


def _kill_driver(pid):
    """Stop a stub-remote driver and its job: its whole group when setsid gave it one of its own."""
    try:
        os.killpg(pid, signal.SIGKILL) if os.getpgid(pid) == pid else os.kill(pid, signal.SIGKILL)
    except ProcessLookupError:
        pass


def _remote_probe(out):
    m = re.search(r'retry_when "(.*)"', out)
    assert m, out
    return shlex.split(m.group(1))


def test_detach_remote_runs_the_driver_over_ssh_and_its_check_reports_running_then_the_exit(env, tmp_path):
    p = _device_project(env, device=False)
    run_dir = p.runs / "21"
    run_dir.mkdir(parents=True)
    e = {**_ssh_stub(tmp_path), "TTP_RUN_DIR": str(run_dir)}
    go = tmp_path / "go"
    r = _ttp_run(p, "detach", "--remote", "box-a", "drv", "--", "sh", "-c",
                 f"echo hi; while [ ! -e {go} ]; do sleep 0.1; done; exit 3", env=e)
    assert r.returncode == 0, r.stderr
    remote = tmp_path / "home" / ".ttp-detach" / "21"   # the default folder, under the remote home
    for ext in ("pid", "boot", "start"):
        assert (remote / f"drv.{ext}").exists(), ext
    assert (remote / "drv.start").read_text().split()[0].isdigit()
    probe = _remote_probe(r.stdout)
    assert probe[1:] == ["detach", "--check", "--host", "box-a", "--mirror", str(run_dir.resolve()),
                         str(remote / "drv")], probe
    assert "survives_reboot true" in r.stdout
    check = _ttp_run(p, *probe[1:], env=e)
    assert check.returncode == 1 and "running" in check.stdout, check.stdout
    assert not (run_dir / "detached.json").exists(), "the local job registry holds local jobs only"
    go.touch()
    assert _wait_for_path(remote / "drv.rc")
    check = _ttp_run(p, *probe[1:], env=e)
    assert check.returncode == 4 and "drv: job finished rc=3" in check.stdout, check.stdout
    assert (remote / "drv.log").read_text().strip() == "hi"
    assert set((tmp_path / "ssh.log").read_text().split()) == {"box-a"}
    again = _ttp_run(p, "detach", "--remote", "box-a", "drv", "--", "true", env=e)
    assert again.returncode != 0 and "already ran" in again.stderr + again.stdout


def test_detach_options_after_the_name_count_as_before_it_and_never_join_the_command(env, tmp_path):
    """The reported failure: `ttp detach <name> --devices 1 -- <cmd>` ran `--devices 1 -- <cmd>` as the
    job (exit 127 remotely). The options after the name now count as if they came before it; any other
    option there is refused (exit 2) and starts nothing."""
    p = _device_project(env, device=False)
    run_dir = p.runs / "22"
    run_dir.mkdir(parents=True)
    e = {"TTP_RUN_DIR": str(run_dir)}
    opts = ["--cores", "3", "--devices=1", "--mem-gb", "2.5", "--resumable"]
    before = _ttp_run(p, "detach", *opts, "pre", "--", "sh", "-c", "echo ran", env=e)
    after = _ttp_run(p, "detach", "post", *opts, "--", "sh", "-c", "echo ran", env=e)
    assert before.returncode == 0 and after.returncode == 0, before.stderr + after.stderr
    for name in ("pre", "post"):
        assert _wait_for_path(run_dir / f"{name}.rc")
        assert (run_dir / f"{name}.rc").read_text().strip() == "0"
        assert (run_dir / f"{name}.log").read_text().strip() == "ran"
    jobs = {j["name"]: j for j in json.loads((run_dir / "detached.json").read_text())}
    for k in ("command", "requested", "resumable"):
        assert jobs["pre"][k] == jobs["post"][k], k
    assert jobs["post"]["requested"] == {"cores": 3, "devices": 1, "mem_gb": 2.5}
    assert jobs["post"]["command"] == "sh -c echo ran"
    for bad in (["--frobnicate"], ["--dir", "x"], ["--devices"], ["--cores", "many"]):
        r = _ttp_run(p, "detach", "bad", *bad, "--", "true", env=e)
        assert r.returncode == 2 and bad[0] in r.stderr, (bad, r.stderr)
        assert not any(run_dir.glob("bad.*")), bad
    assert set(jobs) == {j["name"] for j in json.loads((run_dir / "detached.json").read_text())}

    s = {**_ssh_stub(tmp_path), **e}
    remote = tmp_path / "home" / "jobs"
    outs = [_ttp_run(p, "detach", "--remote", "box-a", "--dir", str(remote), "--devices", "1", "rpre", "--",
                     "sh", "-c", "echo ran", env=s),
            _ttp_run(p, "detach", "--remote", "box-a", "rpost", "--dir", str(remote), "--devices", "1", "--",
                     "sh", "-c", "echo ran", env=s)]
    for name, r in zip(("rpre", "rpost"), outs):
        assert r.returncode == 0, r.stderr
        assert _remote_probe(r.stdout)[-1] == str(remote / name)
        assert _wait_for_path(remote / f"{name}.rc")
        assert (remote / f"{name}.rc").read_text().strip() == "0", (remote / f"{name}.log").read_text()
        assert (remote / f"{name}.log").read_text().strip() == "ran"
    calls = (tmp_path / "ssh.log").read_text().split()
    r = _ttp_run(p, "detach", "--remote", "box-a", "rbad", "--frobnicate", "--", "true", env=s)
    assert r.returncode == 2 and "--frobnicate" in r.stderr, r.stderr
    assert (tmp_path / "ssh.log").read_text().split() == calls, "a refused option reaches no host"


def test_detach_remote_check_sees_a_dead_pid_or_a_new_boot_as_gone_and_ssh_failure_as_255(env, tmp_path):
    p = _device_project(env, device=False)
    e = _ssh_stub(tmp_path)
    rdir = tmp_path / "remote"
    r = _ttp_run(p, "detach", "--remote", "box-b", "--dir", str(rdir), "long", "--", "sleep", "60", env=e)
    assert r.returncode == 0, r.stderr
    probe = _remote_probe(r.stdout)
    assert probe[-1] == str(rdir / "long")
    pid = int((rdir / "long.pid").read_text())
    try:
        assert _ttp_run(p, *probe[1:], env=e).returncode == 1
        # ssh failing keeps the task asleep (255), never reads as the driver being gone.
        down = _ttp_run(p, *probe[1:], env={**e, "SSH_STUB_FAIL": "1"})
        assert down.returncode == 255 and "ssh to box-b failed" in down.stdout, down.stdout
        assert _ttp_run(p, "detach", "--remote", "box-b", "--dir", str(rdir), "x", "--", "true",
                        env={**e, "SSH_STUB_FAIL": "1"}).returncode == 255
        # The host restarted: its boot_id changed, so the driver is gone even if a process holds its pid.
        boot = (rdir / "long.boot").read_text()
        assert boot.strip(), "the boot is recorded (boot_id, or kern.boottime without /proc)"
        (rdir / "long.boot").write_text("another-boot\n")
        gone = _ttp_run(p, *probe[1:], env=e)
        assert gone.returncode == 4 and "gone without an exit code (driver died with the host reboot" in gone.stdout, gone.stdout
        (rdir / "long.boot").write_text(boot)
        assert _ttp_run(p, *probe[1:], env=e).returncode == 1
    finally:
        _kill_driver(pid)
    # Killed: no .rc is ever written, and the check still ends the wait with 'gone', not a missing marker.
    deadline = time.time() + 20
    while time.time() < deadline and _ttp_run(p, *probe[1:], env=e).returncode == 1:
        time.sleep(0.1)
    gone = _ttp_run(p, *probe[1:], env=e)
    assert gone.returncode == 4 and "gone without an exit code (the driver crashed or was killed: same boot" in gone.stdout
    assert not (rdir / "long.rc").exists()
    # A pid now taken by another process (its start differs) is gone too.
    (rdir / "long.pid").write_text(f"{os.getpid()}\n")
    assert _ttp_run(p, *probe[1:], env=e).returncode == 4
    # Several jobs on one host: still waiting while any one runs; a path with .rc reads the same.
    r2 = _ttp_run(p, "detach", "--remote", "box-b", "--dir", str(rdir), "two", "--", "sleep", "60", env=e)
    pid2 = int((rdir / "two.pid").read_text())
    try:
        both = _ttp_run(p, "detach", "--check", "--host", "box-b", str(rdir / "long.rc"), str(rdir / "two"), env=e)
        assert both.returncode == 1 and "long: gone" in both.stdout and "two: running" in both.stdout, both.stdout
    finally:
        _kill_driver(pid2)
    assert r2.returncode == 0


def test_detach_check_rows_wakes_on_a_new_row_the_end_or_a_dead_driver(env):
    """`--rows <file> --after <n>`: 1 while the job runs and the file has n lines or fewer; 0 on a new
    row, on the job's end (any exit code, never 4) and on a dead driver (killed, or another boot)."""
    from ttp import locks
    from ttp.runner import boot_id
    p = _device_project(env, device=False)
    run_dir = p.runs / "7"
    run_dir.mkdir(parents=True)
    rows = run_dir / "rows.csv"
    jobs = [{"name": n, "rc": str(run_dir / f"{n}.rc"), "log": str(run_dir / f"{n}.log"), "boot": b}
            for n, b in (("live", boot_id()), ("ended", boot_id()), ("dead", boot_id()), ("reboot", "an-earlier-boot"))]
    (run_dir / "detached.json").write_text(json.dumps(jobs))

    def check(job, after="3"):
        return _ttp_run(p, "detach", "--check", str(run_dir / f"{job}.rc"), "--rows", str(rows), "--after", after)

    lock = locks.try_take([locks.job_lock(run_dir / "live.rc")], "test job")   # the job still runs
    try:
        r = check("live")
        assert r.returncode == 1 and "live: running" in r.stdout and "no file yet" in r.stdout, r.stdout
        rows.write_text("a\nb\nc\n")
        r = check("live")
        assert r.returncode == 1 and "rows: 3 lines" in r.stdout, r.stdout
        rows.write_text("a\nb\nc\nd")   # a new row, its newline not written yet
        r = check("live")
        assert r.returncode == 0 and "rows: 4 lines" in r.stdout, r.stdout
        assert check("live", "4").returncode == 1
    finally:
        lock.close()
    (run_dir / "ended.rc").write_text("3\n")   # ended with a failure: the task wakes to look, not 4
    r = check("ended", "9")
    assert r.returncode == 0 and "job finished rc=3" in r.stdout, r.stdout
    __import__("ttp.detach", fromlist=["x"]).started(run_dir / "dead.rc").write_text("123\n")   # pid gone, no .rc
    r = check("dead", "9")
    assert r.returncode == 0 and "killed after it started" in r.stdout, r.stdout
    r = check("reboot", "9")
    assert r.returncode == 0 and "host restarted" in r.stdout, r.stdout
    bad = _ttp_run(p, "detach", "--check", str(run_dir / "live.rc"), "--after", "3")
    assert bad.returncode != 0 and "--after goes with --rows" in bad.stderr, bad.stderr


def test_detach_remote_check_rows_wakes_on_a_new_row_the_end_or_a_dead_driver(env, tmp_path):
    p = _device_project(env, device=False)
    e = _ssh_stub(tmp_path)
    rdir = tmp_path / "remote"
    r = _ttp_run(p, "detach", "--remote", "box-b", "--dir", str(rdir), "rowjob", "--", "sleep", "60", env=e)
    assert r.returncode == 0, r.stderr
    pid = int((rdir / "rowjob.pid").read_text())
    rows = rdir / "rows.csv"
    probe = ["detach", "--check", "--host", "box-b", "--rows", str(rows), "--after", "2", str(rdir / "rowjob")]
    try:
        r = _ttp_run(p, *probe, env=e)
        assert r.returncode == 1 and "running on box-b" in r.stdout and "no file yet" in r.stdout, r.stdout
        rows.write_text("h\n1\n")
        assert _ttp_run(p, *probe, env=e).returncode == 1
        rows.write_text("h\n1\n2\n")   # a new row
        r = _ttp_run(p, *probe, env=e)
        assert r.returncode == 0 and "rows: 3 lines" in r.stdout and "on box-b" in r.stdout, r.stdout
        rows.write_text("h\n1\n")
        # ssh failing keeps the task asleep (255), never reads as a new row or a dead driver.
        assert _ttp_run(p, *probe, env={**e, "SSH_STUB_FAIL": "1"}).returncode == 255
        # The box power-cycled: another boot id, so the driver is dead though no .rc was written.
        boot = (rdir / "rowjob.boot").read_text()
        (rdir / "rowjob.boot").write_text("another-boot\n")
        r = _ttp_run(p, *probe, env=e)
        assert r.returncode == 0 and "driver died with the host reboot" in r.stdout, r.stdout
        (rdir / "rowjob.boot").write_text(boot)
        assert _ttp_run(p, *probe, env=e).returncode == 1
    finally:
        _kill_driver(pid)
    deadline = time.time() + 20   # killed: its pid is gone and no .rc is ever written
    while time.time() < deadline and _ttp_run(p, *probe, env=e).returncode == 1:
        time.sleep(0.1)
    r = _ttp_run(p, *probe, env=e)
    assert r.returncode == 0 and "gone without an exit code" in r.stdout, r.stdout
    (rdir / "rowjob.rc").write_text("5\n")   # ended with a failure: 0 wakes the task to look, not 4
    r = _ttp_run(p, *probe, env=e)
    assert r.returncode == 0 and "job finished rc=5" in r.stdout, r.stdout


def test_detach_check_rows_never_reads_a_path_with_no_driver_recorded_as_gone(env, tmp_path):
    """A rows file of a run `ttp detach` never started (no .rc, .pid, .boot or entry next to the stem):
    with `--rows` nothing says it ended, so only a new row wakes it, locally and over ssh, and the
    local look leaves no .lost behind. Without `--rows` such a path still reads as gone (4)."""
    p = _device_project(env, device=False)
    series = tmp_path / "series"
    series.mkdir()
    rows = series / "rows.csv"
    rows.write_text("h\n1\n")
    stem = series / "run"
    r = _ttp_run(p, "detach", "--check", f"{stem}.rc", "--rows", str(rows), "--after", "2")
    assert r.returncode == 1 and "no detached job recorded" in r.stdout and "gone" not in r.stdout, r.stdout
    assert not list(series.glob("run.*")), "the check marked a path no job wrote as lost"
    e = _ssh_stub(tmp_path)
    probe = ["detach", "--check", "--host", "box-b", "--rows", str(rows), "--after", "2", f"{stem}.rc"]
    r = _ttp_run(p, *probe, env=e)
    assert r.returncode == 1 and "no driver recorded" in r.stdout and "gone" not in r.stdout, r.stdout
    rows.write_text("h\n1\n2\n")   # a new row wakes both
    assert _ttp_run(p, *probe, env=e).returncode == 0
    assert _ttp_run(p, "detach", "--check", f"{stem}.rc", "--rows", str(rows), "--after", "2").returncode == 0
    (series / "run.rc").write_text("0\n")   # a real end marker wakes it too
    r = _ttp_run(p, *probe[:-3], "5", probe[-1], env=e)
    assert r.returncode == 0 and "job finished rc=0" in r.stdout, r.stdout
    (series / "run.rc").unlink()
    r = _ttp_run(p, "detach", "--check", "--host", "box-b", f"{stem}.rc", env=e)
    assert r.returncode == 4 and "no driver was recorded" in r.stdout, r.stdout


@pytest.mark.parametrize("where", ["local", "host"])
def test_detach_check_reads_a_series_driver_dir_by_its_pid_and_exit(env, tmp_path, where):
    """A series driver's own dir (<dir>/cmd, log, pid, optional EXIT; no .rc, .pid or .boot next to
    it): its pid alive and no EXIT is running (1); a dead pid or an EXIT wakes the check, with
    `--rows` (0) and without (4 for a dead pid or an EXIT with no exit code, else EXIT's code)."""
    p = _device_project(env, device=False)
    d = tmp_path / "series" / "run"
    d.mkdir(parents=True)
    for f in ("cmd", "log"):
        (d / f).write_text("x\n")
    (d / "pid").write_text(f"{os.getpid()}\n")   # this test's own process: alive
    e = _ssh_stub(tmp_path) if where == "host" else None
    host = ["--host", "box-b"] if where == "host" else []
    rows = ["--rows", str(d / "log"), "--after", "5"]
    check = lambda *extra: _ttp_run(p, "detach", "--check", *host, f"{d}.rc", *extra, env=e)
    r = check(*rows)
    assert r.returncode == 1 and "running" in r.stdout and "gone" not in r.stdout, r.stdout
    assert check().returncode == 1
    assert not list(d.parent.glob("run.*")), "the check left a marker next to the series dir"
    dead = subprocess.Popen(["true"])
    dead.wait()
    (d / "pid").write_text(f"{dead.pid}\n")
    r = check(*rows)
    assert r.returncode == 0 and "series driver" in r.stdout and "gone" in r.stdout, r.stdout
    r = check()
    assert r.returncode == 4 and "gone" in r.stdout, r.stdout
    (d / "pid").write_text(f"{os.getpid()}\n")
    (d / "EXIT").write_text("0\n")   # EXIT wins over a live pid
    r = check(*rows)
    assert r.returncode == 0 and "job finished rc=0" in r.stdout, r.stdout
    assert check().returncode == 0
    (d / "EXIT").write_text("3\n")
    r = check()
    assert r.returncode == 4 and "job finished rc=3" in r.stdout, r.stdout
    (d / "EXIT").write_text("")
    r = check()
    assert r.returncode == 4 and "job finished rc=?" in r.stdout, r.stdout
    assert check(*rows).returncode == 0


@pytest.mark.parametrize("where", ["local", "host"])
def test_detach_check_options_after_the_paths_are_options(env, tmp_path, where):
    """`--rows`, `--after` and `--host` given after the first path (or as --opt=value) count as
    options, never as more paths to check."""
