def test_device_timeout_ceiling_clamps_or_refuses_devq_timeouts_and_reaches_the_worker(env, tmp_path):
    p = make(env)
    d = tmp_path / "rq"
    p.set_config("device", {"runners": {"dev": {"dir": str(d), **DEVQ_FAST}}})
    p.set_config("runner.device_timeout_max_s", 600)
    try:
        r = _ttp_run(p, "devq", "submit", "dev", "--id", "t9-long", "--timeout", "2700", "--", "true")
        assert r.returncode != 0 and "above the project's device-job ceiling of 600 s" in r.stderr
        assert not (d / "queue").exists() or not list((d / "queue").iterdir()), "a refused job is not queued"
        r = _ttp_run(p, "devq", "submit", "dev", "--id", "t9-none", "--", "sh", "-c", "echo $TTP_DEVQ_TIMEOUT_S")
        assert r.returncode == 0, r.stderr
        assert "gets the project's device-job ceiling of 600 s" in r.stdout
        m = _devq_marker(d, "t9-none")
        assert m["status"] == "done" and pathlib.Path(m["log"]).read_text().strip() == "600"
        r = _ttp_run(p, "devq", "submit", "dev", "--id", "t9-short", "--timeout", "300", "--",
                     "sh", "-c", "echo $TTP_DEVQ_TIMEOUT_S")
        assert r.returncode == 0 and "ceiling" not in r.stdout, r.stderr
        assert pathlib.Path(_devq_marker(d, "t9-short")["log"]).read_text().strip() == "300"
        # A runner default within the ceiling is kept; one above it is replaced by the ceiling.
        p.set_config("device", {"runners": {"dev": {"dir": str(d), **DEVQ_FAST, "job_timeout_s": 120}}})
        r = _ttp_run(p, "devq", "submit", "dev", "--id", "t9-def", "--", "sh", "-c", "echo $TTP_DEVQ_TIMEOUT_S")
        assert r.returncode == 0 and "ceiling" not in r.stdout, r.stderr
        assert pathlib.Path(_devq_marker(d, "t9-def")["log"]).read_text().strip() == "120"
    finally:
        with contextlib.suppress(OSError, ValueError):
            os.kill(int((d / "runner.pid").read_text()), signal.SIGKILL)
    from ttp.project import config_problems, device_timeout_max
    from ttp.prompts import worker_task
    assert device_timeout_max({}) == (0, None)
    assert device_timeout_max({"runner": {"device_timeout_max_s": 600}}) == (600, None)
    for bad in (0, -5, "600", True):
        n, why = device_timeout_max({"runner": {"device_timeout_max_s": bad}})
        assert n == 0 and "runner.device_timeout_max_s" in why
    assert config_problems({"runner": {"device_timeout_max_s": 600}}) == []
    assert config_problems({"runner": {"device_timeout_max_s": 600},
                            "device": {"runners": {"dev": {"job_timeout_s": 1500}}}}) == [
        "device.runners.dev.job_timeout_s: 1500 is above runner.device_timeout_max_s (600); "
        "jobs without their own --timeout get 600"]
    tid = p.db.add_task("run it", "s", kind="work", tier="light", origin="user")
    head = worker_task(p, p.db.task(tid), str(p.root), None)
    assert "device job timeouts: at most 600 s each" in head and "device runners: dev" in head
    p.set_config("device", {"runners": {}})
    assert "device job timeouts: at most 600 s each" in worker_task(p, p.db.task(tid), str(p.root), None)
    p.set_config("runner.device_timeout_max_s", None)
    assert "device job timeouts" not in worker_task(p, p.db.task(tid), str(p.root), None)


def test_devq_runner_runs_a_job_queued_after_its_settings_read_with_that_submits_settings(env, tmp_path,
                                                                                         monkeypatch):
    from ttp import devq
    d = tmp_path / "rq"
    devq._dirs(d)
    devq._write(d / "config.json", json.dumps(devq.settings({"job_timeout_s": 0})))
    r = devq.Runner(d)
    real_next, seen = r.next_job, []

    def submit_then_dequeue():
        # A submit lands between the loop's settings read and its dequeue: settings first, then the job.
        devq._write(d / "config.json", json.dumps(devq.settings({"job_timeout_s": 120})))
        devq._write(d / "queue" / f"{time.time_ns():020d}-j1.json", json.dumps({"id": "j1", "cmd": "true"}))
        return real_next()

    class Ran(Exception):
        pass

    def run_job(job):
        seen.append((job, r.limit(json.loads((d / "running" / f"{job}.json").read_text()))))
        raise Ran
    monkeypatch.setattr(r, "next_job", submit_then_dequeue)
    monkeypatch.setattr(r, "run_job", run_job)
    monkeypatch.setattr(devq.signal, "signal", lambda *a: None)
    with pytest.raises(Ran):
        r.loop()
    assert seen == [("j1", 120.0)], "the job ran with the settings from before its submit"


class _FakeCaffeinate:
    """Stands in for the caffeinate child: records its argv and whether it was ended and reaped."""
    started: list = []

    def __init__(self, argv, **kw):
        self.argv, self.kw, self.pid = argv, kw, 4242 + len(_FakeCaffeinate.started)
        self.ended = self.reaped = False
        _FakeCaffeinate.started.append(self)

    def poll(self):
        return 0 if self.ended else None

    def terminate(self):
        self.ended = True

    def kill(self):
        self.ended = True

    def wait(self, timeout=None):
        self.reaped = True
        return 0


def _idle_hold(platform="darwin", ac=True, lid=None):
    from ttp import awake
    _FakeCaffeinate.started = []
    power = {"ac": ac, "reads": 0, "lid": lid, "lid_reads": 0}

    def read():
        power["reads"] += 1
        return power["ac"]

    def read_lid():
        power["lid_reads"] += 1
        return power["lid"]
    shown = []
    h = awake.IdleHold(platform=platform, power=read, spawn=_FakeCaffeinate, pid=777, record=shown.append,
                       read_lid=read_lid)
    # forget the cached power and lid readings, as after POWER_EVERY_S
    h._fresh = lambda: (setattr(h, "_ac", None), setattr(h, "_lid", None))
    return h, power, shown


def test_idle_sleep_held_on_ac_with_work_by_caffeinate_i_s_tied_to_the_daemon(env):
    h, _, shown = _idle_hold()
    h.update({}, lambda: True)
    [c] = _FakeCaffeinate.started
    assert c.argv == ["caffeinate", "-i", "-s", "-w", "777"], "idle and system (maintenance) sleep, on AC"
    assert not {"-d", "-u", "-m"} & set(c.argv), "the display may sleep and no user activity is faked"
    assert not {"sudo", "pmset"} & set(c.argv)
    assert c.kw.get("start_new_session") is True
    assert shown == [{"daemon": 777, "held": True, "pid": c.pid, "why": ""}]


@pytest.mark.parametrize("platform,ac,work,cfg,why", [
    ("darwin", False, True, {}, "on battery power"),
    ("darwin", True, False, {}, ""),
    ("darwin", True, True, {"runner": {"prevent_idle_sleep": "off"}}, "off by config (runner.prevent_idle_sleep)"),
    ("darwin", True, True, {"runner": {"prevent_idle_sleep": False}}, "off by config (runner.prevent_idle_sleep)"),
    ("darwin", True, True, {"power": {"keep_awake": "off"}}, "off by config (runner.prevent_idle_sleep)"),
    ("linux", True, True, {}, None),
])
def test_idle_sleep_not_held_on_battery_without_work_config_off_or_off_macos(env, platform, ac, work, cfg, why):
    h, power, shown = _idle_hold(platform, ac)
    checked = []
    h.update(cfg, lambda: checked.append(1) or work)
    assert _FakeCaffeinate.started == []
    if why is None:
        assert shown == [] and checked == [] and power["reads"] == power["lid_reads"] == 0, \
            "nothing is read or spawned off macOS"
    else:
        assert shown == ([{"daemon": 777, "held": False, "pid": None, "why": why}] if why else [])


def test_idle_sleep_released_when_work_ends_or_on_battery_and_never_held_twice(env):
    h, power, shown = _idle_hold()
    for _ in range(5):
        h.update({}, lambda: True)
    assert len(_FakeCaffeinate.started) == 1, "one assertion at a time"
    first = _FakeCaffeinate.started[0]
    assert power["reads"] == 1, "the power source is read at most every POWER_EVERY_S"
    h.update({}, lambda: False)
    assert first.ended and first.reaped and h.proc is None
    assert shown[-1] is None
    h.update({}, lambda: True)
    second = _FakeCaffeinate.started[-1]
    assert len(_FakeCaffeinate.started) == 2 and not second.ended
    power["ac"] = False
    h._fresh()
    h.update({}, lambda: True)
    assert second.ended and second.reaped and h.proc is None
    assert shown[-1]["why"] == "on battery power" and not shown[-1]["held"]
    h.update({"runner": {"prevent_idle_sleep": "on"}}, lambda: True)
    assert len(_FakeCaffeinate.started) == 2
    power["ac"] = True
    h._fresh()
    h.update({}, lambda: True)
    third = _FakeCaffeinate.started[-1]
    third.ended = True   # someone killed it: the next tick holds again
    h.update({}, lambda: True)
    assert len(_FakeCaffeinate.started) == 4 and not _FakeCaffeinate.started[-1].ended
    h.release()
    assert _FakeCaffeinate.started[-1].ended and _FakeCaffeinate.started[-1].reaped and shown[-1] is None


def test_idle_sleep_power_source_unreadable_counts_as_battery(env):
    from ttp import awake
    ac = "Now drawing from 'AC Power'\n -InternalBattery-0 (id=1)\t100%; charged; 0:00 remaining present: true\n"
    batt = "Now drawing from 'Battery Power'\n -InternalBattery-0 (id=1)\t80%; discharging\n"
    ok = lambda out, rc=0: (lambda argv, **kw: subprocess.CompletedProcess(argv, rc, out, ""))
    assert awake.on_ac_power(ok(ac))
    assert not awake.on_ac_power(ok(batt))
    assert not awake.on_ac_power(ok(ac, rc=1))

    def missing(argv, **kw):
        raise FileNotFoundError(2, "No such file or directory")
    assert not awake.on_ac_power(missing)

    def slow(argv, **kw):
        raise subprocess.TimeoutExpired(argv, 10)
    assert not awake.on_ac_power(slow)


def test_lid_read_from_ioreg_and_unreadable_means_no_lid(env):
    from ttp import awake
    seen = []

    def ok(out, rc=0):
        def run(argv, **kw):
            seen.append(argv)
            return subprocess.CompletedProcess(argv, rc, out, "")
        return run
    closed = '  | |   "AppleClamshellState" = Yes\n  | |   "AppleClamshellCausesSleep" = Yes\n'
    clamshell = '  | |   "AppleClamshellState" = Yes\n  | |   "AppleClamshellCausesSleep" = No\n'
    assert awake.lid(ok(closed)) == {"closed": True, "causes_sleep": True}
    assert seen[0][:4] == ["ioreg", "-r", "-k", "AppleClamshellState"], "a read-only ioreg query"
    assert awake.lid(ok(clamshell)) == {"closed": True, "causes_sleep": False}
    assert awake.lid(ok('"AppleClamshellState" = No\n')) == {"closed": False, "causes_sleep": True}
    assert awake.lid(ok('"AppleClamshellState" = Yes\n')) == {"closed": True, "causes_sleep": True}, \
        "no CausesSleep key counts as sleeping"
    assert awake.lid(ok("")) is None, "a desktop Mac has no lid"
    assert awake.lid(ok(closed, rc=1)) is None

    def missing(argv, **kw):
        raise FileNotFoundError(2, "No such file or directory")
    assert awake.lid(missing) is None


