def test_svcscan_flags_every_unit_change_and_no_read_only_query(env):
    from ttp import svcscan
    hits = {n: reason for n, reason, _ in svcscan.scan(SERVICE_SCRIPT)}
    assert sorted(hits) == list(range(3, 14)), hits
    assert all("systemctl changes a unit" in hits[n] for n in (*range(3, 10), 11, 12, 13)), hits
    assert "service changes a unit" in hits[10], hits
    assert "absolute path" in hits[11] and "absolute path" in hits[13] and "over ssh" in hits[12], hits
    assert not any("absolute path" in hits[n] or "ssh" in hits[n] for n in range(3, 11)), hits
    # any verb outside the read-only allowlist is a change, also an unknown or variable one
    for verb in ("stop", "disable", "mask", "start", "restart", "enable", "unmask", "try-restart", "kill",
                 "isolate", "reboot", "poweroff", "halt", "kexec", "suspend", "hibernate", "reload",
                 "daemon-reload", "set-property", "reset-failed", "preset", "reenable", "revert", "link",
                 "edit", "freeze", "thaw", "set-environment", "$verb", "{action}"):
        assert svcscan.scan(f"sudo -n systemctl {verb} x\n"), verb
    for query in (*(f"{v} x" for v in svcscan.READ_ONLY), "-p ActiveState show x", "-qH box status x",
                  "--version", "-h", "--user"):
        assert svcscan.scan(f"sudo -n systemctl {query}\n") == [], query
    # forms that are not one plain shell line: argv lists, a relative path, backslash continuations
    for text in ('subprocess.run(["sudo", "-n", "systemctl", "stop", unit])\n',
                 "run(('systemctl', '--user', 'daemon-reload'))\n", "service x reload\n",
                 'subprocess.run(["service", unit, "reload"])\n', "./systemctl stop x\n",
                 "systemctl -H box stop x\n", "sudo -n systemctl \\\n  --user \\\n  restart x\n"):
        assert [n for n, _, _ in svcscan.scan(text)] == [1], text
    # a comment ending in a backslash does not swallow the next line
    assert [n for n, _, _ in svcscan.scan("# note \\\nsystemctl stop x\n")] == [2]
    assert "relative path" in svcscan.scan("./systemctl stop x\n")[0][1]
    for text in ('subprocess.run(["systemctl", "is-active", unit])\n', 'shutil.which("systemctl")\n',
                 "echo $(systemctl is-active x)\n", "service x status\n", "systemctl \\\n  status x\n"):
        assert svcscan.scan(text) == [], text


def test_ttp_svcscan_exits_1_on_a_hit_and_its_shims_change_no_unit(env, tmp_path):
    script = tmp_path / "driver.sh"
    script.write_text("\n".join(line for line in SERVICE_SCRIPT.splitlines()
                                if not line.startswith(("/usr/bin/", "ssh "))) + "\n")
    clean = tmp_path / "clean.sh"
    clean.write_text("#!/bin/sh\nsystemctl is-active ttp-svcscan-none\n")

    def ttp(*args):
        return subprocess.run([sys.executable, str(TTP), "svcscan", *args], capture_output=True, text=True)
    # The worker prompt has no room for it: --help carries the guidance (and the harness skill reference).
    r = ttp("--help")
    text = " ".join(r.stdout.split())
    for part in ("before running it on a shared machine", "unless your task says to", "`ttp svcscan --shim <dir>`",
                 "`PATH=<dir>:\"$PATH\" <script>`", "a local shim does not stop it"):
        assert part in text, part
    r = ttp(str(script))
    assert r.returncode == 1 and "driver.sh:3: systemctl changes a unit" in r.stdout and \
        "8 service unit change(s)" in r.stdout, r.stdout
    r = ttp(str(clean))
    assert r.returncode == 0 and "no service unit changes" in r.stdout, r.stdout
    assert ttp(str(tmp_path / "missing.sh")).returncode == 2, "unreadable is not a hit"
    shims = tmp_path / "shims"
    r = ttp("--shim", str(shims))
    assert r.returncode == 0 and f"PATH={shims}:" in r.stdout, r.stdout
    # With the shims first on PATH the driver runs to its end and every unit change is only logged;
    # a real systemctl elsewhere on PATH is never reached for a change, but answers a query.
    real = tmp_path / "real"
    real.mkdir()
    (real / "systemctl").write_text(f"#!/bin/sh\necho \"real $*\" >> {tmp_path / 'real.log'}\n")
    (real / "systemctl").chmod(0o755)
    r = subprocess.run(["sh", str(script)], capture_output=True, text=True,
                       env={**os.environ, "PATH": f"{shims}:{real}:{os.environ['PATH']}"})
    assert r.returncode == 0, r.stderr
    log = (shims / "svcscan.log").read_text().splitlines()
    for call in ("sudo -n systemctl stop ttp-svcscan-none.service", "systemctl stop ttp-svcscan-none.service",
                 "systemctl --user disable --now ttp-svcscan-none", "systemctl mask ttp-svcscan-none",
                 "sudo -n -u root systemctl enable ttp-svcscan-none", "systemctl enable ttp-svcscan-none",
                 "service ttp-svcscan-none restart"):
        assert call in log, (call, log)
    assert (tmp_path / "real.log").read_text().splitlines() == [
        "real is-active ttp-svcscan-none", "real status ttp-svcscan-stop-x", "real show -p ActiveState ttp-svcscan-none"]
    # sudo through the shim runs only systemctl/service (through their shims), never another command
    marker = tmp_path / "ran"
    r = subprocess.run(["sudo", "-n", "touch", str(marker)], capture_output=True, text=True,
                       env={**os.environ, "PATH": f"{shims}:{os.environ['PATH']}"})
    assert r.returncode == 0 and not marker.exists() and f"sudo -n touch {marker}" in \
        (shims / "svcscan.log").read_text()
    # a changing verb after an option with a value (`-H <host> stop`) is still only logged
    r = subprocess.run(["systemctl", "-H", "box", "stop", "x"], capture_output=True, text=True,
                       env={**os.environ, "PATH": f"{shims}:{real}"})
    assert r.returncode == 0 and "real -H" not in (tmp_path / "real.log").read_text()
    # only read-only verbs reach the real one: reboot, reload, daemon-reload... are only logged
    for verb in ("reboot", "poweroff", "reload", "daemon-reload", "set-property", "reset-failed", "edit"):
        r = subprocess.run(["sudo", "-n", "systemctl", verb, "x"], capture_output=True, text=True,
                           env={**os.environ, "PATH": f"{shims}:{real}"})
        assert r.returncode == 0 and f"systemctl {verb} x" in (shims / "svcscan.log").read_text(), verb
    assert (tmp_path / "real.log").read_text().splitlines()[3:] == [], "a change reached the real systemctl"
    # the shim folder on PATH as a relative path, with a trailing slash or twice: a query does not
    # re-run a shim, it reaches the real one once and logs one line
    other = tmp_path / "shims2"
    from ttp import svcscan
    svcscan.write_shims(other)
    for path in ("shims", "shims/", f"{shims}/", f"shims:{other}"):
        (shims / "svcscan.log").write_text("")
        (tmp_path / "real.log").write_text("")
        r = subprocess.run(["systemctl", "is-active", "x"], capture_output=True, text=True, timeout=10,
                           cwd=tmp_path, env={**os.environ, "PATH": f"{path}:{real}:/usr/bin:/bin"})
        assert r.returncode == 0, (path, r.stderr)
        assert (shims / "svcscan.log").read_text().splitlines() == ["systemctl is-active x"], path
        assert (tmp_path / "real.log").read_text().splitlines() == ["real is-active x"], path


def test_no_test_resolves_or_starts_a_real_agent_cli(env, tmp_path_factory):
    p = make(env)
    from ttp.daemon import Daemon
    from ttp.providers import get_provider
    fakes = env["tmp"] / "provider-bin"
    for name in ("claude", "codex", "cursor"):
        assert pathlib.Path(get_provider(name).binary()).parent == fakes, name
    d = Daemon(p.base)
    tid = p.db.add_task("t", "s", kind="code", tier="light", origin="user")
    for name in ("claude", "codex", "cursor"):
        rid = d.start_run("worker", "go", name, "light", str(p.root), task=p.db.task(tid))
        (p.runs / str(rid) / "STOP").touch()
        argv = json.loads((p.runs / str(rid) / "run.json").read_text())["argv"]
        assert pathlib.Path(argv[0]).parent == fakes, (name, argv[0])
    # The guards catch a real one, wherever a test would reach it from.
    elsewhere = tmp_path_factory.mktemp("elsewhere")
    real = elsewhere / "claude"
    real.write_text(FAKE_PROVIDER)
    real.chmod(0o755)
    with pytest.raises(AssertionError, match="real agent CLI"):
        subprocess.run([str(real), "--version"], capture_output=True)
    with pytest.raises(AssertionError, match="real agent CLI"):
        subprocess.Popen(["claude"], env={"PATH": str(elsewhere)})
    from ttp.providers import base
    os.environ["PATH"] = f"{elsewhere}{os.pathsep}{os.environ['PATH']}"
    assert base.find_binary("claude") == str(real)
    assert len(env["real_agents"]) == 3 and env["real_agents"][-1] == f"resolved {real}"
    env["real_agents"].clear()   # caught on purpose


def test_work_tasks_get_their_own_worktree_only_when_worktree_kinds_lists_them(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm
    from ttp.project import config_problems
    from ttp.prompts import worker_task
    work = p.db.add_task("tidy notes", "s", kind="work", tier="light", origin="user")
    review = p.db.add_task("review it", "s", kind="review", tier="light", origin="user")
    # The default: only code tasks get a worktree; a work task runs in the project root.
    assert dm.Daemon(p.base)._workdir_for(p.db.task(work)) == (str(p.root), None)
    p.set_config("worktree.kinds", ["work", "review"])
    d = dm.Daemon(p.base)
    cwd, branch = d._workdir_for(p.db.task(work))
    assert cwd == str(p.worktrees / f"t{work}") and branch.startswith(f"ttp/t{work}-"), (cwd, branch)
    assert _git_out(cwd, "rev-parse", "--abbrev-ref", "HEAD") == branch
    assert d._workdir_for(p.db.task(review)) == (str(p.root), None), "a review never gets one"
    prompt = worker_task(p, p.db.task(work), cwd, branch)
    assert f"commit changes to tracked files on {branch}" in prompt
    assert "worktree of your own" not in worker_task(p, p.db.task(work), str(p.root), None)
    # Dispatch puts the run there, with the branch on the task.
    p.db.update_task(review, status="cancelled")
    class Proc:
        pid = 4242
    real = subprocess.Popen
    monkeypatch.setattr(dm.subprocess, "Popen",
                        lambda argv, *a, **k: Proc() if "ttp.runner" in argv else real(argv, *a, **k))
    p.set_config("core_provider", "claude")
    dm.Daemon(p.base).dispatch()
    run = p.db.one("SELECT dir FROM runs WHERE task=?", (work,))
    assert run, p.db.task(work)["blocked_reason"]
    assert json.loads((pathlib.Path(run["dir"]) / "run.json").read_text())["cwd"] == cwd
    assert p.db.task(work)["branch"] == branch
    assert config_problems({"worktree": {"kinds": "work"}}) and config_problems({"worktree": {"kinds": ["review"]}})
    assert not config_problems({"worktree": {"kinds": ["work"]}})


def _root_run(p, d, tid):
    """A worker run of `tid` started through the daemon (its runner not launched), as the reaper sees it."""
    rid = d.start_run("worker", "go", "claude", "light", str(p.root), task=p.db.task(tid))
    return p.db.one("SELECT * FROM runs WHERE id=?", (rid,))


def _end_run(p, d, row):
    run_dir = p.runs / str(row["id"])
    (run_dir / "output.jsonl").write_text("")
    (run_dir / "result.json").write_text(json.dumps({"status": "done", "summary": "did it"}))
    d.finish_run(row, {"rc": 0})


def test_a_run_that_leaves_the_project_root_off_its_branch_or_newly_dirty_alerts_and_clears(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm

    class Proc:
        pid = 4242
    real = subprocess.Popen
    monkeypatch.setattr(dm.subprocess, "Popen",
                        lambda argv, *a, **k: Proc() if "ttp.runner" in argv else real(argv, *a, **k))
    repo = env["repo"]
    base = _git_out(repo, "rev-parse", "--abbrev-ref", "HEAD")
    d = dm.Daemon(p.base)
    alerts = lambda key: p.db.q("SELECT * FROM messages WHERE kind='alert' AND ref=?", (key,))
    resolved = lambda key: p.db.q("SELECT * FROM messages WHERE kind='resolved' AND ref=?", (key,))

    # A run that changes nothing in the root: no alert. One already dirty before it is not its doing.
    (repo / "README.md").write_text("dirty before\n")
    quiet = p.db.add_task("quiet", "s", kind="work", tier="light", origin="user")
    row = _root_run(p, d, quiet)
    assert json.loads(row["note"])["root"]["branch"] == base
    _end_run(p, d, row)
    assert not alerts(f"root-checkout:{quiet}") and not p.db.kv(dm.ROOT_CHECKOUT_KEY)
    _git_out(repo, "checkout", "README.md")

    # A run that switches the root to its own branch, with another task's run alongside.
    other = p.db.add_task("other", "s", kind="work", tier="light", origin="user")
    _root_run(p, d, other)
    racer = p.db.add_task("racer", "s", kind="work", tier="light", origin="user")
    row = _root_run(p, d, racer)
    _git_out(repo, "checkout", "-q", "-b", "my-branch")
    _end_run(p, d, row)
    got = alerts(f"root-checkout:{racer}")
    assert len(got) == 1 and got[0]["severity"] == "low", got
    text = got[0]["text"]
    assert f"#{racer}" in text and "branch my-branch" in text and f"branch {base}" in text and f"#{other}" in text
    assert "Nothing was changed" in text
    assert p.db.one("SELECT 1 FROM events WHERE kind='observation' AND task=? AND text LIKE '%root%'", (racer,))
    assert _git_out(repo, "rev-parse", "--abbrev-ref", "HEAD") == "my-branch", "the checkout is left alone"
    # Not cleared while the root stays off; a recheck does not repeat it.
    d.clear_root_checkout(force=True)
    d.check_root_checkout(row, json.loads(row["note"])["root"])
    assert len(alerts(f"root-checkout:{racer}")) == 1 and not resolved(f"root-checkout:{racer}")
    # A later run that puts the root back is no fault of its own, and the next sweep clears the alert.
    fixer = p.db.add_task("fixer", "s", kind="work", tier="light", origin="user")
    row = _root_run(p, d, fixer)
    _git_out(repo, "checkout", "-q", base)
    _end_run(p, d, row)
    assert not alerts(f"root-checkout:{fixer}")
    d.sweep_alerts()
    assert len(resolved(f"root-checkout:{racer}")) == 1 and not p.db.kv(dm.ROOT_CHECKOUT_KEY)

    # A run that leaves new uncommitted changes to tracked files (untracked files do not count).
    messy = p.db.add_task("messy", "s", kind="work", tier="light", origin="user")
    row = _root_run(p, d, messy)
    (repo / "README.md").write_text("edited in the root\n")
    (repo / "scratch.txt").write_text("untracked\n")
    _end_run(p, d, row)
    got = alerts(f"root-checkout:{messy}")
    assert len(got) == 1 and "README.md" in got[0]["text"] and "scratch.txt" not in got[0]["text"]
    assert "instead of" not in got[0]["text"], "still on its branch"
    # Survives a daemon restart, and clears once the path is clean, looked at every ROOT_RECHECK_S.
    d2 = dm.Daemon(p.base)
    d2.clear_root_checkout(force=True)
    assert not resolved(f"root-checkout:{messy}")
    _git_out(repo, "checkout", "README.md")
    d2.sweep_alerts()
    assert not resolved(f"root-checkout:{messy}"), "checked at most every ROOT_RECHECK_S"
    d2._root_checked = 0.0
    d2.sweep_alerts()
    assert len(resolved(f"root-checkout:{messy}")) == 1 and not p.db.kv(dm.ROOT_CHECKOUT_KEY)
    # A run that moves the root onto the project's base branch is no fault either.
    p.set_config("delivery.base_ref", base)
    d = dm.Daemon(p.base)
    _git_out(repo, "checkout", "-q", "-b", "side")
    homing = p.db.add_task("homing", "s", kind="work", tier="light", origin="user")
    row = _root_run(p, d, homing)
    _git_out(repo, "checkout", "-q", base)
    _end_run(p, d, row)
    assert not alerts(f"root-checkout:{homing}") and not p.db.kv(dm.ROOT_CHECKOUT_KEY)


def test_a_root_run_that_newly_dirties_tracked_paths_is_sent_back_once_before_its_done_counts(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm

    class Proc:
        pid = 4242
    real = subprocess.Popen
    monkeypatch.setattr(dm.subprocess, "Popen",
                        lambda argv, *a, **k: Proc() if "ttp.runner" in argv else real(argv, *a, **k))
    p.set_config("review.auto", False)
    repo = env["repo"]
    d = dm.Daemon(p.base)
    alerts = lambda key: p.db.q("SELECT * FROM messages WHERE kind='alert' AND ref=?", (key,))
    # a) A root run that newly dirties a tracked file and hands off done is woken once with the path.
    t = p.db.add_task("edits in the root", "s", kind="work", tier="light", origin="user")
    row = _root_run(p, d, t)
    (repo / "README.md").write_text("edited in the root\n")
    (repo / "scratch.txt").write_text("untracked\n")
    _end_run(p, d, row)
    task = p.db.task(t)
    res = json.loads(task["result"])
    assert task["status"] == "queued" and int(task["attempts"] or 0) == 0, dict(task)
    assert "README.md" in res["woke"] and "scratch.txt" not in res["woke"] and "commit" in res["woke"], res
    assert res[dm.ROOT_WAKE_KEY]["paths"] == ["README.md"]
    assert not alerts(f"root-checkout:{t}"), "the wake, not the user, deals with it first"
    assert not p.db.one("SELECT 1 FROM events WHERE kind='observation' AND task=?", (t,))
    # b) Its next hand-off with the path still dirty is accepted, with the low alert and no second wake.
    row = _root_run(p, d, t)
    _end_run(p, d, row)
    task = p.db.task(t)
    assert task["status"] == "done", dict(task)
    got = alerts(f"root-checkout:{t}")
    assert len(got) == 1 and got[0]["severity"] == "low" and "README.md" in got[0]["text"], got
    assert dm.ROOT_WAKE_KEY in json.loads(task["result"]), "once per task"
    # Requeued later, it is not woken again for a newly dirtied path either.
    _git_out(repo, "checkout", "README.md")
    p.db.update_task(t, status="queued")
    row = _root_run(p, d, t)
    (repo / "README.md").write_text("again\n")
    _end_run(p, d, row)
    assert p.db.task(t)["status"] == "done"
    _git_out(repo, "checkout", "README.md")
    # A woken run that commits or reverts its edits is accepted with no alert.
    clean = p.db.add_task("cleans up", "s", kind="work", tier="light", origin="user")
    row = _root_run(p, d, clean)
    (repo / "README.md").write_text("edited\n")
    _end_run(p, d, row)
    assert p.db.task(clean)["status"] == "queued"
    row = _root_run(p, d, clean)
    _git_out(repo, "checkout", "README.md")
    _end_run(p, d, row)
    assert p.db.task(clean)["status"] == "done" and not alerts(f"root-checkout:{clean}")


def test_a_root_run_is_not_sent_back_for_paths_dirty_before_it_overlapping_root_runs_or_a_worktree(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm

    class Proc:
        pid = 4242
    real = subprocess.Popen
    monkeypatch.setattr(dm.subprocess, "Popen",
                        lambda argv, *a, **k: Proc() if "ttp.runner" in argv else real(argv, *a, **k))
    p.set_config("review.auto", False)
    repo = env["repo"]
    d = dm.Daemon(p.base)
    alerts = lambda key: p.db.q("SELECT * FROM messages WHERE kind='alert' AND ref=?", (key,))
    # c) A path dirty before the run started: no wake, no alert (not its doing).
    (repo / "README.md").write_text("dirty before\n")
    before = p.db.add_task("before", "s", kind="work", tier="light", origin="user")
    row = _root_run(p, d, before)
    (repo / "README.md").write_text("dirty before, edited again\n")
    _end_run(p, d, row)
    assert p.db.task(before)["status"] == "done" and not alerts(f"root-checkout:{before}")
    assert dm.ROOT_WAKE_KEY not in json.loads(p.db.task(before)["result"])
    _git_out(repo, "checkout", "README.md")
    # d) Two root runs overlapping: whose edit it is is unknown, so no wake; the alert stays as today.
    first = p.db.add_task("first", "s", kind="work", tier="light", origin="user")
    second = p.db.add_task("second", "s", kind="work", tier="light", origin="user")
    a = _root_run(p, d, first)
    b = _root_run(p, d, second)
    (repo / "README.md").write_text("edited by one of them\n")
    _end_run(p, d, b)
    assert p.db.task(second)["status"] == "done"
    got = alerts(f"root-checkout:{second}")
    assert len(got) == 1 and got[0]["severity"] == "low" and "README.md" in got[0]["text"], got
    _end_run(p, d, a)
    assert p.db.task(first)["status"] == "done"
    _git_out(repo, "checkout", "README.md")
    d.clear_root_checkout(force=True)
    # e) A run in its own worktree that dirties the root is unchanged: done, and the alert as today.
    code = p.db.add_task("in a worktree", "s", kind="code", tier="light", origin="user")
    cwd, branch = d._workdir_for(p.db.task(code))
    p.db.update_task(code, status="running", branch=branch)
    w = p.db.one("SELECT * FROM runs WHERE id=?",
                 (d.start_run("worker", "go", "claude", "light", cwd, task=p.db.task(code)),))
    (repo / "README.md").write_text("edited from a worktree run\n")
    _end_run(p, d, w)
    assert p.db.task(code)["status"] != "queued", dict(p.db.task(code))
    assert dm.ROOT_WAKE_KEY not in json.loads(p.db.task(code)["result"])
    assert len(alerts(f"root-checkout:{code}")) == 1


def test_a_review_run_works_in_the_changes_worktree_or_its_own_never_the_project_root(env):
    p = make(env)
    from ttp import daemon as dm
    repo = env["repo"]
    root_head = _git_out(repo, "rev-parse", "HEAD")
    d = dm.Daemon(p.base)
    code = p.db.add_task("the change", "s", kind="code", tier="light", origin="user")
    cwd, branch = d._workdir_for(p.db.task(code))
    p.db.update_task(code, status="done", branch=branch)
    pathlib.Path(cwd, "change.txt").write_text("x\n")
    _git_out(cwd, "add", "change.txt")
    _git_out(cwd, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "the change")
    head = _git_out(cwd, "rev-parse", "HEAD")
    review = p.db.add_task("review it", f"Review {branch}.", kind="review", tier="light", origin="user")
    # The change's worktree, while it is there.
    assert d._workdir_for(p.db.task(review)) == (cwd, None)
    # A push-conflict fix prefers the branch it rebases.
    other = p.db.add_task("another change", "s", kind="code", tier="light", origin="user")
    ocwd, obranch = d._workdir_for(p.db.task(other))
    p.db.update_task(other, status="done", branch=obranch)
    p.db.update_task(review, result=json.dumps({"conflict_fix": {"head": head, "branch": obranch}}))
    assert d._workdir_for(p.db.task(review)) == (ocwd, None)
    p.db.update_task(review, result=None)
    # Once that worktree is gone, a detached one of its own at the reviewed head; reused by its next run.
    _git_out(repo, "worktree", "remove", cwd)
    own = str(p.worktrees / f"t{review}")
    assert d._workdir_for(p.db.task(review)) == (own, None)
    assert _git_out(own, "rev-parse", "HEAD") == head
    assert _git_out(own, "rev-parse", "--abbrev-ref", "HEAD") == "HEAD", "detached"
    _git_out(own, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "--allow-empty", "-m", "a rebase's commit")
    kept = _git_out(own, "rev-parse", "HEAD")
    assert d._workdir_for(p.db.task(review)) == (own, None) and _git_out(own, "rev-parse", "HEAD") == kept
    # A review of nothing this repository holds runs in the root, as before.
    plain = p.db.add_task("review the notes", "s", kind="review", tier="light", origin="user")
    assert d._workdir_for(p.db.task(plain)) == (str(p.root), None)
    assert _git_out(repo, "rev-parse", "HEAD") == root_head and _git_out(repo, "symbolic-ref", "-q", "HEAD")


def test_the_daemon_puts_a_root_a_run_left_detached_back_on_its_branch_and_keeps_its_commits(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm

    class Proc:
        pid = 4242
    real = subprocess.Popen
    monkeypatch.setattr(dm.subprocess, "Popen",
                        lambda argv, *a, **k: Proc() if "ttp.runner" in argv else real(argv, *a, **k))
    repo = env["repo"]
    base = _git_out(repo, "rev-parse", "--abbrev-ref", "HEAD")
    tip = _git_out(repo, "rev-parse", "HEAD")
    d = dm.Daemon(p.base)
    alerts = lambda key: p.db.q("SELECT * FROM messages WHERE kind='alert' AND ref=?", (key,))
    # A run detaches the root and commits there (a rebase run in the wrong place).
    t = p.db.add_task("rebases in the root", "s", kind="review", tier="light", origin="user")
    row = _root_run(p, d, t)
    _git_out(repo, "checkout", "-q", "--detach", tip)
    _git_out(repo, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "--allow-empty", "-m", "made while detached")
    made = _git_out(repo, "rev-parse", "HEAD")
    _end_run(p, d, row)
    assert _git_out(repo, "symbolic-ref", "--short", "HEAD") == base
    assert _git_out(repo, "rev-parse", base) == tip, "the branch is not moved"
    rescue = f"rescue/root-run{row['id']}-{made[:12]}"
    assert _git_out(repo, "rev-parse", rescue) == made, "the detached commits are kept"
    ev = p.db.one("SELECT text FROM events WHERE kind='observation' AND task=? AND text LIKE '%put it back%'", (t,))
    assert ev and rescue in ev["text"] and base in ev["text"]
    assert not alerts(f"root-checkout:{t}") and not p.db.kv(dm.ROOT_CHECKOUT_KEY)
    # Another branch: back on its own, no rescue branch needed (the commits are on that branch).
    t2 = p.db.add_task("switches the root", "s", kind="work", tier="light", origin="user")
    row = _root_run(p, d, t2)
    _git_out(repo, "checkout", "-q", "-b", "elsewhere")
    _end_run(p, d, row)
    assert _git_out(repo, "symbolic-ref", "--short", "HEAD") == base
    assert not _git_out(repo, "branch", "--list", f"rescue/root-run{row['id']}-*")
    # A rebase under way there is left alone: alerted, not touched.
    t3 = p.db.add_task("mid-rebase", "s", kind="work", tier="light", origin="user")
    row = _root_run(p, d, t3)
    _git_out(repo, "checkout", "-q", "--detach", tip)
    busy = pathlib.Path(_git_out(repo, "rev-parse", "--absolute-git-dir")) / "rebase-merge"
    busy.mkdir()
    try:
        _end_run(p, d, row)
        assert _git_out(repo, "rev-parse", "--abbrev-ref", "HEAD") == "HEAD", "left as it is"
        assert len(alerts(f"root-checkout:{t3}")) == 1
    finally:
        busy.rmdir()
        _git_out(repo, "checkout", "-q", base)


def test_one_root_change_seen_by_two_runs_raises_one_alert_naming_the_run_in_the_root(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm

    class Proc:
        pid = 4242
    real = subprocess.Popen
    monkeypatch.setattr(dm.subprocess, "Popen",
                        lambda argv, *a, **k: Proc() if "ttp.runner" in argv else real(argv, *a, **k))
    p.set_config("review.auto", False)
    repo = env["repo"]
    d = dm.Daemon(p.base)
    alerts = lambda: p.db.q("SELECT * FROM messages WHERE kind='alert' AND ref LIKE 'root-checkout:%'")
    observations = lambda: p.db.q("SELECT * FROM events WHERE kind='observation' "
                                  "AND (text LIKE '%root%' OR text LIKE '%main checkout%')")
    # A code task in its own worktree and a work task in the project root run together.
    code = p.db.add_task("in a worktree", "s", kind="code", tier="light", origin="user")
    cwd, branch = d._workdir_for(p.db.task(code))
    p.db.update_task(code, status="running", branch=branch)
    a = p.db.one("SELECT * FROM runs WHERE id=?",
                 (d.start_run("worker", "go", "claude", "light", cwd, task=p.db.task(code)),))
    work = p.db.add_task("in the root", "s", kind="work", tier="light", origin="user")
    b = _root_run(p, d, work)
    (repo / "README.md").write_text("edited in the root\n")
    # The worktree run ends first, then the one in the root: one alert, the root run named as its cause.
    _end_run(p, d, a)
    _end_run(p, d, b)
    got = alerts()
    assert len(got) == 1 and got[0]["ref"] == f"root-checkout:{work}", [g["ref"] for g in got]
    text = got[0]["text"]
    assert f"task #{work} (in the root) worked in the project root" in text and "README.md" in text, text
    assert f"also running then, not in the project root: #{code}" in text, text
    assert len(observations()) == 1, [o["text"] for o in observations()]
    # The same run in the root ending on its own still names itself.
    _git_out(repo, "checkout", "README.md")
    d.clear_root_checkout(force=True)
    assert not p.db.kv(dm.ROOT_CHECKOUT_KEY)
    c = _root_run(p, d, work)
    (repo / "README.md").write_text("again\n")
    _end_run(p, d, c)
    assert f"after run {c['id']} of task #{work} (in the root), which worked in the project root" \
        in alerts()[-1]["text"]


def test_a_work_task_with_its_own_worktree_is_guarded_like_a_code_task(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm, integrity, worktree
    _with_origin(env)
    p.set_config("worktree.kinds", ["work"])
    work = p.db.add_task("work in a worktree", "s", kind="work", tier="light", origin="user")
    path, branch = worktree.ensure(p, p.db.task(work))
    p.db.update_task(work, status="done", branch=branch)
    _commit_file(path, "a")
    in_root = p.db.add_task("work in the root", "s", kind="work", tier="light", origin="user")
    p.db.update_task(in_root, status="done")
    # Its commits on that branch alone are flagged by the local-only check.
    d = _local_only_daemon(p)
    _check_local_only(d)
    assert [e["task"] for e in _local_only_events(p)] == [work]
    assert worktree.own_worktree(p.db.task(work)) and not worktree.own_worktree(p.db.task(in_root))
    review = p.db.add_task("review", "s", kind="review", tier="light", origin="user")
    p.db.update_task(review, branch=f"ttp/t{review}-x")
    assert not worktree.own_worktree(p.db.task(review)), "a review works in the change's worktree"
    # A task that continues it starts from its branch.
    head = _git_out(path, "rev-parse", "HEAD")
    more = p.db.add_task("more", "s", kind="work", tier="light", origin="user", labels=[f"continues:{work}"])
    assert worktree.continued_head(p, p.db.task(more)) == head
    # A done one is lined up for the backup push; an unfinished one's worktree is in the integrity check.
    p.set_config("delivery.backup_remote", "origin")
    d.cfg = p.config()
    p.db.update_task(work, status="running")
    row = p.db.one("SELECT * FROM runs WHERE id=?", (d.start_run("worker", "go", "claude", "light", str(path),
                                                                 task=p.db.task(work)),))
    checked = []
    monkeypatch.setattr(integrity, "check", lambda proj, wts, kept=(): checked.extend(t for t, _ in wts)
                        or {"seconds": 0, "fsck": "ok", "restored": [], "bad": [], "worktrees": [], "clones": []})
    d.check_integrity(start=True)
    assert checked == [work], checked
    _end_run(p, d, row)
    assert p.db.task(work)["status"] == "done"
    assert str(work) in (p.db.kv(dm.KV_BACKUP) or {}), p.db.kv(dm.KV_BACKUP)
    assert not p.db.q("SELECT id FROM tasks WHERE kind='review' AND id!=?", (review,)), "no review for a work task"


def test_a_continued_own_worktree_work_task_starts_from_the_old_branch(env):
    p = make(env)
    from ttp.prompts import worker_task
    p.set_config("worktree.kinds", ["work"])
    old = p.db.add_task("tidy notes", "s", kind="work", tier="light", origin="user")
    p.db.update_task(old, branch=f"ttp/t{old}-tidy-notes", status="done")
    new = p.db.add_task("continue: tidy notes", "s", kind="work", tier="light", origin="user",
                        labels=[f"continues:{old}"])
    prompt = worker_task(p, p.db.task(new), str(p.root), f"ttp/t{old}-tidy-notes")
    assert f"on branch ttp/t{old}-tidy-notes, and starts from that branch's head" in prompt, prompt
    # Code tasks as before.
    oc = p.db.add_task("fix", "s", kind="code", tier="light", origin="user")
    p.db.update_task(oc, branch=f"ttp/t{oc}-fix", status="done")
    nc = p.db.add_task("continue: fix", "s", kind="code", tier="light", origin="user", labels=[f"continues:{oc}"])
    assert f"on branch ttp/t{oc}-fix, and starts from that branch's head" in worker_task(
        p, p.db.task(nc), str(p.root), f"ttp/t{oc}-fix")
    # A work task without a worktree of its own: no branch claim.
    p.set_config("worktree.kinds", [])
    o2 = p.db.add_task("plain", "s", kind="work", tier="light", origin="user")
    p.db.update_task(o2, branch="feature-x", status="done")
    n2 = p.db.add_task("continue: plain", "s", kind="work", tier="light", origin="user", labels=[f"continues:{o2}"])
    assert "on branch feature-x" not in worker_task(p, p.db.task(n2), str(p.root), None)


def test_check_commands_have_first_failure_semantics(env, tmp_path):
    # A multi-command check whose earlier command fails must fail even when the last one passes.
    from ttp import push
    run = lambda c: subprocess.run(push.check_argv(c), cwd=tmp_path).returncode
    assert run("false; true") != 0
    assert run("false | true") != 0
    assert run(f"test -e {tmp_path}/missing\ntrue") != 0
    # Negative controls: passing lists pass, and an explicit `|| true` still opts out.
    assert run("true; true") == 0
    assert run("true | true") == 0
    assert run("false || true") == 0
    # A git error inside a substitution in a test is not caught by -e; assigning first is.
    git = "git -C " + str(tmp_path) + " rev-parse --verify HEAD"
    assert run(f'[ "$({git})" = "" ] && echo skipped') == 0
    assert run(f'head=$({git}) || exit 1; [ "$head" = "" ] && echo skipped') != 0


# A pytest plugin for a child test run: an audit hook logs every write, folder, link or socket bind
# under TTP_TEST_FORBID_ROOT that is not under one of the TTP_TEST_ALLOW_ROOT folders (os.pathsep
# separated) to TTP_TEST_FORBID_LOG. Forked workers inherit the hook.
_FORBID_AUDIT = """
import os, sys
_forbid = os.path.realpath(os.environ["TTP_TEST_FORBID_ROOT"])
_allow = [os.path.realpath(x) for x in os.environ["TTP_TEST_ALLOW_ROOT"].split(os.pathsep) if x]
_log = os.environ["TTP_TEST_FORBID_LOG"]
_WRITE = os.O_WRONLY | os.O_RDWR | os.O_CREAT


def _under(path, root):
    return path == root or path.startswith(root.rstrip(os.sep) + os.sep)


def _hook(event, args):
    if event == "open":
        path, mode, flags = args
        if not (isinstance(flags, int) and flags & _WRITE) and not any(c in str(mode or "") for c in "wax+"):
            return
    elif event in ("os.mkdir", "os.symlink", "os.rename", "socket.bind", "tempfile.mkdtemp", "tempfile.mkstemp"):
        path = args[1] if event in ("os.symlink", "os.rename", "socket.bind") else args[0]
    else:
        return
    if isinstance(path, bytes):
        path = os.fsdecode(path)
    if not isinstance(path, (str, os.PathLike)) or not str(path):
        return
    real = os.path.realpath(path)
    if _under(real, _forbid) and not any(_under(real, a) for a in _allow):
        with open(_log, "a") as f:
            f.write(f"{event} {real}\\n")


sys.addaudithook(_hook)
"""


def _forbid_audit_plugin(where: pathlib.Path) -> pathlib.Path:
    where.mkdir(parents=True, exist_ok=True)
    (where / "ttp_forbid_audit.py").write_text(_FORBID_AUDIT)
    return where


def test_the_forbidden_root_audit_logs_writes_outside_the_allowed_root(tmp_path):
    # Negative control for the audit the isolation regression relies on, with a forbidden root of its
    # own (never /tmp): writes outside the allowed roots are logged, writes inside either are not.
    forbid, log = tmp_path / "forbid", tmp_path / "audit.log"
    allow, allow2 = forbid / "allow", forbid / "checkout"
    allow.mkdir(parents=True)
    allow2.mkdir()
    plugin = _forbid_audit_plugin(tmp_path / "plugin")
    code = ("import ttp_forbid_audit, os, sys, tempfile\n"
            "f, a, b = sys.argv[1:]\n"
            "open(os.path.join(a, 'ok'), 'w').close()\n"
            "tempfile.mkdtemp(dir=a)\n"
            "os.mkdir(os.path.join(b, '__pycache__'))\n"
            "open(os.path.join(f, 'leak'), 'w').close()\n"
            "tempfile.mkdtemp(dir=f, prefix='leakdir')\n"
            "open(os.path.join(f, 'leak')).read()\n")
    env = {**os.environ, "PYTHONPATH": str(plugin), "TTP_TEST_FORBID_ROOT": str(forbid),
           "TTP_TEST_ALLOW_ROOT": os.pathsep.join([str(allow), str(allow2)]), "TTP_TEST_FORBID_LOG": str(log)}
    subprocess.run([sys.executable, "-c", code, str(forbid), str(allow), str(allow2)], env=env, check=True)
    lines = log.read_text().splitlines()
    assert any(x.startswith("open ") and x.endswith("/leak") for x in lines), lines
    assert any(x.startswith("tempfile.mkdtemp ") and "/leakdir" in x for x in lines), lines
    assert not any(str(allow) in x or str(allow2) in x for x in lines), lines
    assert len([x for x in lines if x.startswith("open ")]) == 1, "a read is not a write"


def test_the_socket_probe_survives_a_tmpdir_past_the_unix_socket_path_limit(tmp_path, monkeypatch):
    # Deep enough that an absolute socket path in it is too long for any platform's sun_path.
    deep = tmp_path / ("d" * 60) / ("e" * 60)
    deep.mkdir(parents=True)
    monkeypatch.setattr(tempfile, "tempdir", str(deep))
    with tempfile.TemporaryDirectory() as d, socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM) as s:
        with pytest.raises(OSError):
            s.bind(os.path.join(d, "s"))
    cwd = os.getcwd()
    assert _sockets_refused() is False
    assert os.getcwd() == cwd and not list(deep.iterdir()), "the probe restores the folder and cleans up"


@pytest.mark.parametrize("jobs", [1, 2])
def test_checks_isolate_run_local_tmpdir_from_enclosing_git_and_project(env, tmp_path, monkeypatch, jobs):
    from ttp import cli
    p, _, run, _ = _checks_repo(env, tmp_path, monkeypatch)
    nested_tmp = p.runs / "test-run" / "tmp"
    nested_tmp.mkdir(parents=True)
    assert p.exists() and _git_out(nested_tmp, "rev-parse", "HEAD"), "the temp root has both ancestors"
    monkeypatch.setenv("TTP_TEST_JOBS", str(jobs))
    targets = [f"{__file__}::{name}" for name in (
        "test_status_without_a_name_uses_the_project_of_the_current_folder",
        "test_check_commands_have_first_failure_semantics",
    )]
    p.set_config("delivery.push_checks", [shlex.join([
        sys.executable, "-m", "pytest", "-q", "-p", "ttp_forbid_audit", "-o", "tmp_path_retention_policy=all",
        *targets,
    ])])
    # The child run's TMPDIR is the deep run-local folder itself, with no short alias elsewhere; the
    # audit logs anything the child creates under /tmp outside it.
    audit_log = tmp_path / "forbid-audit.log"
    plugin = _forbid_audit_plugin(tmp_path / "audit-plugin")
    monkeypatch.setenv("PYTHONPATH", os.pathsep.join(filter(None, [str(plugin), os.environ.get("PYTHONPATH")])))
    monkeypatch.setenv("TTP_TEST_FORBID_ROOT", "/tmp")
    # The child pytest's own bytecode and cache in the checkout are not temp files: allow the checkout,
    # so a checkout under /tmp audits exactly what one elsewhere does.
    monkeypatch.setenv("TTP_TEST_ALLOW_ROOT", os.pathsep.join([str(nested_tmp), str(RUNTIME.parents[2])]))
    monkeypatch.setenv("TTP_TEST_FORBID_LOG", str(audit_log))
    monkeypatch.setenv("TTP_TEST_SHORT_TMP_ROOT", str(nested_tmp))   # the child suite's own short-dir folder
    for var in ("TMPDIR", "TMP", "TEMP"):
        monkeypatch.setenv(var, str(nested_tmp))
    cli.main(["checks"])
    record = json.loads((run / "checks.json").read_text())
    assert record["passed"] is True
    assert "2 passed" in (run / "checks.log").read_text()
    assert list(nested_tmp.glob("pytest-of-*/pytest-*")), "pytest kept its files under the run's TMPDIR"
    assert not audit_log.exists(), audit_log.read_text()


