def test_devq_guard_accepts_function_keyword_handlers_and_tilde_netfs_prefixes(tmp_path, monkeypatch):
    from ttp import devq
    # `function name {` (no parens) is a handler too; the old pattern reported its trap missing.
    for defn in ("function stop { kill -- -$pg; }", "function stop() { kill -- -$pg; }", "stop() { kill -- -$pg; }"):
        assert devq._isolation_problem(f"{defn}\nsetsid x & pg=$!\ntrap stop EXIT TERM INT\n") == "", defn
    assert "a trap on EXIT" in devq._isolation_problem(
        "function stop { kill $pid; }\nsetsid x & pid=$!\ntrap stop EXIT TERM INT\n")
    # A '~' prefix (accepted by the config check) matches the expanded path it stands for.
    monkeypatch.setenv("HOME", str(tmp_path))
    resolved, pre = devq.resolve_local(os.path.expanduser("~/net/a"), ["~/net"])
    assert pre == f"{tmp_path}/net" and resolved == f"{tmp_path}/net/a"


# What a stuck task waits on (waits.wait_kind), and plain words for deferred probes -----------------

_BLOCK_REASONS = [
    ("dependency #7 failed", "coordinator", "waits on the coordinator: dependency #7 failed"),
    ("a dependency is not a task id", "coordinator", "waits on the coordinator: a dependency is not a task id"),
    ("task budget exhausted", "budget", "waits on budget: its task budget is used up"),
    ("its $5.00 budget is above the dollar cap", "budget", "waits on budget: its budget is above the dollar cap"),
    ("workspace: worktree add failed", "coordinator", "waits on the coordinator: a workspace fix: worktree add failed"),
    ("lost to a host reboot 3 times; it may be causing them", "coordinator",
     "waits on the coordinator: lost to a host reboot 3 times; it may be causing them"),
    ("push refused: the branch is protected", "coordinator", "waits on the coordinator: push refused: the branch is protected"),
    ("Which of the two layouts should the cache use?", "coordinator",
     "waits on the coordinator: Which of the two layouts should the cache use?"),
]


@pytest.mark.parametrize("reason,kind,text", _BLOCK_REASONS)
def test_status_and_web_say_what_a_blocked_task_waits_on(env, reason, kind, text):
    """Each blocked reason the daemon writes is the project's to move: the task is listed as stuck
    with plain words and an age, never under 'needs you', in `ttp status` and in /api/state."""
    from ttp.cli import status_text
    from ttp.web import state_payload
    p = make(env)
    tid = p.db.add_task("cache layout", "s", origin="user")
    p.db.update_task(tid, status="blocked", blocked_reason=reason)
    w = next(t for t in state_payload(p, p.db)["tasks"] if t["id"] == tid)["wait"]
    assert (w["kind"], w["text"]) == (kind, text) and w["age"] == "0.0h" and w["asks"] == [], w
    out = status_text(p)
    assert "stuck, the project is on it:" in out and f"  #{tid} waiting 0.0h: cache layout — {text}" in out, out
    assert f"needs you (#{tid}" not in out, out


def test_a_task_an_open_ask_names_waits_on_the_user(env):
    from ttp.cli import status_text
    from ttp.web import state_payload
    p = make(env)
    tid = p.db.add_task("pick a vendor", "s", origin="user")
    other = p.db.add_task("other", "s", origin="user")
    p.db.update_task(tid, status="blocked", blocked_reason="needs a vendor choice")
    p.db.update_task(other, status="blocked", blocked_reason="dependency #99 failed")
    # #1 inside #10 or #100 does not count: only the exact id.
    ask = p.db.post("out", f"#{tid}: vendor A or B? (not #{tid}0)", chat=None, kind="ask", severity="high")
    st = state_payload(p, p.db)
    w = next(t for t in st["tasks"] if t["id"] == tid)["wait"]
    assert w["kind"] == "user" and w["text"] == f"waits on you: ask {ask}" and w["asks"] == [ask], w
    assert next(t for t in st["tasks"] if t["id"] == other)["wait"]["kind"] == "coordinator"
    out = status_text(p)
    assert f"  needs you (#{tid}, waiting 0.0h): pick a vendor — waits on you: ask {ask}" in out, out
    assert f"  #{other} waiting 0.0h: other — waits on the coordinator" in out, out
    # Answered, it is the coordinator's again.
    p.db.x("UPDATE messages SET handled=1 WHERE id=?", (ask,))
    assert f"needs you (#{tid}" not in status_text(p)


_UNTIL = 2_000_000_000


@pytest.mark.parametrize("anchor,kind,text", [
    ("ask", "user", None),
    (f"until:{_UNTIL}", "time", "waits until 2033-05-18 03:33 UTC"),   # the project's home zone (UTC in tests)
    ("when:test -f out/landed.marker", "resource", "waits on a check to pass"),
    ("when:landed:#41", "resource", "waits on #41 to land"),
    ("resource:board-a", "resource", "waits on board-a"),
])
def test_status_and_web_read_a_hold_anchor_by_its_kind(env, anchor, kind, text):
    """A coordinator hold (waits:ask/until/when/resource) shows what it waits on, not its free-text
    reason: an ask is the user's even when its text does not name the task, an until its time, a when
    plain words and never the probe."""
    from ttp.cli import status_text
    from ttp.web import state_payload
    p = make(env)
    tid = p.db.add_task("cache layout", "s", origin="user")
    if anchor == "ask":
        ask = p.db.post("out", "vendor A or B?", chat=None, kind="ask", severity="high")
        anchor, text = f"ask:{ask}", f"waits on you: ask {ask}"
    p.db.update_task(tid, status="blocked", blocked_reason="held by the coordinator: some free text",
                     labels=["kept", f"waits:{anchor}"])
    w = next(t for t in state_payload(p, p.db)["tasks"] if t["id"] == tid)["wait"]
    assert (w["kind"], w["text"]) == (kind, text) and w["age"] == "0.0h", w
    assert w["asks"] == ([ask] if kind == "user" else []), w
    assert "free text" not in w["text"] and "test -f" not in w["text"], w
    out = status_text(p)
    if kind == "user":
        assert f"  needs you (#{tid}, waiting 0.0h): cache layout — {text}" in out, out
        assert "stuck, the project is on it:" not in out, out
    else:
        assert f"  #{tid} waiting 0.0h: cache layout — {text}" in out and f"needs you (#{tid}" not in out, out


def _not_yet_note(p, d, tid):
    """The note a due waiting task gets once its probe said not yet (run, reaped, then due again)."""
    _settle_probe(d, tid)
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()
    return p.db.task(tid)["blocked_reason"]


def test_a_wait_on_another_probe_shows_its_latest_line_and_labels_the_workers_note(env):
    """A wait whose probe is not `ttp lock --probe` (a project's own wrapper, a driver check): its note
    leads with the probe's last non-empty line, trimmed and without control characters, and when it was
    read; the hand-off's waiting_for follows as the worker's note from its time, never as the live state."""
    from ttp import daemon as dmod, timefmt, waits, waitheal
    p = make(env)
    probe = "printf 'checking\\n  \\033[31mheld by job 42\\033[0m\\a  \\n\\n'; exit 1"
    tid = _due_waiting_task(p, probe, waiting_for="held by task #5")
    since = json.loads(p.db.task(tid)["result"])["waiting_since"]
    d = dmod.Daemon(p.base)
    note = _not_yet_note(p, d, tid)
    read = timefmt.short(d._probe_live[tid][1], p)
    assert note.startswith(f"waiting for held by job 42 (read {read}); worker's note from "
                           f"{timefmt.short(since, p)}: held by task #5; its probe says not yet; next try "), note
    assert not any(c in note for c in "\x1b\x07"), repr(note)
    assert "probe" not in waits.wait_kind({**p.db.task(tid), "labels": "[]"}, [], time.time())["text"]
    assert waitheal.last_line("x" * 500 + "\n") == "x" * (waitheal.LIVE_CHARS - 1) + "…"
    assert waitheal.last_line("a\x00b\tc\r\n \n") == "a b c"


def test_a_wait_on_another_probe_that_prints_nothing_marks_the_workers_note_as_maybe_stale(env):
    from ttp import daemon as dmod, timefmt
    p = make(env)
    tid = _due_waiting_task(p, "exit 1", waiting_for="held by task #5")
    since = json.loads(p.db.task(tid)["result"])["waiting_since"]
    d = dmod.Daemon(p.base)
    note = _not_yet_note(p, d, tid)
    assert note.startswith(f"waiting for held by task #5 (worker's note from {timefmt.short(since, p)}, may be "
                           f"stale); its probe says not yet; next try "), note


def test_a_wait_on_ttp_lock_probes_keeps_its_live_lock_note(env):
    from ttp import daemon as dmod, lockprobe
    p = make(env)
    tid = _due_waiting_task(p, "ttp lock --probe build-a >/dev/null", waiting_for="build-a held by task #5")
    held = _held_build_lock(p, "build-a", "x")
    try:
        d = dmod.Daemon(p.base)
        note = _not_yet_note(p, d, tid)
        said = lockprobe.answer(p, p.config(), "build-a")[1]
    finally:
        held.close()
    assert note.startswith(f"waiting for {said}; its probe says not yet; next try "), (note, said)
    assert "worker's note" not in note and "task #5" not in note, note


def test_wait_kind_label_wins_and_queued_holds_read_plainly():
    from ttp import waits
    from ttp.daemon import LOGGED_OUT_NOTE, NET_HELD_NOTE, PAUSED_NOTE
    t = {"id": 3, "status": "blocked", "updated": 100.0, "blocked_reason": "dependency #2 failed",
         "labels": json.dumps(["waits:resource:the lab board"])}
    asks = [{"id": 9, "ts": 50.0, "kind": "ask", "text": "about #3"}]
    assert waits.wait_kind(t, asks, now=3700.0)["text"] == "waits on the lab board"
    assert waits.wait_kind({**t, "labels": "[]"}, asks, now=3700.0)["age"] == "1.0h"   # from the ask
    assert waits.wait_kind({**t, "labels": '["waits:review:#12"]'}, [], 100.0)["text"] == "waits on a review: #12"
    assert waits.wait_kind({**t, "labels": '["waits:bogus:x"]'}, [], 100.0)["kind"] == "coordinator"
    assert waits.wait_kind({**t, "status": "review", "labels": "[]"}, [], 100.0)["kind"] == "review"
    for reason, kind in ((f"{PAUSED_NOTE} box: maintenance; it starts once resumed (`ttp resume x --resource box`)",
                          "resource"), (f"{LOGGED_OUT_NOTE} (claude); it starts once a login check passes", "user"),
                         (f"{NET_HELD_NOTE} waiting for claude's API host to resolve", "resource"),
                         ("waiting for the build box; its probe says not yet; next try 10:00", "resource"),
                         ("interrupted by `ttp stop --kill`; resumes", "time")):
        w = waits.wait_kind({**t, "status": "queued", "labels": "[]", "blocked_reason": reason}, [], 100.0)
        assert w["kind"] == kind and "`" not in w["text"] and "probe" not in w["text"], (reason, w)
    assert waits.wait_kind({**t, "status": "queued", "labels": "[]",
                            "blocked_reason": "waiting for the build box; its probe says not yet; next try 10:00"},
                           [], 100.0)["text"] == "waits on the build box"


def test_waiting_on_you_counts_only_blocked_tasks_that_truly_wait_on_the_user(env):
    """'waiting on you' in `ttp status`, the web app and `ttp overview` counts a blocked task only when
    it waits on an open ask, an explicit user mark or a resource the user paused; one that waits on
    the coordinator, a coordinator pause or an answered ask gets a neutral 'held' line instead."""
    from ttp import waits
    from ttp.cli import status_text
    from ttp.db import PAUSED_RESOURCES_KEY
    from ttp.globalcap import connect_ro
    from ttp.overview import _ReadOnly
    from ttp.web import health, state_payload
    p = make(env)
    now = time.time()
    p.db.x("INSERT INTO runs(role,provider,started,status) VALUES('worker','fake',?,'running')", (now,))
    ask = p.db.post("out", "Which layout should the cache use?", kind="ask", severity="high")
    answered = p.db.post("out", "Which board?", kind="ask")
    p.db.x("UPDATE messages SET handled=1 WHERE id=?", (answered,))
    p.db.set_kv(PAUSED_RESOURCES_KEY, {"box": {"reason": "maintenance", "since": now, "by": "user"},
                                       "rig": {"reason": "flaky", "since": now, "by": "coordinator"}})
    tasks = {
        "coordinator": ("workspace: worktree add failed", []),
        "open ask": ("", [f"waits:ask:{ask}"]),
        "user paused": ("", ["waits:resource:box"]),
        "user mark": ("", ["waits:user:a signature"]),
        "coordinator paused": ("", ["waits:resource:rig"]),
        "answered ask": ("", [f"waits:ask:{answered}"]),
        "unknown": ("something odd happened", []),
    }
    ids = {}
    for title, (reason, labels) in tasks.items():
        ids[title] = tid = p.db.add_task(title, "s", origin="user")
        p.db.x("UPDATE tasks SET status='blocked', blocked_reason=?, labels=? WHERE id=?",
               (reason, json.dumps(labels), tid))
    you, stuck = waits.blocked(p.db, now)
    assert {t["title"] for t in you} == {"open ask", "user paused", "user mark"}, [t["wait"] for t in you]
    assert {t["title"]: t["wait"]["kind"] for t in stuck} == {
        "coordinator": "coordinator", "coordinator paused": "resource", "answered ask": "coordinator",
        "unknown": "coordinator"}
    assert waits.held_line(stuck) == "held: 4 blocked task(s) (waiting on the coordinator 3, a resource 1)"
    assert waits.held_line([]) == ""

    h = health(p, p.db, now=now)
    assert h["waiting_on_user"] == 4 and h["held_blocked"] == 4, h   # 3 tasks + the one open ask
    p.db.x("UPDATE runs SET status='done'")
    h = health(p, p.db, now=now)
    assert "waiting on you: 4 (1 ask(s), 3 task(s))" in h["why_idle"], h["why_idle"]
    assert "held: 4 blocked task(s) (waiting on the coordinator 3, a resource 1)" in h["why_idle"], h["why_idle"]
    # The web board's task waits agree with the count.
    st = state_payload(p, p.db)
    board = {t["title"] for t in st["tasks"] if t["wait"] and t["wait"]["kind"] == "user"}
    assert board == {t["title"] for t in you}, board
    assert st["health"]["waiting_on_user"] == h["waiting_on_user"]
    # `ttp status` lists the same tasks under 'needs you', never the coordinator's.
    out = status_text(p)
    for title in ("open ask", "user paused", "user mark"):
        assert f"needs you (#{ids[title]}," in out, out
    for title in ("coordinator", "coordinator paused", "answered ask", "unknown"):
        assert f"needs you (#{ids[title]}," not in out, out
    # `ttp overview` counts through the same classifier over a read-only connection.
    conn = connect_ro(p.db.path)
    try:
        assert waits.on_user(_ReadOnly(conn), now, ages=False)["count"] == 4
    finally:
        conn.close()


def test_waiting_on_you_agrees_for_an_open_ask_and_a_task_gated_on_it(env):
    """One open ask and one task deferred on a start gate the ask names: overview, status and the web
    payload all say 2 waiting on you."""
    from ttp import waits
    from ttp.cli import status_text
    from ttp.globalcap import connect_ro
    from ttp.overview import _ReadOnly
    from ttp.web import health
    p = make(env)
    now = time.time()
    tid = p.db.add_task("needs the key", "s", origin="user")
    p.db.x("UPDATE tasks SET labels=? WHERE id=?", (json.dumps(["start_when:test -e /nonexistent/key"]), tid))
    p.db.post("out", f"Please provide the key that task #{tid} needs.", kind="ask", severity="high")
    assert health(p, p.db, now=now)["waiting_on_user"] == 2
    assert f"needs you (#{tid}, gated on an open ask)" in status_text(p)
    conn = connect_ro(p.db.path)
    try:
        w = waits.on_user(_ReadOnly(conn), now, ages=False)
    finally:
        conn.close()
    assert (w["count"], len(w["asks"]), len(w["gated"])) == (2, 1, 1)


def _hold_task(p, title="hold me"):
    tid = p.db.add_task(title, "spec", kind="work", tier="light", origin="user")
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    return tid


def _setting_ask(p, text="May reviewed work land on main? That needs delivery.allow_protected_push_branch on."):
    p.db.x("INSERT INTO messages(ts,direction,kind,severity,text) VALUES(?,?,?,?,?)",
           (time.time(), "out", "ask", "high", text))
    return p.db.one("SELECT MAX(id) id FROM messages WHERE kind='ask'")["id"]


def _remote_origin(p):
    """A code repo with a remote, so a push branch on it is refused only by the setting."""
    subprocess.run(["git", "-C", str(p.root), "remote", "add", "origin", "https://example.invalid/r.git"], check=True)


def test_setting_hold_reads_landing_specs():
    from ttp.settinghold import lands
    yes = ["land on origin/main with `ttp push`", "Then run ttp push --detach.", "Landing it on the push branch is next"]
    no = ["Never run ttp push.", "publish with `ttp push --own --detach`", "do not land anything",
          "the landed sha is reported", "plain spec"]
    for s in yes:
        assert lands({"kind": "code", "spec": s}), s
    for s in no:
        assert not lands({"kind": "code", "spec": s}), s
    assert not lands({"kind": "review", "spec": yes[0]})


