def test_a_review_with_a_push_step_runs_review_only_while_a_setting_hold_stands(env):
    from ttp import prompts
    p = make(env)
    _remote_origin(p)
    p.set_config("delivery.push_branch", "origin/main")
    review = p.db.add_task("Review #5", "Review it. If it passes, push it with `ttp push`.", kind="review",
                           tier="light", origin="user")
    plain = p.db.add_task("Review #6", "Review it and report.", kind="review", tier="light", origin="user")

    def line(tid):
        text = prompts.worker_task(p, p.db.task(tid), str(p.root), None)
        return "Review only: do not run `ttp push`" in text, text
    assert not line(review)[0]   # no ask open: no hold
    aid = _setting_ask(p)
    has, text = line(review)
    assert has and f"ask #{aid}" in text and "hand off `blocked`" in text and \
        "naming delivery.allow_protected_push_branch" in text, text
    assert not line(plain)[0]
    p.set_config("delivery.allow_protected_push_branch", True)
    assert not line(review)[0]


def test_stale_holds_raise_one_trigger_per_new_set_and_legacy_holds_count(env):
    p = make(env)
    from ttp import anchors
    from ttp import coordinator as coord
    from ttp import unblock
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    now = time.time()
    legacy = _hold_task(p, "legacy hold")
    p.db.update_task(legacy, status="blocked", blocked_reason="until the user confirms")
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (now - 20 * 3600, legacy))
    fresh = _hold_task(p, "fresh hold")
    p.db.update_task(fresh, status="blocked", blocked_reason="needs a look")
    anchored = _hold_task(p, "anchored")
    p.db.update_task(anchored, status="blocked", labels=[f"waits:until:{now + 3600:.0f}"])
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (now - 30 * 3600, anchored))

    def stale_events():
        return p.db.q("SELECT * FROM events WHERE kind=?", (anchors.STALE_EVENT,))
    d.sweep_holds()
    d.sweep_holds()
    evs = stale_events()
    assert len(evs) == 1 and f"#{legacy} legacy hold" in evs[0]["text"] and f"#{fresh} " not in evs[0]["text"]
    assert evs[0]["status"] == "queued"
    labels, _ = coord.effort_triggers(p.db, p.config(), [evs[0]["id"]], None)
    assert anchors.TRIGGER in labels
    # A spec edit does not make the old hold look new.
    assert coord.apply(p, [{"type": "task_update", "id": legacy, "spec": "more detail"}]) == []
    d.sweep_holds()
    assert len(stale_events()) == 1
    # A user message after a hold makes it stale too: a new set, one more trigger.
    p.db.post("in", "the board is back", chat="c1")
    d.sweep_holds()
    d.sweep_holds()
    evs = stale_events()
    assert len(evs) == 2 and f"#{fresh} fresh hold" in evs[1]["text"] and "the user wrote since" in evs[1]["text"]
    # A set that only shrinks raises nothing; the anchored hold never counts.
    p.db.update_task(fresh, status="cancelled")
    d.sweep_holds()
    assert len(stale_events()) == 2 and all(f"#{anchored} " not in e["text"] for e in stale_events())
    line = next(x for x in unblock.lines(p.db) if x.startswith("holds with no anchor"))
    assert line.endswith(f"1: #{legacy} 20.0 h")


def test_a_replayed_free_text_hold_13h_old_with_no_ask_gives_exactly_one_trigger(env):
    p = make(env)
    from ttp import anchors
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    tid = _hold_task(p, "deploy after confirmation")
    # The hold as an older release let the coordinator make it: free text, no ask, no end.
    p.db.update_task(tid, status="blocked", blocked_reason="blocked until the user confirms the deploy")
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (time.time() - 13 * 3600, tid))
    assert not p.db.one("SELECT id FROM messages WHERE kind='ask' AND handled=0")
    d = Daemon(p.base)
    for _ in range(5):
        d.sweep_holds()
    evs = p.db.q("SELECT * FROM events WHERE kind=?", (anchors.STALE_EVENT,))
    assert len(evs) == 1 and f"#{tid} deploy after confirmation (held 13.0h" in evs[0]["text"]
    labels, _ = coord.effort_triggers(p.db, p.config(), [e["id"] for e in evs], None)
    assert labels.count(anchors.TRIGGER) == 1
    assert "anchored" not in labels
    Daemon(p.base).sweep_holds()   # a restarted daemon does not raise it again
    assert len(p.db.q("SELECT id FROM events WHERE kind=?", (anchors.STALE_EVENT,))) == 1


def test_live_check_judges_codex_steer_by_the_hook_its_run_got(env, monkeypatch, tmp_path):
    # Codex has no fixed steer_hook: a build with hooks on gets ttp.hook per run, so the steer check
    # passes or fails on what the run did; without hooks it stays unsupported.
    from ttp import live
    worker, _, _ = _codex_hooks(monkeypatch, tmp_path)
    prov, argv = worker()
    assert not getattr(prov, "steer_hook", False) and live.hook_used(argv)
    st = lambda **kw: live.judge(prov, _live_ev(**kw))["steer"][0]
    assert st(hook_used=True) == "pass" and st(hook_used=True, steer_delivered=False) == "fail"
    assert st(hook_used=False) == "unsupported"
    off, _, _ = _codex_hooks(monkeypatch, tmp_path, features="hooks  stable  false\n")
    assert not live.hook_used(off()[1])


def test_command_watcher_output_is_parsed_per_line():
    from ttp import daemon
    out = daemon._observations('starting\n{"text": "a down", "severity": "high"}\n{bad json\n'
                               '{"text": "b ok"}\ntail one\ntail two\n')
    assert out == [{"text": "starting"}, {"text": "a down", "severity": "high"}, {"text": "{bad json"},
                   {"text": "b ok"}, {"text": "tail one\ntail two"}]
    assert daemon._observations("just\nplain") == [{"text": "just\nplain"}]
    assert daemon._observations("") == []


def test_normalize_masks_compound_and_decimal_durations():
    from ttp import screen
    for a, b in [("up 18h52m", "up 3h07m"), ("in 1d2h", "in 4d11h"), ("took 3m20s", "took 1m5s"),
                 ("1.5h ago", "0.25h ago"), ("wait 250ms", "wait 12ms")]:
        assert screen.normalize(a) == screen.normalize(b), a
    assert screen.normalize("host03 t48 gpu1") == "host03 t48 gpu1"


def _fake_ttp(tmp_path, rc, out):
    """A `ttp` on an absolute path that prints `out` and exits `rc` (a devq probe's verdict)."""
    b = tmp_path / "fakebin"
    b.mkdir(exist_ok=True)
    (b / "ttp").write_text(f"#!/bin/sh\necho '{out}'\nexit {rc}\n")
    (b / "ttp").chmod(0o755)
    return str(b / "ttp")


def _reprobe(d, tid):
    """Run its probe again ahead of its timer (as every PROBE_EVERY_S)."""
    d._probed.pop(tid, None)
    d.p.db.update_task(tid, not_before=time.time() + 900)
    _settle_probe(d, tid)


def test_a_devq_probe_finding_its_runner_down_restarts_it_model_free_and_the_task_sleeps_on(env, tmp_path):
    from ttp import waitheal
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    d.cfg.setdefault("device", {})["runner_restarts_per_day"] = 2
    calls = []
    d._devq_start = lambda runner: (calls.append(runner), (0, "started runner"))[1]
    probe = f"{_fake_ttp(tmp_path, 3, 'r1-1: queued, but no runner is alive (runner down)')} devq probe r1 r1-1"
    tid = _due_waiting_task(p, probe)
    _settle_probe(d, tid)
    assert calls == ["r1"] and not _ready(p, tid), "restarted, and the task sleeps on (exit 3 is not yet)"
    ev = p.db.q("SELECT * FROM events WHERE kind='devq_runner_restarted'")
    assert len(ev) == 1 and ev[0]["status"] == "handled" and ev[0]["task"] == tid
    assert not p.db.q("SELECT id FROM runs"), "no model run"
    _reprobe(d, tid)
    assert calls == ["r1"], "at most once per 10 min per runner"
    st = p.db.kv(waitheal.RUNNER_RESTARTS_KEY)
    p.db.set_kv(waitheal.RUNNER_RESTARTS_KEY, {"r1": {**st["r1"], "last": time.time() - 601}})
    _reprobe(d, tid)
    assert calls == ["r1", "r1"]
    st = p.db.kv(waitheal.RUNNER_RESTARTS_KEY)
    p.db.set_kv(waitheal.RUNNER_RESTARTS_KEY, {"r1": {**st["r1"], "last": time.time() - 601}})
    _reprobe(d, tid)
    assert calls == ["r1", "r1"], "the day's cap"
    fix = p.db.q("SELECT * FROM tasks WHERE kind='harness' AND title LIKE 'Fix device runner r1:%'")
    assert len(fix) == 1 and "2 restarts today" in fix[0]["title"]
    assert p.db.one("SELECT COUNT(*) n FROM messages WHERE ref='devq_runner:r1' AND severity='low'")["n"] == 1
    _reprobe(d, tid)
    assert len(p.db.q("SELECT id FROM tasks WHERE kind='harness'")) == 1 and not _ready(p, tid)


def test_a_runner_restart_failing_twice_posts_one_low_line_and_queues_one_fix_task(env, tmp_path):
    from ttp import waitheal
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    d._devq_start = lambda runner: (1, "health gate failed")
    tid = _due_waiting_task(p, f"{_fake_ttp(tmp_path, 3, 'no runner is alive')} devq probe r2 r2-1")
    for i in range(3):
        if i:
            st = p.db.kv(waitheal.RUNNER_RESTARTS_KEY)
            p.db.set_kv(waitheal.RUNNER_RESTARTS_KEY, {"r2": {**st["r2"], "last": time.time() - 601}})
        _reprobe(d, tid)
        lines = p.db.one("SELECT COUNT(*) n FROM messages WHERE ref='devq_runner:r2'")["n"]
        assert lines == (0 if i == 0 else 1), i
    fix = p.db.q("SELECT * FROM tasks WHERE kind='harness'")
    assert len(fix) == 1 and "health gate failed" in fix[0]["spec"] and f"#{tid}" in fix[0]["spec"]
    assert not _ready(p, tid)


def test_an_outside_user_probe_stays_not_yet_and_restarts_nothing(env, tmp_path):
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    calls = []
    d._devq_start = lambda runner: (calls.append(runner), (0, ""))[1]
    tid = _due_waiting_task(p, f"{_fake_ttp(tmp_path, 1, 'an outside device user still runs')} devq probe r3 r3-1")
    _settle_probe(d, tid)
    assert not calls and not _ready(p, tid)
    # Exit 3 from any other probe is not a runner down: the probe is broken and wakes its task.
    tid2 = _due_waiting_task(p, f"{_fake_ttp(tmp_path, 3, 'x')} devq probe r3 r3-1 && true")
    _settle_probe(d, tid2)
    assert not calls and d._probe_rc[tid2][0] == 3


def _never(p, tid):
    return p.db.q("SELECT * FROM events WHERE kind='probe_never_passes' AND task=?", (tid,))


def test_a_probe_that_exits_0_wakes_its_task_and_is_never_flagged(env, tmp_path):
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    # devq's own probe exits 0 for a job unknown to its runner: the task wakes, with no extra event.
    unknown = _due_waiting_task(p, f"{_fake_ttp(tmp_path, 0, 'j: unknown to the runner in /x')} devq probe r j")
    _settle_probe(d, unknown)
    assert _ready(p, unknown) and not _never(p, unknown)
    # The same for any probe that passes, even one naming a run dir that is gone.
    gone = _due_waiting_task(p, f"test -e {p.runs}/99999/done || test -d .")
    _settle_probe(d, gone)
    assert _ready(p, gone) and not _never(p, gone)


def test_wait_stale_shows_the_gate_and_flags_same_output_while_a_named_task_has_ended(env):
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    other = p.db.add_task("build", "s", kind="work", tier="light", origin="user")
    p.db.update_task(other, status="done")
    probe = f"echo 'still waiting on #{other}'; exit 1"
    tid = _due_waiting_task(p, probe, since_ago=30000)
    _settle_probe(d, tid)
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()   # its timer runs out on a fresh not yet past the cap
    stale = p.db.q("SELECT * FROM events WHERE kind='wait_stale' AND task=?", (tid,))
    assert len(stale) == 1 and f"Blocking gate: {probe}" in stale[0]["text"]
    assert f"last output: still waiting on #{other}" in stale[0]["text"] and "keeps sleeping" in stale[0]["text"]
    assert not _never(p, tid), "the same output only just started"
    text, _, pr = d._probe_out[tid]
    d._probe_out[tid] = (text, time.time() - 22000, pr)
    d._flag_never_passes(p.db.task(tid), probe, 1, text, stale=True)   # as at its next wait_stale check
    ev = _never(p, tid)
    assert len(ev) == 1 and f"#{other} (done)" in ev[0]["text"] and not _ready(p, tid)


# Heal checks (runtime/ttp/heal.py) ----------------------------------------------------------------
def _heal_setup(env, **block):
    from ttp import daemon as dm
    from ttp import schedule as sched
    p = make(env)
    up = p.root / "svc-up"
    heal_block = {"check": f"test -e {up}", "fix": f"touch {up}", "grace_s": 0, "settle_s": 0, **block}
    sched.upsert(p.db, "svc", "command", "5m", payload={"heal": heal_block})
    return p, dm.Daemon(p.base), up


def _heal_spec(p):
    from ttp import heal
    return heal.of(json.loads(p.db.one("SELECT payload FROM schedules WHERE name='svc'")["payload"]))


def test_heal_cli_lists_and_tests_a_check(env, capsys, monkeypatch):
    from ttp import cli
    p, d, up = _heal_setup(env)
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    cli.main(["heal", "list"])
    assert "svc: not checked yet" in capsys.readouterr().out
    with pytest.raises(SystemExit) as e:
        cli.main(["heal", "test", "svc"])
    assert e.value.code == 1 and "svc: unhealthy (exit 1)" in capsys.readouterr().out
    assert not up.exists()   # a dry run never fixes
    up.touch()
    with pytest.raises(SystemExit) as e:
        cli.main(["heal", "test", "svc"])
    assert e.value.code == 0


def test_heal_outage_check_whose_adopted_task_fails_raises_one_high_alert(env):
    """heal owns the alert once it holds the adopted schedule_fix task: no second schedule:<name>."""
    import unittest.mock
    from ttp import schedule as sched
    p, d, up = _heal_setup(env, outage=True, grace_s=600)
    payload = json.loads(p.db.one("SELECT payload FROM schedules WHERE name='svc'")["payload"])
    payload["heal"]["check"] = "exit 124"
    sched.upsert(p.db, "svc", "command", "5m", payload=payload)
    now = time.time()

    def tick(at):
        p.db.x("UPDATE schedules SET next_run=0 WHERE name='svc'")
        with unittest.mock.patch("time.time", return_value=at):
            d.run_schedules()

    for dt in (0, 300, 700):
        tick(now + dt)
    tid = p.db.one("SELECT id FROM tasks WHERE origin='daemon'")["id"]
    p.db.update_task(tid, status="failed")
    for dt in (1000, 1300):
        tick(now + dt)
    # The box answers once (unhealthy, not unknown), then goes dark again: the schedule fails twice
    # more while heal still holds its failed task.
    def check(cmd):
        payload["heal"]["check"] = cmd
        sched.upsert(p.db, "svc", "command", "5m", payload=payload)
    check("exit 1")
    tick(now + 1600)
    check("exit 124")
    for dt in (1900, 2200, 2500):
        tick(now + dt)
        for t in p.db.q("SELECT id FROM tasks WHERE origin='daemon' AND status='queued'"):
            p.db.update_task(t["id"], status="failed")
    assert p.db.one("SELECT COUNT(*) n FROM tasks WHERE origin='daemon'")["n"] == 1
    rows = p.db.q("SELECT key FROM alerts WHERE cleared IS NULL AND severity='high'")
    assert [r["key"] for r in rows] == ["heal:svc"], rows


# shared machines: recovery owner and change ledger (machine_ledger.py) -----------------------------

def _resources(p, text):
    c = p.charter_path.read_text()
    p.charter_path.write_text(c.replace("## Resources\n", f"## Resources\n{text}\n", 1))


def test_machines_set_names_a_recovery_owner_that_an_update_keeps(env, capsys):
    from ttp import machines as mm
    from ttp.cli import main
    main(["machines", "add", "box-a", "--tags", "device"])
    main(["machines", "set", "box-a", "--owner", "alpha", "--fallback", "beta"])
    assert "box-a [device] (recovery owner alpha, fallback beta)" in capsys.readouterr().out
    mm.add("box-a", note="main board")
    m = mm.load()["box-a"]
    assert (m["recovery_owner"], m["recovery_fallback"], m["note"]) == ("alpha", "beta", "main board")
    mm.set_recovery("box-a", fallback="")
    assert "recovery_fallback" not in mm.load()["box-a"] and mm.load()["box-a"]["recovery_owner"] == "alpha"
    with pytest.raises(ValueError):
        mm.set_recovery("box-z", owner="alpha")
    mm.set_recovery("box-a", owner="")
    with pytest.raises(ValueError, match="needs an owner"):
        mm.set_recovery("box-a", fallback="beta")


def test_machine_change_ledger_add_list_overdue_and_close(env, capsys):
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp.cli import main
    p = make(env)
    mm.add("box-a", tags="device")
    now = time.time()
    with pytest.raises(ValueError, match="give an end"):
        ml.add_change("box-a", "drop-in", "rm it", "demo")
    with pytest.raises(ValueError, match="no machine"):
        ml.add_change("box-z", "drop-in", "rm it", "demo", expires="2h")
    main(["machines", "change", "add", "box-a", "disabled auto power cycle for a soak", "--undo",
          "enable-power-cycle", "--expires", "2h", "--by", "demo"])
    assert "recorded #1 box-a: disabled auto power cycle for a soak (by demo; undo: `enable-power-cycle`" \
        in capsys.readouterr().out
    probe = ml.add_change("box-a", "paused the queue", "resume-queue", "demo", until_probe="test -d /", now=now)
    assert probe["expires"] == pytest.approx(now + ml.PROBE_END_S)
    main(["machines", "change", "list"])
    out = capsys.readouterr().out
    assert "#1 box-a" in out and "#2 box-a: paused the queue" in out and "OVERDUE" not in out
    main(["machines", "change", "add", "box-a", "power-cycled the tray", "--undo", "none", "--expires", "1h",
          "--by", "demo", "--expect", "down", "--expect", "fp-tray"])
    assert "expects down, fp-tray)" in capsys.readouterr().out and ml.changes()[2]["expects"] == ["down", "fp-tray"]
    assert "expects" not in ml.changes()[0], "no --expect, no expects: the change explains no alert"
    ml.close_change(3, "test", "demo")
    first = ml.changes()[0]
    assert ml.overdue(first, now + 3 * 3600).startswith("expired") and not ml.overdue(first, now)
    assert ml.overdue(probe, now + ml.PROBE_END_S + 1).startswith("expired")
    # The until-probe runs in the daemon of the project that made the entry; exit 0 makes it overdue.
    other = ml.Probes(type("P", (), {"name": "else", "root": p.root})())
    other.tick(now)
    assert not other._procs, "another project's daemon runs only its own entries' probes"
    probes = ml.Probes(p, log=lambda s: None)
    for n in range(ml.PROBE_PASSES):
        _change_probe_round(probes, 2, now + ml.PROBE_GRACE_S + n * 600)
    assert ml.overdue(ml.changes()[1], now + ml.PROBE_GRACE_S + 601) == "its until-probe passed"
    main(["machines", "change", "close", "2", "--why", "resumed", "--by", "demo"])
    assert [c["id"] for c in ml.changes()] == [1]
    assert ml.changes(open_only=False)[1]["closed_why"] == "resumed"
    with pytest.raises(SystemExit):
        main(["machines", "change", "close", "2"])


def test_machine_change_edit_corrects_an_open_entry_in_place(env, capsys):
    """`ttp machines change edit <id>` corrects an open entry's text, undo command or end in place: same id,
    alias, author and creation time, an edit trail with the old values; a new end drops its overdue pages.
    It refuses unknown or closed ids, a power cycle's undo or end, and an edit that changes nothing."""
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp.cli import main
    make(env)
    mm.add("box-a", tags="device")
    now = time.time()
    first = ml.add_change("box-a", "drop-in", "rm it", "alpha", expires="1h", now=now - 7200)
    ml.add_change("box-a", "second", "undo-2", "alpha", expires="2h", now=now)
    main(["machines", "change", "edit", "1", "--undo", "rm /etc/x.conf && reload", "--by", "beta"])
    assert "edited #1 box-a: drop-in (by alpha; undo: `rm /etc/x.conf && reload`" in capsys.readouterr().out
    c = ml.changes()[0]
    assert (c["id"], c["alias"], c["by"], c["added"]) == (1, "box-a", "alpha", first["added"])
    assert c["edits"][0]["by"] == "beta" and c["edits"][0]["was"] == {"undo": "rm it"}
    ml.edit_change(1, "beta", what="drop-in for a soak", now=now)
    c = ml.changes()[0]
    assert c["what"] == "drop-in for a soak" and c["edits"][1] == {"at": now, "by": "beta", "was": {"what": "drop-in"}}
    # Overdue and paged: a new end starts afresh, without the old pages or probe result.
    with ml._locked():
        doc = ml._read(ml.LEDGER, {})
        doc["changes"][0].update(page={"stage": 1}, probe_passed=now)
        ml._write(ml.LEDGER, doc)
    assert ml.overdue(ml.changes()[0], now)
    ml.edit_change(1, "beta", expires="3h", now=now)
    c = ml.changes()[0]
    assert c["expires"] == pytest.approx(now + 3 * 3600) and "page" not in c and "probe_passed" not in c
    assert not ml.overdue(c, now) and c["edits"][2]["was"]["expires"] == pytest.approx(now - 3600)
    ml.edit_change(1, "beta", until_probe="test -e /tmp/done", now=now)
    c = ml.changes()[0]
    assert c["probe"] == "test -e /tmp/done" and c["expires"] == pytest.approx(now + ml.PROBE_END_S)
    assert c["edits"][3]["was"]["probe"] is None
    with pytest.raises(ValueError, match="nothing to change"):
        ml.edit_change(1, "beta", what="drop-in for a soak", now=now + 60)
    with pytest.raises(ValueError, match="say what to change"):
        ml.edit_change(1, "beta")
    with pytest.raises(ValueError, match="cannot be empty"):
        ml.edit_change(1, "beta", undo="  ")
    with pytest.raises(ValueError, match="no machine change #9"):
        ml.edit_change(9, "beta", undo="x")
    ml.close_change(2, "undone")
    with pytest.raises(ValueError, match="#2 is closed"):
        ml.edit_change(2, "beta", undo="x")
    for bad in (["9", "--undo", "x"], ["2", "--undo", "x"], ["1", "--what", "drop-in for a soak"],
                ["1", "--until-task", "5", "--until-probe", "true"]):
        with pytest.raises(SystemExit):
            main(["machines", "change", "edit", *bad])
    pc = ml.add_power_cycle("box-a", "1h", "alpha", "firmware", now=now)
    with pytest.raises(ValueError, match="planned power cycle"):
        ml.edit_change(pc["id"], "beta", expires="2h")
    assert ml.edit_change(pc["id"], "beta", what="power-cycle intent: new firmware")["kind"] == ml.POWER_CYCLE
    assert [c["id"] for c in ml.changes()] == [1, pc["id"]] and ml._read(ml.LEDGER, {})["next"] == pc["id"] + 1


def test_a_machine_change_keeps_an_until_probe_and_an_expires_given_together(env, capsys):
    """`machines change add|edit` with --until-probe and --expires keeps both: the entry is overdue at
    whichever comes first, its probe passing or its time. --expires with --until-task stays refused."""
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp.cli import main
    p = make(env)
    mm.add("box-a", tags="device")
    main(["machines", "change", "add", "box-a", "paused", "--undo", "resume", "--until-probe", "false",
          "--expires", "1h", "--by", p.name])
    now = time.time()
    c = ml.changes()[0]
    assert c["probe"] == "false" and c["expires"] == pytest.approx(now + 3600, abs=60)
    assert "until-probe `false`, at the latest" in capsys.readouterr().out
    assert not ml.overdue(c, now) and ml.overdue(c, now + 3700).startswith("expired"), "its time comes first"
    ml.add_change("box-a", "drained", "undrain", p.name, expires="1d", until_probe="test -d /", now=now)
    probes = ml.Probes(p, log=lambda s: None)
    for n in range(ml.PROBE_PASSES):
        _change_probe_round(probes, 2, now + ml.PROBE_GRACE_S + n * 600)
    c = ml.changes()[1]
    assert c["expires"] == pytest.approx(now + 86400) and ml.overdue(c, now + 3600) == "its until-probe passed"
    main(["machines", "change", "edit", "1", "--until-probe", "test -e /nonexistent-ttp-probe", "--expires", "2h",
          "--by", p.name])
    c = ml.changes()[0]
    assert c["probe"] == "test -e /nonexistent-ttp-probe" and c["expires"] == pytest.approx(now + 7200, abs=60)
    with pytest.raises(SystemExit):
        main(["machines", "change", "add", "box-a", "staged", "--undo", "rm -r it", "--until-task", "1",
              "--expires", "1h", "--by", p.name])
    assert len(ml.changes()) == 2


def test_giving_a_machine_change_its_until_probe_again_judges_it_afresh(env):
    """`machines change edit <id> --until-probe <the same probe>` keeps the end but drops the probe's
    result, pages and passes so far: a probe still running from before the edit does not count, and it
    needs PROBE_PASSES fresh passes after PROBE_GRACE_S to be overdue again."""
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    p = make(env)
    mm.add("box-a", tags="device")
    now = time.time()
    ml.add_change("box-a", "paused", "resume", p.name, until_probe="test -d /", now=now)
    probes = ml.Probes(p, log=lambda s: None)
    for n in range(ml.PROBE_PASSES):
        _change_probe_round(probes, 1, now + ml.PROBE_GRACE_S + n * 600)
    with ml._locked():
        doc = ml._read(ml.LEDGER, {})
        doc["changes"][0]["page"] = {"stage": 1}
        ml._write(ml.LEDGER, doc)
    c = ml.changes()[0]
    assert c["probe_passed"] and ml.overdue(c, now + 1000)
    probes._probed.clear()
    t = now + 2000
    probes.tick(t)   # a pass in flight while the probe is set again
    assert 1 in probes._procs
    c = ml.edit_change(1, p.name, until_probe="test -d /", now=t + 1)
    assert c["probe"] == "test -d /" and c["expires"] == pytest.approx(now + ml.PROBE_END_S)
    assert "probe_passed" not in c and "page" not in c and c["page_from"] == t + 1
    assert c["edits"][-1]["was"] == {"probe_passed": pytest.approx(now + ml.PROBE_GRACE_S + 600)}
    probes._procs[1][0].wait(30)
    probes._probed[1] = t + 2   # not due again yet
    probes.tick(t + 2)
    assert "probe_passed" not in ml.changes()[0] and 1 not in probes._passes, "the pass begun before is stale"
    probes.tick(t + 60)
    assert 1 not in probes._procs, "not run again during its grace"
    _change_probe_round(probes, 1, t + 1 + ml.PROBE_GRACE_S)
    assert "probe_passed" not in ml.changes()[0], "one fresh pass is not enough"
    _change_probe_round(probes, 1, t + 1 + ml.PROBE_GRACE_S + 600)
    assert ml.overdue(ml.changes()[0], t + 1 + ml.PROBE_GRACE_S + 601) == "its until-probe passed"
    c = ml.edit_change(1, p.name, until_probe="test -d /", now=t + 2000)
    assert "probe_passed" not in c, "the same probe again clears a pass with no page too"


def test_an_edited_machine_change_overdue_again_pages_afresh_and_a_stale_probe_pass_is_ignored(env, monkeypatch):
    """A new end from `machine change edit` starts a new page episode: once it passes too, the overdue
    page has a new id, so the maker gets a new event rather than a duplicate of the delivered one. A
    probe started before an edit changed the probe does not count as the new probe passing."""
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp.daemon import Daemon
    alpha = make(env, "alpha")
    mm.add("box-a", tags="device")
    now = time.time()
    ml.add_change("box-a", "drop-in", "rm it", "alpha", expires="1h", now=now - 7200)
    d = Daemon(alpha.base)
    first = ml.route(now, able=lambda n: (True, ""), claimer="alpha")
    assert [x["kind"] for x in first] == ["machine_change_overdue"]
    assert d._machine_page(first[0], now)
    ml.delivered(first[0])
    ml.edit_change(1, "alpha", expires="1h", now=now + 60)
    assert ml.route(now + 120, able=lambda n: (True, "")) == []
    second = ml.route(now + 60 + 3601, able=lambda n: (True, ""), claimer="alpha")
    assert [x["kind"] for x in second] == ["machine_change_overdue"] and second[0]["id"] != first[0]["id"]
    assert d._machine_page(second[0], now + 3700)
    assert alpha.db.one("SELECT COUNT(*) n FROM events WHERE kind='machine_change_overdue'")["n"] == 2
    # A probe still running from before an edit to another probe: its pass is not the new probe's.
    ml.edit_change(1, "alpha", until_probe="test -d /", now=now + 3700)
    probes = ml.Probes(alpha, log=lambda s: None)
    _change_probe_round(probes, 1, now + 3700 + ml.PROBE_GRACE_S)   # the first of two passes
    probes._probed.clear()
    probes.tick(now + 4600)
    assert 1 in probes._procs
    ml.edit_change(1, "alpha", until_probe="test -e /nonexistent-ttp-probe", now=now + 4601)
    probes._procs[1][0].wait(10)
    probes._probed[1] = now + 4700   # not due again yet
    probes.tick(now + 4700)
    assert "probe_passed" not in ml.changes()[0], "the old probe's pass does not end the edited probe"


def test_a_planned_power_cycle_tells_running_workers_on_the_machine_to_hand_off_once(env, tmp_path, capsys,
                                                                                    monkeypatch):
    """`ttp machines change add <alias> "<why>" --power-cycle-at <t>` records a power-cycle intent (no
    undo, expects down only around T, never overdue, closes itself after). Shortly before T the daemon tells each running
    worker on that machine (a task resource on it, or every worker when it is this host), once, through
    its steer.md, to commit and hand off; workers elsewhere and runs outside the window hear nothing."""
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp.cli import main
    from ttp.daemon import Daemon
    p = make(env)
    mm.add("box-a", tags="device")
    mm.add("box-b", tags="device")
    for bad in (["--undo", "x"], ["--expires", "2h"]):
        with pytest.raises(SystemExit):
            main(["machines", "change", "add", "box-a", "firmware update", "--power-cycle-at", "1h", "--by", "demo", *bad])
    with pytest.raises(SystemExit):
        main(["machines", "change", "add", "box-a", "drop-in", "--expires", "1h", "--by", "demo"])
    capsys.readouterr()
    now = time.time()
    main(["machines", "change", "add", "box-a", "firmware update", "--power-cycle-at", "1h", "--by", p.name])
    assert "power-cycle intent, at " in capsys.readouterr().out
    c = ml.changes()[0]
    at = c["at"]
    assert c["kind"] == ml.POWER_CYCLE and c["expects"] == ["down"] and at == pytest.approx(now + 3600, abs=60)
    assert not ml.overdue(c, at + 10 * 86400), "a power cycle has nothing to undo: never overdue"
    on_a = p.db.add_task("device job", "s", kind="code", origin="user", labels=["resource:box-a-device"])
    on_b = p.db.add_task("other box", "s", kind="code", origin="user", labels=["resource:box-b-device"])
    runs = {}
    for t in (on_a, on_b):
        (tmp_path / str(t)).mkdir()
        runs[t] = p.db.x("INSERT INTO runs(task,role,started,status,dir) VALUES(?,?,?,?,?)",
                         (t, "worker", now, "running", str(tmp_path / str(t))))
    steer = {t: tmp_path / str(t) / "steer.md" for t in runs}
    monkeypatch.setattr(mm, "here", lambda known=None: None)
    d = Daemon(p.base)
    d.power_cycle_notices(at - ml.POWER_CYCLE_LEAD_S - 60)
    assert not any(f.exists() for f in steer.values()), "not yet: too early"
    d.power_cycle_notices(at - 120)
    d.power_cycle_notices(at - 60)
    text = steer[on_a].read_text()
    assert text.count("## Update") == 1, "told once"
    assert "box-a is to be power-cycled at" in text and f"machine change #{c['id']}" in text \
        and "hand off before then" in text
    assert not steer[on_b].exists(), "a worker on another machine is not told"
    monkeypatch.setattr(mm, "here", lambda known=None: ("box-a", {}))
    d.power_cycle_notices(at - 30)
    assert "this host is to be power-cycled" in steer[on_b].read_text(), "on this host every worker is told"
    assert steer[on_a].read_text().count("## Update") == 1
    ml.Probes(p).tick(at + ml.POWER_CYCLE_AFTER_S + 1)
    assert not ml.changes(), "the intent closes itself once its time is past"
    assert ml.changes(open_only=False)[0]["closed_why"] == "the planned power cycle is past"


def _ledger_writer(home, n, k):
    from ttp import machine_ledger as ml
    for i in range(k):
        ml.add_change("box-a", f"change {n}.{i}", "undo", f"p{n}", expires="1h")


def test_machine_ledger_keeps_every_entry_from_concurrent_writers(env):
    import multiprocessing
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    mm.add("box-a", tags="device")
    ctx = multiprocessing.get_context("fork")
    procs = [ctx.Process(target=_ledger_writer, args=(env["home"], n, 10)) for n in range(4)]
    for pr in procs:
        pr.start()
    for pr in procs:
        pr.join(60)
        assert pr.exitcode == 0
    got = ml.changes()
    assert len(got) == 40 and sorted(c["id"] for c in got) == list(range(1, 41))
    assert {c["what"] for c in got} == {f"change {n}.{i}" for n in range(4) for i in range(10)}


def test_a_long_machine_condition_goes_to_its_owner_then_the_fallback_then_the_user(env):
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp import upstream
    from ttp.daemon import Daemon
    alpha = make(env, "alpha")
    mm.add("box-a", tags="device")
    t0 = time.time()
    assert ml.report("gamma", "box-a", "down", "no answer to ssh", now=t0)
    assert not ml.report("gamma", "box-z", "down", now=t0)
    assert ml.route(t0 + 2 * 3600, able=lambda n: (True, "")) == [], "no owner set: nothing is routed"
    mm.set_recovery("box-a", owner="alpha", fallback="beta")
    t0 += 2 * 3600
    ml.report("gamma", "box-a", "down", "no answer to ssh", now=t0)
    ml.report("delta", "box-a", "down", now=t0 + 60)
    able = {"alpha": (False, "its daemon is stopped"), "beta": (False, "it is paused")}
    pages = ml.route(t0 + 120, able=able.get)
    # The owner cannot act: its recovery page, and at once an outage task for the fallback (nobody can act).
    assert [(x["target"], x["kind"]) for x in pages] == [("alpha", "machine_condition"),
                                                         ("beta", "machine_outage_task")]
    assert "box-a down" in pages[0]["text"] and "gamma, delta" in pages[0]["text"]
    assert ml.route(t0 + 180, able=able.get) == [], "a claimed page goes to one daemon"
    assert ml.delivered(pages[0]) and not ml.delivered(pages[0])
    assert ml.delivered(pages[1])
    assert ml.route(t0 + 120 + ml.outagetask.TASK_DUE_S - 1, able=able.get) == [], "a delivered page is sent once"
    # The task is open past its due time and no project can act: one user alert for it.
    pages = ml.route(t0 + 120 + ml.outagetask.TASK_DUE_S, able=able.get)
    assert [(x["target"], x["kind"]) for x in pages] == [(ml.USER, "machine_outage_overdue")]
    assert "no project can act on it" in pages[0]["text"] and pages[0]["severity"] == "normal"
    ml.delivered(pages[0])
    pages = ml.route(t0 + 180 + ml.UNAVAILABLE_S, able=able.get)
    assert [x["target"] for x in pages] == ["beta"] and "alpha cannot act: its daemon is stopped" in pages[0]["text"]
    ml.delivered(pages[0])
    ml.report("gamma", "box-a", "down", now=t0 + 3000)
    assert ml.route(t0 + 3000, able=able.get) == []
    pages = ml.route(t0 + 3000 + ml.UNAVAILABLE_S, able=able.get)
    assert [x["target"] for x in pages] == [ml.USER]
    ml.delivered(pages[0])
    assert ml.route(t0 + 3000 + 2 * ml.UNAVAILABLE_S, able=able.get) == []
    # Delivered: a high note in the owner's inbox from this daemon, an event at home, an outage alert.
    d = Daemon(alpha.base)
    d._machine_page({"target": "beta", "kind": "machine_condition", "key": "machine:box-a:down",
                     "alias": "box-a", "text": "Machine box-a down."}, t0)
    note = [json.loads(ln) for ln in upstream.path().read_text().splitlines()][-1]
    assert (note["to"], note["from"], note["severity"], note["project"]) == ("beta", "daemon", "high", "alpha")
    assert "from the daemon of alpha" in upstream._event(note)[1]
    d._machine_page({"target": "alpha", "kind": "machine_condition", "key": "machine:box-a:down",
                     "alias": "box-a", "text": "Machine box-a down."}, t0)
    ev = alpha.db.one("SELECT * FROM events WHERE kind='machine_condition'")
    assert ev["severity"] == "high" and ev["status"] == "queued"
    from ttp import coordinator as coord
    assert coord.EFFORT_EVENT_TRIGGERS["machine_condition"] == "resource"
    d._machine_page({"target": ml.USER, "kind": "machine_condition", "key": "machine:box-a:down",
                     "alias": "box-a", "text": "Machine box-a down."}, t0)
    assert "Outage: Machine box-a down." in alpha.db.one("SELECT text FROM alerts WHERE key='machine:box-a:down'")["text"]
    # A clear, or nobody reporting it for CONDITION_GONE_S, ends it.
    ml.report("gamma", "box-a", "down", cleared=True)
    assert ml.conditions() == {}
    ml.report("gamma", "box-a", "held", now=t0)
    ml.route(t0 + ml.CONDITION_GONE_S, able=able.get)
    assert ml.conditions() == {}
    # A command watcher's observation with `machine` and `condition` reports it.
    d._machine_condition({"machine": "box-a", "condition": "held", "grace_s": 60}, "hold never recovers")
    got = ml.conditions()["box-a:held"]
    assert (got["seen_by"], got["grace_s"], got["text"]) == (["alpha"], 60.0, "hold never recovers")


def test_can_act_reads_another_projects_state_without_writing_it(env):
    from ttp import machine_ledger as ml
    beta = make(env, "beta")
    db = beta.base / "state" / "project.db"
    before = db.stat().st_mtime
    assert ml.can_act("beta") == (False, "its daemon is stopped")
    assert ml.can_act("nobody")[0] is False
    assert db.stat().st_mtime == before


def test_an_overdue_machine_change_pages_its_project_then_the_owner(env):
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    mm.add("box-a", tags="device")
    mm.set_recovery("box-a", owner="alpha")
    now = time.time()
    ml.add_change("box-a", "drop-in for a soak", "remove-drop-in", "gamma", expires="1h", now=now)
    assert ml.route(now + 60, able=lambda n: (True, "")) == []
    able = {"gamma": (False, "it is paused"), "alpha": (True, "")}
    pages = ml.route(now + 3601, able=able.get)
    assert [(x["target"], x["kind"]) for x in pages] == [("gamma", "machine_change_overdue")]
    assert "undo it with `remove-drop-in`" in pages[0]["text"]
    ml.route(now + 3700, able=able.get)
    pages = ml.route(now + 3700 + ml.UNAVAILABLE_S, able=able.get)
    assert [x["target"] for x in pages] == ["alpha"]
    assert ml.route(now + 3700 + ml.UNAVAILABLE_S + ml.REPAGE_S, able=able.get)[0]["target"] == ml.USER
    ml.close_change(1, "undone")
    assert ml.route(now + 4 * 86400, able=able.get) == []


def _inbox():
    from ttp import upstream
    try:
        return [json.loads(ln) for ln in upstream.path().read_text().splitlines() if ln.strip()]
    except FileNotFoundError:
        return []


def test_a_machine_page_lost_to_a_crash_goes_out_on_a_later_tick_exactly_once(env, monkeypatch):
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp.daemon import Daemon
    alpha = make(env, "alpha")
    mm.add("box-a", tags="device")
    mm.set_recovery("box-a", owner="beta")
    ml.report("gamma", "box-a", "down", "no answer to ssh", now=time.time() - 3600)
    # A daemon routes the page, then dies before it delivers: the page stays pending, claimed for a while.
    pages = ml.route(claimer="alpha")
    # beta cannot act (not a project here): its outage task goes at once to the detector, gamma.
    assert [(x["target"], x["kind"]) for x in pages] == [("beta", "machine_condition"),
                                                         ("gamma", "machine_outage_task")] and _inbox() == []
    d = Daemon(alpha.base)
    d.route_machines()
    assert _inbox() == [], "the claim holds while the crashed daemon might still deliver"
    monkeypatch.setattr(ml, "CLAIM_S", 0)   # the claim lapsed
    d._machines_routed = 0
    d.route_machines()
    notes = _inbox()
    assert [(n["to"], n["from"]) for n in notes] == [("beta", "daemon"), ("gamma", "daemon")]
    assert notes[0]["spec"] == " ".join(pages[0]["text"].split()), "the text is fixed for the step"
    assert notes[1]["outage"]["label"] == pages[1]["id"] and "outage" not in notes[0]
    d._machines_routed = 0
    d.route_machines()
    assert len(_inbox()) == 2
    # A crash after the send but before it was marked: the resend is the same note, dropped as a duplicate.
    ml.report("gamma", "box-a", "held", now=time.time() - 3600)
    page = next(x for x in ml.route(claimer="alpha") if x["key"] == "machine:box-a:held")
    assert d._machine_page(page, time.time())
    d._machines_routed = 0
    d.route_machines()
    assert len(_inbox()) == 4 and ml.route() == [], "the resend is dropped; the held outage's task goes once"
    # The same at home: one event per page, however often it is retried.
    mm.set_recovery("box-a", owner="alpha")
    ml.report("gamma", "box-a", "down", cleared=True)
    ml.report("gamma", "box-a", "down", now=time.time() - 3600)
    page = ml.route(claimer="alpha")[0]
    assert d._machine_page(page, time.time()) and d._machine_page(page, time.time())
    d._machines_routed = 0
    d.route_machines()
    assert alpha.db.one("SELECT COUNT(*) n FROM events WHERE kind='machine_condition'")["n"] == 1
    assert ml.route() == []


def test_a_limited_machine_page_is_retried_and_daemon_pages_skip_the_worker_note_limit(env, monkeypatch):
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp import upstream
    from ttp.daemon import Daemon
    alpha = make(env, "alpha")
    mm.add("box-a", tags="device")
    mm.set_recovery("box-a", owner="beta")
    now = time.time()
    for i in range(upstream.NOTES_PER_HOUR):
        assert upstream.send("alpha", 1, "other", f"worker note {i}", now=now) == "sent"
    assert upstream.send("alpha", 1, "other", "one more", now=now) == "limited"
    assert upstream.send("alpha", None, "beta", "a page", "high", now=now, sender="daemon") == "sent"
    assert upstream.send("alpha", 1, "other", "one more", now=now) == "limited", "pages count apart"
    # A page whose send is refused stays pending and goes out on the next tick.
    ml.report("gamma", "box-a", "down", now=now - 3600)
    real, calls = upstream.send, []

    def flaky(*a, **k):
        calls.append(a[2])
        return "limited" if len(calls) == 1 else real(*a, **k)
    monkeypatch.setattr(upstream, "send", flaky)
    d = Daemon(alpha.base)
    d.route_machines()
    # beta's refused page waits; the outage task for the detector gamma (beta cannot act) goes out.
    assert calls == ["beta", "gamma"] and not [n for n in _inbox() if n["to"] == "beta" and "Machine box-a down" in n["spec"]]
    d._machines_routed = 0
    d.route_machines()
    assert calls == ["beta", "gamma", "beta"]
    assert len([n for n in _inbox() if n["to"] == "beta" and "Machine box-a down" in n["spec"]]) == 1
    d._machines_routed = 0
    d.route_machines()
    assert len(calls) == 3


def _router(home, n, now):
    from ttp import machine_ledger as ml
    from ttp import upstream
    for page in ml.route(now, able=lambda name: (True, ""), claimer=f"p{n}"):
        assert upstream.send(f"p{n}", None, page["target"], page["text"], "high", now=now, sender="daemon",
                             extra={"outage": page["outage"]} if page.get("outage") else None) == "sent"
        assert ml.delivered(page)


def test_two_daemons_routing_at_once_deliver_a_machine_page_once(env):
    import multiprocessing
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    mm.add("box-a", tags="device")
    mm.set_recovery("box-a", owner="beta")
    now = time.time()
    ml.report("gamma", "box-a", "down", now=now - 3600)
    ml.add_change("box-a", "drop-in", "rm it", "gamma", expires="1h", now=now - 7200)
    ctx = multiprocessing.get_context("fork")
    procs = [ctx.Process(target=_router, args=(env["home"], n, now)) for n in range(4)]
    for pr in procs:
        pr.start()
    for pr in procs:
        pr.join(60)
        assert pr.exitcode == 0
    # The recovery page, the overdue change's page, and one outage task (beta recorded no recovery action
    # within its budget), each sent once by one of the four daemons.
    got = sorted((n["to"], bool(n.get("outage"))) for n in _inbox())
    assert got == [("beta", False), ("gamma", False), ("gamma", True)]
    assert ml.route(now + ml.CLAIM_S, able=lambda name: (True, "")) == []


def test_responsibility_inventory_shows_an_unwatched_machine_until_a_check_names_it(env):
    from ttp import machines as mm
    from ttp import responsibilities as rs
    from ttp import schedule as sched
    from ttp.cli import status_text
    p = make(env)
    mm.add("box-a", tags="device")
    mm.add("box-b")
    _resources(p, "Machines: box-a")
    rec = rs.refresh(p, now=1000.0)
    box = [i for i in rec["items"] if i["kind"] == "machine"]
    assert box == [{"kind": "machine", "name": "box-a", "covered_by": []}]
    n = len(rec["items"])   # the default schedules are items too, covered by the daemon itself
    assert rec["line"] == f"health coverage: {n - 1}/{n} (missing: machine box-a)"
    assert rec["line"] in status_text(p)
    first = rs.digest_lines(p.db)
    assert len(first) == 1 and "missing: machine box-a" in first[0]
    # Unchanged: nothing is stored again and the coordinator hears nothing more.
    assert rs.refresh(p, now=2000.0)["at"] == 1000.0
    assert rs.digest_lines(p.db) == []
    # A heal check on its broker covers it: the change is one digest line.
    sched.upsert(p.db, "box-a-broker", "command", "10m", payload={"heal": {
        "preset": "broker", "status_command": "ssh box-a broker status --json", "resource": "box-a-device"}})
    rec = rs.refresh(p, now=3000.0)
    assert rec["line"] == f"health coverage: {n}/{n}"
    assert rec["items"][0]["covered_by"] == ["box-a-broker"]
    told = rs.digest_lines(p.db)
    assert len(told) == 1 and "now covered: machine box-a" in told[0]
    assert rs.digest_lines(p.db) == []
    # A plain command watcher naming the alias's host name covers it too; an alias inside a word does not.
    p.db.x("DELETE FROM schedules WHERE name='box-a-broker'")
    sched.upsert(p.db, "probe", "command", "10m", payload={"command": "ping -c1 xbox-a.example"})
    assert rs.refresh(p, now=4000.0)["items"][0]["covered_by"] == []
    mm.add("box-a", hostname="node7")
    sched.upsert(p.db, "probe", "command", "10m", payload={"command": "ping -c1 node7"})
    assert rs.refresh(p, now=5000.0)["items"][0]["covered_by"] == ["probe"]
    # The daily review spec carries the line.
    from ttp import daemon as dm
    sched.upsert(p.db, "daily-review", "llm", "1d", payload={})
    d = dm.Daemon(p.base)
    p.db.x("UPDATE schedules SET next_run=0 WHERE name='daily-review'")
    d.run_schedules()
    t = p.db.one("SELECT spec FROM tasks WHERE labels LIKE '%daily-review%'")
    assert t and "Responsibilities: health coverage:" in t["spec"]


def test_responsibility_inventory_credits_the_recovery_owners_heal_check_for_a_shared_machine(env):
    from ttp import machines as mm
    from ttp import responsibilities as rs
    from ttp import schedule as sched
    mm.add("box-a", tags="device")
    mm.set_recovery("box-a", "alpha", "beta")
    me, alpha, beta = make(env), _second_project(env, "alpha"), _second_project(env, "beta")
    _resources(me, "Machines: box-a")
    n = len(rs.inventory(me))
    assert rs.refresh(me, now=1000.0)["line"] == f"health coverage: {n - 1}/{n} (missing: machine box-a)"
    # The owner's plain command watcher or disabled heal check does not cover it; the fallback's heal check does.
    sched.upsert(alpha.db, "ping-a", "command", "5m", payload={"command": "ping box-a"})
    sched.upsert(alpha.db, "box-a-off", "command", "5m", payload={"heal": {"check": "ssh box-a true"}})
    alpha.db.x("UPDATE schedules SET enabled=0 WHERE name='box-a-off'")
    sched.upsert(beta.db, "box-a-up", "command", "5m", payload={"heal": {"check": "ssh box-a true", "outage": True}})
    mtimes = {q.name: (q.base / "state" / "project.db").stat().st_mtime_ns for q in (alpha, beta)}
    rec = rs.refresh(me, now=2000.0)
    assert rec["items"][0] == {"kind": "machine", "name": "box-a", "covered_by": ["beta/box-a-up"],
                               "via": "fallback beta"}
    assert rec["line"] == f"health coverage: {n}/{n} (machine box-a covered by fallback beta)"
    # The owner's own heal check wins over the fallback's.
    alpha.db.x("UPDATE schedules SET enabled=1 WHERE name='box-a-off'")
    rec = rs.refresh(me, now=3000.0)
    assert rec["items"][0]["covered_by"] == ["alpha/box-a-off"]
    assert rec["line"] == f"health coverage: {n}/{n} (machine box-a covered by owner alpha)"
    assert {q.name: (q.base / "state" / "project.db").stat().st_mtime_ns for q in (alpha, beta)} == mtimes
    # A check of this project's own covers it with no owner credit; the owner itself gets none from itself.
    sched.upsert(me.db, "mine", "command", "5m", payload={"heal": {"check": "ssh box-a true"}})
    assert rs.refresh(me, now=4000.0)["items"][0] == {"kind": "machine", "name": "box-a", "covered_by": ["mine"]}
    _resources(alpha, "Machines: box-a")
    alpha.db.x("DELETE FROM schedules WHERE name IN ('box-a-off', 'ping-a')")
    assert [i["covered_by"] for i in rs.inventory(alpha) if i["kind"] == "machine"] == [["beta/box-a-up"]]


