def _local_push_setup(env, monkeypatch, checks):
    """The project's code repo has no git remote at all; its `proj` branch is the push branch."""
    for var, val in (("GIT_AUTHOR_NAME", "t"), ("GIT_AUTHOR_EMAIL", "t@t"),
                     ("GIT_COMMITTER_NAME", "t"), ("GIT_COMMITTER_EMAIL", "t@t")):
        monkeypatch.setenv(var, val)
    p = make(env)
    repo = env["repo"]
    assert _git_out(repo, "remote") == ""
    _git_out(repo, "branch", "proj")
    p.set_config("delivery.push_branch", "proj")
    p.set_config("delivery.push_checks", checks)
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    monkeypatch.chdir(repo)
    return p, repo


def test_push_own_without_a_git_remote_fast_forwards_the_local_branch(env, monkeypatch, capsys):
    """In a code repo with no git remote, `ttp push --own` (and --detach) publishes by moving the
    local branch, fast-forward only, after its checks: the task's own branch is already there, and a
    pr_branch it carries is fast-forwarded to HEAD. A diverged branch is refused before the checks and
    keeps its tip (a branch another worktree has checked out: the next test)."""
    log = env["tmp"] / "checked"
    p, repo = _local_push_setup(env, monkeypatch, [f"git rev-parse HEAD >> {log}"])
    t = p.db.add_task("Speed it up", "s", kind="code")
    monkeypatch.setenv("TTP_TASK", str(t))
    _git_out(repo, "checkout", "-q", "-b", f"ttp/t{t}-speed-it-up")
    _commit(repo, "a.txt", "a\n")
    head = _git_out(repo, "rev-parse", "HEAD")
    capsys.readouterr()
    assert _ttp("push", "--own") == 0
    err = capsys.readouterr().err
    assert "local branch" in err and "cannot reach" not in err, err
    assert log.read_text().split() == [head]
    # A pr_branch it carries: fast-forwarded to HEAD.
    _git_out(repo, "branch", "feature/x", "proj")
    p.db.update_task(t, labels=["pr_branch:feature/x"])
    assert _ttp("push", "--own") == 0 and _git_out(repo, "rev-parse", "feature/x") == head
    assert f"pushed {head[:10]} to local branch feature/x" in capsys.readouterr().err
    # --detach takes the same way and its probe reports it.
    _commit(repo, "b.txt", "b\n")
    second = _git_out(repo, "rev-parse", "HEAD")
    rc = _ttp("push", "--own", "--detach")
    out = capsys.readouterr().out
    probe = next(ln.split(": ", 1)[1] for ln in out.splitlines() if ln.startswith("retry_when: "))
    assert rc == 0
    r = _probe_until_done(p, probe)
    assert r.returncode == 0 and f"pushed {second}" in r.stdout, r
    assert _git_out(repo, "rev-parse", "feature/x") == second
    # Diverged: refused before the checks, the branch keeps its tip.
    _git_out(repo, "branch", "-f", "feature/x", "proj")
    side = env["tmp"] / "side"
    _git_out(repo, "worktree", "add", "-q", str(side), "feature/x")
    _commit(side, "theirs.txt", "theirs\n")
    theirs = _git_out(repo, "rev-parse", "feature/x")
    _git_out(repo, "worktree", "remove", str(side))
    ran = log.read_text().split()
    assert _ttp("push", "--own") == 2 and "not an ancestor of HEAD" in capsys.readouterr().err
    assert _git_out(repo, "rev-parse", "feature/x") == theirs and log.read_text().split() == ran
    # Shared branches stay refused.
    p.db.update_task(t, labels=[])
    for name in ("proj", "main"):
        _git_out(repo, "checkout", "-q", "-B", name)
        assert _ttp("push", "--own") == 2 and "shared branch" in capsys.readouterr().err, name


def test_push_own_without_a_git_remote_fast_forwards_a_pr_branch_checked_out_in_another_worktree(
        env, monkeypatch, capsys):
    """With no git remote, a pr_branch another worktree has checked out is fast-forwarded there, so
    that worktree's files follow the branch (--detach too). Refused, before the checks and with the
    branch and the worktree untouched, while that worktree has uncommitted changes or the branch is
    not an ancestor of HEAD."""
    log = env["tmp"] / "checked"
    p, repo = _local_push_setup(env, monkeypatch, [f"git rev-parse HEAD >> {log}"])
    t = p.db.add_task("Fix it", "s", kind="code", labels=["pr_branch:feature/x"])
    monkeypatch.setenv("TTP_TASK", str(t))
    _git_out(repo, "branch", "feature/x", "proj")
    side = env["tmp"] / "side"
    _git_out(repo, "worktree", "add", "-q", str(side), "feature/x")
    (side / "scratch.log").write_text("untracked\n")   # untracked files do not count as changes
    _git_out(repo, "checkout", "-q", "-b", f"ttp/t{t}-fix-it")
    _commit(repo, "a.txt", "a\n")
    head = _git_out(repo, "rev-parse", "HEAD")
    capsys.readouterr()
    assert _ttp("push", "--own") == 0
    err = capsys.readouterr().err
    assert f"pushed {head[:10]} to local branch feature/x" in err and str(side) in err, err
    assert _git_out(side, "rev-parse", "HEAD") == head and (side / "a.txt").read_text() == "a\n"
    assert _git_out(side, "symbolic-ref", "--short", "HEAD") == "feature/x"
    assert _git_out(side, "status", "--porcelain", "--untracked-files=no") == ""
    # --detach: the same, reported by its probe.
    _commit(repo, "b.txt", "b\n")
    second = _git_out(repo, "rev-parse", "HEAD")
    assert _ttp("push", "--own", "--detach") == 0
    probe = next(ln.split(": ", 1)[1] for ln in capsys.readouterr().out.splitlines()
                 if ln.startswith("retry_when: "))
    r = _probe_until_done(p, probe)
    assert r.returncode == 0 and f"pushed {second}" in r.stdout, r
    assert _git_out(side, "rev-parse", "HEAD") == second and (side / "b.txt").read_text() == "b\n"
    # Dirty there: refused, nothing moves and nothing is checked.
    ran = log.read_text().split()
    _commit(repo, "c.txt", "c\n")
    (side / "a.txt").write_text("edited there\n")
    assert _ttp("push", "--own") == 2 and "uncommitted changes" in capsys.readouterr().err
    assert _git_out(side, "rev-parse", "HEAD") == second and (side / "a.txt").read_text() == "edited there\n"
    assert log.read_text().split() == ran
    _git_out(side, "checkout", "--", "a.txt")
    # Not a fast-forward (the worktree's branch moved on): refused, the branch keeps its commit.
    _commit(side, "theirs.txt", "theirs\n")
    theirs = _git_out(side, "rev-parse", "HEAD")
    assert _ttp("push", "--own") == 2 and "not an ancestor of HEAD" in capsys.readouterr().err
    assert _git_out(repo, "rev-parse", "feature/x") == theirs and (side / "theirs.txt").exists()
    assert not (side / "c.txt").exists() and log.read_text().split() == ran


def test_own_push_off_refuses_every_own_push_and_names_the_push_queue(env, monkeypatch, capsys):
    """delivery.own_push off: `ttp push --own` and `--own --detach` push nothing, start no detached
    push and say how the work lands instead; on (set explicitly) still publishes."""
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    _git_out(repo, "checkout", "-q", "-b", "ttp/t30-exp")
    _commit(repo, "mine.txt", "mine\n")
    monkeypatch.setenv("TTP_TASK", "30")
    p.set_config("delivery.own_push", "off")
    p.set_config("delivery.push_queue", True)
    capsys.readouterr()
    for args in (["push", "--own"], ["push", "--own", "--detach"]):
        assert _ttp(*args) == 2, args
        err = capsys.readouterr().err
        assert "delivery.own_push = off" in err and "approves it for the push queue" in err, err
    assert not (p.state / "pushes").exists()
    assert _git_out(origin, "for-each-ref", "--format=%(refname:short)", "refs/heads") == "proj"
    # An unknown value fails closed, and the config check names it.
    from ttp.project import config_problems
    p.set_config("delivery.own_push", "sometimes")
    assert _ttp("push", "--own") == 2 and "delivery.own_push = off" in capsys.readouterr().err
    assert any(x.startswith("delivery.own_push:") for x in config_problems(p.raw_config()))
    p.set_config("delivery.own_push", "on")
    assert _ttp("push", "--own") == 0 and _git_out(origin, "rev-parse", "ttp/t30-exp") == _git_out(repo, "rev-parse", "HEAD")


def test_own_push_existing_only_never_creates_a_remote_branch_but_updates_one(env, monkeypatch, capsys):
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    p.set_config("delivery.own_push", "existing_only")
    _git_out(repo, "checkout", "-q", "-b", "ttp/t30-exp")
    monkeypatch.setenv("TTP_TASK", "30")
    _commit(repo, "mine.txt", "mine\n")
    capsys.readouterr()
    for args in (["push", "--own"], ["push", "--own", "--detach"]):
        assert _ttp(*args) == 2, args
        assert "not creating it" in capsys.readouterr().err
    assert _git_out(origin, "for-each-ref", "--format=%(refname:short)", "refs/heads") == "proj"
    # Once the branch exists there, --own moves it on (fast-forward, as always).
    _git_out(repo, "push", "-q", "origin", "HEAD:refs/heads/ttp/t30-exp")
    _commit(repo, "more.txt", "more\n")
    assert _ttp("push", "--own") == 0
    assert _git_out(origin, "rev-parse", "ttp/t30-exp") == _git_out(repo, "rev-parse", "HEAD")


def test_own_push_unset_never_lets_a_review_create_a_remote_branch_but_updates_one(env, monkeypatch, capsys):
    """A reported case, replayed: with delivery.own_push unset, reviews ran `ttp push --own` for code
    tasks whose pr_branch: line named their own ttp/t<id>-... branch, and created those branches on a
    remote whose project allowed one push branch only. Unset reads as existing_only: the review is
    refused, naming the setting, and nothing reaches the remote; a branch the remote has still moves."""
    from ttp.project import own_push
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    p.set_config("delivery.own_push", None)
    p.set_config("delivery.push_queue", True)
    assert own_push(p.config()) == "existing_only"
    code = p.db.add_task("Fix it", "s", kind="code", labels=["pr_branch:ttp/t1-fix-it"])
    assert code == 1
    review = p.db.add_task(f"Review #{code}: Fix it", "r", kind="review", labels=[f"auto_review:{code}"])
    _git_out(repo, "checkout", "-q", "-b", "ttp/t1-fix-it")
    _commit(repo, "fix.txt", "fix\n")
    monkeypatch.setenv("TTP_TASK", str(review))
    capsys.readouterr()
    for args in (["push", "--own"], ["push", "--own", "--detach"]):
        assert _ttp(*args) == 2, args
        err = capsys.readouterr().err
        assert "delivery.own_push is unset, which reads as existing_only" in err and "not creating it" in err, err
    assert _git_out(origin, "for-each-ref", "--format=%(refname:short)", "refs/heads") == "proj"
    # The branch already on the remote (its PR's): the review's --own moves it on, fast-forward.
    _git_out(repo, "push", "-q", "origin", "HEAD:refs/heads/ttp/t1-fix-it")
    _commit(repo, "more.txt", "more\n")
    assert _ttp("push", "--own") == 0
    assert _git_out(origin, "rev-parse", "ttp/t1-fix-it") == _git_out(repo, "rev-parse", "HEAD")


def test_own_push_unset_still_lets_a_code_task_create_its_own_draft_pr_branch(env, monkeypatch, capsys):
    """Unset keeps the documented draft-PR path: a code task's `ttp push --own` creates its own
    ttp/t<id>-... branch, while delivery.draft_prs is on. Draft PRs off, an explicit existing_only, a
    review or no run at all creates nothing."""
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    p.set_config("delivery.own_push", None)
    t = p.db.add_task("Speed it up", "s", kind="code")
    branch = f"ttp/t{t}-speed-it-up"
    _git_out(repo, "checkout", "-q", "-b", branch)
    _commit(repo, "a.txt", "a\n")
    heads = lambda: _git_out(origin, "for-each-ref", "--format=%(refname:short)", "refs/heads").split()
    capsys.readouterr()
    assert _ttp("push", "--own") == 2 and "delivery.own_push" in capsys.readouterr().err   # outside a run
    monkeypatch.setenv("TTP_TASK", str(t))
    for key, value in (("delivery.draft_prs", False), ("delivery.own_push", "existing_only")):
        p.set_config(key, value)
        assert _ttp("push", "--own") == 2, key
        assert "not creating it" in capsys.readouterr().err
        p.set_config(key, None if key == "delivery.own_push" else True)
    assert heads() == ["proj"]
    review = p.db.add_task(f"Review #{t}: Speed it up", "r", kind="review", labels=[f"auto_review:{t}"])
    monkeypatch.setenv("TTP_TASK", str(review))   # the task's own branch only: never a review's push
    assert _ttp("push", "--own") == 2 and heads() == ["proj"]
    monkeypatch.setenv("TTP_TASK", str(t))
    assert _ttp("push", "--own") == 0, capsys.readouterr().err
    assert _git_out(origin, "rev-parse", branch) == _git_out(repo, "rev-parse", "HEAD")


def test_own_push_off_keeps_own_out_of_the_code_prompt_and_pr_fix_specs(env):
    """With own pushes off, a code task's prompt (kind-code.md) never advises `ttp push --own`: the PR
    section's publishing bullet is dropped and the based-on-another-branch refusal says hand off
    blocked. The daemon's PR-fix spec asks for no own push either, free branch or held."""
    from ttp.daemon import Daemon
    from ttp.prompts import own_off, worker_task
    p = make(env)
    t = p.db.task(p.db.add_task("Speed up the loader", "Make it faster.", kind="code"))
    assert "--own" in worker_task(p, t, str(p.root), "ttp/t1-x")
    p.set_config("delivery.own_push", "off")
    prompt = worker_task(p, t, str(p.root), "ttp/t1-x")
    assert "--own" not in prompt and "## Pull requests" in prompt, prompt
    assert "else hand off `blocked` with its message (own pushes are off" in prompt
    # A warning against it stays; another sentence of the same item asking for one is cut.
    assert own_off("- Do not `ttp push --own` it.\n") == "- Do not `ttp push --own` it.\n"
    assert own_off("- NEVER run `git push`. The exception: run `ttp push --own`.\n- Next.\n") \
        == "- NEVER run `git push`.\n- Next.\n"
    url = "https://github.com/acme/widgets/pull/7"
    src = p.db.add_task("Tune the cache", "s", kind="code")
    pr_branch = f"ttp/t{src}-tune-the-cache"
    subprocess.run(["git", "-C", str(p.root), "branch", pr_branch], check=True)
    p.db.update_task(src, status="done", pr_url=url, branch=pr_branch)
    d = Daemon(p.base)
    rec = {"task": src, "branch": pr_branch, "url": url}
    fix, made = d.pr_findings_owner("acme/widgets#7", rec, "CI failing: tests")
    assert made and "--own" not in fix["spec"] and "do not push anywhere yourself" in fix["spec"], fix["spec"]
    assert "--own" not in worker_task(p, fix, str(p.root), pr_branch)
    p.db.update_task(fix["id"], status="done")
    held = env["tmp"] / "held"
    subprocess.run(["git", "-C", str(p.root), "worktree", "add", "-q", str(held), pr_branch], check=True)
    fix, made = d.pr_findings_owner("acme/widgets#7", rec, "CI failing: tests")
    assert made and fix["branch"] is None and "--own" not in fix["spec"], fix["spec"]

# One alert per network outage (netwait, Daemon.check_unreachable) -----------------------------------
NET_PROBE = "ssh -o ConnectTimeout=5 jump.example true"
NET_OUT = "ssh: connect to host jump.example port 22: Connection timed out"


def _net_setup(env, monkeypatch, n=2, probe=NET_PROBE, out=NET_OUT, ssh_config=None, workstation=True):
    """Two tasks deferred on a start_when probe that reaches a host over ssh, a home zone that is not
    the machine's, a clock the test moves, and `check(at, rc)`: the probes' latest verdict (None: no
    verdict, as once a probe passed and the task started), one check, the alert sweep; it returns the
    network alerts posted so far. `ssh_config`: what `ssh -G <alias>` answers per alias ({} if not)."""
    from ttp import alerts, netwait, timefmt
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    from ttp.db import deferral
    monkeypatch.setattr(netwait, "_ssh_config", lambda alias: dict((ssh_config or {}).get(alias) or {}))
    monkeypatch.setattr(netwait, "workstation", lambda cfg=None: workstation)
    p = make(env)
    _no_events(p)
    assert timefmt.set_home(p, "America/Los_Angeles")
    d = Daemon(p.base)
    for i in range(n):
        assert coord.apply(p, [{"type": "task_add", "title": f"device job {i}", "spec": "s",
                                "start_when": probe}]) == []
    tids = [t["id"] for t in p.db.q("SELECT id FROM tasks WHERE status='queued' ORDER BY id")]
    clock = {"now": time.time(), "rc": 255}
    monkeypatch.setattr(time, "time", lambda: clock["now"])

    def one(at, rc):
        clock["now"] = at
        for tid in tids:
            # A start_when's verdict goes where the daemon keeps it (_start_verdict), a retry_when's to _probe_rc.
            verdicts = d._start_rc if deferral(p.db.task(tid)).get("when") else d._probe_rc
            if rc is None:
                verdicts.pop(tid, None)
            else:
                verdicts[tid] = (rc, at, probe)
                d._probe_out[tid] = (out if rc == 255 else "", at, probe)
        d._net_checked = 0.0
        d.check_unreachable()
        alerts.sweep(p.db, at)

    def check(at, rc=255):
        # The daemon checks every minute: between calls the last verdict holds (a check every 5 min here).
        t = clock["now"] + 300
        while t < at:
            one(t, clock["rc"])
            t += 300
        one(at, rc)
        clock["rc"] = rc
        return p.db.q("SELECT * FROM messages WHERE kind='alert' AND ref='network:unreachable' ORDER BY id")
    return p, d, tids, clock["now"], check


def test_network_outage_names_the_hosts_from_ssh_errors_or_the_probe(env):
    from ttp import netwait
    assert netwait.hosts("ssh -p 2222 -o BatchMode=yes -i key user@box1 test -e /m") == ["box1"]
    assert netwait.hosts("ssh -q box2 true && ssh box3 true") == ["box2", "box3"]
    assert netwait.hosts("ttp detach --check --host box4 /runs/1/x") == ["box4"]
    assert netwait.hosts("ssh box5 true", "ssh: Could not resolve hostname gw.example: Name or service not known") \
        == ["box5"], "the alias the probe used, not the address ssh resolved"
    assert netwait.hosts("sh check.sh", "ssh: Could not resolve hostname gw.example: Name or service not known") \
        == ["gw.example"], "no alias in the probe: ssh's own error"
    assert netwait.hosts("test -e /tmp/x") == []
    assert "The hosts this project's work needs cannot be reached" in netwait.text("UTC", 0.0, 1, [])
    # ssh inside a command substitution, as a probe captures the remote answer, and ending one.
    assert netwait.hosts("m=$(ssh -o BatchMode=yes h1 stat x) || exit 255") == ["h1"]
    assert netwait.hosts("m=`ssh -o BatchMode=yes h1 stat x` || exit 255") == ["h1"]
    assert netwait.hosts('[ "$(ssh box-a)" ] || exit 255') == ["box-a"]
    assert netwait.confirm("test -e /x || exit 255", "", lambda h: False) == \
        "exit 255 from a probe that names no ssh host"
    assert netwait.confirm("ssh h1 true", "", lambda h: False) == "", "every host it names is unreachable"
    assert "ssh reaches h1" in netwait.confirm("ssh h1 true", "", lambda h: h == "h1")


def test_network_outage_classes_loopback_proxyjump_and_proxycommand_routes_as_tunnels(monkeypatch):
    from ttp import netwait
    conf = {"box-a": {"hostname": "127.0.0.1", "port": "2222"},
            "box-b": {"hostname": "box-b.example", "proxyjump": "box-a"},
            "box-c": {"hostname": "10.0.0.7", "proxyjump": "gw.example,user@[::1]:2200"},
            "box-d": {"hostname": "box-d.example", "proxycommand": "ssh -W %h:%p box-a"},
            "box-e": {"hostname": "box-e.example", "proxycommand": "nc localhost:2201"},
            "box-f": {"hostname": "box-f.example", "proxycommand": "socat - TCP:127.0.0.2:2202"},
            "box-g": {"hostname": "box-g.example", "proxyjump": "gw.example"},
            "box-h": {"hostname": "box-h.example", "proxycommand": "nc %h %p"},
            "loop": {"hostname": "box-x.example", "proxyjump": "loop"}}
    monkeypatch.setattr(netwait, "_ssh_config", lambda alias: dict(conf.get(alias) or {}))
    for alias in ("box-a", "box-b", "box-c", "box-d", "box-e", "box-f", "127.0.0.1", "localhost"):
        assert netwait.route(alias)["tunnel"], alias
    for alias in ("box-g", "box-h", "gw.example", "loop"):
        assert not netwait.route(alias)["tunnel"], alias
    assert netwait.describe(["box-a"]) == (["box-a"], True), "a loopback HostName is never shown"
    assert netwait.describe(["box-c"]) == (["box-c (10.0.0.7)"], True)
    assert netwait.describe(["127.0.0.1"]) == ([], True), "a bare loopback address is no host name"
    assert netwait.describe(["box-a", "box-g"]) == (["box-a", "box-g (box-g.example)"], False), \
        "one real network route among them keeps the network wording"
    assert netwait.describe([]) == ([], False)


def test_network_outage_on_a_remote_route_keeps_the_vpn_wording_and_names_the_alias_first(env, monkeypatch):
    p, d, tids, now, check = _net_setup(env, monkeypatch, probe="ssh box-r true",
                                        out="ssh: connect to host box-r.example port 22: Connection timed out",
                                        ssh_config={"box-r": {"hostname": "box-r.example"}})
    check(now)
    sent = check(now + 900)
    assert len(sent) == 1 and sent[0]["severity"] == "normal"
    assert "box-r (box-r.example) cannot be reached" in sent[0]["text"], sent[0]["text"]
    assert "VPN or network sign-in" in sent[0]["text"] and "tunnel" not in sent[0]["text"]
    assert "Check that machine's network, and its VPN or network sign-in if it needs one" in sent[0]["text"]
    assert "nothing else can start" not in sent[0]["text"], "says what is held and what still runs"
    assert "2 queued task(s) that need it are held" in sent[0]["text"] and "the project keeps running" in sent[0]["text"]
    assert len(check(now + 6 * 3600)) == 1, "a network route is never raised again"


def _net_answering(p, d, at, host="other.example"):
    """A third queued task whose start_when probe reached `host` (exit 1: it answered, not yet ready);
    its verdict is dated ahead so it stays recent while the test moves the clock."""
    from ttp import coordinator as coord
    probe = f"ssh {host} test -e /tmp/marker"
    assert coord.apply(p, [{"type": "task_add", "title": "other box job", "spec": "s", "start_when": probe}]) == []
    tid = p.db.one("SELECT MAX(id) id FROM tasks")["id"]
    d._start_rc[tid] = (1, at + 10 ** 6, probe)
    return tid


def test_network_outage_with_every_host_failing_is_offline_and_gives_vpn_advice_only_on_a_workstation(env, monkeypatch):
    from ttp import netwait
    p, d, tids, now, check = _net_setup(env, monkeypatch)
    check(now)
    sent = check(now + 900)
    assert len(sent) == 1 and sent[0]["text"].startswith("Network: jump.example cannot be reached from the machine")
    assert "VPN or network sign-in" in sent[0]["text"] and "nothing else can start" not in sent[0]["text"]
    assert "other task(s) wait on their own timers" not in sent[0]["text"], "no other task can run: none counted"
    assert p.db.kv("network_outage")["kind"] == "offline"
    # The outage ends; the next one on a server: offline, but no VPN advice.
    check(now + 960, rc=None)
    assert len(check(now + 1600, rc=None)) == 1 and not p.db.kv("network_outage")
    monkeypatch.setattr(netwait, "workstation", lambda cfg=None: False)
    check(now + 3600)
    sent = check(now + 4500)
    assert len(sent) == 2 and sent[1]["severity"] == "normal"
    assert "VPN" not in sent[1]["text"] and "sign-in" not in sent[1]["text"], sent[1]["text"]
    assert "own network looks down" in sent[1]["text"], sent[1]["text"]
    # A name that does not resolve is this machine offline even while another host answers.
    out = "ssh: Could not resolve hostname jump.example: Temporary failure in name resolution"
    assert netwait.classify([out], ["jump.example"], ["other.example"]) == "offline"
    assert netwait.classify(["ssh: connect to host jump.example port 22: Network is unreachable"],
                            ["jump.example"], ["other.example"]) == "offline"
    assert netwait.classify([NET_OUT], ["jump.example"], ["jump.example"]) == "offline", "no other host answers"
    for err in ("No route to host", "Connection refused", "Connection timed out"):
        assert netwait.classify([f"ssh: connect to host jump.example port 22: {err}"],
                                ["jump.example"], ["other.example"]) == "hosts", err


