# Urgent user obligations (obligations.py, Daemon.check_obligations) ----------------------------------
def _ob_setup(env, monkeypatch):
    """A project, an owner task, and `check(at)`: one daemon pass (files run records, raises
    anomalies) at time `at`; it returns the obligation anomalies raised so far."""
    from ttp.daemon import Daemon
    p = make(env)
    _no_events(p)
    d = Daemon(p.base)
    now = time.time()
    tid = p.db.add_task("build the deliverable", "make it", kind="work", tier="light", origin="coordinator")

    def check(at):
        monkeypatch.setattr(time, "time", lambda: at)
        d._obligations_at = 0.0
        d.check_obligations()
        return p.db.q("SELECT * FROM events WHERE kind='obligation_overdue' ORDER BY id")
    return p, d, now, tid, check


def test_obligation_clock_is_not_reset_by_edits_tokens_running_or_waiting(env, monkeypatch):
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the urgent report", [tid], now=now)
    assert "## Obligation o1 " in p.db.task(tid)["spec"], "the owner is told through its spec"
    # Activity of every kind but durable progress, within the first two hours.
    p.db.update_task(tid, status="running", spec=p.db.task(tid)["spec"] + "\nedited", title="renamed")
    run_dir = p.runs / "r1"
    run_dir.mkdir(parents=True)
    p.db.x("INSERT INTO runs(task,role,started,status,dir,progress_ts,input_tokens,output_tokens) "
           "VALUES(?,?,?,?,?,?,?,?)", (tid, "worker", now + 600, "running", str(run_dir), now + 7000, 90000, 5000))
    assert ob.attach(p, oid, [tid], now=now + 3600) == [], "a re-attach keeps the clock"
    p.db.update_task(tid, status="waiting", not_before=now + 9000)
    assert check(now + 2 * 3600 - 60) == []
    evs = check(now + 2 * 3600 + 60)
    assert len(evs) == 1, "two hours with no durable progress raise, whatever the task did meanwhile"
    assert evs[0]["fingerprint"] == f"obligation:{oid}:1" and evs[0]["severity"] == "high" \
        and evs[0]["status"] == "queued" and evs[0]["task"] == tid
    assert f"#{tid} (waiting)" in evs[0]["text"] and "the urgent report" in evs[0]["text"], evs[0]["text"]


def test_obligation_progress_resets_only_its_owners_clock(env, monkeypatch):
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    other = p.db.add_task("second part", "s", kind="work", tier="light", origin="coordinator")
    oid = ob.add(p, "the urgent report", [tid, other], now=now)
    ob.record(p, oid, "progress", "commit abc123", tid, now=now + 3600)
    evs = check(now + 2 * 3600 + 60)
    assert len(evs) == 1 and f"#{other} " in evs[0]["text"] and f"#{tid} " not in evs[0]["text"], \
        "each owner has its own clock"
    stranger = p.db.add_task("unrelated", "s", kind="work", tier="light", origin="coordinator")
    with pytest.raises(ValueError, match="not a required owner"):
        ob.record(p, oid, "progress", "commit def", stranger, now=now + 2 * 3600 + 120)
    with pytest.raises(ValueError, match="needs evidence"):
        ob.record(p, oid, "progress", "  ", tid)


def test_obligation_done_without_receipt_stays_owed_until_a_receipt(env, monkeypatch):
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the urgent report", [tid], now=now)
    p.db.update_task(tid, status="done", result=json.dumps({"status": "done", "summary": "finished"}))
    assert check(now + 3600) == []
    assert ob.get(p.db, oid)["receipt"] is None and "owed" in ob.lines(p.db, now + 3600)[0]
    evs = check(now + 2 * 3600 + 60)
    assert len(evs) == 1 and f"#{tid} (done without a receipt)" in evs[0]["text"], evs[0]["text"]
    with pytest.raises(ValueError, match="is done"):
        ob.attach(p, ob.add(p, "another", now=now), [tid], now=now)
    ob.record(p, oid, "receipt", "report at docs/report.md, checked", None, now=now + 3 * 3600)
    assert ob.overdue(ob.get(p.db, oid), now + 99 * 3600) == []
    assert [e["fingerprint"] for e in check(now + 10 * 3600)].count(f"obligation:{oid}:1") == 1 \
        and not [e for e in check(now + 10 * 3600) if e["fingerprint"].startswith(f"obligation:{oid}:2")], \
        "a receipt ends it: nothing more is raised"
    assert "received" in ob.lines(p.db)[0]


def test_obligation_anomaly_is_raised_once_per_stall_with_no_timed_rewakes(env, monkeypatch):
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the urgent report", [tid], now=now)
    for h in (2.1, 3, 6, 24, 72):
        evs = check(now + h * 3600)
        assert len(evs) == 1, f"one keyed anomaly per obligation, not repeated on a timer ({h} h)"
    ob.record(p, oid, "progress", "commit abc", tid, now=now + 72 * 3600)
    assert len(check(now + 73 * 3600)) == 1, "fresh progress ends the stall"
    evs = check(now + 74.5 * 3600)
    assert len(evs) == 2 and evs[1]["fingerprint"] == f"obligation:{oid}:2", "a new stall is a new episode"
    assert len(check(now + 80 * 3600)) == 2


def test_obligation_without_owner_raises_after_the_clock(env, monkeypatch):
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    ob.add(p, "a deliverable nobody owns", now=now)
    assert check(now + 3600) == []
    evs = check(now + 2 * 3600 + 60)
    assert len(evs) == 1 and "no owner task is attached" in evs[0]["text"] and evs[0]["task"] is None


def _ob_job(p, monkeypatch, tid, now, name="bench"):
    """The owner waiting on a `ttp detach` job of its own run, held running (its job lock), and
    `report(at, reason)`: the job's own `ttp progress report result` at time `at`; `job.close()` kills it."""
    from ttp import cli, locks
    p.db.update_task(tid, status="waiting")
    run_dir = p.runs / f"r{tid}"
    run_dir.mkdir(parents=True, exist_ok=True)
    rid = p.db.x("INSERT INTO runs(task,role,started,ended,status,dir) VALUES(?,?,?,?,?,?)",
                 (tid, "worker", now + 60, now + 300, "done", str(run_dir)))
    rc = run_dir / f"{name}.rc"
    job = locks.try_take([locks.job_lock(rc)], "job")
    for k, v in {"TTP_PROJECT": str(p.base), "TTP_TASK": str(tid), "TTP_RUN_ID": str(rid),
                 "TTP_DETACH_RC": str(rc)}.items():
        monkeypatch.setenv(k, v)

    def report(at, reason, *args):
        monkeypatch.setattr(time, "time", lambda: at)
        try:
            cli.main(["progress", "report", "result", *args, reason])
        except SystemExit as e:
            assert not e.code, e.code
    return rc, job, report


def test_obligation_owner_waiting_on_its_live_job_with_a_new_result_is_not_overdue(env, monkeypatch):
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the benchmark table", [tid], now=now)
    rc, job, report = _ob_job(p, monkeypatch, tid, now)
    try:
        report(now + 1.5 * 3600, "cell 3 of 6 done")
        assert check(now + 2 * 3600 + 60) == [], "a live job's result within 2 h is durable progress"
        assert "OVERDUE" not in ob.lines(p.db, now + 2 * 3600 + 60)[0]
        report(now + 3 * 3600, "cell 4 of 6 done")
        assert check(now + 4 * 3600) == [], "each new result keeps it on time"
    finally:
        job.close()


def test_obligation_job_side_progress_report_records_progress_on_the_owners_obligation(env, monkeypatch):
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the benchmark table", [tid], now=now)
    rc, job, report = _ob_job(p, monkeypatch, tid, now)
    try:
        report(now + 1800, "cell 3 of 6 done")   # in the job: `ttp progress report result "<what>"`, no key
        check(now + 1860)
        own = ob.get(p.db, oid)["owners"][str(tid)]
        assert own["job"]["at"] == pytest.approx(now + 1800, abs=0.01) \
            and own["job"]["text"] == "job bench: cell 3 of 6 done", own
        assert f"#{tid} 0.5 h (job result 0.0 h ago)" in ob.lines(p.db, now + 1860)[0], ob.lines(p.db, now + 1860)
        report(now + 3600, "cell 4 of 6 done")
        check(now + 3660)
        assert ob.get(p.db, oid)["owners"][str(tid)]["job"]["text"] == "job bench: cell 4 of 6 done"
    finally:
        job.close()
    check(now + 3720)
    assert "job" not in ob.get(p.db, oid)["owners"][str(tid)], "a dead job's record goes"


def test_obligation_owner_on_a_live_job_with_no_new_result_for_2h_is_overdue(env, monkeypatch):
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the benchmark table", [tid], now=now)
    rc, job, report = _ob_job(p, monkeypatch, tid, now)
    try:
        report(now + 0.5 * 3600, "cell 1 of 6 done")
        assert check(now + 2 * 3600 + 60) == [], "kept on time while the result is under 2 h old"
        evs = check(now + 2.5 * 3600 + 60)
        assert len(evs) == 1 and evs[0]["fingerprint"] == f"obligation:{oid}:1", "a quiet live job does not keep it"
        assert "OVERDUE" in ob.lines(p.db, now + 2.5 * 3600 + 60)[0]
        # Results that never count: one with no job (the owner's own pid), and one from a job of
        # another task's run naming this task.
        now2 = now + 10 * 3600
        oid2 = ob.add(p, "another table", [tid], now=now2)
        monkeypatch.delenv("TTP_DETACH_RC")
        report(now2 + 3600, "a heartbeat with no job", "--key", "owner")
        other = p.db.add_task("other", "s", kind="work", tier="light", origin="coordinator")
        orc, ojob, oreport = _ob_job(p, monkeypatch, other, now2, name="theirs")
        p.db.update_task(tid, status="waiting")
        monkeypatch.setenv("TTP_TASK", str(tid))
        oreport(now2 + 3600, "forged cell")
        try:
            assert [e["fingerprint"] for e in check(now2 + 2 * 3600 + 60)][-1] == f"obligation:{oid2}:1"
        finally:
            ojob.close()
    finally:
        job.close()


def test_obligation_owner_on_a_dead_job_is_overdue_despite_a_recent_result(env, monkeypatch):
    from ttp import obligations as ob
    from ttp import progress
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the benchmark table", [tid], now=now)
    rc, job, report = _ob_job(p, monkeypatch, tid, now)
    report(now + 1.5 * 3600, "cell 3 of 6 done")
    assert check(now + 2 * 3600 + 30) == [], "kept on time while it runs"
    job.close()   # it died without an exit code
    evs = check(now + 2 * 3600 + 60)
    assert len(evs) == 1 and evs[0]["fingerprint"] == f"obligation:{oid}:1", "a dead job keeps nothing"
    assert rc.with_suffix(".lost").exists()
    # A job that ended (wrote its .rc) and one whose result came from another boot keep nothing either.
    oid2 = ob.add(p, "second table", [tid], now=now + 10 * 3600)
    rc2, job2, report2 = _ob_job(p, monkeypatch, tid, now + 10 * 3600, name="ended")
    try:
        report2(now + 11.5 * 3600, "cell 6 of 6 done")
        rc2.write_text("0")
        assert [e["fingerprint"] for e in check(now + 12 * 3600 + 60)][-1] == f"obligation:{oid2}:1"
    finally:
        job2.close()
    oid3 = ob.add(p, "third table", [tid], now=now + 20 * 3600)
    rc3, job3, report3 = _ob_job(p, monkeypatch, tid, now + 20 * 3600, name="reboot")
    try:
        report3(now + 21.5 * 3600, "cell 1 of 6 done")
        lines = (p.state / progress.LOG).read_text().splitlines()
        last = json.loads(lines[-1])
        last["boot"] = "an-older-boot"
        (p.state / progress.LOG).write_text("\n".join(lines[:-1] + [json.dumps(last)]) + "\n")
        assert [e["fingerprint"] for e in check(now + 22 * 3600 + 60)][-1] == f"obligation:{oid3}:1"
    finally:
        job3.close()


def _ob_detached(p, monkeypatch, tid, now, name="job1", **entry):
    """_ob_job, with the job's detached.json entry in its run's folder as `ttp detach` writes it, and
    the owner queued (its job relaunched after a reboot, say)."""
    rc, job, report = _ob_job(p, monkeypatch, tid, now, name=name)
    (rc.parent / "detached.json").write_text(json.dumps([{"name": name, "rc": str(rc), "log": str(rc.with_suffix(".log")),
                                                          "started": now, "status": "running", **entry}]))
    p.db.update_task(tid, status="queued")
    return rc, job, report


def test_obligation_owner_on_a_live_job_that_never_reports_is_named_with_both_fixes(env, monkeypatch):
    from ttp import obligations as ob
    from ttp import progress
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the results table", [tid], now=now)
    rc, job, report = _ob_detached(p, monkeypatch, tid, now)
    try:
        assert not (p.state / progress.LOG).exists()
        evs = check(now + 2 * 3600 + 60)
        assert len(evs) == 1 and evs[0]["fingerprint"] == f"obligation:{oid}:1", evs
        text = evs[0]["text"]
        assert f"#{tid} (queued) has no durable progress" in text and "job job1 (" in text and str(rc) in text, text
        assert "`ttp progress report result --key <k>" in text and "ttp detach --results <glob>" in text, text
        assert f"dispatch one light run of #{tid}" in text and f"ttp obligation progress {oid}" in text, text
        # One in-window result report from that job clears it.
        oid2 = ob.add(p, "the second table", [tid], now=now + 10 * 3600)
        report(now + 11.5 * 3600, "unit 3 of 6 done")
        assert [e["fingerprint"] for e in check(now + 12 * 3600 + 60)][-1] != f"obligation:{oid2}:1"
    finally:
        job.close()
    oid3 = ob.add(p, "the third table", [tid], now=now + 20 * 3600)
    evs = check(now + 22 * 3600 + 60)
    assert evs[-1]["fingerprint"] == f"obligation:{oid3}:1" and "job1" not in evs[-1]["text"], \
        "a job that is no longer running is not named"


def test_obligation_job_with_a_results_glob_keeps_its_owner_on_time_from_new_files(env, monkeypatch, tmp_path):
    import os
    from ttp import detach
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    work = tmp_path / "work"
    (work / "out").mkdir(parents=True)
    oid = ob.add(p, "the results table", [tid], now=now)
    rc, job, report = _ob_detached(p, monkeypatch, tid, now, results="out/*.json", cwd=str(work))

    def put(name, at):
        f = work / "out" / name
        f.write_text("{}")
        os.utime(f, (at, at))
    try:
        put("unit-1.json", now + 1.5 * 3600)
        put("notes.txt", now + 2 * 3600)   # not matching: never counts
        assert check(now + 2 * 3600 + 60) == [], "a new matching file in the window is a result"
        assert ob.get(p.db, oid)["owners"][str(tid)]["job"]["text"] == "job job1: new result file out/unit-1.json"
        evs = check(now + 3.6 * 3600)
        assert len(evs) == 1 and evs[0]["fingerprint"] == f"obligation:{oid}:1", "only a file older than the window"
        assert "declares results `out/*.json` but no new matching file in 2 h" in evs[0]["text"], evs[0]["text"]
        put("unit-2.json", now + 3.7 * 3600)
        check(now + 3.8 * 3600)
        assert "OVERDUE" not in ob.lines(p.db, now + 3.8 * 3600)[0], "a later file puts it back on time"
        # A relaunch after a reboot keeps the declaration; a file from before the job (re)started never counts.
        detach._restamp(rc, os.getpid(), "boot-2")
        entry = json.loads((rc.parent / "detached.json").read_text())[0]
        assert entry["results"] == "out/*.json" and entry["cwd"] == str(work)
        oid2 = ob.add(p, "the second table", [tid], now=now + 10 * 3600)
        entry["started"] = now + 11 * 3600
        (rc.parent / "detached.json").write_text(json.dumps([entry]))
        put("unit-3.json", now + 10.5 * 3600)
        assert [e["fingerprint"] for e in check(now + 12 * 3600 + 60)][-1] == f"obligation:{oid2}:1"
    finally:
        job.close()


def test_detach_start_notice_reminds_an_obligation_owner_to_report_results(env, monkeypatch, tmp_path):
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the results table", [tid], now=now)
    other = p.db.add_task("other", "s", kind="work", tier="light", origin="coordinator")
    for n, (task, flags) in enumerate(((tid, []), (tid, ["--results", "out/*.json"]), (other, []))):
        run_dir = p.runs / str(70 + n)
        run_dir.mkdir(parents=True)
        r = _ttp_run(p, "detach", "job1", *flags, "--", "true",
                     env={"TTP_HOME": str(env["home"]), "TTP_HOST": "testhost", "TTP_RUN_DIR": str(run_dir),
                          "TTP_TASK": str(task), "TTP_RUN_ID": str(70 + n)})
        assert r.returncode == 0, r.stderr
        reminded = f"obligation {oid}: this job keeps it on time only while it reports results" in r.stdout
        assert reminded == (n == 0), (n, r.stdout)
        assert ("`ttp progress report result --key <k>" in r.stdout) == (n == 0), r.stdout
        entry = json.loads((run_dir / "detached.json").read_text())[0]
        assert (entry.get("results"), entry.get("cwd")) == (("out/*.json", str(p.root)) if n == 1 else (None, None))
        assert ("results: each new file matching out/*.json" in r.stdout) == (n == 1), r.stdout
    run_dir = p.runs / "80"
    run_dir.mkdir(parents=True)
    for bad in ("/abs/*.json", " "):
        r = _ttp_run(p, "detach", "job1", "--results", bad, "--", "true",
                     env={"TTP_HOME": str(env["home"]), "TTP_RUN_DIR": str(run_dir), "TTP_TASK": str(tid)})
        assert r.returncode != 0 and "--results needs a glob relative" in r.stderr, r.stderr


