def _ob_queued(p):
    return [(e["fingerprint"], e["status"]) for e in
            p.db.q("SELECT * FROM events WHERE fingerprint LIKE 'obligation:%' ORDER BY id")]


@pytest.mark.parametrize("resolve", ["milestone", "receipt", "drop"])
def test_obligation_resolved_milestone_episode_retires_its_queued_event_only(env, monkeypatch, resolve):
    from ttp import obligations as ob
    from ttp.daemon import Daemon
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "report", [tid], now=now, milestones=[
        {"key": "report", "due": now + 30, "evidence_required": "checked report"},
        {"key": "deploy", "due": now + 40, "evidence_required": "running deploy"}])
    other = p.db.add_task("other deliverable", "s", kind="work", tier="light", origin="coordinator")
    o2 = ob.add(p, "other", [other], now=now, milestones=[
        {"key": "report", "due": now + 30, "evidence_required": "checked report"}])
    late = now + ob.CLOCK_S + 60
    check(late)
    # A handled event of the same obligation keeps its status and data (history is not rewritten).
    p.db.x("INSERT INTO events(ts,source,kind,fingerprint,severity,text,status) VALUES(?,?,?,?,?,?,?)",
           (now, "daemon", "obligation_overdue", f"obligation:{oid}:milestone:report:0", "high", "old", "handled"))
    mine = {f"obligation:{oid}:milestone:report:1", f"obligation:{oid}:milestone:deploy:1"}
    stall = f"obligation:{oid}:1"
    assert {f for f, st in _ob_queued(p) if st == "queued" and f.startswith(f"obligation:{oid}:")} == mine | {stall}
    Daemon(p.base)   # a restart before the resolution changes nothing
    at = late + 10
    if resolve == "milestone":
        ob.record(p, oid, "receipt", "checked report", tid, now=at, milestone="report")
        gone = {f"obligation:{oid}:milestone:report:1"}
    elif resolve == "receipt":
        ob.record(p, oid, "receipt", "checked deliverable", tid, now=at)
        gone = mine
    else:
        ob.drop(p, oid, "no longer owed", now=at)
        gone = mine
    check(at + 10)
    st = dict(_ob_queued(p))
    assert {f for f in mine if st[f] == "handled"} == gone
    assert {f for f in mine if st[f] == "queued"} == mine - gone
    assert st[stall] == "queued", "the 2 h stall event keeps the rules it had before milestones"
    assert st[f"obligation:{oid}:milestone:report:0"] == "handled"
    assert p.db.one("SELECT data FROM events WHERE fingerprint=?", (f"obligation:{oid}:milestone:report:0",))["data"] is None
    assert st[f"obligation:{o2}:milestone:report:1"] == "queued", "another obligation's episode stays pending"
    queued = {e["id"] for e in p.db.q("SELECT id FROM events WHERE status='queued'")}
    assert not {e["id"] for e in p.db.q("SELECT id FROM events WHERE fingerprint IN (%s)" % ",".join("?" * len(gone)),
                                        list(gone))} & queued, "the coordinator's pending events lose it"


def _ob_quiet_until_the_clock(p, monkeypatch, oid, check, now):
    """No obligation event while the owners wait or move through review, across a restart; the 2 h
    durable-progress clock is the only rule that catches owners that all wait or stall (known gap)."""
    from ttp import obligations as ob
    from ttp.daemon import Daemon
    check(now + 5)
    check(now + 60)
    Daemon(p.base)
    check(now + 120)
    assert _ob_queued(p) == [], "an owner waiting or in review is not stuck: no event, no coordinator wake"
    assert check(now + ob.CLOCK_S - 60) == []
    assert [e["fingerprint"] for e in check(now + ob.CLOCK_S + 60)] == [f"obligation:{oid}:1"]
    assert [f for f, _ in _ob_queued(p)] == [f"obligation:{oid}:1"]


@pytest.mark.parametrize("wait", ["waiting", "resource_busy", "start_when_no_reason", "review_checks"])
def test_obligation_queued_owner_waiting_raises_no_event(env, monkeypatch, wait):
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "report", [tid], now=now)
    if wait == "waiting":     # an ordinary waiting hand-off on its own detached job
        p.db.update_task(tid, not_before=now + 900,
                         blocked_reason="waiting for its detached build; its probe says not yet; next try 10:00 PDT")
    elif wait == "resource_busy":     # the daemon's 30 s backoff after losing the race for a resource
        p.db.update_task(tid, not_before=now + 30,
                         blocked_reason="its resource stayed busy before the run could start; retries")
    elif wait == "start_when_no_reason":     # a reasoned deferral is asleep by design (test_obligation_owner_asleep_*)
        p.db.update_task(tid, labels=json.dumps(["start_when:false"]))
    else:     # the owner is in review and its reviewer waits on its own detached checks
        p.db.update_task(tid, kind="code", status="review", branch="feature/owed")
        rid = p.db.add_task(f"Review #{tid}: build the deliverable", "review feature/owed", kind="review",
                            tier="light", origin="daemon", depends_on=[tid], labels=[f"auto_review:{tid}"])
        p.db.update_task(rid, not_before=now + 900, blocked_reason="waiting for ttp checks --detach; its probe says not yet")
    _ob_quiet_until_the_clock(p, monkeypatch, oid, check, now)


QUOTA_RESET_H = 6   # the owner sleeps until an external quota reset this far ahead


def _ob_sleep(p, tid, now, kind, probe=None):
    """Put owner `tid` to sleep by design on a model-free wake (an external quota reset QUOTA_RESET_H ahead)."""
    from ttp.db import dump_result
    wake = now + QUOTA_RESET_H * 3600
    if kind == "retry_when":
        probe = probe or f'test "$(date +%s)" -ge {int(wake)}'
        # The daemon's shape (#4078): queued, not_before ahead while the probe says not yet.
        p.db.update_task(tid, status="queued", not_before=wake,
                         blocked_reason="waiting for an external quota reset; its probe says not yet",
                         result=dump_result({"status": "waiting", "waiting_for": "an external quota reset",
                                             "retry_when": probe, "waiting_since": now + 600}))
    elif kind == "start_after":
        p.db.update_task(tid, status="queued", not_before=wake,
                         labels=json.dumps([f"start_after:{wake}", "start_why:an external quota reset"]))
    else:
        p.db.update_task(tid, status="queued", labels=json.dumps(
            [f"start_when:{probe or 'test -e /nonexistent/quota-reset'}", "start_why:an external quota reset",
             f"deferred_since:{now + 600}"]))
    return wake


@pytest.mark.parametrize("kind", ["retry_when", "start_after", "start_when"])
def test_obligation_owner_asleep_on_a_model_free_wake_is_not_stalled(env, monkeypatch, kind):
    """An owner asleep by design until an external quota reset cannot record progress: the 2 h stall line
    and obligation_overdue stay quiet for the whole wait, every check, and lines() says what it sleeps on."""
    from ttp import obligations as ob, startgate
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the benchmark table", [tid], now=now)
    _ob_sleep(p, tid, now, kind)
    if kind == "start_when":   # the daemon's last answer: not yet
        startgate.record(p.db, tid, "test -e /nonexistent/quota-reset", 1, "not yet", now + 700)
    for h in (2.1, 3, 4.1, 5.9):
        assert check(now + h * 3600) == [], f"no stall while it sleeps on its {kind} ({h} h)"
    line = ob.lines(p.db, now + 5.9 * 3600)[0]
    assert f"#{tid} asleep on {kind}" in line and "OVERDUE" not in line, line
    assert ob.items(p.db)[0]["owners"][str(tid)]["sleep"]["what"].startswith(kind), oid


@pytest.mark.parametrize("kind", ["retry_when", "start_after", "start_when"])
def test_obligation_owner_stalls_again_two_hours_after_its_wake(env, monkeypatch, kind):
    from ttp import obligations as ob, startgate
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the benchmark table", [tid], now=now)
    wake = _ob_sleep(p, tid, now, kind)
    assert check(now + 3 * 3600) == []
    if kind == "retry_when":     # the probe passed: _probe_passed makes it due now, still queued, no `woke`
        p.db.update_task(tid, not_before=wake)
    elif kind == "start_when":   # its start_when passed: it starts
        startgate.record(p.db, tid, "test -e /nonexistent/quota-reset", 0, "passed", wake)
    seen = wake if kind == "start_after" else wake + 300   # a start_after's wake is known; else the check that saw it
    assert check(wake + 300) == [], "the clock restarts from the wake"
    p.db.update_task(tid, status="running")
    assert check(seen + ob.CLOCK_S - 60) == []
    evs = check(seen + ob.CLOCK_S + 60)
    assert [e["fingerprint"] for e in evs] == [f"obligation:{oid}:1"] and f"#{tid} (running)" in evs[0]["text"], \
        "two hours after the wake with no progress raise again"


def test_obligation_retry_when_owner_queued_for_a_slot_after_its_probe_passed_stalls(env, monkeypatch):
    """The daemon's waiting shape (#4078: queued, result.status waiting, retry_when, waiting_since,
    waiting_for): quiet past 2 h while not_before is ahead; once the probe passes (not_before brought to
    now, no `woke` key) and it sits queued for a slot, it raises 2 h after that."""
    from ttp import obligations as ob
    from ttp.db import load_result
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the benchmark table", [tid], now=now)
    _ob_sleep(p, tid, now, "retry_when")
    t = p.db.task(tid)
    assert t["status"] == "queued" and load_result(t["result"])["status"] == "waiting"
    assert check(now + 2.1 * 3600) == [] and check(now + 4 * 3600) == []
    passed = now + 4.5 * 3600   # before its scheduled wake: the probe passed early
    p.db.update_task(tid, not_before=passed)
    assert "woke" not in load_result(p.db.task(tid)["result"])
    assert check(passed + 60) == []
    assert check(passed + 60 + ob.CLOCK_S - 120) == []
    evs = check(passed + 60 + ob.CLOCK_S + 60)
    assert [e["fingerprint"] for e in evs] == [f"obligation:{oid}:1"], "2 h after the probe passed it raises"


def test_obligation_start_after_wake_counts_from_the_wake_not_the_next_check(env, monkeypatch):
    """A start_after's wake is known: a check that first sees the owner awake hours later raises at once."""
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the benchmark table", [tid], now=now)
    wake = _ob_sleep(p, tid, now, "start_after")
    assert check(now + 3 * 3600) == []
    evs = check(wake + ob.CLOCK_S + 60)
    assert [e["fingerprint"] for e in evs] == [f"obligation:{oid}:1"]


@pytest.mark.parametrize("kind", ["retry_when", "start_after", "start_when"])
def test_obligation_milestone_raises_while_its_owner_sleeps(env, monkeypatch, kind):
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
