@pytest.mark.parametrize("case", ["running", "queued", "woke", "no_reason", "own_job_probe", "live_job",
                                  "broken_start_when", "dead_ref", "past_defer_max", "start_after_passed"])
def test_obligation_owner_not_asleep_by_design_still_stalls(env, monkeypatch, case):
    """Only a reasoned model-free sleep covers an owner: running or plain queued owners, a woken wait, a wait
    with no reason, a probe on its own detach job (the job rule governs), a broken or dead probe, a wait past
    coordinator.defer_max_days and a start_after already past still stall after 2 h."""
    from ttp import obligations as ob, startgate
    from ttp.db import load_result, dump_result
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the benchmark table", [tid], now=now)
    if case == "running":
        p.db.update_task(tid, status="running")
    elif case == "woke":
        _ob_sleep(p, tid, now, "retry_when")
        p.db.update_task(tid, result=dump_result({**load_result(p.db.task(tid)["result"]), "woke": "probe broken: exit 2"}))
    elif case == "no_reason":
        p.db.update_task(tid, status="queued", not_before=now + 6 * 3600, result=dump_result(
            {"status": "waiting", "retry_when": "false", "waiting_since": now + 600}))
    elif case == "own_job_probe":
        _ob_sleep(p, tid, now, "retry_when", probe="ttp detach --check /tmp/run/bench")
    elif case == "live_job":
        _ob_sleep(p, tid, now, "retry_when")
        monkeypatch.setattr(ob, "_live_jobs", lambda _p, _st: {str(tid): [{"name": "bench", "rc": "/tmp/bench.rc"}]})
    elif case == "broken_start_when":
        _ob_sleep(p, tid, now, "start_when")
        startgate.record(p.db, tid, "test -e /nonexistent/quota-reset", 2, "syntax error", now + 700)
    elif case == "dead_ref":
        gone = p.db.add_task("the build it waits on", "s", kind="work", tier="light", origin="coordinator")
        p.db.update_task(gone, status="cancelled")
        _ob_sleep(p, tid, now, "retry_when", probe=f"landed:#{gone}")
    elif case == "past_defer_max":
        cfg = p.config()
        cfg.setdefault("coordinator", {})["defer_max_days"] = 0.05   # 1.2 h
        monkeypatch.setattr(type(p), "config", lambda self: cfg)
        d.cfg = cfg
        _ob_sleep(p, tid, now, "start_when")
    elif case == "start_after_passed":
        p.db.update_task(tid, labels=json.dumps([f"start_after:{now + 60}", "start_why:an external quota reset"]))
    evs = check(now + ob.CLOCK_S + 60)
    assert [e["fingerprint"] for e in evs] == [f"obligation:{oid}:1"], case


def test_obligation_owner_in_review_with_rereview_of_done_fix_raises_no_event(env, monkeypatch):
    """The daemon's fix stack: the owner is in review, its review failed, the fix (continues:<owner>) is
    done and the re-review (auto_review:<fix>) runs."""
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "report", [tid], now=now)
    p.db.update_task(tid, kind="code", status="review", branch="feature/owed")
    rid = p.db.add_task(f"Review #{tid}: build the deliverable", "review feature/owed", kind="review",
                        tier="light", origin="daemon", depends_on=[tid], labels=[f"auto_review:{tid}"])
    p.db.update_task(rid, status="failed")
    fid = p.db.add_task("Fix review", "fix it", kind="code", tier="light", origin="daemon",
                        labels=[f"continues:{tid}", f"review_fix:{rid}"])
    p.db.update_task(fid, status="done", branch="feature/owed-fix")
    rr = p.db.add_task(f"Re-review #{rid}", "review feature/owed-fix", kind="review", tier="light",
                       origin="daemon", depends_on=[fid], labels=[f"auto_review:{fid}", f"continues:{rid}"])
    p.db.update_task(rr, status="running")
    _ob_quiet_until_the_clock(p, monkeypatch, oid, check, now)


def _refwait_ask(p, handled=0):
    return p.db.x("INSERT INTO messages(ts,direction,kind,text,handled) VALUES(?,?,?,?,?)",
                  (time.time(), "out", "ask", "which way?", handled))


def _ref_wait(p, waiting_for, probe=None, **kw):
    """A queued task asleep on a waiting hand-off that names something in its waiting_for."""
    nb = time.time() + 3600
    tid = p.db.add_task("follow up", "s", kind="work", tier="light", origin="user", not_before=nb, **kw)
    res = {"status": "waiting", "waiting_for": waiting_for, "waiting_since": time.time() - 60,
           "retry_after_s": 3600, **({"retry_when": probe} if probe else {})}
    p.db.update_task(tid, result=json.dumps(res), blocked_reason=f"waiting for {waiting_for}; next try later",
                     attempts=1)
    return tid, nb


def test_ref_wait_parser_names_asks_and_tasks_not_prs_or_itself():
    from ttp.refwaits import refs
    assert refs("ask #12 and task #34, then #56", own=99) == [("ask", 12), ("task", 34), ("task", 56)]
    assert refs("PR #55 and issue #9 and run #3") == []
    assert refs("task #7 lands", own=7) == []


def test_a_resolved_ask_refreshes_a_waits_note_and_reruns_its_probe_now(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    dep = p.db.add_task("dep", "s", kind="work", origin="user")
    ask = _refwait_ask(p)
    tid, nb = _ref_wait(p, f"the answer to ask #{ask}", probe="false", depends_on=[dep])
    other, _ = _ref_wait(p, "something else", probe="false")
    before = p.db.task(tid)
    d._probe_rc[tid] = (1, time.time(), "false")
    d._probe_rc[other] = (1, time.time(), "false")   # a shared verdict from before the answer
    d._probed[tid] = time.time()
    d.refresh_ref_waits()
    assert p.db.task(tid)["updated"] == before["updated"]   # the ask is still open: nothing to do
    p.db.x("UPDATE messages SET handled=1 WHERE id=?", (ask,))
    d.refresh_ref_waits()
    t = p.db.task(tid)
    assert f"ask #{ask} is resolved" in t["blocked_reason"] and "probe runs again now" in t["blocked_reason"]
    assert tid not in d._probe_rc and other not in d._probe_rc and tid not in d._probed
    res = json.loads(t["result"])
    assert res["retry_when"] == "false" and res["waiting_since"] == json.loads(before["result"])["waiting_since"]
    assert t["not_before"] == nb and t["attempts"] == 1 and json.loads(t["depends_on"]) == [dep]
    assert t["labels"] == before["labels"] and t["status"] == "queued"
    d.probe_waiting()
    assert tid in d._probes   # rechecked at once, not after PROBE_EVERY_S
    d._probes[tid][0].wait(10)
    # A later rewrite of the note (its probe still says not yet) keeps the fact, not the stale reason.
    d._probe_rc[tid] = (1, time.time(), "false")
    d._hold_waiting(p.db.task(tid), json.loads(p.db.task(tid)["result"]), time.time())
    assert f"ask #{ask} is resolved" in p.db.task(tid)["blocked_reason"]


def test_a_done_task_never_wakes_a_probe_less_wait_across_hand_offs(env):
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    dep = p.db.add_task("upstream fix", "s", kind="code", origin="user", status="done")
    tid, _ = _ref_wait(p, f"#{dep} to land on the branch")
    for i in range(3):   # three hand-offs in a row, each a new wait naming the task already done
        nb = time.time() + 3600 + i
        res = {"status": "waiting", "waiting_for": f"#{dep} to land on the branch",
               "waiting_since": time.time() + i, "retry_after_s": 3600}
        p.db.update_task(tid, result=json.dumps(res), not_before=nb, blocked_reason="waiting")
        d.refresh_ref_waits()
        d.probe_waiting()
        t = p.db.task(tid)
        assert t["not_before"] == nb and t["attempts"] == 1 and t["status"] == "queued"
        assert f"task #{dep} is done" in t["blocked_reason"] and "not proof" in t["blocked_reason"]
        assert "woke" not in json.loads(t["result"]) and tid not in d._probes
    assert (p.logs / "daemon.log").read_text().count(f"task {tid} wait note refreshed") == 3


def test_a_ref_wait_keeps_its_planned_window_and_start_after(env):
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    dep = p.db.add_task("dep", "s", kind="work", origin="user", status="done")
    tid, nb = _ref_wait(p, f"a 2 h soak window after task #{dep}")
    d.refresh_ref_waits()
    t = p.db.task(tid)
    assert t["not_before"] == nb and "keeps its own window" in t["blocked_reason"]
    # A start_when task naming an ask: its probe reruns, but only after its start_after.
    ask = _refwait_ask(p, handled=1)
    after = time.time() + 7200
    sw = p.db.add_task("later", "s", kind="work", origin="user", not_before=after,
                       labels=["start_when:false", f"start_why:ask #{ask} answered",
                               f"start_after:{after:.0f}", f"deferred_since:{time.time():.0f}"])
    labels = p.db.task(sw)["labels"]
    d._start_rc[sw] = (1, time.time(), "false")
    d.refresh_ref_waits()
    t = p.db.task(sw)
    assert t["labels"] == labels and t["not_before"] == after and sw not in d._start_rc
    assert "after its start_after" in t["blocked_reason"]
    d.probe_waiting()
    assert sw not in d._probes
    # Once due, a start_when that names a resolved ask is probed at once.
    sw2 = p.db.add_task("now", "s", kind="work", origin="user",
                        labels=["start_when:false", f"start_why:ask #{ask} answered",
                                f"deferred_since:{time.time():.0f}"])
    d._probed[sw2] = time.time()
    d.refresh_ref_waits()
    assert "probe runs again now" in p.db.task(sw2)["blocked_reason"]
    d.probe_waiting()
    assert sw2 in d._probes
    d._probes[sw2][0].wait(10)


def _fake_runtime(root, version, commit="0123456789abcdef0123"):
    """A runtime folder (runtime/ttp/__init__.py, SOURCE_COMMIT) and a module object as if imported from it."""
    pkg = root / "runtime" / "ttp"
    pkg.mkdir(parents=True, exist_ok=True)
    (pkg / "__init__.py").write_text(f'__version__ = "{version}"\n')
    if commit is None:
        (pkg / "SOURCE_COMMIT").unlink(missing_ok=True)
    else:
        (pkg / "SOURCE_COMMIT").write_text(commit + "\n")
    return types.SimpleNamespace(__name__="ttp_fake", __file__=str(pkg / "__init__.py"), __version__=version)


def test_identity_receipt_is_captured_once_and_survives_file_rewrites(env, tmp_path):
    p = make(env)
    import ttp
    from ttp import identity
    from ttp.daemon import Daemon, heartbeat, start_marker
    d = Daemon(p.base)
    assert d.identity["version"] == ttp.__version__ and d.identity["pid"] == os.getpid()
    assert d.identity["boot"] == d.boot and d.identity["instance"]
    mod = _fake_runtime(tmp_path, "9.9.1")
    d.identity = identity.capture(mod=mod, boot=d.boot, started=d._started)
    assert d.identity["provenance"] == "verified", d.identity
    assert d.identity["commit"] == "0123456789abcdef0123"
    d._mark_start()
    d._beat()
    _fake_runtime(tmp_path, "9.9.2", commit="fedcba9876543210")   # a deploy rewrites the files under it
    d._healthy = False   # the heartbeat is written in full again
    d._beat()
    hb = heartbeat(p)
    assert hb["receipt"]["version"] == "9.9.1" and hb["receipt"]["commit"] == "0123456789abcdef0123"
    assert hb["receipt"] == d.identity == start_marker(p)["receipt"]
    # mixed or missing provenance is unverified, never assumed
    mixed = types.SimpleNamespace(__name__="ttp_fake", __file__=mod.__file__, __version__="9.9.1")
    assert identity.capture(mod=mixed)["provenance"] == "unverified"   # files say 9.9.2
    assert identity.capture(mod=_fake_runtime(tmp_path, "9.9.3", commit=None))["provenance"] == "unverified"


def test_old_daemon_heartbeat_reads_as_unverified_never_as_the_files_version(env):
    p = make(env)
    from ttp import overview
    from ttp.cli import status_text
    from ttp.release import runtime_version
    from ttp.web import health
    files = runtime_version(p.harness / "runtime")
    (p.state / "heartbeat").write_text(json.dumps({"pid": os.getpid(), "host": "testhost", "started": time.time()}))
    p.db.set_kv("daemon", {"pid": os.getpid(), "host": "testhost"})
    rt = health(p, p.db)["runtime"]
    assert rt["running_version"] == "unverified" and rt["files_version"] == files and not rt["restart_pending"]
    text = status_text(p)
    assert "running version unverified" in text and f"running {files}" not in text
    row = overview.project_status(p.name, {"host": "testhost", "dir": str(p.root)}, time.time(), "testhost",
                                  files, (time.time() - 86400, time.time()))
    assert row["running_version"] == "unverified" and row["running_commit"] is None
    assert "running version unverified" in overview.line(row)


def test_overview_and_status_flag_running_code_older_than_its_files(env, tmp_path):
    p = make(env)
    from ttp import identity, overview, timefmt
    from ttp.cli import status_text
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.identity = identity.capture(mod=_fake_runtime(tmp_path, "0.0.1"), boot=d.boot, started=d._started)
    d._beat()
    p.db.set_kv("daemon", {"pid": os.getpid(), "host": "testhost"})
    now = time.time()
    entry = {"host": "testhost", "dir": str(p.root)}
    row = overview.project_status(p.name, entry, now, "testhost", "0.0.1", (now - 86400, now))
    assert row["running_version"] == "0.0.1" and row["files_version"] == "0.0.1" and not row["restart_pending"]
    assert row["instance"] == d.identity["instance"] and row["tick_done"]
    assert f"running 0.0.1 (0123456789ab) since {timefmt.short(d._started, p)}" in status_text(p)
    _fake_runtime(tmp_path, "0.0.2")   # new files on disk, the process still runs the old code
    row = overview.project_status(p.name, entry, now, "testhost", "0.0.2", (now - 86400, now))
    assert row["running_version"] == "0.0.1" and row["files_version"] == "0.0.2" and row["restart_pending"]
    assert "restart pending: running 0.0.1" in overview.line(row)
    assert "restart pending: running 0.0.1, files 0.0.2" in status_text(p)


def test_tick_done_does_not_advance_on_progress_touches(env):
    p = make(env)
    from ttp.daemon import Daemon, heartbeat
    d = Daemon(p.base)
    d._beat()
    old = time.time() - 600
    for f in ("heartbeat", "tick_done"):
        os.utime(p.state / f, (old, old))
    assert abs(heartbeat(p)["tick_done"] - old) < 1
    d._progressed = 0.0
    d._progress()   # a step of a long tick: the heartbeat is fresh, the tick not done
    hb = heartbeat(p)
    assert hb["age"] < 60 and abs(hb["tick_done"] - old) < 1
    d._beat()
    assert heartbeat(p)["tick_done"] > old + 500
    # another daemon's tick file is never read as this one's
    (p.state / "tick_done").write_text(json.dumps({"instance": "someone-else", "pid": 1}))
    assert heartbeat(p)["tick_done"] is None


def test_api_state_and_health_carry_the_runtime_receipt(env):
    p = make(env)
    from ttp import web
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d._beat()
    p.db.set_kv("daemon", {"pid": os.getpid(), "host": "testhost"})
    h = web.health(p, p.db)["runtime"]
    assert h["running_version"] == d.identity["version"] and h["instance"] == d.identity["instance"]
    assert h["tick_done"] and h["line"].startswith(f"running {d.identity['version']}")
    st = json.loads(json.dumps(web.state_payload(p, p.db), default=str))
    assert st["heartbeat"]["receipt"]["instance"] == d.identity["instance"]
    assert st["runtime"]["instance"] == st["health"]["runtime"]["instance"] == d.identity["instance"]
    assert st["heartbeat"]["tick_done"] == st["runtime"]["tick_done"]


def _failover_setup(env, util=91.0, hours=150.0):
    """A project on the fake core provider with codex's 7d plan window at `util`%, resetting in `hours`."""
    from ttp import budget as bud
    from ttp.daemon import Daemon
    p = make(env)
    now = time.time()
    bud.record_windows(p.db, [bud.Window("codex", "seven_day", util, now + hours * 3600)])
    d = Daemon(p.base)
    return p, d, now


def _codex_task(p, title="deep design", **kw):
    tid = p.db.add_task(title, "Design the thing.", kind="work", tier="standard", provider="codex",
                        model="research-model-1", effort="xhigh", **kw)
    return tid


def test_failover_moves_a_codex_pinned_task_off_a_red_window_and_maps_its_effort(env):
    p, d, now = _failover_setup(env)
    tid = _codex_task(p)
    waiting = _codex_task(p, "waits on a job")
    p.db.update_task(waiting, status="waiting")
    d.update_gates()
    assert d.gates["codex"].level == "red" and not d.gates["codex"].allow_new_work
    d.failover_pinned()
    for i in (tid, waiting):
        t = p.db.task(i)
        assert (t["provider"], t["model"], t["effort"], t["tier"]) == ("fake", None, "xhigh", "deep"), t
        assert "[provider failover" in t["spec"] and "moved at once from codex (model research-model-1, effort xhigh) " \
            "to fake" in t["spec"].lower() and "until " in t["spec"]
        assert t["spec"].startswith("Design the thing.\n\n")
    ev = p.db.q("SELECT * FROM events WHERE kind='provider_failover' ORDER BY id")
    assert [e["task"] for e in ev] == [tid, waiting] and all(e["severity"] == "low" for e in ev)
    out = p.db.q("SELECT * FROM messages WHERE direction='out' AND text LIKE 'Provider failover:%'")
    assert len(out) == 1 and out[0]["severity"] == "low", "one low alert per batch of moves"
    from ttp import failover, sweep
    assert len(failover.review_lines(p.db)) == 2
    assert sweep._spec_sha(p.db.task(tid)) == sweep._spec_sha({"spec": "Design the thing."}), \
        "the failover note counts as a spec change (LOOP flag)"
    d._failover_checked = 0
    d.failover_pinned()
    assert len(p.db.q("SELECT id FROM events WHERE kind='provider_failover'")) == 2, "moved twice"


def test_failover_leaves_tasks_when_the_reset_is_near_or_failover_is_off(env):
    # Codex is the core provider here: its own tasks wait out a stop shorter than the threshold.
    p, d, now = _failover_setup(env, hours=2)
    p.set_config("core_provider", "codex")
    p.set_config("providers.fake", {"tiers": {}})
    p.set_config("coordinator.provider_failover_to", ["fake"])
    d._load_config()
    tid = p.db.add_task("on the core provider", "Do it.", kind="work", tier="standard")
    d.update_gates()
    assert d.gates["codex"].level == "red"
    d.failover_pinned()
    assert p.db.task(tid)["provider"] is None, "moved although codex resets within the threshold"
    p.set_config("coordinator.provider_failover_after_h", 1)
    d._load_config()
    d._failover_checked = 0
    d.failover_pinned()
    assert p.db.task(tid)["provider"] == "fake", "a 1 h threshold moves a task whose provider resets in 2 h"
    p.set_config("core_provider", "fake")
    d._load_config()
    other = _codex_task(p, "second")
    p.set_config("coordinator.provider_failover_after_h", 0)
    d._load_config()
    d._failover_checked = 0
    d.failover_pinned()
    assert p.db.task(other)["provider"] == "codex", "0 turns failover off"


def test_failover_keeps_a_required_pin_and_its_review_chain(env):
    p, d, now = _failover_setup(env)
    req = _codex_task(p, labels=["pin:required"])
    review = p.db.add_task("review it", "", kind="review", provider="codex", model="research-model-1",
                           effort="xhigh", labels=[f"auto_review:{req}"])
    d.update_gates()
    d.failover_pinned()
    for i in (req, review):
        t = p.db.task(i)
        assert (t["provider"], t["model"], t["effort"]) == ("codex", "research-model-1", "xhigh")
    assert not p.db.q("SELECT id FROM events WHERE kind='provider_failover'")


def test_failover_never_touches_a_running_task_and_reports_it_once(env):
    p, d, now = _failover_setup(env)
    tid = _codex_task(p)
    p.db.update_task(tid, status="running")
    d.update_gates()
    for _ in range(2):
        d._failover_checked = 0
        d.failover_pinned()
    t = p.db.task(tid)
    assert (t["provider"], t["model"], t["effort"], t["spec"]) == ("codex", "research-model-1", "xhigh",
                                                                    "Design the thing.")
    (ev,) = p.db.q("SELECT * FROM events WHERE kind='provider_failover'")
    assert ev["task"] == tid and "left running on codex" in ev["text"]


def test_failover_stop_reads_each_reason_for_red_and_its_end(env):
    from ttp import failover
    now = 1000.0
    red = lambda reasons, **n: {"level": "red", "allow_new_work": False, "reasons": reasons, "numbers": n}  # noqa: E731
    plan = [{"window": "seven_day", "allowed": 0, "resets_at": now + 9e5}, {"window": "five_hour", "allowed": 3}]
    assert failover.stop(red(["seven_day window at 91%; the project stops at 90% until it resets"], plan=plan),
                         None, False, now)[1] == now + 9e5
    assert failover.stop(red(["runaway guard: $9 spent"]), None, False, now)[1] == now + 3600
    assert failover.stop(red(["cap reached: $9/day of $5, $9/7d of $50"]), None, False, now) is None, \
        "a rolling cap has no known end"
    assert failover.stop({"level": "orange", "allow_new_work": True}, None, False, now) is None
    assert failover.stop(None, {"until": now + 50, "note": "limit"}, False, now) == ("provider limit: limit", now + 50)
    assert failover.stop(None, None, True, now) == ("logged out", None)
    assert failover.hold(red(["cap reached: $9/day of $5, $9/7d of $50"]), None, False, now) == \
        ("cap reached: $9/day of $5, $9/7d of $50", None), "a hold with no known end still holds"
    assert failover.hold({"level": "orange", "allow_new_work": True}, None, False, now) is None
    assert failover.kept_effort("claude", "xhigh") == "xhigh" and failover.kept_effort("claude", "minimal") == "low"
    assert failover.kept_effort("codex", "max") == "xhigh" and failover.kept_effort("cursor", "high") is None
    assert failover.kept_effort("codex", None) is None
    cfg = {"core_provider": "claude", "providers": {"claude": {}, "codex": {"tiers": {"deep": {"effort": "xhigh"}}}},
           "coordinator": {"provider_failover_to": ["codex", "nope"]}}
    assert failover.targets(cfg) == ["codex", "claude"]
    assert failover.mapped_tier(cfg, "codex", {"effort": "xhigh", "tier": "standard"}) == "deep"
    assert failover.mapped_tier(cfg, "claude", {"effort": "low", "tier": "deep"}) == "light"
    assert failover.mapped_tier(cfg, "codex", {"effort": None, "tier": "standard"}) == "standard"


def test_failover_moves_an_unmarked_pin_at_once_and_keeps_a_required_one_held(env):
    # Codex resets in 2 h, well within the 4 h threshold, and its red gate's end may even be unknown:
    # a pin the user's words do not require is a preference and moves to the core provider at once.
    p, d, now = _failover_setup(env, hours=2)
    pref = _codex_task(p, "preference", budget_usd=3.5)
    req = _codex_task(p, "required", labels=["pin:required"])
    d.update_gates()
    d.failover_pinned()
    t = p.db.task(pref)
    assert (t["provider"], t["model"], t["effort"], t["tier"], t["budget_usd"]) == \
        ("fake", None, "xhigh", "deep", 3.5), "an unmarked pin did not fail over at once with its effort and budget"
    r = p.db.task(req)
    assert (r["provider"], r["model"], r["effort"], r["status"]) == ("codex", "research-model-1", "xhigh", "queued")
    (ev,) = p.db.q("SELECT * FROM events WHERE kind='provider_failover'")
    assert ev["task"] == pref and ev["severity"] == "low"
    assert "moved at once from codex" in ev["text"] and "to fake" in ev["text"] and "preference" in ev["text"]
    assert not p.db.q("SELECT id FROM events WHERE kind='provider_failover' AND task=?", (req,))
    from ttp import failover
    # A red gate with no known end (a rolling cap) holds a preference pin too.
    red = {"level": "red", "allow_new_work": False, "reasons": ["cap reached: $9/day of $5"], "numbers": {}}
    held = {"codex": failover.hold(red, None, False, now)}
    other = _codex_task(p, "rolling cap")
    moves, _ = failover.plan(p.db, d.cfg, {}, ["fake"], now, held)
    assert [m["task"]["id"] for m in moves] == [other] and moves[0]["at_once"] and moves[0]["new"] == "fake"


def test_pin_required_is_set_by_the_coordinator_and_kept_by_continues(env):
    from ttp import failover
    from ttp.coordinator import apply
    p, d, now = _failover_setup(env)
    probs = apply(p, [{"type": "task_add", "title": "no pin", "spec": "x", "pin_required": True}])
    assert any("pin_required needs a provider pin" in x for x in probs), probs
    assert apply(p, [{"type": "task_add", "title": "user asked for codex", "spec": "The user said: use codex.",
                      "provider": "codex", "effort": "xhigh", "pin_required": True},
                     {"type": "task_add", "title": "codex preferred", "spec": "y", "provider": "codex"}]) == []
    req = p.db.one("SELECT * FROM tasks WHERE title='user asked for codex'")
    pref = p.db.one("SELECT * FROM tasks WHERE title='codex preferred'")
    assert failover.required(p.db, req) and not failover.required(p.db, pref), "an unmarked pin is a preference"
    assert apply(p, [{"type": "task_update", "id": pref["id"], "pin_required": True}]) == []
    assert failover.required(p.db, p.db.task(pref["id"]))
    assert apply(p, [{"type": "task_update", "id": pref["id"], "pin_required": False}]) == []
    assert not failover.required(p.db, p.db.task(pref["id"]))
    # A continuation keeps the mark with its provider; pin_required false makes it a preference.
    p.db.update_task(req["id"], status="failed")
    assert apply(p, [{"type": "task_add", "title": "user asked for codex, again", "spec": "z",
                      "continues": req["id"]}]) == []
    cont = p.db.one("SELECT * FROM tasks WHERE title='user asked for codex, again'")
    assert cont["provider"] == "codex" and failover.required(p.db, cont)
    p.db.update_task(cont["id"], status="failed")
    assert apply(p, [{"type": "task_add", "title": "codex only preferred now", "spec": "w",
                      "continues": cont["id"], "pin_required": False}]) == []
    later = p.db.one("SELECT * FROM tasks WHERE title='codex only preferred now'")
    assert later["provider"] == "codex" and not failover.required(p.db, later)
    d.update_gates()
    d.failover_pinned()
    assert p.db.task(later["id"])["provider"] == "fake" and p.db.task(pref["id"])["provider"] == "fake"


def test_failover_settings_are_known_keys_and_settable_from_cli_and_chat(env, capsys):
    from ttp import cli, failover
    from ttp.coordinator import apply
    from ttp.project import DEFAULT_CONFIG, config_problems, unknown_key_hint
    p, d, now = _failover_setup(env)
    for key in ("coordinator.provider_failover_after_h", "coordinator.provider_failover_to"):
        assert unknown_key_hint(key) is None, key
    assert DEFAULT_CONFIG["coordinator"]["provider_failover_after_h"] == failover.AFTER_H
    # The CLI sets 0, which turns failover off.
    cli.main(["config", p.name, "coordinator.provider_failover_after_h", "0"])
    assert p.config()["coordinator"]["provider_failover_after_h"] == 0
    tid = _codex_task(p)
    d._load_config()
    d.update_gates()
    d.failover_pinned()
    assert p.db.task(tid)["provider"] == "codex", "0 set through the CLI turns failover off"
    for bad in ("soon", "-1"):
        with pytest.raises(SystemExit):
            cli.main(["config", p.name, "coordinator.provider_failover_after_h", bad])
    with pytest.raises(SystemExit):
        cli.main(["config", p.name, "coordinator.provider_failover_to", '["nosuch"]'])
    # The coordinator's config_set: a threshold, then a target list checked against the providers.
    assert apply(p, [{"type": "config_set", "key": "coordinator.provider_failover_after_h", "value": "1"},
                     {"type": "config_set", "key": "coordinator.provider_failover_to", "value": "claude, codex"}]) == []
    assert p.config()["coordinator"]["provider_failover_after_h"] == 1.0
    assert p.config()["coordinator"]["provider_failover_to"] == ["claude", "codex"]
    probs = apply(p, [{"type": "config_set", "key": "coordinator.provider_failover_after_h", "value": "-2"},
                      {"type": "config_set", "key": "coordinator.provider_failover_to", "value": "nosuch"}])
    assert any("hours >= 0" in x for x in probs) and any("not a configured provider: nosuch" in x for x in probs)
    assert p.config()["coordinator"]["provider_failover_after_h"] == 1.0
    assert config_problems(p.raw_config()) == []
    d._load_config()
    d._failover_checked = 0
    d.failover_pinned()
    assert p.db.task(tid)["provider"] != "codex", "1 h set through config_set turns failover back on"


DEPLOY_C = "abcdef0123456789abcd"


def _deploy_lib(version, commit=DEPLOY_C):
    from ttp import project
    lib = project.HOME_DIR / "lib" / "current" / "runtime" / "ttp"
    lib.mkdir(parents=True, exist_ok=True)
    (lib / "__init__.py").write_text(f'__version__ = "{version}"\n')
    (lib / "SOURCE_COMMIT").write_text(commit + "\n")


def _deploy_project(tmp_path, name, files, running=None, commit=DEPLOY_C, receipt=True, tick_age=5.0):
    """A registered project whose harness files are at `files` and whose daemon (this process) reports
    by its receipt that it runs `running` (default: the files' version), last tick `tick_age` s ago."""
    base, db = _overview_project(tmp_path, name, files)
    rt = base / "harness" / "runtime"
    (rt / "ttp" / "SOURCE_COMMIT").write_text(commit + "\n")
    old = time.time() - 3600       # the files were installed an hour ago
    for f in ("__init__.py", "SOURCE_COMMIT"):
        os.utime(rt / "ttp" / f, (old, old))
    pid = os.getpid()
    db.set_kv("daemon", {"pid": pid, "host": "testhost", "started": old})
    hb = {"pid": pid, "host": "testhost"}
    if receipt:
        inst = f"inst-{name}"
        hb["receipt"] = {"version": running or files, "commit": commit, "runtime": str(rt), "pid": pid,
                         "started": old, "instance": inst, "provenance": "verified"}
        (base / "state" / "tick_done").write_text(json.dumps({"instance": inst, "pid": pid}))
        t = time.time() - tick_age
        os.utime(base / "state" / "tick_done", (t, t))
    (base / "state" / "heartbeat").write_text(json.dumps(hb))
    return base, db


def test_deployed_accepts_only_every_daemons_own_receipt(env, tmp_path, capsys):
    from ttp import overview
    from ttp.cli import main
    _deploy_lib("0.5.0")
    _, a = _deploy_project(tmp_path, "alpha", "0.5.0")
    _, b = _deploy_project(tmp_path, "beta", "0.5.0")
    before = _tree(tmp_path / "alpha"), _tree(tmp_path / "beta")
    r = overview.deployed()
    assert r["rc"] == 0 and [x["state"] for x in r["projects"]] == [0, 0], r["text"]
    assert r["text"].splitlines()[0] == "tt-project 0.5.0 (abcdef012345): deployed to all 2 projects on this machine"
    with pytest.raises(SystemExit) as e:
        main(["deployed", "0.5.0", "--commit", DEPLOY_C[:10]])
    assert e.value.code == 0
    # strictly read-only
    assert (_tree(tmp_path / "alpha"), _tree(tmp_path / "beta")) == before
    # another commit of the same version is not this deploy
    with pytest.raises(SystemExit) as e:
        main(["deployed", "0.5.0", "--commit", "1234567890"])
    assert e.value.code == 1
    # a project registered after the deploy started is checked too: its daemon still runs old code
    _, c = _deploy_project(tmp_path, "gamma", "0.5.0", running="0.4.9")
    capsys.readouterr()
    with pytest.raises(SystemExit) as e:
        main(["deployed"])
    out = capsys.readouterr().out
    assert e.value.code == 1, out
    line = next(x for x in out.splitlines() if x.startswith("gamma\t"))
    assert "pending: files at 0.5.0, daemon still runs 0.4.9" in line and "restart pending" in line, out
    assert "owner: this project's daemon" in line and "resumes when it restarts" in line, out
    assert "alpha\tok: running 0.5.0" in out
    # --projects narrows the check
    assert overview.deployed(names=["alpha", "beta"])["rc"] == 0
    assert overview.deployed(names=["alpha", "nosuch"])["rc"] == 2
    for x in (a, b, c):
        x.close()


def test_deployed_counts_a_deferred_merge_as_pending_with_owner_and_resume_time(env, tmp_path):
    from ttp import overview, release, timefmt
    _deploy_lib("0.5.0")
    _deploy_project(tmp_path, "alpha", "0.5.0")
    base, db = _deploy_project(tmp_path, "beta", "0.4.9")   # its merge conflicted: files stay old
    until = time.time() + 7 * 3600
    db.set_kv(release.KV_AUTO, {"key": "0.5.0 x", "to": "0.5.0", "outcome": "deferred", "until": until,
                                "why": "the merge conflicts in prompts/worker.md"})
    r = overview.deployed()
    beta = next(x for x in r["projects"] if x["name"] == "beta")
    assert r["rc"] == 1 and beta["state"] == 1, r["text"]
    at = timefmt.short(until, overview._settings(base), time.time())
    assert beta["line"].startswith("beta\tpending: files at 0.4.9: merge deferred (the merge conflicts in "
                                   "prompts/worker.md); daemon runs 0.4.9"), beta["line"]
    assert f"resumes at {at}, owner: this project's daemon" in beta["line"], beta["line"]
    # a finish task holding the merge owns it
    tid = db.add_task(release.UPGRADE_TASK_TITLE, "merge", kind="harness")
    (base / "state" / "locks").mkdir(parents=True, exist_ok=True)
    (base / "state" / "locks" / f"{release.UPGRADE_RESOURCE}.task").write_text(
        json.dumps({"task": tid, "key": "0.5.0 x", "target": "0.5.0"}))
    beta = next(x for x in overview.deployed()["projects"] if x["name"] == "beta")
    assert beta["state"] == 1 and f"merge held by harness task #{tid} (queued)" in beta["line"], beta["line"]
    assert beta["line"].endswith(f"owner: harness task #{tid}"), beta["line"]
    assert "resumes when it ends, or at " in beta["line"]
    db.close()


def test_deployed_cannot_tell_without_a_receipt_and_waits_for_a_fresh_tick(env, tmp_path):
    from ttp import overview
    _deploy_lib("0.5.0")
    base, db = _deploy_project(tmp_path, "alpha", "0.5.0", receipt=False)   # a daemon older than receipts
    r = overview.deployed()
    assert r["rc"] == 2 and "cannot tell: daemon" in r["projects"][0]["line"], r["text"]
    assert "no runtime receipt" in r["projects"][0]["line"]
    # unverified provenance cannot tell either
    _deploy_project(tmp_path, "beta", "0.5.0")
    bb = tmp_path / "beta" / "tt-project" / "state" / "heartbeat"
    hb = json.loads(bb.read_text())
    hb["receipt"].update(provenance="unverified", why="no SOURCE_COMMIT")
    bb.write_text(json.dumps(hb))
    beta = overview.deployed(names=["beta"])
    assert beta["rc"] == 2 and "receipt unverified: no SOURCE_COMMIT" in beta["text"], beta["text"]
    # the matching receipt with a stale completed tick is pending, however fresh its heartbeat
    _deploy_project(tmp_path, "gamma", "0.5.0", tick_age=1200)
    g = overview.deployed(names=["gamma"])
    assert g["rc"] == 1 and "last completed tick was 20 min ago" in g["text"], g["text"]
    assert overview.deployed(names=["gamma"], fresh_s=3600)["rc"] == 0
    # a tick that completed before the files were installed does not count
    _deploy_project(tmp_path, "delta", "0.5.0", tick_age=7200)
    d = overview.deployed(names=["delta"], fresh_s=86400)
    assert d["rc"] == 1 and "has not completed a tick since the files were installed" in d["text"], d["text"]
    # a stopped daemon is pending; a missing project database cannot tell
    gb = tmp_path / "gamma" / "tt-project" / "state" / "project.db"
    from ttp.db import DB
    g_db = DB(gb)
    g_db.set_kv("daemon", {"pid": 0, "host": "testhost"})
    g_db.close()
    assert overview.deployed(names=["gamma"])["rc"] == 1
    from ttp import project
    project.register("epsilon", {"host": "testhost", "dir": str(tmp_path / "missing")})
    assert overview.deployed(names=["epsilon"])["rc"] == 2
    db.close()


def test_status_and_deployed_agree_on_the_daemon_when_the_pid_probe_fails(env, tmp_path, capsys, monkeypatch):
    """A sandboxed worker's pid probe fails for a live daemon: `ttp status` (its text, and the
    runtime.running_* fields of --json) and `ttp deployed` all read the same fresh heartbeat, and all
    say not running once it is stale."""
    from ttp import daemon as dmod, overview
    from ttp.cli import daemon_state, main
    from ttp.project import Project
    _deploy_lib("0.5.0")
    base, db = _deploy_project(tmp_path, "alpha", "0.5.0")
    monkeypatch.setattr(dmod, "_alive", lambda pid: False)
    monkeypatch.setenv("TTP_RUN_DIR", str(tmp_path / "run"))
    hb = base / "state" / "heartbeat"

    def views():
        capsys.readouterr()
        main(["status", "alpha", "--json"])
        rt = json.loads(capsys.readouterr().out)["runtime"]
        return daemon_state(Project(base.parent)), rt, overview.deployed("0.5.0", names=["alpha"])

    os.utime(hb, None)
    state, rt, dep = views()
    assert state.startswith("running (heartbeat "), state
    assert (rt["running_version"], rt["running_commit"], rt["instance"], rt["source"]) == (
        "0.5.0", DEPLOY_C, "inst-alpha", "heartbeat"), rt
    row = dep["projects"][0]
    assert dep["rc"] == 0 and row["daemon_alive"] and row["daemon_state"] == "running", dep["text"]
    assert row["running_version"] == rt["running_version"] and row["instance"] == rt["instance"]
    # a fresh heartbeat of another pid than the daemon record names is not that daemon
    db.set_kv("daemon", {"pid": os.getpid() + 1, "host": "testhost"})
    assert daemon_state(Project(base.parent)) != "running" and not overview.deployed(
        "0.5.0", names=["alpha"])["projects"][0]["daemon_alive"]
    db.set_kv("daemon", {"pid": os.getpid(), "host": "testhost"})
    # between fresh and stale: unknown from the sandbox, not alive for either
    mid = time.time() - 200
    os.utime(hb, (mid, mid))
    state, rt, dep = views()
    assert state == "status unknown from this sandbox" and rt["running_version"] is None, (state, rt)
    assert dep["rc"] == 1 and not dep["projects"][0]["daemon_alive"], dep["text"]
    # stale: every view says not running
    old = time.time() - dmod.HEARTBEAT_STALE_S - 60
    os.utime(hb, (old, old))
    state, rt, dep = views()
    assert state == "NOT RUNNING" and rt["running_version"] is None and rt["source"] is None, (state, rt)
    row = dep["projects"][0]
    assert dep["rc"] == 1 and not row["daemon_alive"] and row["daemon_state"] == "stopped", dep["text"]
    db.close()


def _ttp_sources() -> list[tuple[str, pathlib.Path]]:
    """(dotted module name, path) of every module in the ttp package, subpackages included."""
    pkg = RUNTIME / "ttp"
    out = []
    for f in sorted(pkg.rglob("*.py")):
        parts = list(f.relative_to(RUNTIME).with_suffix("").parts)
        if parts[-1] == "__init__":
            parts.pop()
        out.append((".".join(parts), f))
    return out


def _sibling_imports(name: str, path: pathlib.Path) -> tuple[dict, list]:
    """For one ttp module: {local name: sibling module} for its `from . import x` (anywhere in the
    file), and [(lineno, sibling module, attr)] for each `from .x import attr`."""
    import ast
    aliases, froms = {}, []
    for node in ast.walk(ast.parse(path.read_text(), str(path))):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            got = _imported_modules(name, path, node)
            aliases.update(got[0])
            froms += got[1]
    return aliases, froms


def _imported_modules(name: str, path: pathlib.Path, node) -> tuple[dict, list]:
    import ast
    import importlib.util
    pkg = name if path.name == "__init__.py" else name.rpartition(".")[0]
    aliases, froms = {}, []
    if isinstance(node, ast.ImportFrom) and node.level:
        base = importlib.util.resolve_name("." * node.level + (node.module or ""), pkg)
        for a in node.names:
            if node.module:
                froms.append((node.lineno, base, a.name))
            else:
                aliases[a.asname or a.name] = f"{base}.{a.name}"
    elif isinstance(node, ast.Import):
        for a in node.names:
            if a.name.startswith("ttp.") and a.asname:
                aliases[a.asname] = a.name
    return aliases, froms


def _module_attribute_refs(name: str, path: pathlib.Path) -> list[tuple[int, str, str, str]]:
    """[(lineno, local name, sibling module, attr)] for each `x.attr` where x names a sibling module in
    that scope: a function's own imports and local names (a parameter or variable called like a
    module) shadow the enclosing scope's."""
    import ast
    tree = ast.parse(path.read_text(), str(path))
    scopes = (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)
    out = []

    def own_nodes(scope):   # the nodes of a scope, not those of the functions nested in it
        todo = list(ast.iter_child_nodes(scope))
        while todo:
            n = todo.pop()
            yield n
            if not isinstance(n, scopes):
                todo.extend(ast.iter_child_nodes(n))

    def visit(scope, outer: dict):
        mods, bound = {}, set()
        if isinstance(scope, scopes):
            a = scope.args
            bound |= {x.arg for x in [*a.posonlyargs, *a.args, *a.kwonlyargs, a.vararg, a.kwarg] if x}
        for n in own_nodes(scope):
            if isinstance(n, (ast.Import, ast.ImportFrom)):
                got = _imported_modules(name, path, n)[0]
                mods.update(got)
                bound |= {a.asname or a.name.split(".")[0] for a in n.names} - set(got)
            elif isinstance(n, ast.Name) and isinstance(n.ctx, (ast.Store, ast.Del)):
                bound.add(n.id)
            elif isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                bound.add(n.name)
        seen = {k: v for k, v in outer.items() if k not in bound or k in mods}
        seen.update(mods)
        for n in own_nodes(scope):
            if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name) and n.value.id in seen:
                out.append((n.lineno, n.value.id, seen[n.value.id], n.attr))
            if isinstance(n, scopes):
                visit(n, seen)

    visit(tree, {})
    return out


def test_every_cross_module_attribute_between_ttp_modules_resolves():
    """A `push.scalar_problem` in batch.py, or a `from .push import scalar_problem`, names an attribute
    the sibling module really has: a rename or removal in one module cannot leave a caller that only
    fails at run time (an AttributeError in a rarely taken path, such as after_push)."""
    import importlib
    import importlib.util
    missing, checked = [], 0
    for name, path in _ttp_sources():
        for lineno, mod, attr in _sibling_imports(name, path)[1]:
            m = importlib.import_module(mod)
            checked += 1
            if not hasattr(m, attr) and importlib.util.find_spec(f"{mod}.{attr}") is None:
                missing.append(f"{path.name}:{lineno}: from {mod} import {attr}")
        for lineno, local, mod, attr in _module_attribute_refs(name, path):
            checked += 1
            if not hasattr(importlib.import_module(mod), attr):
                missing.append(f"{path.name}:{lineno}: {local}.{attr}")
    assert checked > 500   # the walk really found the references
    assert not missing, "references to attributes the sibling module lacks:\n" + "\n".join(missing)


def test_the_cross_module_attribute_check_sees_a_missing_attribute_and_respects_scope(tmp_path):
    src = tmp_path / "ttp" / "fake.py"
    src.parent.mkdir()
    src.write_text("from . import push\n\n\ndef a():\n    return push.no_such_name\n\n\n"
                   "def b(push):\n    return push.get\n\n\ndef c():\n    push = {}\n    return push.get\n\n\n"
                   "def d():\n    from . import db as push\n    return push.DB\n")
    refs = {(ln, attr): mod for ln, _, mod, attr in _module_attribute_refs("ttp.fake", src)}
    assert refs == {(5, "no_such_name"): "ttp.push", (19, "DB"): "ttp.db"}


def test_a_push_process_loads_every_module_of_its_push_and_after_push_path_at_start():
    """An upgrade may replace runtime/ while a `ttp push` runs. A sibling module first imported late
    (batch for after_push) would then be the new version calling into the old, already loaded push
    module (batch calling a push.scalar_problem the old push lacked: AttributeError, after_push failed,
    the mirror left behind). So push, pushq and batch import their sibling modules at module level,
    never inside a function, and importing push alone loads them all."""
    import ast
    path_mods = ("push", "pushq", "batch")
    late = []
    for mod in path_mods:
        f = RUNTIME / "ttp" / f"{mod}.py"
        tree = ast.parse(f.read_text(), str(f))
        top = {id(n) for n in tree.body}
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom) and node.level and id(node) not in top:
                late.append(f"{mod}.py:{node.lineno}: from {'.' * node.level}{node.module or ''} import "
                            + ", ".join(a.name for a in node.names))
    assert not late, "sibling imports inside functions on the push path:\n" + "\n".join(late)
    needs = {}   # each path module: the sibling modules it uses
    for mod in path_mods:
        aliases, froms = _sibling_imports(f"ttp.{mod}", RUNTIME / "ttp" / f"{mod}.py")
        needs[f"ttp.{mod}"] = sorted(set(aliases.values()) | {m for _, m, _ in froms})
    assert "ttp.batch" in needs["ttp.push"]
    for entry in ("ttp.push", "ttp.batch", "ttp.pushq"):   # whichever a process imports first
        code = (f"import sys, {entry}\n"
                f"print(' '.join(sorted({{n for m, ns in {needs!r}.items() if m in sys.modules for n in ns}}"
                f" - set(sys.modules))))")
        out = subprocess.run([sys.executable, "-c", code], cwd=RUNTIME, capture_output=True, text=True,
                             env={**os.environ, "PYTHONPATH": str(RUNTIME)})
        assert out.returncode == 0, out.stderr
        assert out.stdout.strip() == "", f"importing {entry} leaves unloaded: {out.stdout.strip()}"


@pytest.mark.parametrize("note, severity", [("usage limit reached", "low"), ("rate limit", "low"),
                                            ("Insufficient credits", "high"), ("spending limit", "high")])
def test_a_limited_run_alerts_by_who_can_lift_the_limit(note, severity):
    from ttp.providers.base import FUNDS_RE, LIMIT_RE
    assert LIMIT_RE.search(note)
    assert (severity == "high") == bool(FUNDS_RE.search(note))


def test_coordinator_timeout_defaults_ceiling_and_prompt_size():
    from ttp import coordlimits
    from ttp.project import DEFAULT_CONFIG
    cfg = DEFAULT_CONFIG
    assert coordlimits.turn_timeout(cfg, "codex", "low", 1000) == 300
    assert coordlimits.turn_timeout(cfg, "codex", "high", 1000) == 1200
    assert coordlimits.turn_timeout(cfg, "codex", "xhigh", 1000) == 1800
    assert coordlimits.turn_timeout(cfg, "claude", "high", 1000) == 900
    assert coordlimits.turn_timeout(cfg, "codex", "xhigh", 49000) > 1800
    assert coordlimits.turn_timeout(cfg, "unknown", "unknown", 1000) == 600
    custom = {"coordinator": {"turn_timeout_s": 999999, "turn_timeout_ceiling_s": 999999}}
    assert coordlimits.turn_timeout(custom, "codex", "xhigh", 99999999) == 3600
    custom["coordinator"]["turn_timeout_ceiling_s"] = 500
    assert coordlimits.turn_timeout(custom, "codex", "xhigh", 99999999) == 500
    custom = {"coordinator": {"turn_timeouts_s": {"codex": {"high": 1350}}}}
    assert coordlimits.turn_timeout(custom, "codex", "high", 1000) == 1350
    for bad in (None, "broken", float("nan"), float("inf"), -1):
        assert coordlimits.turn_timeout({"coordinator": {"turn_timeout_ceiling_s": bad}}, "codex", "xhigh", 0) == 1800


def test_blocker_sweep_batches_fit_budget_and_cover_every_item_once(env):
    from ttp import sweep
    p = make(env)
    now = time.time()
    for n in range(75):
        t = p.db.add_task(f"Blocked item {n} " + "x" * 150)
        p.db.update_task(t, status="blocked", blocked_reason="reason " * 200)
    eid = sweep.start(p.db, p.config(), "every 6h", now)
    cfg = {"coordinator": {"sweep_prompt_chars": 2048}}
    seen = []
    while (event := p.db.one("SELECT * FROM events WHERE kind=? AND status='queued' ORDER BY id", (sweep.SWEEP_KIND,))):
        sweep.prepare(p.db, event["id"], cfg, now)
        event = p.db.one("SELECT * FROM events WHERE id=?", (event["id"],))
        keys = json.loads(event["data"])["items"]
        assert f"{len(keys)} stuck item(s) in this batch" in event["text"]
        text = "\n".join(sweep.digest_lines(p.db, [event["id"]], now))
        assert len(text) <= 2048
        assert len([line for line in text.splitlines() if line.startswith("- ")]) == len(keys)
        seen.extend(keys)
        # A retry must not manufacture another continuation or lose coverage.
        count = p.db.one("SELECT COUNT(*) n FROM events")["n"]
        sweep.prepare(p.db, event["id"], cfg, now)
        assert p.db.one("SELECT COUNT(*) n FROM events")["n"] == count
        p.db.x("UPDATE events SET status='handled' WHERE id=?", (event["id"],))
    assert len(seen) == 75 and len(set(seen)) == 75
    assert eid


@pytest.mark.parametrize("pin,expected", [("", "xhigh"), ("xhigh", "xhigh"), ("low", "low")])
def test_coordinator_launch_uses_resolved_effort_and_records_timeout(env, monkeypatch, pin, expected):
    from types import SimpleNamespace
    from ttp import daemon
    p = make(env)
    p.set_config("coordinator.model", "reasoning-model")
    p.set_config("coordinator.effort", pin)
    p.set_config("coordinator.turn_timeouts_s.fake", {"low": 300, "high": 1200, "xhigh": 1800})
    d = daemon.Daemon(p.base)
    d.update_gates()
    real_popen = daemon.subprocess.Popen
    monkeypatch.setattr(daemon.subprocess, "Popen", lambda argv, **k: SimpleNamespace(pid=123456789)
                        if argv[1:3] == ["-m", "ttp.runner"] else real_popen(argv, **k))
    monkeypatch.setattr(daemon.runner, "proc_start", lambda pid: None)
    logs = []
    monkeypatch.setattr(daemon, "log", lambda p, text: logs.append(text))
    rid = d.start_run("coordinator", "digest é", "fake", "light", str(p.base), read_only=True,
                      system="system", context="context")
    row = p.db.one("SELECT * FROM runs WHERE id=?", (rid,))
    spec = json.loads((pathlib.Path(row["dir"]) / "run.json").read_text())
    details = json.loads(row["note"])["turn"]
    assert details == {"provider": "fake", "model": "reasoning-model", "effort": expected,
                       "prompt_bytes": len("digest ésystemcontext".encode()),
                       "timeout_s": {"low": 300, "high": 1200, "xhigh": 1800}[expected],
                       "cache_ttl": "", "cache_ttl_why": "configured"}
    assert spec["timeout_s"] == details["timeout_s"] and spec["effort"] == expected
    d.finish_run(row, {"rc": 1, "stopped": "timeout", "ended": time.time()})
    finished = p.db.one("SELECT * FROM runs WHERE id=?", (rid,))
    assert finished["status"] == "timeout"
    assert json.loads(finished["note"])["turn"] == details
    assert p.db.kv("last_coordinator_timeout") == {"run": rid, "at": p.db.kv("last_coordinator_timeout")["at"], **details}
    assert any("timed out" in line and '"timeout_s"' in line and '"prompt_bytes"' in line for line in logs)


def test_coordinator_dispatch_keeps_sweep_continuations_in_separate_turns(env, monkeypatch):
    from ttp import sweep
    p, d, clock, calls = _routine_turn(env, monkeypatch)
    p.db.x("DELETE FROM events")
    p.set_config("coordinator.sweep_prompt_chars", 2048)
    d.cfg = p.config()
    for n in range(30):
        tid = p.db.add_task(f"stuck {n}")
        p.db.update_task(tid, status="blocked", blocked_reason="evidence " * 30)
    eid = sweep.start(p.db, p.config(), "every 6h", clock[0] - 60)
    # Also exercise an event queued by an older runtime with no persisted snapshot.
    data = json.loads(p.db.one("SELECT data FROM events WHERE id=?", (eid,))["data"])
    data.pop("snapshot")
    p.db.x("UPDATE events SET data=? WHERE id=?", (json.dumps(data), eid))
    d.maybe_coordinate()
    assert len(calls) == 1
    assert p.db.one("SELECT COUNT(*) n FROM events WHERE status='queued'")["n"] > 1
    first = calls[0][1]["note"]["events"]
    assert first == [eid]
    p.db.x("UPDATE events SET status='handled' WHERE id=?", (eid,))
    clock[0] += 60
    d.maybe_coordinate()
    second = calls[1][1]["note"]["events"]
    assert len(second) == 1 and second != first
    assert "## Blocker sweep" in calls[1][0][1]


def test_coordinator_timeout_explicit_overrides_win_over_legacy_and_defaults(env):
    from ttp import coordlimits
    p = make(env)
    tt = coordlimits.turn_timeout
    # An existing project that stored the old flat default still gets effort sizing.
    p.set_config("coordinator.turn_timeout_s", 600)
    cfg = p.config()
    assert tt(cfg, "codex", "high", 0) == 1200 and tt(cfg, "claude", "low", 0) == 300
    # Its own table entry wins, shorter or longer than the default, over a stored legacy value.
    p.set_config("coordinator.turn_timeouts_s.codex.high", 450)
    p.set_config("coordinator.turn_timeouts_s.codex.low", 700)
    cfg = p.config()
    assert tt(cfg, "codex", "high", 0) == 450 and tt(cfg, "codex", "low", 0) == 700
    assert tt(cfg, "codex", "xhigh", 0) == 1800   # entries not set keep the built-in default
    # Any other legacy value is a choice: it wins over the built-in table, never over a table entry.
    p.set_config("coordinator.turn_timeout_s", 90)
    cfg = p.config()
    assert tt(cfg, "codex", "xhigh", 0) == 90 and tt(cfg, "claude", "max", 0) == 90
    assert tt(cfg, "codex", "high", 0) == 450
    # The prompt allowance is added to every base; the ceilings cap every result.
    assert tt(cfg, "codex", "xhigh", 32000 + 8001) == 90 + 120
    assert tt(cfg, "codex", "high", 32000 + 8000) == 450 + 60
    p.set_config("coordinator.turn_timeout_ceiling_s", 400)
    cfg = p.config()
    assert tt(cfg, "codex", "high", 0) == 400 and tt(cfg, "codex", "low", 0) == 400
    assert tt(cfg, "codex", "xhigh", 10**9) == 400
    p.set_config("coordinator.turn_timeout_ceiling_s", 10**6)
    p.set_config("coordinator.turn_timeouts_s.codex.high", 10**6)
    assert tt(p.config(), "codex", "high", 0) == 3600
    # Bad explicit values fall through to the next source, never to zero or infinity.
    for bad in (0, -5, "x", None, float("nan"), float("inf")):
        cfg = {"coordinator": {"turn_timeouts_s": {"codex": {"high": bad}}, "turn_timeout_s": bad}}
        assert tt(cfg, "codex", "high", 0) == 1200


def _snapshotless_sweep(p, now):
    from ttp import sweep
    eid = sweep.start(p.db, p.config(), "every 6h", now)
    data = json.loads(p.db.one("SELECT data FROM events WHERE id=?", (eid,))["data"])
    data.pop("snapshot")   # the format an older runtime queued
    p.db.x("UPDATE events SET data=? WHERE id=?", (json.dumps(data), eid))
    return eid


def test_sweep_upgrade_keeps_items_resolved_before_prepare(env):
    from ttp import sweep
    from ttp.db import PAUSED_RESOURCES_KEY
    p = make(env)
    now = time.time()
    tid = p.db.add_task("stuck one")
    p.db.update_task(tid, status="blocked", blocked_reason="needs a fix")
    p.db.set_kv(PAUSED_RESOURCES_KEY, {"box-a": {"since": now - 3600, "by": "user", "reason": "maintenance"}})
    eid = _snapshotless_sweep(p, now)
    # Both clear before the upgraded runtime prepares the event.
    p.db.update_task(tid, status="done")
    p.db.set_kv(PAUSED_RESOURCES_KEY, {})
    later = p.db.add_task("stuck later")
    p.db.update_task(later, status="blocked", blocked_reason="new")
    for _ in range(2):   # a restart retries prepare on the same event
        sweep.prepare(p.db, eid, {}, now)
        data = json.loads(p.db.one("SELECT data FROM events WHERE id=?", (eid,))["data"])
        assert sorted(data["items"]) == sorted([f"task:{tid}", "resource:box-a"])
        assert p.db.one("SELECT COUNT(*) n FROM events WHERE kind=?", (sweep.SWEEP_KIND,))["n"] == 1
    text = "\n".join(sweep.digest_lines(p.db, [eid], now))
    assert f"#{tid} stuck one | resolved" in text and "no longer stuck (now done)" in text
    assert "resource box-a | resumed" in text and f"#{later} " not in text
    # The turn can record how each ended.
    assert sweep.record(p.db, {"id": tid, "outcome": "closed"}, None, now) == f"task:{tid}"
    assert sweep.record(p.db, {"resource": "box-a", "outcome": "unblocked"}, None, now) == "resource:box-a"


def test_sweep_upgrade_continuations_stay_disjoint_with_resolved_items(env):
    from ttp import sweep
    p = make(env)
    now = time.time()
    tids = []
    for n in range(30):
        tids.append(p.db.add_task(f"stuck {n} " + "x" * 100))
        p.db.update_task(tids[-1], status="blocked", blocked_reason="evidence " * 30)
    eid = _snapshotless_sweep(p, now)
    for tid in tids[::3]:
        p.db.update_task(tid, status="done")
    cfg = {"coordinator": {"sweep_prompt_chars": 2048}}
    seen = []
    while (event := p.db.one("SELECT * FROM events WHERE kind=? AND status='queued' ORDER BY id", (sweep.SWEEP_KIND,))):
        sweep.prepare(p.db, event["id"], cfg, now)
        sweep.prepare(p.db, event["id"], cfg, now)
        keys = json.loads(p.db.one("SELECT data FROM events WHERE id=?", (event["id"],))["data"])["items"]
        text = "\n".join(sweep.digest_lines(p.db, [event["id"]], now))
        assert len(text) <= 2048 and len([ln for ln in text.splitlines() if ln.startswith("- ")]) == len(keys)
        seen.extend(keys)
        p.db.x("UPDATE events SET status='handled' WHERE id=?", (event["id"],))
    assert sorted(seen) == sorted(f"task:{t}" for t in tids) and eid

# Provider credits and free window resets (credits.py) ------------------------------------------------
def _credit_answer(**over):
    """A rate-limit answer shaped like the Codex app-server's: windows, paid credits, free resets."""
    ans = {"rateLimits": {"primary": {"usedPercent": 20, "windowDurationMins": 300, "resetsAt": 1700000000},
                          "secondary": {"usedPercent": 93, "windowDurationMins": 10080, "resetsAt": 1700500000},
                          "credits": {"hasCredits": False, "unlimited": False, "balance": "0"},
                          "spendControlReached": False, "planType": "plus", "rateLimitReachedType": None},
           "rateLimitResetCredits": {"availableCount": 2, "credits": [
               {"id": "late", "resetType": "codexRateLimits", "status": "available", "expiresAt": 1800000000},
               {"id": "early", "resetType": "codexRateLimits", "status": "available", "expiresAt": 1790000000},
               {"id": "gone", "status": "consumed", "expiresAt": 1700000000}]}}
    ans.update(over)
    return ans


def test_credits_parse_reads_every_field_and_takes_missing_or_malformed_as_unknown():
    from ttp import credits
    r = credits.parse(_credit_answer())
    assert r == {"listed": True, "paid": {"has_credits": False, "unlimited": False, "balance": 0.0},
                 "spend_control_reached": False, "reached_type": None, "free_resets": 2,
                 "resets": [{"id": "early", "expires_at": 1790000000.0}, {"id": "late", "expires_at": 1800000000.0}]}, r
    assert not credits.paid_open(r) and credits.summary(r) == "2 free resets"
    # Absent: every field unknown, never "has credits"; no resets to consume.
    for empty in ({}, None, "x", {"rateLimits": {}}):
        r = credits.parse(empty)
        assert r["paid"] == {"has_credits": None, "unlimited": None, "balance": None}, r
        assert r["free_resets"] is None and r["resets"] == [] and r["spend_control_reached"] is None
        assert r["listed"] is False, "no list: a missing credit says nothing"
        assert not credits.paid_open(r) and credits.summary(r) == ""
    # Malformed: strings for booleans, a list for the credits, bad ids and times.
    r = credits.parse({"rateLimits": {"credits": {"hasCredits": "true", "unlimited": 1, "balance": "lots"},
                                      "spendControlReached": "no"},
                       "rateLimitResetCredits": {"availableCount": "2", "credits": [
                           {"id": 7}, "x", {"id": "", "expiresAt": 5}, {"id": "ok", "expiresAt": "soon"},
                           {"id": "ms", "expiresAt": 1790000000000}, {"id": "iso", "expiresAt": "2026-10-22T00:00:00Z"}]}})
    assert r["paid"] == {"has_credits": None, "unlimited": None, "balance": None} and r["spend_control_reached"] is None
    assert [c["id"] for c in r["resets"]] == ["ms", "iso", "ok"] and r["resets"][0]["expires_at"] == 1790000000.0
    assert r["resets"][2]["expires_at"] is None and r["free_resets"] == 3, "count falls back on the list"
    assert not credits.paid_open(r)
    # Paid credits open the window unless the spend control is reached.
    paid = credits.parse({"credits": {"hasCredits": True}, "spendControlReached": False})
    assert credits.paid_open(paid) and credits.summary(paid) == "paid credits"
    assert credits.paid_open(credits.parse({"credits": {"unlimited": True}}))
    stop = credits.parse({"credits": {"hasCredits": True}, "spendControlReached": True})
    assert not credits.paid_open(stop) and credits.summary(stop) == "spend limit reached"


def _held(p, util=95.0, resets_in_h=40.0, now=None, window="7d"):
    from ttp.budget import Window
    now = now or time.time()
    return [Window("codex", window, util, now + resets_in_h * 3600, "acct")]


def test_reset_credit_choice_earliest_expiry_min_hours_expiry_rule_one_per_window_and_off(env):
    from ttp import credits
    p = make(env)
    cfg = p.config()
    now = time.time()
    far = {"id": "far", "expires_at": now + 30 * 86400}
    near = {"id": "near", "expires_at": now + 10 * 86400}
    reading = {"resets": [near, far], "free_resets": 2}
    # Held at the line (90) with the reset 40 h away: the earliest-expiring credit, against that window.
    pick = credits.decide(p.db, cfg, "codex", _held(p, now=now), reading, now)
    assert pick["credit"] == "near" and pick["why"] == "held" and pick["window"] == "7d", pick
    # The reset is under budget.reset_credit_min_hours (12) away: the window just waits.
    assert credits.decide(p.db, cfg, "codex", _held(p, resets_in_h=11, now=now), reading, now) is None
    cfg["budget"]["reset_credit_min_hours"] = 8
    assert credits.decide(p.db, cfg, "codex", _held(p, resets_in_h=11, now=now), reading, now)["credit"] == "near"
    cfg["budget"]["reset_credit_min_hours"] = 12
    # Below the line nothing is held: no consume, unless the credit is about to lapse.
    assert credits.decide(p.db, cfg, "codex", _held(p, util=60, now=now), reading, now) is None
    soon = {"resets": [{"id": "soon", "expires_at": now + 47 * 3600}], "free_resets": 1}
    pick = credits.decide(p.db, cfg, "codex", _held(p, util=60, resets_in_h=5, now=now), soon, now)
    assert pick["credit"] == "soon" and pick["why"] == "expiring", pick
    # ... but not on a window under budget.reset_credit_expiry_use_pct (50) % used: that would waste it.
    assert credits.decide(p.db, cfg, "codex", _held(p, util=40, now=now), soon, now) is None
    cfg["budget"]["reset_credit_expiry_use_pct"] = 30
    assert credits.decide(p.db, cfg, "codex", _held(p, util=40, now=now), soon, now)["why"] == "expiring"
    cfg["budget"]["reset_credit_expiry_hours"] = 24
    assert credits.decide(p.db, cfg, "codex", _held(p, util=40, now=now), soon, now) is None
    # One per window: once a reset was spent against this window's reset time, not again.
    wins = _held(p, now=now)
    credits._finish(p.db, "codex", {"credit": "x", "window": "7d", "against": wins[0].resets_at + 30}, "reset", now)
    assert credits.decide(p.db, cfg, "codex", wins, reading, now) is None
    nxt = _held(p, resets_in_h=40 + 7 * 24, now=now)
    assert credits.decide(p.db, cfg, "codex", nxt, reading, now)["credit"] == "near", "the next window may"
    # Off: nothing is consumed, and the sweep says so.
    cfg["budget"]["reset_credits_auto"] = False
    assert credits.decide(p.db, cfg, "codex", nxt, reading, now) is None
    assert credits.decide(p.db, p.config(), "codex", nxt, {"resets": []}, now) is None
    assert credits.decide(p.db, p.config(), "codex", nxt, None, now) is None


class _ResetProvider:
    """Stands in for a provider's consume endpoint (never the real one): records each call."""

    def __init__(self, answers):
        self.answers, self.calls, self.last_credits = list(answers), [], None

    def consume_reset(self, credit, key):
        self.calls.append((credit, key))
        a = self.answers.pop(0)
        if isinstance(a, Exception):
            raise a
        return a


def test_reset_consume_saves_its_key_first_reuses_it_after_a_crash_and_never_spends_twice(env):
    from ttp import credits
    p = make(env)
    cfg = p.config()
    now = time.time()
    wins = _held(p, now=now)
    reading = {"resets": [{"id": "c1", "expires_at": now + 86400 * 9}, {"id": "c2", "expires_at": now + 86400 * 20}],
               "free_resets": 2}
    seen = {}

    class Crash(BaseException):
        pass

    class Dies(_ResetProvider):
        def consume_reset(self, credit, key):
            seen["pending"] = credits.shared("codex", "acct")[-1]
            super().consume_reset(credit, key)
            raise Crash()   # the daemon dies mid-call: no answer, nothing recorded after
    prov = Dies([None])
    with pytest.raises(Crash):
        credits.consume(p.db, cfg, "codex", prov, wins, reading, now)
    key = prov.calls[0][1]
    assert prov.calls == [("c1", key)] and len(key) >= 16
    assert seen["pending"]["key"] == key and seen["pending"]["credit"] == "c1", "saved before the call"
    assert seen["pending"]["state"] == "pending"
    # After the restart: no retry before RETRY_S; then the same credit with the same key.
    again = _ResetProvider([{"outcome": "reset"}])
    assert credits.consume(p.db, cfg, "codex", again, wins, reading, now + 60) is None and again.calls == []
    done = credits.consume(p.db, cfg, "codex", again, wins, reading, now + credits.RETRY_S + 1)
    assert again.calls == [("c1", key)] and done["outcome"] == "reset" and done["credit"] == "c1", done
    assert [e["state"] for e in credits.shared("codex", "acct")] == ["done"]
    # The window had its reset: a later reading still at the line consumes nothing more.
    later = _ResetProvider([{"outcome": "reset"}])
    assert credits.consume(p.db, cfg, "codex", later, wins, reading, now + 3600) is None and later.calls == []
    assert [u["credit"] for u in credits.used(p.db, "codex")] == ["c1"]


def _fresh_credits(p):
    """Forget every consume: this project's records and the machine-wide one."""
    from ttp import credits
    p.db.x("DELETE FROM kv WHERE key=?", (credits.USED + "codex",))
    credits._file(credits.SHARED, "codex", "acct").unlink(missing_ok=True)


def test_reset_consume_confirmed_only_by_a_reading_that_lists_the_credits_and_skips_unsupported(env):
    from ttp import credits
    p = make(env)
    cfg = p.config()
    now = time.time()
    wins = _held(p, now=now)
    reading = {"listed": True, "resets": [{"id": "c1", "expires_at": now + 86400 * 9}], "free_resets": 1}
    # A lost answer: the consume stays in flight with its key.
    lost = _ResetProvider([{"transport": True, "error": "no answer from `codex app-server`"}])
    assert credits.consume(p.db, cfg, "codex", lost, wins, reading, now) == {
        "error": "no answer from `codex app-server`", "attempts": 1}
    # A reading without the credits list says nothing: still in flight, nothing called, nothing recorded.
    absent = {"listed": False, "resets": [], "free_resets": None}
    assert credits.consume(p.db, cfg, "codex", lost, wins, absent, now + 5) is None
    assert credits.consume(p.db, cfg, "codex", lost, wins, absent, now + credits.RETRY_S + 5) is None
    assert credits.used(p.db, "codex") == [] and credits.shared("codex", "acct")[0]["state"] == "pending"
    # One that lists the credits without it: the consume went through.
    done = credits.consume(p.db, cfg, "codex", lost, wins, {"listed": True, "resets": [], "free_resets": 0}, now + 9)
    assert done["outcome"] == "reset (confirmed by the next reading)" and len(lost.calls) == 1
    # A provider without a consume endpoint: nothing kept in flight.
    _fresh_credits(p)
    assert credits.consume(p.db, cfg, "codex", _ResetProvider([None]), wins, reading, now) is None
    assert credits.shared("codex", "acct") == []


@pytest.mark.parametrize("outcome", ["reset", "alreadyRedeemed"])
def test_reset_consume_counts_reset_and_already_redeemed_as_success_once_per_window(env, outcome):
    from ttp import credits
    p = make(env)
    cfg = p.config()
    now = time.time()
    wins = _held(p, now=now)
    reading = {"listed": True, "resets": [{"id": "c1", "expires_at": now + 86400 * 9}], "free_resets": 1}
    prov = _ResetProvider([{"outcome": outcome}])
    done = credits.consume(p.db, cfg, "codex", prov, wins, reading, now)
    assert done["outcome"] == outcome and len(prov.calls) == 1, done
    assert credits.report_text("codex", done).startswith("Used one free codex window reset")
    assert [(e["state"], e["outcome"]) for e in credits.shared("codex", "acct")] == [("done", outcome)]
    # Recorded against the window: no second consume in it, whatever the readings say.
    for t in (now + 60, now + credits.RETRY_S + 1, now + 3600):
        assert credits.consume(p.db, cfg, "codex", prov, wins, reading, t) is None
    assert len(prov.calls) == 1 and credits.unreported(p.db, "codex") == [done]


def test_reset_consume_retries_only_transport_errors_with_one_key_and_records_the_rest(env):
    from ttp import credits
    p = make(env)
    cfg = p.config()
    now = time.time()
    wins = _held(p, now=now)
    reading = {"listed": True, "resets": [{"id": "c1", "expires_at": now + 86400 * 9}], "free_resets": 1}
    # Transport errors (no answer, an exception, a 5xx): retried with the saved key, MAX_TRIES at most.
    bad = _ResetProvider([{"transport": True, "error": "e1"}, RuntimeError("e2"), {"transport": True, "error": "503"}])
    t = now
    for _ in range(credits.MAX_TRIES):
        out = credits.consume(p.db, cfg, "codex", bad, wins, reading, t)
        assert credits.consume(p.db, cfg, "codex", bad, wins, reading, t + 60) is None, "not before RETRY_S"
        t += credits.RETRY_S + 1
    assert len({k for _, k in bad.calls}) == 1 and len(bad.calls) == credits.MAX_TRIES
    assert out["outcome"] == "failed: 503", out
    assert credits.report_text("codex", out).startswith("Could not use a free codex window reset")
    assert credits.consume(p.db, cfg, "codex", bad, wins, reading, t + 3600) is None, "that window gets no more tries"
    # Unknown outcomes and JSON-RPC errors that are not transport errors: recorded, not retried.
    for answer, want in (({"outcome": "weird"}, "failed: weird"), ({}, "failed: no outcome"),
                         ({"transport": False, "error": '{"code": -32602, "message": "bad id"}'},
                          'failed: {"code": -32602, "message": "bad id"}')):
        _fresh_credits(p)
        once = _ResetProvider([answer])
        assert credits.consume(p.db, cfg, "codex", once, wins, reading, now)["outcome"] == want
        assert credits.consume(p.db, cfg, "codex", once, wins, reading, now + credits.RETRY_S + 1) is None
        assert len(once.calls) == 1, answer
    assert credits.transport_error({"code": -32000, "message": "request timed out"})
    assert credits.transport_error({"code": -32000, "message": "x", "data": {"status": 503}})
    assert credits.transport_error({"status": 502}) and credits.transport_error("connection reset by peer")
    assert not credits.transport_error({"code": -32602, "message": "invalid creditId"})


def test_reset_consume_is_once_per_account_window_across_projects_on_one_machine(env, tmp_path):
    import threading
    from ttp import credits
    from ttp.db import DB
    p = make(env)
    other = DB(tmp_path / "other" / "project.db")   # a second project's database, same TTP_HOME
    cfg = p.config()
    now = time.time()
    wins = _held(p, now=now)
    reading = {"listed": True, "resets": [{"id": "c1", "expires_at": now + 86400 * 9},
                                         {"id": "c2", "expires_at": now + 86400 * 20}], "free_resets": 2}
    # Both see the same held window: one consume between them, even with a stale reading.
    prov = _ResetProvider([{"outcome": "reset"}, {"outcome": "reset"}])
    assert credits.consume(p.db, cfg, "codex", prov, wins, reading, now)["outcome"] == "reset"
    assert credits.consume(other, cfg, "codex", prov, wins, reading, now + 5) is None
    assert credits.consume(other, cfg, "codex", prov, wins, reading, now + 3600) is None
    assert len(prov.calls) == 1 and credits.used(other, "codex") == []
    # A crash after the shared record was written: either project retries with the same key.
    _fresh_credits(p)

    class Crash(BaseException):
        pass

    class Dies(_ResetProvider):
        def consume_reset(self, credit, key):
            super().consume_reset(credit, key)
            raise Crash()
    dies = Dies([None])
    with pytest.raises(Crash):
        credits.consume(p.db, cfg, "codex", dies, wins, reading, now)
    key = dies.calls[0][1]
    flaky = _ResetProvider([{"transport": True, "error": "no answer"}])
    assert credits.consume(other, cfg, "codex", flaky, wins, reading, now + credits.RETRY_S + 1)["attempts"] == 2
    ok = _ResetProvider([{"outcome": "alreadyRedeemed"}])
    done = credits.consume(p.db, cfg, "codex", ok, wins, reading, now + 2 * credits.RETRY_S + 2)
    assert [k for _, k in flaky.calls + ok.calls] == [key, key] and done["outcome"] == "alreadyRedeemed"
    # The lock is real: while one project's consume is in its call, the other waits, then sees it done.
    _fresh_credits(p)
    inside, release = threading.Event(), threading.Event()

    class Slow(_ResetProvider):
        def consume_reset(self, credit, key):
            inside.set()
            release.wait(10)
            return super().consume_reset(credit, key)
    slow, second = Slow([{"outcome": "reset"}]), _ResetProvider([{"outcome": "reset"}])
    seen = {}
    a = threading.Thread(target=lambda: credits.consume(DB(p.state / "project.db"), cfg, "codex", slow, wins, reading, now))
    a.start()
    assert inside.wait(10)
    remetered = []
    b = threading.Thread(target=lambda: seen.update(out=credits.consume(
        DB(tmp_path / "other" / "project.db"), cfg, "codex", second, wins, reading, now + 1,
        remeter=lambda: remetered.append(1) or (wins, reading))))
    b.start()
    b.join(0.5)
    assert b.is_alive() and remetered == [], "the second project waits for the lock before reading again"
    release.set()
    a.join(10)
    b.join(10)
    assert seen["out"] is None and remetered == [1] and second.calls == [] and len(slow.calls) == 1


def test_codex_meter_reads_credits_and_consume_sends_the_key(env, monkeypatch, tmp_path):
    from ttp.providers import codex
    exe = tmp_path / "codex"
    exe.write_text(FAKE_CLI.format(python=sys.executable))
    exe.chmod(0o755)
    monkeypatch.setattr(codex.Codex, "binary", lambda self: str(exe))
    monkeypatch.setenv("FAKE_CLI_LOG", str(tmp_path / "log"))
    monkeypatch.setenv("FAKE_CLI_SESSION", json.dumps(_credit_answer()))
    c = codex.Codex()
    wins = c.meter()
    assert [(w.window, w.utilization) for w in wins] == [("5h", 20.0), ("7d", 93.0)]
    assert c.last_credits["free_resets"] == 2 and c.last_credits["resets"][0]["id"] == "early"
    # The consume call goes to the stand-in CLI only (its answer echoes FAKE_CLI_SESSION).
    monkeypatch.setenv("FAKE_CLI_SESSION", json.dumps({"outcome": "reset"}))
    assert c.consume_reset("early", "k1") == {"outcome": "reset"}
    reqs = [json.loads(x)["request"] for x in (tmp_path / "log" / "app_server.jsonl").read_text().splitlines()
            if "request" in json.loads(x)]
    assert reqs[-1]["method"] == "account/rateLimitResetCredit/consume"
    assert reqs[-1]["params"] == {"creditId": "early", "idempotencyKey": "k1"}
    for outcome in ("alreadyRedeemed", "noCredit", "alreadyConsumed"):   # passed on as it is: credits judges it
        monkeypatch.setenv("FAKE_CLI_SESSION", json.dumps({"outcome": outcome}))
        assert c.consume_reset("early", "k1") == {"outcome": outcome}
    monkeypatch.setattr(codex, "app_server_call", lambda *a, **k: None)
    assert c.consume_reset("early", "k1")["transport"] is True, "no answer: a transport error"
    monkeypatch.setattr(codex, "app_server_call", lambda *a, **k: {"id": 2, "error": {"code": -32602, "message": "bad id"}})
    assert c.consume_reset("early", "k1")["transport"] is False
    monkeypatch.setattr(codex, "app_server_call", lambda *a, **k: {"id": 2, "error": {"code": -32000, "message": "upstream 502"}})
    assert c.consume_reset("early", "k1")["transport"] is True


class _MeterProvider(_ResetProvider):
    """A metered provider (no model call) whose window empties once a reset is consumed."""

    def __init__(self, util, answers=(), resets=None):
        super().__init__(answers)
        self.util, self.reads, self.resets = util, 0, resets or []

    def account(self):
        return "acct"

    def meter(self):
        from ttp.budget import Window
        self.reads += 1
        self.last_credits = {"paid": {}, "free_resets": len(self.resets), "resets": list(self.resets)}
        return [Window("codex", "7d", self.util, self.at, "acct")]

    def consume_reset(self, credit, key):
        out = super().consume_reset(credit, key)
        if out and out.get("outcome") in ("reset", "alreadyRedeemed"):
            self.util, self.resets = 0.0, [r for r in self.resets if r["id"] != credit]
        return out


@pytest.mark.parametrize("outcome", ["reset", "alreadyRedeemed"])
def test_a_consumed_reset_remeters_at_once_and_is_reported_once_at_low_severity(env, monkeypatch, outcome):
    from ttp import credits, daemon as dm
    p = make(env)
    d = dm.Daemon(p.base)
    now = time.time()
    prov = _MeterProvider(95.0, [{"outcome": outcome}],
                          resets=[{"id": "r2", "expires_at": now + 20 * 86400}, {"id": "r1", "expires_at": now + 9 * 86400}])
    prov.resets.sort(key=lambda r: r["expires_at"])
    prov.at = now + 60 * 3600
    monkeypatch.setattr(dm, "get_provider", lambda name: prov)
    sent = []
    monkeypatch.setattr(d, "alert", lambda key, text, severity="high", every_s=0: sent.append((key, text, severity)))
    d._meter_providers(p.db, ["codex"])
    # Read, read again inside the account's lock before deciding, consume the earliest, read again.
    assert prov.calls and prov.calls[0][0] == "r1" and prov.reads == 3, "consumed the earliest, then read again"
    assert credits.latest(p.db, "codex")["free_resets"] == 1
    d._report_resets()
    d._report_resets()
    assert len(sent) == 1 and sent[0][2] == "low" and sent[0][0] == "reset-credit:codex:r1", sent
    assert "Used one free codex window reset" in sent[0][1] and "95%" in sent[0][1] and "Held work starts again" in sent[0][1]
    assert f"Outcome: {outcome}." in sent[0][1]
    assert credits.unreported(p.db, "codex") == []
    # Read again at the line in the same window: no second consume.
    prov.util = 95.0
    d._meter_providers(p.db, ["codex"])
    assert len(prov.calls) == 1 and prov.reads == 4, "no second consume, and no second reading for nothing"


def test_budget_line_shows_free_resets_and_paid_credits_on_one_line(env):
    from ttp import credits
    from ttp.web import budget_line
    p = make(env)
    now = time.time()
    snap = lambda prov, win, util, resets: p.db.x(  # noqa: E731
        "INSERT INTO snapshots(ts,provider,account,window,utilization,resets_at) VALUES(?,?,?,?,?,?)",
        (now - 60, prov, "", win, util, resets))
    snap("claude", "five_hour", 4.4, now + 3.94 * 3600)
    snap("codex", "5h", 10.0, now + 3600)
    snap("codex", "7d", 93.0, now + 2 * 86400)
    base = budget_line(p.db, now)
    assert "free reset" not in base and "credits" not in base
    credits.record(p.db, "codex", credits.parse(_credit_answer()), "", now)
    line = budget_line(p.db, now)
    assert line == base + ", codex 7d 93%, 2 free resets", line
    credits.record(p.db, "claude", credits.parse({"credits": {"hasCredits": True}}), "", now)
    line = budget_line(p.db, now)
    assert line == base + ", paid credits, codex 7d 93%, 2 free resets", line
    assert "\n" not in line
    credits.record(p.db, "codex", credits.parse(_credit_answer()), "", now - credits.FRESH_S - 1)
    assert budget_line(p.db, now) == base + ", paid credits", "a stale reading is left out"


def test_sweep_digest_and_budget_digest_list_credits_as_a_provider_holds_unblock_path(env):
    from ttp import credits, sweep
    from ttp import coordinator as coord
    from ttp.budget import Gate
    p = make(env)
    now = time.time()
    ev = p.db.x("INSERT INTO events(ts,source,kind,severity,text,data,status) VALUES(?,?,?,?,?,?,?)",
                (now, "daemon", sweep.SWEEP_KIND, "normal", "Blocker sweep", "{}", "queued"))
    p.db.set_kv("gates", {"codex": {"level": "red", "reasons": ["7d window at 95% (line 90%)"]}})
    lines = sweep.digest_lines(p.db, [ev], now, p.config())
    assert lines[-1] == ("- provider codex held (no sweep action; 7d window at 95% (line 90%)) | unblock path: "
                         "none reported (no free resets or paid credits)"), lines[-1]
    credits.record(p.db, "codex", credits.parse(_credit_answer(**{"rateLimits": {
        "credits": {"hasCredits": True}}})), "", now)
    credits._finish(p.db, "codex", {"credit": "x", "window": "7d", "against": now + 9}, "reset", now - 7200)
    line = sweep.digest_lines(p.db, [ev], now, p.config())[-1]
    assert line.endswith("unblock path: 2 free window reset(s) (consumed automatically when held); paid credits "
                         "(the window does not hold; the dollar caps apply); last free reset 2.0 h ago: reset"), line
    cfg = p.config()
    cfg["budget"]["reset_credits_auto"] = False
    assert "(auto-consume off)" in sweep.digest_lines(p.db, [ev], now, cfg)[-1]
    g = Gate(provider="codex", level="red", reasons=["held"])
    text = coord.digest(p, {"codex": g.as_dict()}, [], [])
    assert "unblock path: 2 free window reset(s)" in text, text[:2000]
    src = (RUNTIME.parent / "template" / "prompts" / "coordinator.md").read_text()
    assert "free window resets and paid credits are an unblock path" in " ".join(src.split())


def _assert_openai_strict_schema(schema):
    """Check the conservative subset used by every coordinator schema adapter."""
    allowed = {'type', 'properties', 'required', 'additionalProperties', 'items', 'enum',
               'anyOf', '$defs', '$ref', 'description', 'title'}
    assert set(schema) <= allowed, schema
    types = schema.get('type', [])
    types = [types] if isinstance(types, str) else types
    if 'object' in types or 'properties' in schema:
        assert schema.get('additionalProperties') is False, schema
        assert set(schema.get('required', [])) == set(schema.get('properties', {})), schema
        for sub in schema.get('properties', {}).values():
            _assert_openai_strict_schema(sub)
    if 'items' in schema:
        _assert_openai_strict_schema(schema['items'])
    for sub in schema.get('anyOf', []):
        _assert_openai_strict_schema(sub)
    for sub in schema.get('$defs', {}).values():
        _assert_openai_strict_schema(sub)


def test_strict_schema_visits_anyof_definitions_and_refuses_free_objects():
    from ttp.providers.base import strict_schema
    source = {'type': 'object', 'properties': {'choice': {'anyOf': [
        {'type': ['object', 'null'], 'properties': {'flag': {'type': 'boolean'}}},
        {'type': 'array', 'items': {'type': 'object', 'properties': {'name': {'type': 'string'}}}}]}},
        '$defs': {'nested': {'type': 'object', 'properties': {'value': {'type': ['string', 'null']}}}}}
    wire = strict_schema(source)
    _assert_openai_strict_schema(wire)
    assert strict_schema(wire) == wire and 'required' not in source
    for free in ({'type': 'object'}, {'type': ['object', 'null']}):
        with pytest.raises(ValueError, match='full object'):
            strict_schema(free)


# Missing check targets are owned configuration gaps, never an unchecked pass. ----------------------

def test_push_check_applicability_lint(env):
    from ttp.project import config_problems
    p = make(env)
    checks = ["git diff --check " + "a" * 40, "/tmp/check-env/bin/python -m pytest tests/test_absent.py",
              "python3 -m pytest tests/test_absent.py"]
    problems = config_problems({"delivery": {"push_checks": checks}}, p.root)
    assert any("SHA" in x for x in problems)
    assert any("absolute temp" in x for x in problems)
    assert any("tests/test_absent.py" in x and "missing" in x for x in problems)
    assert all("if_exists" in x and "if_changed" in x for x in problems)
    assert not config_problems({"delivery": {"push_checks": [
        {"run": checks[-1], "if_exists": "tests/test_absent.py"}]}}, p.root)


def _gap_review_failure(env, p, command, base, i):
    """One review that fails check_only on a missing target; returns (review id, daemon)."""
    from ttp import push
    from ttp.daemon import Daemon
    from ttp.providers.base import RunUsage
    code, _, _, (rev,) = _finish_code(env, p, f"gap docs {i}", {f"docs/gap{i}.md": 1})
    path = p.worktrees / f"t{code}"
    head = _git_out(path, "rev-parse", "HEAD").strip()
    run = env["tmp"] / f"gap-{i}"
    run.mkdir()
    failure = push.applicability_failure(path, head, push.Check(command), 4,
                                        "ERROR: file or directory not found: tests/test_absent.py", base)
    (run / "check_failure.json").write_text(json.dumps(failure))
    (run / "result.json").write_text(json.dumps({"status": "failed", "review_failure": "check_only",
                                               "summary": "only the check target is missing"}))
    p.db.x("INSERT INTO runs(task,role,status,dir) VALUES(?,?,?,?)", (rev["id"], "worker", "ok", str(run)))
    d = Daemon(p.base)
    d._finish_worker({"task": rev["id"], "note": "{}"}, RunUsage(), "ok", run)
    return rev["id"], d


def _gap_probe(p, tid):
    from ttp import cli
    args = shlex.split(json.loads(p.db.task(tid)["result"])["retry_when"])
    with pytest.raises(SystemExit) as exc:
        cli.main(args[args.index("checks"):])
    return exc.value.code


def test_check_gap_waiter_is_released_only_by_a_change_since_its_own_failure(env, monkeypatch):
    from ttp import checkgaps
    p = make(env)
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    command = "python3 -m pytest tests/test_absent.py"
    p.set_config("delivery.push_checks", [command, "true"])
    base = _git_out(p.root, "rev-parse", "HEAD").strip()
    first, d = _gap_review_failure(env, p, command, base, 0)
    assert _gap_probe(p, first) == 1
    # An unrelated push_checks edit releases the first waiter, but not one that failed after it.
    p.set_config("delivery.push_checks", [command, "git diff --check"])
    assert _gap_probe(p, first) == 0
    second, d = _gap_review_failure(env, p, command, base, 1)
    assert json.loads(p.db.task(second)["result"])["check_gap"]
    assert _gap_probe(p, second) == 1, "a new waiter on an old gap must not wake at once"
    (key,) = p.db.kv(checkgaps.KEY)
    assert not checkgaps.ready(p, key.removeprefix("check:")), "the gap's fingerprint follows its newest waiter"
    p.set_config("delivery.push_checks", ["git diff --check"])
    assert _gap_probe(p, second) == 0


def test_check_gap_replaces_a_dead_owner_once_and_escalates_after_the_cap(env, monkeypatch):
    from ttp import checkgaps
    p = make(env)
    command = "python3 -m pytest tests/test_absent.py"
    p.set_config("delivery.push_checks", [command, "true"])
    base = _git_out(p.root, "rev-parse", "HEAD").strip()
    owners = lambda: [t["id"] for t in p.db.q("SELECT id FROM tasks WHERE kind='harness' AND origin='daemon' ORDER BY id")]
    first, d = _gap_review_failure(env, p, command, base, 0)
    (owner,) = owners()
    # A failed owner: the next check-only failure names one live replacement, and ticks add none.
    p.db.update_task(owner, status="failed")
    second, d = _gap_review_failure(env, p, command, base, 1)
    gap = next(iter(p.db.kv(checkgaps.KEY).values()))
    assert len(owners()) == 2 and gap["owner"] == owners()[1] != owner
    assert p.db.task(gap["owner"])["status"] == "queued"
    for tid in (first, second):
        assert f"owner #{gap['owner']}." in json.loads(p.db.task(tid)["result"])["summary"]
    d.reconcile_tasks()
    d.reconcile_tasks()
    assert len(owners()) == 2
    # A tick alone replaces a cancelled owner, or one done while the config never changed.
    p.db.update_task(gap["owner"], status="done")
    d.reconcile_tasks()
    d.reconcile_tasks()
    assert len(owners()) == 3
    assert next(iter(p.db.kv(checkgaps.KEY).values()))["owner"] == owners()[2]
    # Past the cap: one coordinator event, no further owner, no loop.
    p.db.update_task(owners()[2], status="cancelled")
    for _ in range(3):
        d.reconcile_tasks()
    assert len(owners()) == checkgaps.MAX_OWNERS
    events = p.db.q("SELECT * FROM events WHERE kind='check_gap_unowned'")
    assert len(events) == 1 and command in events[0]["text"]
    third, d = _gap_review_failure(env, p, command, base, 2)
    assert len(owners()) == checkgaps.MAX_OWNERS
    assert len(p.db.q("SELECT * FROM events WHERE kind='check_gap_unowned'")) == 1
    assert "Raised to the coordinator" in json.loads(p.db.task(third)["result"])["summary"]


def test_check_gap_retires_once_its_check_is_gone_and_nobody_waits(env, monkeypatch):
    from ttp import checkgaps
    p = make(env)
    command = "python3 -m pytest tests/test_absent.py"
    p.set_config("delivery.push_checks", [command, "true"])
    base = _git_out(p.root, "rev-parse", "HEAD").strip()
    tid, d = _gap_review_failure(env, p, command, base, 0)
    p.set_config("delivery.push_checks", ["true"])
    d._load_config()
    monkeypatch.setattr(d, "_start_checks", lambda *args: True)
    d.reconcile_tasks()
    assert p.db.kv(checkgaps.KEY), "a waiter still rerunning keeps its gap"
    p.db.update_task(tid, status="done")
    d.reconcile_tasks()
    assert not p.db.kv(checkgaps.KEY, {})
    assert len(p.db.q("SELECT id FROM tasks WHERE kind='harness' AND origin='daemon'")) == 1


def test_checks_record_missing_target_and_probe_config_change(env, tmp_path, monkeypatch, capsys):
    from ttp import cli, checkgaps
    p = make(env)
    _with_origin(env, clone=False)
    p.set_config("delivery.push_branch", "work")
    p.set_config("delivery.checks_fast_globs", [])
    base = _git_out(p.root, "rev-parse", "HEAD").strip()
    _git_out(p.root, "update-ref", "refs/remotes/origin/work", base)
    (p.root / "docs").mkdir(exist_ok=True)
    _commit_files(p.root, {"docs/new.md": "docs\n"}, "docs")
    run = tmp_path / "missing-run"
    run.mkdir()
    monkeypatch.setenv("TTP_RUN_DIR", str(run))
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    monkeypatch.chdir(p.root)
    command = "python3 tests/test_absent.py"
    p.set_config("delivery.push_checks", [command])
    with pytest.raises(SystemExit) as exc:
        cli.main(["checks"])
    assert exc.value.code == 1
    receipt = json.loads((run / "check_failure.json").read_text())
    assert receipt["unrelated"] is True and receipt["base"] == base
    assert receipt["check"] == command and receipt["rc"] == 2
    key = "check:" + receipt["sig"]
