# ---- budget kind changes (budgetkind.py) -------------------------------------------------------

ACCT_PLAN, ACCT_BILLED, ACCT_PLAN2 = "a@example.org | Org | plan", "a@example.org | Org | usage-billed", "b@example.org"


def _bk_events(p):
    from ttp import budgetkind
    return p.db.q("SELECT * FROM events WHERE kind=? ORDER BY id", (budgetkind.KIND,))


def _bk_tick(d, monkeypatch, n=2):
    """Gate updates enough for a new fingerprint to pass its debounce (zeroed in these tests)."""
    for _ in range(n):
        d.update_gates()


def test_budget_fingerprint_debounces_flapping_readings():
    """A reading that falls back before the debounce wakes nobody; a lasting one wakes once, and a
    provider raises at most one event per MIN_GAP_S; an unknown part is no change."""
    from ttp import budgetkind as bk
    from ttp.db import DB
    import tempfile
    from pathlib import Path
    db = DB(Path(tempfile.mkdtemp()) / "t.db")
    a = {"account": "h1", "kind": "plan", "windows": ["five_hour", "seven_day"]}
    b = {"account": "h1", "kind": "billed", "windows": [], "caps": {"daily_usd": 100.0}}
    t = 100000.0
    assert bk.observe(db, "claude", a, t) is None   # baseline
    for i in range(5):   # flapping a <-> b every minute
        assert bk.observe(db, "claude", b, t + 120 * i + 60) is None
        assert bk.observe(db, "claude", a, t + 120 * i + 120) is None
    t = 200000.0
    assert bk.observe(db, "claude", b, t) is None
    assert bk.observe(db, "claude", b, t + bk.DEBOUNCE_S - 1) is None
    got = bk.observe(db, "claude", b, t + bk.DEBOUNCE_S)
    assert got and got["old"]["kind"] == "plan" and got["new"]["kind"] == "billed"
    assert bk.observe(db, "claude", b, t + bk.DEBOUNCE_S + 5) is None, "once per change"
    # back to the plan within the minimum gap: no second wake until the gap has passed
    t2 = t + bk.DEBOUNCE_S + 10
    assert bk.observe(db, "claude", a, t2) is None
    assert bk.observe(db, "claude", a, t2 + bk.DEBOUNCE_S) is None
    assert bk.observe(db, "claude", a, t + bk.DEBOUNCE_S + bk.MIN_GAP_S)["new"]["kind"] == "plan"
    # an unknown account or kind takes the known one: no change
    assert bk.observe(db, "claude", {"account": "", "kind": "unknown", "windows": []}, t + 2 * bk.MIN_GAP_S) is None
    assert bk.observe(db, "claude", {"account": "", "kind": "unknown", "windows": []}, t + 3 * bk.MIN_GAP_S) is None


def test_budget_fingerprint_adopts_a_first_known_account_or_kind_silently():
    """A baseline taken before the provider's first run (kind unknown, no account label) is
    completed by the first known reading: no pending change, no event."""
    from ttp import budgetkind as bk
    from ttp.db import DB
    import tempfile
    from pathlib import Path
    db = DB(Path(tempfile.mkdtemp()) / "t.db")
    t = 1.8e9
    plan = {"account": "h1", "kind": "plan", "windows": ["five_hour", "seven_day"]}
    assert bk.observe(db, "claude", {"account": "", "kind": "unknown", "windows": []}, t) is None
    for dt in (0, bk.DEBOUNCE_S + 1, bk.MIN_GAP_S + bk.DEBOUNCE_S + 2):
        assert bk.observe(db, "claude", plan, t + 10 + dt) is None
    st = db.kv(bk.KV + "claude")
    assert st["parts"] == plan and not st.get("pending"), st
    # an empty account becomes known, same kind
    billed = {"account": "", "kind": "billed", "windows": [], "caps": {"daily_usd": 100.0}}
    assert bk.observe(db, "codex", billed, t) is None
    for dt in (0, bk.DEBOUNCE_S + 1, bk.MIN_GAP_S + bk.DEBOUNCE_S + 2):
        assert bk.observe(db, "codex", {**billed, "account": "h1"}, t + 10 + dt) is None
    st = db.kv(bk.KV + "codex")
    assert st["parts"]["account"] == "h1" and not st.get("pending"), st
    # a known part that differs after that is still a change
    assert bk.observe(db, "codex", {**billed, "account": "h2"}, t + 2 * bk.MIN_GAP_S) is None
    assert bk.observe(db, "codex", {**billed, "account": "h2"}, t + 2 * bk.MIN_GAP_S + bk.DEBOUNCE_S)
    assert not bk._switched({"account": "", "kind": "unknown"}, {"account": "h1", "kind": "plan"})


def test_a_new_providers_first_run_is_no_budget_change(env, monkeypatch):
    """A new project's provider starts with an unknown budget; its first finished run makes the
    kind known. That wakes nobody and keeps a real usage-limit pause."""
    from ttp import budgetkind
    from ttp.daemon import Daemon
    monkeypatch.setattr(budgetkind, "DEBOUNCE_S", 0.0)
    p = make(env)
    d = Daemon(p.base)
    _bk_tick(d, monkeypatch)
    assert p.db.kv(budgetkind.KV + "fake")["parts"]["kind"] == "unknown"
    now = time.time()
    p.db.set_kv("limited:fake", {"until": now + 3600, "note": "usage limit"})
    p.db.x("INSERT INTO runs(role,provider,account,started,ended,status,cost_usd) VALUES('worker','fake',?,?,?,'ok',1)",
           (ACCT_BILLED, now - 900, now - 600))
    _bk_tick(d, monkeypatch)
    assert _bk_events(p) == []
    assert float(p.db.kv("limited:fake")["until"]) > now and p.db.kv("limited:fake")["note"] == "usage limit"
    assert p.db.kv(budgetkind.KV + "fake")["parts"]["kind"] == "billed"


@pytest.mark.parametrize("command, expected", [("true", "0"), ("false", "1"), ("sleep 60", "143")])
def test_detached_checks_clean_scratch_on_exit(env, tmp_path, monkeypatch, capsys, command, expected):
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    pid = _detached_checks(run, capsys, command)
    scratch = pathlib.Path(cli._read_checks_pid(run)["check_run_dir"]) / cli.CHECKS_TMP
    if expected == "143":
        assert _wait_for(lambda: (run / "checks.log").exists())
        os.killpg(pid, signal.SIGTERM)
    assert _wait_precheck(run) == expected
    assert _wait_for(lambda: not scratch.exists())
    assert not scratch.parent.exists(), 'completed checks left their check-runs folder behind'


@pytest.mark.parametrize("when", ["before", "after"])
def test_detached_check_stop_during_start_still_ends_the_command(monkeypatch, when):
    """SIGTERM inside Popen (before or after the fork) never leaves the started check running."""
    from ttp import cli
    real, started = subprocess.Popen, []

    def popen(*args, **kw):
        if when == "before":
            os.kill(os.getpid(), signal.SIGTERM)
        proc = real(*args, **kw)
        started.append(proc)
        if when == "after":
            os.kill(os.getpid(), signal.SIGTERM)
        return proc

    monkeypatch.setattr(cli.subprocess, "Popen", popen)
    monkeypatch.setitem(cli._CHECK_STOP, "stopped", None)   # the stop must not outlast this test
    old = signal.signal(signal.SIGTERM, cli._checks_stop)
    try:
        with pytest.raises(SystemExit) as e:
            cli._run_check([sys.executable, "-c", "import time; time.sleep(60)"], True)
    finally:
        signal.signal(signal.SIGTERM, old)
    assert e.value.code == 143
    assert len(started) == 1 and started[0].returncode is not None, "the started check kept running"
    assert cli._CHECK_STOP["defer"] is False


def test_detached_checks_stop_even_when_the_launcher_blocks_sigterm(env, tmp_path, monkeypatch, capsys):
    """A SIGTERM mask the launcher had passes to the detached checks and their commands: a stop must
    still end them as stopped (143), never let the command finish and record its exit code."""
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    old = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGTERM})
    try:
        pid = _detached_checks(run, capsys, "sleep 300")
    finally:
        signal.pthread_sigmask(signal.SIG_SETMASK, old)
    try:
        assert _wait_for(lambda: (run / "checks.log").exists())
        os.killpg(pid, signal.SIGTERM)
        assert _wait_precheck(run) == "143"
        assert "stopped by signal 15" in (run / "checks.log").read_text()
    finally:
        try:
            os.killpg(pid, signal.SIGKILL)
        except OSError:
            pass


def test_detached_checks_record_a_stop_whose_exit_was_lost(env, tmp_path, monkeypatch):
    """A stop whose SystemExit something swallowed still records 128+signal, and no further check starts."""
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    monkeypatch.setitem(cli._CHECK_STOP, "stopped", None)
    handlers = {sig: signal.getsignal(sig) for sig in cli._CHECK_STOP_SIGNALS}
    started = []

    def checks(_a):
        try:
            cli._checks_stop(signal.SIGTERM, None)
        except SystemExit:
            pass   # e.g. a broad except on the way out of a check
        with pytest.raises(SystemExit) as e:
            cli._run_check(["sh", "-c", f"touch {tmp_path / 'ran'}"], True)
        started.append(e.value.code)

    monkeypatch.setattr(cli, "cmd_checks", checks)
    monkeypatch.setattr(cli.sys, "stdin", io.TextIOWrapper(io.BytesIO(b"go\n")))
    monkeypatch.setenv("TTP_CHECK_OUTPUT_DIR", str(run))
    monkeypatch.delenv("TTP_CHECKS_TMP_FD", raising=False)
    try:
        code = cli._checks_child(types.SimpleNamespace(rc=str(run / cli.CHECKS_RC)))
    finally:
        for sig, h in handlers.items():
            signal.signal(sig, h)
    assert code == 143 and (run / cli.CHECKS_RC).read_text().strip() == "143"
    assert "stopped by signal 15" in (run / "checks.log").read_text()
    assert started == [143] and not (tmp_path / "ran").exists(), "a check started after the stop"


def test_detached_checks_recovery_leaves_legacy_scratch(env, tmp_path, monkeypatch):
    from ttp import cli, detach
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    scratch = run / "checks-tmp"
    scratch.mkdir()
    (scratch / "orphan").write_text("left by a killed check or reboot")
    monkeypatch.setattr(p, "runs", tmp_path)
    detach.tend(p)
    assert (scratch / "orphan").read_text() == "left by a killed check or reboot"
    cli._checks_tmp_cleanup(run)
    assert scratch.exists(), "legacy storage is outside managed reclamation"


def test_detached_checks_recovery_preserves_scratch_after_supervisor_killed(env, tmp_path, monkeypatch, capsys):
    from ttp import cli, detach
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    ready = tmp_path / "check.pid"
    code = ("import os, pathlib, tempfile, time; "
            "f = pathlib.Path(tempfile.mkdtemp()) / 'keep'; f.write_text('alive'); "
            f"pathlib.Path({str(ready)!r}).write_text(str(os.getpid())); time.sleep(60)")
    pid = _detached_checks(run, capsys, shlex.join([sys.executable, "-c", code]))
    child = None
    try:
        assert _wait_for(ready.exists)
        child = _host_pid([sys.executable, "-c", code])
        output = pathlib.Path(cli._read_checks_pid(run)["check_run_dir"])
        scratch = pathlib.Path(json.loads((output / "owner.json").read_text())["tmp"])   # short (shorttmp)
        os.killpg(pid, signal.SIGKILL)
        assert _wait_for(lambda: _gone_pid(pid))
        monkeypatch.setattr(p, "runs", tmp_path)
        detach.tend(p)
        assert list(scratch.glob("*/keep")), "live command lost its scratch"
        assert cli._checks_result(run) == 0
        assert scratch.exists(), "lost-supervisor probe removed a live command's scratch"
        os.kill(child, signal.SIGTERM)
        assert _wait_for(lambda: _gone_pid(child))
        detach.tend(p)
        assert not scratch.exists() and not output.exists()
    finally:
        for owned in (pid, child):
            if owned:
                try:
                    os.kill(owned, signal.SIGKILL)
                except OSError:
                    pass


def test_foreground_checks_keep_worker_temporary_environment(env, tmp_path, monkeypatch):
    from ttp import cli
