def test_streamed_and_codex_cache_telemetry_preserve_missing_metadata(tmp_path):
    from ttp.providers import claude, codex
    log = tmp_path / 'stream.jsonl'
    for provider, event, usage, complete in (
        (claude.Claude(), 'assistant', {'input_tokens': 10, 'cache_read_input_tokens': 0,
                                      'cache_creation_input_tokens': 0}, True),
        (claude.Claude(), 'assistant', {'input_tokens': 10}, False),
        (codex.Codex(), 'turn.completed', {'input_tokens': 10, 'cached_input_tokens': 5}, True),
        (codex.Codex(), 'turn.completed', {'input_tokens': 10}, False),
        (codex.Codex(), 'turn.completed', {'input_tokens': 10, 'cached_input_tokens': 20}, False),
    ):
        payload = {'type': event, 'usage': usage}
        if event == 'assistant':
            payload = {'type': event, 'message': {'id': 'm1', 'usage': usage, 'content': []}}
        log.write_text(json.dumps(payload) + '\n')
        assert provider.parse(log).extra['cache_telemetry']['complete'] is complete
    log.write_text('')
    assert not codex.Codex().parse(log).extra['cache_telemetry']['complete']


HARNESS_PLAN = "ttp check-plan --purpose harness --definition-commit " + "a" * 40 + " --definition-path checks/harness.json"


def _fake_check_plan_ttp(tmp_path, monkeypatch, log, rc=0):
    """A `ttp` on PATH that only logs its call: the harness entry's check-plan command."""
    bin_dir = tmp_path / "fakebin"
    bin_dir.mkdir(exist_ok=True)
    (bin_dir / "ttp").write_text(f"#!/bin/sh\necho plan >> {log}\nexit {rc}\n")
    (bin_dir / "ttp").chmod(0o755)
    monkeypatch.setenv("PATH", f"{bin_dir}{os.pathsep}{os.environ['PATH']}")


def test_ttp_checks_tolerates_runtime_written_tracked_logs_the_repo_ignores(env, tmp_path, monkeypatch, capsys):
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    # A watcher's log committed before it was ignored, then appended to by the running watcher.
    (repo / "logs").mkdir()
    (repo / "logs" / "queue-wait.jsonl").write_text("{}\n")
    (repo / ".gitignore").write_text("logs/*.jsonl\n")
    subprocess.run([*git, "add", "-f", ".gitignore", "logs/queue-wait.jsonl"], check=True)
    subprocess.run([*git, "commit", "-qm", "watcher log"], check=True)
    with open(repo / "logs" / "queue-wait.jsonl", "a") as f:
        f.write('{"wait": 1}\n')
    count = tmp_path / "count"
    cli.main(["checks", "--", "sh", "-c", f"echo x >> {count}"])
    assert count.read_text() == "x\n"
    assert "runtime-written changes to tracked files the repository ignores: logs/queue-wait.jsonl" in capsys.readouterr().out
    # Any other change still blocks: an edit to a file not ignored, or a staged edit to an ignored one.
    for staged, path in ((False, "a.txt"), (True, "logs/queue-wait.jsonl")):
        subprocess.run([*git, "checkout", "-q", "--", "."], check=True)
        with open(repo / path, "a") as f:
            f.write("more\n")
        if staged:
            subprocess.run([*git, "add", "-f", path], check=True)
        with pytest.raises(SystemExit) as e:
            cli.main(["checks", "--fresh", "--", "sh", "-c", f"echo x >> {count}"])
        assert e.value.code and "commit first" in capsys.readouterr().err, path
        subprocess.run([*git, "reset", "-q"], check=True)
    assert count.read_text() == "x\n"


def test_ttp_checks_purpose_harness_tolerates_harness_state_it_does_not_own(env, tmp_path, monkeypatch, capsys):
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    log = tmp_path / "log"
    _fake_check_plan_ttp(tmp_path, monkeypatch, log)
    p.set_config("delivery.push_checks", [{"run": HARNESS_PLAN, "purpose": "harness"}])
    ran = lambda: len(log.read_text().splitlines()) if log.exists() else 0
    # Tracked state files other writers keep appending to while the worker's head is committed.
    (repo / "state").mkdir()
    for f in ("queue-wait.jsonl", "state/tasks.json", "project.json"):
        (repo / f).write_text("{}\n")
    subprocess.run([*git, "add", "."], check=True)
    subprocess.run([*git, "commit", "-qm", "state"], check=True)
    for f in ("queue-wait.jsonl", "state/tasks.json"):
        with open(repo / f, "a") as fh:
            fh.write('{"wait": 1}\n')
    cli.main(["checks", "--purpose", "harness"])
    assert ran() == 1
    assert ("not counting uncommitted harness state files the runtime or other tasks write: "
            "queue-wait.jsonl, state/tasks.json") in capsys.readouterr().out
    # The candidate purpose is unchanged: they still block it.
    with pytest.raises(SystemExit) as e:
        cli.main(["checks", "--", "true"])
    assert e.value.code and "commit first" in capsys.readouterr().err
    # The worker's own sources still block: an edited source, a staged state file, and project.json
    # outside the project's harness repo.
    for staged, path in ((False, "a.txt"), (True, "queue-wait.jsonl"), (False, "project.json")):
        subprocess.run([*git, "checkout", "-q", "--", "."], check=True)
        with open(repo / path, "a") as fh:
            fh.write("more\n")
        if staged:
            subprocess.run([*git, "add", path], check=True)
        with pytest.raises(SystemExit) as e:
            cli.main(["checks", "--purpose", "harness", "--fresh"])
        assert e.value.code and "commit first" in capsys.readouterr().err, path
        subprocess.run([*git, "reset", "-q"], check=True)
    assert ran() == 1
    # In the project's own harness repo, the config, charter and memory the coordinator writes do not block.
    h = ["git", "-C", str(p.harness), "-c", "user.email=t@example.com", "-c", "user.name=t"]
    subprocess.run([*h, "add", "-A"], check=True)
    subprocess.run([*h, "commit", "-qm", "base", "--allow-empty"], check=True)
    monkeypatch.chdir(p.harness)
    p.set_config("delivery.push_checks", [{"run": HARNESS_PLAN, "purpose": "harness"}, "true"])
    with open(p.memory_index, "a") as fh:
        fh.write("- a lesson\n")
    cli.main(["checks", "--purpose", "harness"])
    assert ran() == 2
    assert "harness state files the runtime or other tasks write: MEMORY.md, project.json" in capsys.readouterr().out
    # A harness source the worker changed still blocks there.
    with open(p.harness / "prompts" / "worker.md", "a") as fh:
        fh.write("more\n")
    with pytest.raises(SystemExit) as e:
        cli.main(["checks", "--purpose", "harness", "--fresh"])
    assert e.value.code and "commit first" in capsys.readouterr().err
    assert ran() == 2


def test_ttp_checks_purpose_cache_never_crosses_purposes(env, tmp_path, monkeypatch, capsys):
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    log = tmp_path / "log"
    _fake_check_plan_ttp(tmp_path, monkeypatch, log)
    p.set_config("delivery.push_checks", [{"run": HARNESS_PLAN, "purpose": "harness"}, f"echo consumer >> {log}"])
    ran = lambda: len(log.read_text().splitlines()) if log.exists() else 0
    cli.main(["checks"])
    assert ran() == 1
    cli.main(["checks", "--purpose", "harness"])
    assert ran() == 3, "a candidate pass was reused for a harness qualification"
    cli.main(["checks", "--purpose", "harness"])
    assert ran() == 3 and "(recorded)" in capsys.readouterr().out
    cli.main(["checks"])
    assert ran() == 3, "the candidate pass on the same tree was not reused"
    assert json.loads((run / "checks.json").read_text())["purpose"] == "candidate"
    assert cli._recorded_pass(p, subprocess.run([*git, "rev-parse", "HEAD^{tree}"], capture_output=True,
                                                text=True).stdout.strip(), [], "other") is None


def test_ttp_checks_purpose_harness_fails_closed(env, tmp_path, monkeypatch, capsys):
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    log = tmp_path / "log"
    _fake_check_plan_ttp(tmp_path, monkeypatch, log)
    # No harness entry: the default harness plan runs, and its whitespace check fails a bad head.
    p.set_config("delivery.push_checks", ["true", {"run": "true", "purpose": "candidate"}])
    (repo / "b.txt").write_text("trailing \n")
    subprocess.run([*git, "add", "b.txt"], check=True)
    subprocess.run([*git, "commit", "-qm", "b"], check=True)
    with pytest.raises(SystemExit) as exc:
        cli.main(["checks", "--purpose", "harness", "--", "true"])
    assert exc.value.code == 1 and "default harness plan" in capsys.readouterr().out
    rec = json.loads((run / "checks.json").read_text())
    assert rec["passed"] is False and rec["purpose"] == "harness"
    assert json.loads((run / "check_failure.json").read_text())["check"]["run"].startswith("git diff --check ")
    # An unknown purpose fails it too, never skipping the entry.
    p.set_config("delivery.push_checks", [{"run": HARNESS_PLAN, "purpose": "harness"}, {"run": "true", "purpose": "x"}])
    with pytest.raises(SystemExit) as exc:
        cli.main(["checks", "--purpose", "harness"])
    assert exc.value.code == 1 and "purpose must be one of" in capsys.readouterr().err
    # A failing consumer fails the run, and a selector-shaped failure opens no check gap.
    selector = "sh -c 'echo \"mandatory check selector: no case for HEAD $(git rev-parse HEAD)\"; exit 1'"
    p.set_config("delivery.push_checks", [{"run": HARNESS_PLAN, "purpose": "harness"}, selector])
    with pytest.raises(SystemExit) as exc:
        cli.main(["checks", "--purpose", "harness"])
    assert exc.value.code == 1
    rec = json.loads((run / "checks.json").read_text())
    assert rec["passed"] is False and rec["purpose"] == "harness"
    receipt = json.loads((run / "check_failure.json").read_text())
    assert receipt["kind"] == "check_failed" and receipt["purpose"] == "harness", "a harness run opened a check gap"
    # A failing harness plan fails it as well.
    _fake_check_plan_ttp(tmp_path, monkeypatch, log, rc=65)
    p.set_config("delivery.push_checks", [{"run": HARNESS_PLAN, "purpose": "harness"}])
    with pytest.raises(SystemExit) as exc:
        cli.main(["checks", "--purpose", "harness"])
    assert exc.value.code == 1 and json.loads((run / "checks.json").read_text())["passed"] is False


def _out_of_scope_head(p, tmp_path, git):
    """A push target at HEAD and a later commit that changes nothing: if_changed scopes skip on it."""
    p.set_config("delivery.push_branch", "origin/proj")
    subprocess.run([*git, "remote", "add", "origin", str(tmp_path / "none.git")], check=True)
    subprocess.run([*git, "update-ref", "refs/remotes/origin/proj", "HEAD"], check=True)
    subprocess.run([*git, "commit", "-q", "--allow-empty", "-m", "notes"], check=True)


@pytest.mark.parametrize("case", ["consumer", "extra", "all_out_of_scope"])
def test_ttp_checks_purpose_harness_fails_when_its_harness_check_is_skipped(env, tmp_path, monkeypatch, capsys,
                                                                            case):
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    log = tmp_path / "log"
    _fake_check_plan_ttp(tmp_path, monkeypatch, log)
    _out_of_scope_head(p, tmp_path, git)
    harness = {"run": HARNESS_PLAN, "purpose": "harness", "if_changed": "src"}
    checks = {"consumer": [harness, f"echo consumer >> {log}"], "extra": [harness],
              "all_out_of_scope": [harness, {"run": f"echo consumer >> {log}", "if_changed": "src"}]}[case]
    p.set_config("delivery.push_checks", checks)
    extra = ["--", f"echo extra >> {log}"] if case == "extra" else []
    capsys.readouterr()
    with pytest.raises(SystemExit) as exc:
        cli.main(["checks", "--purpose", "harness", *extra])
    err = capsys.readouterr().err
    assert exc.value.code == 1 and "every purpose harness check was skipped" in err, err
    assert not log.exists(), "checks ran though nothing could qualify the head"
    rec = json.loads((run / "checks.json").read_text())
    assert rec["passed"] is False and rec["purpose"] == "harness" and rec["commands"] == []
    receipt = json.loads((run / "check_failure.json").read_text())
    assert receipt["kind"] == "harness_skipped" and receipt["purpose"] == "harness" and receipt["check"] is None
    # The same entries qualify a head the harness check applies to.
    (repo / "src").write_text("x\n")
    subprocess.run([*git, "add", "src"], check=True)
    subprocess.run([*git, "commit", "-qm", "src"], check=True)
    cli.main(["checks", "--purpose", "harness", *extra])
    assert log.read_text().split()[0] == "plan"
    assert json.loads((run / "checks.json").read_text())["passed"] is True
    # A reused harness pass still qualifies it.
    cli.main(["checks", "--purpose", "harness", *extra])
    assert "(recorded)" in capsys.readouterr().out


