def test_task_show_prints_spec_handoff_and_findings(env, capsys):
    from ttp import cli
    p = make(env)
    done = p.db.add_task("Do thing", "the spec text", kind="code")
    p.db.update_task(done, status="done", result=json.dumps(
        {"status": "done", "summary": "did it", "followups": [{"title": "next"}], "notes": "a note"}))
    rev = p.db.add_task("Review thing", "check it", kind="review")
    p.db.update_task(rev, status="failed", result=json.dumps(
        {"status": "changes_needed", "summary": "bad", "findings": [{"fact": "missing test"}]}))
    cli.main(["task", p.name, "show", str(done)])
    out = capsys.readouterr().out
    assert "Do thing" in out and "the spec text" in out and "did it" in out and "next" in out and "a note" in out
    cli.main(["task", p.name, "show", str(rev)])
    out = capsys.readouterr().out
    assert "missing test" in out and "changes_needed" in out
    with pytest.raises(SystemExit) as e:
        cli.main(["task", p.name, "show", "99999"])
    assert e.value.code != 0 and "no task #99999" in capsys.readouterr().err


# Globs a project might list in delivery.checks_fast_globs to opt in; the built-in default is none.
DOCS_GLOBS = ["*.md", "*.rst", "*.txt", "*.csv", "*.tsv"]


def _fast_cli(env, tmp_path, monkeypatch, files, push_check, extras=(), globs=DOCS_GLOBS):
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    p.set_config("delivery.push_branch", "work")
    if globs is not None:
        p.set_config("delivery.checks_fast_globs", list(globs))
    base = subprocess.run([*git, "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    subprocess.run([*git, "update-ref", "refs/remotes/origin/work", base], check=True)
    mark = tmp_path / "mark"
    p.set_config("delivery.push_checks", [f"echo project >> {mark}"] if push_check else [])
    for name, body in files.items():
        (repo / name).parent.mkdir(parents=True, exist_ok=True)
        (repo / name).write_text(body)
    subprocess.run([*git, "add", "-A"], check=True)
    subprocess.run([*git, "commit", "-qm", "change"], check=True)
    return cli, p, run, mark


def test_ttp_checks_fast_path_on_a_docs_only_commit(env, tmp_path, monkeypatch, capsys):
    cli, p, run, mark = _fast_cli(env, tmp_path, monkeypatch, {"docs/n.md": "hi\n"}, True)
    cli.main(["checks"])
    out = capsys.readouterr().out
    assert "FAST PATH" in out and "FAST-PATH pass" in out and "recorded for the draft PR" not in out
    assert not mark.exists(), "the project's check ran on the fast path"
    rec = json.loads((run / "checks.json").read_text())
    assert rec["passed"] is True and rec["fast_path"] is True and rec["skipped_project_checks"]
    assert len(rec["commands"]) == 2 and all("git diff" in c for c in rec["commands"])
    from ttp import prguard
    assert not prguard.candidate_record(rec)
    assert "fast-path pass" in prguard._checks_problem(os.getcwd())


