def test_upstream_wontfix_queues_in_a_sandbox_is_refused_without_resolve_or_with_fixed_in(env, monkeypatch, tmp_path):
    from ttp import cli, upstream
    p = make(env)
    upstream.append("demo", 4, [{"title": "upstream: sb", "spec": "y"}])
