def _peer(env, name):
    """Another project registered on this machine (only its folder: enough to be a note's target)."""
    from ttp.project import register
    d = env["repo"].parent / f"peer-{name}"
    d.mkdir(exist_ok=True)
    register(name, {"host": "testhost", "dir": str(d)})


def _notes_to(name):
    from ttp import upstream
    if not upstream.path().exists():
        return []
    return [n for n in upstream._lines(upstream.path().read_bytes())[0] if n.get("to") == name]


def test_command_watcher_to_pages_another_project_once_per_key_until_rewake(env, monkeypatch):
    from ttp import daemon as dm
    run, issues, p = _json_watcher(env, monkeypatch)
    _peer(env, "ops")
    line = {"text": "box-a: held (cause A)", "severity": "high", "key": "hold:A", "to": "ops"}
    run("hw", line)
    run("hw", dict(line, text="box-a: held (cause A, still)"))   # the same key: no second note
    notes = _notes_to("ops")
    assert len(notes) == 1 and notes[0]["from"] == "daemon" and notes[0]["severity"] == "high"
    assert "Watcher hw of project demo, reporting since" in notes[0]["spec"] and "(cause A)" in notes[0]["spec"]
    assert not issues("hw") and not p.db.q("SELECT id FROM events WHERE kind='observation'"), "paged and observed"
    run("hw", line, dict(line, key="hold:B", text="box-a: held (cause B)"))   # a new cause: its own note
    assert len(_notes_to("ops")) == 2
    # rewake_after_h (the screen's default, 6 h) applies as for observations.
    paged = p.db.kv(dm.PAGED_KEY + "hw")
    p.db.set_kv(dm.PAGED_KEY + "hw", {k: dict(v, at=v["at"] - 7 * 3600) for k, v in paged.items()})
    run("hw", line, dict(line, key="hold:B", text="box-a: held (cause B)"))
    notes = _notes_to("ops")
    assert len(notes) == 4 and all("still reported: note 2" in n["spec"] for n in notes[2:])
    # A cause no longer reported is over; its recurrence (a later minute) pages again. "repeat": true
    # pages every run.
    run("hw", line)
    real = time.time
    monkeypatch.setattr(dm.time, "time", lambda: real() + 120)
    run("hw", dict(line, key="hold:B", text="box-a: held (cause B)"))
    assert len(_notes_to("ops")) == 5 and "still" not in _notes_to("ops")[-1]["spec"]
    run("hw", dict(line, repeat=True))
    run("hw", dict(line, repeat=True))
    assert len(_notes_to("ops")) == 7
    run("hw")   # a clean run clears it all
    assert not p.db.kv(dm.PAGED_KEY + "hw")


def test_command_watcher_to_unknown_or_own_project_is_observed_here(env, monkeypatch):
    run, issues, p = _json_watcher(env, monkeypatch)
    for to in ("nope", "demo", 5, ""):
        run("hw", {"text": f"box-a: held ({to})", "severity": "high", "to": to})
        assert f"box-a: held ({to})" in issues("hw")
    assert not _notes_to("nope") and not _notes_to("demo")
    log = (p.logs / "daemon.log").read_text()
    assert "no project 'nope' on this machine" in log and "observed here instead" in log


def test_command_watcher_to_machine_owner_resolves_outage_then_recovery_owner(env, monkeypatch):
    from ttp import machine_ledger as ml, machines as mm, pageto
    run, issues, _ = _json_watcher(env, monkeypatch)
    mm.add("box-a", tags="device")
    line = {"text": "box-a: held", "severity": "high", "key": "a", "machine": "box-a", "to": pageto.OWNER}
    run("hw", line)   # no owner set: observed here
    assert "box-a: held" in issues("hw") and not _notes_to("ops")
    _peer(env, "ops")
    _peer(env, "repair")
    mm.set_recovery("box-a", "ops")
    run("hw", dict(line, key="b", text="box-a: held (b)"))
    assert len(_notes_to("ops")) == 1
    ml.set_outage("box-a", "board swap", "demo", "2d", owner="repair")   # a known outage's owner project first
    run("hw", dict(line, key="c", text="box-a: held (c)"))
    assert len(_notes_to("repair")) == 1 and len(_notes_to("ops")) == 1
    ml.set_outage("box-a", "board swap", "demo", "2d", owner="a vendor ticket")   # not a project: the recovery owner
    run("hw", dict(line, key="d", text="box-a: held (d)"))
    assert len(_notes_to("ops")) == 2
    assert pageto.resolve(pageto.OWNER, None)[0] is None and pageto.resolve(pageto.OWNER, "box-z")[0] is None


def test_command_watcher_to_pages_a_keyed_lines_new_episode_again(env, monkeypatch):
    """A keyed line's `episode` works for a paged line as for an observed one: another episode pages
    again; the same one, or none, does not; a key paged without one adopts the first it sees."""
    run, _, _ = _json_watcher(env, monkeypatch)
    _peer(env, "ops")
    line = {"text": "job 7 failed", "severity": "high", "key": "job-fail", "episode": "7", "to": "ops"}
    run("hw", line)
    run("hw", dict(line, text="job 8 failed", episode="8"))
    assert [n["spec"].split(": ", 1)[1] for n in _notes_to("ops")] == ["job 7 failed", "job 8 failed"]
    run("hw", dict(line, text="job 8 failed (still)", episode="8"))
    run("hw", dict(line, text="job 8 failed (still)", episode=None))
    assert len(_notes_to("ops")) == 2
    plain = {"text": "box-a: held", "severity": "high", "key": "hold", "to": "ops"}
    run("hw", plain)
    run("hw", dict(plain, text="box-a: held (since boot 1)", episode="boot 1"))   # adopted: no note
    assert len(_notes_to("ops")) == 3
    run("hw", dict(plain, text="box-a: held (since boot 2)", episode="boot 2"))
    assert len(_notes_to("ops")) == 4


def test_a_running_end_confirmation_does_not_block_stop_or_exit(env, monkeypatch):
    import threading
    from ttp import ends, netwait
    p = make(env)
    release = threading.Event()
    monkeypatch.setattr(netwait, "confirm", lambda *a, **k: release.wait(30) and "")
    procs = {"c": (ends._Confirming(ends._confirm("exit 255", "", p), ""), time.time(), "exit 255")}
    t0 = time.time()
    ends.stop_probes(procs, {})
    assert time.time() - t0 < 2 and not procs
    th = [t for t in threading.enumerate() if t.name == "ttp-end-confirm"]
    assert th and all(t.daemon for t in th)
    release.set()


@pytest.mark.parametrize("code,passed,reported", [(0, True, False), (1, False, False), (2, False, True)])
def test_machine_change_until_probe_exit_codes(env, code, passed, reported):
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    p = make(env)
    mm.add("box-a", tags="device")
    now = time.time()
    c = ml.add_change("box-a", "paused", "resume", p.name, until_probe=f"sh -c 'exit {code}'", now=now)
    logs = []
    probes = ml.Probes(p, log=logs.append)
    for n in range(ml.PROBE_PASSES):
        _change_probe_round(probes, c["id"], now + ml.PROBE_GRACE_S + n * 1000)
    [got] = ml.changes()
    assert bool(got.get("probe_passed")) is passed
    assert any("broken" in l for l in logs) is reported
    if reported:
        assert len(logs) == 1, "reported once"


def test_machine_change_until_probe_255_needs_ssh_confirmation(env, monkeypatch):
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp import netwait
    p = make(env)
    mm.add("box-a", tags="device")
    now = time.time()
    c = ml.add_change("box-a", "paused", "resume", p.name, until_probe="exit 255", now=now)
    seen = []
    monkeypatch.setattr(netwait, "confirm", lambda *a, **k: seen.append(a) or "ssh reaches h1")
    logs = []
    probes = ml.Probes(p, log=logs.append)
    now += ml.PROBE_GRACE_S
    probes.tick(now)
    probes._procs[c["id"]][0].wait(30)
    probes.tick(now + 1)
    for _ in range(100):
        if seen:
            break
        time.sleep(0.05)
    probes.tick(now + 2)
    assert seen and any("broken" in l and "ssh reaches h1" in l for l in logs), logs


def _change_probe_round(probes, cid, at):
    probes._probed.clear()
    probes.tick(at)
    probes._procs[cid][0].wait(30)
    probes.tick(at + 1)


def test_machine_change_until_probe_true_at_add_time_does_not_page_during_its_grace(env):
    """An until-probe already true when its entry is made (an 'until X is not set' probe) is not run
    before PROBE_GRACE_S, so the entry is not overdue and pages nobody meanwhile."""
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    p = make(env)
    mm.add("box-a", tags="device")
    now = time.time()
    c = ml.add_change("box-a", "paused", "resume", p.name, until_probe="test -d /", now=now)
    probes = ml.Probes(p, log=lambda s: None)
    for at in (now, now + 60, now + ml.PROBE_GRACE_S - 1):
        probes._probed.clear()
        probes.tick(at)
        assert c["id"] not in probes._procs, at
    assert not ml.overdue(ml.changes()[0], now + ml.PROBE_GRACE_S - 1)
    assert not [x for x in ml.route(now + ml.PROBE_GRACE_S - 1, able=lambda n: (True, ""))
                if x["kind"] == "machine_change_overdue"]


def test_machine_change_until_probe_passes_twice_in_a_row_and_a_later_not_yet_clears_it(env, tmp_path):
    """An until-probe counts as passed only after PROBE_PASSES passes in a row, each logged with its output's
    tail; it keeps running while the entry is open, and a later 'not yet' clears the pass and its pages."""
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    p = make(env)
    mm.add("box-a", tags="device")
    code = tmp_path / "code"
    code.write_text("0")
    now = time.time()
    c = ml.add_change("box-a", "paused", "resume", p.name, until_probe=f"echo probe-said-done; exit $(cat {code})",
                      now=now)
    logs = []
    probes = ml.Probes(p, log=logs.append)
    at = now + ml.PROBE_GRACE_S
    _change_probe_round(probes, c["id"], at)
    assert not ml.changes()[0].get("probe_passed"), "one pass is not enough"
    assert "1 of 2 in a row" in logs[-1] and "probe-said-done" in logs[-1], logs
    code.write_text("1")   # one pass then a fail: the streak starts over
    _change_probe_round(probes, c["id"], at + 1000)
    code.write_text("0")
    _change_probe_round(probes, c["id"], at + 2000)
    assert not ml.changes()[0].get("probe_passed") and "1 of 2 in a row" in logs[-1], logs
    _change_probe_round(probes, c["id"], at + 3000)
    got = ml.changes()[0]
    assert got["probe_passed"] and "probe-said-done" in got["probe_out"], got
    assert ml.overdue(got, at + 3001) == "its until-probe passed"
    with ml._locked():   # it was paged meanwhile
        doc = ml._read(ml.LEDGER, {})
        doc["changes"][0]["page"] = {"stage": 1}
        ml._write(ml.LEDGER, doc)
    _change_probe_round(probes, c["id"], at + 4000)   # still passing: still probed, the pass kept
    assert ml.changes()[0]["probe_passed"] == got["probe_passed"]
    code.write_text("1")   # what it waited for is back: no longer overdue, the pages dropped
    _change_probe_round(probes, c["id"], at + 5000)
    got = ml.changes()[0]
    assert not got.get("probe_passed") and "probe_out" not in got and "page" not in got, got
    assert got["page_from"] == at + 5001 and not ml.overdue(got, at + 5001)
    assert "no longer overdue" in logs[-1], logs


def test_machine_change_until_probe_timeout_is_broken_and_queued_once(env):
    from ttp import ends
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    p = make(env)
    mm.add("box-a", tags="device")
    now = time.time()
    c = ml.add_change("box-a", "paused", "resume", p.name, until_probe="sleep 30", now=now)
    logs = []
    probes = ml.Probes(p, log=logs.append)
    for at in (now + ml.PROBE_GRACE_S, now + 1000):   # two rounds: each runs past the timeout and is killed
        probes._probed.clear()
        probes.tick(at)
        probes.tick(at + ends.PROBE_TIMEOUT_S + 1)
        assert c["id"] not in probes._procs
    [got] = ml.changes()
    assert not got.get("probe_passed")
    assert len(logs) == 1 and "timeout" in logs[0], logs
    [ev] = p.db.q("SELECT * FROM events WHERE kind=?", (ml.PROBE_BROKEN_KIND,))
    assert ev["severity"] == "low" and ev["status"] == "queued" and f"#{c['id']} on box-a" in ev["text"]
    assert "timeout" in ev["text"] and f"ttp machines change edit {c['id']} --until-probe" in ev["text"]


def test_machine_change_broken_probe_reported_once_per_kind_not_per_stderr(env, tmp_path):
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    p = make(env)
    mm.add("box-a", tags="device")
    code = tmp_path / "code"
    code.write_text("2")
    now = time.time()
    probe = f"date +%N >&2; exit $(cat {code})"   # a new stderr tail every round
    c = ml.add_change("box-a", "paused", "resume", p.name, until_probe=probe, now=now)
    logs = []
    probes = ml.Probes(p, log=logs.append)
    _change_probe_round(probes, c["id"], now + ml.PROBE_GRACE_S)
    _change_probe_round(probes, c["id"], now + 1000)
    assert len(logs) == 1, logs
    _change_probe_round(ml.Probes(p, log=logs.append), c["id"], now + 2000)   # a daemon restart
    events = lambda: p.db.q("SELECT fingerprint FROM events WHERE kind=?", (ml.PROBE_BROKEN_KIND,))
    assert len(events()) == 1, "one event across restarts"
    code.write_text("3")   # broken another way: said again
    _change_probe_round(probes, c["id"], now + 3000)
    assert len(events()) == 2 and "exit 3" in logs[-1]
    code.write_text("1")   # not yet clears it; broken again later is the same kind: no new event
    _change_probe_round(probes, c["id"], now + 4000)
    code.write_text("3")
    _change_probe_round(probes, c["id"], now + 5000)
    assert len(events()) == 2
    from ttp import coordinator
    assert coordinator.EFFORT_EVENT_TRIGGERS[ml.PROBE_BROKEN_KIND] == "resource"


def test_broker_released_counts_health_held_false_and_hold_released_log_lines(env, tmp_path, capsys, monkeypatch):
    from ttp import brokerhold, cli
    rel = brokerhold.released
    log = "21:00:01 STARTUP hold engaged until the fabric check passes\n21:43:41 STARTUP hold released after 2949s\n"
    # The log line alone, with no device_released event anywhere, counts as released.
    assert rel(log)[0] and "STARTUP hold released" in rel(log)[1]
    assert rel("12:00 hold released by recovery\n")[0]
    assert rel('{"event": "device_released"}\n')[0]
    # /health held false with a healthy fsm counts, also as curl's unterminated answer before a log tail.
    assert rel('{"held": false, "fsm": "healthy"}')[0]
    assert rel('{"held": false, "fsm": {"state": "Healthy"}}12:00 server up\n')[0]
    # Live /health wins over an older release line: still held, or an fsm that is not healthy.
    assert not rel(log + '{"held": true, "fsm": "healthy"}\n')[0]
    assert not rel(log + '{"held": false, "fsm": "recovering"}\n')[0]
    # /health with no fsm falls back to the log; a hold set after the release is held again.
    assert rel('{"held": false}\n' + log)[0]
    assert not rel(log + "22:10:00 hold set by recovery\n")[0]
    assert not rel("")[0] and not rel("12:00 no hold today\n")[0]
    # The broker's real /health shape reports fsm_state, not fsm.
    real = '{"status": "ok", "version": "1", "running": 0, "queued": 0, "held": %s, "fsm_state": "%s", "fsm_why": ""}\n'
    assert rel(real % ("false", "healthy"))[0]
    assert rel(log + "22:10:00 hold set by recovery\n" + real % ("false", "healthy"))[0]
    assert not rel(real % ("true", "healthy"))[0]
    assert not rel(real % ("false", "recovering"))[0]
    no_fsm = rel('{"status": "ok", "held": false}\n')
    assert not no_fsm[0] and "no /health answer" not in no_fsm[1] and "fsm not reported" in no_fsm[1]
    # A device_held event after device_released is held again; a device_held_since field is not a hold.
    assert not rel('{"kind": "device_released"}\n{"kind": "device_held", "reason": "x"}\n')[0]
    assert rel('{"kind": "device_held", "reason": "x"}\n{"kind": "device_released"}\n')[0]
    assert rel('{"kind": "device_released"}\n12:00 device_held_since=0\n')[0]
    # The CLI probe: 0 released, 1 not, from files or stdin.
    f = tmp_path / "server.log"
    f.write_text(log)
    with pytest.raises(SystemExit) as e:
        cli.main(["broker-released", str(f)])
    assert e.value.code == 0 and "released (released: 21:43:41 STARTUP hold released" in capsys.readouterr().out
    monkeypatch.setattr(sys, "stdin", io.StringIO('{"held": true, "fsm": "healthy"}\n'))
    with pytest.raises(SystemExit) as e:
        cli.main(["broker-released"])
    assert e.value.code == 1 and "not released (/health: held true" in capsys.readouterr().out


def test_heal_classify_known_exit_75_and_unknown_agree_with_the_daemon():
    from ttp import heal
    out = "noise\nttp-heal: known owner-x: waiting on a part\n"
    assert heal.classify(75, out) == "known (owner-x: waiting on a part)"
    assert heal.classify(75, "no marker") == "unknown"
    assert heal.classify(0, "") == "healthy"
    assert heal.classify(1, "ttp-heal: not-outage") == "unhealthy, not an outage"
    # the daemon's reading of the same result uses the same known_run
    assert heal.known_run(75, out) == ("owner-x", "waiting on a part")
    assert heal.known_run(75, "no marker") is None


# Area case files. Groups of this file's tests live in tests/tt_project_runtime/<area>_cases.py, so
# changes to different areas touch different files. pytest never collects those files itself (no
# test_ prefix): each runs here, in this module's namespace, as if its text stood at this point, so
# its tests keep their ids, fixtures and helpers and run once under the required command. A case
# file uses this file's helpers and imports and defines only what its own tests use.
_CASES = pathlib.Path(__file__).resolve().parent / "tt_project_runtime"


def _include_cases(area: str) -> None:
    import ast
    import hashlib
    import marshal
    path = _CASES / f"{area}_cases.py"
    source = path.read_bytes()
    # pytest rewrote this file's asserts (its rewritten code names @pytest_ar): rewrite the cases' too.
    rewrite = "@pytest_ar" in globals()
    tag = repr((sys.version, pytest.__version__, rewrite)).encode()
    key = hashlib.sha256(source + tag).hexdigest()[:16]
    cache = path.parent / "__pycache__" / f"{path.stem}.{key}.pyc"
    try:
        code = marshal.loads(cache.read_bytes())
    except (OSError, EOFError, ValueError, TypeError):
        # Rewriting asserts costs seconds per thousand tests, so the result is kept like pytest's own.
        tree = ast.parse(source, str(path))
        if rewrite:
            from _pytest.assertion.rewrite import rewrite_asserts
            rewrite_asserts(tree, source, str(path), None)
        code = compile(tree, str(path), "exec", dont_inherit=True)
        try:
            cache.parent.mkdir(exist_ok=True)
            for old in cache.parent.glob(f"{path.stem}.*.pyc"):
                old.unlink(missing_ok=True)
            tmp = cache.with_name(f"{cache.name}.{os.getpid()}.tmp")
            tmp.write_bytes(marshal.dumps(code))
            os.replace(tmp, cache)
        except OSError:
            pass
    exec(code, globals())


for _area in sorted(p.name[:-len("_cases.py")] for p in _CASES.glob("*_cases.py")):
    _include_cases(_area)


def test_case_files_run_once_under_this_file_with_rewritten_asserts():
    import ast
    files = sorted(_CASES.glob("*_cases.py"))
    assert files and not list(_CASES.glob("test_*.py")) and not list(_CASES.glob("*_test.py"))
    # A name a case file defines that this file or another case file also defines silently replaces
    # the other one, and a test that is replaced never runs.
    where = {}
    for path in [pathlib.Path(__file__), *files]:
        for st in ast.parse(path.read_text(encoding="utf-8")).body:
            targets = st.targets if isinstance(st, ast.Assign) else []
            for name in [getattr(st, "name", None), *(t.id for t in targets if isinstance(t, ast.Name))]:
                if name:
                    where.setdefault(name, set()).add(path.name)
    assert not {n: f for n, f in where.items() if len(f) > 1}
    from_cases = {}
    for name, f in globals().items():
        code = getattr(f, "__code__", None)
        if name.startswith("test_") and code and pathlib.Path(code.co_filename).parent == _CASES:
            from_cases.setdefault(pathlib.Path(code.co_filename), []).append(f)
    assert sorted(from_cases) == files
    if "@pytest_ar" in globals():   # asserts in the case files are rewritten like this file's
        assert all(any("@pytest_ar" in f.__code__.co_names for f in fs) for fs in from_cases.values())


